def _parse_env_value(v: str) -> str:
    """Decode a KEY=value value that may be single- or double-quoted, matching how
    bash `source` and Docker env_file already treat these files. Bare values are
    returned unchanged (back-compat). A single-quoted value is literal except for
    the shell escape '\\'' -> ' ; a double-quoted value just loses its wrapper.
    Keep in lockstep with scripts/_bridge_common._parse_env_value and _env_quote."""
    v = v.strip()
    if len(v) >= 2 and v[0] == v[-1] and v[0] in ("'", '"'):
        inner = v[1:-1]
        if v[0] == "'":
            return inner.replace("'\\''", "'")
        return inner.replace('\\"', '"').replace('\\\\', '\\')
    return v


_CUSTOM_ENV_KEYS: set[str] = set()
_LAUNCHER_RUNTIME_KEYS = {
    "AGENT_CHAT_EDITION", "DATA_DIR", "STORAGE_DB", "AGENT_CHAT_DB",
    "JARVIS_FOREMAN_CONFIG",
}

for env_file in ENV_FILES:
    if not env_file.is_file():
        continue
    for line in env_file.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        key = k.strip()
        value = _parse_env_value(v)
        if _CUSTOM_ENV_FILE:
            _CUSTOM_ENV_KEYS.add(key)
            # A dedicated Community config is authoritative, including blank
            # values.  Using setdefault here allowed tokens inherited from the
            # launcher/desktop process to punch through an intentionally blank
            # config and silently attach the maintainer's private bridges.
            # Directory/database paths are supplied by the platform launcher;
            # the portable template intentionally leaves them blank.
            if not (key in _LAUNCHER_RUNTIME_KEYS and os.environ.get(key)):
                os.environ[key] = value
        else:
            os.environ.setdefault(key, value)

if _CUSTOM_ENV_FILE:
    # Do not inherit optional application integrations that are absent from the
    # user's dedicated config. This process may have been launched by another
    # Agents Chat/Codex session whose environment contains private credentials.
    isolated_keys = {
        "AGENTS", "CALENDAR_ICS_URL", "TAVILY_API_KEY",
        "CRAWL4AI_API_TOKEN", "CRAWL4AI_ENV_FILE", "CRAWL4AI_URL",
        "ELEVENLABS_API_KEY", "GOOGLE_TTS_API_KEY",
        "REDDIT_CLIENT_ID", "REDDIT_CLIENT_SECRET", "REDDIT_REFRESH_TOKEN",
        "TELEGRAM_BOT_TOKEN", "TELEGRAM_CHAT_ID", "DEEPSEEK_API_KEY",
        "MINIMAX_API_KEY", "MINIMAX_JWT", "GROK_DEPLOYMENT_KEY",
        "GROK_AUTH_PROVIDER_COMMAND",
    }
    isolated_keys.update(
        key for key in os.environ if key.startswith("AGENT_TOKEN_")
    )
    for key in isolated_keys - _CUSTOM_ENV_KEYS:
        os.environ.pop(key, None)

