# User-added agents are mutable runtime data, so keep them beside the database
# rather than in the application bundle. That makes Community upgrades safe and
# keeps the isolated tester / a packaged install from accidentally sharing the
# maintainer checkout's agents. CUSTOM_AGENTS_FILE remains overrideable for
# managed deployments.
CUSTOM_AGENTS_FILE = Path(
    os.environ.get("CUSTOM_AGENTS_FILE", str(DATA_DIR / "custom_agents.json"))
).expanduser()
LEGACY_CUSTOM_AGENTS_FILE = BASE_DIR / "custom_agents.json"


def _load_custom_agents() -> list:
    entries = []
    paths = [CUSTOM_AGENTS_FILE]
    # The checkout-local file is a migration fallback for the default install
    # only. A caller-supplied AGENT_CHAT_ENV_FILE config or an explicit
    # CUSTOM_AGENTS_FILE override is an isolation boundary (see ENV_FILES):
    # the maintainer checkout's connected agents must not leak into that roster.
    _isolated = bool(_CUSTOM_ENV_FILE) or bool(os.environ.get("CUSTOM_AGENTS_FILE"))
    if not _isolated and LEGACY_CUSTOM_AGENTS_FILE != CUSTOM_AGENTS_FILE:
        paths.append(LEGACY_CUSTOM_AGENTS_FILE)
    for path in paths:
        if not path.exists():
            continue
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError) as exc:
            logging.warning("Ignoring %s — could not parse: %s", path, exc)
            continue
        rows = raw.get("agents", raw) if isinstance(raw, dict) else raw
        if not isinstance(rows, list):
            logging.warning("Ignoring %s — expected a list of agents", path)
            continue
        entries.extend(rows)
    known = {str(a.get("id")) for a in AGENTS}
    out = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        aid = str(entry.get("id") or "").strip()
        if not aid or not str(entry.get("url") or "").strip():
            logging.warning("Skipping custom agent without id+url: %r", entry)
            continue
        # RC24 briefly instructed the Windows desktop app to register a generic
        # ``codex-desktop`` localhost server. That server could satisfy a socket
        # probe while returning canned text instead of invoking Codex. Preserve
        # the row on disk for recoverability, but never load or grant it as a
        # connected agent. The supported built-in ``codex`` adapter below is the
        # only Codex identity and supplies the same premium controls on Mac/PC.
        if (
            community_mode()
            and aid == "codex-desktop"
            and str(entry.get("source") or "") == "community_connector"
        ):
            logging.warning(
                "Ignoring deprecated codex-desktop placeholder; connect the built-in Codex adapter"
            )
            continue
        if aid in known:
            logging.warning("Skipping custom agent %r — id already in use", aid)
            continue
        entry.setdefault("name", aid.title())
        entry.setdefault("color", "#8b9bb4")
        entry.setdefault("emoji", aid[:1].upper())
        known.add(aid)
        out.append(entry)
    if out:
        logging.info("Loaded %d custom agent(s) from the local connector store", len(out))
    return out


AGENTS = list(AGENTS) + _load_custom_agents()

# Strip secrets before exposing agents to browser.
def _public_agent(a: dict) -> dict:
    # Adapter configuration can include a private upstream address, model and
    # credential. The browser only needs the public identity + Agents Chat-facing
    # URL; never serialize connector internals into bootstrap/admin payloads.
    private_keys = {
        "token_env", "token", "managed_adapter", "upstream_url",
        "upstream_token", "upstream_model", "owner_user_id", "source",
    }
    public = {k: v for k, v in a.items() if k not in private_keys}
    if not str(public.get("voice") or "").strip():
        fallback_voice = DEFAULT_AGENT_VOICES.get(str(public.get("id") or ""))
        if fallback_voice:
            public["voice"] = fallback_voice
    return public

