OPENROUTER_MODEL_RE = re.compile(
    r"^(?=.{1,160}$)~?[A-Za-z0-9][A-Za-z0-9._~:+/-]*$"
)
def _openrouter_model_id_is_free(value: object) -> bool:
    """Accept only OpenRouter's explicit free router or official :free variants."""
    model_id = str(value or "").strip()
    return bool(
        OPENROUTER_MODEL_RE.fullmatch(model_id)
        and (model_id == "openrouter/free" or model_id.endswith(":free"))
    )


