# Derive each bridge's launchd label rather than repeating it per entry: a new
# bridge that forgot the line would silently fall back to the unsupervised
# detached path, which is the dual-supervisor bug this supervision exists to fix.
for _bridge_id, _bridge_spec in MANAGED_BRIDGES.items():
    _bridge_spec.setdefault("launchd_label", f"com.agentchat.{_bridge_id}-bridge")


def _normalize_chat_mode(mode: Optional[str]) -> str:
    mode = (mode or DEFAULT_CHAT_MODE).strip().lower()
    return mode if mode in CHAT_MODES else DEFAULT_CHAT_MODE


CHAT_INTENTS = frozenset({"auto", "chat", "code"})


def _normalize_chat_intent(intent: Optional[str]) -> str:
    """Keep project organization separate from conversation routing.

    ``auto`` is the compatibility value for conversations created before this
    distinction existed: a workspace-bearing project keeps its historical coding
    behavior. New user-created conversations persist an explicit ``chat`` or
    ``code`` choice instead.
    """
    value = str(intent or "auto").strip().lower()
    return value if value in CHAT_INTENTS else "auto"


# Origin allowlist: localhost + Tailscale CGNAT range (100.64.0.0/10) + ts.net.
# Override with ALLOWED_ORIGINS="https://foo,https://bar" to lock down further.
ALLOWED_ORIGINS_ENV = os.environ.get("ALLOWED_ORIGINS", "").strip()
ALLOWED_ORIGINS = [o.strip() for o in ALLOWED_ORIGINS_ENV.split(",") if o.strip()]

# Companion browser extensions (the screen recorder) call the API from a
# chrome-extension:// origin that no host-based rule can ever match. Only the
# pinned extension IDs below (extendable via ALLOWED_EXTENSION_ORIGINS) get
# through the origin gate — authentication is still enforced separately via
# the x-agent-chat-session header, so this widens CSRF exposure only to these
# specific extensions.
ALLOWED_EXTENSION_ORIGINS = {
    "chrome-extension://aimlmpihhnbacfpadbpafcbfoipngnbo",  # extensions/screen-recorder
} | {
    o.strip().rstrip("/").lower()
    for o in os.environ.get("ALLOWED_EXTENSION_ORIGINS", "").split(",")
    if o.strip()
}

MAX_MESSAGE_BYTES = 16 * 1024
