# --- Custom Kokoro voice presets (blend recipes) -----------------------------
# Named voices defined in custom_voices/voices.json without touching code. Each
# preset resolves to a Kokoro blend string (comma-separated base voice ids; repeat
# an id to weight it), which the kokoro server averages on the fly. The RESOLVED
# recipe string — not the preset name — is what flows into the audio cache key
# (see _kokoro_voice_for_agent), so re-tuning a preset's weights changes the
# recipe and busts stale cached audio automatically. The file hot-reloads on
# mtime change, so edits take effect without restarting the app.
CUSTOM_VOICES_DIR = BASE_DIR / "custom_voices"
VOICE_PRESETS_PATH = CUSTOM_VOICES_DIR / "voices.json"
_VOICE_BASE_IDS = {voice[0] for voice in VOICE_KOKORO_VOICES}
_kokoro_presets: dict[str, dict] = {}
_kokoro_presets_mtime: float = -1.0
_kokoro_presets_lock = threading.Lock()


def _sanitize_recipe(recipe: str) -> str:
    """Keep only known base voice ids; preserve order and repeats (weighting).
    Returns '' if nothing valid remains."""
    parts = [p.strip() for p in str(recipe or "").split(",")]
    valid = [p for p in parts if p in _VOICE_BASE_IDS]
    return ",".join(valid[:16])  # cap blend length defensively


def _load_kokoro_presets() -> dict[str, dict]:
    """Load (and hot-reload on mtime change) named blend presets from
    custom_voices/voices.json. Malformed entries are skipped, never fatal; the
    last good set is kept on a parse error."""
    global _kokoro_presets, _kokoro_presets_mtime
    try:
        mtime = VOICE_PRESETS_PATH.stat().st_mtime
    except OSError:
        if _kokoro_presets:
            with _kokoro_presets_lock:
                _kokoro_presets = {}
                _kokoro_presets_mtime = -1.0
        return _kokoro_presets
    if mtime == _kokoro_presets_mtime and _kokoro_presets:
        return _kokoro_presets
    with _kokoro_presets_lock:
        try:
            raw = json.loads(VOICE_PRESETS_PATH.read_text("utf-8") or "{}")
        except (json.JSONDecodeError, OSError) as exc:
            logging.getLogger("neuroblend.v5.voice.config").warning(
                "Ignoring invalid custom_voices/voices.json: %s", exc)
            return _kokoro_presets  # keep last-good on parse error
        entries = raw.get("presets", raw) if isinstance(raw, dict) else raw
        if isinstance(entries, dict):
            entries = [
                {"id": k, **(v if isinstance(v, dict) else {"recipe": v})}
                for k, v in entries.items()
            ]
        parsed: dict[str, dict] = {}
        for entry in entries or []:
            if not isinstance(entry, dict):
                continue
            pid = str(entry.get("id") or "").strip().lower()
            recipe = _sanitize_recipe(entry.get("recipe") or entry.get("blend") or "")
            # Need an id, a valid recipe, and no clash with a base voice id.
            if not pid or not recipe or pid in _VOICE_BASE_IDS:
                continue
            parsed[pid] = {
                "id": pid,
                "name": str(entry.get("name") or pid),
                "recipe": recipe,
                "lang": str(entry.get("lang") or "en-US"),
            }
        _kokoro_presets = parsed
        _kokoro_presets_mtime = mtime
    return _kokoro_presets


def _kokoro_resolve_voice(voice: str) -> str:
    """Map a requested voice id to what the kokoro server should synthesize: a base
    voice id passes through; a preset id becomes its blend recipe; a raw comma-blend
    is sanitized; anything unknown returns ''."""
    voice = str(voice or "").strip()
    if not voice:
        return ""
    if voice in _VOICE_BASE_IDS:
        return voice
    preset = _load_kokoro_presets().get(voice.lower())
    if preset:
        return preset["recipe"]
    if "," in voice:
        return _sanitize_recipe(voice)
    return ""
