# --- Premium cloud voice providers (ElevenLabs / Google Chirp 3 HD) ----------
# Fully built, gracefully DORMANT until a key lands (Settings → Voice). Keys
# live in agents/shared.env via _write_shared_env_secret (the Tavily pattern —
# masked hints only, values never leave the process); the provider choice and
# voice names live in app_settings:
#   voice_provider            auto|elevenlabs|google|kokoro|say   (default auto)
#   voice_elevenlabs_voice    default ElevenLabs voice id ('' = warm-male preset)
#   voice_elevenlabs_voices   JSON {agent_id: voice_id} per-persona map
#   voice_google_voice        Google voice name (default Chirp 3 HD male)
#   voice_google_voices       JSON {agent_id: voice_name} per-persona map
#   voice_agent_providers     JSON {agent_id: provider} casting board — a named
#                             provider carries explicit-pick semantics for that
#                             one agent (cloud leads w/ safety net, local stays
#                             local); absent = follow the global voice_provider
# With no cloud keys the auto chain is exactly the pre-existing behavior
# (openai → kokoro → macOS say). Provider objects live beside the voice
# helpers (see _voice_cloud_providers section).
VOICE_ELEVENLABS_MODEL = os.environ.get(
    "VOICE_ELEVENLABS_MODEL", voice_providers.ELEVENLABS_MODEL
).strip()
# One fixed instructions string for EVERY provider's cache key (only OpenAI's
# synth actually consumes it). /api/voice/speech and /api/voice/stream must use
# the SAME value or the same phrase would cache twice.
VOICE_SPEECH_INSTRUCTIONS = (
    "Speak clearly and naturally. Preserve the meaning, but do not read markdown "
    "punctuation, raw URLs, or formatting symbols aloud."
)

_TELEGRAM_LOG_SECRET_RE = re.compile(
    r"(https://api\.telegram\.org/bot)[^/\s\"']+",
    re.IGNORECASE,
)
# A bot token that reached a log line without its URL wrapper.
_TELEGRAM_TOKEN_RE = re.compile(r"\b\d{6,12}:[A-Za-z0-9_-]{30,}")
# Alternation is ordered: `key` must precede `k`, `signature` must precede `sig`.
# `k` is ours — the HMAC on signed attachment URLs.
_URL_LOG_SECRET_RE = re.compile(
    r"([?&](?:access_token|api_key|apikey|session_token|token|password|passwd"
    r"|signature|sig|secret|key|auth|k)=)[^&\s\"']+",
    re.IGNORECASE,
)
# Matches a header line (`Authorization: Bearer x`) and a dict repr
# (`{'authorization': 'Bearer x'}`) alike.
_AUTH_LOG_SECRET_RE = re.compile(
    r"(authorization[\"']?\s*[:=]\s*[\"']?(?:bearer\s+)?)[^\s,}\]\"']+",
    re.IGNORECASE,
)


def _redact_log_text(value) -> str:
    """Remove credential-shaped values before any handler writes a record."""
    text = str(value)
    text = _TELEGRAM_LOG_SECRET_RE.sub(r"\1[REDACTED]", text)
    text = _URL_LOG_SECRET_RE.sub(r"\1[REDACTED]", text)
    text = _AUTH_LOG_SECRET_RE.sub(r"\1[REDACTED]", text)
    return _TELEGRAM_TOKEN_RE.sub("[REDACTED]", text)


class _RedactingFormatter(logging.Formatter):
    """Scrub credentials from the *rendered* record, traceback included.

    Redacting in a Filter only ever covers ``record.msg``: the traceback is
    rendered from ``exc_info`` by the formatter afterwards, and that is exactly
    where a credential surfaces — httpx puts the full request URL in its
    exception messages, and Telegram's bot token is path-embedded in that URL.
    Wrapping the handler's own formatter (rather than replacing it) keeps
    uvicorn's colourised output intact.
    """

    def __init__(self, inner: Optional[logging.Formatter] = None) -> None:
        super().__init__()
        self._inner = inner or logging.Formatter()

    def format(self, record: logging.LogRecord) -> str:
        return _redact_log_text(self._inner.format(record))


def _install_log_redaction() -> None:
    """Wrap every configured handler's formatter, exactly once.

    Called at import for the root handlers, and again from the lifespan hook:
    uvicorn installs its own non-propagating `uvicorn*` handlers as the server
    boots — after this module finishes importing — so an import-time pass alone
    would leave "Exception in ASGI application" tracebacks unredacted.
    """
    targets = [logging.getLogger(), *logging.root.manager.loggerDict.values()]
    for target in targets:
        for handler in list(getattr(target, "handlers", None) or []):
            if not isinstance(handler.formatter, _RedactingFormatter):
                handler.setFormatter(_RedactingFormatter(handler.formatter))


logging.basicConfig(
    level=getattr(logging, LOG_LEVEL, logging.INFO),
    format="%(asctime)s %(levelname)s [%(name)s] %(message)s",
)
_install_log_redaction()
# httpx's INFO line includes the complete request URL. Besides being extremely
# noisy for polling, that exposed path-embedded credentials such as Telegram's
# bot token. Application-level failures are logged explicitly where relevant.
logging.getLogger("httpx").setLevel(logging.WARNING)
logging.getLogger("httpcore").setLevel(logging.WARNING)
logger = logging.getLogger("neuroblend.v5")


def _openrouter_price_is_zero(value: object) -> bool:
    """OpenRouter serializes catalog prices as decimal strings."""
    try:
        return float(value) == 0.0
    except (TypeError, ValueError, OverflowError):
        return False


def _openrouter_pricing_is_fully_zero(pricing: object) -> bool:
    """Fail closed if any cost OpenRouter publishes for a model is non-zero."""
    if not isinstance(pricing, dict):
        return False
    cost_fields = set(pricing) - {"overrides"}
    if not {"prompt", "completion"}.issubset(cost_fields):
        return False
    if not all(_openrouter_price_is_zero(pricing.get(field)) for field in cost_fields):
        return False
    overrides = pricing.get("overrides")
    if isinstance(overrides, list):
        for block in (item for item in overrides if isinstance(item, dict)):
            for field in cost_fields:
                if field in block and not _openrouter_price_is_zero(block.get(field)):
                    return False
    elif overrides is not None:
        # An unknown override shape could conceal non-zero conditional pricing.
        return False
    return True


def _openrouter_free_chat_models(
    rows: object,
) -> tuple[tuple[str, ...], dict[str, str]]:
    """Extract every zero-token-cost conversational LLM from a catalog response.

    Embedding, reranking, speech, and media-generation models cannot answer an
    Agent Chat turn. Keep the picker to models whose declared output is text.
    """
    labels: dict[str, str] = {}
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            continue
        model_id = str(row.get("id") or "").strip()
        pricing = row.get("pricing") if isinstance(row.get("pricing"), dict) else {}
        architecture = (
            row.get("architecture") if isinstance(row.get("architecture"), dict) else {}
        )
        input_modalities = architecture.get("input_modalities")
        output_modalities = architecture.get("output_modalities")
        if (
            not _openrouter_model_id_is_free(model_id)
            or not _openrouter_pricing_is_fully_zero(pricing)
            or not isinstance(input_modalities, list)
            or "text" not in input_modalities
            or output_modalities != ["text"]
        ):
            continue
        label = " ".join(str(row.get("name") or model_id).split())[:120] or model_id
        labels[model_id] = label
    ordered = sorted(labels, key=lambda mid: (labels[mid].casefold(), mid.casefold()))
    if "openrouter/free" in ordered:
        ordered.remove("openrouter/free")
        ordered.insert(0, "openrouter/free")
    return tuple(ordered), {mid: labels[mid] for mid in ordered}


def _openrouter_model_options() -> tuple[str, ...]:
    """Every selectable OpenRouter route, restricted to verified free variants."""
    free_models = _OPENROUTER_FREE_MODEL_OPTIONS or OPENROUTER_FREE_MODEL_FALLBACK
    return tuple(dict.fromkeys(("openrouter/free", *free_models)))


def _openrouter_catalog_snapshot() -> dict:
    free_models = _OPENROUTER_FREE_MODEL_OPTIONS or OPENROUTER_FREE_MODEL_FALLBACK
    labels = {
        model_id: _OPENROUTER_FREE_MODEL_LABELS.get(model_id, model_id)
        for model_id in free_models
    }
    return {
        "model_options": list(_openrouter_model_options()),
        "free_model_options": list(free_models),
        "free_model_labels": labels,
        "free_model_count": len(free_models),
        "catalog_status": _OPENROUTER_CATALOG_STATUS,
        "catalog_checked_ts": int(_OPENROUTER_CATALOG_CHECKED_TS),
        "catalog_detail": _OPENROUTER_CATALOG_DETAIL,
    }


def _persist_openrouter_catalog() -> None:
    """Persist only public model ids/labels so restarts retain the last good list."""
    if not _OPENROUTER_FREE_MODEL_OPTIONS:
        return
    payload = {
        "checked_ts": int(_OPENROUTER_CATALOG_CHECKED_TS),
        "models": [
            {
                "id": model_id,
                "label": _OPENROUTER_FREE_MODEL_LABELS.get(model_id, model_id),
            }
            for model_id in _OPENROUTER_FREE_MODEL_OPTIONS
        ],
    }
    try:
        OPENROUTER_CATALOG_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
        tmp = OPENROUTER_CATALOG_CACHE_FILE.with_name(
            f".{OPENROUTER_CATALOG_CACHE_FILE.name}.{os.getpid()}.tmp"
        )
        tmp.write_text(json.dumps(payload, separators=(",", ":")) + "\n")
        os.chmod(tmp, 0o600)
        os.replace(tmp, OPENROUTER_CATALOG_CACHE_FILE)
    except OSError as exc:
        logger.warning("could not persist OpenRouter model catalog: %s", exc)


def _install_openrouter_catalog(
    models: tuple[str, ...], labels: dict[str, str], *, checked_ts: float,
    status: str, detail: str = "", persist: bool = False,
) -> bool:
    global _OPENROUTER_FREE_MODEL_OPTIONS, _OPENROUTER_FREE_MODEL_LABELS
    global _OPENROUTER_CATALOG_CHECKED_TS, _OPENROUTER_CATALOG_STATUS
    global _OPENROUTER_CATALOG_DETAIL
    safe_models = tuple(dict.fromkeys(
        model_id for model_id in models if _openrouter_model_id_is_free(model_id)
    ))
    if not safe_models or "openrouter/free" not in safe_models:
        return False
    _OPENROUTER_FREE_MODEL_OPTIONS = safe_models
    _OPENROUTER_FREE_MODEL_LABELS = {
        mid: str(labels.get(mid) or mid)[:120] for mid in _OPENROUTER_FREE_MODEL_OPTIONS
    }
    _OPENROUTER_CATALOG_CHECKED_TS = float(checked_ts)
    _OPENROUTER_CATALOG_STATUS = status
    _OPENROUTER_CATALOG_DETAIL = detail
    if persist:
        _persist_openrouter_catalog()
    return True


def _load_openrouter_catalog_cache() -> None:
    try:
        payload = json.loads(OPENROUTER_CATALOG_CACHE_FILE.read_text())
        items = payload.get("models") if isinstance(payload, dict) else None
        checked_ts = float(payload.get("checked_ts") or 0) if isinstance(payload, dict) else 0
        models: list[str] = []
        labels: dict[str, str] = {}
        for item in items if isinstance(items, list) else []:
            if not isinstance(item, dict):
                continue
            model_id = str(item.get("id") or "").strip()
            if not _openrouter_model_id_is_free(model_id):
                continue
            models.append(model_id)
            labels[model_id] = " ".join(str(item.get("label") or model_id).split())[:120]
        age = max(0.0, time.time() - checked_ts)
        status = "cached" if age <= OPENROUTER_CATALOG_TTL_S else "stale"
        _install_openrouter_catalog(
            tuple(models), labels, checked_ts=checked_ts, status=status,
            detail="Using the last verified OpenRouter catalog." if status == "stale" else "",
        )
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return


async def _refresh_openrouter_free_catalog(*, force: bool = False) -> dict:
    """Refresh the public catalog with a bounded timeout and stale-safe fallback."""
    global _OPENROUTER_CATALOG_STATUS, _OPENROUTER_CATALOG_DETAIL
    now = time.time()
    if (
        not force
        and _OPENROUTER_FREE_MODEL_OPTIONS
        and now - _OPENROUTER_CATALOG_CHECKED_TS < OPENROUTER_CATALOG_TTL_S
    ):
        return _openrouter_catalog_snapshot()
    async with _OPENROUTER_CATALOG_LOCK:
        now = time.time()
        if (
            not force
            and _OPENROUTER_FREE_MODEL_OPTIONS
            and now - _OPENROUTER_CATALOG_CHECKED_TS < OPENROUTER_CATALOG_TTL_S
        ):
            return _openrouter_catalog_snapshot()
        failure = "OpenRouter's live catalog is temporarily unavailable."
        try:
            async with httpx.AsyncClient(timeout=4.0) as client:
                response = await client.get(OPENROUTER_CATALOG_URL, headers={})
            if response.status_code != 200:
                failure = f"OpenRouter catalog returned HTTP {response.status_code}."
            else:
                payload = response.json()
                rows = payload.get("data") if isinstance(payload, dict) else None
                models, labels = _openrouter_free_chat_models(rows)
                if _install_openrouter_catalog(
                    models, labels, checked_ts=now, status="live", persist=True,
                ):
                    return _openrouter_catalog_snapshot()
                failure = "OpenRouter returned no usable free chat models."
        except (httpx.HTTPError, ValueError, TypeError, json.JSONDecodeError):
            pass
        _OPENROUTER_CATALOG_STATUS = (
            "stale" if _OPENROUTER_FREE_MODEL_OPTIONS else "fallback"
        )
        _OPENROUTER_CATALOG_DETAIL = failure
        return _openrouter_catalog_snapshot()


_load_openrouter_catalog_cache()

