def _mime_blocked(mime: str) -> Optional[str]:
    """Return an error string if this MIME may not be stored, else None.
    Everything is allowed except active web content (HTML/SVG/XML families)."""
    m = (mime or "").lower().strip()
    if m in DISALLOWED_MIME_TYPES:
        return f"mime '{m}' not allowed"
    if "html" in m or m.endswith("+xml"):
        return f"mime '{m}' not allowed"
    return None
