def _agent_public_base(agent: Optional[dict]) -> str:
    """Base URL an agent should use to reach the orchestrator. Container agents
    get CONTAINER_PUBLIC_URL (the Docker host gateway) so localhost-in-container
    does not point back at themselves; every other agent gets the default."""
    if CONTAINER_PUBLIC_URL and agent and agent.get("id") in CONTAINER_AGENT_IDS:
        return CONTAINER_PUBLIC_URL
    return ORCHESTRATOR_PUBLIC_URL


