def _seed_reference_skills(conn: sqlite3.Connection, owner_user_id: int) -> None:
    """Seed the distilled methodology + marketing playbooks (workspace-plan
    phase 2). Insert-if-absent by slug: an edited, re-categorized, or archived
    copy is Owner's and never gets healed back."""
    now = int(time.time() * 1000)
    for playbook in _REFERENCE_PLAYBOOKS:
        if conn.execute(
            "SELECT id FROM skills WHERE slug=?", (playbook["slug"],)
        ).fetchone():
            continue
        steps = [{"role": playbook["role"], "instruction": playbook["instruction"]}]
        conn.execute(
            "INSERT INTO skills(slug, name, kind, description, body, mode, steps_json, "
            "inputs_json, tags_json, secrets_json, status, pack, category, author, "
            "created_ts, updated_ts, owner_user_id) "
            "VALUES (?, ?, 'playbook', ?, ?, 'solo', ?, ?, ?, '[]', 'active', "
            "'General', ?, 'references', ?, ?, ?)",
            (
                playbook["slug"], playbook["name"], playbook["description"],
                playbook["body"], json.dumps(steps), json.dumps(playbook["inputs"]),
                json.dumps(playbook["tags"]), playbook["category"],
                now, now, owner_user_id,
            ),
        )


