def _seed_agent_role_cards(conn: sqlite3.Connection) -> None:
    """Give every roster agent a routing card if it has none, so Delegate and
    Pipeline staff by real strengths instead of an empty fallback. Fill-only:
    never updates an existing row."""
    now = int(time.time() * 1000)
    for agent_id, default_card in _DEFAULT_ROLE_CARDS.items():
        if agent_id not in AGENTS_BY_ID:
            continue
        card = default_card
        if community_mode() and agent_id == "hermes":
            card = {
                "best_for": "Autonomous local work in a contained agent runtime",
                "strengths": [
                    "Long-running task execution",
                    "Tool use inside its own workspace",
                    "Research, planning, and follow-through",
                ],
            }
        if conn.execute(
            "SELECT agent_id FROM agent_cards WHERE agent_id=?", (agent_id,)
        ).fetchone():
            continue
        conn.execute(
            "INSERT INTO agent_cards(agent_id, best_for, strengths, voice, updated_ts) "
            "VALUES (?, ?, ?, '', ?)",
            (
                agent_id, card["best_for"],
                "\n".join(card["strengths"]), now,
            ),
        )


