def _security_headers(response):
    response.headers.setdefault("X-Content-Type-Options", "nosniff")
    response.headers.setdefault("X-Frame-Options", "DENY")
    # Browsers ignore HSTS on plain HTTP, so this is safe for localhost while
    # ensuring the public HTTPS endpoint cannot be downgraded after first use.
    response.headers.setdefault(
        "Strict-Transport-Security", "max-age=31536000; includeSubDomains"
    )
    response.headers.setdefault("Referrer-Policy", "same-origin")
    response.headers.setdefault(
        "Permissions-Policy", "camera=(), microphone=(self), geolocation=(), payment=()"
    )
    response.headers.setdefault(
        "Content-Security-Policy",
        "default-src 'self'; "
        "script-src 'self'; "
        "style-src 'self' 'unsafe-inline'; "
        "font-src 'self'; "
        "img-src 'self' data: blob:; "
        "connect-src 'self' https://api.openai.com; "
        "media-src 'self' blob:; "
        "object-src 'none'; base-uri 'self'; frame-ancestors 'none'"
    )
    return response


# ------------------------- Auth: sessions, users, ownership -------------------------
def _user_with_password(identifier: str) -> Optional[dict]:
    """Look up a user by username or email without revealing which matched."""
    with _db() as conn:
        row = conn.execute(
            "SELECT id, email, username, display_name, preferred_name, password_hash, role, is_active "
            "FROM users WHERE lower(email)=lower(?) OR "
            "(username<>'' AND lower(username)=lower(?))",
            (identifier, identifier),
        ).fetchone()
    if not row:
        return None
    return {
        "id": int(row["id"]), "email": row["email"], "username": row["username"],
        "display_name": row["display_name"],
        "preferred_name": row["preferred_name"], "password_hash": row["password_hash"],
        "role": row["role"], "is_active": bool(row["is_active"]),
    }


def _user_by_id(user_id: Optional[int]) -> Optional[dict]:
    if not user_id:
        return None
    with _db() as conn:
        row = conn.execute(
            "SELECT id, email, username, display_name, preferred_name, role, is_active FROM users WHERE id=?",
            (int(user_id),),
        ).fetchone()
    return _row_user(row)


def _admin_user() -> dict:
    """Synthetic admin used on the legacy-token and dev-bypass paths."""
    real = _user_by_id(_default_admin_id())
    if real:
        return real
    return {
        "id": _default_admin_id(), "email": ADMIN_EMAIL, "display_name": USER_NAME,
        "username": "", "preferred_name": USER_NAME, "role": "admin", "is_active": True,
    }


def _create_login_session(user_id: int) -> tuple[str, int]:
    token = secrets.token_urlsafe(32)
    now_ms = int(time.time() * 1000)
    expires_ms = now_ms + AUTH_SESSION_DAYS * 24 * 60 * 60 * 1000
    with _db() as conn:
        conn.execute(
            "INSERT INTO user_sessions(token_hash, user_id, created_ts, expires_ts, last_seen_ts, last_activity_ts) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (_token_hash(token), int(user_id), now_ms, expires_ms, now_ms, now_ms),
        )
    return token, expires_ms


def _refresh_login_session(token: str) -> tuple[str, int]:
    """Slide an existing session's expiry forward WITHOUT minting a new row, so
    /api/auth/me can keep the caller's token stable. Previously every /api/auth/me
    (page load, reconnect) minted a fresh session and rotated the token — which
    piled up orphan rows (churn) and opened a rotation race that could bounce an
    active user. Reusing the same token kills both. Returns (token, new_expires)."""
    now_ms = int(time.time() * 1000)
    expires_ms = now_ms + AUTH_SESSION_DAYS * 24 * 60 * 60 * 1000
    with _db() as conn:
        conn.execute(
            "UPDATE user_sessions SET expires_ts=?, last_seen_ts=? WHERE token_hash=?",
            (expires_ms, now_ms, _token_hash(token)),
        )
    _invalidate_session_auth_cache(token)
    return token, expires_ms


def _mark_session_active(token: str) -> bool:
    """Refresh a session's idle clock on REAL user activity (the /api/auth/activity
    beacon). Returns False if the session is gone/expired. Deliberately NOT called
    by background polling so an unattended tab still idles out."""
    if not token:
        return False
    now_ms = int(time.time() * 1000)
    with _db() as conn:
        cur = conn.execute(
            "UPDATE user_sessions SET last_activity_ts=?, last_seen_ts=? "
            "WHERE token_hash=? AND expires_ts>?",
            (now_ms, now_ms, _token_hash(token), now_ms),
        )
        active = cur.rowcount > 0
    # The cached user includes last_activity_ts, so both a successful heartbeat
    # and a failed/revoked session must invalidate it.
    _invalidate_session_auth_cache(token)
    return active


# One page boot asks several authenticated read endpoints in parallel. Without
# this tiny positive cache each request opened a new SQLite connection, updated
# the same session row, and reparsed the WAL schema. Two seconds is long enough
# to collapse that burst and short enough that a direct database revocation
# remains prompt; normal logout and refresh invalidate it immediately.
_SESSION_AUTH_CACHE_TTL_S = 2.0
_SESSION_AUTH_CACHE_MAX = 256
_SESSION_AUTH_CACHE: dict[str, tuple[float, dict]] = {}
_SESSION_AUTH_CACHE_LOCK = threading.Lock()


def _invalidate_session_auth_cache(token: str = "") -> None:
    with _SESSION_AUTH_CACHE_LOCK:
        if token:
            _SESSION_AUTH_CACHE.pop(_token_hash(token), None)
        else:
            _SESSION_AUTH_CACHE.clear()


def _session_user_from_token(token: str) -> Optional[dict]:
    if not token:
        return None
    token_hash = _token_hash(token)
    now_mono = time.monotonic()
    with _SESSION_AUTH_CACHE_LOCK:
        cached = _SESSION_AUTH_CACHE.get(token_hash)
        if cached and now_mono - cached[0] < _SESSION_AUTH_CACHE_TTL_S:
            return dict(cached[1])
        if cached:
            _SESSION_AUTH_CACHE.pop(token_hash, None)
    now_ms = int(time.time() * 1000)
    with _db() as conn:
        row = conn.execute(
            "SELECT u.id, u.email, u.username, u.display_name, u.preferred_name, u.role, u.is_active, "
            "s.last_activity_ts AS last_activity_ts "
            "FROM user_sessions s JOIN users u ON u.id = s.user_id "
            "WHERE s.token_hash=? AND s.expires_ts>? AND u.is_active=1",
            (token_hash, now_ms),
        ).fetchone()
        if not row:
            return None
        # Idle lock is client-side. Do not delete the session here: an in-flight
        # agent and its stream must keep going while the UI asks for the password.
        # AUTH_SESSION_DAYS (expires_ts) remains the hard cap.
        conn.execute(
            "UPDATE user_sessions SET last_seen_ts=? WHERE token_hash=?",
            (now_ms, token_hash),
        )
    user = _row_user(row)
    with _SESSION_AUTH_CACHE_LOCK:
        if len(_SESSION_AUTH_CACHE) >= _SESSION_AUTH_CACHE_MAX:
            oldest = min(_SESSION_AUTH_CACHE, key=lambda key: _SESSION_AUTH_CACHE[key][0])
            _SESSION_AUTH_CACHE.pop(oldest, None)
        _SESSION_AUTH_CACHE[token_hash] = (now_mono, dict(user))
    return user


def _current_user(request: Optional[Request]) -> Optional[dict]:
    if not request:
        return _admin_user() if not REQUIRE_AUTH and not ACCESS_TOKEN else None
    cached = getattr(request.state, "current_user", None)
    if cached:
        return cached
    # EventSource cannot set custom headers, so the stream keeps a narrow legacy
    # query-token fallback. Never accept session credentials in arbitrary API
    # URLs where proxies, history and referrers can retain them.
    query_token = (
        request.query_params.get("session_token", "")
        if request.method == "GET" and request.url.path == "/api/stream"
        else ""
    )
    token = (
        request.cookies.get("agent_chat_session", "")
        or request.headers.get("x-agent-chat-session", "")
        or query_token
    ).strip()
    user = _session_user_from_token(token)
    if not user:
        supplied = _access_token_from_request(request)
        if ACCESS_TOKEN and secrets.compare_digest(supplied, ACCESS_TOKEN):
            user = _admin_user()
    if not user and not REQUIRE_AUTH and not ACCESS_TOKEN:
        user = _admin_user()
    if user:
        request.state.current_user = user
    return user


def _is_admin_user(user: Optional[dict]) -> bool:
    return bool(user and user.get("role") == "admin" and user.get("is_active"))


def _chat_owner_id(cid: int) -> Optional[int]:
    try:
        if int(cid) <= 0:
            return None
    except (TypeError, ValueError):
        return None
    chat = CHAT_INDEX.get("chats", {}).get(str(cid))
    if isinstance(chat, dict) and chat.get("owner_user_id"):
        return int(chat["owner_user_id"])
    with _db() as conn:
        row = conn.execute("SELECT owner_user_id FROM chats WHERE id=?", (int(cid),)).fetchone()
    return int(row["owner_user_id"]) if row and row["owner_user_id"] else None


def _chat_belongs_to_user(cid: int, user: Optional[dict]) -> bool:
    if not user:
        return False
    # SQLite is authoritative across worker processes. A peer can move a chat
    # to Trash while this process still has a stale live index, so ownership
    # alone (or only this process's cache) cannot grant ordinary access.
    _refresh_index_from_storage()
    try:
        with _db() as conn:
            row = conn.execute(
                "SELECT owner_user_id FROM chats "
                "WHERE id=? AND deleted_ts IS NULL",
                (int(cid),),
            ).fetchone()
    except (sqlite3.Error, TypeError, ValueError):
        return False
    return bool(
        row and row["owner_user_id"] is not None
        and int(row["owner_user_id"]) == int(user["id"])
    )


def _principal_name_for_owner(owner_id: Optional[int]) -> str:
    """The name agents should address this owner by. The user's PROFILE
    (address_as / name) is authoritative and SUPERSEDES the account name — so a
    user who told onboarding to call them "User" is "User" everywhere, not their
    login name. Falls back to the account's preferred/display name, then to the
    professional generic (GENERIC_PRINCIPAL)."""
    try:
        prof = _get_user_profile(owner_id)
        nm = (prof.get("address_as") or prof.get("name") or "").strip()
        if nm:
            return nm
    except Exception:
        pass
    return _preferred_name(_user_by_id(owner_id) if owner_id else None)


def _chat_principal_name(cid: int) -> str:
    """Display name of the chat's owner, for agent prompts and message
    attribution. Each chat belongs to exactly one user, so the owner IS the
    human principal the agents are serving in this room. The owner's profile name
    wins over their account name (see _principal_name_for_owner); falls back to a
    professional generic (GENERIC_PRINCIPAL) when the owner can't be resolved."""
    try:
        return _principal_name_for_owner(_chat_owner_id(cid))
    except Exception:
        return _preferred_name(None)


# --- User Profile platform (Phase 0) -----------------------------------------
# A structured, versioned, owner-owned record of who a user is, injected into
# EVERY agent's prompt via build_prompt() so the whole team shares one
# authoritative source of truth. build_prompt() is the single dispatch path for
# every agent (host bridges AND Agent Zero containers) and runs each turn, so an
# edit is live on every agent's very next message — no per-agent push is needed
# for the prompt path. Stored as users.profile_json ('{}' = no profile, a no-op).
# Free-text fields are fenced as untrusted DATA before injection (the block lands
# in every agent's prompt, so it must not become an injection vector).
def _get_user_profile(user_id: Optional[int]) -> dict:
    if not user_id:
        return {}
    try:
        with _db() as conn:
            row = conn.execute(
                "SELECT profile_json FROM users WHERE id=?", (int(user_id),)
            ).fetchone()
        if not row:
            return {}
        data = json.loads(row["profile_json"] or "{}")
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _save_user_profile(user_id: int, profile: dict) -> dict:
    """Persist a profile, bumping version + stamping locked/updated_ts. Returns
    the saved record. This is the ONLY sanctioned writer (Settings edit /
    onboarding); agents read the profile but never call this."""
    prev = _get_user_profile(user_id)
    out = dict(profile or {})
    out["version"] = int(prev.get("version", 0) or 0) + 1
    out["locked"] = True
    out["updated_ts"] = int(time.time())
    with _db() as conn:
        conn.execute(
            "UPDATE users SET profile_json=? WHERE id=?",
            (json.dumps(out), int(user_id)),
        )
    return out


def _get_user_ui_prefs(user_id: Optional[int]) -> dict:
    if not user_id:
        return {}
    try:
        with _db() as conn:
            row = conn.execute(
                "SELECT ui_prefs_json FROM users WHERE id=?", (int(user_id),)
            ).fetchone()
        data = json.loads((row["ui_prefs_json"] if row else "") or "{}")
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


# Bounds for the roaming UI-prefs bag. Values are opaque strings (the client
# stores localStorage values verbatim); the caps only keep a buggy client from
# growing the row without limit.
_UI_PREFS_MAX_KEYS = 128
_UI_PREFS_MAX_KEY_LEN = 128
_UI_PREFS_MAX_VALUE_LEN = 16_384
_UI_PREFS_MAX_TOTAL = 65_536


def _save_user_ui_prefs(user_id: int, prefs: dict) -> dict:
    """Replace the whole roaming UI-prefs bag after bounds-checking it.

    Whole-bag replace (not merge) so the client can also delete keys; the client
    always POSTs its complete allowlisted set. Raises ValueError on oversize or
    non-string content rather than silently truncating."""
    if not isinstance(prefs, dict) or len(prefs) > _UI_PREFS_MAX_KEYS:
        raise ValueError("prefs must be an object with a bounded number of keys")
    clean: dict = {}
    total = 0
    for key, value in prefs.items():
        if not isinstance(key, str) or not key or len(key) > _UI_PREFS_MAX_KEY_LEN:
            raise ValueError("invalid pref key")
        if not isinstance(value, str) or len(value) > _UI_PREFS_MAX_VALUE_LEN:
            raise ValueError("pref values must be short strings")
        total += len(key) + len(value)
        if total > _UI_PREFS_MAX_TOTAL:
            raise ValueError("prefs too large")
        clean[key] = value
    with _db() as conn:
        conn.execute(
            "UPDATE users SET ui_prefs_json=? WHERE id=?",
            (json.dumps(clean), int(user_id)),
        )
    return clean


def _sabbath_mode_enabled(profile: dict) -> bool:
    """True when the profile carries a Sabbath quiet-hours window."""
    cons = (profile or {}).get("constraints") or {}
    for w in (cons.get("quiet_hours") or []):
        if isinstance(w, dict) and (w.get("rule") or "").strip().lower() in SABBATH_RULES:
            return True
    return False


def _set_sabbath_mode(user_id: int, on: bool) -> dict:
    """Appliance-style switch: one flag, no window arithmetic for the user.

    Flipping it on appends the Sabbath quiet-hours window (Friday candle-lighting
    to Saturday nightfall, computed from the profile timezone's coordinates);
    flipping it off removes every Sabbath window while leaving any unrelated
    daily quiet hours alone. The enforcement already exists at the proactive
    chokepoints — scheduler, web-push, pager — this just turns it on."""
    profile = dict(_get_user_profile(user_id) or {})
    cons = dict(profile.get("constraints") or {})
    windows = [w for w in (cons.get("quiet_hours") or [])
               if isinstance(w, dict)
               and (w.get("rule") or "").strip().lower() not in SABBATH_RULES]
    if on:
        windows.append({"label": SABBATH_MODE_LABEL, "rule": "sabbath",
                        "from": "", "to": ""})
    cons["quiet_hours"] = windows[:12]
    profile["constraints"] = cons
    return _save_user_profile(user_id, profile)


def _sabbath_mode_state(user_id: Optional[int]) -> dict:
    """Current Sabbath Mode state for the UI: whether it is on, and whether the
    quiet window is active right now (so the switch can read 'on — quiet until
    nightfall' rather than just 'on')."""
    profile = _get_user_profile(user_id)
    on = _sabbath_mode_enabled(profile)
    active, label = _profile_quiet_now(user_id) if on else (False, "")
    cons = (profile or {}).get("constraints") or {}
    tzname = (cons.get("timezone") or "").strip()
    return {
        "enabled": on,
        "active_now": bool(active),
        "label": label or SABBATH_MODE_LABEL,
        "timezone": tzname,
        # Sunset math needs coordinates; without them the window falls back to a
        # fixed Fri 18:30 → Sat 20:00. Surface that so it isn't a silent downgrade.
        "sunset_precision": bool(_TZ_LATLON.get(tzname)),
        "window": "Friday candle-lighting (sunset−18m) → Saturday nightfall (sunset+50m)",
    }


def _user_profile_for_chat(cid: int) -> dict:
    try:
        return _get_user_profile(_chat_owner_id(cid))
    except Exception:
        return {}


def _render_profile_block(profile: dict) -> str:
    """Render the authoritative profile block injected into agent prompts.
    Returns '' for an empty profile (the live default, so this is a no-op until a
    user fills it in). Descriptive free-text (context, notes) is fenced as DATA,
    never instructions — a prompt-injection guard, since this lands in every
    agent's prompt. Structured limits (quiet hours, hard no's) are presented as
    the user's own stated rules; the SYSTEM enforces the load-bearing ones in
    code (Phase 0.4), so honoring them never relies on model goodwill alone."""
    if not isinstance(profile, dict) or not profile:
        return ""
    lines: list[str] = []
    name = (profile.get("address_as") or profile.get("name") or "").strip()
    if name:
        roleorg = ", ".join(
            p for p in ((profile.get("role") or "").strip(),
                        (profile.get("org") or "").strip()) if p
        )
        lines.append(f"  Name: {name}{(' — ' + roleorg) if roleorg else ''}")
    pri = profile.get("priorities")
    if isinstance(pri, (list, tuple)):
        pri = ", ".join(str(p).strip() for p in pri if str(p).strip())
    pri = (pri or "").strip() if isinstance(pri, str) else ""
    if pri:
        lines.append(f"  Wants help with: {pri}")
    comms = (profile.get("comms_style") or "").strip()
    if comms:
        lines.append(f"  Communication: {comms}")
    constraints = profile.get("constraints") or {}
    if not isinstance(constraints, dict):
        constraints = {}
    qh_labels: list[str] = []
    for w in (constraints.get("quiet_hours") or []):
        if not isinstance(w, dict):
            continue
        lab = (w.get("label") or "").strip()
        frm = (w.get("from") or "").strip()
        to = (w.get("to") or "").strip()
        if lab and frm and to:
            qh_labels.append(f"{lab} ({frm}–{to})")
        elif lab:
            qh_labels.append(lab)
    if qh_labels:
        lines.append(f"  Quiet hours (do not contact): {'; '.join(qh_labels)}")
    hard = constraints.get("hard_nos") or []
    if isinstance(hard, (list, tuple)):
        hard = [str(h).strip() for h in hard if str(h).strip()]
        if hard:
            lines.append(f"  Never: {'; '.join(hard)}")
    tz = (constraints.get("timezone") or "").strip()
    if tz:
        lines.append(f"  Timezone: {tz}")
    # Context + the free-form "always keep in mind" note are the user's OWN
    # standing preferences/instructions (owner-scoped account data, not
    # third-party content), so they're honored like the rest of the profile —
    # not fenced off as inert data. Every field the user set is authoritative.
    ctx = (profile.get("context") or "").strip()
    if ctx:
        lines.append(f"  Context: {ctx}")
    notes = (constraints.get("notes") or "").strip()
    if notes:
        lines.append(f"  Always keep in mind: {notes}")
    if not lines:
        return ""
    block = (
        "\nAbout the person you're helping — set by them; treat as authoritative "
        "and honor it (their name, preferences, and standing instructions). Never "
        "contradict or overwrite it.\n" + "\n".join(lines)
    )
    block += f"\n[profile v{int(profile.get('version', 0) or 0)}]"
    return block


PROFILE_MAX_STR = 2000
PROFILE_COMMS_STYLES = ("brief", "detailed")


def _profile_clean_str(v, limit: int = PROFILE_MAX_STR) -> str:
    return v.strip()[:limit] if isinstance(v, str) else ""


def _normalize_profile(payload: dict) -> dict:
    """Whitelist + coerce a client-supplied profile into the stored shape. The
    server owns version/locked/updated_ts/source (stamped in _save_user_profile),
    so any of those in the payload are ignored, and unknown keys are dropped. This
    is the validation boundary for the write endpoints."""
    p = payload if isinstance(payload, dict) else {}
    out: dict = {}
    for k in ("name", "address_as", "role", "org", "context"):
        v = _profile_clean_str(p.get(k))
        if v:
            out[k] = v
    lang = _profile_clean_str(p.get("language"), 16)
    if lang:
        out["language"] = lang
    comms = _profile_clean_str(p.get("comms_style"), 16)
    if comms in PROFILE_COMMS_STYLES:
        out["comms_style"] = comms
    pri = p.get("priorities")
    if isinstance(pri, str):
        pri = pri.split(",")
    if isinstance(pri, (list, tuple)):
        pri = [s for s in (_profile_clean_str(x, 120) for x in pri) if s][:12]
        if pri:
            out["priorities"] = pri
    cin = p.get("constraints")
    cin = cin if isinstance(cin, dict) else {}
    cons: dict = {}
    tz = _profile_clean_str(cin.get("timezone"), 64)
    if tz:
        cons["timezone"] = tz
    qh = cin.get("quiet_hours")
    if isinstance(qh, (list, tuple)):
        windows = []
        for w in qh:
            if not isinstance(w, dict):
                continue
            win = {
                "label": _profile_clean_str(w.get("label"), 60),
                "rule": _profile_clean_str(w.get("rule"), 32) or "daily",
                "from": _profile_clean_str(w.get("from"), 40),
                "to": _profile_clean_str(w.get("to"), 40),
            }
            if win["label"] or (win["from"] and win["to"]):
                windows.append(win)
        if windows:
            cons["quiet_hours"] = windows[:12]
    hn = cin.get("hard_nos")
    if isinstance(hn, str):
        hn = [hn]
    if isinstance(hn, (list, tuple)):
        hn = [s for s in (_profile_clean_str(x, 200) for x in hn) if s][:12]
        if hn:
            cons["hard_nos"] = hn
    notes = _profile_clean_str(cin.get("notes"))
    if notes:
        cons["notes"] = notes
    if cons:
        out["constraints"] = cons
    return out


# --- Quiet hours engine (User Profile platform, Phase 0.4) -------------------
# Enforcement, not instruction: when the owner is inside a quiet-hours window we
# suppress proactive contact (web-push + the recurring-automation Telegram pager)
# so the app simply won't disturb them. Pure + injectable `now` for tests. A
# "shabbos" rule is computed from real sunset at the timezone's city (Fri
# candle-lighting → Sat nightfall); daily windows are exact local-time ranges
# with overnight wrap. EVERYTHING fails OPEN (returns "not quiet") on any error,
# so a bug here can never silently swallow an alert.
_TZ_LATLON = {
    "America/New_York": (40.71, -74.01), "America/Chicago": (41.88, -87.63),
    "America/Denver": (39.74, -104.99), "America/Los_Angeles": (34.05, -118.24),
    "America/Sao_Paulo": (-23.55, -46.63), "Europe/London": (51.51, -0.13),
    "Europe/Paris": (48.85, 2.35), "Europe/Berlin": (52.52, 13.40),
    "Asia/Jerusalem": (31.78, 35.22), "Asia/Dubai": (25.20, 55.27),
    "Asia/Kolkata": (22.57, 88.36), "Asia/Shanghai": (31.23, 121.47),
    "Asia/Tokyo": (35.68, 139.69), "Australia/Sydney": (-33.87, 151.21),
}


def _parse_hhmm(raw) -> Optional[int]:
    """Minutes since midnight from '21:00', '9:30', '9pm', '9:30 pm'. None if unparseable."""
    s = str(raw or "").strip().lower()
    m = re.match(r"^(\d{1,2})(?::(\d{2}))?\s*(am|pm)?$", s)
    if not m:
        return None
    h = int(m.group(1)); mn = int(m.group(2) or 0); ap = m.group(3)
    if ap == "pm" and h < 12:
        h += 12
    if ap == "am" and h == 12:
        h = 0
    if h > 23 or mn > 59:
        return None
    return h * 60 + mn


def _daily_quiet_active(frm, to, now_local) -> bool:
    f = _parse_hhmm(frm); t = _parse_hhmm(to)
    if f is None or t is None or f == t:
        return False
    cur = now_local.hour * 60 + now_local.minute
    return (f <= cur < t) if f < t else (cur >= f or cur < t)


def _sunset_local_minutes(d, lat, lon, offset_hours) -> Optional[int]:
    """Local time-of-day (minutes since midnight) of sunset on date `d` at
    lat/lon, given the local UTC offset in hours. Standard sunrise/sunset
    algorithm (official zenith 90.833°). Computing a TIME-OF-DAY (not a datetime)
    sidesteps the UTC date-rollover that bites western longitudes. None on
    polar no-set days or any error."""
    try:
        import math
        N = d.timetuple().tm_yday
        lng_hour = lon / 15.0
        t = N + ((18 - lng_hour) / 24.0)  # setting
        M = (0.9856 * t) - 3.289
        L = (M + 1.916 * math.sin(math.radians(M))
             + 0.020 * math.sin(math.radians(2 * M)) + 282.634) % 360
        RA = math.degrees(math.atan(0.91764 * math.tan(math.radians(L)))) % 360
        RA = (RA + (((math.floor(L / 90)) * 90) - ((math.floor(RA / 90)) * 90))) / 15.0
        sin_dec = 0.39782 * math.sin(math.radians(L))
        cos_dec = math.cos(math.asin(sin_dec))
        cos_h = ((math.cos(math.radians(90.833)) - (sin_dec * math.sin(math.radians(lat))))
                 / (cos_dec * math.cos(math.radians(lat))))
        if cos_h < -1 or cos_h > 1:
            return None
        H = math.degrees(math.acos(cos_h)) / 15.0  # setting
        T = H + RA - (0.06571 * t) - 6.622
        ut = (T - lng_hour) % 24
        local = (ut + offset_hours) % 24
        return int(round(local * 60))
    except Exception:
        return None


SABBATH_MODE_LABEL = "Sabbath Mode"
# Quiet-hours rule keys that mean "the weekly Sabbath window". 'shabbos' is the
# original key and still appears in saved profiles, so both must keep working.
SABBATH_RULES = ("sabbath", "shabbos")


def _shabbos_quiet_active(now_local, latlon) -> bool:
    """Fri candle-lighting (sunset−18m) → Sat nightfall (sunset+50m), in the
    owner's timezone. Falls back to a fixed Fri 18:30 → Sat 20:00 window when we
    have no coordinates for the timezone."""
    wd = now_local.weekday()  # Mon=0 … Fri=4, Sat=5, Sun=6
    if wd not in (4, 5):
        return False
    now_min = now_local.hour * 60 + now_local.minute
    off = now_local.utcoffset()
    off_h = (off.total_seconds() / 3600.0) if off else 0.0
    ss = _sunset_local_minutes(now_local.date(), latlon[0], latlon[1], off_h) if latlon else None
    if wd == 4:  # Friday — quiet once candle-lighting passes
        start = (ss - 18) if ss is not None else (18 * 60 + 30)
        return now_min >= start
    end = (ss + 50) if ss is not None else (20 * 60)  # Saturday — quiet until nightfall
    return now_min <= end


def _profile_quiet_at(profile, now=None) -> tuple[bool, str]:
    """(active, label): is `now` inside any of the profile's quiet-hours windows?
    `now` is an aware datetime (defaults to real now, UTC). Fails to (False, '')."""
    try:
        cons = (profile or {}).get("constraints") or {}
        windows = cons.get("quiet_hours") or []
        if not windows:
            return (False, "")
        from datetime import timezone as _tz
        tzname = (cons.get("timezone") or "").strip()
        tz = _sched_tz(tzname)
        nowdt = now or datetime.now(_tz.utc)
        if nowdt.tzinfo is None:
            nowdt = nowdt.replace(tzinfo=_tz.utc)
        now_local = nowdt.astimezone(tz) if tz else nowdt
        for w in windows:
            if not isinstance(w, dict):
                continue
            rule = (w.get("rule") or "daily").strip().lower()
            if rule in SABBATH_RULES:
                if _shabbos_quiet_active(now_local, _TZ_LATLON.get(tzname)):
                    return (True, w.get("label") or SABBATH_MODE_LABEL)
            elif _daily_quiet_active(w.get("from"), w.get("to"), now_local):
                return (True, w.get("label") or "Quiet hours")
        return (False, "")
    except Exception:
        return (False, "")


def _profile_quiet_now(owner_user_id, now=None) -> tuple[bool, str]:
    """Is the given owner currently inside a quiet-hours window? The proactive
    chokepoints (web-push, automation pager) call this to honor "do not contact"."""
    return _profile_quiet_at(_get_user_profile(owner_user_id), now)


# --- Onboarding (Phase 1): resumable first-run state --------------------------
# Progress lives in users.onboarding_state ('{}' = not started);
# onboarding_completed_ts is set when the user finishes or skips. The client
# reads `onboarding` from /api/auth/me to decide whether to auto-launch the
# guided first-run and where to resume.
def _get_onboarding_state(user_id: Optional[int]) -> dict:
    if not user_id:
        return {}
    try:
        with _db() as conn:
            row = conn.execute(
                "SELECT onboarding_state, onboarding_completed_ts FROM users WHERE id=?",
                (int(user_id),),
            ).fetchone()
        if not row:
            return {}
        st = json.loads(row["onboarding_state"] or "{}")
        st = st if isinstance(st, dict) else {}
        st["completed"] = row["onboarding_completed_ts"] is not None
        st["completed_ts"] = row["onboarding_completed_ts"]
        return st
    except Exception:
        return {}


def _save_onboarding_state(user_id: int, *, phase=None, answers=None,
                           completed: Optional[bool] = None) -> dict:
    """Persist resumable first-run progress. `answers` is shallow-MERGED into any
    existing answers (each step adds a few). completed=True stamps the completion
    ts once (idempotent); completed=False clears it (a full restart)."""
    cur = _get_onboarding_state(user_id)
    phase_v = str((phase if phase is not None else cur.get("phase", "")) or "")
    merged = dict(cur.get("answers") or {})
    if isinstance(answers, dict):
        merged.update(answers)
    store = json.dumps({"phase": phase_v, "answers": merged})
    with _db() as conn:
        if completed is True:
            conn.execute(
                "UPDATE users SET onboarding_state=?, "
                "onboarding_completed_ts=COALESCE(onboarding_completed_ts, ?) WHERE id=?",
                (store, int(time.time()), int(user_id)),
            )
        elif completed is False:
            conn.execute(
                "UPDATE users SET onboarding_state=?, onboarding_completed_ts=NULL WHERE id=?",
                (store, int(user_id)),
            )
        else:
            conn.execute(
                "UPDATE users SET onboarding_state=? WHERE id=?", (store, int(user_id)),
            )
    return _get_onboarding_state(user_id)


def _onboarding_public(user_id: Optional[int]) -> dict:
    st = _get_onboarding_state(user_id)
    return {
        "completed": bool(st.get("completed")),
        "phase": st.get("phase", ""),
        "answers": st.get("answers") or {},
    }


