def _pick_onboarding_starter(owner_user_id, answers):
    """Pick the best curated REAL starter skill available to the user (global or
    owned), matched to their priorities. Returns (entry, skill) or None if none
    are seeded — the caller then falls back to the synthetic catalog."""
    avail = []
    for entry in ONBOARDING_STARTER_SLUGS:
        try:
            sk = _get_skill(entry["slug"], owner_user_id=owner_user_id)
        except Exception:
            sk = None
        if sk and sk.get("status") == "active":
            avail.append((entry, sk))
    if not avail:
        return None
    a = answers if isinstance(answers, dict) else {}
    pri = a.get("priorities")
    if isinstance(pri, (list, tuple)):
        pri = " ".join(str(x) for x in pri)
    hay = " ".join(str(x) for x in (pri or "", a.get("role") or "", a.get("keep_in_mind") or "")).lower()
    best, best_score = avail[0], -1
    for entry, sk in avail:
        score = sum(1 for kw in entry["match"] if kw in hay)
        if score > best_score:
            best, best_score = (entry, sk), score
    return best


def _prefill_starter_inputs(skill, profile) -> list:
    """Pre-fill a starter skill's inputs from the profile so the user can run with
    one tap (or tweak). Returns [{name, label, value, placeholder}]."""
    p = profile if isinstance(profile, dict) else {}
    pri = p.get("priorities")
    if isinstance(pri, (list, tuple)):
        pri = ", ".join(str(x) for x in pri)
    pri = (pri or "").strip()
    out = []
    for inp in (skill.get("inputs") or []):
        nm = (inp.get("name") or "").strip()
        item = {"name": nm, "label": inp.get("label") or nm, "value": "", "placeholder": ""}
        if nm == "decision":
            # Leave blank with a clear example — a debate needs a real decision the
            # user states (auto-filling from a vague goal reads awkwardly).
            item["placeholder"] = "e.g. Should we expand to a new market this year?"
        elif nm == "paths":
            item["placeholder"] = "e.g. Expand now · Wait a quarter · Partner instead"
        elif nm == "my_needs":
            item["value"] = pri
            item["placeholder"] = "What matters most to you here"
        elif nm == "product_url":
            item["placeholder"] = "Paste a product link to evaluate"
        elif nm == "logs":
            item["value"] = "24"
            item["placeholder"] = "How many hours back to review"
        else:
            item["placeholder"] = inp.get("label") or nm
        out.append(item)
    return out


def _allowed_agent_ids_for_user(
    user: Optional[dict], *, include_secret_conflicts: bool = False,
) -> set:
    if not user:
        return set()
    with _db() as conn:
        rows = conn.execute(
            "SELECT agent_id FROM user_agents WHERE user_id=?", (int(user["id"]),)
        ).fetchall()
        allowed = {r["agent_id"] for r in rows if r["agent_id"] in AGENTS_BY_ID}
        if include_secret_conflicts or not allowed:
            return allowed
        # Secret vaults/env files belong to a physical agent runtime, not to an
        # individual chat. If another owner has provisioned that runtime, fail
        # closed: this user may not run it and therefore cannot exercise or read
        # the other owner's credential through tools or prompts.
        legacy_shared = conn.execute(
            "SELECT 1 FROM agent_secrets "
            "WHERE owner_user_id<>? AND backend='shared_env' LIMIT 1",
            (int(user["id"]),),
        ).fetchone()
        if legacy_shared:
            return set()
        blocked = {
            r["agent_id"]
            for r in conn.execute(
                "SELECT DISTINCT agent_id FROM agent_secrets WHERE owner_user_id<>?",
                (int(user["id"]),),
            ).fetchall()
        }
        blocked.update(
            r["agent_id"]
            for r in conn.execute(
                "SELECT DISTINCT agent_id FROM secret_restart_blocks "
                "WHERE owner_user_id<>?",
                (int(user["id"]),),
            ).fetchall()
        )
    return allowed - blocked


# --- Per-agent typical reply time (for the voice picker "how long to respond") ---
# Median of each agent's recent user→reply gaps. Capped at 45s so heavy agentic
# turns (file edits, tool loops) don't distort the conversational expectation a
# voice user cares about, and cached so building the agents payload never pays a
# per-request table scan. Surfaced as `response_secs`; the client turns it into
# plain words ("usually replies in ~8s").
_AGENT_LATENCY_CACHE: dict = {"ts": 0.0, "data": {}}
_AGENT_LATENCY_TTL = 600.0  # 10 min

# An agent silent this long is shown as dormant. The roster lists every
# configured agent equally, so a retired one looks identical to a live one — two
# agents had been silent 37 days while still occupying a slot, a bridge and a
# port. Measured from real output, so an agent that starts talking again clears
# itself with no bookkeeping.
_AGENT_DORMANT_DAYS = int(os.environ.get("AGENT_DORMANT_DAYS", "14"))
_AGENT_LASTSEEN_CACHE: dict = {"ts": 0.0, "data": {}}
_AGENT_LASTSEEN_TTL = 600.0  # 10 min


def _agent_last_seen_ms() -> dict:
    """{agent_id: ts of its most recent message}. Cached like the latency stats so
    building the agents payload never pays a table scan."""
    now = time.time()
    cache = _AGENT_LASTSEEN_CACHE
    if cache["data"] and (now - cache["ts"] < _AGENT_LASTSEEN_TTL):
        return cache["data"]
    data: dict = {}
    try:
        with _db() as conn:
            rows = conn.execute(
                "SELECT agent_id, MAX(ts) AS last_ts FROM messages "
                "WHERE role='agent' AND agent_id IS NOT NULL AND agent_id<>'' "
                "GROUP BY agent_id"
            ).fetchall()
        data = {r["agent_id"]: int(r["last_ts"] or 0) for r in rows}
    except Exception:
        logger.exception("agent last-seen lookup failed")
        return cache["data"] or {}
    cache["ts"] = now
    cache["data"] = data
    return data


def _agent_response_seconds() -> dict:
    now = time.time()
    cache = _AGENT_LATENCY_CACHE
    if cache["data"] and (now - cache["ts"] < _AGENT_LATENCY_TTL):
        return cache["data"]
    try:
        with _db() as conn:
            rows = conn.execute(
                """
                WITH ordered AS (
                  SELECT chat_id, role, agent_id, ts, id,
                         LEAD(role)     OVER (PARTITION BY chat_id ORDER BY id) AS nrole,
                         LEAD(agent_id) OVER (PARTITION BY chat_id ORDER BY id) AS nagent,
                         LEAD(ts)       OVER (PARTITION BY chat_id ORDER BY id) AS nts
                  FROM messages
                )
                SELECT nagent AS agent_id, (nts - ts) AS delta_ms
                FROM ordered
                WHERE role='user' AND nrole='agent' AND nagent IS NOT NULL
                  AND (nts - ts) BETWEEN 300 AND 45000
                ORDER BY ts DESC, id DESC
                """
            ).fetchall()
    except Exception:
        rows = []
    buckets: dict = {}
    for row in rows:
        lst = buckets.setdefault(row["agent_id"], [])
        if len(lst) < 30:  # most recent 30 turns per agent
            lst.append(row["delta_ms"])
    stats: dict = {}
    for aid, deltas in buckets.items():
        if len(deltas) < 5:  # too little history to be meaningful
            continue
        deltas.sort()
        n = len(deltas)
        median_ms = deltas[n // 2] if n % 2 else (deltas[n // 2 - 1] + deltas[n // 2]) / 2
        stats[aid] = round(median_ms / 1000.0, 1)
    cache["ts"] = now
    cache["data"] = stats
    return stats


def _allowed_agents_for_user(user: Optional[dict]) -> list:
    allowed = _allowed_agent_ids_for_user(user)
    stats = _agent_response_seconds()
    last_seen = _agent_last_seen_ms()
    now_ms = int(time.time() * 1000)
    out = []
    for a in AGENTS:
        if a["id"] not in allowed:
            continue
        pub = _public_agent(a)
        # Measured only — an agent with no reply history shows NO estimate rather
        # than a made-up default (the client hides the tag when this is absent).
        secs = stats.get(a["id"])
        if secs:
            pub["response_secs"] = secs
        # Dormancy is likewise measured, never configured: an agent that speaks
        # again clears the flag by itself on the next cache refresh.
        seen = last_seen.get(a["id"])
        if seen:
            idle_days = max(0, (now_ms - seen) // 86_400_000)
            pub["last_seen_ts"] = seen
            pub["idle_days"] = int(idle_days)
            if _AGENT_DORMANT_DAYS > 0 and idle_days >= _AGENT_DORMANT_DAYS:
                pub["dormant"] = True
        out.append(pub)
    return out


def _allowed_agent_ids_for_chat(cid: int) -> set:
    owner_id = _chat_owner_id(cid)
    if not owner_id:
        return set()
    return _allowed_agent_ids_for_user({"id": owner_id, "is_active": True})


def _filter_chat_for_user(cid: str, chat: dict, user: Optional[dict]) -> Optional[dict]:
    if not user or not isinstance(chat, dict):
        return None
    try:
        if int(cid) <= 0:
            return None
    except (TypeError, ValueError):
        return None
    if int(chat.get("owner_user_id") or 0) != int(user["id"]):
        return None
    allowed = _allowed_agent_ids_for_user(user)
    item = dict(chat)
    if isinstance(item.get("targets"), list):
        item["targets"] = [tid for tid in item["targets"] if tid in allowed]
    if isinstance(item.get("contexts"), dict):
        item["contexts"] = {tid: ctx for tid, ctx in item["contexts"].items() if tid in allowed}
    return item


def _chat_index_for_user(user: Optional[dict]) -> dict:
    chats = {}
    for cid, chat in (CHAT_INDEX.get("chats") or {}).items():
        item = _filter_chat_for_user(cid, chat, user)
        if item is not None:
            chats[cid] = item
    return {"active_id": CHAT_INDEX.get("active_id", 1001), "chats": chats}


def _trash_index_for_user(user: Optional[dict]) -> dict:
    """Return reversible, owner-scoped Trash metadata without putting deleted
    chats back into ``CHAT_INDEX``. Keeping the live index clean makes every
    ordinary chat route fail closed while a conversation is in Trash."""
    if not user:
        return {}
    try:
        owner_user_id = int(user["id"])
    except (KeyError, TypeError, ValueError):
        return {}
    with _db() as conn:
        rows = conn.execute(
            """
            SELECT c.id, c.owner_user_id, c.title, c.ts, c.mode, c.chat_intent, c.project_id,
                   c.archived, c.archived_ts, c.deleted_ts, c.deleted_nonce,
                   (SELECT MAX(m.ts) FROM messages m WHERE m.chat_id=c.id) AS last_ts
            FROM chats c
            WHERE c.owner_user_id=? AND c.deleted_ts IS NOT NULL AND c.id>0
            ORDER BY c.deleted_ts DESC, c.id DESC
            """,
            (owner_user_id,),
        ).fetchall()
    trash = {}
    for row in rows:
        item = {
            "owner_user_id": int(row["owner_user_id"]),
            "title": row["title"],
            "ts": int(row["ts"] or 0),
            "mode": _normalize_chat_mode(row["mode"]),
            "chat_intent": _normalize_chat_intent(row["chat_intent"]),
            "project_id": row["project_id"],
            "archived": bool(row["archived"]),
            "deleted_ts": int(row["deleted_ts"]),
            "delete_receipt": row["deleted_nonce"] or "",
        }
        if row["archived_ts"]:
            item["archived_ts"] = int(row["archived_ts"])
        if row["last_ts"]:
            item["last_ts"] = int(row["last_ts"])
        trash[str(row["id"])] = item
    return trash


def _require_chat_access(request: Request, cid: int) -> Optional[JSONResponse]:
    """404 (not 403) when a chat is missing OR owned by another user — never
    reveal that someone else's resource exists. Trash rows are deliberately
    absent from the live index and therefore fail closed on every ordinary chat
    route; Restore/Permanent Delete use their own owner-qualified SQL."""
    _refresh_index_from_storage()
    if (
        str(cid) not in (CHAT_INDEX.get("chats") or {})
        or not _chat_belongs_to_user(cid, _current_user(request))
    ):
        return JSONResponse({"error": "chat not found"}, status_code=404)
    return None


def _set_user_agents(user_id: int, agent_ids: list) -> list:
    now_ms = int(time.time() * 1000)
    valid = [aid for aid in agent_ids if aid in AGENTS_BY_ID]
    with _db() as conn:
        conn.execute("DELETE FROM user_agents WHERE user_id=?", (int(user_id),))
        for aid in valid:
            conn.execute(
                "INSERT OR IGNORE INTO user_agents(user_id, agent_id, created_ts) VALUES (?, ?, ?)",
                (int(user_id), aid, now_ms),
            )
    return valid


def _list_users() -> list:
    with _db() as conn:
        rows = conn.execute(
            "SELECT id, email, username, display_name, preferred_name, role, is_active, created_ts "
            "FROM users ORDER BY role='admin' DESC, email"
        ).fetchall()
        grants = conn.execute(
            "SELECT user_id, agent_id FROM user_agents ORDER BY agent_id"
        ).fetchall()
    by_user: dict = {}
    for g in grants:
        if g["agent_id"] in AGENTS_BY_ID:
            by_user.setdefault(int(g["user_id"]), []).append(g["agent_id"])
    return [{
        "id": int(r["id"]), "email": r["email"], "username": r["username"],
        "display_name": r["display_name"],
        "preferred_name": _clean_user_name(r["preferred_name"], r["display_name"], 80),
        "role": r["role"], "is_active": bool(r["is_active"]), "created_ts": r["created_ts"],
        "agents": by_user.get(int(r["id"]), []),
    } for r in rows]


def _access_token_from_request(request: Request) -> str:
    auth = request.headers.get("authorization", "")
    if auth.lower().startswith("bearer "):
        return auth.split(" ", 1)[1].strip()
    return (
        request.headers.get("x-orchestrator-token", "")
        or request.cookies.get("orchestrator_token", "")
    ).strip()


def _require_auth(request: Request) -> Optional[JSONResponse]:
    if _current_user(request):
        return None
    return JSONResponse({"error": "unauthorized"}, status_code=401)


def _parse_cid_param(cid: str) -> Optional[int]:
    """Strictly parse a chat-id query param, or None. isdigit() alone is a trap:
    it accepts Unicode digits ('²', '①') that int() rejects, and no length cap
    means a multi-KB numeral could hit int-str limits — both would raise on the
    auth middleware path instead of failing closed."""
    cid = (cid or "").strip()
    if not (cid.isascii() and cid.isdigit() and 0 < len(cid) <= 12):
        return None
    try:
        return int(cid)
    except ValueError:
        return None


# Per-AGENT belt tools carry ?cid=&agent=&k= (an agent-bound token) instead of the
# shared per-chat ?cid=&k=. Reads are GET; mutations (send an email, create a
# calendar event) are POST with a JSON body — never a URL query string, since the
# body carries personal content. The map fixes each path's allowed method so a
# mutation can't be smuggled in as a GET.
_AGENT_TOOL_METHODS = {
    "/api/tools/email/search": "GET",
    "/api/tools/email/send": "POST",
    "/api/tools/email/draft": "POST",
    "/api/tools/calendar/agent": "GET",
    "/api/tools/calendar/agent/event": "POST",
    "/api/tools/calendar/agent/delete": "POST",
    "/api/tools/contacts/agent": "GET",
}
def _signed_web_tool_request_ok(request: Request) -> bool:
    """True when this is a request to a shared/per-agent tool endpoint carrying a
    valid token minted into agents' prompts by build_prompt. Lets chat-participant
    agents use tools without a user session — same trust model as signed attachment
    URLs; the endpoint re-verifies and rate-limits."""
    path = request.url.path
    if not path.startswith("/api/tools/"):
        return False
    cid = _parse_cid_param(request.query_params.get("cid", ""))
    token = (request.query_params.get("k") or "").strip()
    if cid is None or not token:
        return False
    # Per-AGENT tools: the token binds to a specific agent id so access can't leak
    # between agents, and the method must match the map (GET read / POST mutate).
    want_method = _AGENT_TOOL_METHODS.get(path)
    if want_method is not None:
        if request.method != want_method:
            return False
        agent_id = (request.query_params.get("agent") or "").strip()
        return bool(agent_id) and _email_tool_token_ok(cid, agent_id, token)
    # The Telegram pager accepts POST too (longer JSON bodies), not just GET, so
    # belt agents on the web token can page with multi-line notes. It re-verifies
    # and rate-limits in the handler like every other shared tool.
    if path == "/api/tools/telegram/send":
        return _live_web_tool_token_ok(cid, token)
    if request.method != "GET":
        return False
    return _live_web_tool_token_ok(cid, token)


def _signed_attachment_request_ok(request: Request) -> bool:
    """True when this is a read of an attachment carrying a valid per-file ?k=
    token. Lets chat-participant agents fetch attachments without a user session,
    bypassing the global auth gate for that one file only. Path shapes:
    /attachments/{cid}/{file_id} and /attachments/{cid}/{file_id}/text."""
    if request.method not in ("GET", "HEAD"):
        return False
    path = request.url.path
    if not path.startswith("/attachments/"):
        return False
    token = request.query_params.get("k", "")
    if not token:
        return False
    parts = path.split("/")  # ['', 'attachments', cid, file_id, ('text')?]
    if len(parts) < 4:
        return False
    try:
        cid = int(parts[2])
    except ValueError:
        return False
    return _live_attachment_token_ok(cid, parts[3], token)


def _require_admin(request: Request) -> Optional[JSONResponse]:
    if _is_admin_user(_current_user(request)):
        return None
    return JSONResponse({"error": "admin token required"}, status_code=401)


def _request_body_limit(request: Request) -> int:
    path = request.url.path
    content_type = request.headers.get("content-type", "").lower()
    if path == "/api/send":
        return MAX_MESSAGE_BYTES
    if path == "/api/voice/speech":
        return 32 * 1024
    if path == "/api/chat_bridge/attachment_save":
        # Compatibility endpoint: base64 expands bytes by 4/3. New upload paths
        # should use multipart UploadFile instead of increasing this allowance.
        return ((CHAT_BRIDGE_ATTACHMENT_MAX_BYTES + 2) // 3) * 4 + 64 * 1024
    if path == "/api/skills/import":
        return 8 * 1024 * 1024
    if path.startswith("/preview/"):
        return 16 * 1024 * 1024
    if content_type.startswith("multipart/form-data"):
        return MAX_UPLOAD_BYTES + 4 * 1024 * 1024
    return MAX_API_BODY_BYTES


def _body_limit_response(request: Request, message: str, status_code: int) -> Response:
    response = JSONResponse({"error": message}, status_code=status_code)
    response.headers["X-Request-ID"] = request.state.request_id
    if status_code in (400, 411, 413):
        # The oversized stream is intentionally not drained; prevent a keep-alive
        # connection from interpreting its unread bytes as the next request.
        response.headers["Connection"] = "close"
    return _security_headers(response)


async def _enforce_request_body_limit(request: Request) -> Optional[Response]:
    if request.method not in ("POST", "PUT", "PATCH", "DELETE"):
        return None
    path = request.url.path
    if not (path.startswith("/api/") or path.startswith("/preview/")):
        return None
    body_limit = _request_body_limit(request)
    content_type = request.headers.get("content-type", "").lower()
    content_lengths = request.headers.getlist("content-length")
    transfer_encoding = request.headers.get("transfer-encoding", "").strip()
    if content_lengths and transfer_encoding:
        return _body_limit_response(
            request, "content-length and transfer-encoding may not be combined", 400,
        )
    if len(content_lengths) > 1:
        return _body_limit_response(request, "duplicate content-length", 400)
    if content_lengths:
        raw_length = content_lengths[0].strip()
        if not raw_length.isascii() or not raw_length.isdigit():
            return _body_limit_response(request, "invalid content-length", 400)
        declared_length = int(raw_length)
        if declared_length > body_limit:
            return _body_limit_response(
                request, f"request body exceeds {body_limit} bytes", 413,
            )
    # Preserve FastAPI's streaming multipart/UploadFile path only when the total
    # size is declared and bounded. Starlette otherwise parses a chunked multipart
    # body before endpoint-level file checks, which makes a missing Content-Length
    # an unbounded memory/disk ingress path.
    if content_type.startswith("multipart/form-data"):
        if not content_lengths:
            return _body_limit_response(
                request, "content-length is required for multipart uploads", 411,
            )
        return None
    chunks: list[bytes] = []
    received = 0
    try:
        async for chunk in request.stream():
            received += len(chunk)
            if received > body_limit:
                return _body_limit_response(
                    request, f"request body exceeds {body_limit} bytes", 413,
                )
            chunks.append(chunk)
    except ClientDisconnect:
        return _body_limit_response(request, "request body disconnected", 400)
    request._body = b"".join(chunks)
    return None


def _chat_bridge_header_authenticated(request: Request) -> bool:
    """Authenticate bridge credentials before any request body is buffered."""
    path = request.url.path
    if path == "/api/chat_bridge/attachment_save":
        return _agent_from_token(request.headers.get("x-api-key", "")) is not None
    if path == "/api/chat_bridge/message":
        return _alert_actor_from_request(request) is not None
    return False


@app.middleware("http")
async def hardening_middleware(request: Request, call_next):
    request.state.request_id = uuid.uuid4().hex[:12]
    start = time.perf_counter()
    bridge_path = request.url.path.startswith("/api/chat_bridge/")
    community_pairing_callback = request.url.path == "/api/community/agents/self-connect"
    signed_web_tool = _signed_web_tool_request_ok(request)
    # Host pin, applied to exactly the requests that carry their own credential
    # in the URL and therefore skip BOTH _require_auth and _require_origin. Those
    # are the only ones DNS rebinding can reach: a page on attacker.example that
    # rebinds to 127.0.0.1 gets no session cookie (it was set on the app's real
    # host), but a signed ?cid=&k= URL needs no cookie at all. Without this, a
    # a blind cross-origin fetch could trigger an authenticated read.
    if (signed_web_tool or _signed_attachment_request_ok(request)) and not host_allowed(
        request.headers.get("host", "")
    ):
        blocked = JSONResponse({"error": "bad host"}, status_code=400)
        blocked.headers["X-Request-ID"] = request.state.request_id
        _audit_event(
            request,
            "host.failure",
            actor="anonymous",
            status="blocked",
            meta={"host": (request.headers.get("host", "") or "")[:120]},
        )
        logger.warning(
            "request_id=%s rejected host=%s path=%s client=%s",
            request.state.request_id,
            (request.headers.get("host", "") or "")[:120],
            request.url.path,
            request.client.host if request.client else "-",
        )
        return _security_headers(blocked)
    if bridge_path and not _chat_bridge_header_authenticated(request):
        blocked = JSONResponse({"error": "unauthorized"}, status_code=401)
        blocked.headers["X-Request-ID"] = request.state.request_id
        _audit_event(
            request,
            "auth.failure",
            actor="anonymous",
            status="blocked",
            meta={"reason": "bad_or_missing_bridge_token"},
        )
        logger.warning(
            "request_id=%s unauthorized bridge method=%s path=%s client=%s",
            request.state.request_id,
            request.method,
            request.url.path,
            request.client.host if request.client else "-",
        )
        return _security_headers(blocked)
    if (
        request.url.path.startswith(("/api/", "/attachments/", "/artifacts/"))
        # /auth/logout: the client idle-logout beacon fires from just-expired
        # sessions — a 401 here leaves the dead cookie in place. /push/latest:
        # service workers poll it without a session cookie; the handler already
        # degrades anonymous callers to a contentless fallback payload.
        and request.url.path not in (
            "/api/auth/session", "/api/auth/logout", "/api/auth/setup/status",
            "/api/auth/setup", "/api/push/latest",
        )
        and not bridge_path
        and not community_pairing_callback
        and not _signed_attachment_request_ok(request)
        and not signed_web_tool
    ):
        blocked = _require_auth(request)
        if blocked:
            blocked.headers["X-Request-ID"] = request.state.request_id
            _audit_event(
                request,
                "auth.failure",
                actor="anonymous",
                status="blocked",
                meta={"reason": "bad_or_missing_token"},
            )
            logger.warning(
                "request_id=%s unauthorized method=%s path=%s client=%s",
                request.state.request_id,
                request.method,
                request.url.path,
                request.client.host if request.client else "-",
            )
            return _security_headers(blocked)
    # Enforce the same CSRF boundary for every API mutation instead of relying
    # on each handler to remember it. Agent belt tools and bridge
    # callbacks authenticate with narrow capabilities and do not originate in a
    # browser, while login/logout/activity must remain usable when a client has
    # no established page origin yet.
    if (
        request.method in ("POST", "PUT", "PATCH", "DELETE")
        and request.url.path.startswith("/api/")
        and request.url.path not in (
            "/api/auth/session", "/api/auth/logout", "/api/auth/activity",
        )
        and not bridge_path
        and not community_pairing_callback
        and not signed_web_tool
    ):
        blocked = _require_origin(request)
        if blocked:
            blocked.headers["X-Request-ID"] = request.state.request_id
            _audit_event(
                request,
                "origin.failure",
                actor=(_current_user(request) or {}).get("email") or "anonymous",
                status="blocked",
            )
            return _security_headers(blocked)
    body_blocked = await _enforce_request_body_limit(request)
    if body_blocked is not None:
        return body_blocked
    response = await call_next(request)
    response.headers["X-Request-ID"] = request.state.request_id
    elapsed_ms = (time.perf_counter() - start) * 1000
    logger.info(
        "request_id=%s method=%s path=%s status=%s elapsed_ms=%.1f client=%s",
        request.state.request_id,
        request.method,
        request.url.path,
        response.status_code,
        elapsed_ms,
        request.client.host if request.client else "-",
    )
    return _security_headers(response)


# Browser reconnects and resumed tabs can all wake their periodic reads at once.
# Those reads are disposable snapshots: admitting an unbounded pile only delays
# the newest snapshot and can starve real sends plus the liveness endpoint. Shed
# only these idempotent background surfaces when the app is already busy; never
# reject mutations, bridge callbacks, downloads, or the chat stream here.
_BACKGROUND_POLL_PATHS = frozenset({
    "/api/chats",
    "/api/projects",
    "/api/agents/health",
    "/api/agents/models",
    "/api/capabilities",
    "/api/orchestrator",
    "/api/notifications",
    "/api/brief",
    "/api/tasks",
    "/api/automation-items",
    "/api/decisions",
    "/api/orchestrator/recommendations",
    "/api/settings/setup-status",
    "/api/tools/calendar/upcoming",
    "/api/coding_jobs",
})
_HTTP_INFLIGHT = 0
_HTTP_POLL_INFLIGHT_LIMIT = max(8, int(os.environ.get("HTTP_POLL_INFLIGHT_LIMIT", "24")))


def _is_background_poll_request(request: Request) -> bool:
    return request.method == "GET" and request.url.path in _BACKGROUND_POLL_PATHS


@app.middleware("http")
async def background_poll_load_shedding_middleware(request: Request, call_next):
    global _HTTP_INFLIGHT
    if _is_background_poll_request(request) and _HTTP_INFLIGHT >= _HTTP_POLL_INFLIGHT_LIMIT:
        response = _security_headers(JSONResponse(
            {"error": "busy", "retryable": True},
            status_code=503,
            headers={"Retry-After": "2"},
        ))
        # This middleware is the outer admission gate, so rejected requests do
        # not reach hardening_middleware where request IDs are normally added.
        response.headers["X-Request-ID"] = uuid.uuid4().hex[:12]
        return response
    _HTTP_INFLIGHT += 1
    try:
        return await call_next(request)
    finally:
        _HTTP_INFLIGHT = max(0, _HTTP_INFLIGHT - 1)


@app.post("/api/chats/{cid}/switch")
async def api_switch_chat(cid: int, request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    _refresh_index_from_storage()
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    if str(cid) not in CHAT_INDEX["chats"]:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    _set_active_chat_for_request(request, cid)
    return {
        "status": "ok",
        "chat_id": cid,
        "device_id": _device_id_from_request(request),
    }

# --- Chat Atlas: a month of chats seen four ways (workstreams / calendar /
# agent activity / follow-up constellation). Reads are owner-scoped; Atlas v2
# aggregates real per-day message activity, reuses Projects as durable
# workstreams, and stores continuation edges in chats.parent_chat_id. The title
# regex remains only as a compatibility fallback for pre-v2 handoffs.
_ATLAS_CONT_RE = re.compile(r"cont\. from #(\d+)", re.I)
_ATLAS_ID_PREFIX_RE = re.compile(r"^\s*#?\d+\s*[–—:\-]\s*")
_ATLAS_TOPIC_KW = [
    ("ppc", ["ppc", "google ads", "adwords", "ad account", "campaign", "ad /", "climate ad"]),
    ("markets", ["portfolio", "brokerage", "stock", "position", "market", "trade",
                 "rebalance", "hype", "trump-signal", "trump signal", "invest",
                 "ticker", "equit", "option", "dividend"]),
    ("email", ["email", "inbox", "radar", "daily brief", "gmail", "newsletter", "reply to"]),
    ("ops", ["sales tax", "franchise tax", " tax", "backup", "baikal", "baïkal",
             "disk", "invoice", "quickbooks", "payroll", "comptroller", "webfile"]),
    ("app", ["ship it", "v7.", "v7 ", "the app", "build", "bug", "fix ", "ui ",
             "panel", "deploy", "stability", "foreman", "secret", "mailbox",
             "canvas", "endpoint", "css", "commit", "release", "audit",
             "refactor", "migrat", "launchd", "schema"]),
]
_ATLAS_AGENT_TOPIC = {
    "sales": "markets", "sales-agent": "markets",
    "hermes": "email", "ops-agent": "email", "support-agent": "email",
    "lead": "ops", "lead-agent": "ops",
    "codex": "app", "claude": "app", "antigravity": "app", "minimax": "app",
    "grok": "asks", "gpt": "asks",
}


def _atlas_clean_title(title: str, cid: int) -> str:
    """Strip the leading '#<id> – ' marker so cards read as topics, not numbers."""
    t = (title or "").strip()
    t = _ATLAS_ID_PREFIX_RE.sub("", t).strip()
    return t or (title or f"#{cid}")


def _atlas_topic_for(title, targets, participants) -> str:
    low = (title or "").lower()
    for topic, kws in _ATLAS_TOPIC_KW:
        for kw in kws:
            if kw in low:
                return topic
    for a in list(participants or []) + list(targets or []):
        if a in _ATLAS_AGENT_TOPIC:
            return _ATLAS_AGENT_TOPIC[a]
    return "asks"


@app.get("/atlas", response_class=HTMLResponse)
async def atlas_page(request: Request):
    """Serve the self-contained Atlas viewer (loaded in an iframe by the app).
    Carries no user data itself — it fetches owner-scoped data from /api/atlas."""
    response = templates.TemplateResponse(request, "atlas.html")
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    # Atlas loads inside the app's own iframe. The global hardening middleware
    # otherwise sets CSP `frame-ancestors 'none'` (+ X-Frame-Options: DENY) via
    # setdefault, which blocks the frame with "<host> refused to connect".
    # Pre-setting our own headers wins over the setdefault — same pattern the
    # inline PDF/artifact preview uses. Mirrors the global CSP but allows a
    # same-origin frame; the page is our own trusted template (no user content).
    response.headers["X-Frame-Options"] = "SAMEORIGIN"
    response.headers["Content-Security-Policy"] = (
        "default-src 'self'; script-src 'self' 'unsafe-inline'; "
        "style-src 'self' 'unsafe-inline'; font-src 'self'; "
        "img-src 'self' data: blob:; connect-src 'self'; "
        "media-src 'self' blob:; object-src 'none'; base-uri 'self'; "
        "frame-ancestors 'self'"
    )
    return response


@app.get("/api/atlas")
async def api_atlas(request: Request, days: int = 30):
    guard = _require_auth(request)
    if guard:
        return guard
    _refresh_index_from_storage()
    user = _current_user(request)
    try:
        days = max(1, min(int(days), 365))
    except Exception:
        days = 30
    chats = _chat_index_for_user(user)["chats"]
    now_ms = int(time.time() * 1000)
    cutoff = now_ms - days * 86400 * 1000
    cids = [int(c) for c in chats.keys()]
    last_by: dict = {}
    parts_by: dict = {}
    message_counts: dict = {}
    activity_by_chat: dict = {}
    activity_days: dict = {}
    if cids:
        try:
            with _db() as conn:
                for i in range(0, len(cids), 400):
                    chunk = cids[i:i + 400]
                    ph = ",".join("?" * len(chunk))
                    for r in conn.execute(
                        f"SELECT chat_id, MAX(ts) AS lts FROM messages "
                        f"WHERE chat_id IN ({ph}) GROUP BY chat_id", chunk
                    ).fetchall():
                        last_by[int(r["chat_id"])] = int(r["lts"] or 0)
                    for r in conn.execute(
                        f"SELECT chat_id, role, agent_id, ts FROM messages "
                        f"WHERE ts>=? AND chat_id IN ({ph}) ORDER BY ts ASC, id ASC",
                        [cutoff, *chunk],
                    ).fetchall():
                        chat_id = int(r["chat_id"])
                        ts = int(r["ts"] or 0)
                        day = time.strftime("%Y-%m-%d", time.localtime(ts / 1000))
                        message_counts[chat_id] = message_counts.get(chat_id, 0) + 1
                        per_chat = activity_by_chat.setdefault(chat_id, {})
                        chat_day = per_chat.setdefault(day, {"messages": 0, "agents": {}})
                        chat_day["messages"] += 1
                        per_day = activity_days.setdefault(day, {
                            "messages": 0, "chats": set(), "agents": {},
                        })
                        per_day["messages"] += 1
                        per_day["chats"].add(chat_id)
                        agent_id = r["agent_id"]
                        if r["role"] == "agent" and agent_id:
                            agent_id = str(agent_id)
                            parts = parts_by.setdefault(chat_id, {})
                            parts[agent_id] = parts.get(agent_id, 0) + 1
                            chat_agents = chat_day["agents"]
                            chat_agents[agent_id] = chat_agents.get(agent_id, 0) + 1
                            agents = per_day["agents"]
                            agents[agent_id] = agents.get(agent_id, 0) + 1
        except Exception:
            logger.exception("atlas message aggregation failed")
    items = []
    for cid_s, ch in chats.items():
        try:
            cid = int(cid_s)
        except (TypeError, ValueError):
            continue
        created = int(ch.get("ts") or 0)
        last = last_by.get(cid) or created
        if last < cutoff:
            continue
        parts = parts_by.get(cid, {})
        participants = sorted(parts.keys(), key=lambda a: -parts[a])
        raw_title = ch.get("title") or f"#{cid}"
        m = _ATLAS_CONT_RE.search(raw_title)
        targets = [t for t in (ch.get("targets") or []) if isinstance(t, str)]
        parent_id = ch.get("parent_chat_id")
        try:
            parent_id = int(parent_id) if parent_id else (int(m.group(1)) if m else None)
        except (TypeError, ValueError):
            parent_id = None
        items.append({
            "id": cid,
            "title": _atlas_clean_title(raw_title, cid),
            "mode": ch.get("mode") or "",
            "project_id": ch.get("project_id"),
            "archived": bool(ch.get("archived")),
            "created_ts": created,
            "last_ts": last,
            "turns": sum(parts.values()),
            "message_count": int(message_counts.get(cid, 0)),
            "activity": [
                {
                    "date": day,
                    "messages": int(data["messages"]),
                    "agents": data["agents"],
                }
                for day, data in sorted(activity_by_chat.get(cid, {}).items())
            ],
            "participants": participants,
            "targets": targets,
            "parent_id": parent_id,
            "topic": _atlas_topic_for(raw_title, targets, participants),
        })
    present = set()
    for it in items:
        present.update(it["participants"])
        present.update(it["targets"])
    agents = {}
    for aid in present:
        a = AGENTS_BY_ID.get(aid)
        agents[aid] = {
            "name": (a.get("name") if a else None) or aid,
            "color": (a.get("color") if a else "") or "",
            "emoji": (a.get("emoji") if a else "") or "",
        }
    project_rows = _list_projects(user)
    projects = {str(int(p["id"])): p["title"] for p in project_rows}
    project_list = [
        {
            "id": int(p["id"]),
            "title": p["title"],
            "status": p.get("status") or "active",
            "chat_count": int(p.get("chat_count") or 0),
        }
        for p in project_rows
    ]
    days_out = [
        {
            "date": day,
            "messages": int(data["messages"]),
            "chats": len(data["chats"]),
            "agents": data["agents"],
        }
        for day, data in sorted(activity_days.items())
    ]
    return {
        "days": days,
        "now": now_ms,
        "chats": items,
        "agents": agents,
        "projects": projects,
        "project_list": project_list,
        "activity_days": days_out,
    }


@app.post("/api/chats/{cid}/parent")
async def api_link_chat_parent(cid: int, request: Request):
    """Set or clear a durable Atlas continuation edge between two owned chats."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_chat_access(request, cid)
    if blocked:
        return blocked
    if _track_current_chat_task(cid) is None:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    body = await request.json()
    parent_id = body.get("parent_id")
    if parent_id in (None, "", 0, "0"):
        parent_id = None
    else:
        try:
            parent_id = int(parent_id)
        except (TypeError, ValueError):
            return JSONResponse({"error": "invalid parent chat"}, status_code=400)
        if parent_id == cid:
            return JSONResponse({"error": "a chat cannot continue from itself"}, status_code=400)
        blocked = _require_chat_access(request, parent_id)
        if blocked:
            return blocked
    CHAT_INDEX["chats"][str(cid)]["parent_chat_id"] = parent_id
    _save_index()
    await broadcast({
        "type": "chat_meta",
        "chat_id": cid,
        "parent_chat_id": parent_id,
    }, global_event=True)
    return {"status": "ok", "chat_id": cid, "parent_id": parent_id}


def _chat_directory_etag(request: Request, user: Optional[dict], active_id: int) -> str:
    """Cheap semantic version for the chat-directory representation.

    The full directory is large because it includes archived metadata. Background
    clients send this tag back, allowing the overwhelmingly common unchanged poll
    to finish before owner filtering, unread aggregation, badge queries, JSON
    encoding, gzip, transfer, parsing, or DOM work.
    """
    try:
        with _db() as conn:
            chat_rev = _chats_rev(conn)
            # MAX(rowid) uses SQLite's integer-primary-key fast path; unlike
            # MAX(ts), it cannot turn an unchanged poll into a messages scan.
            message_id = int(conn.execute(
                "SELECT COALESCE(MAX(id), 0) FROM messages"
            ).fetchone()[0])
            schedule_state = tuple(tuple(row) for row in conn.execute(
                "SELECT id, series_chat_id, enabled, last_run_ts, next_run_ts, last_status "
                "FROM skill_schedules ORDER BY id"
            ).fetchall())
            handoff_state = tuple(tuple(row) for row in conn.execute(
                "SELECT chat_id, status, decided, carried_forward, updated_ts "
                "FROM room_handoffs "
                "WHERE status='kept' OR decided!='' OR carried_forward!='' ORDER BY chat_id"
            ).fetchall())
            shelf_state = tuple(int(row[0]) for row in conn.execute(
                "SELECT DISTINCT chat_id FROM room_shelves WHERE status='paused' ORDER BY chat_id"
            ).fetchall())
    except sqlite3.Error:
        # Startup migrations normally guarantee these tables. If a partial/legacy
        # database is still converging, vary every response rather than risk stale UI.
        return '"chat-directory-uncacheable-%s"' % secrets.token_hex(8)

    running = []
    for info in list(RUNNING_TASKS.values()):
        task = info.get("task")
        if task is not None and task.done():
            continue
        running.append(str(info.get("chat_id") or ""))
    runtime = (
        tuple(sorted(running)),
        tuple(sorted(str(cid) for cid in PENDING_HOLDS)),
        tuple(sorted(str(cid) for cid in PENDING_INPUT_CARDS)),
    )
    semantic = (
        int((user or {}).get("id") or 0),
        _device_id_from_request(request),
        int(active_id),
        bool(_mission_control_enabled()),
        int(CHAT_TRASH_RETENTION_DAYS),
        int(chat_rev),
        message_id,
        schedule_state,
        handoff_state,
        shelf_state,
        runtime,
    )
    digest = hashlib.sha256(repr(semantic).encode("utf-8")).hexdigest()[:32]
    return f'"chat-directory-{digest}"'


@app.get("/api/chats")
async def api_chats(request: Request, response: Response):
    # Rev-gated: skips the full-table scan + per-row JSON parse of ALL tenants'
    # chats (which ran on every 20s poll of every tab) unless the chats/meta have
    # actually changed since the last rebuild. See _refresh_index_from_storage.
    _refresh_index_from_storage()
    user = _current_user(request)
    active_id = _active_chat_id_for_request(request)
    etag = _chat_directory_etag(request, user, active_id)
    cache_headers = {"ETag": etag, "Cache-Control": "private, no-cache"}
    if request.headers.get("if-none-match", "").strip() == etag:
        return Response(status_code=304, headers=cache_headers)
    response.headers.update(cache_headers)
    chats = _chat_index_for_user(user)["chats"]
    chats = {
        cid: ch for cid, ch in chats.items()
        if not _is_product_guide_chat(cid)
    }
    trash = {
        cid: ch for cid, ch in _trash_index_for_user(user).items()
        if not _is_product_guide_chat(cid)
    }
    # Mission Control: when enabled, an automation's series chat lives in the
    # Automations surface, not the chat list — so it stops getting lost among
    # conversations. Builds a filtered copy (never mutates the index); a no-op
    # when the flag is off, so the default chat list is unchanged.
    if _mission_control_enabled():
        try:
            with _db() as conn:
                series_ids = {
                    str(r["series_chat_id"]) for r in conn.execute(
                        "SELECT series_chat_id FROM skill_schedules "
                        "WHERE series_chat_id IS NOT NULL"
                    ).fetchall() if r["series_chat_id"]
                }
            if series_ids:
                chats = {cid: ch for cid, ch in chats.items()
                         if str(cid) not in series_ids}
        except Exception:
            logger.exception("mission-control chat-list filter failed")
    # Enrich each chat with its last message ts so the client can flag unread
    # threads. Derived from the messages table (no mutation of the index). Scoped
    # to THIS user's chats via the (chat_id, id) index instead of aggregating every
    # user's messages on each poll.
    try:
        chat_ids = [int(cid) for cid in chats.keys()]
        if chat_ids:
            placeholders = ",".join("?" * len(chat_ids))
            with _db() as conn:
                rows = conn.execute(
                    f"SELECT chat_id, MAX(ts) AS last_ts FROM messages "
                    f"WHERE chat_id IN ({placeholders}) GROUP BY chat_id",
                    chat_ids,
                ).fetchall()
            last_by = {str(r["chat_id"]): int(r["last_ts"] or 0) for r in rows}
            for cid, ch in chats.items():
                if last_by.get(str(cid)):
                    ch["last_ts"] = last_by[str(cid)]
    except Exception:
        logger.exception("chat last_ts enrichment failed")
    # An automation's series chat is minted once and reused for every run, so its
    # creation date is meaningless months later. Hand the client the schedule's
    # run state and let the row report when it last ran instead of how old it is.
    # A no-op when Mission Control is on (series chats were filtered out above).
    try:
        with _db() as conn:
            sched_rows = conn.execute(
                "SELECT series_chat_id, enabled, last_run_ts, next_run_ts, last_status "
                "FROM skill_schedules WHERE series_chat_id IS NOT NULL"
            ).fetchall()
        for r in sched_rows:
            ch = chats.get(str(r["series_chat_id"]))
            if ch is None:
                continue
            ch["automation"] = {
                "enabled": bool(r["enabled"]),
                "last_run_ts": int(r["last_run_ts"] or 0),
                "next_run_ts": int(r["next_run_ts"] or 0),
                "last_status": r["last_status"] or "",
            }
    except Exception:
        logger.exception("chat automation enrichment failed")
    # SIGNAL state layer: per-chat workflow summary so the thread list can show
    # cross-room "working" / "needs you" badges. Reads only the in-memory
    # RUNNING_TASKS / PENDING_HOLDS dicts — no extra DB work, and a failure here
    # must never break the chat listing.
    try:
        working_by: dict[str, int] = {}
        for _tid, info in list(RUNNING_TASKS.items()):
            task = info.get("task")
            if task is not None and task.done():
                continue
            wcid = str(info.get("chat_id"))
            working_by[wcid] = working_by.get(wcid, 0) + 1
        for cid, ch in chats.items():
            w = working_by.get(str(cid), 0)
            if w:
                ch["working"] = w
            try:
                icid = int(cid)
                if PENDING_HOLDS.get(icid) or icid in PENDING_INPUT_CARDS:
                    ch["needs_you"] = True
            except (TypeError, ValueError):
                pass
    except Exception:
        logger.exception("chat state-badge enrichment failed")
    try:
        ids = []
        for cid in chats.keys():
            try:
                ids.append(int(cid))
            except (TypeError, ValueError):
                pass
        if ids:
            placeholders = ",".join("?" * len(ids))
            with _db() as conn:
                _room_conn_schema(conn)
                notes = {
                    int(r["chat_id"]): r["status"]
                    for r in conn.execute(
                        f"SELECT chat_id, status FROM room_handoffs WHERE chat_id IN ({placeholders}) "
                        f"AND (status='kept' OR decided!='' OR carried_forward!='')",
                        ids,
                    ).fetchall()
                }
                paused = {
                    int(r["chat_id"]) for r in conn.execute(
                        f"SELECT DISTINCT chat_id FROM room_shelves WHERE chat_id IN ({placeholders}) "
                        f"AND status='paused'",
                        ids,
                    ).fetchall()
                }
            for cid, ch in chats.items():
                try:
                    icid = int(cid)
                except (TypeError, ValueError):
                    continue
                marks = []
                if icid in notes:
                    marks.append("Kept note" if notes[icid] == "kept" else "Note")
                if icid in paused:
                    marks.append("Paused")
                if marks:
                    ch["room_badges"] = marks
    except Exception:
        logger.exception("room badge enrichment failed")
    return {
        "active_id": active_id,
        "device_id": _device_id_from_request(request),
        "chats": chats,
        "trash": trash,
        "trash_count": len(trash),
        "trash_retention_days": CHAT_TRASH_RETENTION_DAYS,
    }


@app.get("/api/threads/search")
async def api_threads_search(request: Request):
    """Premium thread search: matches BOTH chat titles and message content across
    all of the user's conversations — archived included — and returns a snippet
    for each content hit so a thread is findable by what was said inside it."""
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "auth required"}, status_code=401)
    q = (request.query_params.get("q") or "").strip()
    if not q:
        return {"query": "", "results": []}
    if len(q) > 200:
        return JSONResponse({"error": "query too long (max 200 characters)"}, status_code=400)
    try:
        limit = max(1, min(int(request.query_params.get("limit") or 30), 60))
    except Exception:
        limit = 30
    _refresh_index_from_storage()
    chats = _chat_index_for_user(user)["chats"]  # cid_str -> chat dict (this user only)
    chats = {cid: ch for cid, ch in chats.items() if not _is_product_guide_chat(cid)}
    if not chats:
        return {"query": q, "results": []}
    ql = q.lower()
    title_hits = {cid for cid, ch in chats.items()
                  if ql in str(ch.get("title") or "").lower()}
    # Content matches: one bounded, case-insensitive scan of the messages table,
    # newest-first, constrained to this user's chats (no cross-user leakage).
    body_snip: dict[str, dict] = {}
    body_count: dict[str, int] = {}
    def _content_hits(cid_ints: list[int], needle: str) -> list[dict]:
        hits: list[dict] = []
        with _db() as conn:
            for i in range(0, len(cid_ints), 400):  # stay under SQLite's variable cap
                chunk = cid_ints[i:i + 400]
                ph = ",".join("?" * len(chunk))
                rows = conn.execute(
                    f"""
                    SELECT chat_id, text, ts, match_count
                    FROM (
                      SELECT chat_id, text, ts,
                             COUNT(*) OVER (PARTITION BY chat_id) AS match_count,
                             ROW_NUMBER() OVER (
                               PARTITION BY chat_id ORDER BY ts DESC, id DESC
                             ) AS match_rank
                      FROM messages
                      WHERE chat_id IN ({ph}) AND instr(lower(text), ?) > 0
                        AND (json_valid(metadata_json)=0 OR
                             COALESCE(json_extract(metadata_json, '$.sensor_id'), '') != 'memory_gap')
                        AND (json_valid(metadata_json)=0 OR
                             COALESCE(json_extract(metadata_json, '$.kind'), '') NOT IN
                             ('onboarding_first_ask', 'onboarding_control',
                              'onboarding_guide_internal'))
                        AND NOT (
                          (role='system' AND text LIKE '[Trusted onboarding desktop setup]%')
                          OR (
                            role='user' AND (
                              text LIKE 'Agents Chat just completed the real desktop-agent connection pass.%'
                              OR (
                                text LIKE 'I returned from the secure agent setup surface.%'
                                AND text LIKE '%Never ask me to paste a password, API key, token, or recovery code into chat.'
                              )
                              OR (
                                (text LIKE '% is now ready according to Agents Chat.%'
                                 OR text LIKE '% is not ready yet according to Agents Chat.%')
                                AND text LIKE '%Never ask me to paste a password, API key, token, or recovery code into chat.'
                              )
                            )
                          )
                        )
                    )
                    WHERE match_rank=1
                    """,
                    (*chunk, needle),
                ).fetchall()
                hits.extend(_row_dict(row) for row in rows)
        return hits

    try:
        cid_ints = [int(c) for c in chats.keys()]
        rows = await asyncio.to_thread(_content_hits, cid_ints, ql)
        for r in rows:
            c = str(r["chat_id"])
            body_count[c] = int(r.get("match_count") or 0)
            body_snip[c] = {"text": r.get("text") or "", "ts": int(r.get("ts") or 0)}
    except Exception:
        logger.exception("thread search content scan failed")

    results = []
    for cid in (set(title_hits) | set(body_snip.keys())):
        ch = chats.get(cid) or {}
        results.append({
            "chat_id": int(cid),
            "title": ch.get("title") or f"#{cid}",
            "project_id": ch.get("project_id"),
            "archived": bool(ch.get("archived")),
            "in_title": cid in title_hits,
            "in_body": cid in body_snip,
            "matches": body_count.get(cid, 0),
            "snippet": _make_snippet(body_snip[cid]["text"], ql) if cid in body_snip else None,
            "ts": int((body_snip.get(cid, {}) or {}).get("ts") or ch.get("last_ts") or ch.get("ts") or 0),
        })
    # Title matches surface first, then the most-recently-matched conversations.
    results.sort(key=lambda r: (r["in_title"], r["ts"]), reverse=True)
    return {"query": q, "results": results[:limit]}


@app.post("/api/chats/new")
async def api_new_chat(request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        body = await _json_object_body(request, empty_ok=True)
        project_id = _parse_resource_id(
            body.get("project_id"), "project_id", allow_none=True,
        ) if "project_id" in body else None
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if project_id is not None and not _active_project_belongs_to_user(project_id, user):
        return JSONResponse({"error": "project not found"}, status_code=404)
    raw_intent = body.get("chat_intent", "chat")
    if not isinstance(raw_intent, str) or raw_intent.strip().lower() not in {"chat", "code"}:
        return JSONResponse(
            {"error": "chat_intent must be chat or code"}, status_code=400,
        )
    chat_intent = raw_intent.strip().lower()
    if chat_intent == "code":
        project = _project_row(project_id)
        workspace, workspace_error = _project_folder_for_user(project, user)
        if workspace_error or workspace is None:
            return JSONResponse({
                "error": workspace_error or "set up a coding workspace first",
            }, status_code=409)
    new_id = _create_chat_record(
        NEW_CHAT_TITLE,
        mode=NEW_CHAT_MODE,
        owner_user_id=int(user["id"]),
        project_id=project_id,
        chat_intent=chat_intent,
    )
    _set_active_chat_for_request(request, new_id)
    if project_id is not None:
        bound = _ensure_project_folder(_project_row(project_id), user)
        if bound:
            await broadcast({
                "type": "project_meta",
                "owner_user_id": int(user["id"]),
                "project": bound,
            }, global_event=True)
            await _rehome_project_member_chats(int(project_id))
    await broadcast({
        "type": "chat_meta",
        "owner_user_id": int(user["id"]),
        "chat_id": new_id,
        "title": NEW_CHAT_TITLE,
        "mode": NEW_CHAT_MODE,
        "chat_intent": chat_intent,
        "project_id": project_id,
        "ts": CHAT_INDEX["chats"][str(new_id)]["ts"],
    }, global_event=True)
    return {
        "status": "ok",
        "chat_id": new_id,
        "device_id": _device_id_from_request(request),
        "project_id": project_id,
        "chat_intent": chat_intent,
    }


async def _apply_chat_target_edit(
    cid: int,
    requested: list[str],
    *,
    allowed: Optional[set[str]] = None,
) -> dict:
    """Apply and broadcast one authoritative room-roster edit.

    Shared by the picker endpoint and the quick-change-then-Send fallback so
    controllers, background cards, and every signed-in device observe the same
    revisioned result.
    """
    allowed = allowed if allowed is not None else _allowed_agent_ids_for_chat(cid)
    requested = list(dict.fromkeys(
        target for target in requested
        if isinstance(target, str)
        and target in AGENTS_BY_ID
        and target in allowed
    ))
    _controllers, working, protected_by_token, protected = (
        _live_roster_protection(cid, allowed)
    )
    # The active dispatch is the one part of the process an edit cannot replace.
    # If a stale/second device tries to remove it, retain it at its previous room
    # position and tell every client which selection was protected.  Future/offline
    # participants remain freely removable.
    previous = _get_chat_targets(cid)
    valid = _merge_protected_targets(requested, protected, previous)
    valid = _save_chat_targets(cid, valid)
    roster_revision = _chat_target_revision(cid)
    active_runs = _replace_live_turn_rosters(
        cid, requested, protected_by_token,
    )
    active_background_jobs = {
        int(controller.background_job_id): controller.snapshot()
        for controller in (LIVE_TURN_ROSTERS.get(int(cid)) or {}).values()
        if controller.background_job_id
    }
    for job_id, job_targets in sorted(active_background_jobs.items()):
        await broadcast({
            "type": "bg_job",
            "phase": "roster",
            "job_id": job_id,
            "chat_id": int(cid),
            "agents": job_targets,
        }, global_event=True)
    await broadcast({
        "type": "chat_meta",
        "owner_user_id": _chat_owner_id(cid),
        "chat_id": int(cid),
        "targets": valid,
        "working": working,
        "protected": protected,
        "roster_revision": roster_revision,
        "roster_edit": True,
    }, global_event=True)
    return {
        "targets": valid,
        "working": working,
        "protected": protected,
        "roster_revision": roster_revision,
        "active_runs": active_runs,
    }


@app.post("/api/chats/{cid}/targets")
async def api_chat_targets(cid: int, request: Request):
    """Persist a room edit and apply it to future active-turn hand-offs.

    An agent already inside ``dispatch_to_agent`` is never cancelled.  Sequential
    runners consult the edited roster before choosing their next speaker; parallel
    runners finish the batch already started and then admit additions once.  The
    authoritative result is broadcast so another signed-in device cannot keep a
    stale composer roster.
    """
    blocked = _require_origin(request)
    if blocked: return blocked
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    try:
        body = await _json_object_body(request)
    except ValueError as exc:
        return JSONResponse({"error": str(exc)}, status_code=400)
    targets = body.get("targets") or []
    if not isinstance(targets, list):
        return JSONResponse({"error": "targets must be a list"}, status_code=400)
    result = await _apply_chat_target_edit(cid, targets)
    return {"status": "ok", **result}


@app.post("/api/chats/{cid}/search")
async def api_chat_search(cid: int, request: Request):
    """Keyword search over a chat's message history (Phase 2 retrieval). Returns
    the best-matching messages so a long chat stays searchable."""
    blocked = _require_origin(request)
    if blocked: return blocked
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    if str(cid) not in CHAT_INDEX["chats"]:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    try:
        body = await request.json()
    except Exception:
        body = {}
    query = str(body.get("query") or "").strip()
    if not query:
        return JSONResponse({"error": "query required"}, status_code=400)
    limit = max(1, min(int(body.get("limit") or 10), 50))
    results = _search_messages(cid, query, limit=limit)
    return {
        "chat_id": cid,
        "query": query,
        "results": [
            {
                "id": r.get("id"),
                "role": r.get("role"),
                "agent_id": r.get("agent_id"),
                "name": r.get("name"),
                "text": r.get("text"),
                "ts": r.get("ts"),
            }
            for r in results
        ],
    }


@app.post("/api/chats/{cid}/mode")
async def api_chat_mode(cid: int, request: Request):
    """Persist the collaboration mode for a chat."""
    blocked = _require_origin(request)
    if blocked: return blocked
    blocked = _require_chat_access(request, cid)
