@app.post("/api/projects/auto-group/{run_id}/cancel")
async def api_project_auto_group_cancel(run_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        rid = _parse_resource_id(run_id, "run_id")
    except ValueError as exc:
        return JSONResponse({"error": str(exc)}, status_code=400)
    row = _auto_group_run_row(rid, int(user["id"]))
    if not row:
        return JSONResponse({"error": "auto-group run not found"}, status_code=404)
    if row["status"] != "planning":
        return JSONResponse({"error": "auto-group run is not planning"}, status_code=409)
    task = AUTO_GROUP_TASKS.get(rid)
    if task and not task.done():
        task.cancel()
    else:
        with _db() as conn:
            conn.execute(
                "UPDATE project_auto_group_runs SET status='canceled', error='Canceled before any changes', updated_ts=? "
                "WHERE id=? AND owner_user_id=? AND status='planning'",
                (int(time.time() * 1000), rid, int(user["id"])),
            )
    _audit_event(request, "project.auto_group.cancel", actor=user.get("email") or "user", target=str(rid))
    return {"status": "canceling", "run_id": rid}


@app.post("/api/projects/auto-group/{run_id}/apply")
async def api_project_auto_group_apply(run_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        rid = _parse_resource_id(run_id, "run_id")
        body = await _json_object_body(request)
    except ValueError as exc:
        return JSONResponse({"error": str(exc)}, status_code=400)
    raw_ids = body.get("chat_ids")
    if not isinstance(raw_ids, list):
        return JSONResponse({"error": "chat_ids must be a list"}, status_code=400)
    try:
        chat_ids = [_parse_resource_id(value, f"chat_ids[{index}]") for index, value in enumerate(raw_ids)]
        applied = _apply_auto_group_plan(rid, int(user["id"]), chat_ids)
    except ValueError as exc:
        return JSONResponse({"error": str(exc)}, status_code=400)
    except KeyError as exc:
        return JSONResponse({"error": str(exc).strip("'")}, status_code=404)
    except RuntimeError as exc:
        return JSONResponse({"error": str(exc)}, status_code=409)
    grouped: dict[int, list[int]] = {}
    for assignment in applied["assignments"]:
        grouped.setdefault(int(assignment["after_project_id"]), []).append(int(assignment["chat_id"]))
    for project in applied["created_projects"]:
        await broadcast({
            "type": "project_meta", "owner_user_id": int(user["id"]),
            "project": project,
        }, global_event=True)
    for pid, chat_ids_for_project in grouped.items():
        await broadcast({
            "type": "project_assignment", "owner_user_id": int(user["id"]),
            "chat_ids": chat_ids_for_project, "project_id": pid,
        }, global_event=True)
        project = _project_row(pid)
        if project and project.get("folder"):
            await _rehome_project_member_chats(pid)
    archived_ids = [int(item["chat_id"]) for item in applied.get("archived_chats") or []]
    deleted_ids = [int(item["chat_id"]) for item in applied.get("deleted_chats") or []]
    switched_ids = set(archived_ids) | set(deleted_ids)
    switched_to = _switch_active_away_from_archived(
        request, switched_ids, owner_hint=int(user["id"]),
    ) if switched_ids else None
    active_id = _active_chat_id_for_request(request)
    for item in applied.get("archived_chats") or []:
        await broadcast({
            "type": "chat_meta", "owner_user_id": int(user["id"]),
            "chat_id": int(item["chat_id"]), "project_id": None, "archived": True,
        }, global_event=True)
    for item in applied.get("deleted_chats") or []:
        snapshot = item.get("snapshot") or {}
        await broadcast({
            "type": "chat_meta", "owner_user_id": int(user["id"]),
            "chat_id": int(item["chat_id"]), "deleted": True,
            "deleted_ts": item.get("deleted_ts"),
            "title": item.get("chat_title") or "",
            "project_id": snapshot.get("project_id"),
            "archived": bool(snapshot.get("archived")),
            "archived_ts": snapshot.get("archived_ts"),
            "active_id": active_id,
        }, global_event=True)
    _audit_event(
        request, "project.auto_group.apply", actor=user.get("email") or "user",
        target=str(rid), meta={
            "chat_count": len(applied["assignments"]),
            "archived_count": len(archived_ids),
            "deleted_count": len(deleted_ids),
            "created_project_count": len(applied["created_projects"]),
        },
    )
    return {"status": "ok", "run_id": rid, "applied": applied, "switched_to": switched_to}


@app.post("/api/projects/auto-group/{run_id}/undo")
async def api_project_auto_group_undo(run_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        rid = _parse_resource_id(run_id, "run_id")
        undo = _undo_auto_group_plan(rid, int(user["id"]))
    except ValueError as exc:
        return JSONResponse({"error": str(exc)}, status_code=400)
    except KeyError as exc:
        return JSONResponse({"error": str(exc).strip("'")}, status_code=404)
    except RuntimeError as exc:
        return JSONResponse({"error": str(exc)}, status_code=409)
    restored_groups: dict[Optional[int], list[int]] = {}
    for restored in undo["restored"]:
        restored_groups.setdefault(restored["project_id"], []).append(int(restored["chat_id"]))
    for pid, chat_ids_for_project in restored_groups.items():
        await broadcast({
            "type": "project_assignment", "owner_user_id": int(user["id"]),
            "chat_ids": chat_ids_for_project, "project_id": pid,
        }, global_event=True)
        if pid is not None:
            project = _project_row(pid)
            if project and project.get("folder"):
                await _rehome_project_member_chats(int(pid))
    for pid in undo["deleted_project_ids"]:
        await broadcast({
            "type": "project_deleted", "owner_user_id": int(user["id"]),
            "project_id": int(pid), "chat_ids": [],
        }, global_event=True)
    for restored in undo.get("restored_archives") or []:
        await broadcast({
            "type": "chat_meta", "owner_user_id": int(user["id"]),
            "chat_id": int(restored["chat_id"]), "project_id": restored.get("project_id"),
            "archived": False,
        }, global_event=True)
    for restored in undo.get("restored_deleted") or []:
        entry = (
            CHAT_INDEX.get("chats", {}).get(str(int(restored["chat_id"]))) or {}
        )
        await broadcast({
            "type": "chat_meta", "owner_user_id": int(user["id"]),
            "chat_id": int(restored["chat_id"]), "deleted": False,
            "deleted_ts": None,
            "project_id": entry.get("project_id", restored.get("project_id")),
            "archived": bool(entry.get("archived")),
            "archived_ts": entry.get("archived_ts"),
            "title": entry.get("title") or restored.get("title") or f"Conversation {restored['chat_id']}",
            "ts": entry.get("ts"), "mode": entry.get("mode"),
            "active_id": _active_chat_id_for_request(request),
        }, global_event=True)
    _audit_event(
        request, "project.auto_group.undo", actor=user.get("email") or "user",
        target=str(rid), meta={
            "restored_count": (
                len(undo["restored"])
                + len(undo.get("restored_archives") or [])
                + len(undo.get("restored_deleted") or [])
            ),
            "conflict_count": len(undo["conflicts"]),
        },
    )
    return {"status": "ok", "run_id": rid, "undo": undo}


