@app.post("/api/projects")
async def api_create_project(request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        body = await _json_object_body(request)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    raw_title = body.get("title")
    if raw_title is not None and not isinstance(raw_title, str):
        return JSONResponse({"error": "title must be a string"}, status_code=400)
    title = (raw_title or "").strip()
    if not title:
        return JSONResponse({"error": "title required"}, status_code=400)
    if len(title) > PROJECT_TITLE_MAX:
        return JSONResponse(
            {"error": f"title must be {PROJECT_TITLE_MAX} characters or fewer"},
            status_code=400,
        )
    coding_start = body.get("coding_start", False)
    if not isinstance(coding_start, bool):
        return JSONResponse({"error": "coding_start must be a boolean"}, status_code=400)
    try:
        chat_id = _parse_resource_id(
            body.get("chat_id"), "chat_id", allow_none=True,
        ) if "chat_id" in body else None
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    move_chat = body.get("move_chat", False)
    if not isinstance(move_chat, bool):
        return JSONResponse({"error": "move_chat must be a boolean"}, status_code=400)
    if move_chat and chat_id is None:
        return JSONResponse({"error": "move_chat requires chat_id"}, status_code=400)
    current_project_id = None
    if chat_id is not None:
        if not user:
            return JSONResponse({"error": "chat not found"}, status_code=404)
        # Read membership from authoritative SQLite, not the best-effort hot
        # mirror: the safety check must still hold while another client refreshes
        # or after recovery has rebuilt one store before the other.
        with _db() as conn:
            chat_row = conn.execute(
                "SELECT project_id FROM chats WHERE id=? AND owner_user_id=? "
                "AND deleted_ts IS NULL",
                (chat_id, int(user["id"])),
            ).fetchone()
        if not chat_row:
            return JSONResponse({"error": "chat not found"}, status_code=404)
        if chat_row["project_id"] is not None:
            current_project_id = int(chat_row["project_id"])
    if current_project_id is not None and not move_chat:
        # A chat has exactly one project. Creating another project with a
        # assigned chat used to overwrite that membership without saying it was a
        # move. Require an explicit opt-in before creating anything, so a stale
        # client cannot leave behind an empty project or silently refile a chat.
        return JSONResponse({
            "error": "chat already belongs to a project; pass move_chat=true to move it",
            "project_id": current_project_id,
        }, status_code=409)
    selected_project_folder: Optional[Path] = None
    if "folder" in body:
        raw_folder = body.get("folder")
        if not isinstance(raw_folder, str) or not raw_folder.strip():
            return JSONResponse({"error": "workspace folder must be a non-empty path"}, status_code=400)
        selected_project_folder, folder_error = _validated_workspace_path(raw_folder, user)
        if folder_error or selected_project_folder is None:
            return JSONResponse({"error": folder_error or "invalid workspace folder"}, status_code=400)
    try:
        project = _create_project(title, chat_id,
                                  owner_user_id=int(user["id"]))
    except (ValueError, KeyError) as e:
        status = 404 if isinstance(e, KeyError) else 400
        return JSONResponse({"error": str(e).strip("'")}, status_code=status)
    if selected_project_folder is not None:
        selected = _update_project(
            int(project["id"]), int(user["id"]),
            {"folder": str(selected_project_folder)},
        )
        if selected:
            project = selected
            _seed_project_md(selected_project_folder, project)
    else:
        bound = _ensure_project_folder(project, user)
        if bound:
            project = bound
    if project.get("folder"):
        await _rehome_project_member_chats(int(project["id"]))
    chat_intent = None
    if coding_start and chat_id is not None:
        chat_intent = _set_chat_intent(int(chat_id), "code")
    await broadcast({
        "type": "project_meta",
        "owner_user_id": int(user["id"]),
        "project": project,
        "chat_id": chat_id,
    }, global_event=True)
    if chat_id is not None:
        await broadcast({
            "type": "chat_meta",
            "owner_user_id": int(user["id"]),
            "chat_id": chat_id,
            "project_id": project.get("id"),
            **({"chat_intent": chat_intent} if chat_intent else {}),
        }, global_event=True)
    if coding_start and chat_id is not None:
        await _launch_coding_start(int(chat_id), title, user)
    return {
        "status": "ok", "project": project,
        **({"chat_intent": chat_intent} if chat_intent else {}),
    }


@app.patch("/api/projects/{project_id}")
async def api_update_project(project_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        pid = _parse_resource_id(project_id, "project_id")
        body = await _json_object_body(request)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    existing_project = _project_row(pid)
    if (
        not existing_project or not user
        or int(existing_project.get("owner_user_id") or 0) != int(user["id"])
    ):
        return JSONResponse({"error": "project not found"}, status_code=404)
    updates: dict = {}
    if "title" in body:
        title = body.get("title")
        if not isinstance(title, str):
            return JSONResponse({"error": "title must be a string"}, status_code=400)
        title = title.strip()
        if not title:
            return JSONResponse({"error": "title required"}, status_code=400)
        if len(title) > PROJECT_TITLE_MAX:
            return JSONResponse(
                {"error": f"title must be {PROJECT_TITLE_MAX} characters or fewer"},
                status_code=400,
            )
        updates["title"] = title
    if "status" in body:
        status = body.get("status")
        if status not in ("active", "archived"):
            return JSONResponse({"error": "status must be active or archived"}, status_code=400)
        updates["status"] = status
    if "create_folder" in body and "folder" in body:
        return JSONResponse({"error": "pass folder or create_folder, not both"}, status_code=400)
    if "create_folder" in body:
        name = body.get("create_folder")
        if not isinstance(name, str) or not name.strip():
            return JSONResponse({"error": "create_folder must be a workspace folder name"}, status_code=400)
        name = name.strip()
        if len(name) > 120 or re.search(r"[/\\]|^\.", name) or not _workspace_path_is_safe(name):
            return JSONResponse({"error": "workspace folder name may not start with a dot or contain slashes, quotes, or control characters"}, status_code=400)
        root = (
            PROJECTS_FOLDER_ROOT
            if _is_admin_user(user)
            else _managed_project_root(int(user["id"]))
        )
        target, error = _validated_workspace_path(
            str(root / name), user, require_exists=False,
        )
        if error or target is None:
            return JSONResponse({"error": error or "invalid workspace folder"}, status_code=400)
        try:
            target.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            return JSONResponse({"error": f"could not create workspace folder: {e}"}, status_code=400)
        updates["folder"] = str(target)
    elif "folder" in body:
        raw_folder = body.get("folder")
        if raw_folder is not None and not isinstance(raw_folder, str):
            return JSONResponse({"error": "workspace folder must be a string path or empty"}, status_code=400)
        cleaned = (raw_folder or "").strip()
        if cleaned == "":
            updates["folder"] = None
        else:
            expanded, error = _validated_workspace_path(cleaned, user)
            if error or expanded is None:
                return JSONResponse({"error": error or "invalid workspace folder"}, status_code=400)
            updates["folder"] = str(expanded)
    if not updates:
        return JSONResponse({"error": "title, status, or folder required"}, status_code=400)
    project = _update_project(pid, int(user["id"]), updates)
    if not project:
        return JSONResponse({"error": "project not found"}, status_code=404)
    if "folder" in updates:
        # Workspace-folder attach/detach re-homes every member chat that has no explicit
        # binding of its own: seed the identity file, reconcile tombstones in
        # vacated scratch dirs, and tell open clients which cwd is now live.
        if updates["folder"]:
            _seed_project_md(Path(updates["folder"]), project)
        await _rehome_project_member_chats(pid)
    await broadcast({
        "type": "project_meta",
        "owner_user_id": int(user["id"]),
        "project": project,
    }, global_event=True)
    return {"status": "ok", "project": project}


@app.delete("/api/projects/{project_id}")
async def api_delete_project(project_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        pid = _parse_resource_id(project_id, "project_id")
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    existing = _project_row(pid)
    if (
        not existing or not user
        or int(existing.get("owner_user_id") or 0) != int(user["id"])
    ):
        return JSONResponse({"error": "project not found"}, status_code=404)

    # A preview is a real child process running code from the attached folder.
    # Stop it before removing the only UI record that can address that process.
    server = PREVIEW_SERVERS.get(pid)
    if server:
        proc = server.get("proc")
        try:
            await asyncio.to_thread(_stop_preview_server, pid)
        except Exception as exc:
            logger.error("could not stop preview before deleting project %s: %s", pid, exc)
            return JSONResponse(
                {"error": "could not stop the project preview; folder was not deleted"},
                status_code=503,
            )
        if proc is not None and proc.poll() is None:
            return JSONResponse(
                {"error": "project preview did not stop; folder was not deleted"},
                status_code=503,
            )

    try:
        result = _delete_project_record(pid, int(user["id"]))
    except RuntimeError:
        logger.exception("project %s changed during permanent deletion", pid)
        return JSONResponse(
            {"error": "project changed while it was being deleted; nothing was removed"},
            status_code=409,
        )
    if not result:
        return JSONResponse({"error": "project not found"}, status_code=404)

    # Defense against a preview start racing the initial stop gate.
    if pid in PREVIEW_SERVERS:
        await asyncio.to_thread(_stop_preview_server, pid)
    chat_ids = result["chat_ids"]
    await broadcast({
        "type": "project_deleted",
        "owner_user_id": int(user["id"]),
        "project_id": pid,
        "chat_ids": chat_ids,
    }, global_event=True)
    if chat_ids:
        await broadcast({
            "type": "project_assignment",
            "owner_user_id": int(user["id"]),
            "chat_ids": chat_ids,
            "project_id": None,
        }, global_event=True)
        for cid in chat_ids:
            info = _chat_workspace_info(cid)
            await broadcast({
                "type": "chat_meta",
                "owner_user_id": int(user["id"]),
                "chat_id": cid,
                "project_id": None,
                "workspace": info["path"],
                "workspace_is_default": True,
                "workspace_source": info["source"],
            }, global_event=True)
    return {
        "status": "ok",
        "project_id": pid,
        "chat_ids": chat_ids,
        "unfiled_chat_count": len(chat_ids),
        "unfiled_event_count": result["event_count"],
        "unfiled_decision_count": result["decision_count"],
        "disk_folder_deleted": False,
    }


# Where "clone the app baseline into a project" clones FROM. The live tree is
# read-only for agents (protected paths); a local git clone reads only .git and
# never mutates the source, which is the one sanctioned way project work may
# start from Agents Chat's own code (workspace-plan phase 2; full self-upgrade
# flow is phase 5).
BASELINE_REPO_PATH = Path(
    os.environ.get("BASELINE_REPO_PATH", str(BASE_DIR))
).expanduser()


_LIVE_TREE_SKIP_PREFIXES = (
    ".git/", "node_modules/", "__pycache__/", ".venv/", "venv/",
    "data/", "attachments/", "artifacts_store/", "voice_cache/",
    "storage_backups/", "cutover_backups/", "backup/", ".pytest_cache/",
)


def _overlay_live_working_tree(src: Path, dest: Path) -> None:
    """Copy uncommitted live files onto a git clone so the copy is the running app."""
    if not (src / ".git").exists() or not dest.is_dir():
        return
    listed = subprocess.run(
        ["git", "-C", str(src), "diff", "--name-only", "HEAD"],
        capture_output=True, text=True, timeout=30,
    )
    extra = subprocess.run(
        ["git", "-C", str(src), "ls-files", "--others", "--exclude-standard"],
        capture_output=True, text=True, timeout=30,
    )
    rels = []
    for blob in (listed.stdout or "", extra.stdout or ""):
        rels.extend([line.strip() for line in blob.splitlines() if line.strip()])
    for rel in dict.fromkeys(rels):
        if rel.endswith(".sqlite3") or rel.endswith(".sqlite3-wal") or rel.endswith(".sqlite3-shm"):
            continue
        if any(rel == p[:-1] or rel.startswith(p) for p in _LIVE_TREE_SKIP_PREFIXES):
            continue
        if Path(rel).name in {".env", ".env.local"}:
            continue
        source = src / rel
        if not source.is_file():
            continue
        target = dest / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)


def _clone_baseline_into(target: Path, branch: str) -> tuple[bool, str]:
    """Clone the baseline repo, then overlay the live working tree. Off-loop."""
    try:
        clone = subprocess.run(
            ["git", "clone", "--no-hardlinks", f"file://{BASELINE_REPO_PATH}", str(target)],
            capture_output=True, text=True, timeout=180,
        )
        if clone.returncode != 0:
            return False, (clone.stderr or clone.stdout or "git clone failed")[-400:]
        checkout = subprocess.run(
            ["git", "-C", str(target), "checkout", "-b", branch],
            capture_output=True, text=True, timeout=30,
        )
        if checkout.returncode != 0:
            return False, (checkout.stderr or checkout.stdout or "git checkout failed")[-400:]
        try:
            _overlay_live_working_tree(Path(BASELINE_REPO_PATH), target)
        except Exception:
            logger.exception("live-tree overlay failed for %s", target)
        return True, ""
    except subprocess.TimeoutExpired:
        return False, "git timed out"
    except OSError as e:
        return False, str(e)


@app.post("/api/projects/{project_id}/clone-baseline")
async def api_clone_project_baseline(project_id: str, request: Request):
    """One-tap 'pull the Agents Chat baseline into this project': local git clone
    of the app repo into <workspace folder>/<subdir> on a fresh project/<number>
    branch. The source repo is never written to; agents then work on the copy."""
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        pid = _parse_resource_id(project_id, "project_id")
        body = await _json_object_body(request, empty_ok=True)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    project = _project_row(pid)
    if not project or not user or int(project.get("owner_user_id") or 0) != int(user["id"]):
        return JSONResponse({"error": "project not found"}, status_code=404)
    if not _is_admin_user(user):
        return JSONResponse(
            {"error": "admin required to run host git processes"}, status_code=403,
        )
    folder_path, folder_error = _project_folder_for_user(project, user)
    if folder_error or folder_path is None:
        return JSONResponse({"error": folder_error or "attach a workspace folder first"}, status_code=400)
    subdir = body.get("subdir") or "agent-chat"
    if not isinstance(subdir, str) or not subdir.strip():
        return JSONResponse({"error": "subdir must be a folder name"}, status_code=400)
    subdir = subdir.strip()
    if len(subdir) > 120 or re.search(r"[/\\]|^\.", subdir) or not _workspace_path_is_safe(subdir):
        return JSONResponse({"error": "subdir may not start with a dot or contain slashes, quotes, or control characters"}, status_code=400)
    if not (BASELINE_REPO_PATH / ".git").exists():
        return JSONResponse({"error": "baseline repo is not a git checkout"}, status_code=400)
    target = folder_path / subdir
    if target.exists():
        return JSONResponse({"error": f"{subdir} already exists in the workspace folder"}, status_code=409)
    number = str(project.get("number") or f"P-{pid}").lower()
    branch = f"project/{re.sub(r'[^a-z0-9-]+', '-', number).strip('-')}"
    # Clone into a private temp dir and rename into place. Two concurrent clones
    # can both pass the exists() check above; without this the loser's cleanup
    # would delete the winner's freshly cloned tree.
    staging = target.with_name(f".{target.name}.incoming-{secrets.token_hex(6)}")
    ok, detail = await asyncio.to_thread(_clone_baseline_into, staging, branch)
    if not ok:
        shutil.rmtree(staging, ignore_errors=True)
        return JSONResponse({"error": f"clone failed: {detail}"}, status_code=502)
    try:
        os.rename(staging, target)          # atomic; fails if someone else won
    except OSError:
        shutil.rmtree(staging, ignore_errors=True)
        return JSONResponse(
            {"error": f"{subdir} already exists in the workspace folder"}, status_code=409,
        )
    return {"status": "ok", "path": str(target), "branch": branch}


# ------------------------- Project preview servers (Phase 3) -------------------------
# Each project workspace folder can run ONE managed dev server on a loopback port; the app
# reverse-proxies it under an auth-gated /preview/<project_id>/ path so the live
# result renders inside Agents Chat (and on mobile through the existing HTTPS
# relay) without ever exposing the raw dev-server port. The proxy only ever
# forwards to the port THIS app allocated for THIS project — never a host/port
# taken from the request — so it is SSRF-safe by construction. In-memory only:
# an app restart stops every preview (the child dies in our process group) and
# the owner restarts on demand.
PREVIEW_SERVERS: dict[int, dict] = {}
# Deliberately BELOW the ephemeral range (49152-65535 on macOS): the startup
# sweep terminates whatever holds these ports, so they must not be ports the
# OS might hand to an unrelated program.
PREVIEW_PORT_RANGE = range(8300, 8350)
_PREVIEW_MAX_COMMAND = 500
_PREVIEW_MAX_RESPONSE_BYTES = max(
    1,
    int(os.environ.get("PREVIEW_MAX_RESPONSE_BYTES", str(32 * 1024 * 1024))),
)
# A preview server is agent-authored, untrusted project code. Forward only
# ordinary representation/request metadata; never proxy Agents Chat credentials
# (Authorization, X-Orchestrator-Token, session headers/cookies) into it.
_PREVIEW_REQUEST_HEADER_ALLOWLIST = {
    "accept", "accept-language", "cache-control", "content-type",
    "if-modified-since", "if-none-match", "origin", "pragma", "range",
    "user-agent",
}
# Preview code is untrusted and its response is served on Agents Chat's origin.
# A strict allowlist prevents stateful headers such as Clear-Site-Data/Set-Cookie,
# protocol headers nominated by Connection, and stale validators from escaping.
# Location is handled separately and rewritten through the preview capability.
_PREVIEW_RESPONSE_HEADER_ALLOWLIST = {
    "content-disposition", "content-language", "content-type",
}


def _preview_forward_headers(headers) -> dict[str, str]:
    return {
        key: value
        for key, value in headers.items()
        if key.lower() in _PREVIEW_REQUEST_HEADER_ALLOWLIST
    }


def _preview_response_headers(headers) -> dict[str, str]:
    return {
        key: value
        for key, value in headers.items()
        if key.lower() in _PREVIEW_RESPONSE_HEADER_ALLOWLIST
    }


def _preview_rewrite_location(
    location: str, project_id: int, server: dict, upstream_path: str,
) -> Optional[str]:
    """Map one dev-server redirect back through this preview capability.

    Root-relative and absolute loopback redirects otherwise escape the token
    prefix (or point a mobile client at its own localhost). External redirects
    are deliberately rejected by returning None.
    """
    location = str(location or "").strip()
    if not location:
        return None
    upstream_base = f"http://127.0.0.1:{int(server['port'])}/{upstream_path}"
    resolved = urlparse(urljoin(upstream_base, location))
    try:
        resolved_port = resolved.port
    except ValueError:
        return None
    if (
        resolved.scheme != "http"
        or (resolved.hostname or "").lower() not in {"127.0.0.1", "localhost"}
        or resolved_port != int(server["port"])
        or resolved.username is not None
        or resolved.password is not None
    ):
        return None
    base = _preview_url(project_id, server).rstrip("/")
    target = base + "/" + resolved.path.lstrip("/")
    if resolved.query:
        target += "?" + resolved.query
    if resolved.fragment:
        target += "#" + resolved.fragment
    return target


# Running previews are recorded to a small sidecar so a HARD stop can still reap
# them. The in-memory registry dies with the process, and `launchctl bootout` (or
# a crash) skips the lifespan shutdown — without this, dev servers survive as
# orphans reparented to PID 1, holding their ports and invisible to the next boot.
PREVIEW_STATE_FILE = Path(
    os.environ.get("PREVIEW_STATE_FILE", str(DATA_DIR / "preview_servers.json"))
)


def _save_preview_state() -> None:
    try:
        rows = [
            {"project_id": int(pid), "pid": int(s["proc"].pid), "port": int(s["port"])}
            for pid, s in PREVIEW_SERVERS.items()
            if s.get("proc") is not None and s["proc"].poll() is None
        ]
        tmp = PREVIEW_STATE_FILE.with_suffix(".tmp")
        tmp.write_text(json.dumps(rows))
        tmp.replace(PREVIEW_STATE_FILE)
    except OSError:
        pass


def _process_cmdline(pid: int) -> str:
    try:
        out = subprocess.run(
            ["ps", "-p", str(pid), "-o", "command="],
            capture_output=True, text=True, timeout=5,
        )
        return out.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return ""


def _parse_listening_ports_in_range(lsof_output: str, lo: int, hi: int) -> dict[int, int]:
    """port -> pid, from `lsof -nP -iTCP -sTCP:LISTEN` output, limited to the
    inclusive port range [lo, hi]. Split out from the lsof call so it stays
    testable — lsof itself is unavailable in some sandboxes."""
    found: dict[int, int] = {}
    for line in (lsof_output or "").splitlines():
        match = re.search(r":(\d+)\s+\(LISTEN\)", line)
        if not match:
            continue
        port = int(match.group(1))
        if not (lo <= port <= hi):
            continue
        parts = line.split()
        try:
            found[port] = int(parts[1])
        except (IndexError, ValueError):
            continue
    return found


def _parse_listening_preview_ports(lsof_output: str) -> dict[int, int]:
    """port -> pid for the app-reserved preview range."""
    return _parse_listening_ports_in_range(
        lsof_output, PREVIEW_PORT_RANGE[0], PREVIEW_PORT_RANGE[-1]
    )


def _listening_preview_ports() -> dict[int, int]:
    """Whatever is listening on the reserved preview range right now. Only
    meaningful at boot, when nothing of ours can legitimately be running."""
    try:
        out = subprocess.run(
            ["lsof", "-nP", "-iTCP", "-sTCP:LISTEN"],
            capture_output=True, text=True, timeout=10,
        )
    except (OSError, subprocess.SubprocessError):
        return {}
    return _parse_listening_preview_ports(out.stdout)


async def _reap_orphan_previews_on_startup() -> None:
    """Kill preview dev servers stranded by a hard restart.

    The persisted sidecar is the authority for what Agents Chat owns. Never kill
    an unrecorded listener merely because it happens to use a reserved port: a
    stale/missing sidecar must degrade to a skipped port, not host process loss.
    """
    rows: list = []
    try:
        if PREVIEW_STATE_FILE.is_file():
            loaded = json.loads(PREVIEW_STATE_FILE.read_text())
            if isinstance(loaded, list):
                rows = loaded
    except (OSError, ValueError):
        rows = []
    reaped = 0
    listening = _listening_preview_ports()   # port -> pid, for identity checks
    for row in rows:
        try:
            pid, port = int(row["pid"]), int(row["port"])
        except (KeyError, TypeError, ValueError):
            continue
        # Two ways to be sure this pid is really that preview, so PID reuse can
        # never make us kill a bystander: it still holds the recorded port, or
        # the port appears in its command line. `npm run dev` takes its port from
        # the environment and shows nothing in argv — hence the first check.
        if listening.get(port) != pid:
            cmd = _process_cmdline(pid)
            if not cmd or str(port) not in cmd:
                continue  # already gone, or the PID belongs to something else
        try:
            os.killpg(os.getpgid(pid), signal.SIGTERM)
            reaped += 1
        except OSError:
            try:
                os.kill(pid, signal.SIGTERM)
                reaped += 1
            except OSError:
                pass
    if reaped:
        logger.info("reaped %d orphaned preview server(s) from a previous run", reaped)
    try:
        PREVIEW_STATE_FILE.unlink(missing_ok=True)
    except OSError:
        pass


def _free_preview_port() -> Optional[int]:
    used = {s.get("port") for s in PREVIEW_SERVERS.values()}
    for port in PREVIEW_PORT_RANGE:
        if port in used:
            continue
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
            try:
                sock.bind(("127.0.0.1", port))
            except OSError:
                continue
        return port
    return None


def _preview_html_files(folder: Path) -> list[Path]:
    """Top-level HTML in this folder only — never a recursive crawl."""
    try:
        return [
            child for child in folder.iterdir()
            if child.is_file() and child.suffix.lower() in {".html", ".htm"}
        ]
    except OSError:
        return []


def _preview_command_at(folder: Path) -> Optional[str]:
    """Detect a preview command at exactly this directory."""
    try:
        pkg = folder / "package.json"
        if pkg.is_file():
            data = json.loads(pkg.read_text())
            scripts = data.get("scripts") if isinstance(data, dict) else {}
            if isinstance(scripts, dict):
                for name in ("dev", "start", "serve", "preview"):
                    if name in scripts:
                        return f"npm run {name}"
        # A workspace of standalone pages (no package.json, often no index.html)
        # is still previewable — serve the folder and let the browser list them.
        if _preview_html_files(folder):
            return "python3 -m http.server $PORT --bind 127.0.0.1"
    except (OSError, ValueError):
        pass
    return None


def _preview_launch_target(folder: Path) -> tuple[Path, Optional[str]]:
    """Find the runnable project root without scanning beyond one safe level.

    A freshly cloned Agent Chat baseline lives at ``<workspace>/agent-chat``.
    Treating only the outer workspace as runnable made the one-tap clone flow a
    dead end. We accept one unambiguous, real (non-symlink) child project; two
    candidates stay ambiguous and require an explicit command.
    """
    direct = _preview_command_at(folder)
    if direct:
        return folder, direct
    try:
        candidates = [
            (child, command)
            for child in sorted(folder.iterdir())
            if child.is_dir() and not child.is_symlink()
            for command in [_preview_command_at(child)]
            if command
        ]
    except OSError:
        candidates = []
    return candidates[0] if len(candidates) == 1 else (folder, None)


def _preview_default_command(folder: Path) -> Optional[str]:
    """Best-effort command, including one unambiguous nested checkout."""
    return _preview_launch_target(folder)[1]


def _preview_alive(server: Optional[dict]) -> bool:
    proc = (server or {}).get("proc")
    return bool(proc and proc.poll() is None)


def _preview_log_tail(server: Optional[dict], limit: int = 1500) -> str:
    """Last bytes of a preview's log — the only explanation available when a dev
    server starts and then dies (bad command, missing dep, port in use)."""
    path = (server or {}).get("log_path")
    if not path:
        return ""
    try:
        return Path(path).read_text(errors="replace")[-limit:].strip()
    except OSError:
        return ""


def _stop_preview_server(project_id: int) -> bool:
    server = PREVIEW_SERVERS.pop(int(project_id), None)
    if not server:
        return False
    proc = server.get("proc")
    if proc and proc.poll() is None:
        # Kill the whole process group (npm spawns children); SIGTERM, then SIGKILL.
        try:
            os.killpg(os.getpgid(proc.pid), signal.SIGTERM)
        except (ProcessLookupError, PermissionError, OSError):
            try: proc.terminate()
            except OSError: pass
        try:
            proc.wait(timeout=5)
        except subprocess.TimeoutExpired:
            try:
                os.killpg(os.getpgid(proc.pid), signal.SIGKILL)
            except OSError:
                try: proc.kill()
                except OSError: pass
    fh = server.get("_log_fh")
    if fh:
        try: fh.close()
        except OSError: pass
    _save_preview_state()
    return True


def _start_preview_server(project_id: int, folder: Path, command: str, port: int) -> dict:
    """Spawn `command` in `folder` with PORT/HOST env set, in its own session so
    the whole tree can be killed together. Non-blocking; readiness is discovered
    lazily by the proxy (a connect error before the server is up renders a
    'starting…' page rather than a hard error)."""
    env = dict(os.environ)
    env["PORT"] = str(port)
    env["HOST"] = "127.0.0.1"
    env["BROWSER"] = "none"  # keep CRA/Vite from opening a desktop browser
    token = secrets.token_urlsafe(24)
    # Base-path-aware dev servers (Vite, routers, API clients) can opt into the
    # exact capability path instead of emitting root-relative URLs that escape
    # the authenticated preview proxy. The child already controls all content
    # served by this one preview, and the short-lived token dies with it.
    env["AGENT_CHAT_PREVIEW_BASE"] = f"/preview/{int(project_id)}/{token}/"
    log_path = WORKSPACES_ROOT / f"preview-{int(project_id)}.log"
    try:
        WORKSPACES_ROOT.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass
    log = open(log_path, "wb")
    proc = subprocess.Popen(
        ["/bin/sh", "-lc", command],
        cwd=str(folder), env=env,
        stdout=log, stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL,
        start_new_session=True,
    )
    server = {
        "proc": proc, "port": port, "command": command, "folder": str(folder),
        "log_path": str(log_path), "started_ts": int(time.time() * 1000),
        "_log_fh": log,
        # Capability token for THIS preview run. The preview frame is sandboxed
        # into an opaque origin (so a previewed page cannot call Agents Chat's own
        # API with the user's session), which also means its asset requests no
        # longer carry the SameSite session cookie. This token, carried in the
        # path so relative assets inherit it, is how those requests authenticate.
        # It grants access to this one preview only, and dies with the server.
        "token": token,
    }
    PREVIEW_SERVERS[int(project_id)] = server
    _save_preview_state()
    return server


def _preview_url(pid: int, server: Optional[dict]) -> str:
    token = (server or {}).get("token")
    return f"/preview/{int(pid)}/{token}/" if token else f"/preview/{int(pid)}/"


def _owned_project_or_404(project_id: str, request: Request):
    """Resolve (pid, project) for an owned project, or a JSONResponse to return.
    A missing and a cross-owner project deliberately look identical."""
    user = _current_user(request)
    pid = _parse_resource_id(project_id, "project_id")
    project = _project_row(pid)
    if not project or not user or int(project.get("owner_user_id") or 0) != int(user["id"]):
        return None, None, JSONResponse({"error": "project not found"}, status_code=404)
    return pid, project, None


def _project_folder_for_user(
    project: Optional[dict], user: Optional[dict],
) -> tuple[Optional[Path], Optional[str]]:
    """Resolve a project workspace folder at use time, catching symlink retargets."""
    folder = str((project or {}).get("folder") or "").strip()
    if not folder:
        return None, "attach a workspace folder first"
    path, error = _validated_workspace_path(folder, user)
    if error or path is None:
        return None, error or "workspace folder is no longer available"
    return path, None


@app.post("/api/projects/{project_id}/preview/start")
async def api_preview_start(project_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        pid, project, err = _owned_project_or_404(project_id, request)
        if err: return err
        body = await _json_object_body(request, empty_ok=True)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if not _is_admin_user(user):
        return JSONResponse(
            {"error": "admin required to run host preview processes"}, status_code=403,
        )
    folder_path, folder_error = _project_folder_for_user(project, user)
    if folder_error or folder_path is None:
        return JSONResponse({"error": folder_error or "attach a workspace folder first"}, status_code=400)
    existing = PREVIEW_SERVERS.get(pid)
    if _preview_alive(existing):
        return {"status": "ok", "port": existing["port"], "command": existing["command"],
                "working_dir": existing.get("folder"),
                "preview_url": _preview_url(pid, existing), "already_running": True}
    if existing:
        _stop_preview_server(pid)  # reap a dead husk before relaunch
    command = body.get("command")
    if command is not None and not isinstance(command, str):
        return JSONResponse({"error": "command must be a string"}, status_code=400)
    command = (command or "").strip()
    if len(command) > _PREVIEW_MAX_COMMAND:
        return JSONResponse({"error": f"command too long (max {_PREVIEW_MAX_COMMAND} chars)"}, status_code=400)
    if any(ch in command for ch in "\r\n\x00"):
        return JSONResponse({"error": "command may not contain newlines or null bytes"}, status_code=400)
    if command:
        launch_folder = folder_path
    else:
        launch_folder, command = _preview_launch_target(folder_path)
    if not command:
        return JSONResponse(
            {"error": "could not detect how to run this project — pass a command, e.g. \"npm run dev\""},
            status_code=400,
        )
    port = _free_preview_port()
    if not port:
        return JSONResponse({"error": "no free preview port available"}, status_code=503)
    try:
        server = _start_preview_server(pid, launch_folder, command, port)
    except OSError as e:
        return JSONResponse({"error": f"could not start preview: {e}"}, status_code=502)
    return {"status": "ok", "port": server["port"], "command": command,
            "working_dir": str(launch_folder),
            "preview_url": _preview_url(pid, server)}


@app.post("/api/projects/{project_id}/preview/stop")
async def api_preview_stop(project_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    try:
        pid, _project, err = _owned_project_or_404(project_id, request)
        if err: return err
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    stopped = await asyncio.to_thread(_stop_preview_server, pid)
    return {"status": "ok", "stopped": stopped}


@app.get("/api/projects/{project_id}/preview/status")
async def api_preview_status(project_id: str, request: Request):
    try:
        pid, _project, err = _owned_project_or_404(project_id, request)
        if err: return err
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    server = PREVIEW_SERVERS.get(pid)
    running = _preview_alive(server)
    died_log = ""
    if server and not running:
        died_log = _preview_log_tail(server)   # capture BEFORE the handle closes
        _stop_preview_server(pid)  # reap
        server = None
    return {
        "status": "ok", "running": running,
        "port": server["port"] if running else None,
        "command": server["command"] if server else None,
        "working_dir": server.get("folder") if server else None,
        "preview_url": _preview_url(pid, server) if running else None,
        "started_ts": server["started_ts"] if server else None,
        # Non-empty only when a server was found dead on this check.
        "died_log": died_log,
    }


def _preview_placeholder_html(project_id: int, *, starting: bool) -> str:
    msg = ("The preview server is starting — give it a moment and refresh."
           if starting else
           "No preview is running for this project. Start it from the project's "
           "workspace dialog, then refresh.")
    return (
        "<!doctype html><html><head><meta charset='utf-8'>"
        "<meta name='viewport' content='width=device-width, initial-scale=1'>"
        "<title>Preview</title><style>body{font:15px/1.5 -apple-system,system-ui,"
        "sans-serif;color:#2b2b2b;background:#faf9f6;display:flex;min-height:100vh;"
        "align-items:center;justify-content:center;margin:0}.card{max-width:420px;"
        "padding:28px 32px;border:1px solid #e6e2d8;border-radius:14px;text-align:center}"
        "h1{font-size:16px;margin:0 0 8px}p{margin:0;color:#6b6b6b}</style></head>"
        f"<body><div class='card'><h1>Preview {'starting' if starting else 'not running'}</h1>"
        f"<p>{msg}</p></div></body></html>"
    )


def _preview_framed_html(project_id: int, *, starting: bool, status_code: int = 503) -> HTMLResponse:
    """A preview placeholder that carries the same same-origin framing headers as
    a real proxied response — without them, _security_headers' setdefault stamps
    X-Frame-Options: DENY and the browser blocks the placeholder inside the
    preview iframe (showing a bare 'refused to connect' during the startup
    window instead of the friendly 'starting…' page)."""
    response = HTMLResponse(
        _preview_placeholder_html(project_id, starting=starting), status_code=status_code
    )
    response.headers["X-Frame-Options"] = "SAMEORIGIN"
    response.headers["Content-Security-Policy"] = (
        "sandbox allow-scripts allow-forms allow-popups allow-downloads; "
        "frame-ancestors 'self'"
    )
    return response


# The Visual Director's in-page agent (phase 4). Injected into every proxied
# HTML page — and ONLY proxied pages, never Agents Chat itself. Inert until the
# parent toggles inspect on, except for error capture, which runs from load so
# "this is broken" can ship the real stack trace instead of a description.
_PREVIEW_INSPECT_JS = """
(function(){
  if (window.__acInspect) return; window.__acInspect = true;
  var on = false, hl = null, errors = [];
  function note(type, message){
    errors.push({type: type, message: String(message).slice(0, 400)});
    if (errors.length > 40) errors.shift();
  }
  window.addEventListener('error', function(e){
    note('js-error', (e && (e.message || e.error) || '') + (e && e.filename ? ' @ ' + e.filename + ':' + e.lineno : ''));
  });
  window.addEventListener('unhandledrejection', function(e){
    note('unhandled-rejection', (e && e.reason && e.reason.message) || (e && e.reason) || '');
  });
  var origError = console.error;
  console.error = function(){
    try { note('console.error', Array.prototype.map.call(arguments, String).join(' ')); } catch (_) {}
    return origError.apply(console, arguments);
  };
  var origFetch = window.fetch;
  if (origFetch) {
    window.fetch = function(){
      var url = arguments[0] && arguments[0].url || arguments[0];
      return origFetch.apply(this, arguments).then(function(r){
        if (!r.ok) note('http', r.status + ' ' + r.statusText + ' — ' + url);
        return r;
      }, function(err){ note('network', 'request failed — ' + url + ' — ' + err); throw err; });
    };
  }
  function box(){
    if (hl) return hl;
    hl = document.createElement('div');
    hl.setAttribute('data-ac-inspect-overlay', '');
    hl.style.cssText = 'position:fixed;pointer-events:none;z-index:2147483647;border:2px solid #c6a052;' +
      'background:rgba(198,160,82,.18);border-radius:3px;display:none';
    (document.body || document.documentElement).appendChild(hl);
    return hl;
  }
  function show(el){
    var r = el.getBoundingClientRect(), b = box();
    b.style.display = 'block'; b.style.left = r.left + 'px'; b.style.top = r.top + 'px';
    b.style.width = r.width + 'px'; b.style.height = r.height + 'px';
  }
  function hide(){ if (hl) hl.style.display = 'none'; }
  function selectorFor(el){
    if (!el || el === document.body) return 'body';
    if (el.id) return '#' + el.id;
    var parts = [], node = el, depth = 0;
    while (node && node.nodeType === 1 && depth < 4) {
      if (node.id) { parts.unshift('#' + node.id); break; }
      var s = node.tagName.toLowerCase();
      if (node.classList && node.classList.length) {
        s += '.' + Array.prototype.slice.call(node.classList, 0, 2).join('.');
      }
      var parent = node.parentElement;
      if (parent) {
        var sibs = Array.prototype.filter.call(parent.children, function(c){ return c.tagName === node.tagName; });
        if (sibs.length > 1) s += ':nth-of-type(' + (sibs.indexOf(node) + 1) + ')';
      }
      parts.unshift(s); node = parent; depth++;
    }
    return parts.join(' > ');
  }
  function describe(el){
    var r = el.getBoundingClientRect(), cs = window.getComputedStyle(el);
    return {
      selector: selectorFor(el), tag: el.tagName.toLowerCase(),
      text: (el.innerText || '').trim().slice(0, 120),
      width: Math.round(r.width), height: Math.round(r.height),
      color: cs.color, background: cs.backgroundColor, fontSize: cs.fontSize,
      html: (el.outerHTML || '').slice(0, 400)
    };
  }
  function pick(el){
    if (!el || el.nodeType !== 1 || el.hasAttribute('data-ac-inspect-overlay')) return;
    hide();
    parent.postMessage({ __acInspect: 'element', payload: describe(el) }, '*');
  }
  document.addEventListener('mousemove', function(e){ if (on && e.target && e.target.nodeType === 1) show(e.target); }, true);
  document.addEventListener('click', function(e){
    if (!on) return;
    e.preventDefault(); e.stopPropagation(); pick(e.target);
  }, true);
  document.addEventListener('touchstart', function(e){
    if (!on) return;
    var t = e.touches && e.touches[0]; if (!t) return;
    e.preventDefault();
    pick(document.elementFromPoint(t.clientX, t.clientY));
  }, { capture: true, passive: false });
  window.addEventListener('message', function(e){
    var d = e.data || {};
    if (d.__acInspect === 'toggle') {
      on = !!d.on; if (!on) hide();
      document.documentElement.style.cursor = on ? 'crosshair' : '';
    } else if (d.__acInspect === 'collect-errors') {
      parent.postMessage({ __acInspect: 'errors', payload: errors.slice(-20) }, '*');
    }
  });
  parent.postMessage({ __acInspect: 'ready' }, '*');
})();
"""


def _inject_preview_base(content: bytes, project_id: int, base_path: str) -> bytes:
    """Inject <base href='<base_path>'> so a dev app's relative asset paths
    resolve under the proxy prefix — which also carries the preview's capability
    token, the credential a sandboxed (opaque-origin) frame has instead of the
    session cookie. Also injects the Visual Director's inspect agent.
    (Absolute-path assets like /static/app.js still escape the prefix — those
    apps need a configured base; documented.)"""
    try:
        html = content.decode("utf-8")
    except UnicodeDecodeError:
        return content
    tag = "" if "<base " in html.lower() else f'<base href="{base_path}">'
    tag += f"<script>{_PREVIEW_INSPECT_JS}</script>"
    lower = html.lower()
    head = lower.find("<head>")
    if head != -1:
        pos = head + len("<head>")
        return (html[:pos] + tag + html[pos:]).encode("utf-8")
    html_tag = lower.find("<html")
    if html_tag != -1:
        close = lower.find(">", html_tag)
        if close != -1:
            return (html[:close + 1] + tag + html[close + 1:]).encode("utf-8")
    return (tag + html).encode("utf-8")


@app.get("/preview/{project_id}")
async def preview_root_redirect(project_id: str):
    # A trailing slash is required for <base href>-relative assets to resolve.
    return RedirectResponse(f"/preview/{project_id}/", status_code=307)


@app.api_route(
    "/preview/{project_id}/{path:path}",
    methods=["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "HEAD"],
)
async def preview_proxy(project_id: str, path: str, request: Request):
    # This path is NOT under the middleware's /api auth gate — authorize here.
    # Two accepted credentials, because the preview frame is sandboxed into an
    # opaque origin and therefore cannot send the SameSite session cookie:
    #   1. the running preview's capability token, carried as the FIRST path
    #      segment (relative assets inherit it via <base href>), or
    #   2. an owning user session, for opening the preview directly in a tab.
    # A non-owner without a valid token sees the same 404 as a missing project.
    try:
        pid = _parse_resource_id(project_id, "project_id")
    except ValueError:
        return PlainTextResponse("bad project id", status_code=400)
    server = PREVIEW_SERVERS.get(pid)
    token = (server or {}).get("token")
    token_ok = False
    if token:
        first, _, rest = path.partition("/")
        if secrets.compare_digest(first, token):
            token_ok, path = True, rest
    if not token_ok:
        user = _current_user(request)
        project = _project_row(pid)
        if not project or not user or int(project.get("owner_user_id") or 0) != int(user["id"]):
            return PlainTextResponse("preview not found", status_code=404)
    if not _preview_alive(server):
        if server:
            _stop_preview_server(pid)
        return _preview_framed_html(pid, starting=False)
    upstream = f"http://127.0.0.1:{server['port']}/{path}"
    # The preview process is untrusted project code. Forward only the explicit
    # representation/request metadata allowlist above; all Agents Chat auth and
    # orchestration headers stay at this boundary.
    fwd = _preview_forward_headers(request.headers)
    body = await request.body()
    try:
        async with httpx.AsyncClient(timeout=30.0) as client:
            async with client.stream(
                request.method,
                upstream,
                params=request.query_params,
                headers=fwd,
                content=body,
                follow_redirects=False,
            ) as up:
                ctype = up.headers.get("content-type", "")
                headers = _preview_response_headers(up.headers)
                location = up.headers.get("location")
                if location is not None:
                    rewritten = _preview_rewrite_location(location, pid, server, path)
                    if rewritten is None:
                        logger.warning(
                            "preview project %s rejected unsafe redirect location", pid,
                        )
                        return _preview_framed_html(pid, starting=False, status_code=502)
                    headers["location"] = rewritten

                content = b""
                if request.method != "HEAD":
                    declared = up.headers.get("content-length")
                    try:
                        declared_size = int(declared) if declared is not None else None
                    except (TypeError, ValueError):
                        declared_size = None
                    if declared_size is not None and declared_size > _PREVIEW_MAX_RESPONSE_BYTES:
                        logger.warning(
                            "preview project %s response too large (%s declared bytes)",
                            pid,
                            declared_size,
                        )
                        return _preview_framed_html(pid, starting=False, status_code=502)

                    chunks: list[bytes] = []
                    received = 0
                    async for chunk in up.aiter_bytes():
                        received += len(chunk)
                        if received > _PREVIEW_MAX_RESPONSE_BYTES:
                            logger.warning(
                                "preview project %s response exceeded %s bytes",
                                pid,
                                _PREVIEW_MAX_RESPONSE_BYTES,
                            )
                            return _preview_framed_html(pid, starting=False, status_code=502)
                        chunks.append(chunk)
                    content = b"".join(chunks)
    except (httpx.ConnectError, httpx.ReadError, httpx.RemoteProtocolError):
        # Server registered but not yet accepting (or mid-boot) — treat as "starting".
        return _preview_framed_html(pid, starting=True)
    except httpx.HTTPError as e:
        logger.info("preview upstream error for project %s: %s", pid, e)
        return _preview_framed_html(pid, starting=False, status_code=502)
    if "text/html" in ctype.lower():
        content = _inject_preview_base(content, pid, _preview_url(pid, server))
    response = Response(content=content, status_code=up.status_code, headers=headers,
                        media_type=ctype or None)
    response.headers["Cache-Control"] = "no-store"
    # The sandboxed frame has an opaque ("null") origin, so module scripts and
    # crossorigin-attributed assets (every Vite/modern build) are fetched in CORS
    # mode and are DROPPED by the browser unless the response opts in. "*" is safe
    # here: the capability token in the path is the credential, and wildcard CORS
    # never exposes cookies (credentialed requests are forbidden with "*").
    response.headers["Access-Control-Allow-Origin"] = "*"
    # Explicit framing headers beat _security_headers()'s setdefault DENY/none so
    # the preview can be embedded same-origin inside Agents Chat.
    response.headers["X-Frame-Options"] = "SAMEORIGIN"
    # Enforce the opaque-origin sandbox at the HTTP boundary too. The iframe's
    # sandbox attribute alone did not protect a token URL opened top-level.
    response.headers["Content-Security-Policy"] = (
        "sandbox allow-scripts allow-forms allow-popups allow-downloads; "
        "frame-ancestors 'self'"
    )
    return response


# ------------------------- Project test runs (Phase 3) -------------------------
# Run a project's own test suite in its workspace folder and land the result in
# the chat as a pass/fail card, so a change an agent just made is verified where
# the conversation is — not in a terminal the user has to go find.
_TESTS_TIMEOUT_S = int(os.environ.get("PROJECT_TESTS_TIMEOUT_S", "300"))
_TESTS_MAX_COMMAND = 500
_TESTS_TAIL_CHARS = 4000


def _test_command_at(folder: Path) -> Optional[str]:
    """Detect a test command at exactly this directory."""
    try:
        pkg = folder / "package.json"
        if pkg.is_file():
            data = json.loads(pkg.read_text())
            scripts = data.get("scripts") if isinstance(data, dict) else {}
            if isinstance(scripts, dict) and scripts.get("test"):
                return "npm test"
            # Replit/Vite exports often have no test script but do expose the
            # two deterministic gates that matter for a build: TypeScript and
            # the production bundle. Do not call that "no verification" and
            # send the implementer through the same repair round forever.
            if isinstance(scripts, dict) and scripts.get("check") and scripts.get("build"):
                return "npm run check && npm run build"
            if isinstance(scripts, dict) and scripts.get("check"):
                return "npm run check"
            if isinstance(scripts, dict) and scripts.get("build"):
                return "npm run build"
        if (folder / "pytest.ini").is_file():
            return "python3 -m pytest -q"
        pyproject = folder / "pyproject.toml"
        if pyproject.is_file() and "pytest" in pyproject.read_text(errors="replace"):
            return "python3 -m pytest -q"
        tests_dir = folder / "tests"
        if tests_dir.is_dir() and any(tests_dir.glob("test_*.py")):
            return "python3 -m pytest -q"
        makefile = folder / "Makefile"
        if makefile.is_file() and re.search(r"^test:", makefile.read_text(errors="replace"), re.M):
            return "make test"
    except (OSError, ValueError):
        pass
    return None


def _detect_test_target(folder: Path) -> tuple[Path, Optional[str]]:
    """Find an unambiguous test root at the workspace root or one level down."""
    direct = _test_command_at(folder)
    if direct:
        return folder, direct
    try:
        candidates = [
            (child, command)
            for child in sorted(folder.iterdir())
            if child.is_dir() and not child.is_symlink()
            for command in [_test_command_at(child)]
            if command
        ]
    except OSError:
        candidates = []
    return candidates[0] if len(candidates) == 1 else (folder, None)


def _detect_test_command(folder: Path) -> Optional[str]:
    """Best-effort command, including one unambiguous nested checkout."""
    return _detect_test_target(folder)[1]


def _test_summary_line(output: str, *, passed: bool, timed_out: bool) -> str:
    """One human line for the card header — prefer a runner's own tally line."""
    if timed_out:
        return f"Timed out after {_TESTS_TIMEOUT_S}s"
    lines = [ln.strip() for ln in (output or "").splitlines() if ln.strip()]
    if not lines:
        return "Tests passed" if passed else "Tests failed"
    for line in reversed(lines[-20:]):
        if re.search(r"\b\d+\s+(passed|failed|error|skipped)", line, re.I):
            return line[:200]
    return lines[-1][:200]


def _kill_process_tree(proc: "subprocess.Popen") -> None:
    """SIGTERM then SIGKILL the child's whole process GROUP, so a runner's worker
    processes die with it instead of detaching to init."""
    if proc.poll() is not None:
        return
    try:
        os.killpg(os.getpgid(proc.pid), signal.SIGTERM)
    except OSError:
        try: proc.terminate()
        except OSError: return
    try:
        proc.wait(timeout=5)
        return
    except subprocess.TimeoutExpired:
        pass
    try:
        os.killpg(os.getpgid(proc.pid), signal.SIGKILL)
    except OSError:
        try: proc.kill()
        except OSError: pass


def _run_project_tests(folder: Path, command: str) -> dict:
    """Blocking test run, executed off the event loop."""
    started = time.time()
    timed_out = False
    proc = None
    try:
        env = dict(os.environ)
        # Keep popular runners deterministic and non-interactive. CRA/Jest in
        # particular otherwise enters watch mode and looks like a hung button.
        env.update({"CI": "true", "BROWSER": "none", "PYTHONUNBUFFERED": "1"})
        # Popen, not run(): run()'s timeout path calls Popen.kill(), which signals
        # only the direct child — a test runner's workers (jest, pytest-xdist)
        # survive and leak. Own session + killpg is what actually reaps the tree.
        proc = subprocess.Popen(
            ["/bin/sh", "-lc", command], cwd=str(folder),
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            stdin=subprocess.DEVNULL, env=env,
            text=True, errors="replace", start_new_session=True,
        )
        try:
            output = proc.communicate(timeout=_TESTS_TIMEOUT_S)[0] or ""
            exit_code = int(proc.returncode)
        except subprocess.TimeoutExpired:
            timed_out = True
            exit_code = -1
            _kill_process_tree(proc)
            try:
                output = proc.communicate(timeout=5)[0] or ""
            except (subprocess.TimeoutExpired, ValueError, OSError):
                output = ""
            output += f"\n[timed out after {_TESTS_TIMEOUT_S}s — process tree terminated]"
    except OSError as e:
        timed_out = False
        exit_code = -1
        output = f"could not run tests: {e}"
    passed = (exit_code == 0) and not timed_out
    return {
        "passed": passed,
        "exit_code": exit_code,
        "timed_out": timed_out,
        "duration_ms": int((time.time() - started) * 1000),
        "output_tail": (output or "")[-_TESTS_TAIL_CHARS:],
        "summary": _test_summary_line(output, passed=passed, timed_out=timed_out),
    }


@app.post("/api/projects/{project_id}/tests/run")
async def api_run_project_tests(project_id: str, request: Request):
    """Run the project's tests in its workspace folder and post a pass/fail card to a chat."""
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        pid, project, err = _owned_project_or_404(project_id, request)
        if err: return err
        body = await _json_object_body(request, empty_ok=True)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if not _is_admin_user(user):
        return JSONResponse(
            {"error": "admin required to run host test processes"}, status_code=403,
        )
    folder_path, folder_error = _project_folder_for_user(project, user)
    if folder_error or folder_path is None:
        return JSONResponse({"error": folder_error or "attach a workspace folder first"}, status_code=400)
    try:
        cid = _parse_resource_id(body.get("chat_id"), "chat_id", allow_none=True)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if cid is None:
        cid = _active_chat_id_for_request(request)
    if not _chat_belongs_to_user(cid, user):
        return JSONResponse({"error": "chat not found"}, status_code=404)
    command = body.get("command")
    if command is not None and not isinstance(command, str):
        return JSONResponse({"error": "command must be a string"}, status_code=400)
    command = (command or "").strip()
    if len(command) > _TESTS_MAX_COMMAND:
        return JSONResponse({"error": f"command too long (max {_TESTS_MAX_COMMAND} chars)"}, status_code=400)
    if any(ch in command for ch in "\r\n\x00"):
        return JSONResponse({"error": "command may not contain newlines or null bytes"}, status_code=400)
    if command:
        test_folder = folder_path
    else:
        test_folder, command = _detect_test_target(folder_path)
    if not command:
        return JSONResponse(
            {"error": "could not detect a test command — pass one, e.g. \"npm test\" or \"pytest -q\""},
            status_code=400,
        )
    result = await asyncio.to_thread(_run_project_tests, test_folder, command)
    meta = {
        "kind": "test_run",
        "project_id": pid,
        "project_number": project.get("number"),
        "project_title": project.get("title"),
        "command": command,
        "working_dir": str(test_folder),
        **result,
    }
    icon = "✅" if result["passed"] else "❌"
    text = f"{icon} Tests {'passed' if result['passed'] else 'failed'} — {result['summary']}"
    entry = append_thread(cid, "system", None, "Tests", text, metadata=meta)
    await broadcast({"type": "test_run", "chat_id": cid, "ts": entry["ts"], **meta})
    return {"status": "ok", "chat_id": cid, **meta}


# ------------------------- Diff review (Phase 5: self-upgrade) -------------------------
# The last link in "agents build it, you approve it": summarise what actually
# changed in a project's repo and put it in the chat as a review card. Every git
# call here is READ-ONLY — nothing merges, commits, or pushes. Shipping stays a
# human action in the normal release flow, and the live tree is never a target.
_REVIEW_DIFF_CHARS = 12000
_REVIEW_MAX_FILES = 40


def _git(folder: Path, *args: str, timeout: int = 20) -> str:
    """Read-only git. Decoding never raises (a repo can hold non-UTF8 bytes);
    failures return "" — callers that need to distinguish "empty" from "broken"
    must probe explicitly (see _git_ok)."""
    try:
        out = subprocess.run(
            [
                "git", "-c", "core.fsmonitor=false",
                "-c", "core.hooksPath=/dev/null",
                "-C", str(folder), *args,
            ],
            capture_output=True, text=True, errors="replace", timeout=timeout,
        )
        return out.stdout if out.returncode == 0 else ""
    except (OSError, subprocess.SubprocessError):
        return ""


def _git_ok(folder: Path) -> bool:
    """Whether git can actually read this repo — so a broken or unreadable
    checkout reports an error instead of a confident "no changes"."""
    try:
        out = subprocess.run(
            [
                "git", "-c", "core.fsmonitor=false",
                "-c", "core.hooksPath=/dev/null",
                "-C", str(folder), "rev-parse", "--git-dir",
            ],
            capture_output=True, text=True, errors="replace", timeout=20,
        )
        return out.returncode == 0
    except (OSError, subprocess.SubprocessError):
        return False


def _review_repo_root(folder: Path) -> Optional[Path]:
    """The repo to review: the project workspace folder itself, else a single obvious
    checkout inside it (e.g. the agent-chat/ baseline clone)."""
    if (folder / ".git").exists():
        return folder
    try:
        candidates = [
            c for c in sorted(folder.iterdir())
            if not c.name.startswith(".") and (c / ".git").exists()
        ]
    except OSError:
        return None
    return candidates[0] if len(candidates) == 1 else None


def _untracked_review(repo: Path, *, char_budget: int) -> tuple[list[str], str, bool]:
    """Return bounded names/content for untracked regular files without symlinks."""
    raw = _git(repo, "ls-files", "--others", "--exclude-standard", "-z")
    names = [name for name in raw.split("\0") if name]
    blocks: list[str] = []
    truncated = len(names) > _REVIEW_MAX_FILES
    remaining = max(0, char_budget)
    for rel in names[:_REVIEW_MAX_FILES]:
        display = rel.replace("\r", "?").replace("\n", "?")[:240]
        path = repo / rel
        try:
            info = path.lstat()
        except OSError:
            continue
        if stat.S_ISLNK(info.st_mode):
            block = f"\n[untracked symlink: {display}]\n"
        elif not stat.S_ISREG(info.st_mode):
            block = f"\n[untracked non-regular file: {display}]\n"
        else:
            flags = os.O_RDONLY
            if hasattr(os, "O_NOFOLLOW"):
                flags |= os.O_NOFOLLOW
            try:
                fd = os.open(path, flags)
                with os.fdopen(fd, "rb") as handle:
                    data = handle.read(min(remaining + 1, _REVIEW_DIFF_CHARS + 1))
            except OSError:
                block = f"\n[untracked unreadable file: {display}]\n"
            else:
                if b"\x00" in data:
                    block = f"\n[untracked binary file: {display} ({info.st_size} bytes)]\n"
                else:
                    text = data.decode("utf-8", errors="replace")
                    block = f"\n[untracked file: {display} ({info.st_size} bytes)]\n{text}\n"
                    if len(data) > remaining or info.st_size > len(data):
                        block += "[content truncated]\n"
                        truncated = True
        if len(block) > remaining:
            blocks.append(block[:remaining])
            truncated = True
            remaining = 0
            break
        blocks.append(block)
        remaining -= len(block)
    return names, "".join(blocks), truncated


def _changelog_from_dirty(dirty: list[str]) -> list[str]:
    """Truthful fallback changelog for uncommitted agent work.

    Commit subjects remain the preferred wording. Before the agent commits,
    use Git's own status plus the path so the review card still contains a
    useful draft without inventing product claims.
    """
    lines: list[str] = []
    for row in dirty[:10]:
        status = row[:2]
        path = row[3:].strip() if len(row) > 3 else row.strip()
        if not path:
            continue
        if " -> " in path:
            action = "Rename"
        elif "D" in status:
            action = "Remove"
        elif status == "??" or "A" in status:
            action = "Add"
        else:
            action = "Update"
        lines.append(f"{action} {path}")
    return lines


def _git_review(folder: Path) -> dict:
    """Read-only summary of what changed on this repo's current branch."""
    repo = _review_repo_root(folder)
    if repo is None:
        return {"ok": False, "error": "no git repository in this workspace folder"}
    if not _git_ok(repo):
        return {"ok": False, "error": "git could not read this repository"}
    branch = _git(repo, "rev-parse", "--abbrev-ref", "HEAD").strip() or "(detached)"
    base = ""
    for cand in ("main", "master"):
        if cand != branch and _git(repo, "rev-parse", "--verify", "--quiet", cand).strip():
            base = cand
            break
    if not base:
        # Fall back to the remote's default branch: a repo whose trunk is named
        # anything else (trunk/develop), or a single-branch clone with no local
        # main, would otherwise look like it had nothing to review.
        head = _git(repo, "symbolic-ref", "--quiet", "refs/remotes/origin/HEAD").strip()
        ref = head.replace("refs/remotes/", "") if head else ""
        if ref and ref.rsplit("/", 1)[-1] != branch:
            base = ref
    if base:
        commits = [l for l in _git(repo, "log", "--oneline", f"{base}..HEAD").splitlines() if l.strip()]
        # Compare the WORKING TREE to the MERGE-BASE. Two-dot against the base tip
        # would report files base gained since the branch was cut as deletions by
        # the agent; three-dot would miss uncommitted work entirely. Merge-base
        # with a dirty tree gives exactly this branch's own changes.
        fork = _git(repo, "merge-base", base, "HEAD").strip() or base
        stat = _git(repo, "diff", "--no-ext-diff", "--no-textconv", "--stat", fork)
        diff = _git(repo, "diff", "--no-ext-diff", "--no-textconv", fork)
    else:
        # No base to compare against: the branch's own history is NOT pending
        # work, so don't present it as such. Only the working tree is "changes".
        commits = []
        stat = _git(repo, "diff", "--no-ext-diff", "--no-textconv", "--stat", "HEAD")
        diff = _git(repo, "diff", "--no-ext-diff", "--no-textconv", "HEAD")
    dirty = [l for l in _git(repo, "status", "--porcelain").splitlines() if l.strip()]
    untracked_names, untracked_diff, untracked_truncated = _untracked_review(
        repo, char_budget=max(0, _REVIEW_DIFF_CHARS - len(diff)),
    )
    tracked_files = [l.strip() for l in stat.splitlines() if "|" in l]
    untracked_files = [
        f"{name.replace(chr(10), '?').replace(chr(13), '?')[:240]} | untracked"
        for name in untracked_names
    ]
    all_files = tracked_files + untracked_files
    files = all_files[:_REVIEW_MAX_FILES]
    totals = next((l.strip() for l in reversed(stat.splitlines()) if "changed" in l), "")
    if untracked_names:
        extra = f"{len(untracked_names)} untracked file{'' if len(untracked_names) == 1 else 's'}"
        totals = f"{totals}; {extra}" if totals else extra
    combined_diff = diff + untracked_diff
    return {
        "ok": True,
        "repo": str(repo),
        "repo_name": repo.name,
        "branch": branch,
        "base": base or None,
        "commits": commits[:20],
        "commit_count": len(commits),
        "files": files,
        "file_count": len(all_files),      # true total, not the display cap
        "files_truncated": len(all_files) > len(files),
        "totals": totals,
        "dirty_count": len(dirty),
        "dirty": [d[:120] for d in dirty[:_REVIEW_MAX_FILES]],
        "diff": combined_diff[:_REVIEW_DIFF_CHARS],
        "diff_truncated": (
            len(combined_diff) > _REVIEW_DIFF_CHARS or untracked_truncated
        ),
        # Prefer the branch's own commit subjects. Before anything is committed,
        # fall back to factual Git status/path lines rather than an empty draft.
        "changelog_draft": (
            [c.split(" ", 1)[1] for c in commits[:10] if " " in c]
            or _changelog_from_dirty(dirty)
        ),
    }


@app.post("/api/projects/{project_id}/review")
async def api_review_project_changes(project_id: str, request: Request):
    """Summarise a project repo's changes and post a review card to the chat."""
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        pid, project, err = _owned_project_or_404(project_id, request)
        if err: return err
        body = await _json_object_body(request, empty_ok=True)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if not _is_admin_user(user):
        return JSONResponse(
            {"error": "admin required to run host git processes"}, status_code=403,
        )
    folder_path, folder_error = _project_folder_for_user(project, user)
    if folder_error or folder_path is None:
        return JSONResponse({"error": folder_error or "attach a workspace folder first"}, status_code=400)
    try:
        cid = _parse_resource_id(body.get("chat_id"), "chat_id", allow_none=True)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if cid is None:
        cid = _active_chat_id_for_request(request)
    if not _chat_belongs_to_user(cid, user):
        return JSONResponse({"error": "chat not found"}, status_code=404)
    review = await asyncio.to_thread(_git_review, folder_path)
    if not review.get("ok"):
        return JSONResponse({"error": review.get("error") or "review failed"}, status_code=400)
    meta = {
        "kind": "diff_review",
        "project_id": pid,
        "project_title": project.get("title"),
        **{k: v for k, v in review.items() if k != "ok"},
    }
    if review["file_count"]:
        headline = (
            f"{review['file_count']} file{'' if review['file_count'] == 1 else 's'} changed"
            f" on {review['branch']}"
        )
    elif review["dirty_count"]:
        # e.g. untracked-only work: real changes that a diff --stat cannot show.
        headline = (
            f"{review['dirty_count']} uncommitted path"
            f"{'' if review['dirty_count'] == 1 else 's'} on {review['branch']}"
        )
    elif review["commit_count"]:
        headline = (
            f"{review['commit_count']} commit"
            f"{'' if review['commit_count'] == 1 else 's'} on {review['branch']}"
        )
    else:
        headline = f"No changes on {review['branch']}"
    text = f"🔍 Review — {headline}"
    entry = append_thread(cid, "system", None, "Review", text, metadata=meta)
    await broadcast({"type": "diff_review", "chat_id": cid, "ts": entry["ts"],
                     "text": text, **meta})
    return {"status": "ok", "chat_id": cid, **meta}


@app.post("/api/projects/assign")
async def api_assign_chats_project(request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        body = await _json_object_body(request)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    raw_chat_ids = body.get("chat_ids")
    if not isinstance(raw_chat_ids, list) or not raw_chat_ids:
        return JSONResponse({"error": "chat_ids must be a non-empty list"}, status_code=400)
    if len(raw_chat_ids) > 1000:
        return JSONResponse({"error": "chat_ids may contain at most 1000 ids"}, status_code=400)
    try:
        chat_ids = [
            _parse_resource_id(value, f"chat_ids[{index}]")
            for index, value in enumerate(raw_chat_ids)
        ]
        if "project_id" not in body:
            raise ValueError("project_id required")
        project_id = _parse_resource_id(
            body.get("project_id"), "project_id", allow_none=True,
        )
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    chat_ids = list(dict.fromkeys(chat_ids))
    try:
        pid = _assign_chats_project(chat_ids, project_id, int(user["id"]))
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    except KeyError as e:
        return JSONResponse({"error": str(e).strip("'")}, status_code=404)
    project = _project_row(pid) if pid is not None else None
    bound = _ensure_project_folder(project, user)
    if bound:
        project = bound
        await broadcast({
            "type": "project_meta",
            "owner_user_id": int(user["id"]),
            "project": project,
        }, global_event=True)
        await _rehome_project_member_chats(int(pid))
    await broadcast({
        "type": "project_assignment",
        "owner_user_id": int(user["id"]),
        "chat_ids": chat_ids,
        "project_id": pid,
    }, global_event=True)
    return {
        "status": "ok",
        "chat_ids": chat_ids,
        "project_id": pid,
        "project": project,
    }


