_LOOPBACK_HOSTS = {"127.0.0.1", "::1", "localhost"}
_HOST_ADDRESS_CACHE: dict[str, tuple[bool, float]] = {}
_HOST_ADDRESS_TTL = 300.0


def _address_belongs_to_this_host(ip: str) -> bool:
    """True when `ip` is an address this very machine answers on.

    Binding a throwaway UDP socket to the address is the stdlib-only way to ask
    the kernel "is this one of mine?": it succeeds for loopback, the LAN address
    and the Tailscale address, and fails for every other peer. Cached, because
    the answer only changes when an interface does.
    """
    ip = (ip or "").lower().split("%", 1)[0]
    if not ip:
        return False
    if ip in _LOOPBACK_HOSTS:
        return True
    now = time.time()
    cached = _HOST_ADDRESS_CACHE.get(ip)
    if cached and now - cached[1] < _HOST_ADDRESS_TTL:
        return cached[0]
    try:
        family = socket.AF_INET6 if ":" in ip else socket.AF_INET
        with socket.socket(family, socket.SOCK_DGRAM) as probe:
            probe.bind((ip, 0))
        mine = True
    except OSError:
        mine = False
    _HOST_ADDRESS_CACHE[ip] = (mine, now)
    return mine


def _native_folder_picker_request_is_local(request: Request) -> bool:
    """Native dialogs only make sense in a browser opened on this computer.

    The test is the client address: a browser on this Mac reaches the app from
    one of the Mac's own addresses, whichever route it took — loopback, the LAN
    IP, or the Tailscale IP. (Requiring loopback alone rejected the everyday
    case: the app is normally opened at its own Tailscale HTTPS address, which
    arrives as the host's tailnet IP even when the browser is sitting here.)

    `request.client` is already the address uvicorn resolved from the local
    Tailscale relay's X-Forwarded-For — it walks that list from the right and
    stops at the first host outside `forwarded_allow_ips`, so a remote client
    cannot pass itself off as the Mac by sending its own header (verified: a
    spoofed `X-Forwarded-For` is appended to, not honoured). The one shape that
    would fool us is a relay hop whose header was NOT resolved, which leaves the
    proxy's own loopback address in `client` — refuse those, because behind them
    could be a phone anywhere in the world.
    """
    client_host = ((request.client.host if request.client else "") or "").lower()
    request_host = (request.url.hostname or "").lower()
    if client_host == "testclient" and request_host == "testserver":
        return True
    relayed = any(
        request.headers.get(header)
        for header in ("x-forwarded-for", "forwarded", "x-real-ip")
    )
    if relayed and client_host in _LOOPBACK_HOSTS:
        return False
    return _address_belongs_to_this_host(client_host)


def _pick_folder_on_host(prompt: str) -> tuple[Optional[str], Optional[str]]:
    """Open the operating system's folder chooser.

    Returns (path, error). (None, None) means the user cancelled. No selected
    path is logged, and every returned path is still authorization-checked by
    `_validated_workspace_path` before the API exposes it.
    """
    command: Optional[list[str]] = None
    if sys.platform == "darwin":
        command = [
            "osascript", "-e",
            f'POSIX path of (choose folder with prompt "{prompt}")',
        ]
    elif os.name == "nt":
        ps_prompt = prompt.replace("'", "''")
        script = (
            "Add-Type -AssemblyName System.Windows.Forms; "
            "$d = New-Object System.Windows.Forms.FolderBrowserDialog; "
            f"$d.Description = '{ps_prompt}'; "
            "$d.ShowNewFolderButton = $true; "
            "if ($d.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { "
            "[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; "
            "Write-Output $d.SelectedPath; exit 0 }; exit 2"
        )
        command = ["powershell.exe", "-NoProfile", "-STA", "-Command", script]
    elif shutil.which("zenity"):
        command = ["zenity", "--file-selection", "--directory", f"--title={prompt}"]
    else:
        return None, "Folder selection is available in the macOS and Windows desktop builds."

    try:
        result = subprocess.run(
            command, capture_output=True, text=True, timeout=300,
        )
    except subprocess.TimeoutExpired:
        return None, "The folder chooser timed out. Please try again."
    except OSError:
        return None, "The folder chooser could not be opened on this computer."

    if result.returncode != 0:
        # AppleScript uses -128 for User canceled; PowerShell and zenity use a
        # small non-zero code. Treat every quiet chooser exit as cancellation.
        detail = (result.stderr or "").lower()
        if result.returncode in (1, 2, -128) or "cancel" in detail:
            return None, None
        return None, "The folder chooser could not be opened on this computer."
    selected = (result.stdout or "").strip()
    return (selected, None) if selected else (None, None)


@app.post("/api/workspaces/pick-folder")
async def api_pick_workspace_folder(request: Request):
    """Let a local admin choose an existing host folder with the native OS UI."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    if not _native_folder_picker_request_is_local(request):
        return JSONResponse(
            {
                "error": (
                    "This browser is reaching Agents Chat from another device, so the "
                    "folder chooser can't open on the computer that holds the folders. "
                    "Open Agents Chat on that computer to attach one."
                )
            },
            status_code=400,
        )
    try:
        body = await _json_object_body(request)
    except ValueError as exc:
        return JSONResponse({"error": str(exc)}, status_code=400)
    purpose = str(body.get("purpose") or "chat").strip().lower()
    if purpose not in {"chat", "project"}:
        return JSONResponse({"error": "purpose must be chat or project"}, status_code=400)
    prompt = "Choose a project workspace folder" if purpose == "project" else "Choose a workspace folder for this chat"
    selected, picker_error = await asyncio.to_thread(_pick_folder_on_host, prompt)
    if picker_error:
        return JSONResponse({"error": picker_error}, status_code=503)
    if not selected:
        return {"ok": True, "cancelled": True}
    validated, validation_error = _validated_workspace_path(selected, _current_user(request))
    if validation_error or validated is None:
        return JSONResponse(
            {"error": validation_error or "That workspace folder cannot be used by Agents Chat."},
            status_code=400,
        )
    return {"ok": True, "cancelled": False, "path": str(validated), "name": validated.name}


@app.get("/api/chats/{cid}/secret-folders")
async def api_chat_secret_folders(cid: int, request: Request):
    """Which credential folders this chat is scoped to, what they contain, and
    which agents in the room are missing a key from them.

    Names only — no endpoint anywhere returns a secret value. The `gaps` list is
    the answer to "why can't the agent see it": the credential exists and the
    folder is scoped, but this particular agent was never granted it.
    """
    blocked = _require_chat_access(request, cid)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    owner_id = _chat_owner_id(cid) or int(user["id"])
    view = _chat_folder_secret_view(cid, int(owner_id))
    view["status"] = "ok"
    view["chat_id"] = cid
    view["can_grant"] = _is_admin_user(user)
    return view


@app.post("/api/chats/{cid}/secret-folders")
async def api_set_chat_secret_folders(cid: int, request: Request):
    """Scope this chat to credential folders, and optionally close the gaps.

    Body: {"folders": ["Example Company"], "grant": false}.

    Pinning alone moves nothing — it only tells the prompt builder which
    credential family is this conversation's working set, which is what stops an
    agent from claiming it has no access to a service the owner already holds
    keys for. Passing grant=true additionally copies every key in those folders
    onto every agent in this chat that is missing one; that genuinely
    distributes credentials, so it is admin-only and never implicit.
    """
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_chat_access(request, cid)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        body = await request.json()
    except Exception:
        body = {}
    raw = body.get("folders")
    if raw is not None and not isinstance(raw, list):
        return JSONResponse({"error": "folders must be a list"}, status_code=400)
    for item in (raw or []):
        _folder, err = _clean_secret_folder(item)
        if err:
            return JSONResponse({"error": err}, status_code=400)

    owner_id = int(_chat_owner_id(cid) or int(user["id"]))
    known = set(_secret_folders_for_owner(owner_id))
    requested = _set_chat_secret_folders(cid, list(raw or []))
    # A folder that no key names any more is kept as a pin (harmless, and it
    # starts working again the moment a key is filed there) but reported so the
    # UI can show it as empty rather than silently doing nothing.
    empty = [f for f in requested if f not in known]

    granted: list[dict] = []
    grant_errors: list[dict] = []
    wants_grant = bool(body.get("grant"))
    if wants_grant and not _is_admin_user(user):
        return JSONResponse(
            {"error": "admin required to grant credentials to this chat's agents"},
            status_code=403,
        )
    if wants_grant:
        view = _chat_folder_secret_view(cid, owner_id)
        async with _SECRET_MUTATION_LOCK:
            for gap in view["gaps"]:
                key = gap["key"]
                value = _recover_secret_value(owner_id, key)
                if not value:
                    grant_errors.append({
                        "key": key,
                        "error": "value can’t be read back automatically; re-enter it in Secrets",
                    })
                    continue
                for aid in gap["missing_agent_ids"]:
                    if _secret_agent_is_shared(owner_id, aid) or \
                            _secret_slot_has_other_owner(owner_id, key, aid):
                        grant_errors.append({
                            "key": key, "agent_id": aid,
                            "error": "that agent's secret slot belongs to another user",
                        })
                        continue
                    status, err = await _set_secret_with_grant(
                        owner_id, key, aid, value,
                    )
                    if status == "ok":
                        granted.append({"key": key, "agent_id": aid})
                    else:
                        grant_errors.append({
                            "key": key, "agent_id": aid,
                            "error": err or "secret copy failed",
                        })

    _audit_event(
        request, "chat.secret_folders", chat_id=cid,
        actor=user.get("email") or "user",
        target=", ".join(requested) or "none", status="ok",
        meta={"folders": requested, "granted": granted,
              "grant_errors": grant_errors, "owner_user_id": owner_id},
    )
    view = _chat_folder_secret_view(cid, owner_id)
    await broadcast({
        "type": "chat_meta", "chat_id": cid,
        "secret_folders": requested,
    }, global_event=True)
    return {
        "status": "ok",
        "chat_id": cid,
        "folders": requested,
        # Mirrors the GET payload. Without it the client loses the flag on the
        # very response that first reports a gap, and the "give them access"
        # button vanishes at the moment it becomes useful.
        "can_grant": _is_admin_user(user),
        "empty_folders": empty,
        "granted": granted,
        "grant_errors": grant_errors,
        "restart_needed": _secret_restart_entries(
            sorted({g["agent_id"] for g in granted}), owner_id,
        ),
        **{k: v for k, v in view.items() if k != "folders"},
    }


@app.post("/api/chats/{cid}/workspace")
async def api_set_chat_workspace(cid: int, request: Request):
    """Bind this chat to a project dir (absolute path) or clear to the per-chat
    scratch. Body: {"workspace": "/abs/path"} to bind, {"workspace": ""} (or
    "default") to clear. Persisted; broadcasts chat_meta so other clients update."""
    blocked = _require_origin(request)
    if blocked: return blocked
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    try:
        body = await request.json()
    except Exception:
        body = {}
    raw = body.get("workspace")
    if raw is not None and not isinstance(raw, str):
        return JSONResponse({"error": "workspace must be a string path or empty"}, status_code=400)
    cleaned = (raw or "").strip()
    if cleaned not in ("", "default", "scratch"):
        validated, error = _validated_workspace_path(cleaned, _current_user(request))
        if error or validated is None:
            return JSONResponse({"error": error or "invalid workspace"}, status_code=400)
        cleaned = str(validated)
    _set_chat_workspace(cid, cleaned)
    info = _chat_workspace_info(cid)
    _sync_scratch_tombstone(cid)
    ws = info["path"]
    is_default = info["source"] != "chat"
    await broadcast({
        "type": "chat_meta", "chat_id": cid,
        "workspace": ws, "workspace_is_default": is_default,
        "workspace_source": info["source"],
    }, global_event=True)
    return {
        "status": "ok", "workspace": ws, "is_default": is_default,
        "source": info["source"], "project_id": info["project_id"],
        "branch": _git_branch(ws),
    }


def _open_command_for(agent_id: str, cid: int) -> dict:
    """Resolve how to "open an agent in its own UI" for this chat. Returns a
    dict describing the action: a web URL (works anywhere, incl. mobile), a
    host launch (argv to run on the Mac mini for desktop surfaces), and a
    copyable command (for the mobile "do it yourself" fallback)."""
    cap = _agent_capabilities(agent_id, cid)
    ui = cap.get("ui") or {}
    surface = ui.get("surface", "none")
    ws = cap.get("workspace")
    if surface == "web":
        return {"surface": "web", "url": ui.get("url"), "argv": None, "command": None}
    if surface == "desktop":
        kind = ui.get("kind")
        if kind == "app":
            app_name = ui.get("app", "")
            argv = ["open", "-a", app_name] if app_name else None
            return {"surface": "desktop", "url": None, "argv": argv,
                    "command": (f'open -a "{app_name}"' if app_name else None)}
        # terminal-or-ide / ide → open a Terminal at the workspace, with a
        # launch hint per agent so the user lands ready to drive that CLI.
        launch = {"claude": "claude", "codex": "codex", "antigravity": "agy", "grok": "grok"}.get(agent_id, "")
        parts = []
        if ws:
            parts.append(f"cd {shlex.quote(ws)}")
        if launch:
            parts.append(launch)
        command = " && ".join(parts) if parts else None
        argv = None
        if command:
            # Defense-in-depth: escape for the AppleScript string literal so a
            # workspace path can never break out of the `do script "…"` quotes
            # even if source validation is bypassed. (ws is also validated at the
            # setter to forbid quotes/backslashes/controls.)
            as_command = command.replace("\\", "\\\\").replace('"', '\\"')
            script = f'tell application "Terminal" to do script "{as_command}"'
            argv = ["osascript", "-e", script, "-e", 'tell application "Terminal" to activate']
        return {"surface": "desktop", "url": None, "argv": argv, "command": command}
    return {"surface": "none", "url": None, "argv": None, "command": None}


@app.post("/api/agents/{agent_id}/open")
async def api_agent_open(agent_id: str, request: Request):
    """Open an agent in its own UI (Phase 2). Web surfaces (Lead/Sales) return a
    URL the client opens — works on mobile too. Desktop surfaces (the CLI agents,
    MiniMax Code) launch on the Mac mini when the caller is local; a remote caller
    (phone over Tailscale) gets a 'remote' result with a copyable command unless
    it passes ?on_mini=1 to launch on the host deliberately."""
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    if agent_id not in AGENTS_BY_ID:
        return JSONResponse({"error": "unknown agent"}, status_code=404)
    if agent_id not in _allowed_agent_ids_for_user(user):
        return JSONResponse({"error": "unknown agent"}, status_code=404)
    cid = _active_chat_id_for_request(request)
    plan = _open_command_for(agent_id, cid)
    surface = plan["surface"]
    if surface == "web" and plan["url"]:
        return {"action": "open_url", "url": plan["url"]}
    if surface == "desktop":
        on_mini = request.query_params.get("on_mini") in ("1", "true", "yes")
        # A desktop plan can launch Terminal/AppleScript on the service host.
        # Regular users may receive the copyable command for their own managed
        # workspace, but can never make the shared Mac execute it.
        if not _is_admin_user(user):
            if on_mini:
                return JSONResponse(
                    {"error": "admin required to launch host applications"},
                    status_code=403,
                )
            return {"action": "remote", "surface": "desktop",
                    "command": plan["command"], "workspace": _chat_workspace(cid)}
        if not _client_is_local(request) and not on_mini:
            return {"action": "remote", "surface": "desktop",
                    "command": plan["command"], "workspace": _chat_workspace(cid)}
        if plan["argv"]:
            try:
                subprocess.Popen(
                    plan["argv"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                    stdin=subprocess.DEVNULL, start_new_session=True,
                )
                return {"action": "launched", "command": plan["command"]}
            except Exception as e:
                return JSONResponse({"error": f"launch failed: {e}"}, status_code=500)
        return JSONResponse({"error": "no launch command available for this agent"}, status_code=400)
    return {"action": "none", "reason": "this agent has no separate UI to open"}


@app.post("/api/projects/{project_id}/events")
async def api_create_project_event(project_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        project_id_int = _parse_resource_id(project_id, "project_id")
        body = await _json_object_body(request)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    project_id = project_id_int
    if not _project_belongs_to_user(project_id, user):
        return JSONResponse({"error": "project not found"}, status_code=404)
    raw_title = body.get("title")
    raw_due_label = body.get("due_label")
    if raw_title is not None and not isinstance(raw_title, str):
        return JSONResponse({"error": "title must be a string"}, status_code=400)
    if raw_due_label is not None and not isinstance(raw_due_label, str):
        return JSONResponse({"error": "due_label must be a string"}, status_code=400)
    title = (raw_title or "").strip()
    due_label = (raw_due_label or "").strip()
    if not title:
        return JSONResponse({"error": "title required"}, status_code=400)
    if len(title) > 220:
        return JSONResponse({"error": "title too long (max 220 characters)"}, status_code=400)
    if len(due_label) > 120:
        return JSONResponse({"error": "due_label too long (max 120 characters)"}, status_code=400)
    owner_agent_id = body.get("owner_agent_id")
    if owner_agent_id is not None:
        if not isinstance(owner_agent_id, str) or owner_agent_id not in _allowed_agent_ids_for_user(user):
            return JSONResponse({"error": "unknown owner_agent_id"}, status_code=400)
    source_text = body.get("source_text")
    if source_text is not None and not isinstance(source_text, str):
        return JSONResponse({"error": "source_text must be a string"}, status_code=400)
    if isinstance(source_text, str) and len(source_text) > 500:
        return JSONResponse({"error": "source_text too long (max 500 characters)"}, status_code=400)
    try:
        chat_id = _parse_resource_id(
            body.get("chat_id"), "chat_id", allow_none=True,
        ) if "chat_id" in body else None
        due_ts = _parse_optional_timestamp(body.get("due_ts"), "due_ts")
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if chat_id is not None and not _chat_belongs_to_user(chat_id, user):
        return JSONResponse({"error": "chat not found"}, status_code=404)
    try:
        event = _create_project_event(
            title=title,
            due_label=due_label or "unspecified",
            due_ts=due_ts,
            project_id=project_id,
            chat_id=chat_id,
            owner_agent_id=owner_agent_id,
            source_text=source_text,
            owner_user_id=int(user["id"]),
        )
    except KeyError as e:
        return JSONResponse({"error": str(e).strip("'")}, status_code=404)
    await broadcast({"type": "project_meta", "event": event,
                     "owner_user_id": int(user["id"])}, global_event=True)
    return {"status": "ok", "event": event}


@app.patch("/api/project-events/{event_id}")
async def api_update_project_event(event_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    try:
        event_id_int = _parse_resource_id(event_id, "event_id")
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    event_id = event_id_int
    if _event_owner_id(event_id) != int(user["id"]):
        return JSONResponse({"error": "event not found or no valid updates"}, status_code=404)
    try:
        body = await _json_object_body(request)
        if "title" in body:
            if not isinstance(body["title"], str) or not body["title"].strip():
                raise ValueError("title must be a non-empty string")
            if len(body["title"].strip()) > 220:
                raise ValueError("title too long (max 220 characters)")
            body["title"] = body["title"].strip()
        if "due_label" in body:
            if not isinstance(body["due_label"], str):
                raise ValueError("due_label must be a string")
            if len(body["due_label"].strip()) > 120:
                raise ValueError("due_label too long (max 120 characters)")
            body["due_label"] = body["due_label"].strip()
        if "due_ts" in body:
            body["due_ts"] = _parse_optional_timestamp(body["due_ts"], "due_ts")
        if "owner_agent_id" in body:
            owner = body["owner_agent_id"]
            if owner is not None and (
                not isinstance(owner, str)
                or owner not in _allowed_agent_ids_for_user(user)
            ):
                raise ValueError("unknown owner_agent_id")
        if "status" in body and body["status"] not in ("planned", "active", "done", "blocked"):
            raise ValueError("invalid status")
        if "project_id" in body:
            target_project_id = _parse_resource_id(
                body.get("project_id"), "project_id", allow_none=True,
            )
            if target_project_id is not None and not _project_belongs_to_user(target_project_id, user):
                return JSONResponse({"error": "project not found"}, status_code=404)
            body["project_id"] = target_project_id
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    event = _update_project_event(event_id, body, owner_user_id=int(user["id"]))
    if not event:
        return JSONResponse({"error": "event not found or no valid updates"}, status_code=404)
    await broadcast({"type": "project_meta", "event": event,
                     "owner_user_id": int(user["id"])}, global_event=True)
    return {"status": "ok", "event": event}


@app.get("/api/chats/{cid}/artifacts")
async def api_chat_artifacts(cid: int, request: Request):
    """Unified Files view for a chat: user uploads (attachments/) PLUS agent-created
    canvas output (artifacts_store/), so the Files folder is the single place that
    shows every file in the chat. Bytes aren't moved — each keeps its serving path
    (/attachments/… or /artifacts/…); we just merge the listings."""
    _refresh_index_from_storage()
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    artifacts = _list_attachment_meta(cid) + _canvas_artifacts_as_files(cid)
    artifacts.sort(key=lambda a: a.get("ts") or 0, reverse=True)
    return {"status": "ok", "chat_id": cid, "artifacts": artifacts}


# ----- Shared search tools (web + Reddit) ----------------------------------
# One deterministic search capability for every agent and the orchestrator.
# Callable by a logged-in UI user OR an agent presenting its X-API-KEY token.
def _email_tool_access_token(
    cid, agent_id: str, *, time_bucket: Optional[int] = None,
) -> str:
    """Per-AGENT (not per-chat) token for the email belt tool. Unlike the shared
    web-search token, this binds to a specific agent id — so an agent can only
    ever search the ONE mailbox its own vault holds a credential for, and cannot
    forge a token for another agent to read a different inbox."""
    bucket = int(time.time() // 86400) if time_bucket is None else int(time_bucket)
    msg = f"emailsearch:{int(cid)}:{agent_id}:{bucket}".encode()
    return hmac.new(_attachment_url_secret().encode(), msg, hashlib.sha256).hexdigest()[:32]


def _email_tool_token_ok(cid, agent_id: str, token: str) -> bool:
    if not (token and agent_id):
        return False
    try:
        cid = int(cid)
    except (TypeError, ValueError):
        return False
    if not _chat_row_is_live(cid):
        return False
    if agent_id not in _allowed_agent_ids_for_chat(cid):
        return False
    try:
        bucket = int(time.time() // 86400)
        expected = [
            _email_tool_access_token(cid, agent_id, time_bucket=bucket),
            _email_tool_access_token(cid, agent_id, time_bucket=bucket - 1),
        ]
    except Exception:
        return False
    return any(secrets.compare_digest(candidate, token) for candidate in expected)


def _agent_tool_caller_id(request: Request):
    """Resolve + authorize the calling agent for a per-AGENT belt tool (calendar,
    contacts, email send). Returns (agent_id, None) on success, or (None, JSONResponse)
    on failure. Same trust model as the email search endpoint: a logged-in owner acts
    on one of their own agents; an agent presents its own X-API-KEY or the signed
    ?cid=&agent=&k= token — either way it can only ever be ITS OWN id."""
    user = _current_user(request)
    if user:
        agent_id = (request.query_params.get("agent") or "").strip() or None
        if not agent_id:
            return None, JSONResponse({"error": "no agent specified"}, status_code=400)
        if agent_id not in _allowed_agent_ids_for_user(user):
            return None, JSONResponse({"error": "not your agent"}, status_code=403)
        return agent_id, None
    tok_agent = _agent_from_token(request.headers.get("x-api-key", ""))
    if tok_agent:
        return tok_agent.get("id"), None
    cid = _parse_cid_param(request.query_params.get("cid", ""))
    agent_id = (request.query_params.get("agent") or "").strip() or None
    k = (request.query_params.get("k") or "").strip()
    if not (cid is not None and agent_id and _email_tool_token_ok(cid, agent_id, k)):
        return None, JSONResponse({"error": "unauthorized"}, status_code=401)
    return agent_id, None


def _tool_caller(request: Request) -> Optional[dict]:
    user = _current_user(request)
    if user:
        return {"kind": "user", "id": user.get("id")}
    agent = _agent_from_token(request.headers.get("x-api-key", ""))
    if agent:
        return {"kind": "agent", "id": agent.get("id")}
    # Signed per-chat token (?cid=..&k=..) minted into the agents' prompt by
    # build_prompt — the only auth path agents can actually exercise, since they
    # hold no app token at the model level. Same model as attachment ?k= URLs.
    cid = _parse_cid_param(request.query_params.get("cid", ""))
    k = (request.query_params.get("k") or "").strip()
    if cid is not None and _live_web_tool_token_ok(cid, k):
        return {"kind": "chat", "id": cid}
    return None


def _tool_int(request: Request, name: str, default: int) -> int:
    try:
        return int(request.query_params.get(name, default))
    except (TypeError, ValueError):
        return default


# Two-layer throttle for the shared search tool. Per-caller: catches tight loops.
# 'chat' callers get a bigger bucket — every agent in a room shares one (an 8-agent
# counsel turn is a legitimate burst). Global daily budget: bounds AGGREGATE spend,
# because per-caller limits can't — a leaked non-expiring token would otherwise
# drain the Tavily month in under an hour (review finding). Env-tunable.
_TOOL_CALLS: "dict[str, deque]" = {}
_TOOL_RATE_MAX = 20
_TOOL_RATE_MAX_CHAT = int(os.environ.get("WEB_TOOL_CHAT_PER_MIN", "60"))
_TOOL_RATE_WINDOW = 60.0
_TOOL_DAILY_MAX = int(os.environ.get("WEB_TOOL_DAILY_MAX", "250"))
_TOOL_DAILY_WINDOW = 86400.0

# Crawling is local/free but browser-heavy. Keep a separate, tighter minute
# budget so a prompt loop cannot starve the app or the five Hermes containers.
_CRAWL_TOOL_CALLS: "dict[str, deque]" = {}
_CRAWL_TOOL_RATE_MAX = int(os.environ.get("CRAWL4AI_CALLS_PER_MIN", "6"))
_CRAWL_TOOL_RATE_MAX_CHAT = int(os.environ.get("CRAWL4AI_CHAT_CALLS_PER_MIN", "12"))
_CRAWL_TOOL_GLOBAL_MAX = int(os.environ.get("CRAWL4AI_GLOBAL_CALLS_PER_MIN", "24"))


def _tool_rate_limited(caller: dict, costs_quota: bool = True) -> bool:
    """Per-caller burst throttle, plus a global daily ceiling that ONLY the paid
    Tavily endpoints (web/reddit/fetch) debit. Free local tools (memory) pass
    costs_quota=False so their traffic can never 429 the paid endpoints."""
    now = time.monotonic()
    gdq = _TOOL_CALLS.setdefault("global", deque())
    if costs_quota:
        while gdq and now - gdq[0] > _TOOL_DAILY_WINDOW:
            gdq.popleft()
        if len(gdq) >= _TOOL_DAILY_MAX:
            return True
    kind = caller.get("kind")
    key = f"{kind}:{caller.get('id')}"
    cap = _TOOL_RATE_MAX_CHAT if kind == "chat" else _TOOL_RATE_MAX
    dq = _TOOL_CALLS.setdefault(key, deque())
    while dq and now - dq[0] > _TOOL_RATE_WINDOW:
        dq.popleft()
    if len(dq) >= cap:
        return True
    dq.append(now)
    if costs_quota:
        gdq.append(now)
    return False


def _crawl_tool_rate_limited(caller: dict) -> bool:
    now = time.monotonic()
    global_calls = _CRAWL_TOOL_CALLS.setdefault("global", deque())
    while global_calls and now - global_calls[0] > 60.0:
        global_calls.popleft()
    if len(global_calls) >= max(1, _CRAWL_TOOL_GLOBAL_MAX):
        return True
    key = f"{caller.get('kind')}:{caller.get('id')}"
    calls = _CRAWL_TOOL_CALLS.setdefault(key, deque())
    while calls and now - calls[0] > 60.0:
        calls.popleft()
    cap = _CRAWL_TOOL_RATE_MAX_CHAT if caller.get("kind") == "chat" else _CRAWL_TOOL_RATE_MAX
    if len(calls) >= max(1, cap):
        return True
    calls.append(now)
    global_calls.append(now)
    return False


def _memory_search(owner_user_id: Optional[int], query: str, limit: int = 8) -> list[dict]:
    """Search the owner's past chats (institutional memory) by message content.
    Owner-scoped — never crosses users. Mirrors the api_threads_search scan."""
    q = (query or "").strip()
    if not q or owner_user_id is None:
        return []
    ql = q.lower()
    chats = {
        c: ch for c, ch in (CHAT_INDEX.get("chats") or {}).items()
        if isinstance(ch, dict) and ch.get("owner_user_id") == owner_user_id
    }
    if not chats:
        return []
    limit = max(1, min(int(limit or 8), 25))
    cid_ints: list[int] = []
    for c in chats:
        try:
            cid_ints.append(int(c))
        except (TypeError, ValueError):
            pass
    hits: list = []
    with _db() as conn:
        for i in range(0, len(cid_ints), 400):  # stay under SQLite's variable cap
            chunk = cid_ints[i:i + 400]
            ph = ",".join("?" * len(chunk))
            hits.extend(conn.execute(
                f"SELECT id, chat_id, name, text, ts FROM messages "
                f"WHERE chat_id IN ({ph}) AND text IS NOT NULL AND instr(lower(text), ?) > 0 "
                f"AND (json_valid(metadata_json)=0 OR "
                f"COALESCE(json_extract(metadata_json, '$.sensor_id'), '') != 'memory_gap') "
                f"ORDER BY ts DESC, id DESC LIMIT ?",
                (*chunk, ql, limit * 3),
            ).fetchall())
    hits.sort(key=lambda r: r["ts"] or 0, reverse=True)
    out: list[dict] = []
    for r in hits[:limit]:
        c = str(r["chat_id"])
        title = str((chats.get(c) or {}).get("title") or f"#{c}")
        text = r["text"] or ""
        idx = text.lower().find(ql)
        start = max(0, idx - 80)
        snippet = ("…" if start else "") + text[start:idx + len(q) + 120].strip()
        out.append({
            "chat_id": r["chat_id"],
            "chat_title": title,
            "who": r["name"],
            "when": r["ts"],
            "snippet": snippet[:280],
        })
    return out


@app.get("/api/tools/web/search")
async def api_tools_web_search(request: Request):
    """General web search (Tavily) for agents + orchestrator.
    Params: q (required), count, site, depth (basic|advanced), topic (general|news),
    time (day|week|month|year)."""
    caller = _tool_caller(request)
    if not caller:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    if _tool_rate_limited(caller):
        return JSONResponse({"error": "rate limited — too many searches, slow down"}, status_code=429)
    q = (request.query_params.get("q") or request.query_params.get("query") or "").strip()
    if not q:
        return JSONResponse({"error": "missing query parameter (?q=)"}, status_code=400)
    try:
        res = await web_search.web_search(
            q,
            count=_tool_int(request, "count", 10),
            site=(request.query_params.get("site") or "").strip() or None,
            search_depth=(request.query_params.get("depth") or "basic").strip(),
            topic=(request.query_params.get("topic") or "general").strip(),
            time_range=(request.query_params.get("time") or "").strip() or None,
        )
    except web_search.WebSearchError as e:
        return JSONResponse({"error": str(e)}, status_code=502)
    return {"status": "ok", **res}


@app.get("/api/tools/reddit/search")
async def api_tools_reddit_search(request: Request):
    """Reddit search. Uses the official Reddit Data API when REDDIT_CLIENT_ID/SECRET
    are configured (structured results), else a reddit.com-scoped web search.
    Params: q (required), subreddit, sort, time, limit."""
    caller = _tool_caller(request)
    if not caller:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    if _tool_rate_limited(caller):
        return JSONResponse({"error": "rate limited — too many searches, slow down"}, status_code=429)
    q = (request.query_params.get("q") or request.query_params.get("query") or "").strip()
    if not q:
        return JSONResponse({"error": "missing query parameter (?q=)"}, status_code=400)
    limit = _tool_int(request, "limit", 25)
    try:
        if reddit_search.credentials_configured():
            res = await reddit_search.reddit_search(
                q,
                subreddit=(request.query_params.get("subreddit") or "").strip() or None,
                sort=(request.query_params.get("sort") or "relevance").strip(),
                time_filter=(request.query_params.get("time") or "all").strip(),
                limit=limit,
            )
            res["mode"] = "oauth"
        else:
            res = await web_search.reddit_web_search(q, count=limit)
            res["mode"] = "web"
    except (reddit_search.RedditError, web_search.WebSearchError) as e:
        return JSONResponse({"error": str(e)}, status_code=502)
    return {"status": "ok", **res}


