@app.get("/api/tools/crawl")
async def api_tools_crawl(request: Request):
    """Render one public JavaScript-heavy page through the local Crawl4AI worker.

    The model gets a signed, per-chat GET URL; this handler owns the private
    service token, URL/SSRF policy, safe request shape, concurrency, and output
    ceiling. Params: url (required), max_chars (1,000..60,000; default 30,000).
    """
    caller = _tool_caller(request)
    if not caller:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    if not crawl4ai_client.configured():
        return JSONResponse(
            {"error": "Crawl4AI is not configured or is not loopback-only"},
            status_code=503,
        )
    if _crawl_tool_rate_limited(caller):
        return JSONResponse({"error": "rate limited — too many crawls, slow down"}, status_code=429)
    target = (request.query_params.get("url") or "").strip()
    if not target:
        return JSONResponse({"error": "missing url parameter (?url=)"}, status_code=400)
    try:
        result = await crawl4ai_client.crawl_page(
            target, max_chars=_tool_int(request, "max_chars", 30_000)
        )
    except crawl4ai_client.Crawl4AIInputError as exc:
        return JSONResponse({"error": str(exc)}, status_code=400)
    except crawl4ai_client.Crawl4AIError as exc:
        return JSONResponse({"error": str(exc)}, status_code=502)
    return {"status": "ok", **result}


@app.get("/api/tools/memory/search")
async def api_tools_memory_search(request: Request):
    """Search the owner's past chats (institutional memory). Params: q (required), limit."""
    caller = _tool_caller(request)
    if not caller:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    # Free local scan — burst-limit per caller but don't debit the paid Tavily budget.
    if _tool_rate_limited(caller, costs_quota=False):
        return JSONResponse({"error": "rate limited — too many requests, slow down"}, status_code=429)
    q = (request.query_params.get("q") or request.query_params.get("query") or "").strip()
    if not q:
        return JSONResponse({"error": "missing query parameter (?q=)"}, status_code=400)
    if caller.get("kind") == "user":
        owner = caller.get("id")
    elif caller.get("kind") == "chat":
        owner = _chat_owner_id(caller.get("id"))
    else:
        owner = None
    results = _memory_search(owner, q, _tool_int(request, "limit", 8))
    return {"status": "ok", "query": q, "count": len(results), "results": results}


@app.get("/api/tools/email/search")
async def api_tools_email_search(request: Request):
    """Read-only search of the CALLING AGENT'S granted mailbox (Gmail / Workspace
    over IMAP, App Password — no OAuth). Per-AGENT scoped: an agent can only reach
    the one inbox its own vault holds a credential for, and cannot read another
    agent's. Params: q (Gmail search syntax, optional), limit, days, and full
    (full=1 adds each match's complete decoded `body`, not just the ~220-char
    snippet — needed to actually read a message, e.g. a forwarded notice nested
    under a cover note). Free/local — never debits the paid web quota; the mailbox
    is selected READ-ONLY."""
    # Resolve the calling agent. The signed URL here is per-AGENT (?cid=&agent=&k=),
    # unlike the shared per-chat web tools, so access can't leak between agents.
    agent_id = None
    user = _current_user(request)
    if user:  # a logged-in owner may test on behalf of one of their own agents
        agent_id = (request.query_params.get("agent") or "").strip() or None
        if agent_id and agent_id not in _allowed_agent_ids_for_user(user):
            return JSONResponse({"error": "not your agent"}, status_code=403)
    else:
        tok_agent = _agent_from_token(request.headers.get("x-api-key", ""))
        if tok_agent:
            agent_id = tok_agent.get("id")
        else:
            cid = _parse_cid_param(request.query_params.get("cid", ""))
            agent_id = (request.query_params.get("agent") or "").strip() or None
            k = (request.query_params.get("k") or "").strip()
            if not (cid is not None and agent_id and _email_tool_token_ok(cid, agent_id, k)):
                return JSONResponse({"error": "unauthorized"}, status_code=401)
    if not agent_id:
        return JSONResponse({"error": "no agent specified"}, status_code=400)
    if _tool_rate_limited({"kind": "email", "id": agent_id}, costs_quota=False):
        return JSONResponse({"error": "rate limited — slow down"}, status_code=429)
    mbox, merr = _resolve_mailbox(agent_id, request.query_params.get("mailbox"))
    if merr:
        return merr
    cfg = mbox["config"]  # read is the floor authority — any granted box may search
    q = (request.query_params.get("q") or request.query_params.get("query") or "").strip()
    full = (request.query_params.get("full") or "").strip().lower() in ("1", "true", "yes", "on")
    try:
        res = await asyncio.to_thread(
            imap_search.email_search, cfg["account"], cfg["password"], q,
            _tool_int(request, "limit", 20), _tool_int(request, "days", 14),
            "0", cfg["imap_host"], cfg["imap_port"], full,
        )
    except imap_search.EmailSearchError as e:
        return JSONResponse({"error": str(e)}, status_code=502)
    except Exception:
        logger.exception("email tool search failed for agent %s", agent_id)
        return JSONResponse({"error": "email search failed"}, status_code=502)
    return {"status": "ok", **res}


@app.post("/api/tools/email/send")
async def api_tools_email_send(request: Request):
    """SEND (or reply to) an email FROM the calling agent's OWN granted mailbox over
    SMTP — this transmits immediately (there is no draft step). Per-AGENT scoped
    exactly like the search tool: an agent can only send from the one mailbox its own
    vault holds a credential for, never another agent's. POST JSON body:
      {to, subject, body, cc?, bcc?, reply_to_msgid?, reply_query?, reply_all?}
    For a reply, pass reply_to_msgid (an `id` from the search tool) OR reply_query
    instead of to/subject — To/Re:/threading headers are filled in automatically.
    Non-Gmail sends are also copied into the mailbox's Sent folder."""
    agent_id = None
    user = _current_user(request)
    if user:  # a logged-in owner may send on behalf of one of their own agents
        agent_id = (request.query_params.get("agent") or "").strip() or None
        if agent_id and agent_id not in _allowed_agent_ids_for_user(user):
            return JSONResponse({"error": "not your agent"}, status_code=403)
    else:
        tok_agent = _agent_from_token(request.headers.get("x-api-key", ""))
        if tok_agent:
            agent_id = tok_agent.get("id")
        else:
            cid = _parse_cid_param(request.query_params.get("cid", ""))
            agent_id = (request.query_params.get("agent") or "").strip() or None
            k = (request.query_params.get("k") or "").strip()
            if not (cid is not None and agent_id and _email_tool_token_ok(cid, agent_id, k)):
                return JSONResponse({"error": "unauthorized"}, status_code=401)
    if not agent_id:
        return JSONResponse({"error": "no agent specified"}, status_code=400)
    if _tool_rate_limited({"kind": "email_send", "id": agent_id}, costs_quota=False):
        return JSONResponse({"error": "rate limited — slow down"}, status_code=429)
    mbox, merr = _resolve_mailbox(agent_id, request.query_params.get("mailbox"))
    if merr:
        return merr
    if not _mailbox_can(mbox, "send"):
        return JSONResponse(
            {"error": f"mailbox '{mbox['id']}' is {mbox['authority']}-only, not send-enabled"},
            status_code=403)
    cfg = mbox["config"]
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    body = str(payload.get("body") or "").strip()
    to = str(payload.get("to") or "").strip()
    reply_to_msgid = str(payload.get("reply_to_msgid") or payload.get("msgid") or "").strip()
    reply_query = str(payload.get("reply_query") or "").strip()
    if not body:
        return JSONResponse({"error": "body is required"}, status_code=400)
    if not (to or reply_to_msgid or reply_query):
        return JSONResponse(
            {"error": "specify 'to' for a new message, or 'reply_to_msgid'/'reply_query' to reply"},
            status_code=400,
        )
    try:
        res = await asyncio.to_thread(
            imap_compose.send_email, cfg,
            to=to,
            subject=str(payload.get("subject") or "").strip(),
            body=body,
            cc=str(payload.get("cc") or "").strip(),
            bcc=str(payload.get("bcc") or "").strip(),
            reply_to_msgid=reply_to_msgid,
            reply_query=reply_query,
            reply_all=bool(payload.get("reply_all")),
        )
    except imap_compose.EmailComposeError as e:
        return JSONResponse({"error": str(e)}, status_code=502)
    except Exception:
        logger.exception("email send failed for agent %s", agent_id)
        return JSONResponse({"error": "email send failed"}, status_code=502)
    _audit_event(request, "email.send", actor=str(agent_id), status="ok",
                 meta={"to": res.get("to"), "subject": res.get("subject"),
                       "host": res.get("host"), "mailbox": mbox["id"]})
    return {"status": "ok", "mailbox": mbox["id"], **res}


