@app.get("/api/tools/calendar/agent")
async def api_tools_calendar_agent(request: Request):
    """Read the calling agent's OWN CalDAV calendar — events in a time window
    (?days=30 by default, or explicit ?start=&end= as ISO datetime or epoch).
    Per-AGENT scoped: an agent only ever reads the calendar its own vault points at."""
    agent_id, err = _agent_tool_caller_id(request)
    if err:
        return err
    if _tool_rate_limited({"kind": "caldav", "id": agent_id}, costs_quota=False):
        return JSONResponse({"error": "rate limited — slow down"}, status_code=429)
    mbox, merr = _resolve_mailbox(agent_id, request.query_params.get("mailbox"))
    if merr:
        return merr
    if not mbox["caldav_url"]:
        return JSONResponse({"error": f"mailbox '{mbox['id']}' has no calendar configured"},
                            status_code=403)
    now = time.time()
    days = _tool_int(request, "days", 30)
    start = (request.query_params.get("start") or "").strip() or now
    end = (request.query_params.get("end") or "").strip() or (now + max(1, days) * 86400)
    try:
        res = await asyncio.to_thread(
            caldav_client.list_events, mbox["caldav_url"], mbox["caldav_username"],
            mbox["caldav_password"], start, end, _tool_int(request, "limit", 100),
        )
    except caldav_client.CalDavError as e:
        return JSONResponse({"error": str(e)}, status_code=502)
    except Exception:
        logger.exception("calendar tool failed for agent %s", agent_id)
        return JSONResponse({"error": "calendar read failed"}, status_code=502)
    return {"status": "ok", **res}


@app.post("/api/tools/calendar/agent/event")
async def api_tools_calendar_agent_event(request: Request):
    """Create an event on the calling agent's OWN CalDAV calendar. JSON body:
      {summary, start, end?, description?, location?}  (start/end: ISO datetime or epoch;
    a missing end defaults to start + 1h)."""
    agent_id, err = _agent_tool_caller_id(request)
    if err:
        return err
    if _tool_rate_limited({"kind": "caldav_write", "id": agent_id}, costs_quota=False):
        return JSONResponse({"error": "rate limited — slow down"}, status_code=429)
    mbox, merr = _resolve_mailbox(agent_id, request.query_params.get("mailbox"))
    if merr:
        return merr
    if not mbox["caldav_url"]:
        return JSONResponse({"error": f"mailbox '{mbox['id']}' has no calendar configured"},
                            status_code=403)
    if not _mailbox_can(mbox, "dav_write"):
        return JSONResponse(
            {"error": f"mailbox '{mbox['id']}' calendar is read-only (dav_authority=read)"},
            status_code=403)
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    summary = str(payload.get("summary") or payload.get("title") or "").strip()
    start = payload.get("start")
    if not summary:
        return JSONResponse({"error": "summary is required"}, status_code=400)
    if not start:
        return JSONResponse({"error": "start is required (ISO datetime or epoch)"}, status_code=400)
    try:
        res = await asyncio.to_thread(
            caldav_client.create_event, mbox["caldav_url"], mbox["caldav_username"],
            mbox["caldav_password"],
            summary=summary, start=start, end=payload.get("end"),
            description=str(payload.get("description") or "").strip(),
            location=str(payload.get("location") or "").strip(),
        )
    except caldav_client.CalDavError as e:
        return JSONResponse({"error": str(e)}, status_code=502)
    except Exception:
        logger.exception("calendar create failed for agent %s", agent_id)
        return JSONResponse({"error": "calendar create failed"}, status_code=502)
    _audit_event(request, "calendar.create", actor=str(agent_id), status="ok",
                 meta={"summary": summary, "uid": res.get("uid")})
    return {"status": "ok", **res}


