def _tool_caller_owner_and_chat(caller: dict) -> tuple[Optional[int], Optional[int]]:
    """(owner_user_id, chat_id) for a belt-tool caller. Chat callers (presigned
    ?k= URLs — i.e. agents) resolve to the chat's owner; user callers to themselves."""
    if caller.get("kind") == "user":
        return caller.get("id"), None
    if caller.get("kind") == "chat":
        cid = caller.get("id")
        return _chat_owner_id(cid), cid
    return None, None


@app.get("/api/tools/decisions/search")
async def api_tools_decisions_search(request: Request):
    """Search the owner's settled-decisions ledger (statement + rationale).
    Params: q (optional — empty lists the latest active entries), limit, all=1
    to include superseded history. Free local — never debits the web quota."""
    caller = _tool_caller(request)
    if not caller:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    if _tool_rate_limited(caller, costs_quota=False):
        return JSONResponse({"error": "rate limited — too many requests, slow down"}, status_code=429)
    owner, _cid = _tool_caller_owner_and_chat(caller)
    if owner is None:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    q = (request.query_params.get("q") or request.query_params.get("query") or "").strip()
    results = _get_team_decisions(
        owner, query=q, limit=_tool_int(request, "limit", 10),
        include_superseded=(request.query_params.get("all") or "").strip() == "1",
        chat_id=_cid,
    )
    if q and not results:
        results = _decision_token_fallback(
            owner, q, chat_id=_cid, limit=_tool_int(request, "limit", 10),
        )
    for r in results:
        r["date"] = time.strftime("%Y-%m-%d", time.localtime((r["created_ts"] or 0) / 1000))
    # Learn-on-miss telemetry: after literal and conservative token retrieval both
    # miss, record the lookup internally. Never auto-triage from inside the lookup.
    if q and not results:
        kind = caller.get("kind")
        asked_by = "user" if kind == "user" else (
            str(caller.get("id")) if kind == "agent" else f"chat:{caller.get('id')}"
        )
        ctx = (_control_chat_title(_cid) or "") if _cid else ""
        _record_gap(
            owner, q, asked_by=asked_by, store="decisions", context=ctx, chat_id=_cid,
        )
    return {"status": "ok", "query": q, "count": len(results), "results": results}


@app.api_route("/api/tools/decisions/record", methods=["GET", "POST"])
async def api_tools_decisions_record(request: Request):
    """Record one settled decision in the shared ledger. Agents call this the
    moment the team settles something durable, so nobody rediscovers it later.
    Params (query string or JSON body): statement (required), why, by (the
    recorder's @handle), scope=global to skip project tagging, supersedes=<id>.
    Both GET and POST work because belt agents are plain-HTTP-GET creatures."""
    caller = _tool_caller(request)
    if not caller:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    if _tool_rate_limited(caller, costs_quota=False):
        return JSONResponse({"error": "rate limited — too many requests, slow down"}, status_code=429)
    owner, cid = _tool_caller_owner_and_chat(caller)
    if owner is None:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    params: dict = dict(request.query_params)
    if request.method == "POST":
        try:
            body = await request.json()
            if isinstance(body, dict):
                params = {**params, **body}
        except Exception:
            pass
    statement = str(params.get("statement") or params.get("decision") or "").strip()
    if not statement:
        return JSONResponse(
            {"error": "missing statement — pass ?statement=<the decision, one sentence>"},
            status_code=400)
    by = str(params.get("by") or "").strip().lstrip("@").lower()
    decided_by = f"@{by}" if by in AGENTS_BY_ID else str(params.get("by") or "").strip()
    durable_project_id = None
    if cid:
        owned, durable_project_id = _owned_chat_project_id(owner, cid)
        if not owned:
            return JSONResponse({"error": "chat scope unavailable"}, status_code=403)
    project_id = None
    if str(params.get("scope") or "").strip().lower() != "global" and cid:
        project_id = durable_project_id
    supersedes = None
    if str(params.get("supersedes") or "").strip():
        try:
            supersedes = int(params["supersedes"])
        except (TypeError, ValueError):
            return JSONResponse({"error": "supersedes must be a decision id (integer)"}, status_code=400)
    ev_kind = str(params.get("evidence") or params.get("evidence_kind") or "").strip()
    ev_ref = str(params.get("proof") or params.get("file") or params.get("test")
                 or params.get("evidence_ref") or "").strip()
    source = "human" if caller.get("kind") == "user" else "agent"
    # Belt agents may describe evidence, but they cannot promote their own claim
    # to owner-confirmed or server-verified ground through request parameters.
    # File evidence remains checkable against the scoped workspace below.
    if source != "human" and ev_kind.lower() == "user":
        ev_kind = ""
    test_passed = None
    res = _add_team_decision(
        owner, statement, str(params.get("why") or params.get("rationale") or ""),
        source=source,
        decided_by=decided_by, chat_id=cid, project_id=project_id,
        supersedes=supersedes,
        evidence_kind=ev_kind, evidence_ref=ev_ref, test_passed=test_passed,
    )
    if not res.get("ok"):
        return JSONResponse({"error": res.get("error", "could not record")}, status_code=400)
    if res.get("duplicate_of"):
        return {"status": "duplicate", "id": res["id"],
                "note": "an active entry already says this — it was left as-is"}
    return {"status": "ok", "id": res["id"], "recorded": statement}


@app.api_route("/api/tools/telegram/send", methods=["GET", "POST"])
async def api_tools_telegram_send(request: Request):
    """Page the owner on their Telegram. This is the SAME pager the PPC monitor
    and scheduled automations use — it reaches the owner's phone with no Agent
    Chat app open. It is locked to the single allow-listed Telegram user id in
    the owner's Settings, so an agent can only message the owner, never an
    arbitrary number — that bounded blast radius is why it's safe to hand to
    every agent (including sandboxed containers) on the presigned ?k= token,
    the only auth path they can actually exercise. Params (query string or JSON
    body): text (required — the message), title (optional heading), by (the
    sender's @handle). Both GET and POST work because belt agents are
    plain-HTTP-GET creatures. Rate-limited; never debits the web quota."""
    caller = _tool_caller(request)
    if not caller:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    if _tool_rate_limited(caller, costs_quota=False):
        return JSONResponse({"error": "rate limited — too many requests, slow down"}, status_code=429)
    owner, cid = _tool_caller_owner_and_chat(caller)
    if owner is None:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    if not TELEGRAM_ENABLED:
        return JSONResponse(
            {"error": "Telegram is not configured — the owner has not set a bot "
                      "token + allowed user id in Settings."},
            status_code=503)
    params: dict = dict(request.query_params)
    if request.method == "POST":
        try:
            body = await request.json()
            if isinstance(body, dict):
                params = {**params, **body}
        except Exception:
            pass
    text = str(params.get("text") or params.get("message") or params.get("body") or "").strip()
    if not text:
        return JSONResponse(
            {"error": "missing text — pass ?text=<the message to page the owner with>"},
            status_code=400)
    title = str(params.get("title") or "").strip()[:100]
    by = str(params.get("by") or params.get("from") or "").strip().lstrip("@").lower()
    if caller.get("kind") == "agent":
        who = (AGENTS_BY_ID.get(caller.get("id")) or {}).get("name") or str(caller.get("id"))
    elif by in AGENTS_BY_ID:
        who = AGENTS_BY_ID[by]["name"]
    else:
        who = "Agents Chat"
    heading = f"📟 <b>{_tg_esc(title or 'Agent page')}</b>\n<i>{_tg_esc(who)}</i>\n\n"
    await _tg_send(heading + _tg_esc(text), parse_html=True)
    _audit_event(
        request, "tools.telegram.send",
        actor=(f"agent:{caller.get('id')}" if caller.get("kind") == "agent"
               else f"chat:{cid}"),
        chat_id=cid, status="ok", meta={"by": who, "chars": len(text)},
    )
    return {"status": "ok", "sent": True, "to": "owner-telegram", "by": who}


@app.get("/api/tools/calendar/upcoming")
async def api_tools_calendar_upcoming(request: Request):
    """The owner's real upcoming schedule from the configured Google ICS feed.
    Read-only, free (no Tavily). Params: days (default 14), limit."""
    caller = _tool_caller(request)
    if not caller:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    if _tool_rate_limited(caller, costs_quota=False):
        return JSONResponse({"error": "rate limited — too many requests, slow down"}, status_code=429)
    try:
        res = await calendar_ics.upcoming(
            days=_tool_int(request, "days", 14),
            limit=_tool_int(request, "limit", 25),
        )
    except calendar_ics.CalendarError as e:
        return JSONResponse({"error": str(e)}, status_code=502)
    return {"status": "ok", **res}



@app.get("/api/chats/{cid}/export/{fmt}")
async def api_chat_export(cid: int, fmt: str, request: Request):
    _refresh_index_from_storage()
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    fmt = (fmt or "").lower()
    if fmt not in ("json", "md", "markdown", "zip"):
        return JSONResponse({"error": "format must be json, md, or zip"}, status_code=400)
    limit_error = await asyncio.to_thread(
        _chat_export_preflight, cid, fmt == "zip"
    )
    if limit_error:
        return JSONResponse({"error": limit_error}, status_code=413)
    payload = await asyncio.to_thread(_chat_export_payload, cid)
    title = _safe_export_name(
        payload.get("chat", {}).get("title") or f"chat-{cid}",
        f"chat-{cid}",
    )
    if fmt == "json":
        body = await asyncio.to_thread(json.dumps, payload, indent=2)
        media_type = "application/json"
        filename = f"{title}.json"
    elif fmt in ("md", "markdown"):
        body = await asyncio.to_thread(_chat_markdown, payload)
        media_type = "text/markdown; charset=utf-8"
        filename = f"{title}.md"
    elif fmt == "zip":
        temp_handle = tempfile.NamedTemporaryFile(
            prefix=f"chat-{cid}-", suffix=".zip", dir=str(DATA_DIR), delete=False,
        )
        temp_path = Path(temp_handle.name)
        temp_handle.close()
        try:
            export_bytes = await asyncio.to_thread(
                _chat_export_zip_to_file, cid, temp_path, payload
            )
        except ValueError as exc:
            temp_path.unlink(missing_ok=True)
            return JSONResponse({"error": str(exc)}, status_code=413)
        except Exception:
            temp_path.unlink(missing_ok=True)
            logger.exception("chat ZIP export failed for %s", cid)
            return JSONResponse({"error": "could not build chat export"}, status_code=500)
        _audit_event(
            request,
            "chat.export",
            chat_id=cid,
            target=fmt,
            status="ok",
            meta={"bytes": export_bytes, "messages": len(payload.get("messages") or [])},
        )
        return FileResponse(
            temp_path,
            media_type="application/zip",
            headers={
                "Content-Disposition": f'attachment; filename="{title}.zip"',
                "Cache-Control": "no-store",
            },
            background=BackgroundTask(temp_path.unlink, missing_ok=True),
        )

    encoded = body.encode("utf-8")
    if len(encoded) > CHAT_EXPORT_TEXT_MAX_BYTES:
        return JSONResponse(
            {"error": "Chat text is too large to export safely in one file."},
            status_code=413,
        )
    _audit_event(
        request,
        "chat.export",
        chat_id=cid,
        target=fmt,
        status="ok",
        meta={"bytes": len(encoded), "messages": len(payload.get("messages") or [])},
    )
    return Response(
        encoded,
        media_type=media_type,
        headers={
            "Content-Disposition": f'attachment; filename="{filename}"',
            "Cache-Control": "no-store",
        },
    )


@app.post("/api/chats/{cid}/support")
async def api_support_ticket(cid: int, request: Request):
    """User-filed support ticket from the composer. The user writes what happened
    and chooses whether to attach a copy of the chat. The ticket is always saved
    to disk and the product owner is paged (web push + Telegram pager); emailing
    SUPPORT_TICKET_TO with the chat .md attached is best-effort on top."""
    _refresh_index_from_storage()
    blocked = _require_chat_access(request, cid)
    if blocked:
        return blocked
    user = _current_user(request)
    try:
        body = await request.json()
    except Exception:
        body = {}
    explanation = str(body.get("explanation") or "").strip()
    include_chat = bool(body.get("include_chat"))
    if not explanation:
        return JSONResponse({"error": "Please describe what happened."}, status_code=400)
    if len(explanation) > 8000:
        explanation = explanation[:8000]

    chat = CHAT_INDEX["chats"].get(str(cid)) or {}
    chat_title = chat.get("title") or f"Chat #{cid}"
    reporter_name = _preferred_name(user) if user else "Unknown user"
    reporter_email = (user or {}).get("email") or "unknown"
    stamp = time.strftime("%Y-%m-%d %H:%M:%S %Z")
    now_ms = int(time.time() * 1000)
    md_text: Optional[str] = None
    md_name = "chat.md"
    if include_chat:
        limit_error = await asyncio.to_thread(_chat_export_preflight, cid, False)
        if limit_error:
            return JSONResponse({"error": limit_error}, status_code=413)
        payload = await asyncio.to_thread(_chat_export_payload, cid)
        md_text = await asyncio.to_thread(_chat_markdown, payload)
        if len(md_text.encode("utf-8")) > CHAT_EXPORT_TEXT_MAX_BYTES:
            return JSONResponse(
                {"error": "Chat text is too large to export safely in one file."},
                status_code=413,
            )
        md_name = _safe_export_name(chat_title, f"chat-{cid}") + ".md"

    # Always persist first — nothing is lost even if email and push are down.
    # A seconds-only id used to overwrite a ticket when two reports arrived in
    # the same second. Reserve the metadata path exclusively so even concurrent
    # submissions can never clobber one another.
    ticket_id = ""
    meta_path: Optional[Path] = None
    transcript_path: Optional[Path] = None
    try:
        SUPPORT_TICKETS_DIR.mkdir(parents=True, exist_ok=True)
        for _attempt in range(5):
            candidate = f"{time.time_ns()}-{cid}-{secrets.token_hex(4)}"
            candidate_meta = SUPPORT_TICKETS_DIR / f"{candidate}.json"
            meta = {
                "ticket_id": candidate,
                "chat_id": cid,
                "chat_title": chat_title,
                "reporter_name": reporter_name,
                "reporter_email": reporter_email,
                "include_chat": include_chat,
                "explanation": explanation,
                "created_ts": now_ms,
                "created_at": stamp,
                "app_version": APP_VERSION,
            }
            if await asyncio.to_thread(
                _create_text_exclusive, candidate_meta, json.dumps(meta, indent=2)
            ):
                ticket_id = candidate
                meta_path = candidate_meta
                break
        if not ticket_id:
            raise OSError("could not reserve a unique support-ticket id")
        if md_text is not None:
            transcript_path = SUPPORT_TICKETS_DIR / f"{ticket_id}-{md_name}"
            if not await asyncio.to_thread(
                _create_text_exclusive, transcript_path, md_text
            ):
                raise OSError("could not persist support-ticket transcript")
    except Exception:
        # If the optional transcript failed, remove only the metadata file this
        # request just created; the caller must never be told a partial ticket
        # was saved successfully.
        if transcript_path is not None:
            transcript_path.unlink(missing_ok=True)
        if meta_path is not None:
            meta_path.unlink(missing_ok=True)
        logger.exception("support: failed to persist ticket %s", ticket_id or "unallocated")
        return JSONResponse(
            {"ok": False, "error": "Could not save the support ticket. Please try again."},
            status_code=500,
        )

    email_body = "\n".join([
        "A user flagged an issue while using Agents Chat.",
        "",
        f"Reporter:   {reporter_name} <{reporter_email}>",
        f"Chat:       {chat_title} (ID {cid})",
        f"When:       {stamp}",
        f"App build:  {APP_VERSION}",
        f"Transcript: {'attached as ' + md_name if include_chat else 'not included by reporter'}",
        f"Ticket:     {ticket_id}",
        "",
        "— What happened —",
        explanation,
    ])
    emailed, email_detail = await _send_support_email(
        SUPPORT_TICKET_SUBJECT, email_body, md_text, md_name
    )

    # Page the owner so the ticket reaches them even with the app closed. Both
    # channels are locked to the owner, so no other user receives this.
    try:
        await _notify_push_subscribers({
            "title": "Agents Chat — issue flagged",
            "body": f"{reporter_name}: {explanation[:140]}",
            "severity": "warn",
            "source": f"Support · {chat_title}",
            "chat_id": cid,
            "ts": now_ms,
        }, owner_user_id=_chat_owner_id(cid))
    except Exception:
        logger.exception("support: push notify failed")
    if TELEGRAM_ENABLED:
        email_line = "sent ✅" if emailed else f"not sent ({_tg_esc(email_detail)})"
        try:
            await _tg_send(
                f"🚩 <b>App Issue Flagged</b>\n"
                f"<i>{_tg_esc(reporter_name)} · {_tg_esc(chat_title)}</i>\n\n"
                f"{_tg_esc(explanation[:1500])}\n\n"
                f"Transcript: {'attached to email' if include_chat else 'not included'}\n"
                f"Email: {email_line}",
                parse_html=True,
            )
        except Exception:
            logger.exception("support: telegram notify failed")

    _audit_event(
        request, "support.ticket", chat_id=cid, status="ok",
        meta={"ticket_id": ticket_id, "emailed": emailed, "include_chat": include_chat},
    )
    return JSONResponse({
        "ok": True,
        "ticket_id": ticket_id,
        "emailed": emailed,
        "email_detail": email_detail,
    })


@app.patch("/api/chats/{cid}/title")
async def api_rename_chat(cid: int, request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    body = await request.json()
    title = (body.get("title") or "").strip()
    if not title:
        return JSONResponse({"error": "title required"}, status_code=400)
    cid_str = str(cid)
    if cid_str not in CHAT_INDEX["chats"]:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    CHAT_INDEX["chats"][cid_str]["title"] = title
    _save_index()
    await broadcast({"type": "chat_meta", "chat_id": cid, "title": title}, global_event=True)
    return {"status": "ok"}


def _switch_active_away_from_archived(
    request: Request,
    archived_ids: set,
    owner_hint: Optional[int] = None,
) -> Optional[int]:
    """If the caller (or any device session) is parked on a chat that was just
    archived, move it to the most recent chat that the same owner can access —
    minting a fresh one for that owner when everything got archived. Returns the
    replacement chat id when THIS request's active chat had to move, else None."""
    archived_str = {str(cid) for cid in archived_ids}
    # Read the raw device pointer. The ordinary accessor repairs a pointer that
    # is absent from the live index; auto-group has already removed its newly
    # trashed rows when it calls this helper, and that eager repair would hide
    # the fact that THIS request moved (returning ``switched_to=None``).
    device_id = _device_id_from_request(request)
    device_key = _session_storage_key(request, device_id)
    caller_session = _session_entry(device_key, legacy_key=device_id)
    caller_active = str(caller_session["active_id"])
    caller_moved = caller_active in archived_str
    stale_sessions = [
        (session, str(session.get("active_id")))
        for session in SESSIONS.get("devices", {}).values()
        if isinstance(session, dict) and str(session.get("active_id")) in archived_str
    ]
    if not caller_moved and not stale_sessions:
        return None

    caller_owner = int((_current_user(request) or {}).get("id") or _default_admin_id())
    replacements: dict[int, int] = {}

    def archived_owner(cid_str: str) -> int:
        entry = CHAT_INDEX.get("chats", {}).get(cid_str) or {}
        return int(entry.get("owner_user_id") or owner_hint or _default_admin_id())

    def replacement_for(owner_id: int) -> int:
        cached = replacements.get(owner_id)
        if cached is not None:
            return cached
        remaining = sorted(
            (
                kv for kv in CHAT_INDEX["chats"].items()
                if str(kv[0]) not in archived_str
                and not kv[1].get("archived")
                and int(kv[1].get("owner_user_id") or _default_admin_id()) == owner_id
            ),
            key=lambda kv: kv[1].get("last_ts", kv[1].get("ts", 0)),
            reverse=True,
        )
        if remaining:
            replacement = int(remaining[0][0])
        else:
            replacement = _mint_chat_id()
            CHAT_INDEX["chats"][str(replacement)] = {
                "owner_user_id": owner_id,
                "title": NEW_CHAT_TITLE,
                "ts": int(time.time() * 1000),
                "mode": NEW_CHAT_MODE,
                "project_id": None,
                "targets": [],
                "contexts": {},
            }
            _save_thread(replacement, [])
        replacements[owner_id] = replacement
        return replacement

    caller_replacement = replacement_for(caller_owner) if caller_moved else None
    if caller_moved:
        CHAT_INDEX["active_id"] = caller_replacement
        _set_active_chat_for_request(request, caller_replacement)
    for session, active_id in stale_sessions:
        session["active_id"] = replacement_for(archived_owner(active_id))
        session["last_seen_ts"] = int(time.time() * 1000)
    global_active = str(CHAT_INDEX.get("active_id"))
    if not caller_moved and global_active in archived_str:
        CHAT_INDEX["active_id"] = replacement_for(archived_owner(global_active))
    # Persist a newly minted replacement and any global-active change before a
    # subsequent /api/chats refresh can conclude that the owner has no chats and
    # create a competing replacement.
    _save_index()
    _save_sessions()
    return caller_replacement


@app.post("/api/chats/archive")
async def api_archive_chats_bulk(request: Request):
    """Archive or recall a batch of chats in one call. All-or-nothing on
    validation: if any id is missing or owned by someone else, nothing changes.
    Mirrors the single-chat route's active-chat handoff."""
    blocked = _require_origin(request)
    if blocked: return blocked
    try:
        body = await _json_object_body(request)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    raw_chat_ids = body.get("chat_ids")
    if not isinstance(raw_chat_ids, list) or not raw_chat_ids:
        return JSONResponse({"error": "chat_ids must be a non-empty list"}, status_code=400)
    if len(raw_chat_ids) > 1000:
        return JSONResponse({"error": "chat_ids may contain at most 1000 ids"}, status_code=400)
    try:
        chat_ids = [
            _parse_resource_id(value, f"chat_ids[{index}]")
            for index, value in enumerate(raw_chat_ids)
        ]
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    chat_ids = list(dict.fromkeys(chat_ids))
    archived = bool(body.get("archived", True))

    for cid in chat_ids:
        blocked = _require_chat_access(request, cid)
        if blocked: return blocked
        if str(cid) not in CHAT_INDEX["chats"]:
            return JSONResponse({"error": "chat not found"}, status_code=404)

    now_ms = int(time.time() * 1000)
    for cid in chat_ids:
        entry = CHAT_INDEX["chats"][str(cid)]
        if archived:
            entry["archived"] = True
            entry["archived_ts"] = now_ms
        else:
            entry.pop("archived", None)
            entry.pop("archived_ts", None)

    switched_to = _switch_active_away_from_archived(request, set(chat_ids)) if archived else None
    _save_index()
    for cid in chat_ids:
        await broadcast({"type": "chat_meta", "chat_id": cid, "archived": archived}, global_event=True)
    return {"status": "ok", "chat_ids": chat_ids, "archived": archived, "switched_to": switched_to}


@app.post("/api/chats/{cid}/archive")
async def api_archive_chat(cid: int, request: Request):
    """Archive or recall (unarchive) a chat. Archived chats drop out of the main
    thread list but keep all their data and stay findable via search. Archiving
    the chat you're viewing switches you to the most recent non-archived chat so
    you're never parked in a now-hidden thread."""
    blocked = _require_origin(request)
    if blocked: return blocked
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    try:
        body = await request.json()
    except Exception:
        body = {}
    archived = bool(body.get("archived", True))
    cid_str = str(cid)
    if cid_str not in CHAT_INDEX["chats"]:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    entry = CHAT_INDEX["chats"][cid_str]
    if archived:
        entry["archived"] = True
        entry["archived_ts"] = int(time.time() * 1000)
    else:
        entry.pop("archived", None)
        entry.pop("archived_ts", None)

    switched_to = None
    if archived:
        switched_to = _switch_active_away_from_archived(request, {cid})

    _save_index()
    await broadcast({"type": "chat_meta", "chat_id": cid, "archived": archived}, global_event=True)
    return {"status": "ok", "chat_id": cid, "archived": archived, "switched_to": switched_to}


async def _quiesce_chat_for_trash(cid: int) -> Optional[str]:
    """Stop every producer and clear ephemeral room state before hiding a chat.

    Unlike permanent deletion this deliberately preserves the database rows,
    attachments, Canvas bytes, workspace binding, and thread mirror so Restore
    is lossless.
    """
    DELETING_CHATS.add(cid)
    live_tasks: set[asyncio.Task] = set()
    for _task_id, info in list(RUNNING_TASKS.items()):
        if info.get("chat_id") != cid:
            continue
        task = info.get("task")
        if task is not None and not task.done():
            live_tasks.add(task)
    for task in list(RUNNING_TURNS.get(cid, set())):
        if task is not None and not task.done():
            live_tasks.add(task)
    current_task = asyncio.current_task()
    for task in list(CHAT_TASKS.get(cid, set())):
        if task is not None and task is not current_task and not task.done():
            live_tasks.add(task)
    if live_tasks:
        _mark_intentional_stop_tasks(live_tasks)
        INTENTIONAL_STOP.add(cid)
        for task in live_tasks:
            task.cancel()
        _done, pending = await asyncio.wait(live_tasks, timeout=5)
        if pending:
            DELETING_CHATS.discard(cid)
            INTENTIONAL_STOP.discard(cid)
            return "active work could not be stopped; chat was not moved to Trash"

    for task_id, info in list(RUNNING_TASKS.items()):
        if info.get("chat_id") == cid:
            RUNNING_TASKS.pop(task_id, None)
    RUNNING_TURNS.pop(cid, None)
    LIVE_TURN_ROSTERS.pop(cid, None)
    CHAT_TARGET_REVISIONS.pop(cid, None)
    CHAT_TASKS.pop(cid, None)
    PENDING_HOLDS.pop(cid, None)
    PENDING_INPUT_CARDS.discard(cid)
    _clear_active_turn_runs(cid)
    CHAT_BG_UPGRADE.pop(cid, None)
    EPISODE_JOBS.pop(cid, None)
    _COMPACTING.discard(cid)
    _FREEWILL_TOPIC_OVERRIDE.pop(cid, None)
    for settings in (
        CODEX_SETTINGS_BY_CHAT, CLAUDE_SETTINGS_BY_CHAT,
        MINIMAX_SETTINGS_BY_CHAT, ANTIGRAVITY_SETTINGS_BY_CHAT,
        GROK_SETTINGS_BY_CHAT, PERPLEXITY_SETTINGS_BY_CHAT,
        OPENROUTER_SETTINGS_BY_CHAT,
    ):
        settings.pop(cid, None)
    for key in [key for key in _PENDING_LINEAGE if int(key[0]) == cid]:
        _PENDING_LINEAGE.pop(key, None)
    for key in [key for key in _PREAMBLE_SENT if int(key[0]) == cid]:
        _PREAMBLE_SENT.pop(key, None)
    return None


@app.delete("/api/chats/{cid}")
async def api_trash_chat(cid: int, request: Request):
    """Move an owner-visible chat to reversible Trash."""
    blocked = _require_origin(request)
    if blocked: return blocked
    _refresh_index_from_storage()
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    cid_str = str(cid)
    if cid_str not in CHAT_INDEX["chats"]:
        return JSONResponse({"error": "chat not found"}, status_code=404)

    # A pinned Control Room must remain addressable by its HUD/outbox.
    if _pinned_control_chat_id() == cid:
        return JSONResponse(
            {"error": "This chat is the pinned Control Room — unpin it in Control Room settings first"},
            status_code=409,
        )

    entry = dict(CHAT_INDEX["chats"][cid_str])
    owner_user_id = int(entry.get("owner_user_id") or _default_admin_id())
    title = str(entry.get("title") or "")[:120]
    schedule_reference = _chat_schedule_reference(cid, owner_user_id)
    if schedule_reference:
        label = str(schedule_reference.get("name") or "this automation")[:120]
        return JSONResponse(
            {"error": f"This chat is used by {label}; change that automation before moving it to Trash"},
            status_code=409,
        )
    with _db() as conn:
        now_ms = int(time.time() * 1000)
        conn.execute(
            "DELETE FROM chat_activity_leases WHERE expires_ts<=?", (now_ms,),
        )
        coding_job = conn.execute(
            "SELECT id FROM coding_jobs WHERE chat_id=? AND owner_user_id=? "
            "AND status NOT IN ('done', 'cancelled') ORDER BY id DESC LIMIT 1",
            (cid, owner_user_id),
        ).fetchone()
        activity_lease = conn.execute(
            "SELECT 1 FROM chat_activity_leases WHERE chat_id=? AND expires_ts>? LIMIT 1",
            (cid, now_ms),
        ).fetchone()
    if coding_job:
        return JSONResponse(
            {
                "error": (
                    f"Coding job #{int(coding_job['id'])} is still attached to this chat; "
                    "finish or cancel it before moving the chat to Trash"
                ),
            },
            status_code=409,
        )
    if activity_lease:
        return JSONResponse(
            {"error": "This conversation still has active work; wait for it to finish before moving it to Trash"},
            status_code=409,
        )
    require_empty = request.headers.get("x-agent-chat-require-empty", "") == "1"
    if require_empty:
        with _db() as conn:
            if conn.execute(
                "SELECT 1 FROM messages WHERE chat_id=? LIMIT 1", (cid,),
            ).fetchone():
                return JSONResponse(
                    {"error": "setup conversation now has content and was kept"},
                    status_code=409,
                )
    quiesce_error = await _quiesce_chat_for_trash(cid)
    if quiesce_error:
        return JSONResponse({"error": quiesce_error}, status_code=409)
    deleted_ts = int(time.time() * 1000)
    deleted_nonce = secrets.token_urlsafe(18)
    try:
        with _db() as conn:
            conn.execute("BEGIN IMMEDIATE")
            lease_cutoff = int(time.time() * 1000)
            sql = (
                "UPDATE chats SET deleted_ts=?, deleted_nonce=? "
                "WHERE id=? AND owner_user_id=? AND deleted_ts IS NULL "
                "AND NOT EXISTS (SELECT 1 FROM skill_schedules "
                "WHERE owner_user_id=? AND (series_chat_id=? OR target=?)) "
                "AND NOT EXISTS (SELECT 1 FROM coding_jobs "
                "WHERE chat_id=? AND owner_user_id=? "
                "AND status NOT IN ('done', 'cancelled')) "
                "AND NOT EXISTS (SELECT 1 FROM chat_activity_leases "
                "WHERE chat_id=? AND expires_ts>?) "
                "AND NOT EXISTS (SELECT 1 FROM turn_runs "
                "WHERE chat_id=? AND status='running') "
                "AND NOT EXISTS (SELECT 1 FROM background_jobs "
                "WHERE chat_id=? AND status='running') "
                "AND NOT EXISTS (SELECT 1 FROM automation_runs "
                "WHERE chat_id=? AND status='running') "
                "AND NOT EXISTS (SELECT 1 FROM freewill_sessions "
                "WHERE chat_id=? AND status='running')"
            )
            params: list = [
                deleted_ts, deleted_nonce, cid, owner_user_id,
                owner_user_id, cid, str(cid),
                cid, owner_user_id,
                cid, lease_cutoff, cid, cid, cid, cid,
            ]
            if require_empty:
                sql += " AND NOT EXISTS (SELECT 1 FROM messages WHERE chat_id=?)"
                params.append(cid)
            changed = conn.execute(sql, params).rowcount
            if changed != 1:
                if conn.execute(
                    "SELECT 1 FROM skill_schedules WHERE owner_user_id=? "
                    "AND (series_chat_id=? OR target=?)",
                    (owner_user_id, cid, str(cid)),
                ).fetchone():
                    return JSONResponse(
                        {"error": "This chat is now used by an automation; change it before moving to Trash"},
                        status_code=409,
                    )
                coding_job = conn.execute(
                    "SELECT id FROM coding_jobs WHERE chat_id=? AND owner_user_id=? "
                    "AND status NOT IN ('done', 'cancelled') ORDER BY id DESC LIMIT 1",
                    (cid, owner_user_id),
                ).fetchone()
                if coding_job:
                    return JSONResponse(
                        {
                            "error": (
                                f"Coding job #{int(coding_job['id'])} is still attached to this chat; "
                                "finish or cancel it before moving the chat to Trash"
                            ),
                        },
                        status_code=409,
                    )
                if conn.execute(
                    "SELECT 1 FROM chat_activity_leases "
                    "WHERE chat_id=? AND expires_ts>? LIMIT 1",
                    (cid, lease_cutoff),
                ).fetchone():
                    return JSONResponse(
                        {"error": "This conversation still has active work; wait for it to finish before moving it to Trash"},
                        status_code=409,
                    )
                if any(conn.execute(sql, (cid,)).fetchone() for sql in (
                    "SELECT 1 FROM turn_runs WHERE chat_id=? AND status='running' LIMIT 1",
                    "SELECT 1 FROM background_jobs WHERE chat_id=? AND status='running' LIMIT 1",
                    "SELECT 1 FROM automation_runs WHERE chat_id=? AND status='running' LIMIT 1",
                    "SELECT 1 FROM freewill_sessions WHERE chat_id=? AND status='running' LIMIT 1",
                )):
                    return JSONResponse(
                        {"error": "This conversation still has active work; wait for it to finish before moving it to Trash"},
                        status_code=409,
                    )
                if require_empty:
                    return JSONResponse(
                        {"error": "setup conversation now has content and was kept"},
                        status_code=409,
                    )
                raise RuntimeError("chat storage changed before Trash update")
            _bump_chats_rev(conn)
        switched_to = _switch_active_away_from_archived(
            request, {cid}, owner_hint=owner_user_id,
        )
        CHAT_INDEX["chats"].pop(cid_str, None)
        _save_index()
        try:
            _audit_event(
                request, "chat.trash",
                actor=(_current_user(request) or {}).get("email") or "user",
                chat_id=cid, target=title,
                meta={"retention_days": CHAT_TRASH_RETENTION_DAYS},
            )
        except Exception:
            logger.warning("chat.trash audit failed for %s", cid, exc_info=True)
        trashed = {
            **entry, "deleted_ts": deleted_ts,
            "delete_receipt": deleted_nonce,
        }
        await broadcast({
            "type": "chat_meta", "chat_id": cid, "deleted": True,
            "deleted_ts": deleted_ts, "owner_user_id": owner_user_id,
            "title": title, "project_id": entry.get("project_id"),
            "archived": bool(entry.get("archived")),
            "active_id": _active_chat_id_for_request(request),
        }, global_event=True)
        return {
            "status": "ok", "trashed": cid, "chat": trashed,
            "active_id": _active_chat_id_for_request(request),
            "switched_to": switched_to,
            "delete_receipt": deleted_nonce,
            "trash_retention_days": CHAT_TRASH_RETENTION_DAYS,
        }
    except Exception:
        logger.exception("chat Trash update failed for %s", cid)
        # If the database update committed but later UI bookkeeping failed, the
        # revision-gated refresh reconciles the in-memory view from SQLite.
        _refresh_index_from_storage()
        return JSONResponse({"error": "chat could not be moved to Trash safely"}, status_code=500)
    finally:
        INTENTIONAL_STOP.discard(cid)
        DELETING_CHATS.discard(cid)


@app.post("/api/chats/{cid}/restore")
async def api_restore_trashed_chat(cid: int, request: Request):
    """Restore an owner-owned Trash item to its original project/archive state."""
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    owner_user_id = int(user.get("id") or 0)
    delete_receipt = request.headers.get(
        "x-agent-chat-deletion-receipt", "",
    ).strip()
    if not delete_receipt:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    with _db() as conn:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT project_id, title FROM chats "
            "WHERE id=? AND owner_user_id=? AND deleted_ts IS NOT NULL "
            "AND deleted_nonce=?",
            (cid, owner_user_id, delete_receipt),
        ).fetchone()
        if not row:
            return JSONResponse({"error": "chat not found"}, status_code=404)
        project_id = row["project_id"]
        if project_id is not None and not conn.execute(
            "SELECT 1 FROM projects WHERE id=? AND owner_user_id=?",
            (int(project_id), owner_user_id),
        ).fetchone():
            project_id = None
        changed = conn.execute(
            "UPDATE chats SET deleted_ts=NULL, deleted_nonce='', project_id=? "
            "WHERE id=? AND owner_user_id=? AND deleted_ts IS NOT NULL "
            "AND deleted_nonce=?",
            (project_id, cid, owner_user_id, delete_receipt),
        ).rowcount
        if changed != 1:
            return JSONResponse({"error": "chat not found"}, status_code=404)
        _bump_chats_rev(conn)
    _refresh_index_from_storage()
    entry = dict(CHAT_INDEX.get("chats", {}).get(str(cid)) or {})
    if not entry:
        return JSONResponse({"error": "chat restore did not become visible"}, status_code=500)
    _write_index_mirror()
    try:
        _audit_event(
            request, "chat.restore",
            actor=(user.get("email") or "user"), chat_id=cid,
            target=str(row["title"] or "")[:120],
        )
    except Exception:
        logger.warning("chat.restore audit failed for %s", cid, exc_info=True)
    try:
        await broadcast({
            "type": "chat_meta", "chat_id": cid, "deleted": False,
            "deleted_ts": None, "owner_user_id": owner_user_id,
            "title": entry.get("title"), "ts": entry.get("ts"),
            "mode": entry.get("mode"), "project_id": entry.get("project_id"),
            "archived": bool(entry.get("archived")),
        }, global_event=True)
    except Exception:
        logger.warning("chat.restore broadcast failed for %s", cid, exc_info=True)
    return {"status": "ok", "restored": cid, "chat": entry}


async def api_delete_chat(cid: int, request: Request):
    """Delete a chat by id. Removes thread file + index entry. If the deleted chat
    was active, switches to the most recent remaining chat (or auto-creates one)."""
    blocked = _require_origin(request)
    if blocked: return blocked
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    current_active = _active_chat_id_for_request(request)
    cid_str = str(cid)
    if cid_str not in CHAT_INDEX["chats"]:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    deleted_meta = dict(CHAT_INDEX["chats"].get(cid_str) or {})
    deleted_owner_id = _chat_owner_id(cid) or _default_admin_id()

    # The foreman-pinned Control Room is the destination for every flag it posts;
    # deleting it strands the HUD and the outbox on a dead id. Unpin first.
    if _pinned_control_chat_id() == cid:
        return JSONResponse(
            {"error": "This chat is the pinned Control Room — unpin it in Control Room settings first"},
            status_code=409,
        )
    # Audit every deletion so a vanished chat is attributable (the Control Room
    # once disappeared with no trail). Best-effort: telemetry must not block
    # the delete.
    try:
        _audit_event(
            request, "chat.delete",
            actor=(_current_user(request) or {}).get("email") or "user",
            chat_id=cid,
            target=str((CHAT_INDEX["chats"].get(cid_str) or {}).get("title") or "")[:120],
        )
    except Exception:
        logger.warning("chat.delete audit failed for %s", cid, exc_info=True)

    # Stop every producer before deleting its database row. Otherwise a late
    # agent reply can race the delete, hit foreign-key failures, or partially
    # resurrect state after the UI has reported success.
    DELETING_CHATS.add(cid)
    live_tasks: set[asyncio.Task] = set()
    for task_id, info in list(RUNNING_TASKS.items()):
        if info.get("chat_id") != cid:
            continue
        task = info.get("task")
        if task is not None and not task.done():
            live_tasks.add(task)
    for task in list(RUNNING_TURNS.get(cid, set())):
        if task is not None and not task.done():
            live_tasks.add(task)
    current_task = asyncio.current_task()
    for task in list(CHAT_TASKS.get(cid, set())):
        if task is not None and task is not current_task and not task.done():
            live_tasks.add(task)
    if live_tasks:
        _mark_intentional_stop_tasks(live_tasks)
        INTENTIONAL_STOP.add(cid)
        for task in live_tasks:
            task.cancel()
        _done, pending = await asyncio.wait(live_tasks, timeout=5)
        if pending:
            DELETING_CHATS.discard(cid)
            INTENTIONAL_STOP.discard(cid)
            return JSONResponse(
                {"error": "active work could not be stopped; chat was not deleted"},
                status_code=409,
            )

    for task_id, info in list(RUNNING_TASKS.items()):
        if info.get("chat_id") == cid:
            RUNNING_TASKS.pop(task_id, None)
    RUNNING_TURNS.pop(cid, None)
    LIVE_TURN_ROSTERS.pop(cid, None)
    CHAT_TARGET_REVISIONS.pop(cid, None)
    CHAT_TASKS.pop(cid, None)
    PENDING_HOLDS.pop(cid, None)
    PENDING_INPUT_CARDS.discard(cid)
    _clear_active_turn_runs(cid)
    CHAT_BG_UPGRADE.pop(cid, None)
    EPISODE_JOBS.pop(cid, None)
    _COMPACTING.discard(cid)
    _FREEWILL_TOPIC_OVERRIDE.pop(cid, None)
    for settings in (
        CODEX_SETTINGS_BY_CHAT, CLAUDE_SETTINGS_BY_CHAT,
        MINIMAX_SETTINGS_BY_CHAT, ANTIGRAVITY_SETTINGS_BY_CHAT,
        GROK_SETTINGS_BY_CHAT, PERPLEXITY_SETTINGS_BY_CHAT,
        OPENROUTER_SETTINGS_BY_CHAT,
    ):
        settings.pop(cid, None)
    for key in [key for key in _PENDING_LINEAGE if int(key[0]) == cid]:
        _PENDING_LINEAGE.pop(key, None)
    for key in [key for key in _PREAMBLE_SENT if int(key[0]) == cid]:
        _PREAMBLE_SENT.pop(key, None)

    # remove from index + delete thread file
    CHAT_INDEX["chats"].pop(cid_str, None)
    try:
        _delete_chat_storage(cid)
    except Exception:
        CHAT_INDEX["chats"][cid_str] = deleted_meta
        INTENTIONAL_STOP.discard(cid)
        DELETING_CHATS.discard(cid)
        logger.exception("chat delete storage cleanup failed for %s", cid)
        return JSONResponse(
            {"error": "chat storage could not be deleted safely"}, status_code=500,
        )
    try:
        p = _get_thread_path(cid)
        if p.is_file():
            p.unlink()
    except Exception:
        pass
    # Wipe both user uploads and Canvas bytes. The per-chat scratch workspace is
    # intentionally retained: it may contain the user's only copy of source work
    # and chat deletion must not silently destroy it.
    for store_dir in (
        ATTACHMENTS_DIR / str(cid), DATA_DIR / "artifacts_store" / str(cid),
        EPISODES_DIR / str(cid),
    ):
        try:
            if store_dir.is_symlink():
                store_dir.unlink()
            elif store_dir.is_dir():
                shutil.rmtree(store_dir, ignore_errors=True)
        except OSError:
            logger.warning("failed to remove deleted chat store %s", store_dir)
    if WORKSPACE_BY_CHAT.pop(cid, None) is not None:
        _save_workspace_bindings()

    remaining = sorted(
        CHAT_INDEX["chats"].items(),
        key=lambda kv: kv[1].get("ts", 0),
        reverse=True,
    )
    # The replacement MUST be a chat the deleting user can actually access, or
    # _require_chat_access parks them on a 404'd chat they can't escape. Picking
    # remaining[0] blindly hands a non-admin another tenant's most-recent chat;
    # minting without an owner defaults it to admin (via _chat_upsert_params).
    user = _current_user(request) or {}
    uid = int(user.get("id") or 0)
    own_remaining = [
        kv for kv in remaining
        if _is_admin_user(user)
        or kv[1].get("owner_user_id") is None
        or int(kv[1].get("owner_user_id") or 0) == uid
    ]
    if own_remaining:
        replacement = int(own_remaining[0][0])
    else:
        replacement = _mint_chat_id()
        CHAT_INDEX["chats"][str(replacement)] = {
            "owner_user_id": uid or _default_admin_id(),
            "title": NEW_CHAT_TITLE,
            "ts": int(time.time() * 1000),
            "mode": NEW_CHAT_MODE,
            "project_id": None,
            "targets": [],
            "contexts": {},
        }
        _save_thread(replacement, [])
    CHAT_INDEX["active_id"] = replacement

    switched_to = None
    if current_active == cid:
        _set_active_chat_for_request(request, replacement)
        switched_to = replacement

    for session in SESSIONS.get("devices", {}).values():
        if isinstance(session, dict) and int(session.get("active_id", replacement)) == cid:
            session["active_id"] = replacement
            session["last_seen_ts"] = int(time.time() * 1000)
    _save_sessions()

    _save_index()
    INTENTIONAL_STOP.discard(cid)
    DELETING_CHATS.discard(cid)
    await broadcast({
        "type": "chat_deleted", "chat_id": cid,
        "owner_user_id": deleted_owner_id,
        "title": str(deleted_meta.get("title") or "")[:120],
        "active_id": _active_chat_id_for_request(request),
    }, global_event=True)
    return {
        "status": "ok",
        "deleted": cid,
        "active_id": _active_chat_id_for_request(request),
        "switched_to": switched_to,
    }


@app.delete("/api/chats/{cid}/permanent")
async def api_delete_chat_permanently(cid: int, request: Request):
    """Explicit hard-delete boundary.

    Only a current Trash item can cross this boundary. In particular, a stale
    request that races with Restore must return 404 instead of hard-deleting the
    newly live conversation.
    """
    blocked = _require_origin(request)
    if blocked: return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    owner_user_id = int(user.get("id") or 0)
    delete_receipt = request.headers.get(
        "x-agent-chat-deletion-receipt", "",
    ).strip()
    if not delete_receipt:
        # Keep the permanent-delete boundary owner/lifecycle indistinguishable:
        # callers without the exact Trash receipt learn nothing about whether
        # the id is live, trashed, foreign-owned, or absent.
        return JSONResponse({"error": "chat not found"}, status_code=404)
    try:
        purged = _purge_trashed_chat_storage(
            cid, owner_user_id=owner_user_id,
            deleted_nonce=delete_receipt,
        )
    except Exception:
        logger.exception("permanent Trash delete failed for %s", cid)
        return JSONResponse(
            {"error": "chat could not be permanently deleted safely"},
            status_code=500,
        )
    if not purged:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    try:
        _audit_event(
            request, "chat.delete",
            actor=(user.get("email") or "user"), chat_id=cid,
            target=str(purged.get("title") or "")[:120],
            meta={"source": "trash"},
        )
    except Exception:
        logger.warning("chat.delete audit failed for %s", cid, exc_info=True)
    try:
        await broadcast({
            "type": "chat_deleted", "chat_id": cid,
            "owner_user_id": owner_user_id,
            "title": str(purged.get("title") or "")[:120],
            "active_id": _active_chat_id_for_request(request),
        }, global_event=True)
    except Exception:
        logger.warning("chat.delete broadcast failed for %s", cid, exc_info=True)
    return {"status": "ok", "deleted": cid, "permanent": True}


def _agent_from_token(token: str) -> Optional[dict]:
    """Resolve an X-API-KEY back to one of our configured agents. Used by
    inbound chat_bridge endpoints (agent -> orchestrator)."""
    if not token:
        return None
    for a in AGENTS:
        env_name = a.get("token_env", "")
        env_tok = os.environ.get(env_name) if env_name else None
        if env_tok and secrets.compare_digest(env_tok, token):
            return a
        if a.get("token") and secrets.compare_digest(a["token"], token):
            return a
    return None


@app.post("/api/chat_bridge/attachment_save")
async def api_agent_attachment_save(request: Request):
    """Inbound: an agent posts a file artifact to the orchestrator. Mirrors
    the secret_set / secret_delete handlers — agent authenticates with its
    own X-API-KEY token, which we resolve back to its configured identity.
    Body: {chat_id?, name, mime, content_b64, text?}
      chat_id   : defaults to the active chat
      name      : display name; will be sanitised
      mime      : MIME type (active web content is Canvas-only)
      content_b64: base64-encoded bytes
      text      : optional accompanying chat text from the agent
    """
    token = request.headers.get("x-api-key", "")
    agent = _agent_from_token(token)
    if not agent:
        return JSONResponse({"error": "unauthorized"}, status_code=401)

    try:
        body = await request.json()
    except json.JSONDecodeError:
        return JSONResponse({"error": "invalid json"}, status_code=400)

    cid = body.get("chat_id") or _fallback_chat_id()
    try:
        cid = int(cid)
    except (TypeError, ValueError):
        return JSONResponse({"error": "bad chat_id"}, status_code=400)
    if str(cid) not in CHAT_INDEX["chats"]:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    # An agent may only attach to a chat whose owner is granted that agent.
    if agent["id"] not in _allowed_agent_ids_for_chat(cid):
        return JSONResponse({"error": "chat not found"}, status_code=404)
    if _track_current_chat_task(cid) is None:
        return JSONResponse({"error": "chat is unavailable"}, status_code=409)

    declared_mime = (body.get("mime") or "application/octet-stream").lower().strip()
    mime_err = _mime_blocked(declared_mime)

    try:
        data = base64.b64decode(body.get("content_b64") or "", validate=True)
    except Exception:
        return JSONResponse({"error": "bad base64"}, status_code=400)
    if len(data) > CHAT_BRIDGE_ATTACHMENT_MAX_BYTES:
        return JSONResponse({"error": "too large"}, status_code=413)
    if not data:
        return JSONResponse({"error": "empty content"}, status_code=400)

    file_id = uuid.uuid4().hex
    safe_name = _safe_download_name(body.get("name") or file_id, file_id)
    digest = hashlib.sha256(data).hexdigest()
    active_content = bool(mime_err or _looks_like_active_content(data))

    # HTML/SVG/XML must not enter the ordinary attachment route (it is designed
    # for same-origin downloads), but rejecting it made container agents silently
    # lose exactly the dashboards users asked them to create.  Persist it only in
    # the hardened Canvas store: CSP + a null-origin sandbox isolate execution,
    # while the Files view still lists the artifact through its Canvas overlay.
    if active_content:
        for prior in _chat_canvas_artifacts(cid):
            if str(prior.get("source_name") or prior.get("title") or "") != safe_name:
                continue
            if _stored_artifact_digest(cid, prior) != digest:
                continue
            note = (body.get("text") or "").strip()
            if note:
                try:
                    entry = append_thread(
                        cid, "agent", agent["id"], agent["name"], note,
                        artifacts=[prior],
                    )
                except RuntimeError:
                    return JSONResponse(
                        {"error": "conversation moved to Trash before file delivery completed"},
                        status_code=409,
                    )
                await broadcast({
                    "type": "message", "chat_id": cid, "sender": "agent",
                    "agent_id": agent["id"], "name": agent["name"],
                    "text": note, "ts": entry["ts"], "artifacts": [prior],
                })
            return {
                "status": "ok", "url": prior.get("url"), "id": prior.get("id"),
                "duplicate": True, "canvas_only": True,
            }
        if not _chat_row_is_live(cid):
            return JSONResponse(
                {"error": "conversation moved to Trash before file delivery completed"},
                status_code=409,
            )
        art = register_bytes_artifact(
            DATA_DIR, cid, agent["id"], data,
            source_name=safe_name, mime=declared_mime, title=safe_name,
        )
        if not art:
            return JSONResponse({"error": "could not store canvas artifact"}, status_code=500)
        text = (body.get("text") or "").strip()
        try:
            if not _chat_row_is_live(cid):
                raise RuntimeError(f"chat {cid} is unavailable")
            entry = append_thread(
                cid, "agent", agent["id"], agent["name"], text, artifacts=[art],
            )
        except RuntimeError:
            _discard_ingress_artifact(cid, art)
            return JSONResponse(
                {"error": "conversation moved to Trash before file delivery completed"},
                status_code=409,
            )
        await broadcast({
            "type": "message", "chat_id": cid, "sender": "agent",
            "agent_id": agent["id"], "name": agent["name"],
            "text": text, "ts": entry["ts"], "artifacts": [art],
        })
        try:
            _audit_event(
                request, "artifact.create", actor=f"agent:{agent['id']}", chat_id=cid,
                target=art["id"], status="ok",
                meta={"name": safe_name, "mime": declared_mime, "size": len(data),
                      "agent_id": agent["id"], "canvas_only": True},
            )
        except Exception:
            logger.warning("artifact.create audit failed for chat %s", cid, exc_info=True)
        return {
            "status": "ok", "url": art["url"], "id": art["id"],
            "canvas_only": True,
        }

    bytes_path, meta_path = _attachment_paths(cid, file_id)
    if bytes_path is None:
        return JSONResponse({"error": "internal id error"}, status_code=500)

    # Same name + same bytes already in this chat → hand back the existing copy
    # instead of minting a duplicate (agents re-save their work when nudged).
    # Only same-name same-size rows are read back, so this stays cheap. An
    # accompanying text note still lands in the chat, pointing at that copy.
    for prior in _list_attachment_meta(cid):
        if prior.get("name") != safe_name or int(prior.get("size") or 0) != len(data):
            continue
        prior_bytes, _pm = _attachment_paths(cid, prior["id"])
        try:
            if (prior_bytes is None or not prior_bytes.is_file()
                    or hashlib.sha256(prior_bytes.read_bytes()).hexdigest() != digest):
                continue
        except OSError:
            continue
        note = (body.get("text") or "").strip()
        prior_att = {
            k: prior[k]
            for k in ("id", "name", "mime", "size", "uploader", "ts", "url")
            if k in prior
        }
        prior_art = next(
            (a for a in _chat_canvas_artifacts(cid)
             if str(a.get("source_attachment_id") or "") == str(prior["id"])),
            None,
        )
        created_overlay = False
        if prior_art is None:
            if not _chat_row_is_live(cid):
                return JSONResponse(
                    {"error": "conversation moved to Trash before file delivery completed"},
                    status_code=409,
                )
            prior_art = register_bytes_artifact(
                DATA_DIR, cid, agent["id"], data,
                source_name=safe_name, mime=declared_mime, title=safe_name,
                source_attachment_id=str(prior["id"]),
            )
            created_overlay = prior_art is not None
        if note or created_overlay:
            try:
                if not _chat_row_is_live(cid):
                    raise RuntimeError(f"chat {cid} is unavailable")
                entry = append_thread(
                    cid, "agent", agent["id"], agent["name"], note,
                    attachments=[prior_att],
                    artifacts=[prior_art] if prior_art else [],
                )
            except RuntimeError:
                if created_overlay:
                    _discard_ingress_artifact(cid, prior_art)
                return JSONResponse(
                    {"error": "conversation moved to Trash before file delivery completed"},
                    status_code=409,
                )
            await broadcast({
                "type": "message", "chat_id": cid, "sender": "agent",
                "agent_id": agent["id"], "name": agent["name"],
                "text": note, "ts": entry["ts"], "attachments": [prior_att],
                "artifacts": [prior_art] if prior_art else [],
            })
        try:
            _audit_event(
                request, "artifact.create", actor=f"agent:{agent['id']}", chat_id=cid,
                target=prior["id"], status="duplicate",
                meta={"name": safe_name, "size": len(data), "agent_id": agent["id"],
                      "noted": bool(note)},
            )
        except Exception:
            logger.warning("artifact.create audit failed for chat %s", cid, exc_info=True)
        return {"status": "ok", "url": f"/attachments/{cid}/{prior['id']}",
                "id": prior["id"], "duplicate": True,
                "canvas_id": prior_art.get("id") if prior_art else None}

    try:
        bytes_path.write_bytes(data)
    except OSError as exc:
        _discard_ingress_attachment(cid, file_id)
        return JSONResponse({"error": f"file delivery failed: {exc}"}, status_code=500)
    extracted_text = None
    if (declared_mime in OOXML_MIMES or declared_mime == "application/pdf"
            or _ocr_eligible_image(declared_mime, len(data))):
        try:
            # The worker is deliberately extraction-only: cancellation cannot
            # leave it writing a sidecar after Trash has purged the chat folder.
            extracted_text = await asyncio.to_thread(
                _extract_attachment_text, data, declared_mime,
            )
        except asyncio.CancelledError:
            _discard_ingress_attachment(cid, file_id)
            raise
        except Exception:
            extracted_text = None
    meta = {
        "id": file_id,
        "name": safe_name,
        "mime": declared_mime,
        "size": len(data),
        "uploader": agent["id"],
        "ts": int(time.time() * 1000),
        "hash": digest,
    }
    if not _save_attachment_meta(cid, meta):
        _discard_ingress_attachment(cid, file_id)
        return JSONResponse(
            {"error": "conversation moved to Trash before file delivery completed"},
            status_code=409,
        )
    try:
        if extracted_text:
            bytes_path.with_suffix(".txt").write_text(
                extracted_text, encoding="utf-8",
            )
            meta["text_url"] = f"/attachments/{cid}/{file_id}/text"
        meta_path.write_text(json.dumps(meta))
    except asyncio.CancelledError:
        _discard_ingress_attachment(cid, file_id)
        raise
    except Exception as exc:
        _discard_ingress_attachment(cid, file_id)
        return JSONResponse({"error": f"file delivery failed: {exc}"}, status_code=500)
    att = {**meta, "url": f"/attachments/{cid}/{file_id}"}
    art = None
    text = (body.get("text") or "").strip()
    try:
        art = register_bytes_artifact(
            DATA_DIR, cid, agent["id"], data,
            source_name=safe_name, mime=declared_mime, title=safe_name,
            source_attachment_id=file_id,
        )
        # append_thread performs a second conditional live-row insert. It closes
        # the cross-worker window after the attachment publication gate.
        entry = append_thread(
            cid, "agent", agent["id"], agent["name"], text,
            attachments=[att], artifacts=[art] if art else [],
        )
    except asyncio.CancelledError:
        _discard_ingress_artifact(cid, art)
        _discard_ingress_attachment(cid, file_id)
        raise
    except Exception as exc:
        _discard_ingress_artifact(cid, art)
        _discard_ingress_attachment(cid, file_id)
        if not _chat_row_is_live(cid):
            return JSONResponse(
                {"error": "conversation moved to Trash before file delivery completed"},
                status_code=409,
            )
        logger.exception("agent attachment finalization failed for chat %s", cid)
        return JSONResponse({"error": f"file delivery failed: {exc}"}, status_code=500)
    await broadcast({
        "type": "message",
        "chat_id": cid,
        "sender": "agent",
        "agent_id": agent["id"],
        "name": agent["name"],
        "text": text,
        "ts": entry["ts"],
        "attachments": [att],
        "artifacts": [art] if art else [],
    })
    try:
        _audit_event(
            request,
            "artifact.create",
            actor=f"agent:{agent['id']}",
            chat_id=cid,
            target=file_id,
            status="ok",
            meta={
                "name": safe_name,
                "mime": declared_mime,
                "size": len(data),
                "agent_id": agent["id"],
            },
        )
    except Exception:
        logger.warning("artifact.create audit failed for chat %s", cid, exc_info=True)
    return {"status": "ok", "url": att["url"], "id": file_id,
            "canvas_id": art.get("id") if art else None}


def _alert_actor_from_request(request: Request) -> Optional[dict]:
    token = request.headers.get("x-api-key", "")
    agent = _agent_from_token(token)
    if agent:
        return {
            "kind": "agent",
            "id": agent["id"],
            "name": agent["name"],
            "actor": f"agent:{agent['id']}",
        }
    supplied = _access_token_from_request(request)
    if ACCESS_TOKEN and secrets.compare_digest(supplied, ACCESS_TOKEN):
        return {
            "kind": "admin",
            "id": "orchestrator",
            "name": "Agents Chat",
            "actor": "admin",
        }
    return None


@app.post("/api/chat_bridge/message")
async def api_chat_bridge_message(request: Request):
    """Inbound alert/message surface for agents and trusted automations.

    Auth: an existing agent X-API-KEY, or ORCHESTRATOR_ACCESS_TOKEN via
    Authorization: Bearer / X-Orchestrator-Token. Body:
      {chat_id?, new_chat?, title?, text, severity?, targets?, mode?, dispatch?, push?}
    """
    actor = _alert_actor_from_request(request)
    if not actor:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        body = await request.json()
    except json.JSONDecodeError:
        return JSONResponse({"error": "invalid json"}, status_code=400)
    if not isinstance(body, dict):
        return JSONResponse({"error": "json object required"}, status_code=400)

    text = str(body.get("text") or body.get("message") or "").strip()
    title = str(body.get("title") or "Agents Chat Alert").strip()[:100]
    severity = str(body.get("severity") or "info").strip().lower()[:20]
    if severity not in ("info", "success", "warn", "warning", "error", "critical"):
        severity = "info"
    if severity == "warning":
        severity = "warn"
    if not text:
        return JSONResponse({"error": "text required"}, status_code=400)

    raw_targets = body.get("targets") or []
    if not isinstance(raw_targets, list):
        return JSONResponse({"error": "targets must be a list"}, status_code=400)
    if any(not isinstance(t, str) or t not in AGENTS_BY_ID for t in raw_targets):
        return JSONResponse({"error": "unknown target"}, status_code=400)
    target_ids = list(dict.fromkeys(raw_targets))
    mode = _normalize_chat_mode(str(body.get("mode") or DEFAULT_CHAT_MODE))
    requested_chat_id = body.get("chat_id")
    new_chat = bool(body.get("new_chat") or body.get("create_chat"))
    if actor["kind"] == "agent" and (new_chat or requested_chat_id in (None, "")):
        # A shared agent credential has no unambiguous human owner. It may post
        # only to an explicit existing chat where that agent is granted.
        return JSONResponse(
            {"error": "agent alerts require an existing chat_id"}, status_code=400,
        )
    if new_chat:
        cid = _create_chat_record(title, mode=mode, targets=target_ids)
        created_chat = True
    else:
        try:
            cid = int(requested_chat_id) if requested_chat_id else _fallback_chat_id()
        except (TypeError, ValueError):
            return JSONResponse({"error": "bad chat_id"}, status_code=400)
        if str(cid) not in CHAT_INDEX["chats"]:
            return JSONResponse({"error": "chat not found"}, status_code=404)
        allowed = _allowed_agent_ids_for_chat(cid)
        if actor["kind"] == "agent" and actor["id"] not in allowed:
            return JSONResponse({"error": "chat not found"}, status_code=404)
        if any(target not in allowed for target in target_ids):
            return JSONResponse({"error": "target not available for this chat"}, status_code=404)
        if target_ids:
            _save_chat_targets(cid, target_ids)
        created_chat = False

    source = str(body.get("source") or actor["name"])[:80]
    note = (
        f"[alert:{severity}] {title}\n"
        f"Source: {source}\n\n"
        f"{text}"
    )
    entry = append_thread(cid, "system", None, "system", note)
    if created_chat:
        await broadcast({
            "type": "chat_meta",
            "chat_id": cid,
            "title": CHAT_INDEX["chats"][str(cid)]["title"],
            "mode": mode,
            "targets": target_ids,
            "ts": CHAT_INDEX["chats"][str(cid)]["ts"],
        }, global_event=True)
    await broadcast({
        "type": "system",
        "chat_id": cid,
        "level": "error" if severity in ("error", "critical") else ("warn" if severity == "warn" else "info"),
        "text": note,
        "ts": entry["ts"],
    })

    push_payload = {
        "title": title,
        "body": text,
        "severity": severity,
        "source": source,
        "chat_id": cid,
        "ts": entry["ts"],
    }
    # Premium in-app banner on every open stream (push below covers closed apps).
    await _emit_notification(
        cid, event="attention", title=title, body=text,
        severity=severity, push=False,
    )
    push_result = {"sent": 0, "failed": 0}
    if body.get("push", True):
        push_result = await _notify_push_subscribers(
            push_payload, owner_user_id=_chat_owner_id(cid),
        )

    # Relay alerts/scheduled-agent output to the Telegram pager (opt out per-call
    # with "telegram": false). This is the channel that reaches you with no app open.
    if TELEGRAM_ENABLED and body.get("telegram", True):
        sev_icon = _TG_SEVERITY_EMOJI.get(severity, "🔔")
        await _tg_send(
            f"{sev_icon} <b>{_tg_esc(title)}</b>\n<i>{_tg_esc(source)}</i>\n\n{_tg_esc(text)}",
            parse_html=True,
        )

    dispatch = bool(body.get("dispatch")) or (body.get("dispatch") is None and bool(target_ids))
    if dispatch and target_ids:
        _spawn_chat_task(cid, route_agent_turn(cid, target_ids, mode))

    _audit_event(
        request,
        "chat_bridge.message",
        actor=actor["actor"],
        chat_id=cid,
        target=",".join(target_ids),
        status="ok",
        meta={
            "severity": severity,
            "source": source,
            "push_sent": push_result.get("sent", 0),
            "push_failed": push_result.get("failed", 0),
            "dispatch": dispatch,
            "created_chat": created_chat,
        },
    )
    return {
        "status": "ok",
        "chat_id": cid,
        "created_chat": created_chat,
        "targets": target_ids,
        "dispatch": dispatch,
        "push": push_result,
    }


@app.post("/api/chats/{cid}/attachments")
async def api_upload_attachment(cid: int, request: Request, file: UploadFile = File(...)):
    """Stream-upload a single file into this chat's attachment dir. Caps at
    MAX_UPLOAD_BYTES, enforces MIME prefix allowlist, returns metadata the
    client then ships back inside /api/send's `attachments` list."""
    blocked = _require_origin(request)
    if blocked: return blocked
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked

    # Upload/OCR yields repeatedly. Register this request so Trash waits for or
    # cancels it instead of letting late bytes recreate a purged chat folder.
    if _track_current_chat_task(cid) is None:
        return JSONResponse({"error": "chat is unavailable"}, status_code=409)

    declared_mime = (file.content_type or "application/octet-stream").lower().strip()
    mime_err = _mime_blocked(declared_mime)
    if mime_err:
        return JSONResponse({"error": mime_err}, status_code=415)

    file_id = uuid.uuid4().hex
    bytes_path, meta_path = _attachment_paths(cid, file_id)
    if bytes_path is None:
        return JSONResponse({"error": "internal id error"}, status_code=500)

    written = 0
    head = bytearray()
    try:
        with bytes_path.open("wb") as out:
            while True:
                chunk = await file.read(64 * 1024)
                if not chunk:
                    break
                written += len(chunk)
                if len(head) < 4096:
                    head.extend(chunk[: 4096 - len(head)])
                if written > MAX_UPLOAD_BYTES:
                    out.close()
                    bytes_path.unlink(missing_ok=True)
                    return JSONResponse(
                        {"error": f"file exceeds {MAX_UPLOAD_BYTES} bytes"},
                        status_code=413,
                    )
                out.write(chunk)
    except asyncio.CancelledError:
        bytes_path.unlink(missing_ok=True)
        if meta_path is not None:
            meta_path.unlink(missing_ok=True)
        raise
    except Exception as e:
        bytes_path.unlink(missing_ok=True)
        return JSONResponse({"error": f"upload failed: {e}"}, status_code=500)

    if written == 0:
        bytes_path.unlink(missing_ok=True)
        return JSONResponse({"error": "empty file"}, status_code=400)
    if _looks_like_active_content(bytes(head)):
        bytes_path.unlink(missing_ok=True)
        return JSONResponse({"error": "active browser content is not allowed"}, status_code=415)

    safe_name = _safe_download_name(file.filename or file_id, file_id)
    text_url = None
    extracted_text = None
    if (declared_mime in OOXML_MIMES or declared_mime == "application/pdf"
            or _ocr_eligible_image(declared_mime, written)):
        try:
            # Off the event loop: image OCR can shell out / hit the network.
            extracted_text = await asyncio.to_thread(
                _extract_attachment_text,
                bytes_path.read_bytes(), declared_mime,
            )
        except asyncio.CancelledError:
            bytes_path.unlink(missing_ok=True)
            bytes_path.with_suffix(".txt").unlink(missing_ok=True)
            if meta_path is not None:
                meta_path.unlink(missing_ok=True)
            raise
        except Exception:
            text_url = None
    meta = {
        "id": file_id,
        "name": safe_name,
        "mime": declared_mime,
        "size": written,
        "uploader": "user",
        "ts": int(time.time() * 1000),
    }
    if not _save_attachment_meta(cid, meta):
        bytes_path.unlink(missing_ok=True)
        bytes_path.with_suffix(".txt").unlink(missing_ok=True)
        meta_path.unlink(missing_ok=True)
        return JSONResponse(
            {"error": "conversation moved to Trash before upload completed"},
            status_code=409,
        )
    if extracted_text:
        try:
            bytes_path.with_suffix(".txt").write_text(
                extracted_text, encoding="utf-8",
            )
            meta["text_url"] = f"/attachments/{cid}/{file_id}/text"
        except OSError:
            pass
    try:
        meta_path.write_text(json.dumps(meta))
    except OSError as exc:
        _delete_attachment_meta(cid, file_id)
        bytes_path.unlink(missing_ok=True)
        bytes_path.with_suffix(".txt").unlink(missing_ok=True)
        return JSONResponse({"error": f"upload failed: {exc}"}, status_code=500)
    _audit_event(
        request,
        "artifact.upload",
        chat_id=cid,
        target=file_id,
        status="ok",
        meta={"name": safe_name, "mime": declared_mime, "size": written},
    )
    # Event-trigger seam: let the uploading owner's skills scheduled on
    # "attachment_added" fire. Scoped to this chat's owner so an upload in one
    # tenant's chat never triggers another tenant's automations.
    # Fire-and-forget so the upload response never waits on a skill run.
    if _chat_row_is_live(cid):
        asyncio.create_task(_fire_event_triggers("attachment_added", _chat_owner_id(cid)))
    return {**meta, "url": f"/attachments/{cid}/{file_id}"}


@app.delete("/api/chats/{cid}/attachments/{file_id}")
async def api_delete_attachment(cid: int, file_id: str, request: Request):
    """Delete one attachment (bytes + extracted-text sidecar + metadata) from
    this chat. Same access checks as upload; idempotent."""
    blocked = _require_origin(request)
    if blocked: return blocked
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    bytes_path, meta_path = _attachment_paths(cid, file_id)
    if bytes_path is None:
        return JSONResponse({"error": "bad file id"}, status_code=400)
    user = _current_user(request)
    try:
        owner_user_id = int((user or {})["id"])
    except (KeyError, TypeError, ValueError):
        return JSONResponse({"error": "chat not found"}, status_code=404)

    name = file_id
    existed = False
    staged: list[tuple[Path, Path]] = []
    try:
        with _db() as conn:
            # Serialize the final live-parent check, byte staging, and metadata
            # deletion against both Trash and permanent purge. Whichever writer
            # obtains the lock first wins as one complete lifecycle operation.
            conn.execute("BEGIN IMMEDIATE")
            if conn.execute(
                "SELECT 1 FROM chats WHERE id=? AND owner_user_id=? "
                "AND deleted_ts IS NULL",
                (cid, owner_user_id),
            ).fetchone() is None:
                return JSONResponse({"error": "chat not found"}, status_code=404)
            if meta_path and meta_path.is_file():
                try:
                    name = json.loads(meta_path.read_text()).get("name", name)
                except Exception:
                    pass
            existed = bytes_path.is_file()
            staged = _stage_attachment_files_for_delete(cid, file_id)
            try:
                # Use the caller's connection: opening a nested _db() while an
                # IMMEDIATE writer lock is held can self-deadlock on SQLite.
                conn.execute(
                    "DELETE FROM attachments_meta WHERE chat_id=? AND id=?",
                    (cid, file_id),
                )
                conn.commit()
            except Exception:
                _restore_staged_chat_storage(staged)
                staged = []
                raise
    except Exception:
        logger.exception(
            "attachment delete failed safely for chat %s file %s", cid, file_id,
        )
        return JSONResponse(
            {"error": "attachment could not be deleted safely"}, status_code=500,
        )
    pending_cleanup = _cleanup_staged_chat_storage(staged)
    if pending_cleanup:
        logger.warning(
            "attachment delete left %d quarantined file(s) for retry",
            len(pending_cleanup),
        )
    _audit_event(
        request, "artifact.delete", chat_id=cid, target=file_id,
        status="ok", meta={"name": name, "existed": existed},
    )
    return {"ok": True, "id": file_id}


@app.get("/attachments/{cid}/{file_id}")
async def api_get_attachment(cid: int, file_id: str, request: Request):
    # A valid per-file signed token (?k=…) lets a chat-participant agent fetch
    # without a user session; otherwise fall back to cookie/session auth.
    if not _live_attachment_token_ok(cid, file_id, request.query_params.get("k", "")):
        blocked = _require_chat_access(request, cid)
        if blocked: return blocked
    bytes_path, meta_path = _attachment_paths(cid, file_id)
    if bytes_path is None or not bytes_path.is_file():
        return JSONResponse({"error": "not found"}, status_code=404)
    mime = "application/octet-stream"
    name = file_id
    if meta_path and meta_path.is_file():
        try:
            meta = json.loads(meta_path.read_text())
            mime = meta.get("mime", mime)
            name = meta.get("name", name)
        except Exception:
            pass
    headers = {
        # Block content sniffing so e.g. an uploaded text/html cannot be
        # rendered as HTML in a sibling tab and reach our SSE / cookies.
        "X-Content-Type-Options": "nosniff",
    }
    # Inline-display images, PDFs, and audio/video so previews render and media
    # plays. Force-download anything else so HTML/JS/etc. cannot run in-page.
    inline_ok = mime in INLINE_SERVE_MIMES or any(
        mime.startswith(p) for p in INLINE_SERVE_PREFIXES
    )
    # Set the disposition explicitly. We must NOT pass filename= to FileResponse
    # below: Starlette then force-sets `Content-Disposition: attachment`, which makes
    # the browser DOWNLOAD inline-eligible files (PDFs) instead of rendering them —
    # the blank-PDF-preview bug. Inline for images/PDF/AV; force-download the rest.
    headers["Content-Disposition"] = (
        f'{"inline" if inline_ok else "attachment"}; filename="{name}"'
    )
    # PDFs render inside our own Files preview / Chat Canvas iframe. Allow our own
    # page to frame them — BOTH headers are required: the global middleware otherwise
    # applies CSP `frame-ancestors 'none'`, which OVERRIDES X-Frame-Options and blocks
    # the iframe with "<host> refused to connect". Setting our own CSP here wins over
    # the middleware's setdefault.
    if inline_ok and mime == "application/pdf":
        headers["X-Frame-Options"] = "SAMEORIGIN"
        headers["Content-Security-Policy"] = "frame-ancestors 'self'"
    _audit_event(
        request,
        "artifact.download",
        chat_id=cid,
        target=file_id,
        status="ok",
        meta={"name": name, "mime": mime},
    )
    # NB: no filename= here — we already set Content-Disposition above; passing it
    # would override us with `attachment` and re-break inline PDF previews.
    return FileResponse(bytes_path, media_type=mime, headers=headers)


# Content-Security-Policy for canvas artifacts. The bytes are agent-authored and
# therefore untrusted: the iframe also carries sandbox="allow-scripts" (no
# allow-same-origin), so this document runs in a null origin and cannot touch the
# parent page, our cookies, or the SSE stream. CSP is defence-in-depth on top.
_ARTIFACT_CSP = (
    "sandbox allow-scripts allow-forms allow-popups allow-downloads; "
    "default-src 'none'; "
    "img-src 'self' data: blob:; "
    "media-src 'self' data: blob:; "
    "font-src data: https://fonts.gstatic.com; "
    "style-src 'unsafe-inline' https://cdnjs.cloudflare.com https://cdn.jsdelivr.net "
    "https://fonts.googleapis.com; "
    "script-src 'unsafe-inline' https://cdnjs.cloudflare.com https://cdn.jsdelivr.net "
    "https://unpkg.com https://esm.sh; "
    "connect-src 'none'; "
    "frame-ancestors 'self'"
)


@app.get("/artifacts/{cid}/{artifact_id}")
async def api_get_artifact(cid: int, artifact_id: str, request: Request):
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    bytes_path, meta_path = artifact_paths(DATA_DIR, cid, artifact_id)
    if bytes_path is None:
        return JSONResponse({"error": "not found"}, status_code=404)
    try:
        meta = json.loads(meta_path.read_text())
    except Exception:
        meta = {}
    mime = meta.get("mime") or "application/octet-stream"
    name = meta.get("title") or artifact_id
    headers = {
        "X-Content-Type-Options": "nosniff",
        "Content-Security-Policy": _ARTIFACT_CSP,
        # The global hardening middleware sets X-Frame-Options: DENY via setdefault;
        # canvas artifacts must be framable by our own page, so claim it here.
        # Isolation still holds: the iframe is sandboxed without allow-same-origin
        # (null origin) and CSP frame-ancestors 'self' bounds who may embed it.
        "X-Frame-Options": "SAMEORIGIN",
        "Cache-Control": "private, max-age=86400",
    }
    # `?view=text` extracts plain text from a binary Office doc (.docx/.xlsx/.pptx)
    # so the canvas can render it inline — stdlib only, no python-docx/openpyxl dep.
    if request.query_params.get("view") == "text" and mime in OOXML_MIMES:
        try:
            extracted = await asyncio.to_thread(
                lambda: _extract_office_text(bytes_path.read_bytes(), mime)
            )
        except Exception:
            extracted = None
        _audit_event(
            request, "canvas.artifact.view", chat_id=cid, target=artifact_id,
            status="ok", meta={"mime": mime, "view": "text"},
        )
        return Response(
            (extracted or "Preview unavailable for this document."),
            media_type="text/plain; charset=utf-8",
            headers={"X-Content-Type-Options": "nosniff",
                     "Cache-Control": "private, max-age=86400"},
        )
    # HTML/SVG/PDF render in the sandboxed canvas iframe; text kinds (md/json/code)
    # are fetched and rendered by the parent canvas; everything else downloads so it
    # can never execute in-page.
    render = meta.get("render")
    # application/pdf is always safe to serve inline (nosniff forces the built-in
    # PDF viewer; it can never execute as in-page HTML), so render it inline even
    # if an older record's stored render mode doesn't say "frame".
    inline_ok = render in ("frame", "image", "video", "text") or mime == "application/pdf"
    if not inline_ok:
        headers["Content-Disposition"] = f'attachment; filename="{_safe_download_name(name)}"'
    _audit_event(
        request, "canvas.artifact.view", chat_id=cid, target=artifact_id,
        status="ok", meta={"mime": mime, "kind": meta.get("kind")},
    )
    return FileResponse(bytes_path, media_type=mime, headers=headers)


@app.post("/api/dev/inject_artifact")
async def api_dev_inject_artifact(request: Request):
    """Dev-only (v5.14 test): synthesize an agent message carrying an artifact so
    the canvas pipeline can be exercised end-to-end without a live agent. Takes a
    JSON body { chat_id, agent_id?, agent_name?, reply } where `reply` is the raw
    text the way an agent would send it (including a ```artifact fence).

    Gated behind CANVAS_DEV=1 — it injects unauthenticated agent messages, so it
    must stay OFF in the cutover/production environment."""
    if os.environ.get("CANVAS_DEV") != "1":
        return JSONResponse({"error": "not found"}, status_code=404)
    blocked = _require_origin(request)
    if blocked: return blocked
    try:
        body = await _json_object_body(request)
        cid = int(body.get("chat_id") or 0)
    except (ValueError, TypeError):
        return JSONResponse({"error": "valid chat_id required"}, status_code=400)
    if not cid:
        return JSONResponse({"error": "chat_id required"}, status_code=400)
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    blocked = _require_admin(request)
    if blocked: return blocked
    agent_id = str(body.get("agent_id") or "claude")
    if agent_id not in _allowed_agent_ids_for_chat(cid) or agent_id not in AGENTS_BY_ID:
        return JSONResponse({"error": "unknown agent"}, status_code=400)
    agent_name = str(AGENTS_BY_ID[agent_id].get("name") or agent_id)
    reply_value = body.get("reply")
    if not isinstance(reply_value, str):
        return JSONResponse({"error": "reply must be a string"}, status_code=400)
    if len(reply_value) > 1_000_000:
        return JSONResponse({"error": "reply too large"}, status_code=413)
    reply = reply_value
    clean_text, artifacts = extract_artifacts(
        reply, base_dir=DATA_DIR, cid=cid, agent_id=agent_id,
        workspace_dir=_chat_workspace(cid),
    )
    if body.get("parent_id") and artifacts:  # test hook: simulate a hand-off lineage
        _PENDING_LINEAGE[(int(cid), agent_id)] = str(body["parent_id"])
        _apply_pending_lineage(cid, agent_id, artifacts)
    entry = append_thread(
        cid, "agent", agent_id, agent_name, clean_text, artifacts=artifacts,
    )
    await broadcast({
        "type": "message", "chat_id": cid, "id": uuid.uuid4().hex,
        "sender": "agent", "agent_id": agent_id, "text": clean_text,
        "ts": entry["ts"], "artifacts": artifacts,
    })
    return {"ok": True, "artifacts": artifacts, "text": clean_text}


def _apply_pending_lineage(cid: int, agent_id: str, artifacts: list) -> None:
    """If this agent was handed an artifact, tag the artifact it just produced as
    the next version in that lineage. Fail-open — never break a reply."""
    src_id = _PENDING_LINEAGE.pop((int(cid), agent_id), None)
    if not src_id or not artifacts:
        return
    try:
        parent = read_artifact(DATA_DIR, cid, src_id) or {}
        a = artifacts[0]
        a["parent_id"] = src_id
        a["version"] = int(parent.get("version") or 1) + 1
        a["lineage_root"] = parent.get("lineage_root") or src_id
        _, meta_path = artifact_paths(DATA_DIR, cid, a["id"])
        if meta_path:
            m = json.loads(meta_path.read_text())
            m.update({"parent_id": a["parent_id"], "version": a["version"],
                      "lineage_root": a["lineage_root"]})
            meta_path.write_text(json.dumps(m))
    except Exception:
        logger.exception("lineage tagging failed for chat %s", cid)


def _copy_artifact_to_chat(src_cid: int, art_id: str, dst_cid: int,
                           meta: dict) -> Optional[dict]:
    """Duplicate a canvas artifact into another chat's store.

    A chat's canvas is fed by the artifacts attached to that chat's own messages,
    so a hand-off into a *fresh* chat has to carry the visual with it — otherwise
    the new room talks about an artifact nobody there can open. Link artifacts
    hold no bytes, so their record travels as-is. Fail-open: a failed copy costs
    the new chat its canvas card, never the hand-off."""
    try:
        if (meta.get("render") == "link" or meta.get("kind") == "url"):
            if meta.get("external_url"):
                return {k: v for k, v in meta.items()
                        if k not in ("content", "truncated")}
            return None
        bytes_path, _ = artifact_paths(DATA_DIR, src_cid, art_id)
        if bytes_path is None:
            return None
        title = str(meta.get("title") or meta.get("kind") or "artifact")[:160]
        stem = re.sub(r"[^\w .-]+", "_", title).strip() or "artifact"
        return register_file_artifact(
            DATA_DIR, dst_cid, meta.get("agent_id"), bytes_path, title,
            source_name=f"{stem[:80]}{bytes_path.suffix}",
        )
    except Exception:
        logger.exception("canvas hand-off copy failed (%s -> %s)", src_cid, dst_cid)
        return None


def _chat_canvas_artifacts(cid: int) -> list:
    """Every canvas artifact in a chat, oldest-first, for the gallery."""
    out = []
    for msg in _load_thread(cid):
        for a in (msg.get("artifacts") or []):
            if isinstance(a, dict) and a.get("id"):
                out.append(a)
    return out


def _canvas_artifacts_as_files(cid: int) -> list[dict]:
    """Agent-created canvas artifacts normalized to the Files-tab record shape, so
    the unified Files view (api_chat_artifacts) shows them alongside uploads. They
    keep serving from /artifacts/<cid>/<id> — no bytes are moved. Link/url artifacts
    (no downloadable file) are skipped; re-emitted ids are de-duped."""
    out: list[dict] = []
    seen: set = set()
    for a in _chat_canvas_artifacts(cid):
        aid = a.get("id")
        if not aid or aid in seen:
            continue
        # Agent attachment uploads get a Canvas overlay backed by the same
        # delivered file.  The attachment row is already in Files; listing the
        # overlay too would show two identical cards.
        if a.get("source_attachment_id"):
            continue
        kind = (a.get("kind") or "").lower()
        if kind == "url" or a.get("render") == "link":
            continue
        seen.add(aid)
        agent_id = a.get("agent_id") or ""
        bytes_path, _ = artifact_paths(DATA_DIR, cid, aid)
        out.append({
            "id": aid,
            "chat_id": int(cid),
            "name": a.get("title") or (kind.upper() if kind else "Artifact"),
            "mime": a.get("mime") or "application/octet-stream",
            "size": int(a.get("size") or 0),
            "uploader": agent_id or "agent",
            "source": "agent",
            "source_name": AGENTS_BY_ID.get(agent_id, {}).get("name", agent_id or "agent"),
            "ts": int(a.get("ts") or 0),
            "exists": bool(bytes_path and bytes_path.is_file()),
            "url": a.get("url") or f"/artifacts/{int(cid)}/{aid}",
            "origin": "canvas",
            "kind": kind,
        })
    return out


@app.get("/api/chats/{cid}/canvas")
async def api_chat_canvas(cid: int, request: Request):
    """Gallery feed: all agent-generated canvas artifacts for a chat."""
    blocked = _require_chat_access(request, cid)
    if blocked: return blocked
    return {"status": "ok", "chat_id": cid, "artifacts": _chat_canvas_artifacts(cid)}


@app.post("/api/canvas/handoff")
async def api_canvas_handoff(request: Request):
    """Hand a canvas artifact to another agent with its content as context, and
    record the resulting artifact as the next version in the lineage.

    `instruction` is whatever the user typed alongside the hand-off. With
    `new_chat` the pair moves into a fresh 1:1 chat with that agent (the artifact
    is copied across so the new room's canvas still shows it) instead of adding a
    turn to the room the artifact came from."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    body = await request.json()
    cid = int(body.get("chat_id") or _active_chat_id_for_request(request) or 0)
    blocked = _require_chat_access(request, cid)
    if blocked:
        return blocked
    if _track_current_chat_task(cid) is None:
        return JSONResponse({"error": "chat not found"}, status_code=404)
    art_id = str(body.get("artifact_id") or "")
    agent_id = str(body.get("agent") or "")
    instruction = str(body.get("instruction") or "").strip()[:1000]
    new_chat = bool(body.get("new_chat"))
    agent = AGENTS_BY_ID.get(agent_id)
    if not agent or agent_id not in _allowed_agent_ids_for_chat(cid):
        return JSONResponse({"error": "unknown agent"}, status_code=400)
    art = read_artifact(DATA_DIR, cid, art_id)
    if not art:
        return JSONResponse({"error": "artifact not found"}, status_code=404)

    author = AGENTS_BY_ID.get(art.get("agent_id") or "", {}).get(
        "name", art.get("agent_id") or "someone")
    title = art.get("title") or art.get("kind") or "artifact"
    note = (f'@{agent_id} {instruction or "improve this"} '
            f'— handing you {author}\'s "{title}" ({art.get("kind")}).')
    principal = _chat_principal_name(cid)

    # Where the hand-off lands: this room, or a fresh 1:1 with the agent.
    target_cid, target_art_id, seeded = cid, art_id, None
    if new_chat:
        user = _current_user(request)
        src_title = (CHAT_INDEX["chats"].get(str(cid)) or {}).get("title") or f"#{cid}"
        try:
            target_cid = _create_chat_record(
                f"{agent['name']} · {title}", mode="solo", targets=[agent_id],
                owner_user_id=int(user["id"]), parent_chat_id=cid,
            )
        except KeyError:
            return JSONResponse({"error": "could not open a new chat"}, status_code=400)
        if _track_current_chat_task(target_cid) is None:
            return JSONResponse({"error": "new chat is unavailable"}, status_code=409)
        await _route_system_note(
            target_cid, f'Hand-off from {src_title} — {author}\'s "{title}".')
        copied = _copy_artifact_to_chat(cid, art_id, target_cid, art)
        if copied:
            seeded = [copied]
            target_art_id = copied["id"]
        _set_active_chat_for_request(request, target_cid)
        await broadcast({
            "type": "chat_meta",
            "owner_user_id": int(user["id"]),
            "chat_id": target_cid,
            "title": CHAT_INDEX["chats"][str(target_cid)]["title"],
            "mode": "solo",
            "targets": [agent_id],
            "project_id": _chat_project_id(target_cid),
            "parent_chat_id": cid,
            "ts": CHAT_INDEX["chats"][str(target_cid)]["ts"],
        }, global_event=True)

    entry = append_thread(target_cid, "user", None, principal, note,
                          artifacts=seeded)
    await broadcast({
        "type": "message", "chat_id": target_cid, "id": uuid.uuid4().hex,
        "sender": "user", "text": note, "ts": entry["ts"],
        **({"artifacts": seeded} if seeded else {}),
    })

    if art.get("content"):
        block = (f'\n\n--- ARTIFACT CONTENT ({art.get("mime")}) ---\n'
                 f'{art["content"]}\n--- END ARTIFACT ---'
                 + ("\n(content truncated)" if art.get("truncated") else ""))
    else:
        url = (art.get("external_url")
               or f"{ORCHESTRATOR_PUBLIC_URL}/artifacts/{target_cid}/{target_art_id}")
        block = f'\n\n(The artifact is binary — {art.get("mime")}. It is served at {url}.)'
    prompt = (
        f'[CANVAS HAND-OFF] {principal} handed you a visual artifact from '
        f'@{art.get("agent_id")} titled "{title}" ({art.get("kind")}).\n'
        f'Instruction: {instruction or "Improve it and return an updated version."}'
        f'{block}\n\n'
        f'If you produce an improved version, emit it as a new ```artifact block so '
        f'it opens in the canvas as the next version.'
    )
    # Only claim a lineage the target chat can actually resolve — if the copy into
    # a new chat failed, its improved version starts a fresh chain there instead of
    # pointing at a parent that room has never seen.
    if target_cid == cid or seeded:
        _PENDING_LINEAGE[(int(target_cid), agent_id)] = target_art_id
    _spawn_chat_task(target_cid, dispatch_to_agent(
        agent, target_cid, solo=False,
        mode=_get_execution_chat_mode(target_cid),
        auto_forward=False, prompt_override=prompt,
    ))
    return {"ok": True, "agent": agent_id, "artifact_id": target_art_id,
            "chat_id": target_cid, "new_chat": bool(new_chat)}


# --- Pull an agent's workspace output into the chat --------------------------
# The file-capable agents (claude/codex/antigravity/minimax) work in the per-chat
# workspace and are *supposed* to POST each result to attachment_save and/or emit
# a ```artifact so it shows up in the chat. They keep forgetting. The "Save files
# to chat" button on an agent reply calls the endpoint below, which deterministically
# pulls the files that turn touched into the chat's Files (attachments) + the canvas,
# and falls back to nudging the agent if the workspace genuinely has nothing new.
PULL_MAX_FILES = 30
PULL_MAX_BYTES_PER_FILE = 25 * 1024 * 1024
PULL_MAX_TOTAL_BYTES = 80 * 1024 * 1024
PULL_LOOKBACK_MS = 24 * 60 * 60 * 1000  # never reach back further than this
PULL_TURN_GRACE_MS = 2 * 60 * 1000       # a turn may still flush files this long after its reply

# Directory names pruned during the scan: VCS/build/deps + this app's own runtime
# data (protects the case where a chat is bound to the Agent-Chat dir itself).
PULL_SKIP_DIRS = {
    ".git", ".hg", ".svn", "node_modules", "__pycache__", ".venv", "venv",
    "env", ".next", ".nuxt", "dist", "build", "out", "target", ".cache",
    ".idea", ".vscode", ".pytest_cache", ".mypy_cache", ".ruff_cache",
    "coverage", ".gradle", ".terraform", "vendor", "obj",
    "attachments", "threads", "artifacts_store", "storage_backups",
    "cutover_backups", "voice_cache", "push_state", "agents", "backup",
    # Retired browser-control directories may contain sensitive raw page
    # captures; never ingest restored remnants as chat attachments.
    "chrome_bridge", "browser_captures", "browser_downloads",
}
# Extensions never pulled (secrets, databases, compiled/junk, lockfiles).
PULL_SKIP_EXTS = {
    "env", "sqlite3", "sqlite", "db", "wal", "shm", "pem", "key", "pyc",
    "pyo", "lock", "tmp", "swp", "swo", "pid",
}
# Exact filenames never pulled.
PULL_SKIP_NAMES = {
    ".env", ".ds_store", "sessions.json", "chats_index.json",
    "workspace_bindings.json", "package-lock.json", "yarn.lock",
    "pnpm-lock.yaml", "poetry.lock", "thumbs.db",
}


def _scan_workspace_new_files(
    ws: Path, since_ms: int, until_ms: Optional[int] = None
) -> list[Path]:
    """Files under `ws` modified at/after `since_ms` (and, when `until_ms` is
    given, at/before it — bounding the scan to ONE turn's files instead of
    everything touched since), newest last, with junk and secrets pruned.
    Bounded by PULL_MAX_FILES + size caps so a bound real project (or a
    runaway build) can't flood the chat."""
    since_s = since_ms / 1000.0
    until_s = (until_ms / 1000.0) if until_ms else None
    hits: list[tuple[float, Path]] = []
    try:
        root = ws.resolve()
    except OSError:
        return []
    for dirpath, dirnames, filenames in os.walk(root):
        # Prune junk/dot/runtime dirs in place so os.walk never descends them.
        dirnames[:] = [
            d for d in dirnames
            if not d.startswith(".") and d.lower() not in PULL_SKIP_DIRS
        ]
        for fn in filenames:
            if fn.startswith("."):
                continue
            if fn.lower() in PULL_SKIP_NAMES:
                continue
            ext = fn.rsplit(".", 1)[-1].lower() if "." in fn else ""
            if ext in PULL_SKIP_EXTS:
                continue
            p = Path(dirpath) / fn
            try:
                st = p.stat()
            except OSError:
                continue
            if st.st_mtime < since_s:
                continue
            if until_s is not None and st.st_mtime > until_s:
                continue
            if st.st_size <= 0 or st.st_size > PULL_MAX_BYTES_PER_FILE:
                continue
            hits.append((st.st_mtime, p))
    hits.sort(key=lambda t: t[0])           # oldest first
    selected = hits[-PULL_MAX_FILES:]        # keep the newest N
    out: list[Path] = []
    total = 0
    for _mtime, p in selected:
        try:
            sz = p.stat().st_size
        except OSError:
            continue
        if total + sz > PULL_MAX_TOTAL_BYTES:
            break
        total += sz
        out.append(p)
    return out


# File-capable host bridges receive `_chat_workspace(cid)` as their real cwd.
# Snapshot that attached folder before each turn and automatically register any
# user-facing files they create or edit.  This is the enforcement layer behind
# the prompt protocol: a missed ```artifact fence can no longer strand a report
# on disk where the user and the Canvas cannot see it.
AUTO_CAPTURE_WORKSPACE_AGENT_IDS = {
    CODEX_AGENT_ID, CLAUDE_AGENT_ID, MINIMAX_AGENT_ID,
    ANTIGRAVITY_AGENT_ID, GROK_AGENT_ID,
}
AUTO_CAPTURE_EXTS = {
    # Documents / structured deliverables
    "md", "markdown", "html", "htm", "pdf", "doc", "docx", "xlsx",
    "pptx", "csv",
    # Images / visual media
    "png", "jpg", "jpeg", "gif", "webp", "bmp", "ico", "svg",
    "mp4", "webm", "mov", "m4v",
}

# Research-monitor skills can produce several versions of the same report during
# a retry or correction. Their run manifest is the authoritative delivery list;
# without this scope, the workspace safety net can attach stale files from an
# earlier attempt beside the corrected report.
MANIFEST_SCOPED_SKILL_SLUGS = {
    "hype-trump-signal-momentum-scan",
    "truth-social-momentum-hunter",
    "reddit-investment-momentum-tracker",
    "brokerage-portfolio-monitor",
    "x-hype-hedge-fund-desk",
}
MANIFEST_ARTIFACT_KEYS = {
    "raw", "analysis", "html", "audit", "ledger", "quality", "snapshot",
    "edge", "plan", "plan_html",
}


def _workspace_artifact_snapshot(ws: Path) -> dict[str, tuple[int, int]]:
    """Metadata snapshot of auto-capturable files in one attached workspace.

    Symlinks are deliberately ignored: automatic capture must never turn a link
    to a file outside the granted chat workspace into an exfiltration path.
    """
    out: dict[str, tuple[int, int]] = {}
    try:
        root = ws.resolve()
    except OSError:
        return out
    if not root.is_dir():
        return out
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [
            d for d in dirnames
            if not d.startswith(".") and d.lower() not in PULL_SKIP_DIRS
        ]
        for fn in filenames:
            if fn.startswith(".") or fn.lower() in PULL_SKIP_NAMES:
                continue
            ext = fn.rsplit(".", 1)[-1].lower() if "." in fn else ""
            if ext not in AUTO_CAPTURE_EXTS:
                continue
            p = Path(dirpath) / fn
            try:
                if p.is_symlink():
                    continue
                st = p.stat()
                p.resolve().relative_to(root)
            except (OSError, ValueError):
                continue
            if st.st_size <= 0 or st.st_size > PULL_MAX_BYTES_PER_FILE:
                continue
            try:
                rel = str(p.relative_to(root))
            except ValueError:
                continue
            out[rel] = (int(st.st_mtime_ns), int(st.st_size))
    return out


def _workspace_artifact_changes(
    ws: Path, before: dict[str, tuple[int, int]],
) -> list[Path]:
    """Return bounded supported files whose size/mtime changed since snapshot."""
    try:
        root = ws.resolve()
    except OSError:
        return []
    after = _workspace_artifact_snapshot(root)
    changed: list[tuple[int, str, Path]] = []
    for rel, fingerprint in after.items():
        if before.get(rel) == fingerprint:
            continue
        p = root / rel
        changed.append((fingerprint[0], rel, p))
    changed.sort(key=lambda item: (item[0], item[1]))
    selected = changed[-PULL_MAX_FILES:]
    out: list[Path] = []
    total = 0
    for _mtime_ns, _rel, p in selected:
        try:
            size = p.stat().st_size
        except OSError:
            continue
        if total + size > PULL_MAX_TOTAL_BYTES:
            break
        total += size
        out.append(p)
    return out


def _chat_skill_slug(cid: int) -> str:
    chat = (CHAT_INDEX.get("chats") or {}).get(str(int(cid))) or {}
    sid = chat.get("skill_id")
    if not sid:
        return ""
    try:
        skill = _get_skill(int(sid)) or {}
    except Exception:
        return ""
    return str(skill.get("slug") or "").strip()


def _manifest_scoped_artifact_candidates(
    cid: int, workspace: Path, changed: list[Path],
) -> Optional[list[Path]]:
    """Return only the newest run manifest's declared deliverables.

    ``None`` means ordinary workspace capture should continue. A list means a
    manifest-scoped skill was detected and the list is authoritative, including
    an empty list for malformed or unsafe manifests.
    """
    slug = _chat_skill_slug(cid)
    if slug not in MANIFEST_SCOPED_SKILL_SLUGS or not changed:
        return None
    try:
        root = workspace.resolve()
    except OSError:
        return []

    manifest_paths: set[Path] = set()
    for candidate in changed:
        parent = candidate.parent
        while True:
            manifest = parent / "run-manifest.json"
            if manifest.is_file():
                manifest_paths.add(manifest)
                break
            if parent == root or root not in parent.parents:
                break
            parent = parent.parent
    if not manifest_paths:
        return None

    valid: list[tuple[datetime, int, Path, list[Path]]] = []
    for manifest_path in manifest_paths:
        try:
            payload = json.loads(manifest_path.read_text(encoding="utf-8"))
            if payload.get("schema_version") != 2:
                continue
            if payload.get("skill_slug") != slug:
                continue
            run_ts = datetime.fromisoformat(
                str(payload.get("run_timestamp") or "").replace("Z", "+00:00")
            )
            if run_ts.tzinfo is None:
                continue
            artifacts = payload.get("artifacts")
            if not isinstance(artifacts, dict):
                continue
            run_root = manifest_path.parent.resolve()
            run_root.relative_to(root)
            if payload.get("run_id") != run_root.name:
                continue
            declared: list[Path] = [manifest_path.resolve()]
            core_found: set[str] = set()
            for key, value in artifacts.items():
                if key not in MANIFEST_ARTIFACT_KEYS or not isinstance(value, str):
                    continue
                rel = value.strip()
                if not rel:
                    continue
                artifact_path = (run_root / rel).resolve()
                artifact_path.relative_to(run_root)
                if artifact_path.is_file() and artifact_path.stat().st_size > 0:
                    declared.append(artifact_path)
                    if key in {"raw", "analysis", "html"}:
                        core_found.add(key)
            if core_found != {"raw", "analysis", "html"}:
                continue
            valid.append((run_ts, manifest_path.stat().st_mtime_ns,
                          manifest_path, declared))
        except (OSError, ValueError, TypeError, json.JSONDecodeError):
            continue
    if not valid:
        return []
    valid.sort(key=lambda item: (item[0], item[1], str(item[2])))
    return valid[-1][3]


def _stored_artifact_digest(cid: int, artifact: dict) -> Optional[str]:
    """Best-effort SHA-256 for one Canvas overlay or linked attachment."""
    aid = str((artifact or {}).get("id") or "")
    if not aid:
        return None
    attachment_id = str((artifact or {}).get("source_attachment_id") or "")
    if attachment_id:
        bytes_path, _ = _attachment_paths(cid, attachment_id)
    else:
        bytes_path, _ = artifact_paths(DATA_DIR, cid, aid)
    try:
        if bytes_path is not None and bytes_path.is_file():
            return hashlib.sha256(bytes_path.read_bytes()).hexdigest()
    except OSError:
        pass
    return None


# Delivery-claim phrases that gate FIRST-TIME fresh-attach recovery: a reply must
# actually assert it put the file on the Canvas / in Files, so an incidental
# filename mention ("I read notes.md") never yanks an unrelated workspace file in.
_CANVAS_CLAIM_RE = re.compile(
    r"\b(?:canvas|attach\w*|pinned|delivered|files tab|renders? live)\b",
    re.IGNORECASE,
)


def _reply_claims_canvas_delivery(text: str) -> bool:
    """True when a reply asserts a file was placed on the Canvas / in Files."""
    return bool(text and _CANVAS_CLAIM_RE.search(text))


def _resurface_claimed_deliverables(
    cid: int, agent_id: str, workspace: Path, reply_text: str,
) -> list[dict]:
    """Attach a Canvas deliverable a reply *claims* but never carried.

    The failure this closes: an agent tells the user a file is on the Canvas but
    emits no fence and changes no bytes, so the message rides zero artifacts and
    the Canvas claim is empty. For every workspace file whose exact filename
    appears in the reply, in two tiers:

      1. Re-surface — if the file already has a Canvas artifact, the newest one is
         re-attached (same id, so no bytes are duplicated and the id-keyed gallery
         never doubles up).
      2. Fresh-attach — if it has NO Canvas artifact yet the reply makes an explicit
         delivery claim ("Canvas", "attached", "pinned", "Files tab"…), the file is
         registered from disk. This covers the *first-time* claim, where the file's
         creating turn never produced an artifact (missed byte-diff, no fence) so
         there is nothing to re-surface. Once attached it becomes the tier-1
         baseline, which keeps repeat runs idempotent.
    """
    if not reply_text:
        return []
    newest_by_name: dict[str, dict] = {}
    for art in _chat_canvas_artifacts(cid):
        name = str(art.get("source_name") or "")
        if not name or not art.get("id"):
            continue
        cur = newest_by_name.get(name)
        if cur is None or int(art.get("ts") or 0) >= int(cur.get("ts") or 0):
            newest_by_name[name] = art
    claims_delivery = _reply_claims_canvas_delivery(reply_text)
    out: list[dict] = []
    seen_ids: set[str] = set()
    for rel in _workspace_artifact_snapshot(workspace):
        name = Path(rel).name
        if name not in reply_text:
            continue
        art = newest_by_name.get(name)
        if art:
            art_id = str(art.get("id"))
            if art_id in seen_ids:
                continue
            seen_ids.add(art_id)
            rec = dict(art)
            rec["capture"] = "workspace_redeliver"
            out.append(rec)
        elif claims_delivery:
            fresh = register_file_artifact(
                DATA_DIR, cid, agent_id, workspace / rel, title=name,
                source_name=name,
            )
            if fresh:
                fresh["capture"] = "workspace_claim_recover"
                out.append(fresh)
        if len(out) >= PULL_MAX_FILES:
            break
    return out


def _auto_capture_workspace_artifacts(
    cid: int,
    agent_id: str,
    workspace: Path,
    before: dict[str, tuple[int, int]],
    turn_artifacts: Optional[list] = None,
    reply_text: str = "",
) -> list[dict]:
    """Register changed deliverables from a completed agent turn on the Canvas.

    Content hashes make the operation idempotent and prevent a correctly emitted
    path-backed artifact fence from being duplicated by this safety net.

    reply_text closes the "claimed but empty" gap: when a turn writes no fence and
    changes no bytes yet the agent still tells the user a file is on the Canvas
    (naming it), the existing artifact for that named-and-present workspace file is
    re-surfaced onto this turn so the claim is never a blank Canvas.
    """
    candidates = _workspace_artifact_changes(workspace, before)
    if not candidates:
        # No bytes changed this turn — but the reply may still claim a file is on
        # the Canvas. Re-surface the existing artifact for any named, on-disk file.
        if not turn_artifacts and reply_text:
            return _resurface_claimed_deliverables(cid, agent_id, workspace, reply_text)
        return []

    scoped = _manifest_scoped_artifact_candidates(cid, workspace, candidates)
    if scoped is not None:
        candidates = scoped
        if not candidates:
            return []

    # Anything already emitted in this reply wins (it may carry a custom title,
    # lineage, or render hints).  Hash all of those regardless of filename.
    turn_hashes = {
        digest for art in (turn_artifacts or [])
        if (digest := _stored_artifact_digest(cid, art))
    }

    # Older same-name files in either view are the idempotence baseline.  A new
    # version with different bytes is still captured.
    existing_by_name: dict[str, set[str]] = {}
    # Display labels already visible in Files/Canvas. A same-name-different-bytes
    # capture disambiguates its title against this so no two distinct files share
    # a label; the basename identity key (existing_by_name) is kept separate so
    # re-scans stay idempotent.
    taken_titles: set[str] = set()
    for art in _chat_canvas_artifacts(cid):
        name = str(art.get("source_name") or art.get("title") or "")
        label = str(art.get("title") or art.get("source_name") or "")
        if label:
            taken_titles.add(label)
        if not name:
            continue
        digest = _stored_artifact_digest(cid, art)
        if digest:
            existing_by_name.setdefault(name, set()).add(digest)
    for att in _list_attachment_meta(cid):
        name = str(att.get("name") or "")
        if name:
            taken_titles.add(name)
        file_id = str(att.get("id") or "")
        bytes_path, _ = _attachment_paths(cid, file_id)
        try:
            if name and bytes_path is not None and bytes_path.is_file():
                digest = hashlib.sha256(bytes_path.read_bytes()).hexdigest()
                existing_by_name.setdefault(name, set()).add(digest)
        except OSError:
            pass

    captured: list[dict] = []
    for path in candidates:
        try:
            digest = hashlib.sha256(path.read_bytes()).hexdigest()
        except OSError:
            continue
        if digest in turn_hashes or digest in existing_by_name.get(path.name, set()):
            continue
        display_title = _uniquify_artifact_name(path.name, taken_titles)
        art = register_file_artifact(
            DATA_DIR, cid, agent_id, path, title=display_title,
            source_name=path.name,
        )
        if not art:
            continue
        taken_titles.add(display_title)
        art["capture"] = "workspace_auto"
        # Keep the marker in the sidecar too (handoff/readback sees it).
        _bytes_path, meta_path = artifact_paths(DATA_DIR, cid, art["id"])
        if meta_path is not None:
            try:
                meta = json.loads(meta_path.read_text())
                meta["capture"] = "workspace_auto"
                meta_path.write_text(json.dumps(meta))
            except Exception:
                pass
        captured.append(art)
        turn_hashes.add(digest)
        existing_by_name.setdefault(path.name, set()).add(digest)

    # Claimed-but-empty recovery: the turn delivered nothing, so if the reply still
    # names an on-disk file that already has a Canvas artifact, re-surface it.
    if not captured and not turn_artifacts and reply_text:
        captured.extend(_resurface_claimed_deliverables(cid, agent_id, workspace, reply_text))
    return captured


def _recover_interrupted_agent_output(
    cid: int,
    agent: dict,
    workspace: Path,
    before: dict[str, tuple[int, int]],
    error: Exception,
) -> Optional[dict]:
    """Persist useful output created before a bridge/provider interruption.

    Any workspace agent can finish a file or stream part of an answer just
    before a quota wall, timeout, or transport failure. Returning an ordinary
    agent entry lets the existing Canvas and usage paths remain the single
    source of truth.
    """
    partial = str(getattr(error, "partial_response", "") or "").strip()
    try:
        clean_partial, artifacts = extract_artifacts(
            partial,
            base_dir=DATA_DIR,
            cid=cid,
            agent_id=agent["id"],
            workspace_dir=str(workspace),
        ) if partial else ("", [])
    except Exception:
        logger.exception(
            "interrupted artifact extraction failed for chat %s agent %s",
            cid, agent.get("id"),
        )
        clean_partial, artifacts = partial, []
    try:
        captured = _auto_capture_workspace_artifacts(
            cid, agent["id"], workspace, before, artifacts,
            reply_text=clean_partial,
        )
        artifacts.extend(captured)
    except Exception:
        logger.exception(
            "interrupted workspace recovery failed for chat %s agent %s",
            cid, agent.get("id"),
        )
        captured = []
    if not clean_partial and not artifacts:
        return None

    has_files = bool(artifacts)
    what = (
        "its partial response and the files it created"
        if clean_partial and has_files else
        "its partial response" if clean_partial else
        "the files it created"
    )
    text = (
        f"BOTTOM LINE: {agent.get('name', 'The agent')} was interrupted before "
        f"final delivery, but Agent Chat recovered {what}."
    )
    if clean_partial:
        text += "\n\nRecovered partial response:\n\n" + clean_partial
    elif has_files:
        text += "\n\nThe recovered deliverables are attached to this message."

    metadata = {
        "agent_id": agent["id"],
        "interrupted": True,
        "recovered_output": True,
        "interruption": str(error or "")[:300],
    }
    for key in ("model", "reasoning"):
        value = str(getattr(error, key, "") or "").strip()
        if value:
            metadata[key] = value
    usage = getattr(error, "usage", None)
    if isinstance(usage, dict):
        metadata["usage"] = usage
    if captured:
        metadata["auto_captured_files"] = [
            a.get("source_name") or a.get("title") for a in captured
        ]
    return append_thread(
        cid, "agent", agent["id"], agent["name"], text,
        artifacts=artifacts, metadata=metadata,
    )


def _turn_window_ms(cid: int, agent_id: str, msg_ts: int) -> tuple[int, int]:
    """The window the agent's turn ran in: from the nearest user message at/before
    its reply to just past the reply itself — the next user message if one landed
    sooner, else msg_ts + PULL_TURN_GRACE_MS (agents can flush files a beat after
    replying). Bounding BOTH ends keeps the workspace scan to files THIS turn
    touched; an open end used to sweep in every later turn's work. The lower
    bound is clamped to PULL_LOOKBACK_MS so a missing boundary can't grab old
    work."""
    floor = int(msg_ts) - PULL_LOOKBACK_MS
    until = int(msg_ts) + PULL_TURN_GRACE_MS
    thread = _load_thread(cid)
    idx = None
    for i, m in enumerate(thread):
        if (m.get("role") == "agent" and m.get("agent_id") == agent_id
                and int(m.get("ts") or 0) == int(msg_ts)):
            idx = i
            break
    if idx is None:  # exact ts not found — use this agent's most recent reply
        for i in range(len(thread) - 1, -1, -1):
            m = thread[i]
            if m.get("role") == "agent" and m.get("agent_id") == agent_id:
                idx = i
                break
    if idx is None:
        return floor, until
    for j in range(idx + 1, len(thread)):
        if thread[j].get("role") == "user":
            # The next user message provably starts the next turn.
            until = min(until, max(int(thread[j].get("ts") or until), int(msg_ts)))
            break
    for j in range(idx - 1, -1, -1):
        if thread[j].get("role") == "user":
            return max(floor, int(thread[j].get("ts") or floor)), until
    return floor, until


@app.post("/api/chats/{cid}/pull_workspace")
async def api_pull_workspace(cid: int, request: Request):
    """Pull the files an agent's turn created in the chat workspace into the chat:
    each becomes a canvas artifact (always — sandboxed, so HTML/SVG is safe) and,
    when it clears the upload guard, a downloadable attachment in the Files tab.
    If the workspace has nothing new, fall back to nudging the agent to save its
    own work. Body: {agent_id, ts}."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_chat_access(request, cid)
    if blocked:
        return blocked
    if _track_current_chat_task(cid) is None:
        return JSONResponse({"error": "chat is unavailable"}, status_code=409)
    try:
        body = await request.json()
    except json.JSONDecodeError:
        body = {}
    agent_id = str(body.get("agent_id") or "").strip()
    try:
        msg_ts = int(body.get("ts") or 0)
    except (TypeError, ValueError):
        msg_ts = 0
    agent = AGENTS_BY_ID.get(agent_id)
    if not agent or agent_id not in _allowed_agent_ids_for_chat(cid):
        return JSONResponse({"error": "unknown agent"}, status_code=400)
    if not msg_ts:
        msg_ts = int(time.time() * 1000)

    ws = Path(_chat_workspace(cid))
    since_ms, until_ms = _turn_window_ms(cid, agent_id, msg_ts)
    candidates = _scan_workspace_new_files(ws, since_ms, until_ms)

    # Dedupe against what's already in the chat so re-clicks are idempotent.
    # Classification is by CONTENT HASH, computed lazily for names that collide
    # with an existing record — an unchanged file never re-attaches, while a
    # same-size edit (dates, version bumps) still pulls through. Recorded
    # (name, size) pairs are NOT trusted on their own: same size ≠ same bytes.
    att_by_name: dict = {}
    art_by_name: dict = {}
    for m in _list_attachment_meta(cid):
        att_by_name.setdefault(m.get("name"), []).append(m.get("id"))
    for a in _chat_canvas_artifacts(cid):
        nm = a.get("source_name") or a.get("title")
        art_by_name.setdefault(nm, []).append(a.get("id"))

    hash_cache: dict = {}

    def _existing_hashes(name) -> set:
        """sha256 of every already-attached file/artifact with this name — read
        lazily (only names that collide with a candidate) and cached."""
        if name in hash_cache:
            return hash_cache[name]
        digests: set = set()
        for fid in att_by_name.get(name, ()):
            bp, _mp = _attachment_paths(cid, fid)
            try:
                if bp is not None and bp.is_file():
                    digests.add(hashlib.sha256(bp.read_bytes()).hexdigest())
            except OSError:
                pass
        for aid in art_by_name.get(name, ()):
            bp, _mp = artifact_paths(DATA_DIR, cid, aid)
            try:
                if bp is not None and bp.is_file():
                    digests.add(hashlib.sha256(bp.read_bytes()).hexdigest())
            except OSError:
                pass
        hash_cache[name] = digests
        return digests

    attachments: list = []
    artifacts: list = []
    created_attachment_ids: list[str] = []
    created_artifacts: list[dict] = []
    blocked_names: list = []
    duplicates = 0

    def _rollback_unpublished_pull() -> None:
        for file_id in created_attachment_ids:
            _discard_ingress_attachment(cid, file_id)
        for artifact in created_artifacts:
            _discard_ingress_artifact(cid, artifact)

    for p in candidates:
        try:
            data = p.read_bytes()
        except OSError:
            continue
        digest = hashlib.sha256(data).hexdigest()
        if digest in _existing_hashes(p.name):
            duplicates += 1
            continue
        _existing_hashes(p.name).add(digest)
        mime = (mimetypes.guess_type(p.name)[0] or "application/octet-stream").lower()
        attachment_blocked = bool(_mime_blocked(mime) or _looks_like_active_content(data))
        pending_attachment = None
        if attachment_blocked:
            blocked_names.append(p.name)
        else:
            file_id = uuid.uuid4().hex
            bytes_path, meta_path = _attachment_paths(cid, file_id)
            if bytes_path is None:
                continue
            try:
                bytes_path.write_bytes(data)
            except OSError:
                _discard_ingress_attachment(cid, file_id)
                continue
            created_attachment_ids.append(file_id)
            extracted_text = None
            if (mime in OOXML_MIMES or mime == "application/pdf"
                    or _ocr_eligible_image(mime, len(data))):
                try:
                    # Extraction workers never write chat storage. If Trash
                    # cancels this request, only the event-loop task can create
                    # or remove the sidecar.
                    extracted_text = await asyncio.to_thread(
                        _extract_attachment_text, data, mime,
                    )
                except asyncio.CancelledError:
                    _rollback_unpublished_pull()
                    raise
                except Exception:
                    extracted_text = None
            meta = {
                "id": file_id, "name": p.name[:200], "mime": mime,
                "size": len(data), "uploader": agent_id,
                "ts": int(time.time() * 1000), "hash": digest,
            }
            if not _save_attachment_meta(cid, meta):
                _rollback_unpublished_pull()
                return JSONResponse(
                    {"error": "conversation moved to Trash before workspace pull completed"},
                    status_code=409,
                )
            try:
                if extracted_text:
                    bytes_path.with_suffix(".txt").write_text(
                        extracted_text, encoding="utf-8",
                    )
                    meta["text_url"] = f"/attachments/{cid}/{file_id}/text"
                meta_path.write_text(json.dumps(meta))
            except Exception as exc:
                _rollback_unpublished_pull()
                return JSONResponse(
                    {"error": f"workspace pull failed: {exc}"}, status_code=500,
                )
            pending_attachment = {
                **meta, "url": f"/attachments/{cid}/{file_id}",
            }

        # Always register as a Canvas artifact, but only after the conditional
        # attachment-row gate for ordinary files. Canvas-only active content has
        # no attachment row, so live-row checks bracket its filesystem write.
        if not _chat_row_is_live(cid):
            _rollback_unpublished_pull()
            return JSONResponse(
                {"error": "conversation moved to Trash before workspace pull completed"},
                status_code=409,
            )
        art = register_file_artifact(DATA_DIR, cid, agent_id, p, title=p.name)
        if art:
            created_artifacts.append(art)
        if not art:
            if pending_attachment is not None:
                _discard_ingress_attachment(cid, pending_attachment["id"])
            continue
        if not _chat_row_is_live(cid):
            _rollback_unpublished_pull()
            return JSONResponse(
                {"error": "conversation moved to Trash before workspace pull completed"},
                status_code=409,
            )
        artifacts.append(art)
        if pending_attachment is not None:
            attachments.append(pending_attachment)

    n_art = len(artifacts)
    n_att = len(attachments)
    if n_art:
        canvas_only = n_art - n_att
        bits = []
        if n_att:
            bits.append(f"{n_att} into Files")
        if canvas_only > 0:
            bits.append(f"{canvas_only} to the canvas")
        where = (" (" + "; ".join(bits) + ")") if bits else ""
        names = ", ".join(a.get("source_name") or a.get("title") or "file"
                          for a in artifacts[:6])
        more = "" if n_art <= 6 else f" +{n_art - 6} more"
        text = (f"\U0001F4CE Pulled {n_art} file{'s' if n_art != 1 else ''} from the "
                f"workspace into this chat{where}: {names}{more}.")
        try:
            entry = append_thread(
                cid, "agent", agent_id, agent["name"], text,
                attachments=attachments, artifacts=artifacts,
            )
        except Exception as exc:
            _rollback_unpublished_pull()
            if not _chat_row_is_live(cid):
                return JSONResponse(
                    {"error": "conversation moved to Trash before workspace pull completed"},
                    status_code=409,
                )
            logger.exception("workspace pull message finalization failed for chat %s", cid)
            return JSONResponse({"error": f"workspace pull failed: {exc}"}, status_code=500)
        await broadcast({
            "type": "message", "chat_id": cid, "id": uuid.uuid4().hex,
            "sender": "agent", "agent_id": agent_id, "name": agent["name"],
            "text": text, "ts": entry["ts"],
            "attachments": attachments, "artifacts": artifacts,
        })
        try:
            _audit_event(
                request, "artifact.create", actor=f"agent:{agent_id}", chat_id=cid,
                target="workspace_pull", status="ok",
                meta={"files": n_art, "attached": n_att, "agent_id": agent_id},
            )
        except Exception:
            logger.warning("workspace pull audit failed for chat %s", cid, exc_info=True)
        return {"status": "ok", "mode": "pull", "pulled": n_art,
                "attached": n_att, "blocked": blocked_names}

    if duplicates:
        # This turn's files are all in the chat already. Re-clicks are a no-op;
        # nudging here made agents re-upload the same files (the double/triple
        # attachment bug), so say "unchanged" instead.
        return {"status": "ok", "mode": "unchanged", "pulled": 0,
                "duplicates": duplicates}

    # Nothing new in the workspace — nudge the agent to surface its own work.
    prompt = (
        "[SAVE YOUR WORK] The user clicked “Save files to chat”, but no new "
        f"files were found in your workspace ({ws}) for this turn. If you created or "
        "edited any file(s), surface them in this chat NOW:\n"
        f"1) POST each file to /api/chat_bridge/attachment_save (header X-API-KEY: "
        f"your token; JSON body {{\"chat_id\": {cid}, \"name\", \"mime\", \"content_b64\"}}).\n"
        "2) Also emit each as a ```artifact block (omit the body, pass \"path\" to the "
        "workspace file) so it opens in the canvas.\n"
        "Reply only with a one-line confirmation of what you saved. If you genuinely "
        "created nothing this turn, say so plainly."
    )
    _spawn_chat_task(cid, dispatch_to_agent(
        agent, cid, solo=False, mode=_get_execution_chat_mode(cid),
        auto_forward=False, prompt_override=prompt,
    ))
    return {"status": "ok", "mode": "nudge", "pulled": 0}


@app.get("/attachments/{cid}/{file_id}/text")
async def api_get_attachment_text(cid: int, file_id: str, request: Request):
    """Serve the plain-text extraction (Office text or OCR'd image) of an
    attachment. Agents fetch this instead of the opaque binary blob."""
    if not _live_attachment_token_ok(cid, file_id, request.query_params.get("k", "")):
        blocked = _require_chat_access(request, cid)
        if blocked: return blocked
    bytes_path, _ = _attachment_paths(cid, file_id)
    if bytes_path is None:
        return JSONResponse({"error": "not found"}, status_code=404)
    text_path = bytes_path.with_suffix(".txt")
    if not text_path.is_file():
        return JSONResponse({"error": "no extracted text"}, status_code=404)
    return FileResponse(
        text_path,
        media_type="text/plain; charset=utf-8",
        headers={"X-Content-Type-Options": "nosniff"},
    )


def _require_origin(request: Request) -> Optional[JSONResponse]:
    """Strict origin check for state-changing endpoints. Returns a 403 response
    if the request's Origin (or Referer fallback) is missing or not allowlisted.
    Returns None if the request is OK to proceed."""
    origin = request.headers.get("origin") or request.headers.get("referer")
    if not origin or not origin_allowed(origin, request.headers.get("host", "")):
        return JSONResponse({"error": "origin not allowed"}, status_code=403)
    return None


def _normalized_origin(value: str) -> str:
    try:
        parsed = urlparse(value)
    except ValueError:
        return ""
    if not parsed.scheme or not parsed.netloc:
        return ""
    scheme = parsed.scheme.lower()
    host = (parsed.hostname or "").lower()
    port = parsed.port
    if not host:
        return ""
    default_port = (scheme == "http" and port in (None, 80)) or (scheme == "https" and port in (None, 443))
    return f"{scheme}://{host}" if default_port else f"{scheme}://{host}:{port}"


def _host_without_port(value: str) -> str:
    if not value:
        return ""
    try:
        return (urlparse(f"//{value}").hostname or "").lower()
    except ValueError:
        return ""


ALLOWED_HOSTS = [
    h.strip().lower() for h in os.environ.get("ALLOWED_HOSTS", "").split(",") if h.strip()
]


def host_allowed(request_host: str) -> bool:
    """True when the Host header names somewhere this app is actually served.

    This closes DNS rebinding against the request classes that carry their own
    credential in the URL and therefore skip both _require_auth and
    _require_origin — signed tool URLs and signed attachment URLs. It is a
    genuinely separate control from origin_allowed: that function returns True
    whenever the Origin's hostname equals the request Host, so a name the
    attacker controls, rebound to 127.0.0.1, satisfies it by construction —
    Origin and Host are both attacker.example and they match. Comparing Origin
    to Host can never catch that; only pinning the Host to a known-good set can.

    Scope, deliberately: this is applied ONLY to the bypass paths (see
    hardening_middleware). A session-authenticated route is already safe from
    rebinding, because the session cookie was set on the app's real host and a
    browser will not send it to attacker.example — so pinning those too would
    only break legitimate reverse-proxy deployments for no security gain.

    Note this is not a CORS problem and CORS cannot solve it. CORS is a browser
    convention; any local process — another app, another installed extension
    holding http://127.0.0.1/* — reaches this port with no CORS involved at all.

    Set ALLOWED_HOSTS to pin explicitly. The defaults cover the documented
    posture (loopback, the Tailscale surface, and whatever public URL the tool
    notes are already built from) so an existing install keeps working.
    """
    host = _host_without_port(request_host or "")
    if not host:
        # Absent Host on HTTP/1.0 or a direct socket write. There is no name to
        # rebind, and the app binds loopback — nothing to reject.
        return True
    if ALLOWED_HOSTS:
        return host in ALLOWED_HOSTS
    if host in ("localhost", "127.0.0.1", "::1", "0.0.0.0"):
        return True
    # Starlette's TestClient sends Host: testserver. Accepting it unconditionally
    # would put a bypass name in the production allowlist, so it is gated on the
    # same AGENTCHAT_TEST flag conftest.py already sets (read at call time so a
    # test can clear it and assert the rejection path).
    if host == "testserver" and os.environ.get("AGENTCHAT_TEST") == "1":
        return True
    if host.endswith(".ts.net"):
        return True
    try:
        if ipaddress.ip_address(host) in ipaddress.ip_network("100.64.0.0/10"):
            return True
    except ValueError:
        pass
    # Hostnames the operator has already told us about: the explicit origin
    # allowlist, and the public URLs the signed tool notes are built from. A
    # signed URL handed to an agent has to work when it is used.
    known = set(ALLOWED_ORIGINS)
    for _key in ("ORCHESTRATOR_PUBLIC_URL", "CONTAINER_PUBLIC_URL", "PUBLIC_URL"):
        val = (os.environ.get(_key) or "").strip()
        if val:
            known.add(val)
    for origin in known:
        try:
            if (urlparse(origin).hostname or "").lower() == host:
                return True
        except ValueError:
            continue
    return False


def origin_allowed(origin: Optional[str], request_host: str = "") -> bool:
    if not origin:
        return True  # same-origin browsers may omit
    if origin.rstrip("/").lower() in ALLOWED_EXTENSION_ORIGINS:
        return True
    if ALLOWED_ORIGINS:
        normalized_allowed = {_normalized_origin(o) for o in ALLOWED_ORIGINS}
        return _normalized_origin(origin) in normalized_allowed
    try:
        host = (urlparse(origin).hostname or "").lower()
    except ValueError:
        return False
    request_host = _host_without_port(request_host)
    if request_host and host == request_host:
        return True
    if host in ("localhost", "127.0.0.1", "::1") and request_host in ("localhost", "127.0.0.1", "::1"):
        return True
    try:
        ip = ipaddress.ip_address(host)
        req_ip = ipaddress.ip_address(request_host) if request_host else None
        if req_ip and ip == req_ip and ip in ipaddress.ip_network("100.64.0.0/10"):
            return True
    except ValueError:
        pass
    return False


def _looks_like_active_content(data: bytes) -> bool:
    """Best-effort upload guard. MIME headers are user-controlled, so reject
    obvious browser-executable payloads before they become shared artifacts."""
    head = data[:4096].lstrip().lower()
    if head.startswith(b"\xef\xbb\xbf"):
        head = head[3:].lstrip()
    active_starts = (
        b"<!doctype html", b"<html", b"<script", b"<?xml", b"<svg",
        b"<iframe", b"<object", b"<embed",
    )
    if head.startswith(active_starts):
        return True
    active_needles = (
        b"<script", b"javascript:", b"<svg", b"<iframe", b"<object", b"<embed",
        b"srcdoc=", b"onload=", b"onerror=", b"data:text/html",
    )
    return any(needle in head for needle in active_needles)


# ---------- Secret declarations -----------------------------------------------
# Match natural-language secret declarations the user types in chat, e.g.
#   "set secret OPENAI_KEY=sk-xxx"
#   "Add this secret GEMINI_API=xyxftsy"
#   "add this API key RETELL_API_TEST=asdtyhdks"
#   "save the token GITHUB_TOKEN=ghp_..."
# The KEY must be uppercase to avoid matching English words; the value is a
# single non-whitespace token (typical for API keys / tokens / passwords).
SECRET_PATTERN = re.compile(
    r"""(?ix)
    \b                                              # match anywhere in the line
    (?:please\s+)?
    (?:add|set|save|store|remember|register|create|use)
    \s+
    (?:(?:this|the|a|my|new|an)\s+)?
    (?:secret|api\s*key|api|key|token|credential|password)s?
    \s*[:\-]?\s*
    ([A-Z][A-Z0-9_]*)                               # group 1: KEY
    \s*=\s*
    (\S+)                                            # group 2: VALUE
    """,
)

# "delete the secret KEY", "remove api key KEY", "forget token KEY", etc.
SECRET_DELETE_PATTERN = re.compile(
    r"""(?ix)
    \b
    (?:please\s+)?
    (?:delete|remove|forget|drop|unset|clear|revoke)
    \s+
    (?:(?:this|the|a|my|that)\s+)?
    (?:secret|api\s*key|api|key|token|credential|password)s?
    \s*[:\-]?\s*
    ([A-Z][A-Z0-9_]*)                               # group 1: KEY
    \b
    """,
)
SECRET_TRAILING_PUNCT = ".,;:!?"
SECRET_KEY_PATTERN = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
SHARED_ENV_SAFE_VALUE_PATTERN = re.compile(r"^[A-Za-z0-9_./:+@=%,-]+$")
_SECRET_RUNTIME_RESERVED_RE = re.compile(
    r"^(?:PATH|HOME|SHELL|IFS|ENV|BASH_ENV|CDPATH|GLOBIGNORE|SHELLOPTS|"
    r"BASHOPTS|PYTHONPATH|PYTHONHOME|PYTHONSTARTUP|NODE_OPTIONS|RUBYOPT|"
    r"PERL5OPT|LD_.*|DYLD_.*)$"
)


def _secret_key_is_reserved(key: str) -> bool:
    return bool(_SECRET_RUNTIME_RESERVED_RE.fullmatch((key or "").strip().upper()))


def _env_quote(value: str) -> str:
    """Render a value for a KEY=value line that is safe BOTH for the naive
    KEY=value parsers (_parse_env_value) and for `set -a; source` in bash. Bare
    when the value is in the shell-neutral safe set; otherwise single-quoted —
    bash treats single quotes 100% literally (no expansion, word-splitting, or
    command substitution), with any embedded single quote escaped as '\\'' . This
    is why a value like `a$(cmd)b` stores literally instead of executing."""
    if SHARED_ENV_SAFE_VALUE_PATTERN.match(value):
        return value
    return "'" + value.replace("'", "'\\''") + "'"


def extract_secrets(text: str) -> list[tuple[re.Match, str, str]]:
    """Return [(match, KEY, cleaned_value)] for every secret declaration.

    Skips values that already contain Agent Zero's §§secret(...) sentinel —
    that's our own rewritten output, and re-saving it would overwrite a real
    secret with the placeholder string itself."""
    out: list[tuple[re.Match, str, str]] = []
    for m in SECRET_PATTERN.finditer(text):
        key = m.group(1).upper()
        cleaned = m.group(2).rstrip(SECRET_TRAILING_PUNCT)
        if not cleaned or "§§secret(" in cleaned:
            continue
        out.append((m, key, cleaned))
    return out


async def _call_chat_bridge(
    agent: dict, handler: str, payload: dict
) -> tuple[str, Optional[str], Optional[dict]]:
    """POST to <agent>/api/plugins/chat_bridge/<handler>.
    Returns (status, err_reason, response_json)."""
    token = os.environ.get(agent.get("token_env", "")) or agent.get("token", "")
    if not token:
        return ("err", f"no API token (set {agent.get('token_env')} in .env)", None)
    url = agent["url"].replace(
        "/api/api_message", f"/api/plugins/chat_bridge/{handler}"
    )
    try:
        async with httpx.AsyncClient(timeout=15.0) as client:
            resp = await client.post(
                url,
                json=payload,
                headers={"X-API-KEY": token, "Content-Type": "application/json"},
            )
    except Exception as e:
        return ("err", str(e), None)
    if resp.status_code == 404:
        return ("err", "endpoint missing — drop the chat_bridge/ plugin into the agent's <user-dir>/plugins/ folder", None)
    try:
        body = resp.json()
    except Exception:
        body = None
    if resp.status_code == 200:
        return ("ok", None, body)
    return ("err", f"HTTP {resp.status_code}: {resp.text[:120]}", body)


async def _save_secret_to_agent(
    agent: dict, key: str, value: str
) -> tuple[str, Optional[str]]:
    status, err, _ = await _call_chat_bridge(
        agent, "secret_set", {"key": key, "value": value}
    )
    return (status, err)


async def _delete_secret_from_agent(
    agent: dict, key: str
) -> tuple[str, Optional[str]]:
    """Returns ('ok', None), ('not_found', None), or ('err', reason)."""
    status, err, body = await _call_chat_bridge(
        agent, "secret_delete", {"key": key}
    )
    if status == "ok" and isinstance(body, dict) and body.get("status") == "not_found":
        return ("not_found", None)
    return (status, err)


def _write_shared_env_secret(key: str, value: str) -> tuple[str, Optional[str]]:
    """Persist a secret for host-side bridges without exposing its value."""
    key = (key or "").strip().upper()
    if not SECRET_KEY_PATTERN.match(key):
        return ("err", "invalid key")
    if _secret_key_is_reserved(key):
        return ("err", "that key controls the host runtime and cannot be stored as a secret")
    if (
        not value
        or "§§secret(" in value
        or not SHARED_ENV_SAFE_VALUE_PATTERN.match(value)
    ):
        return (
            "err",
            "value contains characters that are not safe for agents/shared.env; save it outside chat",
        )

    SHARED_ENV_FILE.parent.mkdir(mode=0o700, exist_ok=True)
    try:
        existing = SHARED_ENV_FILE.read_text().splitlines() if SHARED_ENV_FILE.is_file() else []
    except Exception as e:
        return ("err", f"couldn't read shared env: {e}")

    prefix_re = re.compile(rf"^\s*(?:export\s+)?{re.escape(key)}\s*=")
    new_line = f"{key}={value}"
    out: list[str] = []
    replaced = False
    for line in existing:
        if prefix_re.match(line):
            if not replaced:
                out.append(new_line)
                replaced = True
            continue
        out.append(line)
    if not replaced:
        if out and out[-1].strip():
            out.append("")
        out.append(new_line)

    tmp = SHARED_ENV_FILE.with_suffix(".tmp")
    try:
        tmp.write_text("\n".join(out) + "\n")
        os.chmod(tmp, 0o600)
        tmp.replace(SHARED_ENV_FILE)
        os.chmod(SHARED_ENV_FILE, 0o600)
        os.environ[key] = value
    except Exception as e:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        return ("err", f"couldn't update shared env: {e}")
    return ("ok", None)


def _delete_shared_env_secret(key: str) -> tuple[str, Optional[str]]:
    key = (key or "").strip().upper()
    if not SECRET_KEY_PATTERN.match(key):
        return ("err", "invalid key")
    if _secret_key_is_reserved(key):
        return ("err", "that key controls the host runtime and cannot be deleted here")
    if not SHARED_ENV_FILE.is_file():
        return ("not_found", None)
    try:
        existing = SHARED_ENV_FILE.read_text().splitlines()
    except Exception as e:
        return ("err", f"couldn't read shared env: {e}")

    prefix_re = re.compile(rf"^\s*(?:export\s+)?{re.escape(key)}\s*=")
    out = [line for line in existing if not prefix_re.match(line)]
    if len(out) == len(existing):
        return ("not_found", None)

    tmp = SHARED_ENV_FILE.with_suffix(".tmp")
    try:
        tmp.write_text("\n".join(out).rstrip() + ("\n" if out else ""))
        os.chmod(tmp, 0o600)
        tmp.replace(SHARED_ENV_FILE)
        os.chmod(SHARED_ENV_FILE, 0o600)
        os.environ.pop(key, None)
    except Exception as e:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        return ("err", f"couldn't update shared env: {e}")
    return ("ok", None)


# --- Secrets panel: owner-scoped, per-agent secret management ------------------
# Values live ONLY in each agent's own store (Agent Zero vault, or a per-agent
# agents/<id>.env file). The database records key NAMES and which agents hold
# them — never the value. There is intentionally no path to read a value back.

SECRET_PANEL_KEY_RE = re.compile(r"^[A-Z][A-Z0-9_]*$")


def _agent_env_file(agent_id: str) -> Path:
    # Community credentials are user data, never application-bundle data. This
    # keeps a packaged/fresh account from discovering mailbox or secret files in
    # the source checkout that built it, and lets upgrades replace code safely.
    root = DATA_DIR / "agents" if community_mode() else BASE_DIR / "agents"
    return root / f"{agent_id}.env"


def _read_agent_env_value(agent_id: str, key: str) -> Optional[str]:
    """Read ONE secret value from an agent's own env file (agents/<id>.env),
    server-side only — the value is never exposed to the model. Backs the email
    belt tool's per-agent mailbox credential lookup."""
    env_file = _agent_env_file(agent_id)
    if not env_file.is_file():
        return None
    key = (key or "").strip().upper()
    prefix_re = re.compile(rf"^\s*(?:export\s+)?{re.escape(key)}\s*=(.*)$")
    try:
        for line in env_file.read_text().splitlines():
            m = prefix_re.match(line)
            if m:
                return m.group(1).strip().strip('"').strip("'")
    except Exception:
        return None
    return None


def _agent_email_creds(agent_id: str) -> Optional[tuple[str, str]]:
    """(account, app_password) for an agent, or None if it has no email grant.
    THIS is the per-agent access gate: no vaulted EMAIL_ACCOUNT + EMAIL_APP_PASSWORD
    => that agent has no email access, and no email tool is minted into its prompt."""
    if not agent_id:
        return None
    acct = _read_agent_env_value(agent_id, "EMAIL_ACCOUNT")
    pw = _read_agent_env_value(agent_id, "EMAIL_APP_PASSWORD")
    return (acct, pw) if (acct and pw) else None


def _agent_email_config(agent_id: str) -> Optional[dict]:
    """Full mailbox config (account, password, IMAP/SMTP host+port, From name) for
    an agent, or None if it has no email grant. Built ON TOP of _agent_email_creds
    so the access gate stays in one place. Host defaults to Gmail; override per agent
    with EMAIL_IMAP_HOST / EMAIL_SMTP_HOST / EMAIL_IMAP_PORT / EMAIL_SMTP_PORT and an
    optional EMAIL_FROM_NAME — e.g. a cPanel mailbox on secure318.inmotionhosting.com."""
    creds = _agent_email_creds(agent_id)
    if not creds:
        return None
    account, password = creds
    return imap_compose.make_config(
        account=account,
        password=password,
        imap_host=_read_agent_env_value(agent_id, "EMAIL_IMAP_HOST") or "",
        imap_port=_read_agent_env_value(agent_id, "EMAIL_IMAP_PORT") or "",
        smtp_host=_read_agent_env_value(agent_id, "EMAIL_SMTP_HOST") or "",
        smtp_port=_read_agent_env_value(agent_id, "EMAIL_SMTP_PORT") or "",
        from_name=_read_agent_env_value(agent_id, "EMAIL_FROM_NAME") or "",
        _require=False,
    )


def _agent_caldav_config(agent_id: str) -> Optional[dict]:
    """CalDAV/CardDAV config for an agent, or None if it holds neither a calendar nor
    an address-book URL. Per-agent access gate, same shape as the email one: set
    CALDAV_URL and/or CARDDAV_URL in agents/<id>.env. Credentials come from
    CALDAV_USERNAME/CALDAV_PASSWORD, falling back to the mailbox's EMAIL_ACCOUNT/
    EMAIL_APP_PASSWORD (cPanel uses the same login for mail and DAV). The DAV password
    is used verbatim — NOT space-stripped — since it is a real account password."""
    if not agent_id:
        return None
    caldav_url = _read_agent_env_value(agent_id, "CALDAV_URL") or ""
    carddav_url = _read_agent_env_value(agent_id, "CARDDAV_URL") or ""
    if not (caldav_url or carddav_url):
        return None
    username = (_read_agent_env_value(agent_id, "CALDAV_USERNAME")
                or _read_agent_env_value(agent_id, "EMAIL_ACCOUNT") or "")
    password = (_read_agent_env_value(agent_id, "CALDAV_PASSWORD")
                or _read_agent_env_value(agent_id, "EMAIL_APP_PASSWORD") or "")
    if not (username and password):
        return None
    return {"caldav_url": caldav_url, "carddav_url": carddav_url,
            "username": username, "password": password}


# ---- Multi-mailbox: one agent may hold SEVERAL mailboxes, each with its own
# authority. Backed by agents/<id>.mailboxes.json (mailbox_store), with the legacy
# single-mailbox env keys folded in as one box so nothing needs migrating. ----

_EMAIL_AUTH_RANK = {"read": 0, "draft": 1, "send": 2}


def _agent_mailbox_file(agent_id: str) -> Path:
    return _agent_env_file(agent_id).parent / f"{agent_id}.mailboxes.json"


def _normalize_mailbox(raw: dict, index: int = 0) -> Optional[dict]:
    """Turn a stored/legacy mailbox dict into a resolved one: a ready IMAP/SMTP config,
    a stable id the agent selects by, and clamped authority levels. None if no account."""
    account = str(raw.get("account") or "").strip()
    if not account:
        return None
    cfg = imap_compose.make_config(
        account=account, password=str(raw.get("password") or ""),
        imap_host=str(raw.get("imap_host") or ""), imap_port=raw.get("imap_port") or "",
        smtp_host=str(raw.get("smtp_host") or ""), smtp_port=raw.get("smtp_port") or "",
        from_name=str(raw.get("from_name") or ""), _require=False,
    )
    mid = str(raw.get("id") or account.split("@", 1)[0] or f"mailbox{index + 1}").strip()
    authority = str(raw.get("authority") or "send").strip().lower()
    if authority not in mailbox_store.EMAIL_AUTHORITIES:
        authority = "read"
    dav_authority = str(raw.get("dav_authority") or "read").strip().lower()
    if dav_authority not in mailbox_store.DAV_AUTHORITIES:
        dav_authority = "read"
    return {
        "id": mid,
        "label": str(raw.get("label") or account).strip(),
        "account": cfg["account"],
        "config": cfg,
        "authority": authority,
        "caldav_url": str(raw.get("caldav_url") or "").strip(),
        "carddav_url": str(raw.get("carddav_url") or "").strip(),
        "caldav_username": str(raw.get("caldav_username") or "").strip() or cfg["account"],
        "caldav_password": str(raw.get("caldav_password") or "").strip() or cfg["password"],
        "dav_authority": dav_authority,
    }


def _agent_mailboxes(agent_id: str) -> list:
    """Every mailbox an agent holds. JSON store first, then the legacy env single
    mailbox folded in as id 'default' (authority send / dav write, matching the
    pre-multi-mailbox behavior) unless that account is already in the store."""
    if not agent_id:
        return []
    boxes: list = []
    try:
        raw_list = mailbox_store.load(_agent_mailbox_file(agent_id)).get("mailboxes", [])
    except Exception:
        raw_list = []
    for i, raw in enumerate(raw_list):
        nb = _normalize_mailbox(raw, i)
        if nb:
            boxes.append(nb)
    legacy = _agent_email_config(agent_id)
    if legacy:
        have = {b["account"].lower() for b in boxes}
        if legacy["account"].lower() not in have:
            dav = _agent_caldav_config(agent_id) or {}
            folded = _normalize_mailbox({
                "id": "default", "account": legacy["account"], "password": legacy["password"],
                "imap_host": legacy["imap_host"], "imap_port": legacy["imap_port"],
                "smtp_host": legacy["smtp_host"], "smtp_port": legacy["smtp_port"],
                "from_name": legacy["from_name"], "authority": "send",
                "caldav_url": dav.get("caldav_url", ""), "carddav_url": dav.get("carddav_url", ""),
                "caldav_username": dav.get("username", ""), "caldav_password": dav.get("password", ""),
                "dav_authority": "write",
            }, len(boxes))
            if folded:
                boxes.append(folded)
    return boxes


def _resolve_mailbox(agent_id: str, mailbox_id: Optional[str]):
    """(mailbox, None) or (None, JSONResponse). With no ?mailbox= and exactly one box,
    that box is used; with several, the caller must name one (so a send can't silently
    go from the wrong address)."""
    boxes = _agent_mailboxes(agent_id)
    if not boxes:
        return None, JSONResponse(
            {"error": "this agent has no mailbox access — none is granted to it"},
            status_code=403)
    mid = (mailbox_id or "").strip().lower()
    if mid:
        for b in boxes:
            if b["id"].lower() == mid:
                return b, None
        return None, JSONResponse(
            {"error": f"no mailbox '{mailbox_id}' for this agent",
             "mailboxes": [b["id"] for b in boxes]}, status_code=404)
    if len(boxes) == 1:
        return boxes[0], None
    return None, JSONResponse(
        {"error": "this agent has multiple mailboxes — add ?mailbox=<id>",
         "mailboxes": [b["id"] for b in boxes]}, status_code=400)


def _mailbox_can(mbox: dict, action: str) -> bool:
    """Authority gate. Email actions ladder read⊂draft⊂send; DAV read⊂write."""
    if action in _EMAIL_AUTH_RANK:
        return _EMAIL_AUTH_RANK.get(mbox.get("authority"), 0) >= _EMAIL_AUTH_RANK[action]
    if action == "dav_read":
        return mbox.get("dav_authority") in ("read", "write")
    if action == "dav_write":
        return mbox.get("dav_authority") == "write"
    return False


# ---- Mailboxes panel: manage an agent's mailboxes from the UI. Owner/admin gated,
# per-agent, exactly like the Secrets panel. Values are write-only (never returned). ----

def _mailbox_admin_gate(request: Request, agent_id: str):
    """(user, None) if the caller may manage this agent's mailboxes, else (None, err)."""
    user = _current_user(request)
    if not user:
        return None, JSONResponse({"error": "unauthorized"}, status_code=401)
    if agent_id not in AGENTS_BY_ID:
        return None, JSONResponse({"error": "unknown agent"}, status_code=404)
    # Mailbox files and credentials are install-global per agent. An agent grant
    # permits using that agent; it does not confer configuration ownership.
    if not _is_admin_user(user):
        return None, JSONResponse({"error": "admin required"}, status_code=403)
    return user, None


def _mailbox_raw_from_payload(payload: dict) -> dict:
    """Build a storable mailbox dict from a panel POST body (only known fields)."""
    def s(k):
        return str(payload.get(k) or "").strip()

    host = s("host")
    authority = s("authority").lower() or "send"
    if authority not in mailbox_store.EMAIL_AUTHORITIES:
        authority = "read"
    dav_authority = s("dav_authority").lower() or "read"
    if dav_authority not in mailbox_store.DAV_AUTHORITIES:
        dav_authority = "read"
    return {
        "id": s("id"), "label": s("label"), "account": s("account"), "password": s("password"),
        "imap_host": s("imap_host") or host, "smtp_host": s("smtp_host") or host,
        "imap_port": s("imap_port"), "smtp_port": s("smtp_port"), "from_name": s("from_name"),
        "authority": authority, "caldav_url": s("caldav_url"), "carddav_url": s("carddav_url"),
        "caldav_username": s("caldav_username"), "caldav_password": s("caldav_password"),
        "dav_authority": dav_authority,
    }


def _panel_mailboxes(agent_id: str) -> list:
    """Mailboxes to show in the management panel. Two kinds, both with secrets masked:
      • JSON-store boxes — editable/removable here (source 'store', read_only False);
      • the legacy single-env mailbox, folded in as a READ-ONLY row (source
        'legacy_env', read_only True) so the owner can SEE the send authority it grants.
    The legacy box lives in the agent's env, not the store, so it can't be edited or
    removed here — but adding a store box with the same address suppresses the fold and
    lets its authority govern instead (that's the non-destructive way to reduce it)."""
    boxes = mailbox_store.masked(_agent_mailbox_file(agent_id))
    for b in boxes:
        b["source"] = "store"
        b["read_only"] = False
    have = {str(b.get("account", "")).strip().lower() for b in boxes}
    for nb in _agent_mailboxes(agent_id):
        if str(nb.get("account", "")).strip().lower() in have:
            continue  # this account is an editable store row already
        cfg = nb.get("config", {})
        boxes.append({
            "id": nb["id"], "label": nb.get("label") or nb["account"], "account": nb["account"],
            "authority": nb.get("authority", "send"),
            "imap_host": cfg.get("imap_host", ""), "smtp_host": cfg.get("smtp_host", ""),
            "from_name": cfg.get("from_name", ""),
            "caldav_url": nb.get("caldav_url", ""), "carddav_url": nb.get("carddav_url", ""),
            "dav_authority": nb.get("dav_authority", "read"),
            "source": "legacy_env", "read_only": True,
        })
    return boxes


@app.get("/api/agents/{agent_id}/mailboxes")
async def api_agent_mailboxes_list(agent_id: str, request: Request):
    """List an agent's mailboxes with secrets MASKED (values are never returned).
    Includes read-only legacy env boxes so their send authority is visible."""
    _user, err = _mailbox_admin_gate(request, agent_id)
    if err:
        return err
    return {
        "agent_id": agent_id,
        "mailboxes": _panel_mailboxes(agent_id),
        "agents": sorted(_allowed_agent_ids_for_user(_current_user(request))),
        "email_authorities": list(mailbox_store.EMAIL_AUTHORITIES),
        "dav_authorities": list(mailbox_store.DAV_AUTHORITIES),
    }


@app.post("/api/agents/{agent_id}/mailboxes")
async def api_agent_mailboxes_save(agent_id: str, request: Request):
    """Add or update one mailbox for an agent (upsert by id/account). The belt tools
    read the store fresh per call, so no restart is needed."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    _user, err = _mailbox_admin_gate(request, agent_id)
    if err:
        return err
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    raw = _mailbox_raw_from_payload(payload)
    if not raw["account"]:
        return JSONResponse({"error": "account is required"}, status_code=400)
    if not raw["password"] and not mailbox_store.get(_agent_mailbox_file(agent_id), raw["id"] or raw["account"].split("@", 1)[0]):
        return JSONResponse({"error": "password is required for a new mailbox"}, status_code=400)
    try:
        # keep existing secrets when the form leaves them blank on an edit
        existing = mailbox_store.get(_agent_mailbox_file(agent_id), raw["id"])
        if existing:
            if not raw["password"] and existing.get("password"):
                raw["password"] = existing["password"]
            if not raw.get("caldav_password") and existing.get("caldav_password"):
                raw["caldav_password"] = existing["caldav_password"]
        stored = mailbox_store.add(_agent_mailbox_file(agent_id), raw)
    except Exception as e:
        logger.exception("mailbox save failed for %s", agent_id)
        return JSONResponse({"error": f"could not save mailbox: {e}"}, status_code=500)
    _audit_event(request, "mailbox.save", actor=str(agent_id), status="ok",
                 meta={"mailbox": stored.get("id"), "account": stored.get("account")})
    return {"status": "ok", "mailbox_id": stored.get("id"), "restart_needed": False}


@app.delete("/api/agents/{agent_id}/mailboxes/{mailbox_id}")
async def api_agent_mailboxes_delete(agent_id: str, mailbox_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    _user, err = _mailbox_admin_gate(request, agent_id)
    if err:
        return err
    removed = mailbox_store.remove(_agent_mailbox_file(agent_id), mailbox_id)
    if removed:
        _audit_event(request, "mailbox.delete", actor=str(agent_id), status="ok",
                     meta={"mailbox": mailbox_id})
    return {"status": "ok", "removed": bool(removed)}


def _verify_mailbox_login(mbox: dict) -> dict:
    """Blocking connectivity check for one mailbox. Never raises."""
    cfg = mbox["config"]
    out: dict = {}
    try:
        M = imaplib.IMAP4_SSL(cfg["imap_host"], cfg["imap_port"], timeout=15)
        try:
            M.login(cfg["account"], cfg["password"])
            out["imap"] = "ok"
        finally:
            try:
                M.logout()
            except Exception:
                pass
    except Exception as e:
        out["imap"] = f"failed: {e}"
    if mbox["authority"] in ("send",):
        try:
            with smtplib.SMTP_SSL(cfg["smtp_host"], cfg["smtp_port"], timeout=15) as s:
                s.login(cfg["account"], cfg["password"])
            out["smtp"] = "ok"
        except Exception as e:
            out["smtp"] = f"failed: {e}"
    if mbox["caldav_url"]:
        try:
            caldav_client.list_events(mbox["caldav_url"], mbox["caldav_username"],
                                      mbox["caldav_password"], limit=1)
            out["caldav"] = "ok"
        except Exception as e:
            out["caldav"] = f"failed: {e}"
    if mbox["carddav_url"]:
        try:
            caldav_client.list_contacts(mbox["carddav_url"], mbox["caldav_username"],
                                        mbox["caldav_password"], limit=1)
            out["carddav"] = "ok"
        except Exception as e:
            out["carddav"] = f"failed: {e}"
    return out


@app.post("/api/agents/{agent_id}/mailboxes/{mailbox_id}/test")
async def api_agent_mailboxes_test(agent_id: str, mailbox_id: str, request: Request):
    """Verify a stored mailbox actually logs in (IMAP + SMTP if send + CalDAV/CardDAV)."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    _user, err = _mailbox_admin_gate(request, agent_id)
    if err:
        return err
    raw = mailbox_store.get(_agent_mailbox_file(agent_id), mailbox_id)
    if not raw:
        return JSONResponse({"error": f"no mailbox '{mailbox_id}'"}, status_code=404)
    mbox = _normalize_mailbox(raw)
    if not mbox:
        return JSONResponse({"error": "mailbox has no account"}, status_code=400)
    checks = await asyncio.to_thread(_verify_mailbox_login, mbox)
    ok = all(v == "ok" for v in checks.values()) if checks else False
    return {"status": "ok" if ok else "issues", "checks": checks}


def _container_env_file(agent_id: str) -> Optional[Path]:
    """Env file bind-mounted into a container agent's Docker runtime (compose
    mounts <agent-dir>/container.env at /opt/data/.env). Container agents run
    their tools INSIDE the container, which never reads agents/<id>.env — a
    panel grant must also land here or the agent simply never sees it. Returns
    None for host-process agents (and for container ids with no compose dir)."""
    if agent_id not in CONTAINER_AGENT_IDS:
        return None
    agent_dir = BASE_DIR / agent_id
    if not (agent_dir / "compose.yaml").is_file():
        return None
    return agent_dir / "container.env"


# Keys that configure the container runtime itself (gateway auth, dashboard
# login). A panel grant must never overwrite or strip these in container.env —
# a bad grant named API_SERVER_KEY would lock the orchestrator out of the
# container even across restarts.
_CONTAINER_RESERVED_KEY_RE = re.compile(r"^(API_SERVER_|HERMES_DASHBOARD_)")


def _panel_secret_backend(agent_id: str) -> str:
    """Storage backend the Secrets panel uses for per-agent isolation: Agent
    Zero agents get their native vault; container agents (Docker runtimes) get
    their bind-mounted container.env PLUS agents/<id>.env so the host bridge
    stays in sync; every other agent gets its OWN env file (agents/<id>.env)
    rather than the shared env, so a grant to one agent is not readable by the
    others."""
    if agent_id in AGENT_ZERO_SECRET_AGENT_IDS:
        return "agent_zero"
    if _container_env_file(agent_id) is not None:
        return "container_env"
    return "agent_env"


def _upsert_env_file_secret(
    env_file: Path, key: str, value: str, what: str = "agent env", quote: bool = False
) -> tuple[str, Optional[str]]:
    """Validated KEY=value upsert into one env file (atomic tmp+replace, 0600).
    Mirrors _write_shared_env_secret but never mutates this process's
    environment — the value belongs to a single agent runtime.

    quote=True renders the value via _env_quote (single-quoted when needed), so
    spaces and symbols like %$#()* can be stored on files whose ONLY consumers are
    the quote-aware parsers (_parse_env_value) and bash `set -a; source`. Leave it
    False for files also read by a parser that doesn't strip quotes (Docker
    env_file), which keeps those to the shell-neutral safe set."""
    key = (key or "").strip().upper()
    if not SECRET_KEY_PATTERN.match(key):
        return ("err", "invalid key")
    if _secret_key_is_reserved(key):
        return ("err", "that key controls the agent runtime and cannot be stored as a secret")
    if not value or "§§secret(" in value:
        return ("err", "value is empty or a placeholder, not a real secret")
    if quote:
        # Single-quoting makes any value shell/parse safe — the only thing that
        # can't live on one KEY=value line is a real newline or control char.
        if re.search(r"[\x00-\x1f\x7f]", value):
            return ("err", "value has a line break or control character, which can't be stored")
        rendered = _env_quote(value)
    else:
        if not SHARED_ENV_SAFE_VALUE_PATTERN.match(value):
            return (
                "err",
                "value has a character this store can't hold "
                "(allowed: letters, digits and _ . - / : + @ = % ,)",
            )
        rendered = value
    env_file.parent.mkdir(mode=0o700, exist_ok=True)
    try:
        existing = env_file.read_text().splitlines() if env_file.is_file() else []
    except Exception as e:
        return ("err", f"couldn't read {what}: {e}")

    prefix_re = re.compile(rf"^\s*(?:export\s+)?{re.escape(key)}\s*=")
    new_line = f"{key}={rendered}"
    out: list[str] = []
    replaced = False
    for line in existing:
        if prefix_re.match(line):
            if not replaced:
                out.append(new_line)
                replaced = True
            continue
        out.append(line)
    if not replaced:
        if out and out[-1].strip():
            out.append("")
        out.append(new_line)

    tmp = env_file.with_suffix(".tmp")
    try:
        tmp.write_text("\n".join(out) + "\n")
        os.chmod(tmp, 0o600)
        tmp.replace(env_file)
        os.chmod(env_file, 0o600)
    except Exception as e:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        return ("err", f"couldn't update {what}: {e}")
    return ("ok", None)


def _write_agent_env_secret(agent_id: str, key: str, value: str) -> tuple[str, Optional[str]]:
    """Persist a secret into one agent's own env file (agents/<id>.env). This file
    is read only by the quote-aware Python bridge loader and, for the Hermes hosts,
    by `set -a; source` — both handle single-quoting — so values with spaces or
    symbols are stored quoted (quote=True) rather than rejected."""
    return _upsert_env_file_secret(_agent_env_file(agent_id), key, value, quote=True)


def _strip_env_file_secret(
    env_file: Path, key: str, what: str = "agent env"
) -> tuple[str, Optional[str]]:
    key = (key or "").strip().upper()
    if not SECRET_KEY_PATTERN.match(key):
        return ("err", "invalid key")
    if not env_file.is_file():
        return ("not_found", None)
    try:
        existing = env_file.read_text().splitlines()
    except Exception as e:
        return ("err", f"couldn't read {what}: {e}")

    prefix_re = re.compile(rf"^\s*(?:export\s+)?{re.escape(key)}\s*=")
    out = [line for line in existing if not prefix_re.match(line)]
    if len(out) == len(existing):
        return ("not_found", None)

    tmp = env_file.with_suffix(".tmp")
    try:
        tmp.write_text("\n".join(out).rstrip() + ("\n" if out else ""))
        os.chmod(tmp, 0o600)
        tmp.replace(env_file)
        os.chmod(env_file, 0o600)
    except Exception as e:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        return ("err", f"couldn't update {what}: {e}")
    return ("ok", None)


def _delete_agent_env_secret(agent_id: str, key: str) -> tuple[str, Optional[str]]:
    return _strip_env_file_secret(_agent_env_file(agent_id), key)


def _snapshot_secret_file(path: Path) -> tuple[bool, bytes, int]:
    """Capture one env file so a multi-file container mutation can roll back."""
    if not path.exists():
        return (False, b"", 0o600)
    return (True, path.read_bytes(), stat.S_IMODE(path.stat().st_mode))


def _restore_secret_file(path: Path, snapshot: tuple[bool, bytes, int]) -> Optional[str]:
    """Best-effort atomic restore for a snapshot made by _snapshot_secret_file."""
    existed, content, mode = snapshot
    tmp = path.with_name(f".{path.name}.rollback.tmp")
    try:
        if existed:
            path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
            tmp.write_bytes(content)
            os.chmod(tmp, mode or 0o600)
            tmp.replace(path)
            os.chmod(path, mode or 0o600)
        elif path.exists():
            path.unlink()
    except Exception as exc:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        return str(exc)
    return None


def _restore_secret_files(
    snapshots: list[tuple[Path, tuple[bool, bytes, int]]],
) -> Optional[str]:
    errors = [
        f"{path.name}: {err}"
        for path, snapshot in snapshots
        if (err := _restore_secret_file(path, snapshot))
    ]
    return "; ".join(errors) or None


async def _panel_set_secret(agent_id: str, key: str, value: str) -> tuple[str, Optional[str]]:
    if _panel_secret_backend(agent_id) == "agent_zero":
        return await _save_secret_to_agent(AGENTS_BY_ID[agent_id], key, value)
    cenv = _container_env_file(agent_id)
    if cenv is not None:
        if _CONTAINER_RESERVED_KEY_RE.match((key or "").strip().upper()):
            return ("err", "that key name is reserved for the container's own runtime config")
        # container.env is consumed by Docker (env_file), which does NOT do bash
        # single-quote unescaping — so container agents stay on the shell-neutral
        # safe set. Fail fast and clearly rather than quoting agents/<id>.env and
        # then erroring on the container.env write (a confusing half-save).
        if not SHARED_ENV_SAFE_VALUE_PATTERN.match((value or "").strip()):
            return ("err", "this agent runs in a container that can't store spaces or "
                           "symbols yet — use an app password (symbol-free) for it")
    snapshots: list[tuple[Path, tuple[bool, bytes, int]]] = []
    if cenv is not None:
        try:
            snapshots = [
                (_agent_env_file(agent_id), _snapshot_secret_file(_agent_env_file(agent_id))),
                (cenv, _snapshot_secret_file(cenv)),
            ]
        except Exception as exc:
            return ("err", f"couldn't prepare transactional secret update: {exc}")
    status, err = _write_agent_env_secret(agent_id, key, value)
    if status != "ok":
        rollback_err = _restore_secret_files(snapshots) if snapshots else None
        if rollback_err:
            err = f"{err or 'agent env update failed'}; rollback failed: {rollback_err}"
        return (status, err)
    if cenv is None:
        return (status, err)
    # Container agents execute tools inside Docker, which reads the bind-mounted
    # container.env (/opt/data/.env) — not agents/<id>.env. Land the value in
    # both so the host bridge and the container runtime agree.
    c_status, c_err = _upsert_env_file_secret(cenv, key, value, what="container env")
    if c_status != "ok":
        rollback_err = _restore_secret_files(snapshots)
        if rollback_err:
            c_err = f"{c_err or 'container env update failed'}; rollback failed: {rollback_err}"
        return ("err", c_err)
    return ("ok", None)


async def _panel_delete_secret(agent_id: str, key: str) -> tuple[str, Optional[str]]:
    if _panel_secret_backend(agent_id) == "agent_zero":
        return await _delete_secret_from_agent(AGENTS_BY_ID[agent_id], key)
    cenv = _container_env_file(agent_id)
    if cenv is not None and _CONTAINER_RESERVED_KEY_RE.match((key or "").strip().upper()):
        return ("err", "that key name is reserved for the container's own runtime config")
    snapshots: list[tuple[Path, tuple[bool, bytes, int]]] = []
    if cenv is not None:
        try:
            snapshots = [
                (_agent_env_file(agent_id), _snapshot_secret_file(_agent_env_file(agent_id))),
                (cenv, _snapshot_secret_file(cenv)),
            ]
        except Exception as exc:
            return ("err", f"couldn't prepare transactional secret deletion: {exc}")
    status, err = _delete_agent_env_secret(agent_id, key)
    if status == "err":
        rollback_err = _restore_secret_files(snapshots) if snapshots else None
        if rollback_err:
            err = f"{err or 'agent env deletion failed'}; rollback failed: {rollback_err}"
        return ("err", err)
    if cenv is None:
        return (status, err)
    c_status, c_err = _strip_env_file_secret(cenv, key, what="container env")
    if "err" in (status, c_status):
        rollback_err = _restore_secret_files(snapshots)
        combined = err or c_err or "container env deletion failed"
        if rollback_err:
            combined = f"{combined}; rollback failed: {rollback_err}"
        return ("err", combined)
    if "ok" in (status, c_status):
        return ("ok", None)
    return ("not_found", None)


def _record_secret_grant(owner_user_id: int, key: str, agent_id: str, backend: str) -> None:
    now = int(time.time() * 1000)
    with _db() as conn:
        columns = {
            row["name"]
            for row in conn.execute("PRAGMA table_info(agent_secrets)").fetchall()
        }
        if "folder" in columns:
            existing = conn.execute(
                "SELECT folder FROM agent_secrets WHERE owner_user_id=? AND key=? "
                "AND folder<>'' LIMIT 1",
                (int(owner_user_id), key),
            ).fetchone()
            folder = str(existing["folder"] or "") if existing else ""
            conn.execute(
                """
                INSERT INTO agent_secrets(
                    owner_user_id, key, agent_id, backend, folder, created_ts, updated_ts
                ) VALUES (?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(owner_user_id, key, agent_id)
                DO UPDATE SET backend=excluded.backend, updated_ts=excluded.updated_ts
                """,
                (int(owner_user_id), key, agent_id, backend, folder, now, now),
            )
        else:
            # Compatibility with deliberately old/rollback schemas used by the
            # migration and tenant-hardening tests.
            conn.execute(
                """
                INSERT INTO agent_secrets(
                    owner_user_id, key, agent_id, backend, created_ts, updated_ts
                ) VALUES (?, ?, ?, ?, ?, ?)
                ON CONFLICT(owner_user_id, key, agent_id)
                DO UPDATE SET backend=excluded.backend, updated_ts=excluded.updated_ts
                """,
                (int(owner_user_id), key, agent_id, backend, now, now),
            )


def _remove_secret_grant(owner_user_id: int, key: str, agent_id: str) -> None:
    with _db() as conn:
        conn.execute(
            "DELETE FROM agent_secrets WHERE owner_user_id=? AND key=? AND agent_id=?",
            (int(owner_user_id), key, agent_id),
        )


def _secret_grant_exists(owner_user_id: int, key: str, agent_id: str) -> bool:
    with _db() as conn:
        return conn.execute(
            "SELECT 1 FROM agent_secrets "
            "WHERE owner_user_id=? AND key=? AND agent_id=? LIMIT 1",
            (int(owner_user_id), key, agent_id),
        ).fetchone() is not None


async def _set_secret_with_grant(
    owner_user_id: int, key: str, agent_id: str, value: str,
) -> tuple[str, Optional[str]]:
    """Reserve metadata before activating a physical secret.

    This is called under _SECRET_MUTATION_LOCK. If SQLite cannot record the
    owner, no vault/file mutation occurs. A failed physical write removes only a
    newly-created reservation; an existing grant remains paired with its prior
    value (container files are rolled back by _panel_set_secret).
    """
    existed = _secret_grant_exists(owner_user_id, key, agent_id)
    backend = _panel_secret_backend(agent_id)
    try:
        _record_secret_grant(owner_user_id, key, agent_id, backend)
    except Exception as exc:
        logger.exception(
            "secret metadata reservation failed owner=%s key=%s agent=%s",
            owner_user_id,
            key,
            agent_id,
        )
        return ("err", f"couldn't reserve secret metadata: {exc}")

    status, err = await _panel_set_secret(agent_id, key, value)
    if status != "ok" and not existed:
        try:
            _remove_secret_grant(owner_user_id, key, agent_id)
        except Exception as rollback_exc:
            logger.exception(
                "secret metadata rollback failed owner=%s key=%s agent=%s",
                owner_user_id,
                key,
                agent_id,
            )
            err = (
                f"{err or 'physical secret write failed'}; "
                f"metadata rollback failed: {rollback_exc}"
            )
    return status, err


def _record_secret_restart_block(owner_user_id: int, agent_id: str) -> None:
    with _db() as conn:
        conn.execute(
            "INSERT INTO secret_restart_blocks(agent_id, owner_user_id, created_ts) "
            "VALUES (?, ?, ?) "
            "ON CONFLICT(agent_id, owner_user_id) "
            "DO UPDATE SET created_ts=excluded.created_ts",
            (agent_id, int(owner_user_id), int(time.time() * 1000)),
        )


def _clear_secret_restart_blocks(agent_id: str) -> None:
    with _db() as conn:
        conn.execute(
            "DELETE FROM secret_restart_blocks WHERE agent_id=?", (agent_id,),
        )


def _secret_restart_block_agents(owner_user_id: int) -> set[str]:
    with _db() as conn:
        return {
            row["agent_id"]
            for row in conn.execute(
                "SELECT agent_id FROM secret_restart_blocks WHERE owner_user_id=?",
                (int(owner_user_id),),
            ).fetchall()
        }


def _secret_backend_requires_restart(agent_id: str, backend: str) -> bool:
    return (
        backend != "agent_zero"
        and agent_id in AGENTS_BY_ID
        and (agent_id in MANAGED_BRIDGES or _container_env_file(agent_id) is not None)
    )


def _list_secrets_for_owner(owner_user_id: int) -> list[dict]:
    """One entry per key with the agents that hold it. Never includes values."""
    with _db() as conn:
        try:
            rows = conn.execute(
                "SELECT key, agent_id, backend, folder, updated_ts FROM agent_secrets "
                "WHERE owner_user_id=? ORDER BY key, agent_id",
                (int(owner_user_id),),
            ).fetchall()
        except sqlite3.OperationalError as exc:
            # A rollback/legacy database may be opened before _init_db has added
            # the display-only folder column. Read it safely as Unfiled rather
            # than letting secrets/revoke status fail during that upgrade window.
            if "no such column: folder" not in str(exc).lower():
                raise
            rows = conn.execute(
                "SELECT key, agent_id, backend, '' AS folder, updated_ts "
                "FROM agent_secrets WHERE owner_user_id=? ORDER BY key, agent_id",
                (int(owner_user_id),),
            ).fetchall()
    by_key: dict[str, dict] = {}
    for r in rows:
        entry = by_key.setdefault(
            r["key"],
            {"key": r["key"], "folder": r["folder"] or "", "agents": [],
             "orphaned_agents": [], "updated_ts": 0},
        )
        if not entry["folder"] and r["folder"]:
            entry["folder"] = r["folder"]
        if r["agent_id"] in AGENTS_BY_ID:
            entry["agents"].append({
                "id": r["agent_id"],
                "name": AGENTS_BY_ID[r["agent_id"]]["name"],
                "backend": r["backend"],
            })
        else:
            # A grant left behind by a retired agent. Silently dropping the row
            # hid the whole key once its last live holder was retired: it stayed
            # in the table and in search results nowhere, so it could not be
            # seen, renamed, re-filed or deleted. Report it instead, so the
            # owner can clear it out.
            entry["orphaned_agents"].append({
                "id": r["agent_id"],
                "name": r["agent_id"],
                "backend": r["backend"],
            })
        entry["updated_ts"] = max(entry["updated_ts"], int(r["updated_ts"] or 0))
    return sorted(by_key.values(), key=lambda e: e["key"])


def _orphaned_secret_agents(owner_user_id: int, key: str) -> list[str]:
    """Retired agent ids still recorded as holding this key. Nothing can be
    written to them — they exist only to be cleaned up."""
    with _db() as conn:
        rows = conn.execute(
            "SELECT DISTINCT agent_id FROM agent_secrets "
            "WHERE owner_user_id=? AND key=?",
            (int(owner_user_id), key),
        ).fetchall()
    return sorted(r["agent_id"] for r in rows if r["agent_id"] not in AGENTS_BY_ID)


def _purge_orphaned_secret_grants(owner_user_id: int, key: str) -> list[str]:
    """Delete metadata rows for retired holders. There is no physical store to
    revoke from — the agent and its vault are already gone — so this only clears
    the row that was making the key unmanageable."""
    orphans = _orphaned_secret_agents(owner_user_id, key)
    if orphans:
        with _db() as conn:
            conn.executemany(
                "DELETE FROM agent_secrets WHERE owner_user_id=? AND key=? AND agent_id=?",
                [(int(owner_user_id), key, aid) for aid in orphans],
            )
    return orphans


# --- secret folders: naming, chat scoping, and deterministic auto-filing ------
# A folder is a display-only label on a key NAME. Values never move because a
# folder changed, and this whole section can therefore run without touching a
# single vault or env file.

SECRET_FOLDER_MAX = 48


def _clean_secret_folder(raw: object) -> tuple[str, Optional[str]]:
    """Normalize a folder name. Returns (folder, error); '' means Unfiled."""
    if raw is None:
        return "", None
    if not isinstance(raw, str):
        return "", "folder must be text"
    folder = re.sub(r"\s+", " ", raw).strip()
    if len(folder) > SECRET_FOLDER_MAX:
        return "", f"folder must be {SECRET_FOLDER_MAX} characters or fewer"
    if any(ord(ch) < 32 or ord(ch) == 127 for ch in folder):
        return "", "folder contains unsupported characters"
    return folder, None


def _secret_folders_for_owner(owner_user_id: int) -> list[str]:
    """Every folder name this owner has in use, sorted for display."""
    names = {
        (entry.get("folder") or "").strip()
        for entry in _list_secrets_for_owner(int(owner_user_id))
    }
    return sorted((n for n in names if n), key=lambda n: n.casefold())


def _secret_key_family(key: str) -> str:
    """The prefix that identifies sibling keys: AC_WORDPRESS_URL and
    AC_WORDPRESS_APP_PASSWORD both resolve to AC_WORDPRESS."""
    parts = [p for p in str(key).split("_") if p]
    if len(parts) >= 2:
        return "_".join(parts[:2])
    return str(key)


# Friendly folder names for families the app can recognise on sight. Used only
# when a key has no sibling already filed somewhere — an owner's own filing
# always wins over this table.
_SECRET_VENDOR_FOLDERS: dict[str, str] = {
    "GOOGLE_ADS": "Google Ads",
    "GOOGLE_ANALYTICS": "Google Analytics",
    "GA4": "Google Analytics",
    "GOOGLE_GSC": "Google Search Console",
    "GSC": "Google Search Console",
    "GOOGLE_GA": "Google Analytics",
    "SEARCH_CONSOLE": "Google Search Console",
    "GMAIL": "Gmail",
    "GOOGLE_WORKSPACE": "Google Workspace",
    "WORDPRESS": "WordPress",
    "SERVICETITAN": "ServiceTitan",
    "CONSTANTCONTACT": "Constant Contact",
    "CONSTANTCONTACTS": "Constant Contact",
    "BROKERAGE": "Brokerage",
    "KRAKEN": "Kraken",
    "OANDA": "OANDA",
    "STRIPE": "Stripe",
    "QUICKBOOKS": "QuickBooks",
    "CANVA": "Canva",
    "RETELL": "Retell",
    "TWILIO": "Twilio",
    "SLACK": "Slack",
    "TELEGRAM": "Telegram",
    "OPENAI": "AI providers",
    "ANTHROPIC": "AI providers",
    "GEMINI": "AI providers",
    "DEEPSEEK": "AI providers",
    "MINIMAX": "AI providers",
    "TAVILY": "AI providers",
    "HUBSPOT": "HubSpot",
    "MAILCHIMP": "Mailchimp",
    "SENDGRID": "SendGrid",
    "SHOPIFY": "Shopify",
    "AIRTABLE": "Airtable",
    "NOTION": "Notion",
    "GITHUB": "GitHub",
    "AWS": "AWS",
    "CLOUDFLARE": "Cloudflare",
}


def _secret_family_label(family: str) -> str:
    """Human folder name for a family prefix, or '' when nothing is known."""
    fam = str(family).upper()
    if fam in _SECRET_VENDOR_FOLDERS:
        return _SECRET_VENDOR_FOLDERS[fam]
    # AC_WORDPRESS → WORDPRESS is a better label than the tenant prefix alone.
    head, _, tail = fam.partition("_")
    for candidate in (tail, head):
        if candidate and candidate in _SECRET_VENDOR_FOLDERS:
            return _SECRET_VENDOR_FOLDERS[candidate]
    return ""


def _suggest_secret_folders(owner_user_id: int) -> list[dict]:
    """Propose a folder for every UNFILED key, deterministically.

    Priority, highest first:
      1. a sibling key (same family) the owner has ALREADY filed — their own
         scheme wins, so a new GOOGLE_ADS_* key lands where the rest already are;
      2. a recognised vendor family (see _SECRET_VENDOR_FOLDERS);
      3. two or more unfiled siblings, which get the vendor label or the family.
    A lone key nobody can place is left alone rather than guessed at. Nothing is
    written — the caller previews this and applies what it wants.
    """
    entries = _list_secrets_for_owner(int(owner_user_id))
    filed_family_folder: dict[str, str] = {}
    for entry in entries:
        folder = (entry.get("folder") or "").strip()
        if not folder:
            continue
        # First filed sibling wins; entries are key-sorted so this is stable.
        filed_family_folder.setdefault(_secret_key_family(entry["key"]), folder)

    unfiled = [e for e in entries if not (e.get("folder") or "").strip()]
    family_counts: dict[str, int] = {}
    for entry in unfiled:
        fam = _secret_key_family(entry["key"])
        family_counts[fam] = family_counts.get(fam, 0) + 1

    out: list[dict] = []
    for entry in unfiled:
        key = entry["key"]
        fam = _secret_key_family(key)
        folder = ""
        reason = ""
        if fam in filed_family_folder:
            folder = filed_family_folder[fam]
            reason = "matches secrets you already filed there"
        else:
            label = _secret_family_label(fam)
            if label:
                folder = label
                reason = "recognised service"
            elif family_counts.get(fam, 0) >= 2:
                folder = fam.replace("_", " ").title()
                reason = "shares a name with its siblings"
        if not folder:
            continue
        out.append({
            "key": key,
            "folder": folder,
            "family": fam,
            "reason": reason,
            "is_new_folder": folder not in set(filed_family_folder.values()),
        })
    return sorted(out, key=lambda item: (item["folder"].casefold(), item["key"]))


def _chat_secret_folders(cid: int) -> list[str]:
    """Folder names this chat is scoped to. Never raises — a chat with no pins
    (the default) simply reports none and behaves exactly as it always has."""
    try:
        with _db() as conn:
            rows = conn.execute(
                "SELECT folder FROM chat_secret_folders WHERE chat_id=? "
                "ORDER BY folder",
                (int(cid),),
            ).fetchall()
        return [r["folder"] for r in rows if (r["folder"] or "").strip()]
    except Exception:
        logger.exception("chat secret folders read failed for chat %s", cid)
        return []


def _set_chat_secret_folders(cid: int, folders: list[str]) -> list[str]:
    """Replace this chat's folder pins. Returns what was stored."""
    cleaned: list[str] = []
    for raw in folders or []:
        folder, err = _clean_secret_folder(raw)
        if err or not folder or folder in cleaned:
            continue
        cleaned.append(folder)
    now = int(time.time() * 1000)
    with _db() as conn:
        conn.execute("DELETE FROM chat_secret_folders WHERE chat_id=?", (int(cid),))
        for folder in cleaned:
            conn.execute(
                "INSERT OR REPLACE INTO chat_secret_folders(chat_id, folder, created_ts) "
                "VALUES (?, ?, ?)",
                (int(cid), folder, now),
            )
    return cleaned


def _chat_folder_secret_view(cid: int, owner_user_id: int) -> dict:
    """What the chat's pinned folders contain and who in this chat is missing a
    key from them. This is the "why can't the agent see it" answer, computed
    without reading a single secret value."""
    pinned = _chat_secret_folders(cid)
    entries = _list_secrets_for_owner(int(owner_user_id))
    by_folder: dict[str, list[dict]] = {}
    for entry in entries:
        folder = (entry.get("folder") or "").strip()
        if folder in pinned:
            by_folder.setdefault(folder, []).append(entry)

    chat_agent_ids = [
        aid for aid in _get_chat_targets(cid) if aid in AGENTS_BY_ID
    ]
    gaps: list[dict] = []
    for folder in pinned:
        for entry in by_folder.get(folder, []):
            holders = {a.get("id") for a in (entry.get("agents") or [])}
            missing = [aid for aid in chat_agent_ids if aid not in holders]
            if missing:
                gaps.append({
                    "key": entry["key"],
                    "folder": folder,
                    "missing_agent_ids": missing,
                    "missing_agents": [
                        AGENTS_BY_ID[aid]["name"] for aid in missing
                    ],
                })
    return {
        "folders": pinned,
        "available_folders": _secret_folders_for_owner(int(owner_user_id)),
        "keys_by_folder": {
            folder: [e["key"] for e in by_folder.get(folder, [])]
            for folder in pinned
        },
        "chat_agent_ids": chat_agent_ids,
        "gaps": gaps,
    }


def _owner_secret_agents(owner_user_id: int, key: str) -> set:
    return {
        a["id"]
        for s in _list_secrets_for_owner(owner_user_id)
        if s["key"] == key
        for a in s["agents"]
    }


def _secret_slot_has_other_owner(owner_user_id: int, key: str, agent_id: str) -> bool:
    """Whether another tenant already owns this install-global physical slot."""
    with _db() as conn:
        return conn.execute(
            "SELECT 1 FROM agent_secrets "
            "WHERE key=? AND agent_id=? AND owner_user_id<>? LIMIT 1",
            (key, agent_id, int(owner_user_id)),
        ).fetchone() is not None


def _secret_agent_is_shared(owner_user_id: int, agent_id: str) -> bool:
    """Physical secret runtimes must be dedicated to one active user."""
    with _db() as conn:
        return conn.execute(
            "SELECT 1 FROM user_agents ua "
            "JOIN users u ON u.id=ua.user_id "
            "WHERE ua.agent_id=? AND ua.user_id<>? AND u.is_active=1 "
            "AND u.role<>'admin' LIMIT 1",
            (agent_id, int(owner_user_id)),
        ).fetchone() is not None


def _secret_slot_has_any_grant(key: str, agent_id: str) -> bool:
    with _db() as conn:
        return conn.execute(
            "SELECT 1 FROM agent_secrets WHERE key=? AND agent_id=? LIMIT 1",
            (key, agent_id),
        ).fetchone() is not None


def _recover_secret_value(owner_user_id: int, key: str) -> Optional[str]:
    """Read an already-granted secret's stored value server-side so a NEW agent
    can be granted the SAME secret without the user re-typing it. Values live only
    in each agent's own agents/<id>.env (container agents dual-write there too), so
    we copy from one holder to another — the value is never returned to any client,
    which keeps the panel's "no read-back to a caller" invariant intact. Agent Zero
    vaults have no read-back path, so a secret held ONLY by such agents can't be
    recovered (returns None → the UI falls back to Edit / re-enter the value)."""
    prefix_re = re.compile(rf"^\s*(?:export\s+)?{re.escape(key)}\s*=(.*)$")
    for aid in _owner_secret_agents(owner_user_id, key):
        if aid not in AGENTS_BY_ID or _panel_secret_backend(aid) == "agent_zero":
            continue
        env_file = _agent_env_file(aid)
        if not env_file.is_file():
            continue
        try:
            for line in env_file.read_text().splitlines():
                m = prefix_re.match(line)
                if m:
                    val = _parse_env_value(m.group(1))
                    if val:
                        return val
        except Exception:
            continue
    return None


_SECRET_MUTATION_LOCK = asyncio.Lock()


async def _revoke_secret_grants_unlocked(
    owner_user_id: int, key: str, agent_ids: list[str],
) -> tuple[list[str], dict[str, str]]:
    revoked: list[str] = []
    failures: dict[str, str] = {}
    requested = list(dict.fromkeys(agent_ids))
    with _db() as conn:
        owner_grants = {
            row["agent_id"]: str(row["backend"] or "")
            for row in conn.execute(
                "SELECT agent_id, backend FROM agent_secrets "
                "WHERE owner_user_id=? AND key=?",
                (int(owner_user_id), key),
            ).fetchall()
        }

    # Legacy shared.env is one global KEY, not one slot per agent. A partial
    # revoke cannot remove one agent's physical access. Delete it only when this
    # request covers every recorded shared reference; otherwise retain metadata
    # and report the operation as impossible instead of claiming success.
    shared_targets = [
        aid for aid in requested if owner_grants.get(aid) == "shared_env"
    ]
    if shared_targets:
        with _db() as conn:
            all_shared = {
                (int(row["owner_user_id"]), row["agent_id"])
                for row in conn.execute(
                    "SELECT owner_user_id, agent_id FROM agent_secrets "
                    "WHERE key=? AND backend='shared_env'",
                    (key,),
                ).fetchall()
            }
        requested_refs = {(int(owner_user_id), aid) for aid in shared_targets}
        if all_shared - requested_refs:
            for aid in shared_targets:
                failures[aid] = (
                    "legacy shared-env secret cannot be revoked from one agent "
                    "while another shared reference remains"
                )
        else:
            status, err = _delete_shared_env_secret(key)
            if status in ("ok", "not_found"):
                try:
                    for blocked_aid in MANAGED_BRIDGES:
                        _record_secret_restart_block(owner_user_id, blocked_aid)
                except Exception as block_exc:
                    logger.exception(
                        "failed to reserve shared-secret restart block owner=%s key=%s",
                        owner_user_id,
                        key,
                    )
                    for aid in shared_targets:
                        failures[aid] = f"couldn't record required restart: {block_exc}"
                else:
                    for aid in shared_targets:
                        _remove_secret_grant(owner_user_id, key, aid)
                        revoked.append(aid)
            else:
                for aid in shared_targets:
                    failures[aid] = err or "physical secret deletion failed"

    for aid in requested:
        if aid in shared_targets:
            continue
        with _db() as conn:
            grant = conn.execute(
                "SELECT backend FROM agent_secrets "
                "WHERE owner_user_id=? AND key=? AND agent_id=?",
                (int(owner_user_id), key, aid),
            ).fetchone()
        if not grant:
            continue
        backend = str(grant["backend"] or "")

        # Panel grants reference one (agent, KEY) physical slot. Removing this
        # owner's metadata while another owner remains also blocks this user from
        # that agent at the central authorization boundary.
        with _db() as conn:
            remaining = conn.execute(
                "SELECT 1 FROM agent_secrets WHERE key=? AND agent_id=? "
                "AND owner_user_id<>? LIMIT 1",
                (key, aid, int(owner_user_id)),
            ).fetchone()
        if remaining:
            _remove_secret_grant(owner_user_id, key, aid)
            revoked.append(aid)
            continue

        # This is the final metadata reference: delete the physical value FIRST.
        # If that fails, retain the grant so the UI and audit trail do not claim a
        # credential disappeared while it is still active in a vault or env file.
        if aid not in AGENTS_BY_ID:
            status, err = ("not_found", None)
        elif backend == "agent_zero":
            status, err = await _delete_secret_from_agent(AGENTS_BY_ID[aid], key)
        else:
            status, err = await _panel_delete_secret(aid, key)
        if status in ("ok", "not_found"):
            try:
                if _secret_backend_requires_restart(aid, backend):
                    _record_secret_restart_block(owner_user_id, aid)
            except Exception as block_exc:
                logger.exception(
                    "failed to reserve secret restart block owner=%s key=%s agent=%s",
                    owner_user_id,
                    key,
                    aid,
                )
                failures[aid] = f"couldn't record required restart: {block_exc}"
                continue
            _remove_secret_grant(owner_user_id, key, aid)
            revoked.append(aid)
        else:
            failures[aid] = err or "physical secret deletion failed"
    return revoked, failures


async def _revoke_secret_grants(
    owner_user_id: int, key: str, agent_ids: list[str],
) -> tuple[list[str], dict[str, str]]:
    async with _SECRET_MUTATION_LOCK:
        return await _revoke_secret_grants_unlocked(owner_user_id, key, agent_ids)


def _secret_conflict_response(conflicted: list[str]) -> JSONResponse:
    return JSONResponse(
        {
            "error": "one or more agent secret slots are already managed by another user",
            "agents_conflicted": conflicted,
        },
        status_code=409,
    )


def _secret_shared_agent_response(shared: list[str]) -> JSONResponse:
    return JSONResponse(
        {
            "error": (
                "secret-bearing agents must be assigned to only one active user; "
                "dedicate the listed agents before provisioning credentials"
            ),
            "agents_shared": shared,
        },
        status_code=409,
    )


def _secret_restart_entries(
    agent_ids: list[str], owner_user_id: Optional[int] = None,
) -> list[dict]:
    pending = list(agent_ids)
    if owner_user_id is not None:
        pending.extend(sorted(_secret_restart_block_agents(owner_user_id)))
    return [
        {
            "id": aid,
            "name": AGENTS_BY_ID[aid]["name"],
            "container": (
                CONTAINER_NAMES.get(aid)
                if _container_env_file(aid) is not None
                else None
            ),
        }
        for aid in dict.fromkeys(pending)
        if aid in AGENTS_BY_ID
        and _panel_secret_backend(aid) != "agent_zero"
        and (aid in MANAGED_BRIDGES or _container_env_file(aid) is not None)
    ]


def _secret_revoke_response(
    *, key: str, owner_user_id: int, revoked: list[str], failures: dict[str, str],
) -> dict:
    status = "ok" if not failures else ("partial" if revoked else "error")
    restart_needed = _secret_restart_entries(revoked, owner_user_id)
    payload = {
        "status": status,
        "key": key,
        "owner_user_id": owner_user_id,
        "revoked": revoked,
        "agents_error": [
            {"id": aid, "error": error} for aid, error in failures.items()
        ],
        "restart_needed": restart_needed,
        "container_restart_needed": [
            item for item in restart_needed if item.get("container")
        ],
        "secrets": _list_secrets_for_owner(owner_user_id),
    }
    if failures:
        payload["error"] = "one or more physical secret deletions failed"
    return payload


async def _sync_env_secret_to_agents(
    keys: list[str],
    target_ids: list[str],
) -> list[dict]:
    """Copy selected orchestrator env secrets into selected Agent Zero vaults.

    Values are read only from this backend process environment and are never
    returned, stored in chat history, or written to audit metadata.
    """
    cleaned_keys: list[str] = []
    for key in keys:
        upper = (key or "").strip().upper()
        if upper and SECRET_KEY_PATTERN.match(upper) and upper not in cleaned_keys:
            cleaned_keys.append(upper)

    cleaned_targets = [tid for tid in target_ids if tid in AGENTS_BY_ID]
    results: list[dict] = []
    for key in cleaned_keys:
        value = os.environ.get(key)
        if value is None:
            results.append({"key": key, "status": "missing_env", "results": {}})
            continue

        # Operational env sync has no tenant principal. Never let it replace a
        # slot already managed through the owner-scoped Secrets panel.
        async with _SECRET_MUTATION_LOCK:
            per_target: dict[str, tuple[str, Optional[str]]] = {}
            writable: list[str] = []
            for tid in cleaned_targets:
                if _secret_slot_has_any_grant(key, tid):
                    per_target[tid] = ("err", "secret slot is managed by a user")
                else:
                    writable.append(tid)
            coros = [
                _save_secret_to_agent(AGENTS_BY_ID[tid], key, value)
                for tid in writable
            ]
            gathered = await asyncio.gather(*coros) if coros else []
            per_target.update({tid: result for tid, result in zip(writable, gathered)})
        overall = "ok" if per_target and all(r[0] == "ok" for r in per_target.values()) else "partial"
        results.append({"key": key, "status": overall, "results": per_target})
    return results


async def _attachment_prune_on_startup():
    """Prune aged attachments once at boot, then once a day. Runs the blocking
    sqlite/file work in a worker thread so it never stalls the event loop."""
    if ATTACHMENT_RETENTION_DAYS <= 0:
        logger.info("attachment auto-prune disabled (retention <= 0)")
        return

    async def _loop():
        while True:
            try:
                await asyncio.to_thread(_prune_old_attachments)
            except Exception:
                logger.exception("attachment prune loop error")
            await asyncio.sleep(24 * 3600)

    asyncio.create_task(_loop())


async def _reconcile_interrupted_turns_on_startup():
    """A turn_runs row left 'interrupted' (flagged by _init_db's boot reconcile)
    means a tracked turn's process died mid-run, so its in-memory hold/resume state
    is gone and the chat would otherwise be stranded with no resume card — exactly
    the silent-strand failure this guards against. For each affected chat, post ONE
    durable, resumable hold (newest run first). Additional same-chat plans remain
    ``interrupted`` and are surfaced one-at-a-time after each card is resolved;
    none are silently settled. Also rehydrate PENDING_HOLDS from any still-
    unresolved cards so a Resume right after boot works instantly. Best-effort:
    never blocks boot."""
    try:
        now = int(time.time() * 1000)
        cutoff = now - 24 * 3600 * 1000
        with _db() as conn:
            # Bound the table: settled runs are only useful for recovery inside the
            # window above, so drop ones that finished over a week ago.
            conn.execute(
                "DELETE FROM turn_runs WHERE status != 'running' "
                "AND COALESCE(finished_ts, created_ts) < ?", (now - 7 * 24 * 3600 * 1000,),
            )
            rows = conn.execute(
                "SELECT id, chat_id, unattended, resume_gen FROM turn_runs "
                "WHERE status='interrupted' AND created_ts >= ? "
                "ORDER BY chat_id, id DESC", (cutoff,)
            ).fetchall()
            # Interrupted runs older than the window are too stale to resume usefully
            # — settle them silently so they never resurface.
            conn.execute(
                "UPDATE turn_runs SET status='stale', finished_ts=COALESCE(finished_ts,?) "
                "WHERE status='interrupted' AND created_ts < ?", (now, cutoff),
            )
        seen: set[int] = set()
        recovered: list[int] = []   # settled -> 'held' (parked a human resume card)
        resumed: list[int] = []     # settled -> 'resumed' (auto-re-driven)
        for row in rows:
            cid, run_id = row["chat_id"], row["id"]
            if cid not in seen:
                seen.add(cid)
                try:
                    unattended = bool(row["unattended"])
                    gen = int(row["resume_gen"] or 0)
                    # An UNATTENDED automation has nobody to click Resume, so re-drive
                    # it instead of parking a hold — UNLESS we've already auto-resumed
                    # it too many times (a stage crashing the process would boot-loop),
                    # in which case fall through to a human hold. Skip if there's
                    # nothing left to resume.
                    if (AUTO_RESUME_UNATTENDED and unattended and gen < AUTO_RESUME_MAX_GEN
                            and _resume_pending_for_run(run_id)):
                        # Supersede any stale hold card a pre-fix boot may have parked
                        # so the chat doesn't show a dead "Resume" button alongside the
                        # auto-resume.
                        stale_card = _pending_hold_from_thread(cid)
                        if stale_card and stale_card.get("hold_id"):
                            await _resolve_hold_card(cid, stale_card["hold_id"], "retry")
                        # Carry _UNATTENDED into the resume task (the contextvar is gone
                        # after a restart) so the re-driven pipeline keeps the
                        # never-block / orchestrator-standin behavior.
                        _tok = _UNATTENDED.set(True)
                        try:
                            asyncio.create_task(
                                _auto_resume_interrupted_run(cid, run_id, gen)
                            )
                        finally:
                            _UNATTENDED.reset(_tok)
                        resumed.append(run_id)
                        continue
                    existing = _pending_hold_from_thread(cid)
                    if existing:
                        # A durable card is already on the thread — just make it live.
                        PENDING_HOLDS.setdefault(cid, existing)
                        if int(existing.get("run_id") or 0) == int(run_id):
                            recovered.append(run_id)
                    else:
                        if await _raise_interrupt_hold(cid, run_id, push=False):
                            recovered.append(run_id)
                except Exception:
                    logger.exception("interrupt reconcile failed for chat %s", cid)
        if recovered:
            with _db() as conn:
                conn.executemany(
                    "UPDATE turn_runs SET status='held', finished_ts=COALESCE(finished_ts,?) "
                    "WHERE id=?", [(now, rid) for rid in recovered],
                )
        if resumed:
            with _db() as conn:
                conn.executemany(
                    "UPDATE turn_runs SET status='resumed', finished_ts=COALESCE(finished_ts,?) "
                    "WHERE id=?", [(now, rid) for rid in resumed],
                )
        if recovered or resumed:
            logger.info(
                "reconciled interrupted turn run(s): %d auto-resumed, %d held, "
                "across %d chat(s)", len(resumed), len(recovered), len(seen),
            )
        # A CLEAN restart empties PENDING_HOLDS and PENDING_INPUT_CARDS while
        # unresolved hold/question/input cards persist on threads — which strands
        # Resume-until-click and hides the thread list's needs-you badge. Rehydrate
        # across all non-archived chats (not just interrupted-run ones), one thread
        # read per chat, boot-only, best-effort.
        rehydrated = 0
        rehydrated_inputs = 0
        for cid_str, ch in list(CHAT_INDEX.get("chats", {}).items()):
            try:
                if ch.get("archived"):
                    continue
                hcid = int(cid_str)
                need_hold = hcid not in PENDING_HOLDS and hcid not in seen
                need_input = hcid not in PENDING_INPUT_CARDS
                if not need_hold and not need_input:
                    continue
                thread = _load_thread(hcid)
                if need_hold:
                    existing = _pending_hold_from_thread(hcid, thread=thread)
                    if existing:
                        PENDING_HOLDS.setdefault(hcid, existing)
                        rehydrated += 1
                if need_input and _pending_input_request_from_thread(
                    hcid, thread=thread
                ):
                    PENDING_INPUT_CARDS.add(hcid)
                    rehydrated_inputs += 1
            except Exception:
                continue
        if rehydrated:
            logger.info("rehydrated %d pending hold(s) from threads at boot", rehydrated)
        if rehydrated_inputs:
            logger.info(
                "rehydrated %d pending input request(s) from threads at boot",
                rehydrated_inputs,
            )
    except Exception:
        logger.exception("interrupted-turn reconcile on startup failed")


async def _warm_capability_registry_on_startup():
    """Pre-learn agent cards a few seconds after boot so the first concierge
    route isn't blind, and a freshly-deployed box populates the orchestrator
    without a manual refresh. Delayed to let the bridges bind their ports."""
    async def _warm():
        await asyncio.sleep(4)
        try:
            await _refresh_capabilities(force=True)
        except Exception:
            logger.exception("startup capability warm failed")

    asyncio.create_task(_warm())


async def _telegram_bridge_on_startup():
    # Prefer DB-stored (UI-configured) creds over the .env bootstrap, then start.
    _tg_load_config()
    if not TELEGRAM_ENABLED:
        logger.info("telegram: bridge disabled (configure it in Settings → Telegram)")
    else:
        _tg_restart_poller()
    # Per-agent group bots have their own tokens and their own pollers — they
    # run whether or not the personal pager is configured.
    _agent_tg_load_config()
    _agent_tg_restart_pollers()


async def _audit_retention_on_startup():
    async def _loop():
        while True:
            # All off the event loop — these walk the DB and the audio dirs.
            for fn in (
                _prune_audit_events, _prune_trashed_chats,
                _prune_usage_tables, _prune_disk_caches,
            ):
                try:
                    await asyncio.to_thread(fn)
                except Exception:
                    logger.exception("retention: %s failed", getattr(fn, "__name__", fn))
            await asyncio.sleep(24 * 3600)
    asyncio.create_task(_loop())


async def _token_usage_backfill_on_startup():
    """One-time estimated backfill of usage from existing history, off the event
    loop, so the usage dashboard shows data the first time it's opened."""
    async def _run():
        await asyncio.sleep(2)
        try:
            await asyncio.to_thread(_backfill_token_usage)
        except Exception:
            logger.exception("token usage backfill startup failed")
        try:
            await asyncio.to_thread(_detach_orphan_token_usage)
        except Exception:
            logger.exception("token usage orphan detach startup failed")
        try:
            await asyncio.to_thread(_backfill_automation_run_cost)
        except Exception:
            logger.exception("automation run cost backfill startup failed")
        try:
            await asyncio.to_thread(_clamp_historical_run_durations)
        except Exception:
            logger.exception("run duration clamp startup failed")
    asyncio.create_task(_run())


async def _sync_operational_secrets_on_startup():
    if not OPERATIONAL_SECRET_AUTO_SYNC:
        return
    targets = OPERATIONAL_SECRET_TARGETS or [a["id"] for a in AGENTS]
    try:
        results = await _sync_env_secret_to_agents(OPERATIONAL_SECRET_KEYS, targets)
        logger.info(
            "operational secret auto-sync complete keys=%s targets=%s statuses=%s",
            OPERATIONAL_SECRET_KEYS,
            targets,
            [r.get("status") for r in results],
        )
        _audit_event(
            None,
            "secret.env_sync",
            actor="system",
            target=",".join(targets),
            status="ok",
            meta={
                "keys": [r.get("key") for r in results],
                "statuses": [r.get("status") for r in results],
            },
        )
    except Exception:
        logger.exception("operational secret auto-sync failed")


async def process_secrets(
    text: str, target_ids: list[str], owner_user_id: int,
) -> tuple[str, list[dict]]:
    """Save each declared secret to every target agent and return the message
    text with each literal value replaced by §§secret(KEY) — Agent Zero's
    native placeholder. The raw value never enters THREAD storage or any
    outgoing prompt."""
    matches = extract_secrets(text)
    if not matches:
        return text, []

    by_key: dict[str, dict[str, tuple[str, Optional[str]]]] = {}
    targets = list(dict.fromkeys(tid for tid in target_ids if tid in AGENTS_BY_ID))
    async with _SECRET_MUTATION_LOCK:
        for _m, key, value in matches:
            writable: list[str] = []
            for tid in targets:
                if _secret_agent_is_shared(owner_user_id, tid):
                    by_key.setdefault(key, {})[tid] = (
                        "err", "agent is shared with another active user; dedicate it first",
                    )
                elif _secret_slot_has_other_owner(owner_user_id, key, tid):
                    by_key.setdefault(key, {})[tid] = (
                        "err", "secret slot is already managed by another user",
                    )
                else:
                    writable.append(tid)
            results = await asyncio.gather(*[
                _set_secret_with_grant(owner_user_id, key, tid, value)
                for tid in writable
            ]) if writable else []
            for tid, result in zip(writable, results):
                by_key.setdefault(key, {})[tid] = result

    # Rewrite text once — replace each value span with §§secret(KEY).
    parts: list[str] = []
    cursor = 0
    seen: list[str] = []
    for m, key, _value in matches:
        parts.append(text[cursor:m.start(2)])
        parts.append(f"§§secret({key})")
        cursor = m.end(2)
        if key not in seen:
            seen.append(key)
    parts.append(text[cursor:])
    rewritten = "".join(parts)

    save_log = [{"key": k, "results": by_key.get(k, {})} for k in seen]
    return rewritten, save_log


def extract_secret_deletions(text: str) -> list[str]:
    """Return distinct KEYs the user asked to delete."""
    out: list[str] = []
    for m in SECRET_DELETE_PATTERN.finditer(text):
        key = m.group(1).upper()
        if key not in out:
            out.append(key)
    return out


async def process_secret_deletions(
    text: str, target_ids: list[str], owner_user_id: int,
) -> list[dict]:
    """For each "delete secret KEY" the user typed, remove KEY from each
    target agent's secrets store. Returns a per-key results log."""
    keys = extract_secret_deletions(text)
    if not keys:
        return []
    targets = list(dict.fromkeys(tid for tid in target_ids if tid in AGENTS_BY_ID))
    logs: list[dict] = []
    for key in keys:
        current = _owner_secret_agents(owner_user_id, key)
        requested = [tid for tid in targets if tid in current]
        revoked, failures = await _revoke_secret_grants(
            owner_user_id, key, requested,
        )
        results: dict[str, tuple[str, Optional[str]]] = {}
        for tid in targets:
            if tid in failures:
                results[tid] = ("err", failures[tid])
            elif tid in revoked:
                results[tid] = ("ok", None)
            else:
                results[tid] = ("not_found", None)
        logs.append({"key": key, "results": results})
    return logs


# A leading greeting we step over so "hey Claude, …" still reads as a direct
# address to Claude (not a group message that happens to name-drop Claude).
_ADDRESS_GREETING = re.compile(
    r"^(?:hey|hi|hello|ok|okay|yo|so|um|uh|hmm|psst)[\s,]+", re.IGNORECASE
)


def _detect_solo_address(text: str) -> Optional[str]:
    """One-shot scoping: if `text` OPENS by addressing exactly one roster agent,
    return that agent id — else None.

    Matches '@claude …', 'Claude, …', 'hey codex:' — i.e. a single name at the
    very start, in @-form (followed by a space) or bare-name form (followed by
    ',', ':' or a dash). Deliberately conservative:

    - Only the message's opening is considered, so a mid-sentence name drop
      ("…and Claude is right") never narrows the room.
    - The bare-name form REQUIRES trailing address punctuation, so "claude code
      is great" is not a scope.
    - A compound lead ("Claude and Codex, …") fails the single-name match and
      falls through to the normal multi-target path.

    Caller scopes only the current turn and does not persist — the chips and
    mode are untouched, so the next message goes back to the full room.
    """
    if not text:
        return None
    s = _ADDRESS_GREETING.sub("", text.lstrip(), count=1)
    for agent in AGENTS:
        # @id — a space after is enough (the @ already marks a direct address).
        if re.match(r"@" + re.escape(agent["id"]) + r"\b\s+\S", s, flags=re.IGNORECASE):
            return agent["id"]
        # bare id or name — must be followed by address punctuation.
        for needle in (agent["id"], agent["name"]):
            if re.match(r"" + re.escape(needle) + r"\b\s*[,:—\-]", s, flags=re.IGNORECASE):
                return agent["id"]
    return None


def _effective_solo_scope(text: str, allowed: set) -> Optional[str]:
    """The single agent THIS turn scopes to, or None if nothing was addressed.

    A message that OPENS by addressing one roster agent ("Claude, …", "@codex ship
    it", "hey hermes:") scopes the turn to them — in ANY mode (counsel, collaborate,
    delegate, debate, poll, solo). Only that agent answers this one message; the
    rest of the room sits out, then the next message goes back to everyone. Not
    persisted, so there's no hidden solo state to switch off.

    The send response echoes the result to drive the composer's "Just X this turn —
    the rest sits out" pill, so this returns None unless we truly scope (e.g. the
    addressed agent isn't granted to this room).

    NOTE: a leading name is taken as a solo address even in pipeline/delegate, so a
    single message can no longer split per-stage work by leading with one name
    ("Claude, edit… Codex, rewrite…") — that collapses to the first agent. Drive
    per-stage/parallel work from the chips + an even-handed instruction, or from a
    skill's explicit `assignments`.
    """
    detected = _detect_solo_address(text)
    if not detected or detected not in allowed:
        return None
    return detected


def extract_mentions(text: str, lenient: bool = False) -> list[str]:
    """Find agent ids mentioned in text.

    Strict (default): only @-handle syntax — @id, or @display-name where the
    display name diverges from the id (agents may address a teammate by a
    display-name handle such as "Build Agent" -> "@build-agent").
    Still @-gated, so casual name drops in replies can't trigger runaway
    agent->agent auto-forward loops.

    Lenient: also matches bare id or bare name as a whole word (case-insensitive).
    Used for user->agent routing so the user can type "sales hi" naturally.
    """
    matches: list[tuple[int, int, str]] = []
    for roster_index, agent in enumerate(AGENTS):
        patterns = [r"@" + re.escape(agent["id"]) + r"\b"]
        name = str(agent.get("name") or "")
        if name and name.lower() != agent["id"].lower() and re.fullmatch(
            r"[A-Za-z0-9._-]+", name
        ):
            patterns.append(r"@" + re.escape(name) + r"\b")
        if lenient:
            patterns.extend(
                r"\b" + re.escape(needle) + r"\b"
                for needle in (agent["id"], agent["name"])
            )
        first_pos: Optional[int] = None
        for pattern in patterns:
            found = re.search(pattern, text, flags=re.IGNORECASE)
            if found and (first_pos is None or found.start() < first_pos):
                first_pos = found.start()
        if first_pos is not None:
            matches.append((first_pos, roster_index, agent["id"]))

    found_ids: list[str] = []
    for _pos, _roster_index, agent_id in sorted(matches):
        if agent_id not in found_ids:
            found_ids.append(agent_id)
    return found_ids


# Set for the duration of a recurring automation run (see _run_schedule). Every
# message the run produces is stamped with this `series` block so the client can
# fold same-series messages into one collapsible digest card. Default None =
# an ordinary message (manual turn, one-off skill apply), which is left untouched.
# A contextvar (not a global) so concurrent runs / requests never cross-tag, and
# the value is copied into the fire-and-forget turn task at create_task() time.
_SERIES_CTX: "contextvars.ContextVar[Optional[dict]]" = contextvars.ContextVar(
    "series_ctx", default=None
)

# Correlates every live event emitted by one user send. The browser uses this to
# keep dictation autoplay scoped to the reply for the words that were just spoken,
# instead of treating any older/concurrent agent message as eligible speech.
# Contextvars copy into create_task() children, so sequential stages, partial
# replies, and auto-forwards all retain the same turn id without global cross-talk.
_TURN_EVENT_ID: "contextvars.ContextVar[str]" = contextvars.ContextVar(
    "turn_event_id", default=""
)

# Marks one direct Voice Chat turn as the portable orchestrator ROLE. The value
# is the concrete, chosen-and-tested seat holder resolved for that request. It is
# task-scoped so concurrent ordinary turns by the same agent never inherit the
# role prompt or message metadata.
_DIRECT_ORCHESTRATOR_AGENT_ID: "contextvars.ContextVar[str]" = contextvars.ContextVar(
    "direct_orchestrator_agent_id", default=""
)
_VOICE_SESSION_TURN: "contextvars.ContextVar[bool]" = contextvars.ContextVar(
    "voice_session_turn", default=False
)

# True for the duration of an UNATTENDED run (a scheduled automation or a
# fire-and-forget background job) — nobody is watching to resolve a hold. A
# pipeline stage that hard-fails in such a run is auto-skipped (with a note) and
# the cascade continues, instead of parking a hold that would block the automation
# forever. Interactive runs leave this False and still hold. Like _SERIES_CTX, the
# value is copied into the fire-and-forget turn task at create_task() time.
_UNATTENDED: "contextvars.ContextVar[bool]" = contextvars.ContextVar(
    "unattended_run", default=False
)


_BOTTOM_LINE_TURN_CONTRACT = (
    "\n\n[FINAL RESPONSE FORMAT — mandatory on this turn]\n"
    "Start the visible reply with exactly `BOTTOM LINE: <one or two direct "
    "sentences>` as its own first paragraph. State the decisive answer, finding, "
    "decision, recommendation, or actual question — no teaser, process narration, "
    "praise, recap, or filler. Then leave a blank line and continue with only useful "
    "detail, without repeating the bottom line. Even a one-line reply must use this "
    "format."
)
_BOTTOM_LINE_MARKER_RE = re.compile(
    r"(?im)(?:^|(?<=[.!?]))[ \t]*(?:>[ \t]*)?(?:#{1,6}[ \t]+)?"
    r"(?:\*\*|__)?BOTTOM[ \t]+LINE"
    r"(?:[ \t]*(?:\*\*|__)?[ \t]*(?::|—|-)[ \t]*(?:\*\*|__)?"
    r"|[ \t]*(?:\*\*|__)?(?=[ \t]*(?:$|\n)))"
)
_BOTTOM_LINE_LEADING_LABEL_RE = re.compile(
    r"(?is)^[ \t]*(?:>[ \t]*)?(?:#{1,6}[ \t]+)?(?:\*\*|__)?"
    r"BOTTOM[ \t]+LINE(?:[ \t]*(?:\*\*|__)?[ \t]*(?::|—|-)[ \t]*"
    r"(?:\*\*|__)?|[ \t]*(?:\*\*|__)?(?=[ \t]*(?:$|\n)))[ \t]*"
)
_BOTTOM_LINE_MAX_CHARS = 600


def _with_bottom_line_turn_contract(prompt: str) -> str:
    """Put the response contract last, where every provider sees it every turn."""
    base = str(prompt or "").rstrip()
    contract = _BOTTOM_LINE_TURN_CONTRACT.strip()
    if base.endswith(contract):
        return base
    return base + _BOTTOM_LINE_TURN_CONTRACT


def _strip_bottom_line_labels(value: str) -> str:
    """Remove one or more model-authored labels from summary content itself."""
    text = str(value or "").strip()
    while text:
        cleaned = _BOTTOM_LINE_LEADING_LABEL_RE.sub("", text, count=1).strip()
        if cleaned == text:
            break
        text = cleaned
    return text


def _split_bottom_line_candidate(value: str) -> tuple[str, str]:
    """Return a bounded 1–2 sentence takeaway plus any overflow as body text."""
    text = _strip_bottom_line_labels(value)
    text = re.sub(r"[ \t\r\f\v]+", " ", text)
    text = re.sub(r" *\n *", " ", text).strip()
    if not text:
        return "", ""

    sentence_ends = list(re.finditer(r"[.!?](?=\s|$)", text))
    split_at = sentence_ends[1].end() if len(sentence_ends) >= 2 else len(text)
    if split_at > _BOTTOM_LINE_MAX_CHARS:
        split_at = _BOTTOM_LINE_MAX_CHARS
        prior_space = text.rfind(" ", 0, split_at + 1)
        if prior_space >= 80:
            split_at = prior_space
    candidate = text[:split_at].strip()
    overflow = text[split_at:].strip()
    return candidate, overflow


def _labeled_bottom_line_parts(
    source: str, marker: re.Match
) -> tuple[str, list[str]]:
    """Extract a labeled summary and return every non-summary fragment as body."""
    before = source[: marker.start()].strip()
    after = source[marker.end() :]
    # Marker-only variants put the actual takeaway in the next non-empty
    # paragraph (`BOTTOM LINE:\n\nShip it.`). Skip only leading line breaks here;
    # inline text after `BOTTOM LINE:` remains untouched.
    if re.match(r"^[ \t]*\r?\n", after):
        after = after.lstrip(" \t\r\n")
    paragraph_end = re.search(r"\n[ \t]*\n", after)
    if paragraph_end:
        raw_bottom = after[: paragraph_end.start()]
        remainder = after[paragraph_end.end() :].strip()
    else:
        raw_bottom = after
        remainder = ""
    bottom, overflow = _split_bottom_line_candidate(raw_bottom)
    body_parts = [part for part in (before, overflow, remainder) if part]
    return bottom, body_parts


def _normalize_agent_reply_bottom_line(
    text: str, metadata: Optional[dict] = None
) -> tuple[str, str]:
    """Guarantee the authored bottom line is the first visible paragraph.

    Providers are still prompted to author the takeaway because they know the full
    answer. This is the deterministic last line of defense for provider drift and
    for synthetic agent-role messages that never went through a provider.
    """
    source = str(text or "").strip()
    md = metadata if isinstance(metadata, dict) else {}

    preferred = ""
    if md.get("foreman") and str(md.get("speech") or "").strip():
        preferred = str(md.get("speech") or "")
    elif str(md.get("bottom_line") or "").strip():
        preferred = str(md.get("bottom_line") or "")

    body_parts: list[str] = []
    if preferred:
        bottom, overflow = _split_bottom_line_candidate(preferred)
        if overflow:
            body_parts.append(overflow)
        source_marker = _BOTTOM_LINE_MARKER_RE.search(source)
        if source_marker:
            _source_bottom, source_body = _labeled_bottom_line_parts(
                source, source_marker
            )
            body_parts.extend(source_body)
        elif source and re.sub(r"\s+", " ", source).strip() != bottom:
            body_parts.append(source)
    else:
        marker = _BOTTOM_LINE_MARKER_RE.search(source)
        if marker:
            bottom, body_parts = _labeled_bottom_line_parts(source, marker)
        else:
            paragraph_end = re.search(r"\n[ \t]*\n", source)
            if paragraph_end:
                raw_bottom = source[: paragraph_end.start()]
                remainder = source[paragraph_end.end() :].strip()
            else:
                raw_bottom = source
                remainder = ""
            bottom, overflow = _split_bottom_line_candidate(raw_bottom)
            if overflow:
                body_parts.append(overflow)
            if remainder:
                body_parts.append(remainder)

    if not bottom:
        return source, ""
    body = "\n\n".join(part.strip() for part in body_parts if part.strip())
    normalized = f"BOTTOM LINE: {bottom}"
    if body:
        normalized += "\n\n" + body
    return normalized, bottom


def _normalize_thread_bottom_lines_for_display(thread: list[dict]) -> list[dict]:
    """Normalize legacy agent rows on a copy for UI display, never persistence.

    `_load_thread` is also consumed by prompt cursors, hold/vote protocols, episode
    builders, and exports. Keeping this as an explicit presentation hook fixes old
    rows without rewriting the DB or changing those internal consumers.
    """
    displayed: list[dict] = []
    for message in thread or []:
        item = dict(message or {})
        metadata = dict(item.get("metadata") or {})
        # These rows drive the private first-run contract and remain available to
        # prompt construction / guide hydration, but they are not authored chat
        # messages. Never show them later in the ordinary conversation view.
        if _is_internal_onboarding_message(item):
            continue
        if item.get("role") == "agent":
            normalized, bottom_line = _normalize_agent_reply_bottom_line(
                item.get("text") or "", metadata
            )
            item["text"] = normalized
            if bottom_line:
                metadata["bottom_line"] = bottom_line
        item["metadata"] = metadata
        displayed.append(item)
    return displayed


def _is_unattended_run() -> bool:
    return bool(_UNATTENDED.get())


def _append_message_row(cid: int, entry: dict) -> Optional[int]:
    """Insert a single message row (O(1)) instead of rewriting the whole thread.

    Returns the new message id so the caller can tie side records (notably the
    token_usage meter) back to the exact message they describe."""
    with _db() as conn:
        cur = conn.execute(
            """
            INSERT INTO messages(chat_id, role, agent_id, name, text, ts, attachments_json, artifacts_json, metadata_json)
            SELECT ?, ?, ?, ?, ?, ?, ?, ?, ?
            FROM chats WHERE id=? AND deleted_ts IS NULL
            """,
            (
                int(cid),
                str(entry.get("role") or "system"),
                entry.get("agent_id"),
                str(entry.get("name") or "system"),
                str(entry.get("text") or ""),
                int(entry.get("ts") or int(time.time() * 1000)),
                json.dumps(entry.get("attachments") or []),
                json.dumps(entry.get("artifacts") or []),
                json.dumps(entry.get("metadata") or {}),
                int(cid),
            ),
        )
        if cur.rowcount != 1:
            raise RuntimeError(f"chat {cid} is unavailable")
        return int(cur.lastrowid) if cur.lastrowid else None


def _append_thread_mirror(cid: int, entry: dict) -> None:
    """Append one message to the JSON disaster-recovery mirror in O(1): a single
    JSONL line, never a full read+parse+dump+rewrite of the entire thread. The
    old whole-file rewrite was O(N) per message / O(N^2) over a chat's life and
    stalled the shared event loop on large chats (a 1MB thread re-serialized on
    every write). Fail-open: sqlite is the source of truth, so a mirror hiccup
    must never break a message write. A legacy pretty-printed array mirror is
    migrated to JSONL on first touch so DR restore keeps working."""
    try:
        with _live_chat_storage_guard(cid) as live:
            if not live:
                return
            p = _get_thread_path(cid)
            line = json.dumps(entry, separators=(",", ":")) + "\n"
            if p.is_file():
                with p.open("rb") as fh:
                    head = fh.read(1)
                if head == b"[":
                    # One-time O(N) migration of a legacy array mirror, then O(1)
                    # forever after (the next append sees a JSONL head).
                    legacy = _read_thread_mirror(p)
                    legacy.append(entry)
                    _write_thread_mirror(p, legacy)
                    return
            with p.open("a") as fh:
                fh.write(line)
    except Exception:
        logger.exception("failed to update thread mirror for chat %s", cid)


def append_thread(
    cid: int,
    role: str,
    agent_id: Optional[str],
    name: str,
    text: str,
    attachments: Optional[list] = None,
    artifacts: Optional[list] = None,
    metadata: Optional[dict] = None,
) -> dict:
    if int(cid) in DELETING_CHATS or str(int(cid)) not in (CHAT_INDEX.get("chats") or {}):
        raise RuntimeError(f"chat {cid} is unavailable")
    md = dict(metadata or {})
    if role == "agent":
        text, bottom_line = _normalize_agent_reply_bottom_line(text, md)
        if bottom_line:
            md["bottom_line"] = bottom_line
    # Stamp the automation series when this write happens inside a recurring run,
    # unless the caller already set one explicitly. This is what lets the client
    # group the run's notes + replies under one digest card.
    series = _SERIES_CTX.get()
    if series and "series" not in md:
        md["series"] = series
    entry = {
        "role": role,
        "agent_id": agent_id,
        "name": name,
        "text": text,
        "ts": int(time.time() * 1000),
        "attachments": list(attachments or []),
        "artifacts": list(artifacts or []),
        "metadata": md,
    }
    # Append-only: one INSERT + one mirror update, instead of the old
    # load-all → delete-all → reinsert-all (which was O(N) per message,
    # O(N^2) over a chat's life and rewrote the full JSON file every time).
    msg_id = _append_message_row(cid, entry)
    _append_thread_mirror(cid, entry)
    # Record token usage for real agent turns (exact when the bridge reported
    # usage, else estimated from text). Jarvis foreman cards borrow an agent's
    # face but are deterministic local notices — counting them fabricated model
    # spend and made the cross-agent audit look far noisier than it was.
    # Best-effort — never let metering break a write.
    # msg_id ties the spend to the exact reply that incurred it, so cost can be
    # attributed per message instead of only per chat.
    is_synthetic_foreman = (
        bool(md.get("foreman")) or md.get("kind") == "foreman"
        or md.get("source") == "jarvis_foreman"
    )
    if role == "agent" and agent_id and not is_synthetic_foreman:
        try:
            _record_token_usage(cid, agent_id, md.get("model") or "", md, text,
                                msg_id=msg_id)
        except Exception:
            logger.exception("token usage record failed for chat %s", cid)
    return entry


def _update_message_metadata(cid: int, ts: int, patch: dict) -> None:
    """Merge `patch` into one stored message's metadata_json, matched by chat +
    ts. Used to flip a hold card to resolved so it stays resolved across reloads
    (the messages table is what _load_thread reads). Best-effort; the JSON mirror
    is disaster-recovery only and left untouched."""
    try:
        with _db() as conn:
            row = conn.execute(
                "SELECT id, metadata_json FROM messages WHERE chat_id=? AND ts=? "
                "ORDER BY id DESC LIMIT 1",
                (int(cid), int(ts)),
            ).fetchone()
            if not row:
                return
            try:
                meta = json.loads(row["metadata_json"] or "{}")
                if not isinstance(meta, dict):
                    meta = {}
            except json.JSONDecodeError:
                meta = {}
            meta.update(patch)
            conn.execute(
                "UPDATE messages SET metadata_json=? WHERE id=?",
                (json.dumps(meta), row["id"]),
            )
    except Exception:
        logger.exception("failed to update message metadata for chat %s ts %s", cid, ts)


_SEARCH_STOPWORDS = {
    "the", "and", "for", "you", "are", "but", "not", "with", "that", "this",
    "have", "has", "was", "were", "will", "would", "can", "could", "should",
    "what", "when", "where", "which", "who", "how", "why", "your", "yours",
    "from", "they", "them", "their", "there", "here", "about", "into", "over",
    "out", "get", "got", "let", "lets", "make", "made", "want", "need", "like",
    "just", "also", "than", "then", "some", "any", "all", "our", "ours",
}


def _make_snippet(text: str, needle_lower: str, width: int = 60) -> str:
    """A compact, single-line excerpt of `text` centered on the first occurrence
    of `needle_lower` (already lowercased), with ellipses at clipped edges."""
    t = " ".join((text or "").split())
    if not t:
        return ""
    idx = t.lower().find(needle_lower)
    if idx < 0:
        return t[:width * 2] + ("…" if len(t) > width * 2 else "")
    start = max(0, idx - width)
    end = min(len(t), idx + len(needle_lower) + width)
    snip = t[start:end]
    if start > 0:
        snip = "…" + snip
    if end < len(t):
        snip = snip + "…"
    return snip


def _search_messages(cid: int, query: str, limit: int = 5, exclude_tail: int = 0) -> list[dict]:
    """Keyword retrieval over a chat's message history. Scores each message by
    how many distinct query terms it contains, newest-first as the tiebreak.

    Deliberately LIKE/substring based (no FTS5 table, so zero schema migration
    on the live DB). Loads the chat's rows once per call — fine into the tens of
    thousands; swap in an FTS5 index here if a single chat ever dwarfs that.
    `exclude_tail` skips the most-recent N messages (already in the prompt's
    recent window) so retrieval only surfaces *older* context."""
    terms = [t for t in re.findall(r"[a-z0-9]{3,}", (query or "").lower()) if t not in _SEARCH_STOPWORDS]
    terms = list(dict.fromkeys(terms))[:10]
    if not terms:
        return []
    with _db() as conn:
        rows = conn.execute(
            "SELECT id, role, agent_id, name, text, ts FROM messages WHERE chat_id=? "
            "AND (json_valid(metadata_json)=0 OR "
            "COALESCE(json_extract(metadata_json, '$.sensor_id'), '') != 'memory_gap') "
            "ORDER BY id",
            (int(cid),),
        ).fetchall()
    candidates = [dict(r) for r in rows]
    if exclude_tail > 0 and len(candidates) > exclude_tail:
        candidates = candidates[:-exclude_tail]
    scored: list[tuple] = []
    for r in candidates:
        low = (r.get("text") or "").lower()
        score = sum(1 for t in terms if t in low)
        if score:
            scored.append((score, r.get("id") or 0, r))
    scored.sort(key=lambda x: (x[0], x[1]), reverse=True)
    return [r for _, _, r in scored[:limit]]


_RAW_INCLUDE_RE = re.compile(r"§§include\s*\(", flags=re.IGNORECASE)
_ADDRESSED_AT_HANDLE_RE = re.compile(
    r"(?im)^\s*@([a-z0-9_-]+)(?=\s|[,;:!?—–-]|$)|"
    r"\b(?:ask|tell|delegate(?:\s+to)?|hand(?:\s+off)?(?:\s+to)?|pass(?:\s+to)?|"
    r"route(?:\s+to)?|assign(?:\s+to)?|send(?:\s+to)?|ping|loop\s+in|"
    r"wait(?:ing)?\s+(?:for|on))\s+@([a-z0-9_-]+)",
    flags=re.IGNORECASE,
)
_NON_ROSTER_ROLE_RE = re.compile(
    r"\b(bookkeeper|archivist|auditor|project manager)\b",
    flags=re.IGNORECASE,
)
_PATH_CLAIM_RE = re.compile(
    r"\b(saved|staged|queued|deployed|launched|sent|pulled|pulling|"
    r"segmented|segmenting|locked|updated|wiped|cleared|created)\b"
    r"[^.\n]{0,140}"
    r"(/a0/|/Users/|/shared/|shared volume|shared drive|ServiceTitan|CRM|"
    r"capacity ledger|campaign|blast|list)",
    flags=re.IGNORECASE,
)


def _reply_guardrail_warnings(agent: dict, reply: str) -> list[str]:
    """Flag high-risk agent reply patterns before peers treat them as truth.

    This is intentionally narrow: it does not try to grade business judgment.
    It catches the failure classes that repeatedly poisoned chats: raw
    Agent-Zero include directives, invented teammates, and confident
    file/CRM/platform state claims with no orchestrator-visible proof.
    """
    if not reply:
        return []

    warnings: list[str] = []
    if _RAW_INCLUDE_RE.search(reply):
        warnings.append(
            "used a raw `§§include(...)` directive in a visible chat reply. "
            "Treat that as unresolved content until the actual text or file is provided."
        )

    # Both the routable id AND the display name are legitimate handles — models
    # may use the display-name handle (for example "@build-agent"), and
    # extract_mentions resolves it, so don't flag it.
    roster_handles = {a["id"].lower() for a in AGENTS} | {
        str(a.get("name") or "").lower() for a in AGENTS
    }
    # Ordinary prose often contains social handles, email-like text, or quoted
    # research (for example "the account @realDonaldTrump"). Only treat an
    # unknown handle as an invented teammate when the reply actually addresses
    # it or uses an explicit delegation verb. This keeps the guardrail useful
    # without polluting the chat with false-positive system warnings.
    addressed_handles = {
        handle
        for match in _ADDRESSED_AT_HANDLE_RE.findall(reply)
        for handle in match
        if handle
    }
    invalid_handles = sorted({
        handle
        for handle in addressed_handles
        if handle.lower() not in roster_handles
    })
    if invalid_handles:
        warnings.append(
            "mentioned non-roster handle(s): "
            + ", ".join(f"@{h}" for h in invalid_handles)
            + ". Valid agents are "
            + ", ".join(f"@{a['id']}" for a in AGENTS)
            + "."
        )

    role_hits = sorted({m.group(1).title() for m in _NON_ROSTER_ROLE_RE.finditer(reply)})
    if role_hits:
        warnings.append(
            "referenced non-roster role(s): "
            + ", ".join(role_hits)
            + ". Do not wait on or delegate to roles that are not in the configured roster."
        )

    if _PATH_CLAIM_RE.search(reply):
        warnings.append(
            "made a file, CRM, queue, list, or campaign-state claim. Verify it with "
            "an actual tool result or user-confirmed path before acting on it."
        )

    return [f"[orchestrator guardrail] {agent['name']} {warning}" for warning in warnings]


