@app.put("/api/profile")
async def api_put_profile(request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    # Accept either the bare profile object or {"profile": {...}}.
    if isinstance(payload, dict) and isinstance(payload.get("profile"), dict):
        payload = payload["profile"]
    profile = _normalize_profile(payload)
    profile["source"] = "settings"
    saved = _save_user_profile(int(user["id"]), profile)
    # Sync receipt: build_prompt() injects the profile for every agent the user
    # holds on its next turn, so list them as "will be told". (Stateful container
    # memory sync is a later enhancement; the prompt path is already live.)
    synced = sorted(_allowed_agent_ids_for_user(user))
    return {"status": "ok", "profile": saved, "synced_agents": synced}


