@app.post("/api/guide/open")
async def api_open_product_guide(request: Request):
    """Find or create the singleton 'Ask about Agents Chat' thread and pin
    the orchestrator. The client then switches into it and opens voice."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    cid, created = _ensure_product_guide_chat(int(user["id"]))
    orch = _effective_concierge_agent_id()
    if orch:
        _save_chat_targets(cid, [orch])
    if created:
        await _route_system_note(
            cid,
            "Ask me anything about Agents Chat — the app, connecting an agent, "
            "or any setting. I'll open the right screen when that helps.",
        )
    messages = []
    for m in (_load_thread(cid) or [])[-80:]:
        messages.append({
            "role": m.get("role") or "agent",
            "agent_id": m.get("agent_id"),
            "name": m.get("name") or "",
            "text": m.get("text") or "",
            "ts": m.get("ts"),
            "chat_id": cid,
        })
    return {
        "ok": True,
        "chat_id": cid,
        "created": created,
        "title": PRODUCT_GUIDE_TITLE,
        "agent_id": orch,
        "messages": messages,
        "screens": [{"id": sid, "label": label} for sid, label in PRODUCT_GUIDE_SCREENS],
    }


