@app.post("/api/settings/telegram")
async def api_settings_telegram_post(request: Request):
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except json.JSONDecodeError:
        return JSONResponse({"error": "invalid json"}, status_code=400)
    if not isinstance(body, dict):
        return JSONResponse({"error": "json object required"}, status_code=400)

    # Token only overwritten when a fresh non-empty one is supplied (rotation),
    # and only after Telegram itself confirms it via getMe.
    new_token = str(body.get("bot_token") or "").strip()
    new_user = str(body.get("allowed_user_id") or "").strip()
    enabled = body.get("enabled")

    if new_token:
        check = await _tg_getme(new_token)
        if not check.get("ok"):
            return JSONResponse({"error": f"Telegram rejected that token: {check.get('error')}"}, status_code=400)
        _set_setting("telegram_bot_token", new_token)
    if new_user:
        if not new_user.isdigit():
            return JSONResponse({"error": "Telegram user id must be numeric"}, status_code=400)
        _set_setting("telegram_allowed_user_id", new_user)
    if enabled is not None:
        _set_setting("telegram_enabled", "1" if enabled else "0")

    _tg_load_config()
    _tg_restart_poller()
    _audit_event(
        request, "settings.telegram", actor="admin", status="ok",
        meta={"rotated_token": bool(new_token), "set_user": bool(new_user), "enabled": TELEGRAM_ENABLED},
    )
    return await _tg_status_payload()


