@app.get("/api/settings/setup-status")
async def api_settings_setup_status(request: Request):
    """Return secret-free facts used by the Today setup recommendations.

    This is deliberately a status endpoint rather than a settings dump: it
    reports only whether each capability is ready and which allowed agents do
    not yet have a mailbox. Tokens, addresses, hosts, and private calendar URLs
    never leave their existing secure settings surfaces.
    """
    blocked = _require_admin(request)
    if blocked:
        return blocked
    _tg_load_config()
    agents = _allowed_agents_for_user(_current_user(request))
    mailbox_ready: list[dict] = []
    mailbox_missing: list[dict] = []
    for agent in agents:
        agent_id = str(agent.get("id") or "").strip()
        if not agent_id:
            continue
        row = {"id": agent_id, "name": str(agent.get("name") or agent_id)}
        if _panel_mailboxes(agent_id):
            mailbox_ready.append(row)
        else:
            mailbox_missing.append(row)
    calendars = calendar_ics.public_calendars()
    telegram_configured = bool(TELEGRAM_BOT_TOKEN and TELEGRAM_ALLOWED_USER_ID)
    return {
        "status": "ok",
        "mailboxes": {
            "total_agents": len(mailbox_ready) + len(mailbox_missing),
            "ready_agents": mailbox_ready,
            "missing_agents": mailbox_missing,
        },
        "telegram": {
            "configured": telegram_configured,
            "enabled": bool(TELEGRAM_ENABLED),
            "ready": bool(telegram_configured and TELEGRAM_ENABLED),
        },
        "calendar": {
            "configured": calendar_ics.configured(),
            "count": len(calendars),
        },
    }


# ----- Orchestrator work-pattern recommendations -----------------------------
# This is intentionally deterministic and owner-scoped. The server reads the
# user's own recent messages to count broad workflow signals, but returns only
# aggregate counts and server-authored recommendations. Raw message text,
# excerpts, titles, and keywords never leave this function or land in the page.
_ORCHESTRATOR_PATTERN_RE = {
    "verify": re.compile(r"\b(test|tests|testing|verify|verification|qa|check)\b", re.I),
    "fix": re.compile(r"\b(fix|bug|debug|broken|issue|error|problem)\b", re.I),
    "release": re.compile(r"\b(ship|release|deploy|commit|push|tag|version)\b", re.I),
    "email": re.compile(r"\b(email|gmail|inbox|mailbox|smtp)\b", re.I),
    "automation": re.compile(
        r"\b(automation|automate|schedule|scheduled|recurring|remind|monitor)\b", re.I
    ),
    "api": re.compile(r"\b(api|integration|webhook|oauth|connector)\b|hook up", re.I),
    "research": re.compile(r"\b(research|latest|current|browse|search|look up)\b", re.I),
}
_ORCHESTRATOR_RECOMMENDATION_CACHE: dict[tuple[str, int, int], tuple[float, dict]] = {}
_ORCHESTRATOR_RECOMMENDATION_CACHE_TTL = 300.0


def _orchestrator_work_recommendations(
    owner_user_id: int, *, lookback_days: int = 30, now_ms: Optional[int] = None
) -> dict:
    """Summarize how one owner works and rank concrete next-step playbooks.

    Thirty days is a truthfulness floor, not marketing copy: until the account
    actually has that history, the endpoint reports that it is still learning
    and makes no behavioral claims. ``lookback_days`` is bounded for predictable
    query cost and is kept injectable for hermetic tests.
    """
    days = max(30, min(int(lookback_days or 30), 90))
    owner = int(owner_user_id)
    use_cache = now_ms is None
    cache_key = (str(DB_PATH.resolve()), owner, days)
    if use_cache:
        cached = _ORCHESTRATOR_RECOMMENDATION_CACHE.get(cache_key)
        if cached and time.monotonic() - cached[0] < _ORCHESTRATOR_RECOMMENDATION_CACHE_TTL:
            return cached[1]
    now = int(now_ms if now_ms is not None else time.time() * 1000)
    cutoff = now - days * 86_400_000

    def finish(payload: dict) -> dict:
        if use_cache:
            _ORCHESTRATOR_RECOMMENDATION_CACHE[cache_key] = (time.monotonic(), payload)
            if len(_ORCHESTRATOR_RECOMMENDATION_CACHE) > 64:
                oldest_key = min(
                    _ORCHESTRATOR_RECOMMENDATION_CACHE,
                    key=lambda key: _ORCHESTRATOR_RECOMMENDATION_CACHE[key][0],
                )
                _ORCHESTRATOR_RECOMMENDATION_CACHE.pop(oldest_key, None)
        return payload

    with _db() as conn:
        oldest = conn.execute(
            "SELECT MIN(m.ts) AS oldest FROM messages m "
            "JOIN chats c ON c.id=m.chat_id "
            "WHERE c.owner_user_id=? AND c.deleted_ts IS NULL AND m.role='user'",
            (owner,),
        ).fetchone()
        user_rows = conn.execute(
            "SELECT m.chat_id, m.text, m.ts, m.attachments_json, c.targets_json "
            "FROM messages m JOIN chats c ON c.id=m.chat_id "
            "WHERE c.owner_user_id=? AND c.deleted_ts IS NULL "
            "AND m.role='user' AND m.ts>=? AND m.ts<=?",
            (owner, cutoff, now),
        ).fetchall()
        role_counts = conn.execute(
            "SELECT m.role, COUNT(*) AS n, COUNT(DISTINCT m.chat_id) AS chats "
            "FROM messages m JOIN chats c ON c.id=m.chat_id "
            "WHERE c.owner_user_id=? AND c.deleted_ts IS NULL "
            "AND m.ts>=? AND m.ts<=? GROUP BY m.role",
            (owner, cutoff, now),
        ).fetchall()
        skills = conn.execute(
            "SELECT COUNT(*) AS total, "
            "SUM(CASE WHEN status='active' THEN 1 ELSE 0 END) AS active "
            "FROM skills WHERE owner_user_id=?",
            (owner,),
        ).fetchone()
        schedules = conn.execute(
            "SELECT COUNT(*) AS total, "
            "SUM(CASE WHEN enabled=1 THEN 1 ELSE 0 END) AS enabled "
            "FROM skill_schedules WHERE owner_user_id=?",
            (owner,),
        ).fetchone()

    oldest_ms = int((oldest["oldest"] if oldest else 0) or 0)
    observed_days = min(days, max(0, int((now - oldest_ms) // 86_400_000))) if oldest_ms else 0
    mature = observed_days >= 30
    role_by_name = {str(row["role"]): int(row["n"] or 0) for row in role_counts}
    chats_scanned = len({int(row["chat_id"]) for row in user_rows})
    active_days = len({int(row["ts"] or 0) // 86_400_000 for row in user_rows})
    attachment_chats = {
        int(row["chat_id"])
        for row in user_rows
        if str(row["attachments_json"] or "[]").strip() not in {"", "[]", "null"}
    }
    multi_agent_chats: set[int] = set()
    for row in user_rows:
        try:
            targets = json.loads(row["targets_json"] or "[]")
        except (TypeError, json.JSONDecodeError):
            targets = []
        if isinstance(targets, list) and len(targets) >= 2:
            multi_agent_chats.add(int(row["chat_id"]))

    pattern_chats: dict[str, set[int]] = {key: set() for key in _ORCHESTRATOR_PATTERN_RE}
    for row in user_rows:
        text = str(row["text"] or "")
        cid = int(row["chat_id"])
        for key, pattern in _ORCHESTRATOR_PATTERN_RE.items():
            if pattern.search(text):
                pattern_chats[key].add(cid)
    counts = {key: len(value) for key, value in pattern_chats.items()}

    coverage = {
        "lookback_days": days,
        "observed_days": observed_days,
        "active_days": active_days,
        "chats": chats_scanned,
        "user_messages": len(user_rows),
        "agent_messages": role_by_name.get("agent", 0),
        "attachment_chats": len(attachment_chats),
        "multi_agent_chats": len(multi_agent_chats),
        "skills": int((skills["total"] if skills else 0) or 0),
        "active_skills": int((skills["active"] if skills else 0) or 0),
        "automations": int((schedules["total"] if schedules else 0) or 0),
        "enabled_automations": int((schedules["enabled"] if schedules else 0) or 0),
        "mature": mature,
    }
    if not mature:
        return finish({"status": "ok", "coverage": coverage, "recommendations": []})

    # Scores rank the cards without changing their wording or exposing content.
    # The four primary families match the highest-leverage actions Agents Chat
    # can actually guide: save a skill, schedule it, connect an API, and put
    # email behind a safe read/draft/approval path.
    candidates: list[tuple[float, dict]] = []
    verify_n, fix_n, release_n = counts["verify"], counts["fix"], counts["release"]
    if verify_n + fix_n + release_n >= 6:
        candidates.append((
            verify_n * 2 + fix_n * 1.5 + release_n * 2,
            {
                "id": "workflow_skill", "kind": "skill", "icon": "badge-check",
                "eyebrow": "Your quality rhythm",
                "title": "Turn test → fix → proof into one skill",
                "body": "You repeatedly move from diagnosis to repair to visible proof. Save that sequence once so every agent starts with your standard of done.",
                "meta": f"{verify_n} chats involved verification · {fix_n} fixes · {release_n} releases",
                "cta": "Build my proof skill",
            },
        ))

    email_n = counts["email"]
    if email_n >= 3:
        candidates.append((
            email_n * 2.1,
            {
                "id": "email_workflow", "kind": "email", "icon": "mails",
                "eyebrow": "Your async command center",
                "title": "Let agents triage email and draft the reply",
                "body": "Your agents can read, prioritize, and prepare replies while you stay in control. Sending remains approval-gated unless you create a narrow allowlist.",
                "meta": f"Email work appeared across {email_n} chats · safest start: read + draft",
                "cta": "Design my email flow",
            },
        ))

    automation_n = counts["automation"]
    if automation_n >= 3 or (active_days >= 12 and chats_scanned >= 24):
        enabled = coverage["enabled_automations"]
        candidates.append((
            automation_n * 1.8 + active_days + max(0, 8 - enabled) * 2,
            {
                "id": "daily_digest", "kind": "automation", "icon": "calendar-sync",
                "eyebrow": "Give your future self the handoff",
                "title": "Let the workday close itself",
                "body": "A short scheduled brief can collect what finished, what is blocked, and what deserves tomorrow’s first hour—without another round of chat cleanup.",
                "meta": f"Active {active_days} of {days} days · {chats_scanned} working chats · {enabled} automations enabled",
                "cta": "Create my daily handoff",
            },
        ))

    api_n, research_n = counts["api"], counts["research"]
    if api_n >= 3 or research_n >= 6:
        candidates.append((
            api_n * 2 + research_n,
            {
                "id": "api_workflow", "kind": "api", "icon": "waypoints",
                "eyebrow": "Stop rebuilding connections",
                "title": "Create one safe API hookup playbook",
                "body": "Use the same least-privilege sequence every time: choose the service, store its secret locally, test the connection, then turn the useful call into a skill.",
                "meta": f"{api_n} chats involved APIs or integrations · {research_n} needed live information",
                "cta": "Build my API playbook",
            },
        ))

    if len(attachment_chats) >= 4:
        candidates.append((
            len(attachment_chats) * 1.25,
            {
                "id": "file_workflow", "kind": "skill", "icon": "scan-search",
                "eyebrow": "Your visual intake pattern",
                "title": "Make every screenshot start the right workflow",
                "body": "A reusable intake skill can inspect the image or file, clarify the desired outcome, route the work, and require a rendered final check.",
                "meta": f"Files or screenshots appeared in {len(attachment_chats)} chats",
                "cta": "Create my intake skill",
            },
        ))

    if len(multi_agent_chats) >= 5:
        candidates.append((
            len(multi_agent_chats),
            {
                "id": "team_workflow", "kind": "skill", "icon": "users-round",
                "eyebrow": "Your multi-agent pattern",
                "title": "Save your best team handoff",
                "body": "Package who investigates, who builds, and who verifies so the orchestrator can assemble your preferred team without re-explaining the roles.",
                "meta": f"You brought multiple agents into {len(multi_agent_chats)} chats",
                "cta": "Save my team pattern",
            },
        ))

    candidates.sort(key=lambda item: (-item[0], item[1]["id"]))
    return finish({
        "status": "ok",
        "coverage": coverage,
        "recommendations": [item[1] for item in candidates[:4]],
    })


@app.get("/api/orchestrator/recommendations")
async def api_orchestrator_recommendations(request: Request):
    """Owner-scoped, aggregate-only recommendations from recent work patterns."""
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    return _orchestrator_work_recommendations(int(user["id"]), lookback_days=30)


@app.post("/api/settings/calendar")
async def api_settings_calendar_post(request: Request):
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except json.JSONDecodeError:
        return JSONResponse({"error": "invalid json"}, status_code=400)
    if not isinstance(body, dict):
        return JSONResponse({"error": "json object required"}, status_code=400)
    url = str(body.get("ics_url") or "").strip()
    if not url:
        return JSONResponse({"error": "ics_url is required"}, status_code=400)
    if not url.lower().startswith(("http://", "https://", "webcal://")):
        return JSONResponse({"error": "must be an http(s) or webcal iCal URL"}, status_code=400)
    status, err = _write_shared_env_secret("CALENDAR_ICS_URL", url)
    if status != "ok":
        return JSONResponse(
            {"error": err or "couldn't save that URL (query strings aren't supported — "
                             "use the plain 'Secret address in iCal format')"},
            status_code=400,
        )
    _audit_event(request, "settings.calendar", actor="admin", status="ok", meta={"action": "set"})
    return _calendar_status_payload()


@app.delete("/api/settings/calendar")
async def api_settings_calendar_delete(request: Request):
    blocked = _require_admin(request)
    if blocked:
        return blocked
    _delete_shared_env_secret("CALENDAR_ICS_URL")
    _audit_event(request, "settings.calendar", actor="admin", status="ok", meta={"action": "clear"})
    return _calendar_status_payload()


@app.post("/api/settings/calendar/test")
async def api_settings_calendar_test(request: Request):
    """Test EVERY connected calendar at once and report the aggregate + any feeds
    that failed (so one broken calendar is visible without blaming the rest)."""
    blocked = _require_admin(request)
    if blocked:
        return blocked
    if not calendar_ics.configured():
        return JSONResponse({"ok": False, "error": "No calendar URL saved yet."}, status_code=400)
    try:
        res = await calendar_ics.upcoming(days=14, limit=1)
    except calendar_ics.CalendarError as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=502)
    events = res.get("events") or []
    return {"ok": True, "count": res.get("count", 0),
            "sample_title": events[0].get("title") if events else None,
            "errors": res.get("errors") or []}


async def _calendar_feed_test_result(feed: dict) -> dict:
    """Fetch and parse one feed without saving it.

    This is the atomic validation boundary used by both the Settings test button
    and conversational setup: the private URL is persisted only after this real
    read succeeds.
    """
    body = await calendar_ics._fetch_ics(feed["url"], timeout=20.0)
    import datetime as _dt
    now = _dt.datetime.now(calendar_ics._UTC)
    win_end = now + _dt.timedelta(days=14)
    rows: list = []
    for ev in calendar_ics._parse_events(calendar_ics._unfold(body)):
        if ev.get("status") == "CANCELLED":
            continue
        for (s, e) in calendar_ics._expand(ev, now, win_end):
            rows.append((s, ev.get("summary") or "(no title)"))
    rows.sort(key=lambda r: r[0])
    return {"ok": True, "count": len(rows),
            "sample_title": rows[0][1] if rows else None}


async def _test_single_feed(feed: dict):
    """Fetch one feed's window; shared by the per-calendar Test button."""
    try:
        return await _calendar_feed_test_result(feed)
    except calendar_ics.CalendarError as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=502)


# ----- Multiple calendars (CRUD over the JSON store) ------------------------
# The Settings "Calendar" card manages a LIST of ICS feeds. Each is named,
# colored and individually toggleable. URLs are secrets — only masked hints are
# returned. The env "primary" (legacy CALENDAR_ICS_URL) is folded into the store
# at boot; before that it appears here with id="primary"/source="env".
@app.post("/api/settings/calendars")
async def api_settings_calendars_add(request: Request):
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except json.JSONDecodeError:
        return JSONResponse({"error": "invalid json"}, status_code=400)
    if not isinstance(body, dict):
        return JSONResponse({"error": "json object required"}, status_code=400)
    url = str(body.get("ics_url") or "").strip()
    name = str(body.get("name") or "").strip()
    color = str(body.get("color") or "").strip() or None
    if not url:
        return JSONResponse({"error": "ics_url is required"}, status_code=400)
    if "§§secret(" in url or not SHARED_ENV_SAFE_VALUE_PATTERN.match(url):
        return JSONResponse({"error": "that URL contains characters that can't be stored safely"},
                            status_code=400)
    # Settings must prove the same real read as conversational setup before it
    # claims the calendar is connected. Previously this route only checked the
    # URL scheme, persisted dead/shareable Google links, and returned a green
    # "on" state even though the Calendar workspace could not read them.
    try:
        clean_url = calendar_ics._validate_url(url)
    except calendar_ics.CalendarError as exc:
        return JSONResponse({"error": _safe_calendar_setup_error(exc)}, status_code=400)
    if any(feed.get("url") == clean_url for feed in calendar_ics.all_calendars()):
        return JSONResponse({"error": "That calendar is already connected."}, status_code=400)
    try:
        await _calendar_feed_test_result({
            "id": "pending", "name": name or "Calendar", "url": clean_url,
            "color": color or calendar_ics._DEFAULT_COLORS[0], "enabled": True,
        })
    except calendar_ics.CalendarError as exc:
        return JSONResponse({"error": _safe_calendar_setup_error(exc)}, status_code=502)
    except Exception:
        logger.exception("settings calendar validation failed")
        return JSONResponse(
            {"error": "The live calendar test could not be completed."},
            status_code=502,
        )
    try:
        calendar_ics.add_calendar(name, clean_url, color)
    except calendar_ics.CalendarError as exc:
        # A concurrent request may have connected the same feed after the live
        # test. Preserve add_calendar's final store-level validation.
        return JSONResponse({"error": _safe_calendar_setup_error(exc)}, status_code=400)
    _audit_event(request, "settings.calendar", actor="admin", status="ok",
                 meta={"action": "add", "name": name or "calendar"})
    return _calendar_status_payload()


@app.patch("/api/settings/calendars/{cal_id}")
async def api_settings_calendars_update(cal_id: str, request: Request):
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except json.JSONDecodeError:
        return JSONResponse({"error": "invalid json"}, status_code=400)
    if not isinstance(body, dict):
        return JSONResponse({"error": "json object required"}, status_code=400)
    name = body.get("name")
    color = body.get("color")
    enabled = body.get("enabled")
    if enabled is not None:
        enabled = bool(enabled)
    if cal_id == "primary":
        # The env primary has no store row yet: enable/disable isn't supported
        # there (clear it to remove), but a URL replace routes to shared.env.
        new_url = str(body.get("ics_url") or "").strip()
        if new_url:
            if not new_url.lower().startswith(("http://", "https://", "webcal://")):
                return JSONResponse({"error": "must be an http(s) or webcal iCal URL"}, status_code=400)
            status, err = _write_shared_env_secret("CALENDAR_ICS_URL", new_url)
            if status != "ok":
                return JSONResponse({"error": err or "couldn't save that URL"}, status_code=400)
        _audit_event(request, "settings.calendar", actor="admin", status="ok",
                     meta={"action": "update", "id": "primary"})
        return _calendar_status_payload()
    try:
        updated = calendar_ics.update_calendar(
            cal_id,
            name=name if name is not None else None,
            color=color if color is not None else None,
            enabled=enabled,
            url=(str(body.get("ics_url")).strip() if body.get("ics_url") else None),
        )
    except calendar_ics.CalendarError as exc:
        return JSONResponse({"error": str(exc)}, status_code=400)
    if updated is None:
        return JSONResponse({"error": "no such calendar"}, status_code=404)
    _audit_event(request, "settings.calendar", actor="admin", status="ok",
                 meta={"action": "update", "id": cal_id})
    return _calendar_status_payload()


@app.delete("/api/settings/calendars/{cal_id}")
async def api_settings_calendars_delete(cal_id: str, request: Request):
    blocked = _require_admin(request)
    if blocked:
        return blocked
    if cal_id == "primary":
        _delete_shared_env_secret("CALENDAR_ICS_URL")
    elif not calendar_ics.remove_calendar(cal_id):
        return JSONResponse({"error": "no such calendar"}, status_code=404)
    _audit_event(request, "settings.calendar", actor="admin", status="ok",
                 meta={"action": "remove", "id": cal_id})
    return _calendar_status_payload()


