@app.post("/api/settings/idle-timeout")
async def api_settings_idle_timeout_post(request: Request):
    """Install-wide idle lock minutes. 0 disables the lock. AUTH_SESSION_DAYS
    remains the absolute session cap."""
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except json.JSONDecodeError:
        return JSONResponse({"error": "invalid json"}, status_code=400)
    if not isinstance(body, dict) or "idle_timeout_min" not in body:
        return JSONResponse({"error": "idle_timeout_min required"}, status_code=400)
    minutes = _parse_idle_timeout_min(body.get("idle_timeout_min"))
    if minutes is None:
        return JSONResponse(
            {"error": f"idle_timeout_min must be an integer from 0 to {IDLE_TIMEOUT_MIN_MAX}"},
            status_code=400,
        )
    _set_setting("idle_timeout_min", str(minutes))
    _audit_event(
        request, "settings.idle_timeout", actor="admin", status="ok",
        meta={"idle_timeout_min": minutes},
    )
    return JSONResponse({"idle_timeout_min": minutes})


