@app.post("/api/settings/telegram/test")
async def api_settings_telegram_test(request: Request):
    blocked = _require_admin(request)
    if blocked:
        return blocked
    _tg_load_config()
    if not TELEGRAM_ENABLED:
        return JSONResponse({"error": "Telegram is not configured or is disabled"}, status_code=400)
    me = await _tg_getme()
    if not me.get("ok"):
        return JSONResponse({"error": f"token invalid: {me.get('error')}"}, status_code=400)
    res = await _tg_api("sendMessage", {
        "chat_id": TELEGRAM_ALLOWED_USER_ID,
        "text": "✅ <b>Test from Agents Chat</b>\nYour Telegram bridge is wired up correctly.",
        "parse_mode": "HTML",
        "disable_web_page_preview": True,
    })
    delivered = bool(res and res.get("ok"))
    _audit_event(
        request, "settings.telegram.test", actor="admin",
        status="ok" if delivered else "error",
        meta={"bot": me.get("username"), "delivered": delivered},
    )
    if not delivered:
        desc = str((res or {}).get("description") or "send failed")
        low = desc.lower()
        hint = " — open Telegram and press Start on the bot first." if ("can't initiate" in low or "chat not found" in low or "blocked" in low) else ""
        return JSONResponse({"error": f"{desc}{hint}", "bot_username": me.get("username")}, status_code=400)
    return {"status": "ok", "delivered": True, "bot_username": me.get("username")}


@app.get("/api/backup.zip")
async def api_backup_zip(request: Request):
    blocked = _require_admin(request)
    if blocked:
        return blocked
    data = _backup_zip()
    _audit_event(
        request,
        "backup.create",
        actor="admin",
        status="ok",
        meta={"bytes": len(data)},
    )
    stamp = time.strftime("%Y%m%d-%H%M%S")
    return Response(
        data,
        media_type="application/zip",
        headers={
            "Content-Disposition": f'attachment; filename="neuroblend-v5-backup-{stamp}.zip"',
            "Cache-Control": "no-store",
        },
    )


@app.get("/api/extensions/screen-recorder.zip")
async def api_recorder_extension_zip(request: Request):
    """Ready-to-load bundle of the screen-recorder Chrome extension, served so
    the Settings walkthrough works on any machine without filesystem access.
    key.pem (the packing key) stays server-side — the manifest's embedded
    public key alone is what pins the extension ID."""
    blocked = _require_auth(request)
    if blocked:
        return blocked
    src = Path(__file__).resolve().parent / "extensions" / "screen-recorder"
    if not src.is_dir():
        return JSONResponse({"error": "extension bundle missing"}, status_code=404)
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for f in sorted(src.iterdir()):
            if not f.is_file() or f.name == "key.pem" or f.name.startswith("."):
                continue
            z.write(f, f"screen-recorder/{f.name}")
    return Response(
        buf.getvalue(),
        media_type="application/zip",
        headers={
            "Content-Disposition": 'attachment; filename="agent-chat-screen-recorder.zip"',
            "Cache-Control": "no-store",
        },
    )


@app.get("/health")
async def health_alias():
    """Bare unauthenticated liveness alias — external probes hit /health, which
    used to 404 (only /api/health exists, behind auth). Outside /api/ so
    hardening_middleware never gates it; discloses nothing but liveness."""
    return {"status": "ok"}


# What a non-admin is told about an agent's health. Deliberately narrow (see
# test_limited_user_health_hides_ungranted_agents_and_sensitive_details): `state`
# already names the condition — online / degraded / reachable / offline /
# error / missing-token — so the client derives its dots from that and no
# operator detail (url, token_present, context_id, error, raw status) leaves here.
_PUBLIC_HEALTH_FIELDS = ("id", "name", "state", "latency_ms")


@app.get("/api/health")
async def api_health(request: Request):
    user = _current_user(request) or {}
    is_admin = _is_admin_user(user)
    allowed = _allowed_agent_ids_for_user(user)
    active_chat_id = _active_chat_id_for_request(request)
    checks = await _agent_health_checks(active_chat_id, allowed)
    with _db() as conn:
        storage_detail = {
            "engine": "sqlite",
            "path": str(DB_PATH),
            "chats": conn.execute("SELECT COUNT(*) FROM chats").fetchone()[0],
            "messages": conn.execute("SELECT COUNT(*) FROM messages").fetchone()[0],
            "sessions": conn.execute("SELECT COUNT(*) FROM sessions").fetchone()[0],
        }
        # A COUNT(*) — never _load_thread(), which would deserialize every message
        # row (3 JSON blobs each) just to produce an integer, on the event loop.
        thread_messages = conn.execute(
            "SELECT COUNT(*) FROM messages WHERE chat_id=?", (int(active_chat_id or 0),)
        ).fetchone()[0] if active_chat_id else 0
    result = {
        "status": "ok",
        "version": "v5",
        "build": APP_VERSION,
        "active_chat_id": active_chat_id,
        "device_id": _device_id_from_request(request),
        "thread_messages": thread_messages,
        "auth_required": bool(REQUIRE_AUTH or ACCESS_TOKEN),
        "storage": storage_detail if is_admin else {"engine": "sqlite"},
        "agents": checks if is_admin else [
            # `ok` and `reachable` are the two booleans every status dot and
            # ready-count in the client is computed from. Stripping them left a
            # non-admin looking at an all-red roster and "0 connected" while the
            # agents were perfectly healthy. They carry no operator detail — the
            # sensitive fields (url, token_present, context_id, error) stay out.
            {k: item.get(k) for k in _PUBLIC_HEALTH_FIELDS}
            for item in checks
        ],
    }
    if is_admin:
        result["sse_clients"] = len(SSE_CLIENTS)
    return result


_AGENT_HEALTH_CACHE: dict[tuple, tuple[float, list[dict]]] = {}
_AGENT_HEALTH_CACHE_S = 20.0
_AGENT_HEALTH_LOCK = asyncio.Lock()


async def _agent_health_checks(
    active_chat_id: int, allowed_ids: Optional[set[str]] = None,
) -> list[dict]:
    contexts = _chat_contexts(active_chat_id)
    allowed = set(allowed_ids) if allowed_ids is not None else {a["id"] for a in AGENTS}
    selected = [a for a in AGENTS if a["id"] in allowed]
    cache_key = (int(active_chat_id or 0), tuple(a["id"] for a in selected))
    cached = _AGENT_HEALTH_CACHE.get(cache_key)
    if cached and time.monotonic() - cached[0] < _AGENT_HEALTH_CACHE_S:
        return [dict(item) for item in cached[1]]

    async def check(agent: dict):
        token = os.environ.get(agent.get("token_env", "")) or agent.get("token", "")
        context_id = contexts.get(agent["id"], "")
        started = time.perf_counter()
        base = {
            "id": agent["id"],
            "name": agent["name"],
            "url": agent["url"],
            "token_present": bool(token),
            "context_present": bool(context_id),
            "context_id": context_id,
            "checked_ts": int(time.time() * 1000),
        }
        if not token:
            return {
                **base,
                "ok": False,
                "reachable": False,
                "state": "missing-token",
                "latency_ms": None,
                "error": f"missing token ({agent.get('token_env')})",
            }
        try:
            async with httpx.AsyncClient(timeout=2.0) as client:
                resp = await client.post(
                    _log_url(agent),
                    json={"context_id": context_id, "length": 1},
                    headers={"X-API-KEY": token, "Content-Type": "application/json"},
                )
            latency_ms = round((time.perf_counter() - started) * 1000, 1)
            reachable = resp.status_code < 500
            fresh_context_ok = (
                resp.status_code == 400
                and "context_id is required" in resp.text.lower()
            )
            ok = resp.status_code == 200 or fresh_context_ok
            state = "online" if ok else ("reachable" if reachable else "error")
            error = None if ok else f"HTTP {resp.status_code}"
            # Honest-health: the probe above only proves the proxy answers. A
            # managed bridge can be up yet unable to serve a turn (upstream token
            # expired / provider down). If it self-reports degraded, downgrade
            # from a false green to amber ("degraded") with the real reason, so
            # the dot and the Reconnect button tell the truth. reachable stays
            # True → the UI renders amber, not red.
            if agent["id"] in MANAGED_BRIDGES:
                degraded, reason = await _managed_bridge_deep_status(agent["id"])
                if degraded and ok:
                    ok = False
                    state = "degraded"
                    error = reason
                elif degraded and reason:
                    # The deep probe was previously asked ONLY when the cheap one
                    # said "fine" — so at the exact moment a bridge was failing,
                    # the UI showed a bare "HTTP 500" and Reconnect had nothing to
                    # explain. The self-reported reason is strictly better than a
                    # status code; ok/state stay as the liveness probe judged them.
                    error = reason
            return {
                **base,
                "ok": ok,
                "reachable": reachable,
                "state": state,
                "status": resp.status_code,
                "latency_ms": latency_ms,
                "error": error,
            }
        except Exception as e:
            return {
                **base,
                "ok": False,
                "reachable": False,
                "state": "offline",
                "latency_ms": round((time.perf_counter() - started) * 1000, 1),
                "error": str(e),
            }

    # Two visible tabs commonly tick on the same 30-second boundary. Only one
    # should fan out to every bridge; followers consume the just-filled cache.
    async with _AGENT_HEALTH_LOCK:
        cached = _AGENT_HEALTH_CACHE.get(cache_key)
        if cached and time.monotonic() - cached[0] < _AGENT_HEALTH_CACHE_S:
            return [dict(item) for item in cached[1]]
        checks = await asyncio.gather(*(check(a) for a in selected)) if selected else []
        _AGENT_HEALTH_CACHE[cache_key] = (time.monotonic(), checks)
        if len(_AGENT_HEALTH_CACHE) > 64:
            oldest = min(_AGENT_HEALTH_CACHE, key=lambda key: _AGENT_HEALTH_CACHE[key][0])
            _AGENT_HEALTH_CACHE.pop(oldest, None)
        return [dict(item) for item in checks]


@app.get("/api/agents/health")
async def api_agents_health(request: Request):
    user = _current_user(request) or {}
    is_admin = _is_admin_user(user)
    active_chat_id = _active_chat_id_for_request(request)
    checks = await _agent_health_checks(
        active_chat_id, _allowed_agent_ids_for_user(user)
    )
    return {
        "status": "ok",
        "chat_id": active_chat_id,
        "device_id": _device_id_from_request(request),
        "agents": checks if is_admin else [
            # `ok` and `reachable` are the two booleans every status dot and
            # ready-count in the client is computed from. Stripping them left a
            # non-admin looking at an all-red roster and "0 connected" while the
            # agents were perfectly healthy. They carry no operator detail — the
            # sensitive fields (url, token_present, context_id, error) stay out.
            {k: item.get(k) for k in _PUBLIC_HEALTH_FIELDS}
            for item in checks
        ],
    }


# Community Edition setup is intentionally discovery-first. The app scans for
# supported local tools without starting anything, then an admin can connect all
# ready tools with one click. No paths or tokens are ever returned to the browser.
_COMMUNITY_BRIDGE_MODULES = {
    "codex": "scripts.codex_agent_bridge:app",
    "claude": "scripts.claude_agent_bridge:app",
    "minimax": "scripts.minimax_agent_bridge:app",
    "antigravity": "scripts.antigravity_agent_bridge:app",
    "grok": "scripts.grok_agent_bridge:app",
    "perplexity": "scripts.perplexity_agent_bridge:app",
    "openrouter": "scripts.openrouter_agent_bridge:app",
}
_COMMUNITY_AGENT_URL_ENVS = {
    "codex": "CODEX_AGENT_URL",
    "claude": "CLAUDE_AGENT_URL",
    "minimax": "MINIMAX_AGENT_URL",
    "antigravity": "ANTIGRAVITY_AGENT_URL",
    "grok": "GROK_AGENT_URL",
    "perplexity": "PERPLEXITY_AGENT_URL",
    "openrouter": "OPENROUTER_AGENT_URL",
}
_COMMUNITY_BRIDGE_PROCESSES: dict[str, subprocess.Popen] = {}
_COMMUNITY_PAIRINGS: dict[str, dict] = {}
_COMMUNITY_PAIRING_TTL_S = 15 * 60
_COMMUNITY_PAIRING_RESULT_TTL_S = 5 * 60
_COMMUNITY_PAIRING_PROGRESS_STAGES = {
    "preparing", "configuring", "starting", "verifying", "needs_user",
}
_COMMUNITY_ADAPTER_PORT_START = 55200
_COMMUNITY_ADAPTER_PORT_END = 55299
# port each live adapter was started on, parallel to _COMMUNITY_BRIDGE_PROCESSES
_COMMUNITY_BRIDGE_PORTS: dict[str, int] = {}

# Sidecar is the only kill authority for detached adapters (same as previews).
COMMUNITY_BRIDGE_STATE_FILE = Path(
    os.environ.get("COMMUNITY_BRIDGE_STATE_FILE",
                   str(DATA_DIR / "community_bridges.json"))
)


def _save_community_bridge_state() -> None:
    try:
        rows = [
            {"agent_id": str(aid), "pid": int(proc.pid),
             "port": int(_COMMUNITY_BRIDGE_PORTS[aid])}
            for aid, proc in _COMMUNITY_BRIDGE_PROCESSES.items()
            if proc is not None and proc.poll() is None
            and _COMMUNITY_BRIDGE_PORTS.get(aid)
            # This file is the kill list the boot reaper works from, so a pid it
            # could never legitimately hold must never enter it. pid 1 is init /
            # launchd; anything below that is not a process at all.
            and int(getattr(proc, "pid", 0) or 0) > 1
        ]
        tmp = COMMUNITY_BRIDGE_STATE_FILE.with_suffix(".tmp")
        tmp.write_text(json.dumps(rows))
        tmp.replace(COMMUNITY_BRIDGE_STATE_FILE)
    except OSError:
        pass


def _listening_community_ports() -> dict[int, int]:
    """Whatever is listening on the reserved adapter pool right now. Only
    meaningful at boot, when nothing of ours can legitimately be running."""
    try:
        out = subprocess.run(
            ["lsof", "-nP", "-iTCP", "-sTCP:LISTEN"],
            capture_output=True, text=True, timeout=10,
        )
    except (OSError, subprocess.SubprocessError):
        return {}
    return _parse_listening_ports_in_range(
        out.stdout, _COMMUNITY_ADAPTER_PORT_START, _COMMUNITY_ADAPTER_PORT_END)


def _pid_is_alive(pid: int) -> bool:
    """False for missing PIDs and for zombies (signal 0 still succeeds on those)."""
    try:
        waited, _status = os.waitpid(pid, os.WNOHANG)
        if waited == pid:
            return False
    except ChildProcessError:
        pass
    except OSError:
        return False
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    try:
        out = subprocess.run(
            ["ps", "-p", str(pid), "-o", "state="],
            capture_output=True, text=True, timeout=1,
        )
    except (OSError, subprocess.SubprocessError):
        return True
    state = (out.stdout or "").strip()
    return bool(state) and not state.upper().startswith("Z")


def _signal_process_group(pid: int, sig: int) -> None:
    try:
        os.killpg(os.getpgid(pid), sig)
    except OSError:
        os.kill(pid, sig)


def _wait_then_kill_pids(
    pids: list[int], *, wait_s: float = 5.0, kill_s: float = 2.0,
) -> list[int]:
    """After SIGTERM. Shared deadline, then SIGKILL. Returns PIDs still alive."""
    remaining = [pid for pid in pids if _pid_is_alive(pid)]
    deadline = time.monotonic() + wait_s
    while remaining and time.monotonic() < deadline:
        time.sleep(0.05)
        remaining = [pid for pid in remaining if _pid_is_alive(pid)]
    for pid in remaining:
        try:
            _signal_process_group(pid, signal.SIGKILL)
        except OSError:
            pass
    deadline = time.monotonic() + kill_s
    while remaining and time.monotonic() < deadline:
        time.sleep(0.05)
        remaining = [pid for pid in remaining if _pid_is_alive(pid)]
    return remaining


def _write_community_bridge_sidecar(rows: list[dict]) -> None:
    try:
        tmp = COMMUNITY_BRIDGE_STATE_FILE.with_suffix(".tmp")
        tmp.write_text(json.dumps(rows))
        tmp.replace(COMMUNITY_BRIDGE_STATE_FILE)
    except OSError:
        pass


async def _reap_orphan_community_bridges_on_startup() -> None:
    """Kill connector adapters stranded by a hard restart.

    The persisted sidecar is the authority for what Agents Chat owns. Never kill
    an unrecorded listener merely because it sits on a pool port: a stale/missing
    sidecar must degrade to a skipped port, not host process loss.
    """
    rows: list = []
    try:
        if COMMUNITY_BRIDGE_STATE_FILE.is_file():
            loaded = json.loads(COMMUNITY_BRIDGE_STATE_FILE.read_text())
            if isinstance(loaded, list):
                rows = loaded
    except (OSError, ValueError):
        rows = []
    signaled: list[tuple[str, int, int]] = []  # agent_id, pid, port
    listening = _listening_community_ports()   # port -> pid, for identity checks
    for row in rows:
        try:
            pid, port = int(row["pid"]), int(row["port"])
            aid = str(row.get("agent_id") or "")
        except (KeyError, TypeError, ValueError):
            continue
        # Two ways to be sure this pid is really that adapter, so PID reuse can
        # never make us kill a bystander: it still holds the recorded port, or
        # the port appears in its command line (uvicorn always gets --port).
        if listening.get(port) != pid:
            cmd = _process_cmdline(pid)
            if not cmd or str(port) not in cmd:
                continue  # already gone, or the PID belongs to something else
        try:
            _signal_process_group(pid, signal.SIGTERM)
            signaled.append((aid, pid, port))
        except OSError:
            pass
    survivors = []
    if signaled:
        still = set(_wait_then_kill_pids([pid for _aid, pid, _port in signaled]))
        survivors = [
            {"agent_id": aid, "pid": pid, "port": port}
            for aid, pid, port in signaled if pid in still
        ]
        logger.info(
            "reaped %d orphaned connector bridge(s) from a previous run",
            len(signaled) - len(survivors),
        )
    if survivors:
        _write_community_bridge_sidecar(survivors)
        return
    try:
        COMMUNITY_BRIDGE_STATE_FILE.unlink(missing_ok=True)
    except OSError:
        pass


def _stop_community_bridges() -> None:
    """SIGTERM the set, wait once, SIGKILL. Unlink sidecar only when all are dead."""
    live: list[tuple[str, int, int]] = []  # aid, pid, port
    for aid, proc in list(_COMMUNITY_BRIDGE_PROCESSES.items()):
        if proc is None or proc.poll() is not None:
            continue
        try:
            _signal_process_group(proc.pid, signal.SIGTERM)
        except OSError:
            try:
                proc.terminate()
            except OSError:
                pass
        port = _COMMUNITY_BRIDGE_PORTS.get(aid)
        if port:
            live.append((str(aid), int(proc.pid), int(port)))
    still = set(_wait_then_kill_pids([pid for _aid, pid, _port in live]))
    survivors = [
        {"agent_id": aid, "pid": pid, "port": port}
        for aid, pid, port in live if pid in still
    ]
    _COMMUNITY_BRIDGE_PROCESSES.clear()
    _COMMUNITY_BRIDGE_PORTS.clear()
    if survivors:
        _write_community_bridge_sidecar(survivors)
        return
    try:
        COMMUNITY_BRIDGE_STATE_FILE.unlink(missing_ok=True)
    except OSError:
        pass


def _community_custom_rows() -> list[dict]:
    """Read the private connector store without applying startup de-dup rules."""
    if not CUSTOM_AGENTS_FILE.is_file():
        return []
    try:
        raw = json.loads(CUSTOM_AGENTS_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return []
    rows = raw.get("agents", raw) if isinstance(raw, dict) else raw
    return [dict(row) for row in rows if isinstance(row, dict)] if isinstance(rows, list) else []


def _community_write_custom_rows(rows: list[dict]) -> None:
    CUSTOM_AGENTS_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = CUSTOM_AGENTS_FILE.with_suffix(CUSTOM_AGENTS_FILE.suffix + ".tmp")
    tmp.write_text(json.dumps({"agents": rows}, indent=2) + "\n", encoding="utf-8")
    try:
        os.chmod(tmp, 0o600)
    except OSError:
        pass
    tmp.replace(CUSTOM_AGENTS_FILE)


def _community_local_url(raw: object, *, protocol: str) -> str:
    """Validate a connector target without turning setup into an SSRF surface."""
    value = str(raw or "").strip()
    if not value:
        raise ValueError("Enter the local agent URL")
    parsed = urlparse(value)
    host = (parsed.hostname or "").lower()
    if parsed.scheme not in ("http", "https") or not host or parsed.username or parsed.password:
        raise ValueError("Use a local http:// or https:// agent URL")
    is_local = host in ("localhost", "::1", "host.docker.internal")
    if not is_local:
        try:
            is_local = ipaddress.ip_address(host).is_loopback
        except ValueError:
            is_local = False
    if not is_local:
        raise ValueError("For safety, connect the agent through localhost or 127.0.0.1")
    path = parsed.path or "/"
    if protocol == "openai_chat" and path == "/":
        path = "/v1/chat/completions"
    elif protocol == "agent_chat" and path == "/":
        path = "/api/api_message"
    if protocol == "openai_chat" and not path.endswith("/chat/completions"):
        raise ValueError("Use the agent's OpenAI-compatible /v1/chat/completions URL")
    if protocol == "agent_chat" and not path.endswith("/api/api_message"):
        raise ValueError("Use the agent's /api/api_message URL")
    return parsed._replace(path=path, params="", query="", fragment="").geturl()


def _community_free_adapter_port() -> int:
    reserved = set()
    for row in AGENTS:
        try:
            reserved.add(urlparse(str(row.get("url") or "")).port)
        except ValueError:
            pass
    for port in range(_COMMUNITY_ADAPTER_PORT_START, _COMMUNITY_ADAPTER_PORT_END + 1):
        if port in reserved:
            continue
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            sock.bind(("127.0.0.1", port))
            return port
        except OSError:
            continue
        finally:
            sock.close()
    raise RuntimeError("No free local connector port is available")


def _community_launch_openai_adapter(agent: dict) -> tuple[bool, str]:
    running = _COMMUNITY_BRIDGE_PROCESSES.get(agent["id"])
    if running and running.poll() is None:
        return True, "Already running"
    parsed = urlparse(str(agent.get("url") or ""))
    if parsed.hostname not in ("127.0.0.1", "localhost", "::1") or not parsed.port:
        return False, "Connector address must be local"
    try:
        with socket.create_connection((parsed.hostname, parsed.port), timeout=0.25):
            return True, "Already running"
    except OSError:
        pass
    env = os.environ.copy()
    env.update({
        "AGENT_ADAPTER_TOKEN": str(agent.get("token") or ""),
        "AGENT_ADAPTER_UPSTREAM_URL": str(agent.get("upstream_url") or ""),
        "AGENT_ADAPTER_UPSTREAM_TOKEN": str(agent.get("upstream_token") or ""),
        "AGENT_ADAPTER_MODEL": str(agent.get("upstream_model") or "agent"),
        "AGENT_ADAPTER_NAME": str(agent.get("name") or agent["id"]),
    })
    log_dir = DATA_DIR / "bridge_logs"
    log_dir.mkdir(parents=True, exist_ok=True)
    flags = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0) if os.name == "nt" else 0
    with (log_dir / f"{agent['id']}.log").open("ab") as log:
        proc = subprocess.Popen(
            [sys.executable, "-m", "uvicorn", "scripts.openai_compatible_agent_bridge:app",
             "--host", "127.0.0.1", "--port", str(parsed.port), "--no-access-log"],
            cwd=str(BASE_DIR), env=env, stdout=log, stderr=subprocess.STDOUT,
            start_new_session=(os.name != "nt"), creationflags=flags,
        )
    _COMMUNITY_BRIDGE_PROCESSES[agent["id"]] = proc
    _COMMUNITY_BRIDGE_PORTS[agent["id"]] = int(parsed.port)
    _save_community_bridge_state()
    return True, "Starting"


def _community_add_runtime_agent(entry: dict, owner_user_id: int) -> dict:
    global PUBLIC_AGENTS
    aid = entry["id"]
    if aid in AGENTS_BY_ID:
        raise ValueError("That agent id is already in use")
    AGENTS.append(entry)
    AGENTS_BY_ID[aid] = entry
    public = _public_agent(entry)
    PUBLIC_AGENTS.append(public)
    with _db() as conn:
        conn.execute(
            "INSERT OR IGNORE INTO user_agents(user_id, agent_id, created_ts) VALUES (?, ?, ?)",
            (int(owner_user_id), aid, int(time.time() * 1000)),
        )
    _AGENT_HEALTH_CACHE.clear()
    return public


def _community_verify_agent_contract(agent: dict) -> None:
    """Require the local endpoint, key, and readiness probe to work before save."""
    token = str(agent.get("token") or "")
    response = None
    last_exc = None
    attempts = 5 if agent.get("managed_adapter") else 1
    for attempt in range(attempts):
        try:
            response = httpx.post(
                _log_url(agent),
                json={"context_id": "", "length": 1},
                headers={"X-API-KEY": token, "Content-Type": "application/json"},
                timeout=2.5,
            )
            break
        except Exception as exc:
            last_exc = exc
            if attempt + 1 < attempts:
                time.sleep(0.15)
    if response is None:
        raise ValueError(
            "Agents Chat could not reach that agent. Keep it running, then check "
            "the local URL and try again."
        ) from last_exc
    accepted = response.status_code == 200 or (
        response.status_code == 400
        and "context_id is required" in response.text.lower()
    )
    if accepted:
        return
    if response.status_code in (401, 403):
        raise ValueError("The agent rejected that connection key. Copy the key again and retry.")
    try:
        detail = str(response.json().get("error") or "").strip()
    except Exception:
        detail = ""
    if detail:
        raise ValueError(detail[:300])
    raise ValueError(
        "The agent answered, but its readiness check failed. Verify the agent URL "
        "and keep the desktop app signed in."
    )


def _community_verify_live_turn(agent: dict) -> None:
    """Prove a self-connected endpoint reaches a real runtime, not a mock reply."""
    marker = f"AGENTS-CHAT-{secrets.token_hex(6).upper()}"
    token = str(agent.get("token") or "")
    try:
        response = httpx.post(
            str(agent.get("url") or ""),
            json={
                "message": (
                    "Agents Chat connection test. Reply with this exact marker "
                    f"and no other text: {marker}"
                ),
                "context_id": "",
            },
            headers={"X-API-KEY": token, "Content-Type": "application/json"},
            timeout=30,
        )
    except Exception as exc:
        raise ValueError(
            "The endpoint opened, but its real agent runtime did not answer a test "
            "question. Keep the agent running and try again."
        ) from exc
    if response.status_code != 200:
        raise ValueError(
            "The endpoint passed its health check but could not answer a real test "
            "question. Connect its model or CLI, then try again."
        )
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError("The agent test reply was not valid JSON.") from exc
    reply = str(payload.get("response") or payload.get("message") or "")
    if marker not in reply:
        raise ValueError(
            "This connector returned a placeholder response instead of using the "
            "real agent. Connect its model or CLI, then try again."
        )


def _community_register_agent(
    owner_user_id: int, body: dict, *, verify_turn: bool = False
) -> tuple[dict, str]:
    protocol = str(body.get("protocol") or "agent_chat").strip().lower()
    if protocol not in ("agent_chat", "openai_chat"):
        raise ValueError("Choose Agents Chat or OpenAI-compatible connection")
    name = " ".join(str(body.get("name") or "My agent").split())[:80] or "My agent"
    requested_id = _slugify(str(body.get("id") or name))[:40]
    aid = requested_id
    suffix = 2
    while aid in AGENTS_BY_ID:
        if body.get("id"):
            raise ValueError("That agent id is already in use")
        aid = f"{requested_id[:35]}-{suffix}"
        suffix += 1
    token = str(body.get("token") or "").strip()
    if not token:
        raise ValueError("Enter the agent's local connection key")
    target = _community_local_url(body.get("url"), protocol=protocol)
    entry = {
        "id": aid, "name": name, "color": "#4f8cff", "emoji": name[:1].upper(),
        "voice": f"{name}, connected locally by this user.",
        "source": "community_connector", "owner_user_id": int(owner_user_id),
    }
    detail = "Saved"
    if protocol == "openai_chat":
        port = _community_free_adapter_port()
        entry.update({
            "url": f"http://127.0.0.1:{port}/api/api_message",
            "token": secrets.token_urlsafe(48),
            "managed_adapter": "openai_chat",
            "upstream_url": target,
            "upstream_token": token,
            "upstream_model": str(body.get("model") or "agent").strip()[:120] or "agent",
        })
        started, detail = _community_launch_openai_adapter(entry)
        if not started:
            raise RuntimeError(detail)
    else:
        entry.update({"url": target, "token": token})
    _community_verify_agent_contract(entry)
    if verify_turn:
        _community_verify_live_turn(entry)
    rows = _community_custom_rows()
    rows.append(entry)
    _community_write_custom_rows(rows)
    public = _community_add_runtime_agent(entry, owner_user_id)
    _invalidate_community_discovery(owner_user_id)
    return public, detail


async def _community_reconnect_on_startup() -> None:
    """Reconnect only agents the user previously approved (token exists)."""
    if not connector_setup_enabled():
        return
    for agent in AGENTS:
        if agent.get("managed_adapter") == "openai_chat":
            try:
                _community_launch_openai_adapter(agent)
            except Exception:
                logger.exception("community adapter reconnect failed: %s", agent["id"])
            continue
        # Everything below auto-spawns a BUILT-IN agent's bridge, which is only
        # correct when nothing else supervises it. On a managed install (macOS
        # launchd, Windows service) those bridges already have a supervisor, and
        # a second detached copy is the dual-supervisor bug: an orphan on PID 1
        # serving stale code alongside the real one. Connector installs get the
        # adapter relaunch above; only Community auto-starts the bridges.
        if not community_mode():
            continue
        token_env = agent.get("token_env", "")
        if not token_env or not os.environ.get(token_env):
            continue
        detected = _community_provider_detection(agent["id"])
        if detected.get("path") and agent["id"] in _COMMUNITY_BRIDGE_MODULES:
            try:
                _community_launch_bridge(agent)
            except Exception:
                logger.exception("community startup reconnect failed: %s", agent["id"])


def _first_existing_path(values) -> Optional[Path]:
    for raw in values:
        if not raw:
            continue
        p = Path(str(raw)).expanduser()
        if sys.platform == "win32" and p.suffix.lower() == ".ps1":
            continue
        if p.is_file():
            return p.resolve()
    return None


def _cli_probe_command(path: Path, args: tuple[str, ...]) -> list[str]:
    command = [str(path), *args]
    if sys.platform == "win32" and path.suffix.lower() in (".cmd", ".bat"):
        command = ["cmd.exe", "/d", "/c", str(path), *args]
    return command


def _first_usable_cli_path(
    values, *, probes: tuple[tuple[str, ...], ...] = (("--version",),),
) -> Optional[Path]:
    """Return the first CLI that can complete every harmless readiness probe."""
    for raw in values:
        if not raw:
            continue
        path = Path(str(raw)).expanduser()
        if not path.is_file():
            continue
        if sys.platform == "win32" or len(probes) > 1:
            try:
                for args in probes:
                    probe = subprocess.run(
                        _cli_probe_command(path, args),
                        capture_output=True,
                        text=True,
                        timeout=5,
                        check=False,
                        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                    )
                    if probe.returncode != 0:
                        break
            except (OSError, subprocess.SubprocessError):
                continue
            if probe.returncode != 0:
                continue
        return path.resolve()
    return None


def _windows_store_app_install_location(package_name: str) -> Optional[Path]:
    """Find an installed Microsoft Store package without exposing its path."""
    if sys.platform != "win32":
        return None
    safe_name = re.sub(r"[^A-Za-z0-9._-]", "", str(package_name or ""))
    if not safe_name:
        return None
    command = (
        f"$app=Get-AppxPackage -Name '{safe_name}' | "
        "Sort-Object Version -Descending | Select-Object -First 1; "
        "if ($app) { $app.InstallLocation }"
    )
    try:
        result = subprocess.run(
            ["powershell.exe", "-NoProfile", "-NonInteractive", "-Command", command],
            capture_output=True,
            text=True,
            timeout=4,
            check=False,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if result.returncode != 0:
        return None
    location = next((line.strip() for line in result.stdout.splitlines() if line.strip()), "")
    return Path(location) if location else None


def _community_perplexity_driver_path() -> Optional[Path]:
    """Resolve the scoped helper without exposing its private install path."""
    if sys.platform != "darwin":
        return None
    try:
        from scripts import perplexity_agent_bridge as bridge

        path = bridge._driver_path()
    except Exception:
        return None
    return path if path.is_file() else None


def _community_request_perplexity_accessibility() -> tuple[bool, str]:
    """Open macOS Accessibility for the final, narrowly scoped helper app."""
    if sys.platform != "darwin":
        return False, "Perplexity desktop control is currently available on macOS only."
    try:
        from scripts import perplexity_agent_bridge as bridge

        if not bridge._driver_path().is_file():
            return False, "This Community package is missing the Perplexity desktop helper."
        result = bridge._driver_json(["--request-accessibility"], timeout=20)
    except Exception:
        logger.exception("community Perplexity Accessibility request failed")
        return False, "macOS could not open the Perplexity Accessibility request."
    if result.get("trusted") or result.get("status") == "ok":
        return True, "Accessibility is already enabled. Verifying Perplexity now."
    return True, (
        "In System Settings, turn on Agent Chat Perplexity Driver. "
        "Leave the generic python3 entry off, then return here and choose Verify."
    )


def _community_provider_detection(agent_id: str) -> dict:
    """Return private detection detail used by setup; callers must strip path."""
    home = Path.home()
    configured = AGENTS_BY_ID.get(agent_id) or {}
    if configured.get("source") == "community_connector":
        return {
            "found": True, "connectable": False, "path": None, "path_env": None,
            "next": "Saved, but the local agent is not responding yet. Start it, then scan again.",
        }
    if agent_id == "codex":
        candidates = [
            os.environ.get("CODEX_BIN"),
            "/Applications/ChatGPT.app/Contents/Resources/codex",
            home / ".local" / "bin" / "codex",
            home / "AppData" / "Roaming" / "npm" / "codex.cmd",
            home / "AppData" / "Roaming" / "npm" / "codex.exe",
            shutil.which("codex"), shutil.which("codex.exe"),
        ]
        installed_cli = _first_existing_path(candidates)
        found = _first_usable_cli_path(
            candidates, probes=(("--version",), ("login", "status")),
        )
        if found:
            return {"found": True, "connectable": True, "path": found,
                    "path_env": "CODEX_BIN", "next": "Codex CLI is ready to connect."}
        desktop_app = _windows_store_app_install_location("OpenAI.Codex")
        protected_store_cli = installed_cli and "windowsapps" in str(installed_cli).lower()
        if desktop_app and (not installed_cli or protected_store_cli):
            return {
                "found": True, "connectable": False, "path": None,
                "path_env": "CODEX_BIN", "setup_kind": "codex_cli",
                "next": (
                    "The Codex app is installed. Use the guided setup below to add "
                    "its official command-line runtime, then Agents Chat will connect it."
                ),
            }
        if installed_cli:
            return {
                "found": True, "connectable": False, "path": installed_cli,
                "path_env": "CODEX_BIN",
                "next": (
                    "The Codex command is installed but not signed in. Stay here — "
                    "I will start the sign-in. Finish it in the browser, then tap I signed in."
                ),
            }
        return {"found": False, "connectable": False, "path": None,
                "path_env": "CODEX_BIN", "next": "Install Codex, then scan again."}
    if agent_id == "claude":
        bundled = sorted(
            (home / "Library" / "Application Support" / "Claude" / "claude-code").glob(
                "*/claude.app/Contents/MacOS/claude"
            ), reverse=True,
        )
        found = _first_existing_path([
            os.environ.get("CLAUDE_BIN"), *bundled,
            home / ".local" / "bin" / "claude",
            shutil.which("claude"), shutil.which("claude.exe"),
        ])
        signed = bool(found) and _claude_cli_signed_in()
        return {
            "found": bool(found), "connectable": bool(found and signed), "path": found,
            "path_env": "CLAUDE_BIN",
            "next": (
                "Claude is installed but signed out. Stay in chat — I will walk you through signing it in."
                if found else "Install or sign in to Claude."
            ),
        }
    if agent_id == "minimax":
        auth_file = Path(os.environ.get(
            "MINIMAX_AUTH_FILE", str(home / ".minimax" / "local-runtime.auth.json")
        )).expanduser()
        found = bool(
            os.environ.get("MINIMAX_JWT")
            or os.environ.get("MINIMAX_API_KEY")
            or auth_file.is_file()
        )
        return {"found": found, "connectable": found, "path": None,
                "path_env": None, "next": "Open MiniMax and sign in once."}
    if agent_id == "antigravity":
        found = _first_existing_path([
            os.environ.get("ANTIGRAVITY_BIN"), home / ".local" / "bin" / "agy",
            "/opt/homebrew/bin/agy", "/usr/local/bin/agy", shutil.which("agy"),
            shutil.which("agy.exe"),
        ])
        return {"found": bool(found), "connectable": bool(found), "path": found,
                "path_env": "ANTIGRAVITY_BIN", "next": "Install or sign in to Antigravity."}
    if agent_id == "grok":
        found = _first_existing_path([
            os.environ.get("GROK_BIN"), home / ".grok" / "bin" / "grok",
            shutil.which("grok"), shutil.which("grok.exe"),
        ])
        signed_in = bool(
            os.environ.get("GROK_DEPLOYMENT_KEY")
            or os.environ.get("GROK_AUTH_PROVIDER_COMMAND")
            or (home / ".grok" / "auth.json").is_file()
        )
        return {
            "found": bool(found), "connectable": bool(found and signed_in),
            "path": found, "path_env": "GROK_BIN",
            "next": "Open a terminal and run grok login." if found else "Install the Grok CLI first.",
        }
    if agent_id == "perplexity":
        mac_app = Path("/Applications/Perplexity.app/Contents/MacOS/Perplexity")
        app_path = mac_app if mac_app.is_file() else None
        driver_ready = bool(_community_perplexity_driver_path())
        return {
            "found": bool(app_path),
            "connectable": bool(app_path and driver_ready),
            "path": app_path,
            "path_env": None,
            "setup_kind": "perplexity_desktop" if driver_ready else "perplexity_driver_missing",
            "next": (
                "Perplexity is installed. Choose Connect; Agents Chat will create "
                "a private local key, start the bridge, and open the one macOS "
                "Accessibility switch you need."
                if app_path and driver_ready
                else "This Community package is missing its Perplexity desktop helper. Reinstall the current Community release."
                if app_path
                else "Install and sign in to the Perplexity desktop app first."
            ),
        }
    if agent_id == "openrouter":
        configured = bool(os.environ.get("OPENROUTER_API_KEY", "").strip())
        return {
            # OpenRouter is a cloud provider, so "found" means the built-in
            # connector is available. The private credential is the only setup
            # dependency; it is never returned to the browser.
            "found": True,
            "connectable": configured,
            "path": None,
            "path_env": None,
            "setup_kind": "openrouter_ready" if configured else "openrouter_api_key",
            "next": (
                "Your OpenRouter key is saved. Start the private local bridge."
                if configured
                else "Paste an OpenRouter API key to connect the provider. The key stays on this computer."
            ),
        }
    if agent_id == "hermes":
        # Hermes has no packaged local bridge yet: it is a self-hosted server.
        # Point at the concrete path (the manual URL+key fields) instead of a
        # generic dead-end.
        return {
            "found": False, "connectable": False, "path": None, "path_env": None,
            # Two surfaces render this hint (onboarding and Settings), and only
            # onboarding has the "Add a Docker or desktop agent" disclosure, so
            # the wording stays surface-neutral and names only controls that
            # exist on both.
            "next": (
                "Hermes runs as a self-hosted local server. Start it, then pick "
                "Hermes Agent / Hermes Desktop in the connection concierge and "
                "enter its local URL and key under Advanced manual setup."
            ),
            "manual": True,
        }
    return {
        "found": False, "connectable": False, "path": None, "path_env": None,
        "next": "This agent uses advanced manual setup.", "manual": True,
    }


# Many Community agents ship as Docker containers, so setup also scans the local
# Docker CLI. The scan is read-only and best-effort: no docker CLI, a stopped
# daemon, a permission error or a hung daemon all mean "no containers found".
# A first-run user must never see a Docker error, and a page load must never
# wait on the daemon, so every call is timed out and the result is cached.
_COMMUNITY_DOCKER_IMAGE_RECIPES = (
    (("agent-zero", "agent0", "agentzero"),
     {"recipe": "agentzero", "protocol": "agent_chat", "model": "", "ports": (80, 50001)}),
    (("hermes",),
     {"recipe": "hermes", "protocol": "openai_chat", "model": "hermes-agent", "ports": (8642,)}),
    (("openclaw",),
     {"recipe": "openclaw", "protocol": "openai_chat", "model": "openclaw/default", "ports": (18789,)}),
    (("betterclaw",),
     {"recipe": "betterclaw", "protocol": "openai_chat", "model": "", "ports": ()}),
)
# An unfamiliar image still gets an offer: try the OpenAI-compatible shape first
# (most local runtimes speak it), then the Agents Chat contract.
_COMMUNITY_DOCKER_UNKNOWN_RECIPES = (
    {"recipe": "openai", "protocol": "openai_chat", "model": "", "ports": (8080, 8000, 3000, 80)},
    {"recipe": "custom", "protocol": "agent_chat", "model": "", "ports": (8080, 8000, 3000, 80)},
)
_COMMUNITY_DOCKER_PROTOCOL_PATHS = {
    "agent_chat": "/api/api_message",
    "openai_chat": "/v1/chat/completions",
}
# Never offer a published service port that cannot be an HTTP agent endpoint.
# Agent Zero publishes SSH (22) beside its web port, and offering that as the
# agent URL would look like a working choice and never answer.
_COMMUNITY_DOCKER_BLOCKED_PORTS = {
    22, 23, 25, 53, 110, 111, 135, 137, 138, 139, 143, 389, 445, 465, 587,
    993, 995, 1433, 3306, 3389, 5432, 5900, 6379, 9200, 11211, 27017,
}
_COMMUNITY_DOCKER_PORT_RE = re.compile(
    r"(?:(\[[0-9A-Fa-f:]+\]|\d{1,3}(?:\.\d{1,3}){3}):)?(\d{1,5})->(\d{1,5})/(tcp|udp)"
)
# The probe only proves "something HTTP answers this path". A 404/501 means the
# server is alive but does not serve this contract, so it is not a match.
_COMMUNITY_DOCKER_LIVE_STATUS = {200, 201, 202, 400, 401, 403, 405, 409, 415, 422, 429}
_COMMUNITY_DOCKER_CACHE: dict = {"ts": 0.0, "data": None}
_COMMUNITY_DOCKER_TTL_S = 20.0
_COMMUNITY_DOCKER_LIST_TIMEOUT_S = 2.0
_COMMUNITY_DOCKER_PROBE_TIMEOUT_S = 0.6
_COMMUNITY_DOCKER_PROBE_BUDGET_S = 3.0


def _community_docker_cli() -> Optional[Path]:
    """Locate the docker CLI; launchd services do not inherit a login PATH."""
    return _first_existing_path([
        os.environ.get("DOCKER_BIN"),
        shutil.which("docker"), shutil.which("docker.exe"),
        "/usr/local/bin/docker", "/opt/homebrew/bin/docker", "/usr/bin/docker",
    ])


def _community_docker_containers() -> list[dict]:
    """List local containers as parsed JSON rows; any failure means none."""
    cli = _community_docker_cli()
    if not cli:
        return []
    try:
        result = subprocess.run(
            [str(cli), "ps", "--all", "--no-trunc", "--format", "{{json .}}"],
            capture_output=True,
            text=True,
            timeout=_COMMUNITY_DOCKER_LIST_TIMEOUT_S,
            check=False,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
    except (OSError, subprocess.SubprocessError):
        return []
    if result.returncode != 0:
        return []
    rows = []
    for line in (result.stdout or "").splitlines():
        line = line.strip()
        if not line.startswith("{"):
            continue
        try:
            row = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(row, dict):
            rows.append(row)
    return rows[:60]


def _community_docker_image_repo(image: str) -> str:
    """Strip the registry tag/digest so any tag of an image maps the same way."""
    ref = str(image or "").strip().lower().split("@", 1)[0]
    head, _, tail = ref.rpartition("/")
    tail = tail.split(":", 1)[0]
    return f"{head}/{tail}" if head else tail


def _community_docker_recipes_for_image(image: str) -> list[dict]:
    """Map an image to setup-screen connector recipes, best guess first."""
    repo = _community_docker_image_repo(image)
    for needles, recipe in _COMMUNITY_DOCKER_IMAGE_RECIPES:
        if repo and any(needle in repo for needle in needles):
            return [dict(recipe)]
    return [dict(item) for item in _COMMUNITY_DOCKER_UNKNOWN_RECIPES]


def _community_docker_host_is_local(host: str) -> bool:
    """A published port only counts when 127.0.0.1 can actually reach it."""
    value = (host or "").strip().strip("[]").lower()
    if not value:
        return False
    if value == "localhost":
        return True
    try:
        address = ipaddress.ip_address(value)
    except ValueError:
        return False
    return address.is_loopback or address.is_unspecified


def _community_docker_ports(container: dict, recipe: dict) -> list[dict]:
    seen, out = set(), []
    for match in _COMMUNITY_DOCKER_PORT_RE.finditer(str(container.get("Ports") or "")):
        host, host_port_raw, container_port_raw, proto = match.groups()
        if proto != "tcp" or not _community_docker_host_is_local(host):
            continue
        host_port, container_port = int(host_port_raw), int(container_port_raw)
        if not 0 < host_port < 65536 or host_port in seen:
            continue
        if host_port in _COMMUNITY_DOCKER_BLOCKED_PORTS:
            continue
        if container_port in _COMMUNITY_DOCKER_BLOCKED_PORTS:
            continue
        seen.add(host_port)
        out.append({"port": host_port, "container_port": container_port})
    preferred = tuple(recipe.get("ports") or ())
    out.sort(key=lambda item: (item["container_port"] not in preferred, item["port"]))
    return out[:6]


def _community_docker_probe(port: int, protocol: str) -> bool:
    """Liveness only: loopback, no redirects, no credentials, short timeout."""
    path = _COMMUNITY_DOCKER_PROTOCOL_PATHS.get(protocol)
    if not path:
        return False
    try:
        response = httpx.get(
            f"http://127.0.0.1:{port}{path}",
            timeout=_COMMUNITY_DOCKER_PROBE_TIMEOUT_S,
            follow_redirects=False,
        )
    except Exception:
        return False
    return response.status_code in _COMMUNITY_DOCKER_LIVE_STATUS


def _community_docker_row(container: dict, deadline: float) -> dict:
    """Describe one container the way _community_provider_detection describes a CLI."""
    name = str(container.get("Names") or "").split(",")[0].strip()
    name = name or str(container.get("ID") or "")[:12] or "container"
    image = str(container.get("Image") or "").strip()
    options = _community_docker_recipes_for_image(image)
    primary = options[0]
    state = str(container.get("State") or "").strip().lower()
    running = (state == "running") if state else str(
        container.get("Status") or ""
    ).strip().lower().startswith("up")
    row = {
        "id": _slugify(f"docker-{name}")[:40] or "docker-agent",
        "kind": "docker", "container": name, "image": image,
        "running": running, "found": True, "connectable": False,
        "recipe": primary["recipe"], "protocol": primary["protocol"],
        "model": primary["model"], "name": name, "url": "", "candidates": [],
        "state": "stopped", "detail": "", "next": "",
    }
    if not running:
        row["detail"] = row["next"] = (
            "Not running. Start this container in Docker, then scan again."
        )
        return row
    ports = _community_docker_ports(container, primary)
    row["candidates"] = [f"http://127.0.0.1:{item['port']}" for item in ports]
    if not ports:
        row["state"] = "no_ports"
        row["detail"] = row["next"] = (
            "Running, but it does not publish a local port. Republish it on "
            "127.0.0.1, then scan again."
        )
        return row
    matches = []
    for item in ports:
        if time.monotonic() > deadline:
            break
        for option in options:
            if _community_docker_probe(item["port"], option["protocol"]):
                matches.append((item, option))
                break
    if len(matches) > 1:
        preferred = [
            match for match in matches
            if match[0]["container_port"] in tuple(primary.get("ports") or ())
        ]
        if len(preferred) == 1:
            matches = preferred
    if len(matches) == 1:
        item, option = matches[0]
        row.update({
            "recipe": option["recipe"], "protocol": option["protocol"],
            "model": option["model"], "connectable": True, "state": "found",
            "url": f"http://127.0.0.1:{item['port']}"
                   f"{_COMMUNITY_DOCKER_PROTOCOL_PATHS[option['protocol']]}",
            "detail": "Found on this computer — ready to connect",
            "next": "Ready to connect. Add this container's connection key.",
        })
        return row
    row["state"] = "needs_choice"
    row["detail"] = row["next"] = (
        "Running, but more than one local port answered. Pick the agent port "
        "under Advanced manual setup."
        if matches else
        "Running, but no published port answered yet. Pick its local port "
        "under Advanced manual setup."
    )
    return row


def _community_docker_agents() -> list[dict]:
    """Cached Docker candidates for setup; never raises, never blocks a load."""
    cache = _COMMUNITY_DOCKER_CACHE
    if cache["data"] is not None and time.monotonic() - cache["ts"] < _COMMUNITY_DOCKER_TTL_S:
        return [dict(row) for row in cache["data"]]
    deadline = time.monotonic() + _COMMUNITY_DOCKER_PROBE_BUDGET_S
    rows = []
    try:
        for container in _community_docker_containers():
            rows.append(_community_docker_row(container, deadline))
    except Exception:
        logger.debug("community docker scan failed", exc_info=True)
        rows = []
    cache["ts"], cache["data"] = time.monotonic(), rows
    return [dict(row) for row in rows]


_COMMUNITY_DOCKER_PRIVATE_NAME = re.compile(
    r"(ops|support|lead|sales|jda|automatic.?climate|private-client|\bac[-_]?hermes\b)",
    re.I,
)
_COMMUNITY_DOCKER_INFRA_IMAGE = re.compile(
    r"(postgres|postgresql|mysql|mariadb|redis|mongo|nginx|caddy|traefik|minio)",
    re.I,
)


def _community_docker_is_public_offer(row: dict) -> bool:
    """Community Edition must not offer private/client stacks or infra images."""
    name = str(row.get("name") or row.get("container") or "")
    image = str(row.get("image") or "")
    if _COMMUNITY_DOCKER_PRIVATE_NAME.search(name):
        return False
    if _COMMUNITY_DOCKER_INFRA_IMAGE.search(name) or _COMMUNITY_DOCKER_INFRA_IMAGE.search(image):
        return False
    return True


def _community_docker_discovery_rows() -> list[dict]:
    """Docker half of the setup payload; inert outside Community Edition."""
    if not community_mode():
        return []
    known = {str(agent.get("url") or "") for agent in AGENTS}
    known |= {str(agent.get("upstream_url") or "") for agent in AGENTS}
    out = []
    for row in _community_docker_agents():
        if not _community_docker_is_public_offer(row):
            continue
        if row.get("url") and row["url"] in known:
            row = {
                **row, "state": "connected", "connectable": False,
                "detail": "Connected and ready",
                "next": "This container is already connected.",
            }
        out.append(row)
    return out


def _community_discovery_agents_for_user(user: dict) -> list[dict]:
    """Full setup catalog, including built-ins not connected to this user yet."""
    uid = int(user["id"])
    out = []
    for agent in AGENTS:
        owner = int(agent.get("owner_user_id") or 0)
        if agent.get("source") == "community_connector" and owner != uid:
            continue
        out.append(agent)
    return out


def _community_sync_connected_grants(user: dict, rows: list[dict]) -> None:
    """Make the runnable Community roster the authoritative user grant list."""
    if not community_mode():
        return
    uid = int(user["id"])
    connected = [row["id"] for row in rows if row.get("state") == "connected"]
    now_ms = int(time.time() * 1000)
    with _db() as conn:
        conn.execute("DELETE FROM user_agents WHERE user_id=?", (uid,))
        for aid in connected:
            conn.execute(
                "INSERT OR IGNORE INTO user_agents(user_id, agent_id, created_ts) VALUES (?, ?, ?)",
                (uid, aid, now_ms),
            )


_COMMUNITY_DISCOVERY_CACHE_S = 5.0
_COMMUNITY_DISCOVERY_CACHE: dict[int, tuple[float, dict]] = {}
_COMMUNITY_DISCOVERY_INFLIGHT: dict[int, asyncio.Task] = {}
_COMMUNITY_DISCOVERY_GENERATION: dict[int, int] = {}


def _invalidate_community_discovery(user_id: Optional[int] = None) -> None:
    """Expire cached setup scans without cancelling callers already using one."""
    if user_id is None:
        keys = (
            set(_COMMUNITY_DISCOVERY_CACHE)
            | set(_COMMUNITY_DISCOVERY_INFLIGHT)
            | set(_COMMUNITY_DISCOVERY_GENERATION)
        )
        for uid in keys:
            _COMMUNITY_DISCOVERY_GENERATION[uid] = (
                _COMMUNITY_DISCOVERY_GENERATION.get(uid, 0) + 1
            )
        _COMMUNITY_DISCOVERY_CACHE.clear()
        _COMMUNITY_DISCOVERY_INFLIGHT.clear()
        return
    uid = int(user_id)
    _COMMUNITY_DISCOVERY_GENERATION[uid] = (
        _COMMUNITY_DISCOVERY_GENERATION.get(uid, 0) + 1
    )
    _COMMUNITY_DISCOVERY_CACHE.pop(uid, None)
    # Do not cancel an existing scan: another request may already be awaiting it.
    # Removing only the shared reference lets the next request start fresh, while
    # the generation check below prevents the older result from being re-cached.
    _COMMUNITY_DISCOVERY_INFLIGHT.pop(uid, None)


async def _community_agent_discovery_uncached(user: dict) -> dict:
    candidates = _community_discovery_agents_for_user(user)
    checks = await _agent_health_checks(0, {agent["id"] for agent in candidates})
    health = {item["id"]: item for item in checks}
    rows = []
    for agent in candidates:
        aid = agent["id"]
        health_row = health.get(aid) or {}
        live = bool(health_row.get("ok"))
        # Shells out to locate the provider CLI. In a loop over every candidate
        # this stalled the event loop for the whole scan.
        detected = await asyncio.to_thread(_community_provider_detection, aid)
        trusted_live = live and (
            agent.get("source") == "community_connector"
            or detected.get("connectable")
            or detected.get("manual")
        )
        health_error = str(health_row.get("error") or "")
        perplexity_permission_needed = (
            aid == "perplexity"
            and bool(os.environ.get(str(agent.get("token_env") or "")))
            and "accessibility" in health_error.casefold()
        )
        if trusted_live:
            state, detail = "connected", "Connected and ready"
        elif perplexity_permission_needed:
            state, detail = "setup_needed", (
                "Turn on Agent Chat Perplexity Driver in System Settings → "
                "Privacy & Security → Accessibility. Leave python3 off, then choose Verify."
            )
            detected = {**detected, "setup_kind": "perplexity_accessibility"}
        elif detected.get("manual"):
            state, detail = "manual", detected["next"]
        elif detected.get("connectable"):
            state, detail = "found", "Found on this computer — ready to connect"
        elif detected.get("found") and detected.get("setup_kind"):
            state, detail = "setup_needed", detected["next"]
        elif detected.get("found"):
            state, detail = "needs_sign_in", detected["next"]
        else:
            state, detail = "not_found", detected["next"]
        rows.append({
            **_public_agent(agent),
            "id": aid, "name": agent.get("name") or aid.title(), "state": state,
            "detail": detail, "connectable": bool(detected.get("connectable") and not live),
            "setup_kind": str(detected.get("setup_kind") or ""),
        })
    _community_sync_connected_grants(user, rows)
    docker = _community_docker_discovery_rows()
    pick = _pick_onboarding_orchestrator(rows)
    return {
        # Only Community Edition treats this scan as the room roster.
        # CONNECT_SETUP=1 on a supervised install must not flip that switch —
        # hello/auth agents have no `state` field, and the client would filter
        # the whole granted list down to nothing.
        "community": bool(community_mode()), "agents": rows, "docker": docker,
        "orchestrator_pick": pick,
        "ready_count": sum(row["state"] == "connected" for row in rows),
        "found_count": sum(row["state"] in ("connected", "found", "needs_sign_in", "setup_needed") for row in rows),
        "connectable_count": sum(row["connectable"] for row in rows),
        "docker_connectable_count": sum(row["connectable"] for row in docker),
    }


async def _community_agent_discovery(user: dict, *, force: bool = False) -> dict:
    """Return a short-lived per-user scan, sharing one expensive probe fan-out."""
    uid = int(user["id"])
    if force:
        _invalidate_community_discovery(uid)
    generation = _COMMUNITY_DISCOVERY_GENERATION.get(uid, 0)
    now = time.monotonic()
    cached = _COMMUNITY_DISCOVERY_CACHE.get(uid)
    if cached and now - cached[0] < _COMMUNITY_DISCOVERY_CACHE_S:
        return copy.deepcopy(cached[1])
    if cached:
        _COMMUNITY_DISCOVERY_CACHE.pop(uid, None)

    task = _COMMUNITY_DISCOVERY_INFLIGHT.get(uid)
    if task is None:
        task = asyncio.create_task(_community_agent_discovery_uncached(user))
        _COMMUNITY_DISCOVERY_INFLIGHT[uid] = task
    try:
        result = await asyncio.shield(task)
    except BaseException:
        # A failed probe must never poison the next scan. A cancelled waiter does
        # not cancel the shielded shared task, so retain it until another waiter
        # collects it or it actually finishes.
        if task.done() and _COMMUNITY_DISCOVERY_INFLIGHT.get(uid) is task:
            _COMMUNITY_DISCOVERY_INFLIGHT.pop(uid, None)
        raise

    if _COMMUNITY_DISCOVERY_INFLIGHT.get(uid) is task:
        _COMMUNITY_DISCOVERY_INFLIGHT.pop(uid, None)
    if _COMMUNITY_DISCOVERY_GENERATION.get(uid, 0) == generation:
        _COMMUNITY_DISCOVERY_CACHE[uid] = (time.monotonic(), copy.deepcopy(result))
    return copy.deepcopy(result)


# Desktop agents that make a strong first conductor. Availability is the first
# decision: a connected or directly connectable local agent must beat a generic
# connector that still needs credentials. Rank only breaks ties inside the same
# readiness tier.
_ONBOARDING_ORCH_RANK = {
    "claude": 100, "codex": 95, "minimax": 90, "grok": 84,
    "perplexity": 82, "antigravity": 68, "openrouter": 62, "hermes": 58,
}
_ONBOARDING_ORCH_WHY = {
    "claude": "Deep reasoning and careful setup — the strongest first conductor.",
    "minimax": "Built to coordinate a room and keep a long setup moving.",
    "grok": "Fast, current, and honest when a plan needs pressure.",
    "perplexity": "Signed-in desktop research with sources, files, and Mac apps.",
    "openrouter": "Free Models Router by default, with the complete free text-model catalog.",
    "codex": "Signed-in on this computer and ready for hands-on setup and building.",
    "antigravity": "Strong on interface work and Google-side setup.",
    "hermes": "A specialist you can shape around your company.",
}
_ONBOARDING_ORCH_STATE_BOOST = {
    "connected": 300, "found": 200, "setup_needed": 100,
    "needs_sign_in": 80, "manual": 20, "not_found": 0,
}


def _pick_onboarding_orchestrator(rows: list) -> Optional[dict]:
    """Return the best first orchestrator from a discovery roster."""
    desktop_ids = {"claude", "codex", "minimax", "grok", "perplexity", "antigravity"}
    has_desktop_candidate = any(
        isinstance(row, dict)
        and str(row.get("id") or "") in desktop_ids
        and (
            str(row.get("state") or "") in {"connected", "found"}
            or bool(row.get("connectable"))
        )
        for row in (rows or [])
    )
    best = None
    best_score = -10**9
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        aid = str(row.get("id") or "").strip()
        if not aid:
            continue
        state = str(row.get("state") or "")
        connectable = bool(row.get("connectable"))
        if state == "not_found" and not connectable:
            continue
        # OpenRouter remains a useful optional provider/fallback, but it has no
        # desktop setup tools. Never let its already-connected state outrank a
        # real local conductor that can finish first-run setup.
        if aid == "openrouter" and has_desktop_candidate:
            continue
        if (
            aid == "openrouter"
            and not connectable
            and str(row.get("setup_kind") or "") == "openrouter_api_key"
        ):
            continue
        score = _ONBOARDING_ORCH_RANK.get(aid, 40) + _ONBOARDING_ORCH_STATE_BOOST.get(state, 0)
        if score > best_score:
            best, best_score = row, score
    if not best:
        return None
    aid = str(best.get("id") or "")
    return {
        "id": aid,
        "name": best.get("name") or aid.title(),
        "state": best.get("state") or "",
        "detail": best.get("detail") or "",
        "connectable": bool(best.get("connectable")),
        "setup_kind": best.get("setup_kind") or "",
        "why": _ONBOARDING_ORCH_WHY.get(aid, "A capable local teammate to run the room."),
        "persona_url": best.get("persona_url") or "",
        "icon_url": best.get("icon_url") or "",
        "color": best.get("color") or "#33c374",
    }


def _is_auth_failure_text(text: str) -> bool:
    blob = (text or "").lower()
    return any(
        needle in blob
        for needle in (
            "oauth", "authenticat", "could not be refreshed",
            "sign in", "login expired", "not logged in",
        )
    )


_CLAUDE_AUTH_CACHE: dict = {"ts": 0.0, "ok": False}
_AGENT_REAUTH: dict[str, dict] = {}
_AGENT_REAUTH_TTL_S = 15 * 60
_REAUTH_URL_RE = re.compile(
    r"https://[a-z0-9.-]+\.(?:claude\.com|openai\.com|chatgpt\.com|x\.ai|anthropic\.com)"
    r"/[^\s\x1b\"'<>]+",
    re.I,
)


def _claude_cli_signed_in(*, force: bool = False) -> bool:
    """True when a long-lived token or a live CLI login can still be used."""
    if (os.environ.get("CLAUDE_CODE_OAUTH_TOKEN") or "").strip():
        return True
    now = time.time()
    if not force and now - float(_CLAUDE_AUTH_CACHE.get("ts") or 0) < 20:
        return bool(_CLAUDE_AUTH_CACHE.get("ok"))
    home = Path.home()
    bundled = sorted(
        (home / "Library" / "Application Support" / "Claude" / "claude-code").glob(
            "*/claude.app/Contents/MacOS/claude"
        ), reverse=True,
    )
    cli = _first_existing_path([
        os.environ.get("CLAUDE_BIN"), *bundled,
        home / ".local" / "bin" / "claude",
        shutil.which("claude"), shutil.which("claude.exe"),
    ])
    ok = False
    if cli:
        try:
            env = dict(os.environ)
            for key in ("ANTHROPIC_API_KEY", "ANTHROPIC_BASE_URL",
                        "USE_STAGING_OAUTH", "USE_LOCAL_OAUTH"):
                env.pop(key, None)
            out = subprocess.run(
                [str(cli), "auth", "status"],
                capture_output=True, text=True, timeout=20, env=env,
            ).stdout
            data = json.loads(out or "{}")
            ok = bool(data.get("loggedIn"))
        except Exception:
            ok = False
    _CLAUDE_AUTH_CACHE["ts"] = now
    _CLAUDE_AUTH_CACHE["ok"] = ok
    return ok


def _agent_reauth_recipe(agent: dict) -> dict:
    """How this agent signs back in. Works for built-ins and user-added connectors."""
    aid = str(agent.get("id") or "")
    name = str(agent.get("name") or aid or "This agent")
    source = str(agent.get("source") or "")
    token_env = str(agent.get("token_env") or "")
    if aid == "claude":
        return {
            "kind": "cli_oauth", "name": name, "agent_id": aid,
            "title": f"{name} needs you to sign in again",
            "detail": "Open the link, authorize, then paste the code here. You stay in this chat. This mints a longer-lived login so it does not die every month.",
            "code_needed": True, "confirm": False,
            "cli_mode": "setup-token",
        }
    if aid == "codex":
        return {
            "kind": "cli_login", "name": name, "agent_id": aid,
            "title": f"{name} needs you to sign in again",
            "detail": "I will start the Codex login. Approve it in the browser, then tap I signed in.",
            "code_needed": False, "confirm": True, "cli_mode": "login",
        }
    if aid == "grok":
        return {
            "kind": "cli_login", "name": name, "agent_id": aid,
            "title": f"{name} needs you to sign in again",
            "detail": "I will start the Grok login. Finish it, then tap I signed in.",
            "code_needed": False, "confirm": True, "cli_mode": "login",
        }
    if aid == "antigravity":
        return {
            "kind": "cli_login", "name": name, "agent_id": aid,
            "title": f"{name} needs you to sign in again",
            "detail": "Sign into Antigravity on this computer, then tap I signed in.",
            "code_needed": False, "confirm": True, "cli_mode": "login",
        }
    if aid == "minimax":
        return {
            "kind": "desktop_app", "name": name, "agent_id": aid,
            "title": f"{name} needs you to sign in again",
            "detail": "Open MiniMax Code on this computer and sign in. Then tap I signed in — I will check.",
            "code_needed": False, "confirm": True,
        }
    if aid == "openrouter":
        return {
            "kind": "api_key", "name": name, "agent_id": aid,
            "title": "OpenRouter needs a fresh API key",
            "detail": "Paste an OpenRouter API key. It stays on this computer and is never sent to the browser or other agents.",
            "code_needed": False, "confirm": False, "secret": True,
            "token_env": "OPENROUTER_API_KEY",
        }
    if source == "community_connector" or token_env or agent.get("managed_adapter"):
        if token_env or agent.get("upstream_token") is not None or agent.get("token"):
            return {
                "kind": "api_key", "name": name, "agent_id": aid,
                "title": f"{name} needs a fresh local key",
                "detail": "Paste the local API key or token for this agent. It stays on this computer.",
                "code_needed": False, "confirm": False, "secret": True,
                "token_env": token_env,
            }
        return {
            "kind": "confirm", "name": name, "agent_id": aid,
            "title": f"{name} needs to come back online",
            "detail": "Start that local agent, then tap I signed in. I will check from here.",
            "code_needed": False, "confirm": True,
        }
    return {
        "kind": "confirm", "name": name, "agent_id": aid,
        "title": f"{name} needs you to sign in again",
        "detail": "Sign this agent in on this computer, then tap I signed in.",
        "code_needed": False, "confirm": True,
    }


def _reauth_public(session: dict) -> dict:
    return {
        "session_id": session.get("id"),
        "agent_id": session.get("agent_id"),
        "name": session.get("name"),
        "kind": session.get("kind"),
        "title": session.get("title"),
        "detail": session.get("detail"),
        "code_needed": bool(session.get("code_needed")),
        "confirm": bool(session.get("confirm")),
        "secret": bool(session.get("secret")),
        "authorize_url": session.get("authorize_url") or "",
        "stage": session.get("stage") or "starting",
        "ready": bool(session.get("ready")),
        "error": session.get("error") or "",
    }


def _reauth_gc() -> None:
    now = time.time()
    for sid, session in list(_AGENT_REAUTH.items()):
        if now - float(session.get("created") or 0) > _AGENT_REAUTH_TTL_S:
            _reauth_stop(session)
            _AGENT_REAUTH.pop(sid, None)


def _reauth_stop(session: Optional[dict]) -> None:
    if not session:
        return
    proc = session.get("proc")
    if proc is not None:
        try:
            proc.terminate()
        except Exception:
            pass
    pid = session.get("pid")
    if pid:
        try:
            if sys.platform == "win32":
                subprocess.run(
                    ["taskkill", "/PID", str(int(pid)), "/T", "/F"],
                    capture_output=True, timeout=4, check=False,
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                )
            else:
                os.kill(int(pid), signal.SIGTERM)
        except (OSError, ProcessLookupError, TypeError, ValueError, subprocess.SubprocessError):
            pass
    tmp = session.get("tmpdir")
    if tmp:
        shutil.rmtree(str(tmp), ignore_errors=True)


def _cli_login_status_ok(agent_id: str) -> bool:
    detected = _community_provider_detection(agent_id)
    raw = detected.get("path")
    if not raw:
        return False
    try:
        probe = subprocess.run(
            _cli_probe_command(Path(raw), ("login", "status")),
            capture_output=True, text=True, timeout=8, check=False,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        return probe.returncode == 0
    except (OSError, subprocess.SubprocessError):
        return False


def _wait_local_bridge(agent: dict, timeout: float = 8.0) -> bool:
    parsed = urlparse(str(agent.get("url") or ""))
    if not parsed.hostname or not parsed.port:
        return False
    deadline = time.time() + timeout
    while time.time() < deadline:
        try:
            with socket.create_connection((parsed.hostname, parsed.port), timeout=0.4):
                return True
        except OSError:
            time.sleep(0.25)
    return False


def _reauth_cli_argv(agent: dict, recipe: dict) -> Optional[list[str]]:
    aid = str(agent.get("id") or "")
    detected = _community_provider_detection(aid) if aid in (
        "claude", "codex", "grok", "antigravity"
    ) else {}
    cli = detected.get("path")
    if not cli:
        return None
    path = Path(str(cli))
    mode = recipe.get("cli_mode") or "login"
    if aid == "claude" and mode == "setup-token":
        return _cli_probe_command(path, ("setup-token",))
    if aid == "claude":
        return _cli_probe_command(path, ("auth", "login"))
    if aid == "codex":
        return _cli_probe_command(path, ("login",))
    if aid == "grok":
        return _cli_probe_command(path, ("login",))
    if aid == "antigravity":
        return _cli_probe_command(path, ("login",))
    return _cli_probe_command(path, ("login",))


def _reauth_cli_worker_windows(session: dict, argv: list[str]) -> None:
    """Start vendor login in a visible console and poll until it is signed in."""
    env = dict(os.environ)
    env["BROWSER"] = "true"
    flags = getattr(subprocess, "CREATE_NEW_CONSOLE", 0) | getattr(
        subprocess, "CREATE_NEW_PROCESS_GROUP", 0
    )
    try:
        proc = subprocess.Popen(argv, env=env, creationflags=flags)
    except Exception as exc:
        session["stage"] = "error"
        session["error"] = "Could not start the sign-in helper."
        logger.warning("reauth windows spawn failed: %s", exc)
        return
    session["pid"] = proc.pid
    session["proc"] = proc
    session["stage"] = "waiting_confirm"
    session["confirm"] = True
    session["detail"] = (
        "A sign-in window should have opened. Finish it in the browser, then tap I signed in."
    )
    aid = str(session.get("agent_id") or "")
    deadline = time.time() + 600
    while time.time() < deadline and not session.get("cancel"):
        if aid and _cli_login_status_ok(aid):
            session["ready"] = True
            session["stage"] = "ready"
            session["error"] = ""
            break
        if proc.poll() is not None:
            if aid and _cli_login_status_ok(aid):
                session["ready"] = True
                session["stage"] = "ready"
                session["error"] = ""
            else:
                session["stage"] = "waiting_confirm"
                session["confirm"] = True
                session["detail"] = "Finish the sign-in, then tap I signed in."
            break
        time.sleep(1.5)
    if session.get("ready"):
        agent = AGENTS_BY_ID.get(aid)
        if agent:
            try:
                _community_restart_bridge(agent)
            except Exception:
                logger.exception("reauth restart after windows login")


def _reauth_cli_worker(session: dict, argv: list[str]) -> None:
    """Drive a vendor CLI login. Never prints tokens."""
    if sys.platform == "win32":
        _reauth_cli_worker_windows(session, argv)
        return
    try:
        import fcntl
        import pty as pty_mod
        import select as select_mod
        import termios
    except ImportError:
        session["stage"] = "waiting_confirm"
        session["confirm"] = True
        session["code_needed"] = False
        session["detail"] = (
            "Open a terminal on this computer and finish the sign-in, then tap I signed in."
        )
        return
    env = dict(os.environ)
    for key in ("ANTHROPIC_API_KEY", "ANTHROPIC_BASE_URL",
                "USE_STAGING_OAUTH", "USE_LOCAL_OAUTH"):
        env.pop(key, None)
    if session.get("cli_mode") == "setup-token":
        env.pop("CLAUDE_CODE_OAUTH_TOKEN", None)
    env["BROWSER"] = "true"
    env["TERM"] = env.get("TERM") or "xterm-256color"
    env["COLUMNS"] = "4000"
    cli = argv[0]
    try:
        pid, fd = pty_mod.fork()
    except Exception as exc:
        session["stage"] = "error"
        session["error"] = "Could not start the sign-in helper."
        logger.warning("reauth pty fork failed: %s", exc)
        return
    if pid == 0:
        os.environ.clear()
        os.environ.update(env)
        os.execv(cli, argv)
        os._exit(127)
    session["pid"] = pid
    try:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", 100, 4000, 0, 0))
    except Exception:
        pass
    buf = b""
    url = ""
    url_at = 0.0
    url_ready = False
    code_sent = False
    enter_due = 0.0
    token = ""
    deadline = time.time() + 600
    ansi = re.compile(rb"\x1b\[[0-9;?]*[a-zA-Z]")
    token_re = re.compile(rb"sk-ant-[A-Za-z0-9_\-]{20,}")
    code_path = Path(session["code_file"])
    try:
        while time.time() < deadline and not session.get("cancel"):
            ready, _, _ = select_mod.select([fd], [], [], 0.4)
            if fd in ready:
                try:
                    chunk = os.read(fd, 4096)
                except OSError:
                    chunk = b""
                if not chunk:
                    break
                buf += chunk
                clean = ansi.sub(b"", buf)
                match = _REAUTH_URL_RE.search(clean.decode("utf-8", "replace"))
                if match and match.group(0) != url:
                    url = match.group(0).rstrip(").,;\"'")
                    url_at = time.time()
                tok_m = token_re.search(clean)
                if tok_m:
                    token = tok_m.group(0).decode()
                if b"Login successful" in clean or b"Logged in" in clean:
                    session["ready"] = True
                    session["stage"] = "ready"
                    break
            if url and not url_ready and time.time() - url_at > 0.8:
                url_ready = True
                session["authorize_url"] = url
                session["stage"] = "waiting_code" if session.get("code_needed") else "waiting_confirm"
            if url_ready and session.get("code_needed") and not code_sent and code_path.is_file():
                code = code_path.read_text(encoding="utf-8").strip()
                if code:
                    os.write(fd, code.encode())
                    code_sent = True
                    enter_due = time.time() + 0.5
                    session["stage"] = "checking"
            if code_sent and enter_due and time.time() >= enter_due:
                os.write(fd, b"\r")
                enter_due = 0.0
            if token and session.get("cli_mode") == "setup-token":
                session["token"] = token
                session["ready"] = True
                session["stage"] = "ready"
                break
            try:
                waited, _st = os.waitpid(pid, os.WNOHANG)
                if waited == pid:
                    break
            except ChildProcessError:
                break
    finally:
        try:
            os.kill(pid, signal.SIGTERM)
        except (OSError, ProcessLookupError):
            pass
        try:
            os.close(fd)
        except OSError:
            pass
    if token and session.get("cli_mode") == "setup-token":
        try:
            _community_write_env({"CLAUDE_CODE_OAUTH_TOKEN": token})
        except Exception:
            logger.exception("reauth could not store Claude token")
        session.pop("token", None)
    if session.get("ready"):
        _CLAUDE_AUTH_CACHE["ts"] = 0.0
        _CLAUDE_AUTH_CACHE["ok"] = True
        session["stage"] = "ready"
        session["error"] = ""
    elif not session.get("error"):
        session["stage"] = "waiting_confirm"
        session["confirm"] = True
        session["detail"] = (
            session.get("detail")
            or "Finish the sign-in, then tap I signed in."
        )


def _start_agent_reauth(agent: dict, *, launch_cli: bool = True) -> dict:
    _reauth_gc()
    recipe = _agent_reauth_recipe(agent)
    sid = secrets.token_urlsafe(12)
    tmp = Path(tempfile.mkdtemp(prefix="agent-reauth-"))
    session = {
        **recipe,
        "id": sid,
        "created": time.time(),
        "stage": "starting",
        "ready": False,
        "error": "",
        "authorize_url": "",
        "tmpdir": str(tmp),
        "code_file": str(tmp / "code.txt"),
        "pid": None,
        "cancel": False,
        "launch_cli": launch_cli,
    }
    _AGENT_REAUTH[sid] = session
    if recipe["kind"] in ("cli_oauth", "cli_login") and session.get("launch_cli", True):
        argv = _reauth_cli_argv(agent, recipe)
        if argv:
            thread = threading.Thread(
                target=_reauth_cli_worker, args=(session, argv), daemon=True,
            )
            thread.start()
            session["stage"] = "waiting_url" if recipe.get("code_needed") else "waiting_confirm"
        else:
            session["kind"] = "confirm"
            session["confirm"] = True
            session["code_needed"] = False
            session["stage"] = "waiting_confirm"
            session["detail"] = (
                f"{recipe['name']} is installed as a desktop login. "
                "Sign it in there, then tap I signed in."
            )
    else:
        session["stage"] = "waiting_confirm" if recipe.get("confirm") or recipe.get("secret") else "starting"
        if recipe.get("secret"):
            session["stage"] = "waiting_secret"
    return session


def _community_restart_bridge(agent: dict) -> tuple[bool, str]:
    aid = str(agent.get("id") or "")
    proc = _COMMUNITY_BRIDGE_PROCESSES.get(aid)
    if proc and proc.poll() is None:
        try:
            proc.terminate()
            proc.wait(timeout=3)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass
        _COMMUNITY_BRIDGE_PROCESSES.pop(aid, None)
    return _community_launch_bridge(agent)


async def _reauth_probe_ready(agent: dict) -> tuple[bool, str]:
    aid = str(agent.get("id") or "")
    if aid == "claude":
        if await asyncio.to_thread(_claude_cli_signed_in, force=True):
            try:
                await asyncio.to_thread(_community_restart_bridge, agent)
            except Exception:
                logger.exception("reauth restart claude bridge")
            return True, f"{agent.get('name') or 'Claude'} is signed in."
        return False, "Still signed out. Finish the login, then tap again."
    if aid == "minimax":
        detected = await asyncio.to_thread(_community_provider_detection, "minimax")
        if detected.get("found"):
            return True, "MiniMax is signed in."
        return False, "Open MiniMax Code and sign in, then tap again."
    if aid == "grok":
        detected = await asyncio.to_thread(_community_provider_detection, "grok")
        if detected.get("connectable") or detected.get("found"):
            signed = bool(
                os.environ.get("GROK_DEPLOYMENT_KEY")
                or (Path.home() / ".grok" / "auth.json").is_file()
            )
            if signed:
                return True, "Grok is signed in."
        return False, "Finish grok login, then tap again."
    if aid == "codex":
        if not await asyncio.to_thread(_cli_login_status_ok, "codex"):
            return False, "Still signed out. Finish the Codex login window, then tap I signed in."
        try:
            started, detail = await asyncio.to_thread(_community_restart_bridge, agent)
        except Exception:
            logger.exception("reauth restart codex bridge")
            started, detail = False, "Could not restart Codex."
        if not started:
            return False, detail or "Could not start the Codex connection."
        if not await asyncio.to_thread(_wait_local_bridge, agent, 10):
            return False, "Codex is signed in, but the local connection did not come up. Tap I signed in again."
    try:
        _AGENT_HEALTH_CACHE.clear()
        checks = await _agent_health_checks(0, {aid})
        row = next((item for item in checks if item.get("id") == aid), None)
        if row and row.get("ok"):
            return True, f"{agent.get('name') or aid} is back."
        if row and row.get("error"):
            return False, str(row["error"])
    except Exception:
        logger.exception("reauth health probe failed for %s", aid)
    return False, "Not ready yet. Finish the sign-in, then tap again."


def _is_onboarding_guide_cid(cid) -> bool:
    chat = (CHAT_INDEX.get("chats") or {}).get(str(cid)) or {}
    return (chat.get("skill_name") or "") == "__onboarding_guide__" or (
        chat.get("title") or ""
    ) == ONBOARDING_GUIDE_TITLE


def _last_user_text(cid: int) -> str:
    """The most recent user message that actually carries text.

    Blank user turns are skipped, not returned: an attachment-only or voice
    message lands as a user row with empty text, and stopping there would hand
    model pinning, skill detection, and per-agent assignment an empty prompt
    instead of what the user actually asked for."""
    for msg in reversed(_load_thread(cid) or []):
        if msg.get("role") == "user" and str(msg.get("text") or "").strip():
            return str(msg.get("text") or "").strip()
    return ""


def _onboarding_failover_agent(failed_id: str, skip_ids=None) -> Optional[dict]:
    rows = []
    skip = {str(failed_id or ""), *(str(x) for x in (skip_ids or []))}
    for agent in (community_agents() if community_mode() else AGENTS):
        aid = str(agent.get("id") or "")
        if not aid or aid in skip:
            continue
        token = os.environ.get(str(agent.get("token_env") or "")) or agent.get("token")
        if not token:
            continue
        rows.append(agent)
    rows.sort(key=lambda a: -int(_ONBOARDING_ORCH_RANK.get(a.get("id"), 40)))
    return rows[0] if rows else None


def _onboarding_guide_setting_key(user_id: int) -> str:
    return f"onboarding_guide_chat:{int(user_id)}"


def _is_onboarding_guide_chat(cid: int) -> bool:
    """True only for the owner-scoped chat created as the setup conductor.

    This server-owned marker is the authority for the guide's elevated setup
    contract. Model text and ordinary user-created chats can never opt into it.
    """
    try:
        chat_id = int(cid)
        chat = (CHAT_INDEX.get("chats") or {}).get(str(chat_id)) or {}
        owner_id = int(chat.get("owner_user_id") or 0)
    except (TypeError, ValueError):
        return False
    mapped = (
        _get_setting(_onboarding_guide_setting_key(owner_id), "").strip()
        if owner_id > 0 else ""
    )
    return bool(
        owner_id > 0
        and mapped == str(chat_id)
        and _is_onboarding_guide_cid(chat_id)
        and not chat.get("archived")
        and not chat.get("deleted_ts")
    )


def _onboarding_first_ask_message(thread: list[dict]) -> tuple[Optional[int], Optional[dict]]:
    """Locate the one private first-ask row without exposing it as authored chat."""
    for index, message in enumerate(thread or []):
        metadata = message.get("metadata") or {}
        if message.get("role") != "user":
            continue
        text = str(message.get("text") or "").strip()
        if (
            metadata.get("kind") == "onboarding_first_ask"
            or text == ONBOARDING_FIRST_ASK
            or text.startswith("I'm here. Introduce yourself in two short sentences")
        ):
            return index, message
    return None, None


def _onboarding_first_turn_thread_state(
    cid: int, orch_id: str = "", *, thread: Optional[list[dict]] = None,
) -> dict:
    """Reconstruct the durable first-turn state from the hidden ask and reply.

    The stored thread survives a process restart while in-memory task registries
    do not.  A private ask with no matching reply is therefore an orphan unless
    the live working snapshot proves that a task still owns it.
    """
    messages = list(thread if thread is not None else (_load_thread(int(cid)) or []))
    ask_index, ask = _onboarding_first_ask_message(messages)
    metadata = dict((ask or {}).get("metadata") or {})
    expected = str(orch_id or "").strip()
    reply = None
    if ask_index is not None:
        for message in messages[ask_index + 1:]:
            if message.get("role") not in ("agent", "assistant"):
                continue
            if not str(message.get("text") or "").strip():
                continue
            agent_id = str(message.get("agent_id") or "").strip()
            if expected and agent_id and agent_id != expected:
                continue
            reply = message
            break
    try:
        attempt = max(0, int(metadata.get("onboarding_first_turn_attempt") or 0))
    except (TypeError, ValueError):
        attempt = 0
    return {
        "ask": ask,
        "reply": reply,
        "attempt": attempt or (1 if ask is not None else 0),
        "turn_id": str(metadata.get("onboarding_first_turn_id") or ""),
        "stored_status": str(metadata.get("onboarding_first_turn_status") or ""),
        "error": str(metadata.get("onboarding_first_turn_error") or "").strip(),
    }


def _update_onboarding_internal_message(
    cid: int, message: dict, *, text: Optional[str] = None, metadata: dict,
) -> bool:
    """Durably migrate one known onboarding row without touching other messages.

    `ts` is not unique (the control note and first ask can share a millisecond),
    so the original role and text are part of the lookup. SQLite is authoritative;
    the disaster-recovery mirror can be repaired again on the next guide open.
    """
    try:
        with _db() as conn:
            row = conn.execute(
                "SELECT id, metadata_json FROM messages "
                "WHERE chat_id=? AND ts=? AND role=? AND text=? "
                "ORDER BY id DESC LIMIT 1",
                (
                    int(cid), int(message.get("ts") or 0),
                    str(message.get("role") or "system"),
                    str(message.get("text") or ""),
                ),
            ).fetchone()
            if not row:
                return False
            try:
                stored = json.loads(row["metadata_json"] or "{}")
                stored = stored if isinstance(stored, dict) else {}
            except json.JSONDecodeError:
                stored = {}
            stored.update(metadata)
            conn.execute(
                "UPDATE messages SET text=?, metadata_json=? WHERE id=?",
                (
                    str(message.get("text") or "") if text is None else str(text),
                    json.dumps(stored),
                    int(row["id"]),
                ),
            )
        return True
    except Exception:
        logger.exception("onboarding internal message migration failed chat=%s", cid)
        return False


def _mark_legacy_onboarding_first_ask(cid: int) -> bool:
    """Tag an exact/generated legacy first ask so ordinary chat can hide it."""
    found = False
    for message in _load_thread(int(cid)) or []:
        metadata = message.get("metadata") or {}
        if metadata.get("kind") == "onboarding_first_ask":
            found = True
            continue
        text = str(message.get("text") or "")
        if (
            message.get("role") == "user"
            and text.startswith("I'm here. Introduce yourself in two short sentences")
        ):
            found = _update_onboarding_internal_message(
                cid,
                message,
                metadata={
                    "kind": "onboarding_first_ask",
                    "version": ONBOARDING_INTERNAL_MESSAGE_VERSION,
                },
            ) or found
    return found


def _ensure_onboarding_control_message(cid: int) -> bool:
    """Upgrade the one stored control note to the current context-free contract."""
    thread = _load_thread(int(cid)) or []
    control = next(
        (
            message for message in thread
            if message.get("role") == "system"
            and (message.get("metadata") or {}).get("kind") == "onboarding_control"
        ),
        None,
    )
    if control is None:
        control = next(
            (
                message for message in thread
                if message.get("role") == "system"
                and "you own and run the entire onboarding process end to end"
                in str(message.get("text") or "")
            ),
            None,
        )
    if control is None:
        return False
    metadata = control.get("metadata") or {}
    if (
        control.get("text") == ONBOARDING_CONTROL_NOTE
        and metadata.get("kind") == "onboarding_control"
        and metadata.get("version") == ONBOARDING_INTERNAL_MESSAGE_VERSION
    ):
        return True
    return _update_onboarding_internal_message(
        cid,
        control,
        text=ONBOARDING_CONTROL_NOTE,
        metadata={
            "kind": "onboarding_control",
            "version": ONBOARDING_INTERNAL_MESSAGE_VERSION,
        },
    )


def _onboarding_guide_reservation_live(reservation: Optional[dict]) -> bool:
    task = (reservation or {}).get("task")
    return bool(task is not None and not task.done())


def _release_onboarding_guide_reservation(
    cid: int, token: str, owner_task: Optional[asyncio.Task] = None,
) -> bool:
    """Release only the reservation still owned by this request/route task."""
    current = _ONB_GUIDE_RESERVATIONS.get(int(cid))
    if not current or str(current.get("token") or "") != str(token or ""):
        return False
    if owner_task is not None and current.get("task") is not owner_task:
        return False
    _ONB_GUIDE_RESERVATIONS.pop(int(cid), None)
    return True


def _onboarding_guide_working_state(
    cid: int, *, live_rows: Optional[list[dict]] = None,
) -> dict:
    """One authoritative guide-work snapshot for hydrate and 409 responses."""
    chat_id = int(cid)
    reservation = _ONB_GUIDE_RESERVATIONS.get(chat_id)
    if reservation and not _onboarding_guide_reservation_live(reservation):
        _release_onboarding_guide_reservation(
            chat_id, str(reservation.get("token") or ""), reservation.get("task"),
        )
        reservation = None
    running = list(_working_for_chat(chat_id) if live_rows is None else live_rows)
    if running:
        preferred_turn = str((reservation or {}).get("turn_id") or "")
        preferred_agent = str((reservation or {}).get("agent_id") or "")
        row = next(
            (
                item for item in running
                if preferred_turn and str(item.get("turn_id") or "") == preferred_turn
            ),
            None,
        ) or next(
            (
                item for item in running
                if preferred_agent and str(item.get("agent_id") or "") == preferred_agent
            ),
            running[0],
        )
        return {
            "active": True,
            "agent_id": row.get("agent_id") or (reservation or {}).get("agent_id"),
            "turn_id": row.get("turn_id") or (reservation or {}).get("turn_id"),
            "started_ts": row.get("started_ts") or (reservation or {}).get("started_ts"),
            "source": "running_task",
            "first_turn": bool((reservation or {}).get("first_turn")),
            "retrying": bool((reservation or {}).get("retrying")),
        }
    if reservation and _onboarding_guide_reservation_live(reservation):
        return {
            "active": True,
            "agent_id": reservation.get("agent_id") or None,
            "turn_id": reservation.get("turn_id") or None,
            "started_ts": reservation.get("started_ts"),
            "source": "reservation",
            "first_turn": bool(reservation.get("first_turn")),
            "retrying": bool(reservation.get("retrying")),
        }
    return {
        "active": False,
        "agent_id": None,
        "turn_id": None,
        "started_ts": None,
        "source": None,
        "first_turn": False,
        "retrying": False,
    }


def _onboarding_first_turn_public(
    cid: int, orch_id: str, working: dict, *, thread: Optional[list[dict]] = None,
) -> dict:
    state = _onboarding_first_turn_thread_state(cid, orch_id, thread=thread)
    ask = state["ask"]
    reply = state["reply"]
    working_turn_id = str(working.get("turn_id") or "")
    owns_live_first_turn = bool(
        working.get("active")
        and (
            working.get("first_turn")
            or (
                state["turn_id"]
                and working_turn_id
                and state["turn_id"] == working_turn_id
            )
        )
    )
    if owns_live_first_turn:
        status = "retrying" if working.get("retrying") else "working"
    # Completion belongs to the durable guide-chat milestone, not whichever
    # conductor is selected later. The finalizer writes this state only after
    # verifying the reply against the attempt's owning agent. Re-filtering that
    # reply against a newly selected conductor would turn a completed welcome
    # into a false orphan when the owner uses Back to switch seats.
    elif state["stored_status"] == "complete":
        status = "complete"
    elif reply is not None:
        status = "complete"
    elif ask is None:
        status = "not_started"
    elif state["stored_status"] == "failed":
        status = "failed"
    else:
        status = "orphaned"
    return {
        "first_turn_status": status,
        "first_turn_attempt": int(state["attempt"]),
        "first_turn_error": state["error"] or None,
        "first_turn_retryable": status in {"failed", "orphaned"},
    }


def _onboarding_guide_status_payload(
    cid: int, orch_id: str, *, thread: Optional[list[dict]] = None,
    working: Optional[dict] = None,
) -> dict:
    working_state = dict(working or _onboarding_guide_working_state(cid))
    return {
        "guide_working": bool(working_state.get("active")),
        "working": working_state,
        "working_agent_id": working_state.get("agent_id") or None,
        "working_turn_id": working_state.get("turn_id") or None,
        **_onboarding_first_turn_public(
            int(cid), str(orch_id or ""), working_state, thread=thread,
        ),
    }


async def _reserve_onboarding_guide_send(
    cid: int, turn_id: str, agent_id: str,
) -> tuple[Optional[dict], Optional[dict]]:
    """Atomically admit one guide send across every tab and request."""
    chat_id = int(cid)
    async with _ONB_GUIDE_ADMISSION_LOCK:
        current = _ONB_GUIDE_RESERVATIONS.get(chat_id)
        if current and not _onboarding_guide_reservation_live(current):
            _ONB_GUIDE_RESERVATIONS.pop(chat_id, None)
            current = None
        running = _working_for_chat(chat_id)
        if current or running:
            return None, _onboarding_guide_working_state(
                chat_id, live_rows=running,
            )
        owner_task = asyncio.current_task()
        if owner_task is None:
            return None, _onboarding_guide_working_state(chat_id, live_rows=[])
        reservation = {
            "token": uuid.uuid4().hex,
            "task": owner_task,
            "chat_id": chat_id,
            "agent_id": str(agent_id or "") or None,
            "turn_id": str(turn_id or "") or None,
            "started_ts": int(time.time() * 1000),
            "first_turn": False,
            "retrying": False,
        }
        _ONB_GUIDE_RESERVATIONS[chat_id] = reservation

        def _release_request(done: asyncio.Task, *, token=reservation["token"]):
            _release_onboarding_guide_reservation(chat_id, token, done)

        owner_task.add_done_callback(_release_request)
        return reservation, None


def _transfer_onboarding_guide_reservation(
    reservation: dict, task: asyncio.Task, *, agent_id: str,
    first_turn: bool, retrying: bool,
) -> bool:
    cid = int(reservation.get("chat_id") or 0)
    current = _ONB_GUIDE_RESERVATIONS.get(cid)
    if current is not reservation:
        return False
    reservation.update({
        "task": task,
        "agent_id": str(agent_id or "") or None,
        "first_turn": bool(first_turn),
        "retrying": bool(retrying),
    })

    def _release_route(done: asyncio.Task, *, token=reservation["token"]):
        _release_onboarding_guide_reservation(cid, token, done)

    task.add_done_callback(_release_route)
    return True


def _prepare_onboarding_first_ask(
    cid: int, turn_id: str, principal: str,
) -> tuple[dict, bool]:
    """Tag a new first ask, or reuse an orphan row for an idempotent retry."""
    state = _onboarding_first_turn_thread_state(cid)
    ask = state["ask"]
    retrying = ask is not None
    attempt = int(state["attempt"] or 0) + 1
    metadata = {
        "kind": "onboarding_first_ask",
        "version": ONBOARDING_INTERNAL_MESSAGE_VERSION,
        "onboarding_first_turn_status": "working",
        "onboarding_first_turn_id": str(turn_id or ""),
        "onboarding_first_turn_attempt": attempt,
        "onboarding_first_turn_error": None,
    }
    if ask is None:
        entry = append_thread(
            int(cid), "user", None, principal, ONBOARDING_FIRST_ASK,
            metadata=metadata,
        )
        return entry, False
    _update_onboarding_internal_message(int(cid), ask, metadata=metadata)
    entry = dict(ask)
    entry["metadata"] = {**dict(ask.get("metadata") or {}), **metadata}
    return entry, True


def _finalize_onboarding_first_turn(cid: int, turn_id: str, orch_id: str) -> None:
    """Persist terminal truth only for the first-turn attempt that just ended."""
    thread = _load_thread(int(cid)) or []
    state = _onboarding_first_turn_thread_state(cid, orch_id, thread=thread)
    ask = state["ask"]
    if ask is None or state["turn_id"] != str(turn_id or ""):
        return
    if state["reply"] is not None:
        status, error = "complete", None
    else:
        status = "failed"
        error = "The orchestrator did not produce a setup reply. Try again."
        ask_index, _ = _onboarding_first_ask_message(thread)
        after_ask = thread[(ask_index + 1 if ask_index is not None else len(thread)):]
        for message in reversed(after_ask):
            if message.get("role") != "system":
                continue
            text = " ".join(str(message.get("text") or "").split())
            if "sign in again" in text.lower():
                error = "The orchestrator needs you to sign in again before retrying."
                break
            if "was stopped" in text.lower():
                error = "The setup reply was stopped. Try again when you are ready."
                break
            if "timed out" in text.lower() or "working past" in text.lower():
                error = "The setup reply timed out. Try again."
                break
    _update_onboarding_internal_message(
        int(cid), ask,
        metadata={
            "onboarding_first_turn_status": status,
            "onboarding_first_turn_error": error,
        },
    )


async def _run_reserved_onboarding_guide_turn(
    reservation: dict,
    cid: int,
    target_ids: list[str],
    mode: str,
    *,
    lead_id: Optional[str],
    assignments: Optional[dict[str, str]],
    live_roster: bool,
) -> None:
    """Hold guide admission until routing and RUNNING_TASKS cleanup both finish."""
    try:
        await _route_turn_then_notify(
            int(cid), target_ids, mode, lead_id=lead_id,
            assignments=assignments, notify_event="agent_done",
            live_roster=live_roster,
        )
    finally:
        if reservation.get("first_turn"):
            _finalize_onboarding_first_turn(
                int(cid), str(reservation.get("turn_id") or ""),
                str(reservation.get("agent_id") or ""),
            )
        _release_onboarding_guide_reservation(
            int(cid), str(reservation.get("token") or ""), asyncio.current_task(),
        )


def _onboarding_settings_scan() -> list[dict]:
    """Important first-week settings. Status only — never secret values."""
    # Settings can persist these outside process env. Use the same live sources
    # as the actual Settings screen so onboarding never calls a saved connection
    # "unset" after a restart.
    cal = bool(calendar_ics.configured())
    search = bool(
        (os.environ.get("TAVILY_API_KEY") or os.environ.get("BRAVE_API_KEY") or "").strip()
    )
    telegram = bool(TELEGRAM_BOT_TOKEN and TELEGRAM_ALLOWED_USER_ID)
    voice = bool((os.environ.get("OPENAI_API_KEY") or "").strip()) or Path(
        "/usr/bin/say"
    ).exists()
    mailbox = False
    try:
        mailbox = bool(mailbox_store.masked(DATA_DIR / "mailboxes.json"))
    except Exception:
        mailbox = False
    items = [
        {
            "id": "calendar", "title": "Calendar", "screen": "settings.calendar",
            "ready": cal, "must": True,
            "why": "So your team can see what's on the day and prep you for it.",
        },
        {
            "id": "search", "title": "Web search", "screen": "settings.tavily",
            "ready": search, "must": True,
            "why": "Lets agents look things up instead of guessing.",
        },
        {
            "id": "mailbox", "title": "Mailbox", "screen": "mailboxes",
            "ready": mailbox, "must": False,
            "why": "Read or draft mail from a conversation, with you approving sends.",
        },
        {
            "id": "telegram", "title": "Telegram alerts", "screen": "settings.telegram",
            "ready": telegram, "must": False,
            "why": "A private pager when an automation finishes or needs you.",
        },
        {
            "id": "voice", "title": "Voice", "screen": "settings.voice",
            "ready": bool(voice), "must": False,
            "why": "Talk to the room instead of typing — optional, and it feels great.",
        },
        {
            "id": "mobile", "title": "Secure phone access", "screen": "settings.mobile",
            "ready": False, "must": False,
            "why": "Reach this same workspace from your phone without opening the LAN.",
        },
    ]
    return items


def _community_env_path() -> Path:
    return Path(_CUSTOM_ENV_FILE).expanduser() if _CUSTOM_ENV_FILE else BASE_DIR / ".env"


def _community_write_env(updates: dict[str, str]) -> None:
    path = _community_env_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    lines = path.read_text(encoding="utf-8").splitlines() if path.is_file() else []
    pending = dict(updates)
    out = []
    for line in lines:
        match = re.match(r"^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=", line)
        if match and match.group(1) in pending:
            key = match.group(1)
            out.append(f"{key}={_env_quote(pending.pop(key))}")
        else:
            out.append(line)
    if pending and out and out[-1].strip():
        out.append("")
    out.extend(f"{key}={_env_quote(value)}" for key, value in pending.items())
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text("\n".join(out).rstrip() + "\n", encoding="utf-8")
    try:
        os.chmod(tmp, 0o600)
    except OSError:
        pass
    tmp.replace(path)
    for key, value in updates.items():
        os.environ[key] = value


def _community_launch_bridge(agent: dict) -> tuple[bool, str]:
    aid = agent["id"]
    if agent.get("managed_adapter") == "openai_chat":
        return _community_launch_openai_adapter(agent)
    module = _COMMUNITY_BRIDGE_MODULES.get(aid)
    if not module:
        return False, "Manual setup is required"
    running = _COMMUNITY_BRIDGE_PROCESSES.get(aid)
    if running and running.poll() is None:
        return True, "Already starting"
    parsed = urlparse(agent["url"])
    if parsed.hostname not in ("127.0.0.1", "localhost", "::1") or not parsed.port:
        return False, "Agent address must be local"
    port_in_use = False
    try:
        with socket.create_connection((parsed.hostname, parsed.port), timeout=0.25):
            port_in_use = True
    except OSError:
        pass
    if port_in_use:
        # Another Agents Chat install may already own the standard bridge port.
        # Only reuse it when it accepts THIS Community install's private token;
        # otherwise the Connect button appears to work but health stays red with
        # HTTP 401 forever. Relocate to a free loopback port instead.
        token = os.environ.get(str(agent.get("token_env") or "")) or agent.get("token", "")
        try:
            response = httpx.post(
                _log_url(agent),
                json={"context_id": "", "length": 1},
                headers={"X-API-KEY": str(token), "Content-Type": "application/json"},
                timeout=0.75,
            )
            accepts_token = response.status_code == 200 or (
                response.status_code == 400
                and "context_id is required" in response.text.lower()
            )
        except Exception:
            accepts_token = False
        if accepts_token:
            return True, "Already connected"
        url_env = _COMMUNITY_AGENT_URL_ENVS.get(aid)
        if not url_env:
            return False, "The local port is already used by another app"
        new_port = _community_free_adapter_port()
        new_url = parsed._replace(netloc=f"127.0.0.1:{new_port}").geturl()
        _community_write_env({url_env: new_url})
        agent["url"] = new_url
        for public in PUBLIC_AGENTS:
            if public.get("id") == aid:
                public["url"] = new_url
        parsed = urlparse(new_url)
    log_dir = DATA_DIR / "bridge_logs"
    log_dir.mkdir(parents=True, exist_ok=True)
    flags = 0
    if os.name == "nt":
        flags = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
    with (log_dir / f"{aid}.log").open("ab") as log:
        proc = subprocess.Popen(
            [sys.executable, "-m", "uvicorn", module, "--host", "127.0.0.1",
             "--port", str(parsed.port), "--no-access-log"],
            cwd=str(BASE_DIR), env=os.environ.copy(), stdout=log,
            stderr=subprocess.STDOUT, start_new_session=(os.name != "nt"),
            creationflags=flags,
        )
    _COMMUNITY_BRIDGE_PROCESSES[aid] = proc
    _COMMUNITY_BRIDGE_PORTS[aid] = int(parsed.port)
    _save_community_bridge_state()
    return True, "Starting on this computer"


def _community_start_perplexity(
    agent: dict, *, request_accessibility: bool,
) -> tuple[bool, str]:
    if sys.platform != "darwin":
        return False, "Perplexity desktop control is currently available on macOS only."
    if not _community_perplexity_driver_path():
        return False, "This Community package is missing the Perplexity desktop helper."
    started, detail = _community_launch_bridge(agent)
    if not started or not request_accessibility:
        return started, detail
    requested, permission_detail = _community_request_perplexity_accessibility()
    return (requested, permission_detail) if requested else (False, permission_detail)


async def _community_validate_openrouter_key(api_key: str) -> tuple[bool, str]:
    """Validate the credential and requested default model before persisting it."""
    if len(api_key) < 16 or len(api_key) > 512 or any(ch.isspace() for ch in api_key):
        return False, "That does not look like an OpenRouter API key."
    try:
        async with httpx.AsyncClient(timeout=12.0) as client:
            headers = {"Authorization": f"Bearer {api_key}"}
            key_response = await client.get(
                "https://openrouter.ai/api/v1/key", headers=headers,
            )
            if key_response.status_code in (401, 403):
                return False, "OpenRouter rejected that API key."
            if key_response.status_code != 200:
                return False, f"OpenRouter key check returned HTTP {key_response.status_code}."
            catalog_response = await client.get(
                OPENROUTER_CATALOG_URL,
                headers=headers,
            )
    except httpx.HTTPError:
        return False, "OpenRouter could not be reached. Check the connection and try again."
    if catalog_response.status_code != 200:
        return False, f"OpenRouter model check returned HTTP {catalog_response.status_code}."
    try:
        rows = catalog_response.json().get("data") or []
    except Exception:
        return False, "OpenRouter returned an unreadable model catalog."
    model_ids = {
        str(row.get("id") or "") for row in rows if isinstance(row, dict)
    }
    if OPENROUTER_DEFAULT_MODEL not in model_ids:
        return False, (
            "This OpenRouter account does not currently expose the configured "
            f"default model ({OPENROUTER_DEFAULT_MODEL})."
        )
    free_models, free_labels = _openrouter_free_chat_models(rows)
    if free_models:
        _install_openrouter_catalog(
            free_models, free_labels, checked_ts=time.time(), status="live", persist=True,
        )
    return True, "OpenRouter key verified."


async def _openrouter_settings_payload() -> dict:
    """Return provider/bridge status without ever returning the upstream key."""
    catalog = await _refresh_openrouter_free_catalog()
    agent = AGENTS_BY_ID.get("openrouter")
    configured = bool(os.environ.get("OPENROUTER_API_KEY", "").strip())
    ready = False
    bridge_state = "not_configured" if not configured else "offline"
    detail = ""
    if configured and agent:
        capability = await _probe_agent_capability(agent)
        online = bool(capability.get("online"))
        degraded = str(capability.get("degraded_reason") or "").strip()
        ready = online and not degraded
        if ready:
            bridge_state = "connected"
        elif online:
            bridge_state = "degraded"
            detail = degraded
        else:
            bridge_state = "offline"
    return {
        "status": "ok",
        "provider": "openrouter",
        "available": bool(agent),
        "configured": configured,
        "key_set": configured,
        "ready": ready,
        "bridge_state": bridge_state,
        "detail": detail,
        "default_model": OPENROUTER_DEFAULT_MODEL,
        "reasoning_options": list(OPENROUTER_REASONING_OPTIONS),
        **catalog,
    }


async def _configure_openrouter(supplied_key: str) -> tuple[Optional[dict], str, int]:
    """Validate, persist, and start OpenRouter for Settings and Community UI."""
    current_key = os.environ.get("OPENROUTER_API_KEY", "").strip()
    api_key = str(supplied_key or "").strip() or current_key
    if not api_key:
        return None, "Paste an OpenRouter API key first.", 400
    valid, detail = await _community_validate_openrouter_key(api_key)
    if not valid:
        return None, detail, 400
    agent = AGENTS_BY_ID.get("openrouter")
    if not agent:
        return None, "OpenRouter is not available in this edition", 404
    updates = {"OPENROUTER_API_KEY": api_key}
    token_env = str(agent.get("token_env") or "")
    if token_env and not os.environ.get(token_env):
        updates[token_env] = secrets.token_urlsafe(48)
    try:
        await asyncio.to_thread(_community_write_env, updates)
        started, start_detail = await asyncio.to_thread(_community_launch_bridge, agent)
    except Exception:
        logger.exception("OpenRouter setup failed")
        return None, "Could not start the OpenRouter connection.", 500
    _AGENT_HEALTH_CACHE.clear()
    if started:
        await asyncio.sleep(0.6)
    payload = await _openrouter_settings_payload()
    payload.update({
        "ok": bool(started),
        "detail": "OpenRouter is connected with the Free Models Router as the default."
        if payload.get("ready") else start_detail,
    })
    return payload, "", 200


