_COMMUNITY_CONNECT_DETECTED_LOCK = asyncio.Lock()


def _community_connect_result_action(
    pre_state: str, started: bool, detail: str,
) -> str:
    """Describe what this pass did, independently of eventual health state."""
    if not started:
        return "failed"
    normalized = str(detail or "").strip().lower()
    if pre_state == "connected" or "already connected" in normalized:
        return "already_connected"
    if normalized.startswith("already"):
        return "already_starting"
    return "newly_started"


@app.post("/api/community/agents/connect-detected")
async def api_community_connect_detected(request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    if not connector_setup_enabled():
        return JSONResponse({"error": "Community setup is not enabled"}, status_code=404)
    try:
        body = await request.json()
    except Exception:
        body = {}
    requested = body.get("agents") if isinstance(body, dict) else None
    requested = set(requested) if isinstance(requested, list) else None
    current_user = _current_user(request)
    # One pass owns token/env persistence and bridge spawning at a time. Without
    # this lock, two tabs can generate different tokens, replace the same .env,
    # and launch two processes against one port before either process is visible.
    async with _COMMUNITY_CONNECT_DETECTED_LOCK:
        before = await _community_agent_discovery(current_user, force=True)
        pre_states = {
            str(item.get("id") or ""): str(item.get("state") or "unknown")
            for item in before.get("agents", []) if isinstance(item, dict)
        }
        results = []
        for public_agent in _community_discovery_agents_for_user(current_user):
            aid = public_agent["id"]
            agent = AGENTS_BY_ID[aid]
            if requested is not None and aid not in requested:
                continue
            pre_state = pre_states.get(aid, "unknown")
            if pre_state == "connected" and aid in _COMMUNITY_BRIDGE_MODULES:
                results.append({
                    "id": aid,
                    "ok": True,
                    "detail": "Already connected",
                    "pre_state": pre_state,
                    "action": "already_connected",
                })
                continue
            detected = await asyncio.to_thread(_community_provider_detection, aid)
            if not detected.get("connectable") or aid not in _COMMUNITY_BRIDGE_MODULES:
                continue
            updates = {}
            token_env = agent.get("token_env")
            if token_env and not os.environ.get(token_env):
                updates[token_env] = secrets.token_urlsafe(48)
            if detected.get("path") and detected.get("path_env"):
                updates[detected["path_env"]] = str(detected["path"])
            try:
                if updates:
                    _community_write_env(updates)
                if aid == "perplexity":
                    started, detail = await asyncio.to_thread(
                        _community_start_perplexity,
                        agent,
                        request_accessibility=True,
                    )
                else:
                    started, detail = await asyncio.to_thread(
                        _community_launch_bridge, agent,
                    )
                results.append({
                    "id": aid,
                    "ok": started,
                    "detail": detail,
                    "pre_state": pre_state,
                    "action": _community_connect_result_action(
                        pre_state, started, detail,
                    ),
                })
            except Exception:
                logger.exception("community agent connect failed: %s", aid)
                results.append({
                    "id": aid,
                    "ok": False,
                    "detail": "Could not start",
                    "pre_state": pre_state,
                    "action": "failed",
                })
        _AGENT_HEALTH_CACHE.clear()
        _invalidate_community_discovery(int(current_user["id"]))
        if results:
            await asyncio.sleep(0.8)
        discovery = await _community_agent_discovery(current_user)
        return {"status": "ok", "results": results, **discovery}


@app.post("/api/community/agents/perplexity/setup")
async def api_community_perplexity_setup(request: Request):
    """Resume or verify the local Perplexity setup without exposing its key."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    if not connector_setup_enabled():
        return JSONResponse({"error": "Community setup is not enabled"}, status_code=404)
    try:
        body = await request.json()
    except Exception:
        body = {}
    action = str((body or {}).get("action") or "open").strip().lower()
    if action not in ("open", "verify"):
        return JSONResponse({"error": "Unknown Perplexity setup action"}, status_code=400)
    agent = AGENTS_BY_ID.get("perplexity")
    if not agent:
        return JSONResponse({"error": "Perplexity is not available in this edition"}, status_code=404)
    detected = await asyncio.to_thread(_community_provider_detection, "perplexity")
    if not detected.get("found"):
        return JSONResponse(
            {"error": "Install and sign in to the Perplexity desktop app first."},
            status_code=409,
        )
    token_env = str(agent.get("token_env") or "")
    if token_env and not os.environ.get(token_env):
        await asyncio.to_thread(
            _community_write_env, {token_env: secrets.token_urlsafe(48)}
        )
    try:
        started, detail = await asyncio.to_thread(
            _community_start_perplexity,
            agent,
            request_accessibility=(action == "open"),
        )
    except Exception:
        logger.exception("community Perplexity setup failed")
        started, detail = False, "Could not start the Perplexity connection."
    _AGENT_HEALTH_CACHE.clear()
    current_user = _current_user(request)
    _invalidate_community_discovery(int(current_user["id"]))
    if started:
        await asyncio.sleep(0.6)
    discovery = await _community_agent_discovery(current_user, force=True)
    row = next(
        (item for item in discovery.get("agents", []) if item.get("id") == "perplexity"),
        {},
    )
    ready = row.get("state") == "connected"
    if action == "verify" and not ready and started:
        detail = (
            "macOS has not granted the final helper yet. Open Accessibility, "
            "remove any stale Agent Chat Perplexity Driver row, add the helper again, "
            "and turn it on. Leave python3 off."
        )
    return {
        "status": "ok",
        "ok": bool(started),
        "ready": bool(ready),
        "detail": detail,
        **discovery,
    }


@app.post("/api/community/agents/openrouter/setup")
async def api_community_openrouter_setup(request: Request):
    """Verify and save the upstream key, then start the loopback-only bridge."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    if not connector_setup_enabled():
        return JSONResponse({"error": "Community setup is not enabled"}, status_code=404)
    try:
        body = await request.json()
    except Exception:
        body = {}
    supplied_key = str((body or {}).get("api_key") or "").strip()
    payload, error, status_code = await _configure_openrouter(supplied_key)
    if error:
        return JSONResponse({"error": error}, status_code=status_code)
    current_user = _current_user(request)
    _invalidate_community_discovery(int(current_user["id"]))
    discovery = await _community_agent_discovery(current_user, force=True)
    row = next(
        (item for item in discovery.get("agents", []) if item.get("id") == "openrouter"),
        {},
    )
    ready = row.get("state") == "connected"
    return {
        **(payload or {}),
        "ready": bool(ready),
        "detail": "OpenRouter is connected with the Free Models Router as the default."
        if ready else str((payload or {}).get("detail") or "OpenRouter is still starting."),
        **discovery,
    }


def _reauth_agent_for_user(user: dict, agent_id: str) -> tuple[Optional[dict], Optional[JSONResponse]]:
    aid = str(agent_id or "").strip()
    agent = AGENTS_BY_ID.get(aid)
    if not agent:
        return None, JSONResponse({"error": "Unknown agent."}, status_code=404)
    owner = agent.get("owner_user_id")
    if not owner:
        # A built-in agent belongs to the host, not to a user, so the ownership
        # test below could never fire for one — every signed-in member could
        # relaunch a SHARED bridge and, via /reauth/secret, rewrite its token
        # env for everyone. Restarting a shared bridge is host process control:
        # admin-only, exactly as /api/agents/{id}/reconnect already treats it.
        # In the single-tenant default (no auth) the caller resolves to admin,
        # so the ordinary Reconnect flow is unaffected.
        if not _is_admin_user(user):
            return None, JSONResponse(
                {"error": "Only an admin can reconnect a shared agent."},
                status_code=403,
            )
        return agent, None
    if int(owner) != int(user["id"]) and not _is_admin_user(user):
        return None, JSONResponse({"error": "Not your agent."}, status_code=403)
    return agent, None


@app.post("/api/agents/reauth/start")
async def api_agent_reauth_start(request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        body = await request.json()
    except Exception:
        body = {}
    agent, err = _reauth_agent_for_user(user, str((body or {}).get("agent_id") or ""))
    if err:
        return err
    _invalidate_community_discovery(int(user["id"]))
    # Every helper below blocks: CLI status shells out, restart does proc.wait,
    # and _wait_local_bridge polls a socket with time.sleep for up to 10s. Run
    # inline on this async handler they stall the ENTIRE event loop — one user
    # tapping Reconnect froze every other request, SSE stream and agent turn for
    # the whole timeout. Same calls, off the loop.
    if agent["id"] == "claude" and await asyncio.to_thread(_claude_cli_signed_in, force=True):
        try:
            await asyncio.to_thread(_community_restart_bridge, agent)
        except Exception:
            logger.exception("reauth start restart")
        return {
            "status": "ok", "ok": True, "ready": True,
            "agent_id": agent["id"], "name": agent.get("name") or agent["id"],
            "title": f"{agent.get('name') or 'Claude'} is already signed in",
            "detail": "The login is live. Sending your last question again.",
        }
    if agent["id"] == "codex" and await asyncio.to_thread(_cli_login_status_ok, "codex"):
        try:
            await asyncio.to_thread(_community_restart_bridge, agent)
        except Exception:
            logger.exception("reauth start restart codex")
        if await asyncio.to_thread(_wait_local_bridge, agent, 10):
            return {
                "status": "ok", "ok": True, "ready": True,
                "agent_id": agent["id"], "name": agent.get("name") or agent["id"],
                "title": f"{agent.get('name') or 'Codex'} is already signed in",
                "detail": "The local connection is back. Sending your last question again.",
            }
        session = _start_agent_reauth(agent, launch_cli=False)
        session["detail"] = (
            "Codex is signed in. Tap I signed in to finish reconnecting the local bridge."
        )
        return {"status": "ok", "ok": True, **_reauth_public(session)}
    session = _start_agent_reauth(agent)
    return {"status": "ok", "ok": True, **_reauth_public(session)}


