@app.post("/api/agents/reauth/secret")
async def api_agent_reauth_secret(request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        body = await request.json()
    except Exception:
        body = {}
    sid = str((body or {}).get("session_id") or "").strip()
    secret = str((body or {}).get("secret") or "").strip()
    session = _AGENT_REAUTH.get(sid)
    if not session:
        return JSONResponse({"error": "That sign-in expired. Start it again."}, status_code=404)
    if not secret:
        return JSONResponse({"error": "Paste the local key."}, status_code=400)
    agent, err = _reauth_agent_for_user(user, session.get("agent_id") or "")
    if err:
        return err
    token_env = session.get("token_env") or agent.get("token_env")
    if token_env:
        _community_write_env({str(token_env): secret})
    elif agent.get("source") == "community_connector":
        agent["token"] = secret
        try:
            _community_write_custom_rows(_community_custom_rows())
        except Exception:
            logger.exception("reauth could not persist connector token")
    try:
        # proc.wait(timeout=3) + a bridge spawn; off the event loop like the
        # rest of the reauth path.
        await asyncio.to_thread(_community_restart_bridge, agent)
    except Exception:
        logger.exception("reauth secret restart")
    ok, detail = await _reauth_probe_ready(agent)
    session["ready"] = ok
    session["stage"] = "ready" if ok else "waiting_secret"
    session["error"] = "" if ok else detail
    _invalidate_community_discovery(int(user["id"]))
    return {"status": "ok", "ok": ok, **_reauth_public(session)}


