@app.get("/api/community/agents/pairing-status")
async def api_community_pairing_status(request: Request):
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    status_id = str(request.query_params.get("status_id") or "").strip()
    now = time.monotonic()
    pairing = next((item for item in _COMMUNITY_PAIRINGS.values()
                    if item.get("status_id") == status_id
                    and int(item.get("owner_user_id") or 0) == int(user["id"])), None)
    if not pairing or pairing["expires"] <= now:
        return JSONResponse({"error": "Setup watch expired"}, status_code=404)
    return {
        "status": "ok",
        "stage": pairing.get("stage") or "prompt_ready",
        "detail": pairing.get("detail") or "Waiting for the desktop agent.",
        "agent": pairing.get("agent"),
        "connected": bool(pairing.get("used")),
    }


def _local_pairing_callback_request(request: Request) -> bool:
    """Only same-computer callers may register through the pairing callback.

    Behind a loopback HTTPS proxy (e.g. Tailscale Funnel) every remote request
    arrives with a 127.0.0.1 socket peer, so like _local_first_run_request this
    pins on the requested Host hostname instead. CLI callers send no
    Origin/Referer, so the origin hostname is only checked when one is present.
    """
    local_hosts = {"127.0.0.1", "localhost", "::1"}
    request_host = (request.url.hostname or "").lower()
    if request_host not in local_hosts:
        return False
    origin = request.headers.get("origin") or request.headers.get("referer") or ""
    if not origin:
        return True
    try:
        origin_host = (urlparse(origin).hostname or "").lower()
    except ValueError:
        return False
    return origin_host in local_hosts


@app.post("/api/community/agents/self-connect")
async def api_community_self_connect(request: Request):
    """One-time, localhost-only registration callback used by the copied prompt."""
    if not connector_setup_enabled():
        return JSONResponse({"error": "Community setup is not enabled"}, status_code=404)
    if not _local_pairing_callback_request(request):
        return JSONResponse({"error": "Pairing is only allowed from this computer"}, status_code=403)
    try:
        body = await request.json()
    except Exception:
        body = {}
    code = str(body.get("pairing_code") or "").strip()
    pairing = _COMMUNITY_PAIRINGS.get(code)
    if not pairing or pairing["expires"] <= time.monotonic():
        _COMMUNITY_PAIRINGS.pop(code, None)
        return JSONResponse({"error": "Pairing code is invalid or expired"}, status_code=401)
    progress_stage = str(body.get("progress_stage") or "").strip().lower()
    if progress_stage:
        if progress_stage not in _COMMUNITY_PAIRING_PROGRESS_STAGES:
            return JSONResponse({"error": "Unknown setup progress stage"}, status_code=400)
        if pairing.get("used"):
            return {"status": "ok", "stage": "connected", "agent": pairing.get("agent")}
        pairing["stage"] = progress_stage
        pairing["detail"] = " ".join(str(body.get("detail") or "").split())[:220] or {
            "preparing": "The desktop agent is preparing the connection.",
            "configuring": "The desktop agent is configuring its local runtime.",
            "starting": "The local agent service is starting.",
            "verifying": "The desktop agent is verifying the live connection.",
            "needs_user": "The desktop agent needs your help before it can continue.",
        }[progress_stage]
        return {"status": "ok", "stage": progress_stage}
    if pairing.get("used"):
        return JSONResponse({"error": "Pairing code has already been used"}, status_code=409)
    if pairing.get("kind") != "self_connect":
        return JSONResponse({"error": "This setup uses Agents Chat's built-in connector"}, status_code=400)
    pairing["stage"] = "verifying"
    pairing["detail"] = "Agents Chat is verifying a real response from the agent."
    try:
        public, _detail = _community_register_agent(
            int(pairing["owner_user_id"]), body, verify_turn=True
        )
    except ValueError as exc:
        return JSONResponse({"error": str(exc)}, status_code=400)
    except Exception:
        logger.exception("community self-connect registration failed")
        return JSONResponse({"error": "Could not register the agent"}, status_code=502)
    pairing["stage"] = "connected"
    pairing["detail"] = f"{public['name']} is connected and ready."
    pairing["agent"] = public
    pairing["used"] = True
    pairing["expires"] = time.monotonic() + _COMMUNITY_PAIRING_RESULT_TTL_S
    return {"status": "ok", "agent": public}


@app.get("/api/agents/models")
async def api_agents_models(request: Request):
    """Per-agent model descriptors for the agents pane: Agent Zero agents report
    their live preset + chat/utility model; bridge agents report a read-only
    model string (from the capability cache, which the concierge already keeps
    warm). Only agents granted to the caller are returned."""
    allowed = _allowed_agent_ids_for_user(_current_user(request))
    await _refresh_capabilities()  # keep card.model fresh for the read-only agents
    models = {
        a["id"]: _agent_model_info(a["id"]) for a in AGENTS if a["id"] in allowed
    }
    if OPENROUTER_AGENT_ID in models:
        # This signed-in endpoint already feeds every model picker. Enrich the
        # bridge's current-model descriptor with the public zero-cost catalog;
        # no provider credential is sent or returned.
        models[OPENROUTER_AGENT_ID].update(
            await _refresh_openrouter_free_catalog()
        )
    return {"status": "ok", "models": models}


@app.post("/api/agents/{agent_id}/model")
async def api_set_agent_model(agent_id: str, request: Request):
    """Switch an Agent Zero agent's LLM by applying one of its presets.yaml
    presets — writes the container's config.json, which A0 re-reads live."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    if agent_id not in AGENTS_BY_ID:
        return JSONResponse({"error": "unknown agent"}, status_code=404)
    user = _current_user(request)
    if agent_id not in _allowed_agent_ids_for_user(user):
        return JSONResponse({"error": "unknown agent"}, status_code=404)
    if not _is_admin_user(user):
        return JSONResponse(
            {"error": "admin required to change shared agent models"},
            status_code=403,
        )
    if agent_id not in AGENT_ZERO_MODEL_DIRS:
        return JSONResponse(
            {"error": "model is not switchable for this agent"}, status_code=400
        )
    try:
        body = await request.json()
    except Exception:
        body = {}
    preset = str(body.get("preset") or "").strip()
    if not preset:
        return JSONResponse({"error": "preset required"}, status_code=400)
    ok, detail, _new = _a0_apply_preset(agent_id, preset)
    if not ok:
        return JSONResponse({"error": detail}, status_code=400)
    return {"status": "ok", "preset": preset, "model": _agent_model_info(agent_id)}


async def _bridge_health(spec: dict) -> tuple[bool, str]:
    """Probe a managed bridge's /health endpoint. Returns (ok, detail)."""
    try:
        async with httpx.AsyncClient(timeout=2.0) as client:
            resp = await client.get(spec["health_url"])
        return (resp.status_code == 200, f"HTTP {resp.status_code}")
    except Exception as e:  # noqa: BLE001 - connection refused etc. mean "down"
        return (False, str(e))


def _spawn_bridge(spec: dict) -> None:
    """Launch a bridge run-script detached, so it outlives this process
    (mirrors the manual `nohup bash scripts/run_*_bridge.sh &` relaunch)."""
    spec["log"].parent.mkdir(parents=True, exist_ok=True)
    log = open(spec["log"], "ab")  # noqa: SIM115 - handed to the child process
    try:
        subprocess.Popen(
            ["bash", str(spec["script"])],
            cwd=str(BASE_DIR),
            stdout=log,
            stderr=log,
            stdin=subprocess.DEVNULL,
            start_new_session=True,  # detach from this process' session
            env=os.environ.copy(),
        )
    finally:
        log.close()  # child keeps its own dup'd fd


def _bridge_port(spec: dict) -> Optional[int]:
    try:
        return urlparse(spec["health_url"]).port
    except Exception:
        return None


def _pids_on_port(port: int) -> list:
    """PIDs holding a TCP port (via `lsof`); [] if none or lsof unavailable."""
    try:
        out = subprocess.run(
            ["lsof", "-ti", f"tcp:{port}"],
            capture_output=True, text=True, timeout=5,
        )
    except Exception:
        return []
    return [int(p) for p in out.stdout.split() if p.strip().isdigit()]


async def _kill_bridge(spec: dict) -> list:
    """Stop whatever is bound to a managed bridge's port so it can be respawned.
    SIGTERM, wait for the port to free, then SIGKILL any straggler. Returns the
    PIDs we signalled (empty if nothing was listening)."""
    port = _bridge_port(spec)
    if not port:
        return []
    pids = _pids_on_port(port)
    for pid in pids:
        try:
            os.kill(pid, signal.SIGTERM)
        except Exception:
            pass
    deadline = time.monotonic() + 6.0
    while time.monotonic() < deadline:
        await asyncio.sleep(0.3)
        if not _pids_on_port(port):
            break
    for pid in _pids_on_port(port):
        try:
            os.kill(pid, signal.SIGKILL)
        except Exception:
            pass
    if pids:
        await asyncio.sleep(0.2)
    return pids


async def _launchctl(*args: str, timeout: float = 12.0) -> tuple[Optional[int], str]:
    """Run one launchctl subcommand. Returns (returncode, stderr).

    A `None` returncode means the call never completed (timeout or exec failure);
    the stderr string says which.
    """
    try:
        proc = await asyncio.create_subprocess_exec(
            "launchctl", *args,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
    except OSError as e:  # launchctl missing / not executable
        return (None, str(e))
    try:
        _out, err = await asyncio.wait_for(proc.communicate(), timeout=timeout)
    except asyncio.TimeoutError:
        proc.kill()
        await proc.communicate()
        return (None, "timed out")
    return (proc.returncode, (err or b"").decode(errors="replace").strip())


def _launchd_bridge_label(spec: dict) -> Optional[str]:
    """The launchd service target for a managed bridge, plist or no plist."""
    if sys.platform != "darwin":
        return None
    label = str(spec.get("launchd_label") or "").strip()
    if not label:
        return None
    return f"gui/{os.getuid()}/{label}"


def _launchd_bridge_service(spec: dict) -> Optional[tuple[str, Path]]:
    """Return the service target and plist for a launchd-supervised bridge."""
    service = _launchd_bridge_label(spec)
    if not service:
        return None
    plist = Path.home() / "Library" / "LaunchAgents" / f"{service.rsplit('/', 1)[1]}.plist"
    if not plist.is_file():
        return None
    return (service, plist)


async def _launchd_job_loaded(service: str) -> bool:
    """Ask launchd — not the filesystem — whether it currently owns this label."""
    rc, _ = await _launchctl("print", service, timeout=8)
    return rc == 0


async def _launchd_orphan_service(spec: dict) -> Optional[str]:
    """A loaded label whose plist has vanished: launchd still owns the port."""
    service = _launchd_bridge_label(spec)
    if not service or _launchd_bridge_service(spec):
        return None
    return service if await _launchd_job_loaded(service) else None


async def _restart_launchd_bridge(spec: dict, *, force: bool) -> tuple[list[int], Optional[str]]:
    """Return one bridge to launchd ownership, its only supervisor.

    `force` reloads the bridge's code/config: boot the job out, clear the port,
    bootstrap it back. Booting out before clearing the port is crucial — killing
    only the uvicorn child makes KeepAlive race a detached replacement and can
    leave two supervisors fighting over the same socket forever.

    Without `force` this is the recovery path for a bridge that merely failed its
    health probe, so it must never kill a process: a live-but-slow bridge (blocked
    event loop, loaded machine) fails that probe too, and killing it would destroy
    the agent turns it still has in flight.
    """
    managed = _launchd_bridge_service(spec)
    if not managed:
        return ([], "launchd service is not configured")
    service, plist = managed
    domain = f"gui/{os.getuid()}"

    killed: list[int] = []
    if force:
        rc, err = await _launchctl("bootout", service)
        if rc is None:
            return ([], f"launchd bootout {err}")
        # A nonzero rc is usually "no such process" — the job simply wasn't
        # loaded. Anything else is the likeliest cause of a bootstrap failure
        # below, so leave a breadcrumb rather than discarding it.
        if rc != 0 and err:
            logger.info("reconnect: launchctl bootout %s: %s", service, err)
        killed = await _kill_bridge(spec)

    # A previous manual disable (or a transient disabled state during bootout)
    # makes bootstrap fail with macOS error 5 and leaves the bridge absent.
    rc, err = await _launchctl("enable", service)
    if rc != 0:
        logger.info(
            "reconnect: launchctl enable %s: %s", service, err or f"exited {rc}"
        )

    last_error = "launchd bootstrap failed"
    for attempt in range(3):
        if attempt:
            await asyncio.sleep(0.5 * attempt)
        rc, err = await _launchctl("bootstrap", domain, str(plist))
        if rc == 0:
            return (killed, None)
        # launchd refuses to bootstrap a label it already owns. That is the
        # normal case for a plain reconnect (KeepAlive is mid-respawn), and can
        # also follow a bootout that hasn't finished tearing down. Either way the
        # job is loaded, so let the caller's health poll be the judge instead of
        # reporting a failure for a bridge that is on its way up.
        if await _launchd_job_loaded(service):
            if not force:
                # `kickstart` (without -k) starts a loaded job that isn't
                # running and leaves a running one alone.
                await _launchctl("kickstart", service)
            return (killed, None)
        if rc is None:
            last_error = f"launchd bootstrap {err}"
        else:
            last_error = err or f"launchd bootstrap exited {rc}"
    return (killed, last_error)


# Serialize kill/respawn PER BRIDGE so concurrent reconnects can't thrash one
# process (double-kill a freshly-spawned bridge, race two spawns on one port).
# Bridges have disjoint ports, labels and containers, so a single global lock
# would only let one wedged launchctl/docker call block the other eight.
_BRIDGE_CONTROL_LOCKS: dict[str, asyncio.Lock] = {}


def _bridge_control_lock(agent_id: str) -> asyncio.Lock:
    lock = _BRIDGE_CONTROL_LOCKS.get(agent_id)
    if lock is None:
        lock = _BRIDGE_CONTROL_LOCKS[agent_id] = asyncio.Lock()
    return lock


@app.post("/api/agents/{agent_id}/reconnect")
async def api_agent_reconnect(agent_id: str, request: Request):
    """Relaunch a locally-managed agent bridge (Codex/Claude).

    Plain call: no-op (already-online) if the bridge answers, else start it — it
    never stops a running process, because a live-but-slow bridge fails the health
    probe too and would lose its in-flight turns.
    `?force=1`: reload bridge code/config even when already healthy. On the
    production Mac this performs a launchd bootout/bootstrap so there is exactly
    one supervisor; other platforms use the detached run-script fallback. The
    endpoint then polls /health until healthy or times out.
    `?force=1&container=1` (container agents only): additionally `docker restart`
    the agent's container, so a change to its bind-mounted container.env — e.g.
    a Secrets-panel grant — is re-read by the in-container agent process.
    """
    blocked = _require_origin(request)
    if blocked:
        return blocked
    # Killing/respawning a shared bridge is host process control: admin-only, in
    # line with /api/agents/secrets/sync. In the single-tenant default (no auth /
    # no access token) the caller resolves to admin, so the UI button still works.
    blocked = _require_admin(request)
    if blocked:
        return blocked
    spec = MANAGED_BRIDGES.get(agent_id)
    if not spec:
        return JSONResponse(
            {"error": f"{agent_id} is not a locally managed bridge"},
            status_code=400,
        )
    if not spec["script"].is_file():
        return JSONResponse(
            {"error": f"launch script missing: {spec['script']}"},
            status_code=500,
        )
    force = str(request.query_params.get("force", "")).lower() in ("1", "true", "yes")
    want_container = str(request.query_params.get("container", "")).lower() in ("1", "true", "yes")
    container_name = CONTAINER_NAMES.get(agent_id) if agent_id in CONTAINER_AGENT_IDS else None
    already_ok, _ = await _bridge_health(spec)
    if already_ok and not force:
        # The bridge process answers — but "reachable" isn't "healthy". If it
        # self-reports degraded (e.g. upstream token expired), don't claim
        # "already-online": relaunching the proxy won't fix an upstream/token
        # problem, so surface the real reason instead of a no-op success. This
        # is why Reconnect used to appear to do nothing on a broken @minimax.
        degraded, reason = await _managed_bridge_deep_status(agent_id)
        # Whatever we just learned is fresher than the cached fan-out, which is
        # held for _AGENT_HEALTH_CACHE_S. Without this drop, the health poll that
        # follows a Reconnect replays the stale row for up to 20s, so the dot
        # stays red and the button reads as having done nothing.
        _AGENT_HEALTH_CACHE.clear()
        if degraded:
            return {
                "status": "degraded",
                "agent_id": agent_id,
                "state": "reachable-degraded",
                "spawned": False,
                "reason": reason,
            }
        else:
            return {
                "status": "ok",
                "agent_id": agent_id,
                "state": "already-online",
                "spawned": False,
            }
    # Past this point the bridge is being relaunched, so every cached health row
    # is about to be wrong. Drop them before the work, not after, so a poll that
    # races the relaunch cannot refill the cache from the pre-restart process.
    _AGENT_HEALTH_CACHE.clear()
    # force=1 reloads bridge code/config even when the bridge was already healthy.
    container_restarted = False
    container_error = None
    supervisor = "launchd" if _launchd_bridge_service(spec) else "detached"
    async with _bridge_control_lock(agent_id):
        if force and want_container and container_name:
            # Bounce the Docker container BEFORE respawning the bridge so the
            # health poll below reflects the whole stack. `docker restart` keeps
            # the bind mounts, so the in-container process re-reads the updated
            # /opt/data/.env on the way back up.
            try:
                proc = await asyncio.create_subprocess_exec(
                    "docker", "restart", container_name,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                )
                _out, errout = await asyncio.wait_for(proc.communicate(), timeout=90)
                if proc.returncode == 0:
                    container_restarted = True
                else:
                    container_error = (
                        (errout or b"").decode(errors="replace").strip()
                        or f"docker restart exited {proc.returncode}"
                    )
            except Exception as e:  # noqa: BLE001
                container_error = str(e)
            if container_error:
                logger.warning(
                    "reconnect: docker restart %s failed: %s",
                    container_name, container_error,
                )
        killed: list[int] = []
        launch_error: Optional[str] = None
        if supervisor == "launchd":
            killed, launch_error = await _restart_launchd_bridge(spec, force=force)
        else:
            if force:
                # A plist can go missing while launchd still owns the label (these
                # plists have been repointed before). Spawning a detached copy then
                # would leave KeepAlive and this process fighting over the port, so
                # take the label back first — bootout needs no plist.
                orphan = await _launchd_orphan_service(spec)
                if orphan:
                    logger.warning(
                        "reconnect: %s has no plist but launchd still owns %s; booting it out",
                        agent_id, orphan,
                    )
                    await _launchctl("bootout", orphan)
            killed = await _kill_bridge(spec) if force else []
            try:
                _spawn_bridge(spec)
            except Exception as e:  # noqa: BLE001
                launch_error = str(e)
        if launch_error:
            logger.error(
                "reconnect: failed to launch %s bridge via %s: %s",
                agent_id, supervisor, launch_error,
            )
            return JSONResponse(
                {"error": f"failed to launch bridge: {launch_error}",
                 "supervisor": supervisor,
                 "container_restarted": container_restarted,
                 "container_error": container_error}, status_code=500
            )
    # The bridge needs a moment to import uvicorn and bind its port.
    deadline = time.monotonic() + 15.0
    while time.monotonic() < deadline:
        await asyncio.sleep(0.6)
        ok, _ = await _bridge_health(spec)
        if ok:
            # A successful forced restart is the point at which an env-file
            # revocation becomes true in the running process. Container agents
            # must also have completed the requested Docker restart before their
            # durable cross-tenant block can be cleared.
            if force and (
                _container_env_file(agent_id) is None or container_restarted
            ):
                try:
                    _clear_secret_restart_blocks(agent_id)
                except Exception:
                    logger.exception(
                        "reconnect: failed to clear secret restart block for %s",
                        agent_id,
                    )
                    return JSONResponse(
                        {
                            "error": "agent restarted but secret revocation could not be finalized",
                            "agent_id": agent_id,
                        },
                        status_code=500,
                    )
            # A just-restarted bridge may now self-report a fresh /capabilities
            # card; refresh the registry so the orchestrator sees it right away
            # instead of waiting out the TTL.
            try:
                await _refresh_capabilities(force=True)
            except Exception:
                pass
            return {
                "status": "ok",
                "agent_id": agent_id,
                "state": "restarted" if killed else "online",
                "spawned": True,
                "restarted": bool(killed),
                "killed_pids": killed,
                "supervisor": supervisor,
                "container_restarted": container_restarted,
                "container_error": container_error,
            }
    return JSONResponse(
        {
            "status": "starting",
            "agent_id": agent_id,
            "state": "starting",
            "spawned": True,
            "detail": "bridge launched but not healthy yet; check again shortly",
            "supervisor": supervisor,
            "container_restarted": container_restarted,
            "container_error": container_error,
        },
        status_code=202,
    )


@app.post("/api/agents/{agent_id}/disconnect")
async def api_agent_disconnect(agent_id: str, request: Request):
    """Remove an agent from Agent Chat.

    Two scopes, in the request body as {"scope": "me"|"everyone"}:
      - "me" — hide the agent for the calling user only, by clearing their
        `user_agents` grant. This is the ONLY option for a built-in agent
        (Codex, Claude, the Hermes family, ...): those are code, not data,
        and can never be fully removed here. It is also the default for a
        community-connector agent you don't own. Every dispatch path already
        re-checks `_allowed_agent_ids_for_chat`, so a stale roster/skill
        entry referencing a now-hidden agent is inert and self-heals on the
        next room edit — nothing else needs to change.
      - "everyone" — a full teardown, available only for a community-
        connector agent you own (or, for any such agent, an admin): stop its
        managed adapter if one is running, drop it from the local connector
        store, remove it from the live registry, and run the same
        routing-state cleanup the Kimi retirement uses (chats, skills,
        coding jobs, FREE-WILL sessions, app_settings — including clearing
        it as orchestrator if it was one — and per-user prefs). This is the
        default scope when you own the connector.

    Refuses (409) while the agent is working on ANY chat right now, in
    either scope — matching the composer's existing "stays selected while
    working" guard, just applied app-wide instead of per-room.
    """
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "sign in required"}, status_code=401)
    agent = AGENTS_BY_ID.get(agent_id)
    if not agent:
        return JSONResponse({"error": "unknown agent"}, status_code=404)

    try:
        body = await request.json()
    except Exception:
        body = {}
    if not isinstance(body, dict):
        body = {}

    uid = int(user["id"])
    is_connector = agent.get("source") == "community_connector"
    is_owned_connector = is_connector and int(agent.get("owner_user_id") or 0) == uid
    can_fully_remove = is_connector and (is_owned_connector or _is_admin_user(user))
    scope = str(body.get("scope") or ("everyone" if is_owned_connector else "me")).strip().lower()
    if scope not in ("me", "everyone"):
        return JSONResponse({"error": "scope must be \"me\" or \"everyone\""}, status_code=400)
    if scope == "everyone" and not can_fully_remove:
        return JSONResponse({
            "error": (
                "Only the person who connected this agent (or an admin) can remove "
                "it for everyone."
            ) if is_connector else (
                "Built-in agents can't be removed from Agent Chat — hide it for "
                "yourself instead."
            ),
        }, status_code=403)

    working_now = [
        info for info in RUNNING_TASKS.values()
        if str(info.get("agent_id") or "").strip().lower() == agent_id.strip().lower()
    ]
    if working_now:
        return JSONResponse({
            "error": f"{agent.get('name') or agent_id} is working right now — wait "
                     "for it to finish, then try again.",
        }, status_code=409)

    changed = 0
    orchestrator_reset = False
    if scope == "everyone":
        orchestrator_reset = _get_setting("orchestrator_agent_id", "").strip().lower() == agent_id.strip().lower()
        proc = _COMMUNITY_BRIDGE_PROCESSES.pop(agent_id, None)
        if proc is not None:
            try:
                if proc.poll() is None:
                    proc.terminate()
            except Exception:
                logger.exception("failed to stop connector adapter for %s", agent_id)
        _COMMUNITY_BRIDGE_PORTS.pop(agent_id, None)
        try:
            _save_community_bridge_state()
        except Exception:
            logger.exception("failed to persist bridge state after disconnecting %s", agent_id)
        rows = [r for r in _community_custom_rows() if str(r.get("id")) != agent_id]
        _community_write_custom_rows(rows)
        AGENTS[:] = [a for a in AGENTS if a.get("id") != agent_id]
        AGENTS_BY_ID.pop(agent_id, None)
        PUBLIC_AGENTS[:] = [a for a in PUBLIC_AGENTS if a.get("id") != agent_id]
        with _db() as conn:
            changed = _retire_agent_from_active_state(conn, agent_id)
        _AGENT_HEALTH_CACHE.clear()
        _invalidate_community_discovery()
    else:
        with _db() as conn:
            changed = int(conn.execute(
                "DELETE FROM user_agents WHERE user_id=? AND agent_id=?", (uid, agent_id),
            ).rowcount or 0)

    _audit_event(request, "agent.disconnect", target=agent_id, status="ok",
                 meta={"scope": scope, "changed": changed})
    return {
        "status": "ok",
        "agent_id": agent_id,
        "scope": scope,
        "changed": changed,
        "orchestrator_reset": orchestrator_reset,
    }


@app.post("/api/agents/secrets/sync")
async def api_sync_agent_secrets(request: Request):
    """Admin/local operation: push selected backend env secrets into agents.

    Intended for operational credentials such as MARKETING_EMAIL. Secret values
    are read from this process environment and never returned to the caller.
    """
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked

    try:
        payload = await request.json()
    except Exception:
        payload = {}
    keys = payload.get("keys") or OPERATIONAL_SECRET_KEYS
    targets = payload.get("targets") or OPERATIONAL_SECRET_TARGETS or [a["id"] for a in AGENTS]
    if not isinstance(keys, list) or not isinstance(targets, list):
        return JSONResponse({"error": "keys and targets must be lists"}, status_code=400)
    if len(keys) > 100 or len(targets) > len(AGENTS_BY_ID):
        return JSONResponse({"error": "too many keys or targets"}, status_code=400)
    if any(
        not isinstance(key, str) or len(key) > 128
        or not SECRET_KEY_PATTERN.fullmatch(key.strip().upper())
        for key in keys
    ):
        return JSONResponse({"error": "invalid secret key"}, status_code=400)
    if any(not isinstance(tid, str) or tid not in AGENTS_BY_ID for tid in targets):
        return JSONResponse({"error": "unknown target"}, status_code=400)
    valid_targets = list(dict.fromkeys(targets))
    if not valid_targets:
        return JSONResponse({"error": "no valid targets"}, status_code=400)

    results = await _sync_env_secret_to_agents(keys, valid_targets)
    status_value = "ok" if results and all(r.get("status") == "ok" for r in results) else "partial"
    _audit_event(
        request,
        "secret.env_sync",
        actor="admin" if ACCESS_TOKEN else "user",
        target=",".join(valid_targets),
        status=status_value,
        meta={
            "keys": [r.get("key") for r in results],
            "statuses": [r.get("status") for r in results],
            "targets": valid_targets,
        },
    )
    return {
        "status": status_value,
        "keys": [r.get("key") for r in results],
        "targets": valid_targets,
        "results": [
            {
                "key": r.get("key"),
                "status": r.get("status"),
                "targets": {
                    tid: {"status": res[0], "error": res[1]}
                    for tid, res in (r.get("results") or {}).items()
                },
            }
            for r in results
        ],
    }


def _secret_scope_agents(
    user: Optional[dict], *, include_secret_conflicts: bool = False,
) -> list[dict]:
    """Agents the given user may be granted a secret on (their allowed set),
    as {id, name} for the panel's picker."""
    allowed = _allowed_agent_ids_for_user(
        user, include_secret_conflicts=include_secret_conflicts,
    )
    return [{"id": a["id"], "name": a["name"]} for a in AGENTS if a["id"] in allowed]


def _resolve_secret_owner(
    caller: Optional[dict], requested_owner: object
) -> tuple[Optional[int], Optional[dict], Optional[JSONResponse]]:
    """Resolve whose secrets a request operates on. Everyone manages their own;
    an admin may pass owner_user_id to provision a secret onto ANOTHER user's
    agents (e.g. give Joanna's agents a Canva key). Non-admins asking for someone
    else get 403. Returns (owner_id, owner_user, error_response)."""
    if not caller:
        return None, None, JSONResponse({"error": "unauthorized"}, status_code=401)
    if requested_owner is None or str(requested_owner).strip() == "":
        return int(caller["id"]), caller, None
    try:
        requested_id = int(requested_owner)
    except (TypeError, ValueError):
        return None, None, JSONResponse({"error": "invalid owner_user_id"}, status_code=400)
    if requested_id == int(caller["id"]):
        return int(caller["id"]), caller, None
    if not _is_admin_user(caller):
        return None, None, JSONResponse(
            {"error": "admin required to manage another user's secrets"}, status_code=403)
    target = _user_by_id(requested_id)
    if not target or not target.get("is_active"):
        return None, None, JSONResponse({"error": "user not found"}, status_code=404)
    return int(target["id"]), target, None


def _secret_panel_users() -> list[dict]:
    """Compact user roster for the admin's 'manage secrets for…' selector."""
    return [
        {"id": u["id"],
         "name": u.get("preferred_name") or u.get("display_name") or u["email"],
         "email": u["email"], "role": u["role"]}
        for u in _list_users() if u.get("is_active")
    ]


# ---------------------------------------------------------------------------
# Token usage & cost-efficiency metering
#
# Every agent turn is metered into the `token_usage` table from append_thread().
# When a bridge reports a usage object we record it exactly (source='api_usage');
# otherwise we estimate tokens from text (source='estimated'). Codex, Claude,
# MiniMax and Hermes emit exact usage; the remaining bridges stay clearly
# labeled estimates. The dashboard prices those
# tokens at list/OpenRouter rates (implied API cost) and compares against the
# amortized cost of the fixed monthly subscriptions, so Owner can see whether the
# subscriptions beat pay-per-token API. Caps are NOT token-denominated, so any
# cap % is approximate and only shown once a cap_tokens calibration is set.
# ---------------------------------------------------------------------------

# Provider that "owns" each agent for cost-bucket accounting. The Hermes family
# runs on MiniMax; the Agent Zero containers (lead/sales) run on the DeepSeek API
# (prepaid, pay-per-token — a "credits" provider, not a flat subscription).
_AGENT_PROVIDER = {
    "claude": "anthropic", "codex": "openai", "antigravity": "google",
    "grok": "xai", "kimi": "moonshot", "perplexity": "perplexity",
    "openrouter": "openrouter",
    "minimax": "minimax", "hermes": "minimax", "ops-agent": "minimax",
    "lead-agent": "minimax", "sales-agent": "minimax", "support-agent": "minimax",
    "lead": "deepseek", "sales": "deepseek",
}

_USAGE_WINDOWS = {
    "1m": (60_000, "last minute"),
    "1h": (3_600_000, "last hour"),
    "24h": (86_400_000, "last 24 hours"),
    "7d": (604_800_000, "last 7 days"),
    "30d": (2_592_000_000, "last 30 days"),
    "90d": (7_776_000_000, "last 90 days"),
    "365d": (31_536_000_000, "last 365 days"),
    "all": (None, "all recorded"),
}
_USAGE_MONTH_MS = 2_592_000_000  # 30d basis for amortizing subs & cap cycles
_USAGE_BASELINE_DAYS = 30  # days of metering before the subs-vs-API verdict is trusted
_USAGE_MAX_CUSTOM_DAYS = 36_500  # 100 years — effectively as far back as the owner asks
_USAGE_CUSTOM_DAYS_RE = re.compile(r"^(\d{1,5})d$")
_USAGE_SINCE_RE = re.compile(r"^since:(\d{4}-\d{2}-\d{2})$")


def _usage_day_label(dt: datetime) -> str:
    return dt.strftime("%d %b %Y").lstrip("0")


def _resolve_usage_window(rng: str, now_ms: int) -> tuple[int, str, str]:
    """Turn a range token into (since_ms, label, canonical).

    Accepts the named presets, `all` (no lower bound), any `Nd` day count,
    or `since:YYYY-MM-DD`. Unknown input falls back to 30d. `since_ms` of 0
    means "from the beginning of recorded usage"."""
    raw = (rng or "30d").strip().lower()
    if raw in _USAGE_WINDOWS:
        win_ms, label = _USAGE_WINDOWS[raw]
        if win_ms is None:
            return 0, label, "all"
        return max(0, int(now_ms) - int(win_ms)), label, raw
    since_m = _USAGE_SINCE_RE.match(raw)
    if since_m:
        try:
            start = datetime.strptime(since_m.group(1), "%Y-%m-%d")
        except ValueError:
            start = None
        if start is not None:
            try:
                since = int(start.timestamp() * 1000)
            except (OverflowError, OSError, ValueError):
                since = 0
            since = max(0, min(since, int(now_ms)))
            return since, "since " + _usage_day_label(start), "since:" + since_m.group(1)
    days_m = _USAGE_CUSTOM_DAYS_RE.match(raw)
    if days_m:
        days = int(days_m.group(1))
        if 1 <= days <= _USAGE_MAX_CUSTOM_DAYS:
            win_ms = days * 86_400_000
            return max(0, int(now_ms) - win_ms), f"last {days} days", f"{days}d"
    win_ms, label = _USAGE_WINDOWS["30d"]
    return max(0, int(now_ms) - int(win_ms)), label, "30d"

# Per-provider cost model. Two kinds:
#   - "subscription": a flat monthly fee, amortized across the window. The
#     dashboard asks "do these beat pay-per-token API?" cap_tokens is an
#     optional (approximate) monthly token allowance.
#   - "credits": prepaid, pay-per-token (e.g. DeepSeek). Cost = actual tokens ×
#     rates (no amortization — they ARE API); credit_balance is the prepaid pool
#     and the dashboard shows the burn-down of it.
# Editable from the Assumptions panel; persisted to app_settings 'usage.settings'.
# These defaults are illustrative — tune them.
_USAGE_SUBS_DEFAULTS = {
    "anthropic": {"label": "Claude Max",  "kind": "subscription", "monthly_usd": 100.0, "cap_tokens": 0,
                  "rolling_budget_tokens": 1_200_000, "rolling_window_hours": 5, "adaptive_guard": True},
    "openai":    {"label": "ChatGPT",     "kind": "subscription", "monthly_usd": 20.0,  "cap_tokens": 0,
                  "adaptive_guard": True},
    "minimax":   {"label": "MiniMax",     "kind": "subscription", "monthly_usd": 20.0,  "cap_tokens": 0,
                  "adaptive_guard": True},
    "google":    {"label": "Antigravity", "kind": "subscription", "monthly_usd": 0.0,   "cap_tokens": 0,
                  "adaptive_guard": True},
    "xai":       {"label": "SuperGrok",   "kind": "subscription", "monthly_usd": 30.0,  "cap_tokens": 0,
                  "adaptive_guard": True},
    "perplexity": {"label": "Perplexity", "kind": "subscription", "monthly_usd": 0.0, "cap_tokens": 0, "adaptive_guard": True},
    "openrouter": {"label": "OpenRouter", "kind": "credits", "credit_balance": 0.0, "monthly_usd": 0.0, "cap_tokens": 0, "adaptive_guard": True},
    "tavily":    {"label": "Tavily Search", "kind": "credits", "credit_balance": 0.0, "monthly_usd": 0.0, "cap_tokens": 0, "adaptive_guard": False},
    "deepseek":  {"label": "DeepSeek",    "kind": "credits", "credit_balance": 25.0, "monthly_usd": 0.0, "cap_tokens": 0, "adaptive_guard": False},
    "other":     {"label": "Other / API", "kind": "subscription", "monthly_usd": 0.0,   "cap_tokens": 0,
                  "adaptive_guard": True},
}
_USAGE_PRICE_FALLBACK = {"in": 1.0, "out": 3.0, "cached": 0.1}


def _provider_for_agent(agent_id: str, model: str = "") -> str:
    if agent_id in _AGENT_PROVIDER:
        return _AGENT_PROVIDER[agent_id]
    m = (model or "").lower()
    if "ox-alpha" in m:
        return {"in": 0.0, "out": 0.0, "cached": 0.0}
    if "claude" in m:
        return "anthropic"
    if "gpt" in m or "o3" in m or "o4" in m:
        return "openai"
    if "gemini" in m:
        return "google"
    if "grok" in m:
        return "xai"
    if "kimi" in m or m.startswith("k3"):
        return "moonshot"
    if "deepseek" in m:
        return "deepseek"
    if "minimax" in m:
        return "minimax"
    if "perplexity" in m or "sonar" in m:
        return "perplexity"
    return "other"


def _price_for_model(model: str, provider: str = "") -> dict:
    """List-price $/M (input, output, cached-input) for a model string. Loose
    substring match so spacing/casing variants ('MiniMax-M3', 'Gemini 3.5
    Flash') all resolve. When the model is unknown/blank (e.g. the Agent Zero
    containers don't report one), fall back to a representative rate for
    `provider`. Illustrative rates — edit here to match your source."""
    m = (model or "").lower()
    if "claude" in m:
        if "haiku" in m:
            return {"in": 0.80, "out": 4.0, "cached": 0.08}
        if "sonnet" in m:
            return {"in": 3.0, "out": 15.0, "cached": 0.30}
        return {"in": 5.0, "out": 25.0, "cached": 0.50}  # opus / default (Opus 4.8: $5/$25/M)
    if "gpt" in m or "o3" in m or "o4" in m:
        return {"in": 5.0, "out": 30.0, "cached": 0.50}  # GPT-5.5: $5/$30/M
    if "gemini" in m:
        if "flash" in m:
            return {"in": 0.30, "out": 2.50, "cached": 0.075}
        return {"in": 1.25, "out": 10.0, "cached": 0.31}  # pro / default
    if "grok" in m:
        return {"in": 3.0, "out": 15.0, "cached": 0.75}  # xAI Grok (illustrative)
    if "deepseek" in m:
        if "reason" in m or "r1" in m:  # deepseek-reasoner (V4 Pro: $1.74/$3.48/M)
            return {"in": 1.74, "out": 3.48, "cached": 0.0145}
        return {"in": 0.14, "out": 0.28, "cached": 0.0028}  # deepseek-chat / default (V4-Flash)
    if "minimax" in m:
        return {"in": 0.30, "out": 1.20, "cached": 0.06}
    if "perplexity" in m or "sonar" in m:
        return {"in": 0.25, "out": 2.50, "cached": 0.0625}
    # Model string unknown/blank — price by the agent's provider instead.
    p = (provider or "").lower()
    _BY_PROVIDER = {
        "deepseek": {"in": 0.14, "out": 0.28, "cached": 0.0028},
        "minimax": {"in": 0.30, "out": 1.20, "cached": 0.06},
        "anthropic": {"in": 5.0, "out": 25.0, "cached": 0.50},
        "openai": {"in": 5.0, "out": 30.0, "cached": 0.50},
        "google": {"in": 0.30, "out": 2.50, "cached": 0.075},
        "perplexity": {"in": 0.25, "out": 2.50, "cached": 0.0625},
        "openrouter": {"in": 1.0, "out": 3.0, "cached": 0.1},
    }
    if p in _BY_PROVIDER:
        return _BY_PROVIDER[p]
    return _USAGE_PRICE_FALLBACK


# Representative model per family for the methodology table. The rates are read
# back through _price_for_model() itself, so the prices shown in the disclaimer
# are provably the exact same rates used to compute every cost on the panel.
_PRICE_SAMPLES = [
    ("Claude Opus", "claude-opus-4"),
    ("Claude Sonnet", "claude-sonnet"),
    ("GPT-5 / Codex", "gpt-5"),
    ("Gemini Pro", "gemini pro"),
    ("Gemini Flash", "gemini flash"),
    ("DeepSeek", "deepseek-chat"),
    ("MiniMax", "minimax-m3"),
    ("Perplexity API equivalent", "perplexity/sonar"),
]


def _usage_price_table() -> list:
    return [dict(label=lbl, **_price_for_model(ms)) for lbl, ms in _PRICE_SAMPLES]


def _estimate_tokens(text: str) -> int:
    if not text:
        return 0
    return max(1, round(len(text) / 4))  # ~4 chars/token, the standard heuristic


def _estimate_input_tokens(cid: int) -> int:
    """Approximate the prompt/context tokens an agent turn consumed by summing
    the recent message text in the chat (context is re-sent every turn, so this
    is charged per call). Rough + clearly labeled 'estimated' downstream."""
    try:
        with _db() as conn:
            rows = conn.execute(
                "SELECT text FROM messages WHERE chat_id=? ORDER BY id DESC LIMIT 24",
                (int(cid),),
            ).fetchall()
        chars = sum(len(r["text"] or "") for r in rows)
        return max(1, round(chars / 4))
    except Exception:
        return 0


def _record_token_usage(cid: int, agent_id: str, model: str, metadata: dict, text: str,
                        msg_id: Optional[int] = None) -> None:
    usage = metadata.get("usage") if isinstance(metadata, dict) else None
    provider = _provider_for_agent(agent_id, model)
    source = "estimated"
    cached = reasoning = 0
    model_calls = 1
    if isinstance(usage, dict):
        fresh = int(usage.get("input_tokens") or usage.get("prompt_tokens") or 0)
        out = int(usage.get("output_tokens") or usage.get("completion_tokens") or 0)
        total = int(usage.get("total_tokens") or 0)
        cached = int(usage.get("cache_read_input_tokens") or usage.get("cached_tokens")
                     or usage.get("cached_input_tokens") or 0)
        cache_create = int(usage.get("cache_creation_input_tokens") or 0)
        reasoning = int(usage.get("reasoning_tokens") or usage.get("reasoning_output_tokens") or 0)
        model_calls = max(1, int(usage.get("model_calls") or 1))
        # Anthropic reports input_tokens EXCLUDING cached reads/creates (separate
        # fields); OpenAI/MiniMax fold them into prompt_tokens. Normalize to one
        # all-in input so the dashboard doesn't undercount cache-heavy Claude
        # turns. `cached` stays the discounted portion for costing.
        inp = (fresh + cached + cache_create) if provider == "anthropic" else fresh
        source = "api_usage"
        if inp <= 0 and out <= 0 and total > 0:
            # Bridge reported only a grand total (e.g. MiniMax/Mavis: the real
            # context window is huge vs. the reply). Split it — output from the
            # reply text, the rest is input/context. Total is exact; split est.
            out = min(total, _estimate_tokens(text))
            inp = max(0, total - out)
        elif inp <= 0 and out <= 0:  # usage object present but empty → estimate
            inp, out, cached, reasoning, source = (
                _estimate_input_tokens(cid), _estimate_tokens(text), 0, 0, "estimated")
    else:
        inp, out = _estimate_input_tokens(cid), _estimate_tokens(text)
    with _db() as conn:
        orow = conn.execute(
            "SELECT owner_user_id FROM chats WHERE id=?", (int(cid),)
        ).fetchone()
        owner_id = orow["owner_user_id"] if orow else None
        conn.execute(
            "INSERT INTO token_usage(ts, chat_id, owner_user_id, agent_id, model, "
            "provider, input_tokens, output_tokens, cached_tokens, reasoning_tokens, "
            "model_calls, source, msg_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (int(time.time() * 1000), int(cid), owner_id, agent_id, model or "",
             provider, inp, out, cached, reasoning, model_calls, source,
             int(msg_id) if msg_id else None),
        )


# ---------------------------------------------------------------------------
#  Token-waste detector (P1): flag a provider usage/quota cap, reconcile it
#  against Agents Chat's own recent usage (so an account burned mostly OUTSIDE
#  the app is named as such), and circuit-break further turns to that provider
#  until it resets — instead of spending failed calls. The account-level number
#  is INFERRED (the CLIs expose no usage API): the only hard signal is the cap
#  error a bridge throws, which v5.38 already classifies as non-retryable.
# ---------------------------------------------------------------------------

# Mirror of the codex bridge's _CODEX_NON_RETRYABLE_RE so the app recognizes a
# quota/usage cap from ANY agent's error text (not just Codex's).
_QUOTA_CAP_RE = re.compile(
    r"usage limit|session limit|hit your (?:usage|rate|session) limit|"
    r"purchase more credits|upgrade to pro|"
    r"\bquota\b|out of credits|insufficient.*credit|payment required|\bbilling\b|rate limit",
    re.IGNORECASE,
)
# "try again at 8:47 PM" / "resets at 14:30" — the reset clock the bridge surfaces.
_CAP_RESET_RE = re.compile(
    # A clock needs :MM or an am/pm suffix — a bare number ("again 30 minutes
    # later") must not parse as an hour-of-day.
    r"(?:try again|reset[s]?|again)\s+(?:at\s+)?"
    r"(\d{1,2})(?::(\d{2})\s*([ap]\.?m\.?)?|\s*([ap]\.?m\.?))",
    re.IGNORECASE,
)
# How long to assume a cap lasts when the message gives no clock (conservative so
# the breaker self-clears rather than wedging a provider off forever).
_CAP_DEFAULT_COOLDOWN_MS = 3_600_000  # 1 hour
_CAP_DEFAULT_COOLDOWN_BY_PROVIDER_MS: dict[str, int] = {}
# Lookback for "how much did Agents Chat itself use" in the reconciliation line.
_CAP_INAPP_LOOKBACK_MS = 5 * 3_600_000  # 5h (ChatGPT's short rolling window)


def _is_quota_cap_message(message: str) -> bool:
    return bool(message) and bool(_QUOTA_CAP_RE.search(message))


def _parse_cap_reset_ms(
    message: str,
    now_ms: Optional[int] = None,
    default_cooldown_ms: int = _CAP_DEFAULT_COOLDOWN_MS,
) -> int:
    """Best-effort: turn a '…try again at 8:47 PM' into an absolute epoch-ms reset.
    Falls back to now + default cooldown when no clock is present. Never raises."""
    now_ms = now_ms if now_ms is not None else int(time.time() * 1000)
    try:
        m = _CAP_RESET_RE.search(message or "")
        if not m:
            return now_ms + int(default_cooldown_ms)
        hh, mm = int(m.group(1)), int(m.group(2) or 0)
        ampm = ((m.group(3) or m.group(4)) or "").lower().replace(".", "")
        if ampm == "pm" and hh != 12:
            hh += 12
        elif ampm == "am" and hh == 12:
            hh = 0
        if not (0 <= hh <= 23 and 0 <= mm <= 59):
            return now_ms + int(default_cooldown_ms)
        now_dt = datetime.fromtimestamp(now_ms / 1000)
        target = now_dt.replace(hour=hh, minute=mm, second=0, microsecond=0)
        if target <= now_dt:  # clock time already passed today → it's tomorrow
            target += timedelta(days=1)
        return int(target.timestamp() * 1000)
    except Exception:
        return now_ms + int(default_cooldown_ms)


# What one cache-read token costs against a rolling safety budget, relative to a
# fresh input token. Anthropic bills cache reads at 0.1x list; the other bridges
# discount them similarly.
_ROLLING_CACHE_READ_WEIGHT = 0.1
# `token_usage.input_tokens` is ALL-IN — it folds cache reads and creates in, so
# the cost dashboard doesn't undercount cache-heavy turns. Budget arithmetic must
# not meter it that way: an agentic Claude turn is ~85% cache reads, and counting
# those 1:1 tripped the guard roughly 5x early (2026-08-20: 1546K "used" against
# a 1.2M budget, of which 1245K were cache reads). So back the reads out and
# re-add them discounted. `cached_tokens` is a subset of `input_tokens` for every
# provider. Cache CREATES stay at full weight — they bill at a premium and are
# not counted in `cached_tokens`.
#
# The rolling guard and the cap-attribution number below share this expression on
# purpose: _learned_provider_budget calibrates a budget from a cap event's in-app
# number and _provider_rolling_usage then meters against it. Two units there would
# make every learned budget several times too permissive.
_WEIGHTED_TOKENS_SQL = (
    "MAX(input_tokens - cached_tokens, 0) + output_tokens "
    f"+ MIN(cached_tokens, input_tokens) * {_ROLLING_CACHE_READ_WEIGHT}"
)


def _provider_inapp_tokens_since(provider: str, since_ms: int) -> int:
    """Tokens (in+out) Agents Chat itself billed to this provider since since_ms.

    Cache reads count at _ROLLING_CACHE_READ_WEIGHT — see _WEIGHTED_TOKENS_SQL.
    """
    try:
        with _db() as conn:
            row = conn.execute(
                f"SELECT COALESCE(SUM({_WEIGHTED_TOKENS_SQL}), 0) AS t "
                "FROM token_usage WHERE provider=? AND ts>=?",
                (provider, int(since_ms)),
            ).fetchone()
        return int(row["t"] or 0) if row else 0
    except Exception:
        return 0


_ADAPTIVE_GUARD_LOOKBACK_MS = 30 * 86_400_000
_ADAPTIVE_GUARD_MIN_SIGNAL_TOKENS = 250_000
_ADAPTIVE_GUARD_HEADROOM = 0.70
_ADAPTIVE_GUARD_ROUND_TOKENS = 50_000


def _learned_provider_budget(provider: str, now_ms: Optional[int] = None) -> int:
    """Learn a conservative guard from meaningful real caps in the last 30d.

    Very small in-app counts mean the account was probably consumed elsewhere;
    using those as a token calibration would disable Agent Chat after a handful
    of tokens. Such caps remain circuit-breaker evidence, but are deliberately
    not converted into a token budget.
    """
    now_ms = int(now_ms or time.time() * 1000)
    try:
        with _db() as conn:
            row = conn.execute(
                "SELECT MAX(in_app_tokens) AS in_app_tokens FROM usage_events "
                "WHERE provider=? AND kind='cap' AND ts>=? AND in_app_tokens>=? ",
                (provider, now_ms - _ADAPTIVE_GUARD_LOOKBACK_MS,
                 _ADAPTIVE_GUARD_MIN_SIGNAL_TOKENS),
            ).fetchone()
        observed = int(row["in_app_tokens"] or 0) if row else 0
        if observed < _ADAPTIVE_GUARD_MIN_SIGNAL_TOKENS:
            return 0
        learned = int(observed * _ADAPTIVE_GUARD_HEADROOM)
        learned = (learned // _ADAPTIVE_GUARD_ROUND_TOKENS) * _ADAPTIVE_GUARD_ROUND_TOKENS
        return max(_ADAPTIVE_GUARD_MIN_SIGNAL_TOKENS, learned)
    except Exception:
        return 0


def _provider_rolling_budget_detail(
    provider: str, now_ms: Optional[int] = None,
) -> tuple[int, float, str]:
    meta = (_usage_settings().get("subscriptions") or {}).get(provider) or {}
    try:
        budget = max(0, int(meta.get("rolling_budget_tokens") or 0))
        hours = max(1.0, float(meta.get("rolling_window_hours") or 5.0))
    except (TypeError, ValueError):
        return 0, 5.0, "monitoring"
    if budget > 0:
        return budget, hours, "configured"
    if bool(meta.get("adaptive_guard", False)) and meta.get("kind") == "subscription":
        learned = _learned_provider_budget(provider, now_ms)
        if learned > 0:
            return learned, hours, "learned"
        return 0, hours, "learning"
    return 0, hours, "off"


def _provider_rolling_budget(provider: str) -> tuple[int, float]:
    budget, hours, _source = _provider_rolling_budget_detail(provider)
    return budget, hours


def _provider_rolling_usage(provider: str, now_ms: Optional[int] = None) -> dict:
    """Measured app usage and when the oldest token row leaves this window."""
    now_ms = int(now_ms or time.time() * 1000)
    budget, hours, source = _provider_rolling_budget_detail(provider, now_ms)
    window_ms = int(hours * 3_600_000)
    since = now_ms - window_ms
    try:
        with _db() as conn:
            row = conn.execute(
                # Cache reads are metered at _ROLLING_CACHE_READ_WEIGHT here —
                # see _WEIGHTED_TOKENS_SQL for why the guard can't use the all-in
                # `input_tokens` the cost dashboard shows.
                f"SELECT COALESCE(SUM({_WEIGHTED_TOKENS_SQL}), 0) AS t, "
                "MIN(ts) AS oldest FROM token_usage WHERE provider=? AND ts>=?",
                (provider, since),
            ).fetchone()
        tokens = int(row["t"] or 0) if row else 0
        oldest = int(row["oldest"]) if row and row["oldest"] is not None else None
    except Exception:
        tokens, oldest = 0, None
    return {
        "provider": provider, "tokens": tokens, "budget_tokens": budget,
        "window_hours": hours, "budget_source": source,
        "pct": round(tokens / budget * 100, 1) if budget else None,
        "reset_ts": (oldest + window_ms) if oldest is not None else now_ms + window_ms,
    }


def _record_cap_event(provider: str, agent_id: str, owner_id: Optional[int],
                      reset_ms: Optional[int], in_app_tokens: int, message: str,
                      kind: str = "cap") -> None:
    try:
        with _db() as conn:
            conn.execute(
                "INSERT INTO usage_events(ts, provider, agent_id, owner_user_id, "
                "kind, reset_ts, in_app_tokens, message) VALUES (?,?,?,?,?,?,?,?)",
                (int(time.time() * 1000), provider, agent_id or "", owner_id,
                 kind, int(reset_ms) if reset_ms is not None else None,
                 int(in_app_tokens), (message or "")[:500]),
            )
    except Exception:
        logger.exception("usage_events: failed to record cap for %s", provider)


async def _usage_budget_short_circuit(agent: dict, cid: int) -> bool:
    """Stop a provider before Agent Chat exceeds its configured rolling guard."""
    provider = _provider_for_agent(agent.get("id", ""))
    roll = _provider_rolling_usage(provider)
    budget = int(roll["budget_tokens"] or 0)
    if budget <= 0 or int(roll["tokens"] or 0) < budget:
        return False
    label = (_usage_settings()["subscriptions"].get(provider) or {}).get(
        "label", provider.title(),
    )
    reset_ms = int(roll["reset_ts"])
    text = (
        f"🛑 {label} safety budget reached: "
        f"{int(roll['tokens']) / 1000:.0f}K of {budget / 1000:.0f}K tokens in "
        f"the rolling {float(roll['window_hours']):g}h window. Agent Chat paused "
        f"{agent.get('name', 'this agent')} until usage rolls off around "
        f"{_fmt_clock(reset_ms)}. You can tune this guard in Usage & cost."
    )
    try:
        with _db() as conn:
            active = conn.execute(
                "SELECT 1 FROM usage_events WHERE provider=? AND kind='budget_guard' "
                "AND reset_ts>? ORDER BY ts DESC LIMIT 1",
                (provider, int(time.time() * 1000)),
            ).fetchone()
        if not active:
            _record_cap_event(
                provider, agent.get("id", ""), _chat_owner_id(cid), reset_ms,
                int(roll["tokens"]), text, kind="budget_guard",
            )
    except Exception:
        logger.exception("usage budget event failed for %s", provider)
    meta = {
        "kind": "budget_guard", "provider": provider,
        "agent_id": agent.get("id", ""), "reset_ms": reset_ms,
        "rolling_tokens": int(roll["tokens"]), "budget_tokens": budget,
    }
    entry = append_thread(
        cid, "system", agent.get("id") or None, "system", text, metadata=meta,
    )
    await broadcast({
        "type": "system", "chat_id": cid, "level": "warn",
        "text": text, "ts": entry["ts"], "metadata": meta,
    })
    return True


def _provider_capped_until(provider: str) -> Optional[int]:
    """The reset_ts of the most recent still-active cap for this provider, or None.
    Fail-open: any error returns None so the breaker never blocks a turn on a bug."""
    try:
        now_ms = int(time.time() * 1000)
        with _db() as conn:
            row = conn.execute(
                "SELECT reset_ts FROM usage_events WHERE provider=? AND kind='cap' "
                "AND reset_ts>? ORDER BY ts DESC, id DESC LIMIT 1",
                (provider, now_ms),
            ).fetchone()
        return int(row["reset_ts"]) if row and row["reset_ts"] else None
    except Exception:
        return None


# --- Self-healing breaker: probe + clear -----------------------------------
# A cap's reset_ts is only a GUESS parsed from the bridge's "try again at …"
# text. If the account is reset / topped-up / swapped before then, that guess is
# stale and the breaker would wedge the provider off until the wrong clock
# passes (the "I reset codex but the app won't pick it up" bug). So while a cap
# is active we let ONE real call through every _CAP_PROBE_INTERVAL_MS: if it
# succeeds the success path clears the cap; if it caps again the bridge records a
# fresh one. Probe cadence is tracked per-provider in app_settings.
_CAP_PROBE_INTERVAL_MS = 10 * 60_000  # 10 min
_CAP_PROBE_INTERVAL_BY_PROVIDER_MS: dict[str, int] = {}


def _cap_probe_key(provider: str) -> str:
    return f"cap.probe.{provider}"


def _cap_should_probe(provider: str, now_ms: int) -> bool:
    """True if it's time to let one real call through to test whether the cap
    actually lifted (vs. waiting out the guessed reset clock)."""
    try:
        last = int(_get_setting(_cap_probe_key(provider), "0") or "0")
    except (TypeError, ValueError):
        last = 0
    interval = _CAP_PROBE_INTERVAL_BY_PROVIDER_MS.get(provider, _CAP_PROBE_INTERVAL_MS)
    return (now_ms - last) >= interval


def _cap_mark_probe(provider: str, now_ms: int) -> None:
    try:
        _set_setting(_cap_probe_key(provider), str(int(now_ms)))
    except Exception:
        logger.exception("cap probe-mark failed for %s", provider)


def _clear_provider_cap(provider: str, now_ms: Optional[int] = None) -> int:
    """Expire every still-active cap row for a provider (a probe succeeded, or the
    user manually cleared it). Preserves the audit rows; returns rows expired."""
    now_ms = now_ms if now_ms is not None else int(time.time() * 1000)
    n = 0
    try:
        with _db() as conn:
            cur = conn.execute(
                "UPDATE usage_events SET reset_ts=? "
                "WHERE provider=? AND kind='cap' AND reset_ts>?",
                (now_ms - 1, provider, now_ms),
            )
            n = cur.rowcount or 0
    except Exception:
        logger.exception("clear provider cap failed for %s", provider)
    try:
        _set_setting(_cap_probe_key(provider), "0")
    except Exception:
        pass
    return n


def _fmt_clock(ms: int) -> str:
    try:
        return datetime.fromtimestamp(int(ms) / 1000).strftime("%-I:%M %p")
    except Exception:
        return "soon"


def _cap_card_text(provider: str, reset_ms: int, in_app_tokens: int) -> str:
    """The reconciliation sentence without guessing the provider's total burn."""
    label = (_USAGE_SUBS_DEFAULTS.get(provider, {}) or {}).get("label", provider.title())
    when = _fmt_clock(reset_ms)
    if in_app_tokens < 1000:
        usage_note = (
            "Agents Chat has used almost none of this account recently, so the "
            "limit was likely reached in another app, CLI, or web session"
        )
    else:
        k = in_app_tokens / 1000.0
        amt = f"{k:.0f}K" if k >= 1 else f"{in_app_tokens}"
        usage_note = (
            f"Agents Chat recorded ~{amt} tokens here in the last 5h; the provider "
            "may also count other apps, CLI, or web sessions on the same plan"
        )
    return (
        f"⚠️ {label} usage limit reached — resets around {when}. {usage_note}. "
        f"Pausing this agent until it resets."
    )


async def _post_cap_card(cid: int, agent: dict, text: str, severity: str = "warn",
                         provider: Optional[str] = None,
                         reset_ms: Optional[int] = None) -> None:
    """Post the cap card into the chat AND raise a global attention banner + push.
    The card carries kind='cap' metadata so the client renders a one-click
    'I reset it — clear cap' override alongside the automatic ~10-min probe."""
    agent_id = agent.get("id") or ""
    if not provider:
        provider = _provider_for_agent(agent_id)
    meta = {"kind": "cap", "provider": provider, "agent_id": agent_id,
            "agent_name": agent.get("name", ""), "reset_ms": reset_ms,
            "resolved": False}
    try:
        sys_entry = append_thread(cid, "system", agent_id or None,
                                  agent.get("name", "system"), text, metadata=meta)
        await broadcast({
            "type": "cap", "chat_id": cid, "level": "warn",
            "text": text, "ts": sys_entry["ts"], **meta,
        })
    except Exception:
        logger.exception("cap card: in-chat post failed")
    try:
        await _emit_notification(
            cid, event="attention",
            title=f"{agent.get('name', 'An agent')}: usage limit",
            body=text, severity=severity, agent_id=agent.get("id"), push=True,
        )
    except Exception:
        logger.exception("cap card: notification failed")
    try:
        if TELEGRAM_ENABLED:
            await _tg_send("🔔 " + text)
    except Exception:
        logger.exception("cap card: telegram ping failed")


async def _handle_quota_cap(
    agent: dict,
    cid: int,
    message: str,
    *,
    provider_hint: str = "",
    limit_scope: str = "",
) -> None:
    """FLAG + record a freshly-detected quota cap. Fail-open: never raises."""
    try:
        agent_provider = _provider_for_agent(agent.get("id", ""))
        provider = str(provider_hint or agent_provider).strip().lower()
        if not provider_hint and re.search(r"\btavily\b|web search failed", message, re.I):
            provider, limit_scope = "tavily", "tool"
        now_ms = int(time.time() * 1000)
        if limit_scope == "tool" or provider != agent_provider:
            owner_id = _chat_owner_id(cid)
            _record_cap_event(
                provider or "tool", agent.get("id", ""), owner_id,
                None, 0, message, kind="tool_cap",
            )
            label = (_USAGE_SUBS_DEFAULTS.get(provider, {}) or {}).get(
                "label", (provider or "Tool").title(),
            )
            text = (
                f"⚠️ {label} reached its own usage limit while "
                f"{agent.get('name', 'the agent')} was working. "
                f"{agent.get('name', 'The agent')} itself is not capped, and its "
                "other tools remain available."
            )
            entry = append_thread(
                cid, "system", agent.get("id") or None, "system", text,
                metadata={
                    "kind": "tool_cap", "provider": provider or "tool",
                    "agent_id": agent.get("id", ""), "reset_ms": None,
                },
            )
            await broadcast({
                "type": "system", "chat_id": cid, "level": "warn",
                "text": text, "ts": entry["ts"],
            })
            return
        reset_ms = _parse_cap_reset_ms(
            message,
            now_ms,
            _CAP_DEFAULT_COOLDOWN_BY_PROVIDER_MS.get(
                provider, _CAP_DEFAULT_COOLDOWN_MS
            ),
        )
        in_app = _provider_inapp_tokens_since(provider, now_ms - _CAP_INAPP_LOOKBACK_MS)
        owner_id = _chat_owner_id(cid)
        _record_cap_event(provider, agent.get("id", ""), owner_id, reset_ms, in_app, message)
        # Anchor the probe clock to now so the first self-heal probe waits a full
        # interval (don't immediately re-spend a doomed call right after capping).
        _cap_mark_probe(provider, now_ms)
        await _post_cap_card(cid, agent, _cap_card_text(provider, reset_ms, in_app),
                             provider=provider, reset_ms=reset_ms)
    except Exception:
        logger.exception("quota cap handling failed for chat %s", cid)


async def _cap_short_circuit(agent: dict, cid: int) -> bool:
    """CORRECT: if the agent's provider is already capped, post the card and tell
    the caller to skip the (doomed, token-wasting) bridge call. Fail-open → False.

    Self-healing: a cap's reset_ts is a guess. So every _CAP_PROBE_INTERVAL_MS we
    let ONE real call through (return False) to test whether the cap has actually
    lifted — if it has, the success path clears it; if not, the bridge re-arms the
    breaker. Between probes we keep short-circuiting to avoid burning failed calls."""
    try:
        provider = _provider_for_agent(agent.get("id", ""))
        reset_ms = _provider_capped_until(provider)
        if not reset_ms:
            return False
        now_ms = int(time.time() * 1000)
        if _cap_should_probe(provider, now_ms):
            _cap_mark_probe(provider, now_ms)  # one probe per interval
            return False
        in_app = _provider_inapp_tokens_since(provider, now_ms - _CAP_INAPP_LOOKBACK_MS)
        await _post_cap_card(cid, agent, _cap_card_text(provider, reset_ms, in_app),
                             provider=provider, reset_ms=reset_ms)
        return True
    except Exception:
        logger.exception("cap short-circuit check failed for chat %s", cid)
        return False


async def _cap_clear_on_success(agent: dict, cid: int) -> None:
    """A real reply came back, so the provider's cap has lifted (a probe got
    through, or the user reset / topped up early). Expire any active cap and post a
    one-line 'recovered' note — but only when a cap was actually active, so normal
    turns stay silent. Fail-open: never raises into the turn."""
    try:
        provider = _provider_for_agent(agent.get("id", ""))
        if not _provider_capped_until(provider):
            return  # no active cap → nothing to do, stay quiet
        _clear_provider_cap(provider)
        label = (_USAGE_SUBS_DEFAULTS.get(provider, {}) or {}).get("label", provider.title())
        text = (f"✅ {label} is responding again — usage cap cleared. "
                f"{agent.get('name', 'The agent')} is back online.")
        sys_entry = append_thread(cid, "system", None, "system", text)
        await broadcast({"type": "system", "chat_id": cid, "level": "info",
                         "text": text, "ts": sys_entry["ts"]})
        await broadcast({"type": "cap_cleared", "chat_id": cid, "provider": provider})
    except Exception:
        logger.exception("cap clear-on-success failed for chat %s", cid)


def _detach_orphan_token_usage() -> int:
    """One-time: point token_usage rows whose chat is already gone at the NULL
    ("unattributed") bucket.

    Chats deleted before spend was made durable left rows referencing dead chat
    ids, so per-chat rollups silently dropped that money while the grand total
    still counted it — the ledger didn't balance. Normalizing them to NULL puts
    the spend in the same bucket a deletion produces today. Idempotent via a
    meta flag; the spend itself is never destroyed."""
    try:
        with _db() as conn:
            if conn.execute(
                "SELECT 1 FROM meta WHERE key='token_usage_orphan_detach'"
            ).fetchone():
                return 0
            cur = conn.execute(
                "UPDATE token_usage SET chat_id=NULL WHERE chat_id IS NOT NULL "
                "AND chat_id NOT IN (SELECT id FROM chats)"
            )
            n = int(cur.rowcount or 0)
            conn.execute(
                "INSERT OR REPLACE INTO meta(key,value) VALUES('token_usage_orphan_detach', ?)",
                (str(int(time.time() * 1000)),))
        if n:
            logger.info("token_usage: detached %s orphaned rows to the unattributed bucket", n)
        return n
    except Exception:
        logger.exception("token usage orphan detach failed")
        return 0


def _clamp_historical_run_durations() -> int:
    """One-time: repair run durations recorded by the pre-clamp boot reconcile.

    That path stamped finished_ts = now on every still-'running' row, so a run
    whose process died in June and was first reconciled at an August boot recorded
    an 18-day runtime. Those rows are the only reason the duration percentiles
    read in days against a real median of ~3.5 minutes. Clamp them to the same
    ceiling the live path now applies. Idempotent via a meta flag."""
    try:
        with _db() as conn:
            if conn.execute(
                "SELECT 1 FROM meta WHERE key='run_duration_clamp'"
            ).fetchone():
                return 0
            cur = conn.execute(
                "UPDATE automation_runs SET finished_ts = started_ts + ?, "
                "error = CASE WHEN error='' "
                "THEN 'duration clamped (process died mid-run, closed at a later boot)' "
                "ELSE error END "
                "WHERE finished_ts IS NOT NULL AND started_ts IS NOT NULL "
                "AND finished_ts - started_ts > ?",
                (AUTOMATION_MAX_RUNTIME_MS, AUTOMATION_MAX_RUNTIME_MS),
            )
            n = int(cur.rowcount or 0)
            conn.execute(
                "INSERT OR REPLACE INTO meta(key,value) VALUES('run_duration_clamp', ?)",
                (str(int(time.time() * 1000)),))
        if n:
            logger.info("automation_runs: clamped %s implausible run duration(s)", n)
        return n
    except Exception:
        logger.exception("run duration clamp failed")
        return 0


def _backfill_automation_run_cost() -> int:
    """One-time: price historical runs that closed while _automation_run_cost()
    still returned a hardcoded $0.

    Only runs whose chat still exists can be repriced — a deleted chat's spend now
    lives in the unattributed bucket with no chat_id to window on, so those stay 0
    rather than being guessed at. Idempotent via a meta flag."""
    try:
        with _db() as conn:
            if conn.execute(
                "SELECT 1 FROM meta WHERE key='automation_cost_backfill'"
            ).fetchone():
                return 0
            rows = conn.execute(
                "SELECT id, chat_id, started_ts, finished_ts FROM automation_runs "
                "WHERE cost_usd=0 AND chat_id IS NOT NULL "
                "AND chat_id IN (SELECT id FROM chats)"
            ).fetchall()
            fixed = 0
            for r in rows:
                end = int(r["finished_ts"] or r["started_ts"] or 0)
                toks, usd = _automation_run_cost(
                    conn, r["chat_id"], int(r["started_ts"] or 0), end)
                if usd > 0:
                    conn.execute(
                        "UPDATE automation_runs SET cost_tokens=?, cost_usd=? WHERE id=?",
                        (int(toks), float(usd), int(r["id"])))
                    fixed += 1
            conn.execute(
                "INSERT OR REPLACE INTO meta(key,value) VALUES('automation_cost_backfill', ?)",
                (str(int(time.time() * 1000)),))
        if fixed:
            logger.info("automation_runs: backfilled USD cost on %s runs", fixed)
        return fixed
    except Exception:
        logger.exception("automation run cost backfill failed")
        return 0


def _backfill_token_usage() -> None:
    """One-time: estimate token usage for the existing message history so the
    dashboard isn't empty on first open. Idempotent via a meta flag; all rows
    land as source='estimated'."""
    try:
        with _db() as conn:
            if conn.execute(
                "SELECT 1 FROM meta WHERE key='token_usage_backfill'"
            ).fetchone():
                return
            if conn.execute("SELECT 1 FROM token_usage LIMIT 1").fetchone():
                conn.execute(
                    "INSERT OR REPLACE INTO meta(key,value) VALUES('token_usage_backfill', ?)",
                    (str(int(time.time() * 1000)),))
                return
            owners = {
                r["id"]: r["owner_user_id"]
                for r in conn.execute("SELECT id, owner_user_id FROM chats").fetchall()
            }
            rows = conn.execute(
                "SELECT id, chat_id, role, agent_id, text, ts, metadata_json "
                "FROM messages ORDER BY chat_id, id"
            ).fetchall()
            from collections import deque, defaultdict
            ctx: "dict[int, deque]" = defaultdict(lambda: deque(maxlen=24))
            batch = []
            for r in rows:
                cid = r["chat_id"]
                txt = r["text"] or ""
                if r["role"] == "agent" and r["agent_id"]:
                    try:
                        md = json.loads(r["metadata_json"] or "{}")
                    except Exception:
                        md = {}
                    model = (md.get("model") if isinstance(md, dict) else "") or ""
                    out = max(1, round(len(txt) / 4))
                    inp = (max(1, round(sum(ctx[cid]) / 4)) if ctx[cid] else out)
                    batch.append((
                        r["ts"], cid, owners.get(cid), r["agent_id"], model,
                        _provider_for_agent(r["agent_id"], model), inp, out, 0, 0,
                        "estimated", r["id"]))
                ctx[cid].append(len(txt))
            if batch:
                conn.executemany(
                    "INSERT INTO token_usage(ts,chat_id,owner_user_id,agent_id,model,"
                    "provider,input_tokens,output_tokens,cached_tokens,reasoning_tokens,"
                    "source,msg_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)", batch)
            conn.execute(
                "INSERT OR REPLACE INTO meta(key,value) VALUES('token_usage_backfill', ?)",
                (str(int(time.time() * 1000)),))
            logger.info("token usage backfill: inserted %d estimated rows", len(batch))
    except Exception:
        logger.exception("token usage backfill failed")


def _usage_settings() -> dict:
    subs = {k: dict(v) for k, v in _USAGE_SUBS_DEFAULTS.items()}
    if community_mode():
        # We cannot know which plans a new owner actually pays for. Starting at
        # the maintainer's illustrative $170/mo made a fresh install claim a
        # personal cost that was never configured. Keep provider labels/rates,
        # but require the owner to enter subscription and credit amounts.
        for detail in subs.values():
            detail["monthly_usd"] = 0.0
            if detail.get("kind") == "credits":
                detail["credit_balance"] = 0.0
    try:
        raw = _get_setting("usage.settings", "")
        if raw:
            data = json.loads(raw)
            for prov, ov in (data.get("subscriptions") or {}).items():
                d = subs.get(prov, {"label": prov.title(), "kind": "subscription",
                                    "monthly_usd": 0.0, "cap_tokens": 0})
                if "monthly_usd" in ov:
                    d["monthly_usd"] = max(0.0, float(ov["monthly_usd"]))
                if "cap_tokens" in ov:
                    d["cap_tokens"] = max(0, int(ov["cap_tokens"]))
                if "credit_balance" in ov:
                    d["credit_balance"] = max(0.0, float(ov["credit_balance"]))
                if "rolling_budget_tokens" in ov:
                    d["rolling_budget_tokens"] = max(0, int(ov["rolling_budget_tokens"]))
                if "rolling_window_hours" in ov:
                    d["rolling_window_hours"] = max(1.0, float(ov["rolling_window_hours"]))
                if "adaptive_guard" in ov:
                    d["adaptive_guard"] = bool(ov["adaptive_guard"])
                if "kind" in ov and ov["kind"] in ("subscription", "credits"):
                    d["kind"] = ov["kind"]
                if "label" in ov:
                    d["label"] = str(ov["label"])
                subs[prov] = d
    except Exception:
        logger.exception("usage settings parse failed")
    return {"subscriptions": subs}


def _usage_report(owner_id: int, is_admin: bool, rng: str) -> dict:
    now = int(time.time() * 1000)
    since, label, canonical = _resolve_usage_window(rng, now)
    subs = _usage_settings()["subscriptions"]
    credit_provs = [p for p, m in subs.items() if m.get("kind") == "credits"]
    own_clause = "" if is_admin else " AND owner_user_id = ?"

    def _params(base):
        p = list(base)
        if not is_admin:
            p.append(owner_id)
        return p

    credit_spent: dict[str, float] = {}
    with _db() as conn:
        oldest_row = conn.execute(
            f"SELECT MIN(ts) oldest FROM token_usage WHERE 1=1{own_clause}",
            _params([]),
        ).fetchone()
        rows = conn.execute(
            "SELECT agent_id, model, provider, SUM(input_tokens) i, SUM(output_tokens) o, "
            "SUM(cached_tokens) c, COUNT(*) n, SUM(model_calls) calls, "
            "SUM(CASE WHEN source='estimated' THEN 1 ELSE 0 END) est "
            f"FROM token_usage WHERE ts >= ?{own_clause} GROUP BY agent_id, model, provider",
            _params([since]),
        ).fetchall()
        cycle = conn.execute(
            "SELECT provider, SUM(input_tokens + output_tokens) t FROM token_usage "
            f"WHERE ts >= ?{own_clause} GROUP BY provider",
            _params([now - _USAGE_MONTH_MS]),
        ).fetchall()
        burn = conn.execute(
            "SELECT provider, SUM(input_tokens + output_tokens) t FROM token_usage "
            f"WHERE ts >= ?{own_clause} GROUP BY provider",
            _params([now - 3_600_000]),
        ).fetchall()
        agent_burn = conn.execute(
            "SELECT agent_id, SUM(input_tokens + output_tokens) t FROM token_usage "
            f"WHERE ts >= ?{own_clause} GROUP BY agent_id",
            _params([now - 3_600_000]),
        ).fetchall()
        usage_events = conn.execute(
            "SELECT ts, provider, agent_id, kind, reset_ts FROM usage_events "
            f"WHERE (ts >= ? OR reset_ts > ?){own_clause} ORDER BY ts DESC LIMIT 30",
            _params([now - 86_400_000, now]),
        ).fetchall()
        # When did live metering begin? The backfill marker is stamped the first
        # time the feature ran, so it's the honest "we started measuring here".
        meta_start = conn.execute(
            "SELECT value FROM meta WHERE key='token_usage_backfill'"
        ).fetchone()
        # Prepaid "credits" providers (e.g. DeepSeek) draw down a balance over
        # their whole lifetime, not a 30d window — sum all-time $ spent so the
        # dashboard can show the burn-down of the credit pool.
        if credit_provs:
            qm = ",".join("?" * len(credit_provs))
            crows = conn.execute(
                "SELECT provider, model, SUM(input_tokens) i, SUM(output_tokens) o, "
                f"SUM(cached_tokens) c FROM token_usage WHERE provider IN ({qm}){own_clause} "
                "GROUP BY provider, model",
                _params(list(credit_provs)),
            ).fetchall()
            for cr in crows:
                rt = _price_for_model(cr["model"], cr["provider"])
                ci, co, cc = int(cr["i"] or 0), int(cr["o"] or 0), int(cr["c"] or 0)
                spent = (max(ci - cc, 0) * rt["in"] + cc * rt["cached"] + co * rt["out"]) / 1e6
                credit_spent[cr["provider"]] = credit_spent.get(cr["provider"], 0.0) + spent

    cycle_tok = {r["provider"]: int(r["t"] or 0) for r in cycle}
    burn_tok = {r["provider"]: int(r["t"] or 0) for r in burn}
    agent_burn_tok = {r["agent_id"]: int(r["t"] or 0) for r in agent_burn}
    try:
        oldest_ms = int(oldest_row["oldest"]) if oldest_row and oldest_row["oldest"] is not None else None
    except (TypeError, ValueError):
        oldest_ms = None
    # All-time (and any window that starts before the first row) amortizes over
    # the recorded span, not an invented eternity.
    effective_since = since
    if canonical == "all" or since <= 0:
        effective_since = oldest_ms if oldest_ms is not None else now
        if oldest_ms is not None:
            label = "all recorded (since " + _usage_day_label(
                datetime.fromtimestamp(oldest_ms / 1000.0)) + ")"
    elif oldest_ms is not None and since < oldest_ms:
        effective_since = oldest_ms
        label = label + " (recorded from " + _usage_day_label(
            datetime.fromtimestamp(oldest_ms / 1000.0)) + ")"
    win_ms = max(1, now - int(effective_since))

    # The subs-vs-API verdict is only honest once a full billing cycle of data has
    # accrued — before that, a full month's subscription fee is being weighed
    # against just a few days of usage, which makes subs look far too expensive.
    # Until BASELINE_DAYS of metering exist, mark the report provisional.
    try:
        metering_start = int(meta_start["value"]) if meta_start else now
    except (TypeError, ValueError):
        metering_start = now
    coverage_days = max(0.0, (now - metering_start) / 86_400_000)
    provisional = coverage_days < _USAGE_BASELINE_DAYS
    verdict_ready_ms = metering_start + _USAGE_BASELINE_DAYS * 86_400_000

    agents: dict[str, dict] = {}
    providers: dict[str, dict] = {}
    tot_tok = tot_api = 0.0
    tot_in = tot_out = tot_cached = tot_n = tot_est = 0
    for r in rows:
        aid = r["agent_id"]
        i, o, c = int(r["i"] or 0), int(r["o"] or 0), int(r["c"] or 0)
        # Resolve the live provider for the agent (history may carry a stale
        # provider on the row — e.g. lead/sales before the DeepSeek remap).
        prov = _provider_for_agent(aid, r["model"]) or r["provider"]
        rates = _price_for_model(r["model"], prov)
        api_cost = (max(i - c, 0) * rates["in"] + c * rates["cached"] + o * rates["out"]) / 1e6
        ag = agents.setdefault(aid, {
            "id": aid,
            "name": (AGENTS_BY_ID.get(aid, {}) or {}).get("name", aid.title()),
            "color": (AGENTS_BY_ID.get(aid, {}) or {}).get("color", "#8b9bb4"),
            "provider": prov, "model": r["model"] or "",
            "tokens": 0, "input": 0, "output": 0, "cached": 0,
            "api_cost": 0.0, "n": 0, "model_calls": 0, "est": 0,
        })
        ag["tokens"] += i + o
        ag["input"] += i
        ag["output"] += o
        ag["cached"] += c
        ag["api_cost"] += api_cost
        ag["n"] += int(r["n"] or 0)
        ag["model_calls"] += int(r["calls"] or 0)
        ag["est"] += int(r["est"] or 0)
        if r["model"]:
            ag["model"] = r["model"]
        pr = providers.setdefault(prov, {"provider": prov, "tokens": 0, "api_cost": 0.0})
        pr["tokens"] += i + o
        pr["api_cost"] += api_cost
        tot_tok += i + o
        tot_api += api_cost
        tot_in += i
        tot_out += o
        tot_cached += c
        tot_n += int(r["n"] or 0)
        tot_est += int(r["est"] or 0)

    win_frac = win_ms / _USAGE_MONTH_MS
    # Subscriptions are amortized across the window; credits providers cost their
    # actual metered token spend this window (no amortization — they ARE API).
    sub_total_month = sum(
        float(s.get("monthly_usd") or 0)
        for s in subs.values() if s.get("kind") != "credits")
    sub_amortized = sub_total_month * win_frac
    credits_window = sum(
        providers.get(p, {}).get("api_cost", 0.0)
        for p, m in subs.items() if m.get("kind") == "credits")
    your_cost = sub_amortized + credits_window

    prov_out = []
    for prov, meta in subs.items():
        is_credits = meta.get("kind") == "credits"
        cap = int(meta.get("cap_tokens") or 0)
        ctok = cycle_tok.get(prov, 0)
        b_min = burn_tok.get(prov, 0) / 60.0
        pcost = round(providers.get(prov, {}).get("api_cost", 0.0), 4)
        entry = {
            "provider": prov,
            "label": meta.get("label", prov.title()),
            "kind": meta.get("kind", "subscription"),
            "monthly_usd": float(meta.get("monthly_usd") or 0),
            # Credits cost their actual spend this window; subs amortize the fee.
            "window_cost": pcost if is_credits else float(meta.get("monthly_usd") or 0) * win_frac,
            "tokens": providers.get(prov, {}).get("tokens", 0),
            "api_cost": pcost,
            "cap_tokens": cap,
            "cycle_tokens": ctok,
            "burn_per_min": round(b_min, 1),
            "cap_pct": round(ctok / cap * 100, 1) if cap > 0 else None,
            "minutes_to_cap": (round((cap - ctok) / b_min) if cap > 0 and b_min > 0 and cap > ctok else None),
        }
        rolling = _provider_rolling_usage(prov, now)
        entry.update({
            "rolling_tokens": rolling["tokens"],
            "rolling_budget_tokens": rolling["budget_tokens"],
            "rolling_window_hours": rolling["window_hours"],
            "rolling_budget_source": rolling["budget_source"],
            "rolling_pct": rolling["pct"],
            "rolling_reset_ts": rolling["reset_ts"],
        })
        if is_credits:
            bal = float(meta.get("credit_balance") or 0)
            spent = round(credit_spent.get(prov, 0.0), 4)
            entry["credit_balance"] = bal
            entry["credit_spent"] = spent
            entry["credit_remaining"] = round(max(bal - spent, 0.0), 2)
            entry["credit_pct"] = round(spent / bal * 100, 1) if bal > 0 else None
        prov_out.append(entry)
    prov_out.sort(key=lambda p: p["tokens"], reverse=True)

    agent_list = sorted(agents.values(), key=lambda a: a["tokens"], reverse=True)
    for a in agent_list:
        a["api_cost"] = round(a["api_cost"], 4)
        a["share_pct"] = round(a["tokens"] / tot_tok * 100, 1) if tot_tok else 0.0
        a["estimated"] = a["est"] >= a["n"] and a["n"] > 0
        a["cache_pct"] = round(a["cached"] / a["input"] * 100, 1) if a["input"] else 0.0
        a["tokens_per_turn"] = round(a["tokens"] / a["n"]) if a["n"] else 0
        a["tokens_per_call"] = (
            round(a["tokens"] / a["model_calls"]) if a["model_calls"] else 0
        )
        a["burn_per_min"] = round(agent_burn_tok.get(a["id"], 0) / 60.0, 1)

    active_events = [
        {
            "ts": int(r["ts"]), "provider": r["provider"],
            "agent_id": r["agent_id"], "kind": r["kind"],
            "reset_ts": int(r["reset_ts"]) if r["reset_ts"] is not None else None,
            # Tool limits never circuit-break the agent and often provide no
            # truthful reset clock. Keep them visible as a 24h diagnostic signal;
            # only real provider caps/guards use reset_ts as active state.
            "active": (
                (r["kind"] == "tool_cap" and int(r["ts"]) >= now - 86_400_000)
                or bool(r["reset_ts"] and int(r["reset_ts"]) > now)
            ),
        }
        for r in usage_events
    ]
    working_now = []
    for task in list(RUNNING_TASKS.values()):
        try:
            task_cid = int(task.get("chat_id") or 0)
            if not is_admin and int(_chat_owner_id(task_cid) or 0) != int(owner_id):
                continue
            started = int(task.get("started_ts") or now)
            working_now.append({
                "agent_id": str(task.get("agent_id") or ""),
                "agent_name": str(task.get("agent_name") or ""),
                "chat_id": task_cid,
                "started_ts": started,
                "elapsed_seconds": max(0, round((now - started) / 1000)),
            })
        except Exception:
            continue

    return {
        "range": canonical,
        "label": label,
        "now": now,
        "since_ms": int(effective_since),
        "oldest_ms": oldest_ms,
        "retention_days": USAGE_RETENTION_DAYS,
        "totals": {
            "tokens": int(tot_tok),
            "input": tot_in,
            "output": tot_out,
            "cached": tot_cached,
            "api_cost": round(tot_api, 4),
            "sub_cost": round(your_cost, 4),
            "sub_monthly": round(sub_total_month, 2),
            "multiple": (round(tot_api / your_cost, 1) if your_cost > 0 else None),
            "eff_rate": (round(your_cost / (tot_tok / 1e6), 2) if tot_tok else 0.0),
            "api_rate": (round(tot_api / (tot_tok / 1e6), 2) if tot_tok else 0.0),
        },
        "agents": agent_list,
        "providers": prov_out,
        "events": active_events,
        "working_now": working_now,
        "estimated_share": (round(tot_est / tot_n, 3) if tot_n else 1.0),
        "provisional": provisional,
        "coverage_days": round(coverage_days, 1),
        "baseline_days": _USAGE_BASELINE_DAYS,
        "verdict_ready_ms": verdict_ready_ms,
        "pricing": _usage_price_table(),
        "assumptions": {"subscriptions": subs, "month_basis_days": 30},
    }


@app.get("/api/usage")
async def api_usage(request: Request):
    """Per-agent token usage + implied-API-vs-subscription cost over a window.
    Named presets (1m/1h/24h/7d/30d/90d/365d/all), any `Nd` day count, or
    `since:YYYY-MM-DD`. Admin sees all owners; others see their own chats."""
