@app.post("/api/usage/settings")
async def api_usage_settings(request: Request):
    """Update the cost assumptions (per-provider monthly subscription price and
    optional token cap). Admin-only; the savings multiple is derived from these."""
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    if not _is_admin_user(user):
        return JSONResponse({"error": "admin only"}, status_code=403)
    try:
        body = await request.json()
    except Exception:
        body = {}
    cur = {}
    try:
        cur = json.loads(_get_setting("usage.settings", "") or "{}")
    except Exception:
        cur = {}
    subs = cur.get("subscriptions") or {}
    for prov, ov in (body.get("subscriptions") or {}).items():
        if not isinstance(ov, dict):
            continue
        d = dict(subs.get(prov) or {})
        if "monthly_usd" in ov:
            try:
                d["monthly_usd"] = max(0.0, float(ov["monthly_usd"]))
            except (TypeError, ValueError):
                pass
        if "cap_tokens" in ov:
            try:
                d["cap_tokens"] = max(0, int(float(ov["cap_tokens"])))
            except (TypeError, ValueError):
                pass
        if "credit_balance" in ov:
            try:
                d["credit_balance"] = max(0.0, float(ov["credit_balance"]))
            except (TypeError, ValueError):
                pass
        if "rolling_budget_tokens" in ov:
            try:
                d["rolling_budget_tokens"] = max(0, int(float(ov["rolling_budget_tokens"])))
            except (TypeError, ValueError):
                pass
        if "rolling_window_hours" in ov:
            try:
                d["rolling_window_hours"] = max(1.0, float(ov["rolling_window_hours"]))
            except (TypeError, ValueError):
                pass
        if "adaptive_guard" in ov and isinstance(ov["adaptive_guard"], bool):
            d["adaptive_guard"] = ov["adaptive_guard"]
        subs[prov] = d
    cur["subscriptions"] = subs
    _set_setting("usage.settings", json.dumps(cur))
    return {"ok": True, "assumptions": {"subscriptions": _usage_settings()["subscriptions"]}}


