@app.post("/api/usage/cap/clear")
async def api_usage_cap_clear(request: Request):
    """Manually clear an active provider usage cap ('I reset it / topped up'), so
    the breaker stops short-circuiting immediately instead of waiting out the
    guessed reset clock. The breaker re-arms on its own if the provider really is
    still capped, so this is safe for any authenticated user. Body:
    {"provider": "openai"} or {"agent_id": "codex"} (+ optional "chat_id")."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not _is_admin_user(user):
        return JSONResponse({"error": "admin required"}, status_code=403)
    try:
        body = await request.json()
    except Exception:
        body = {}
    provider = (body.get("provider") or "").strip().lower()
    agent_id = (body.get("agent_id") or "").strip()
    if not provider and agent_id:
        provider = _provider_for_agent(agent_id)
    if not provider:
        return JSONResponse({"error": "provider or agent_id required"}, status_code=400)
    allowed_providers = set(_USAGE_SUBS_DEFAULTS) | set(_AGENT_PROVIDER.values())
    if provider not in allowed_providers:
        return JSONResponse({"error": "unknown provider"}, status_code=400)
    cid = None
    if body.get("chat_id") is not None:
        try:
            cid = _parse_resource_id(body.get("chat_id"), "chat_id")
        except ValueError as e:
            return JSONResponse({"error": str(e)}, status_code=400)
        blocked = _require_chat_access(request, cid)
        if blocked:
            return blocked
    cleared = await asyncio.to_thread(_clear_provider_cap, provider)
    try:
        _audit_event(request, "usage.cap.clear", actor=str(user.get("id")),
                     target=provider, meta={"cleared": cleared, "agent_id": agent_id})
    except Exception:
        pass
    try:
        if cid is not None:
            await broadcast({"type": "cap_cleared", "chat_id": int(cid),
                             "provider": provider,
                             "owner_user_id": int(user["id"])})
    except Exception:
        pass
    return {"ok": True, "provider": provider, "cleared": cleared}


# ------------------------- Notification center (server-synced) -------------------------
# The bell's history is persisted per user so it reads the same on every device.
# All routes are strictly owner-scoped on _current_user — a user can only ever
# see or mutate their own rows.
@app.get("/api/notifications")
async def api_notifications_list(request: Request):
    """The caller's notification history, newest first (capped). Hydrates the
    bell on load and on every SSE reconnect so desktop and mobile stay in sync."""
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        items = await asyncio.to_thread(_list_notifications, int(user["id"]))
    except Exception:
        logger.exception("notifications: list failed")
        return JSONResponse({"error": "notifications unavailable"}, status_code=500)
    return {"notifications": items, "unread": sum(0 if n["read"] else 1 for n in items)}


@app.post("/api/notifications/read")
async def api_notifications_read(request: Request):
    """Mark notifications read. Body: {"ids": [...]} for specific rows, or
    {"all": true} to clear the whole unread count for this user."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    body = await request.json()
    uid = int(user["id"])

    def _mark() -> None:
        with _db() as conn:
            if body.get("all"):
                conn.execute(
                    "UPDATE notifications SET read=1 WHERE owner_user_id=? AND read=0", (uid,))
                return
            ids = _int_ids(body.get("ids"))
            if not ids:
                return
            qs = ",".join("?" * len(ids))
            conn.execute(
                f"UPDATE notifications SET read=1 WHERE owner_user_id=? AND id IN ({qs})",
                (uid, *ids))

    try:
        await asyncio.to_thread(_mark)
    except Exception:
        logger.exception("notifications: mark-read failed")
        return JSONResponse({"error": "update failed"}, status_code=500)
    return {"ok": True}


