@app.post("/api/notifications/backfill")
async def api_notifications_backfill(request: Request):
    """One-time cutover: push a browser's pre-existing localStorage history up to
    the server so nothing is lost when the bell switches to server-synced
    storage. Returns the merged, server-authoritative list. The client runs this
    once (guarded by a localStorage flag) and adopts the response."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    body = await request.json()
    uid = int(user["id"])
    items = body.get("items") if isinstance(body, dict) else None
    if not isinstance(items, list):
        items = []

    def _backfill() -> list[dict]:
        with _db() as conn:
            # Only seed if this user has no server history yet — keeps repeated
            # or racing backfills from duplicating the same legacy items.
            have = conn.execute(
                "SELECT COUNT(*) AS c FROM notifications WHERE owner_user_id=?", (uid,)
            ).fetchone()["c"]
            if not have:
                now = int(time.time() * 1000)
                # Oldest-first insert so newest keeps the highest id == newest ts.
                for it in sorted(items, key=lambda x: int(x.get("ts") or 0))[:SERVER_NOTIF_CAP]:
                    if not isinstance(it, dict):
                        continue
                    try:
                        cid_raw = it.get("chat_id")
                        cid_val = int(cid_raw) if str(cid_raw or "").strip().isdigit() else None
                        conn.execute(
                            "INSERT INTO notifications(owner_user_id, chat_id, chat_title, "
                            "title, body, event, severity, agent_id, ts, read, created_ts) "
                            "VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                            (uid, cid_val, str(it.get("chat_title") or ""),
                             str(it.get("title") or ""), str(it.get("body") or ""),
                             str(it.get("event") or ""), str(it.get("severity") or "info"),
                             str(it.get("agent_id") or ""), int(it.get("ts") or now),
                             1 if it.get("read") else 0, now),
                        )
                    except Exception:
                        continue
        return _list_notifications(uid)

    try:
        merged = await asyncio.to_thread(_backfill)
    except Exception:
        logger.exception("notifications: backfill failed")
        return JSONResponse({"error": "backfill failed"}, status_code=500)
    return {"notifications": merged, "unread": sum(0 if n["read"] else 1 for n in merged)}


@app.get("/api/secrets")
async def api_secrets_list(request: Request):
    """List a user's secrets — key names + which agents hold them. Never returns
    values; there is no endpoint that does. Admins may pass ?owner_user_id=N to
    view/manage another user's secrets (provisioning APIs for that user)."""
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    owner_id, owner_user, err = _resolve_secret_owner(
        user, request.query_params.get("owner_user_id"))
    if err:
        return err
    can_admin = _is_admin_user(user)
    return {
        "secrets": _list_secrets_for_owner(owner_id),
        "owner_user_id": owner_id,
        "can_admin": can_admin,
        "agents": _secret_scope_agents(owner_user, include_secret_conflicts=True),
        # Admins provision onto any user; the picker offers the FULL agent roster
        # (not just the primary owner's) so a secret can be tied onto whichever
        # agents each recipient holds. The per-recipient save still filters to
        # what that user actually has access to, so this is only a wider menu.
        "all_agents": ([{"id": a["id"], "name": a["name"]} for a in AGENTS]
                       if can_admin else []),
        "users": _secret_panel_users() if can_admin else [],
    }


@app.post("/api/secrets")
async def api_secrets_set(request: Request):
    """Create/replace a secret and set EXACTLY which of the caller's agents hold
    it. The value is pushed into each agent's own store and then discarded;
    agents previously granted this key but no longer selected are revoked."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    key = (payload.get("key") or "").strip().upper()
    value = payload.get("value")
    agent_ids = payload.get("agent_ids") or []
    if not SECRET_PANEL_KEY_RE.match(key):
        return JSONResponse({"error": "key must be UPPER_SNAKE_CASE (A–Z, 0–9, _)"}, status_code=400)
    if not isinstance(value, str) or not value.strip():
        return JSONResponse({"error": "value is required"}, status_code=400)
    if "§§secret(" in value:
        return JSONResponse({"error": "that's a placeholder, not a real secret value"}, status_code=400)
    if not isinstance(agent_ids, list):
        return JSONResponse({"error": "agent_ids must be a list"}, status_code=400)

    owner_id, owner_user, err = _resolve_secret_owner(user, payload.get("owner_user_id"))
    if err:
        return err
    # Targets are restricted to the OWNER's allowed agents — an admin can only
    # provision onto agents the target user actually has access to. Anything the
    # caller picked that this user can't use is reported back as `agents_skipped`
    # so the panel can say so rather than dropping it silently.
    allowed = _allowed_agent_ids_for_user(
        owner_user, include_secret_conflicts=True,
    )
    targets = list(dict.fromkeys(aid for aid in agent_ids if aid in allowed))
    skipped = [aid for aid in agent_ids if aid not in allowed]
    if not targets:
        return JSONResponse(
            {"error": "pick at least one agent that user has access to",
             "agents_skipped": skipped}, status_code=400)

    value = value.strip()
    results: dict[str, dict] = {}
    revoked: list[str] = []
    revoke_failures: dict[str, str] = {}
    async with _SECRET_MUTATION_LOCK:
        shared = [
            aid for aid in targets if _secret_agent_is_shared(owner_id, aid)
        ]
        if shared:
            return _secret_shared_agent_response(shared)
        conflicted = [
            aid for aid in targets if _secret_slot_has_other_owner(owner_id, key, aid)
        ]
        if conflicted:
            return _secret_conflict_response(conflicted)

        previous = _owner_secret_agents(owner_id, key)
        for aid in targets:
            status, set_err = await _set_secret_with_grant(
                owner_id, key, aid, value,
            )
            results[aid] = {"status": status, "error": set_err}

        # Preserve the prior working grants if any requested write failed. Once
        # every requested destination is durable, stale destinations can be
        # revoked without risking a total credential outage during rotation.
        stale = [aid for aid in previous if aid not in targets]
        if all(r["status"] == "ok" for r in results.values()):
            revoked, revoke_failures = await _revoke_secret_grants_unlocked(
                owner_id, key, stale,
            )

    ok = [aid for aid, r in results.items() if r["status"] == "ok"]
    errored = [aid for aid, r in results.items() if r["status"] == "err"]
    overall = (
        "ok" if ok and not errored and not revoke_failures
        else ("error" if not ok else "partial")
    )
    # Agent Zero vaults are live immediately; locally-managed host bridges only
    # read their env file at startup, so they need a force-restart to pick up the
    # new secret. Container agents additionally run their tools inside a Docker
    # container that reads the bind-mounted container.env at startup — those
    # carry their container name so the UI restart bounces it too
    # (reconnect?force=1&container=1).
    restart_needed = [
        {"id": aid, "name": AGENTS_BY_ID[aid]["name"],
         "container": (CONTAINER_NAMES.get(aid)
                       if _container_env_file(aid) is not None else None)}
        for aid in ok
        if aid in MANAGED_BRIDGES or _container_env_file(aid) is not None
    ]
    container_restart_needed = [a for a in restart_needed if a["container"]]
    _audit_event(
        request, "secret.panel_set", actor=user.get("email") or "user",
        target=key, status=overall,
        meta={"agents_ok": ok, "agents_error": errored, "revoked": revoked,
              "revoke_errors": list(revoke_failures),
              "owner_user_id": owner_id, "on_behalf": owner_id != int(user["id"])},
    )
    return {
        "status": overall,
        "key": key,
        "owner_user_id": owner_id,
        "agents_ok": ok,
        "agents_error": (
            [{"id": a, "error": results[a]["error"]} for a in errored]
            + [{"id": a, "error": e} for a, e in revoke_failures.items()]
        ),
        "agents_skipped": skipped,
        "revoked": revoked,
        "restart_needed": restart_needed,
        "container_restart_needed": container_restart_needed,
        "secrets": _list_secrets_for_owner(owner_id),
    }


@app.patch("/api/secrets/{key}")
async def api_secrets_update_grants(key: str, request: Request):
    """Update exactly which agents hold an existing secret without requiring
    the browser to resend its value.

    Secret values are deliberately write-only in the UI.  This endpoint makes
    a blank value during Edit mean "keep the saved value": unchanged grants are
    left alone, new grants receive a server-side copy when one is recoverable,
    and stale grants are revoked only after every requested addition succeeds.
    No secret value is returned to the client.
    """
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)

    key = (key or "").strip().upper()
    if not SECRET_PANEL_KEY_RE.match(key):
        return JSONResponse({"error": "invalid key"}, status_code=400)
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    requested = payload.get("agent_ids") or []
    if not isinstance(requested, list):
        return JSONResponse({"error": "agent_ids must be a list"}, status_code=400)
    owner_id, owner_user, err = _resolve_secret_owner(
        user, payload.get("owner_user_id"),
    )
    if err:
        return err

    current = _owner_secret_agents(owner_id, key)
    if not current:
        return JSONResponse({"error": "secret not found"}, status_code=404)
    allowed = _allowed_agent_ids_for_user(
        owner_user, include_secret_conflicts=True,
    )
    targets = list(dict.fromkeys(aid for aid in requested if aid in allowed))
    skipped = [aid for aid in requested if aid not in allowed]
    if not targets:
        return JSONResponse(
            {"error": "pick at least one agent that user has access to",
             "agents_skipped": skipped},
            status_code=400,
        )

    additions = [aid for aid in targets if aid not in current]
    stale = [aid for aid in current if aid not in targets]
    results: dict[str, dict] = {}
    revoked: list[str] = []
    revoke_failures: dict[str, str] = {}
    async with _SECRET_MUTATION_LOCK:
        shared = [
            aid for aid in additions if _secret_agent_is_shared(owner_id, aid)
        ]
        if shared:
            return _secret_shared_agent_response(shared)
        conflicted = [
            aid for aid in additions
            if _secret_slot_has_other_owner(owner_id, key, aid)
        ]
        if conflicted:
            return _secret_conflict_response(conflicted)

        value: Optional[str] = None
        if additions:
            value = _recover_secret_value(owner_id, key)
            if not value:
                return JSONResponse(
                    {
                        "error": (
                            "the saved value can’t be copied automatically; "
                            "enter the password again to add this agent"
                        ),
                        "needs_value": True,
                    },
                    status_code=409,
                )
        for aid in additions:
            status, set_err = await _set_secret_with_grant(
                owner_id, key, aid, value or "",
            )
            results[aid] = {"status": status, "error": set_err}

        # Never remove a working grant if an addition failed. This makes an edit
        # failure recoverable instead of turning a credential rotation into an
        # outage.
        if all(r["status"] == "ok" for r in results.values()):
            revoked, revoke_failures = await _revoke_secret_grants_unlocked(
                owner_id, key, stale,
            )

    added = [aid for aid, result in results.items() if result["status"] == "ok"]
    set_errors = {
        aid: result["error"] or "secret copy failed"
        for aid, result in results.items()
        if result["status"] != "ok"
    }
    failures = {**set_errors, **revoke_failures}
    changed = added + revoked
    overall = "ok" if not failures else ("partial" if changed else "error")
    restart_needed = _secret_restart_entries(changed, owner_id)
    _audit_event(
        request, "secret.panel_edit", actor=user.get("email") or "user",
        target=key, status=overall,
        meta={
            "agents_added": added,
            "agents_unchanged": sorted(current.intersection(targets)),
            "agents_revoked": revoked,
            "errors": list(failures),
            "owner_user_id": owner_id,
            "on_behalf": owner_id != int(user["id"]),
        },
    )
    return {
        "status": overall,
        "key": key,
        "owner_user_id": owner_id,
        "agents_ok": added,
        "agents_unchanged": sorted(current.intersection(targets)),
        "agents_error": [
            {"id": aid, "error": error} for aid, error in failures.items()
        ],
        "agents_skipped": skipped,
        "revoked": revoked,
        "restart_needed": restart_needed,
        "container_restart_needed": [
            item for item in restart_needed if item.get("container")
        ],
        "secrets": _list_secrets_for_owner(owner_id),
    }


@app.patch("/api/secrets/{key}/folder")
async def api_secret_folder_set(key: str, request: Request):
    """Move one logical secret into a display folder.

    Folders contain names only; secret values remain in their existing agent
    stores and are never read or rewritten by this operation. An empty folder
    moves the secret back to Unfiled.
    """
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    key = (key or "").strip().upper()
    if not SECRET_PANEL_KEY_RE.match(key):
        return JSONResponse({"error": "invalid key"}, status_code=400)
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    owner_id, _owner_user, err = _resolve_secret_owner(
        user, payload.get("owner_user_id"),
    )
    if err:
        return err
    raw_folder = payload.get("folder", "")
    if not isinstance(raw_folder, str):
        return JSONResponse({"error": "folder must be text"}, status_code=400)
    folder = re.sub(r"\s+", " ", raw_folder).strip()
    if len(folder) > 48:
        return JSONResponse({"error": "folder must be 48 characters or fewer"}, status_code=400)
    if any(ord(ch) < 32 or ord(ch) == 127 for ch in folder):
        return JSONResponse({"error": "folder contains unsupported characters"}, status_code=400)
    with _db() as conn:
        result = conn.execute(
            "UPDATE agent_secrets SET folder=? WHERE owner_user_id=? AND key=?",
            (folder, int(owner_id), key),
        )
    if not result.rowcount:
        return JSONResponse({"error": "secret not found"}, status_code=404)
    _audit_event(
        request, "secret.panel_folder", actor=user.get("email") or "user",
        target=key, status="ok",
        meta={
            "folder": folder or "Unfiled",
            "owner_user_id": owner_id,
            "on_behalf": owner_id != int(user["id"]),
        },
    )
    return {
        "status": "ok",
        "key": key,
        "folder": folder,
        "owner_user_id": owner_id,
        "secrets": _list_secrets_for_owner(owner_id),
    }


@app.post("/api/secrets/folders/bulk")
async def api_secret_folders_bulk(request: Request):
    """Move MANY secrets into one folder in a single call.

    This is the create-a-folder, rename-a-folder and empty-a-folder primitive:
    a folder exists exactly as long as some key names it, so "create" is
    assigning the first key and "rename" is reassigning every key that had the
    old name. Values are never read or rewritten — only the display label moves.
    Body: {"keys": ["A","B"], "folder": "Example Company"}.
    """
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    owner_id, _owner_user, err = _resolve_secret_owner(
        user, payload.get("owner_user_id"),
    )
    if err:
        return err

    raw_keys = payload.get("keys")
    if not isinstance(raw_keys, list) or not raw_keys:
        return JSONResponse({"error": "keys must be a non-empty list"}, status_code=400)
    keys: list[str] = []
    for raw in raw_keys:
        key = str(raw or "").strip().upper()
        if not SECRET_PANEL_KEY_RE.match(key):
            return JSONResponse({"error": f"invalid key: {raw!r}"}, status_code=400)
        if key not in keys:
            keys.append(key)

    folder, folder_err = _clean_secret_folder(payload.get("folder", ""))
    if folder_err:
        return JSONResponse({"error": folder_err}, status_code=400)

    known = {entry["key"] for entry in _list_secrets_for_owner(owner_id)}
    missing = [key for key in keys if key not in known]
    moved = [key for key in keys if key in known]
    if not moved:
        return JSONResponse(
            {"error": "none of those secrets exist", "keys_missing": missing},
            status_code=404,
        )
    with _db() as conn:
        for key in moved:
            conn.execute(
                "UPDATE agent_secrets SET folder=? WHERE owner_user_id=? AND key=?",
                (folder, int(owner_id), key),
            )
    _audit_event(
        request, "secret.panel_folder_bulk", actor=user.get("email") or "user",
        target=folder or "Unfiled", status="ok",
        meta={"keys": moved, "keys_missing": missing, "owner_user_id": owner_id,
              "on_behalf": owner_id != int(user["id"])},
    )
    return {
        "status": "ok",
        "folder": folder,
        "keys_moved": moved,
        "keys_missing": missing,
        "owner_user_id": owner_id,
        "folders": _secret_folders_for_owner(owner_id),
        "secrets": _list_secrets_for_owner(owner_id),
    }


@app.get("/api/secrets/folders/suggest")
async def api_secret_folders_suggest(request: Request):
    """Preview a deterministic filing plan for every unfiled secret.

    Nothing is written. The rules are in _suggest_secret_folders: the owner's own
    filing wins, then recognised services, then families with siblings. Keys the
    app cannot place confidently are simply left out of the plan rather than
    guessed at.
    """
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    owner_id, _owner_user, err = _resolve_secret_owner(
        user, request.query_params.get("owner_user_id"),
    )
    if err:
        return err
    proposals = _suggest_secret_folders(owner_id)
    unfiled = [
        entry["key"] for entry in _list_secrets_for_owner(owner_id)
        if not (entry.get("folder") or "").strip()
    ]
    placed = {item["key"] for item in proposals}
    return {
        "proposals": proposals,
        "unplaceable": [key for key in unfiled if key not in placed],
        "owner_user_id": owner_id,
        "folders": _secret_folders_for_owner(owner_id),
    }


@app.post("/api/secrets/{key}/rename")
async def api_secret_rename(key: str, request: Request):
    """Rename a secret's KEY, keeping its value, grants and folder.

    The value is copied server-side from a holder that can be read back and
    re-saved under the new name before the old name is revoked, so no credential
    is lost if a write fails partway. Agent Zero vaults have no read-back path;
    when the secret lives only there the caller is told to supply the value
    again (409 + needs_value), exactly like adding a new grant.
    """
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    old_key = (key or "").strip().upper()
    if not SECRET_PANEL_KEY_RE.match(old_key):
        return JSONResponse({"error": "invalid key"}, status_code=400)
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    new_key = str(payload.get("new_key") or "").strip().upper()
    if not SECRET_PANEL_KEY_RE.match(new_key):
        return JSONResponse(
            {"error": "new name must be UPPER_SNAKE_CASE (A–Z, 0–9, _)"},
            status_code=400,
        )
    if new_key == old_key:
        return JSONResponse({"error": "that is already the name"}, status_code=400)
    if _secret_key_is_reserved(new_key):
        return JSONResponse(
            {"error": "that name controls the host runtime and cannot be used"},
            status_code=400,
        )
    owner_id, owner_user, err = _resolve_secret_owner(
        user, payload.get("owner_user_id"),
    )
    if err:
        return err

    supplied = payload.get("value")
    if supplied is not None and not isinstance(supplied, str):
        return JSONResponse({"error": "value must be text"}, status_code=400)
    if isinstance(supplied, str) and "§§secret(" in supplied:
        return JSONResponse(
            {"error": "that's a placeholder, not a real secret value"},
            status_code=400,
        )

    async with _SECRET_MUTATION_LOCK:
        entries = {e["key"]: e for e in _list_secrets_for_owner(owner_id)}
        if old_key not in entries:
            return JSONResponse({"error": "secret not found"}, status_code=404)
        if new_key in entries:
            return JSONResponse(
                {"error": f"{new_key} already exists — delete it or pick another name"},
                status_code=409,
            )
        folder = (entries[old_key].get("folder") or "").strip()
        holders = [
            aid for aid in _owner_secret_agents(owner_id, old_key)
            if aid in AGENTS_BY_ID
        ]
        if not holders:
            return JSONResponse({"error": "secret not found"}, status_code=404)
        # The new name occupies a different physical slot on every holder, so it
        # has to clear the same install-global ownership guard a fresh secret does.
        conflicted = [
            aid for aid in holders
            if _secret_slot_has_other_owner(owner_id, new_key, aid)
        ]
        if conflicted:
            return _secret_conflict_response(conflicted)

        value = (supplied or "").strip() or _recover_secret_value(owner_id, old_key)
        if not value:
            return JSONResponse(
                {
                    "error": (
                        "the saved value can’t be read back automatically; "
                        "enter the password again to rename this secret"
                    ),
                    "needs_value": True,
                },
                status_code=409,
            )

        written: dict[str, dict] = {}
        for aid in holders:
            status, set_err = await _set_secret_with_grant(
                owner_id, new_key, aid, value,
            )
            written[aid] = {"status": status, "error": set_err}

        failures = {
            aid: (r["error"] or "secret copy failed")
            for aid, r in written.items() if r["status"] != "ok"
        }
        if failures:
            # Roll the new name back so a half-finished rename cannot leave two
            # live copies of one credential under different names.
            await _revoke_secret_grants_unlocked(
                owner_id, new_key,
                [aid for aid, r in written.items() if r["status"] == "ok"],
            )
            _audit_event(
                request, "secret.panel_rename", actor=user.get("email") or "user",
                target=f"{old_key}->{new_key}", status="error",
                meta={"errors": failures, "owner_user_id": owner_id},
            )
            return JSONResponse(
                {
                    "error": "rename failed; the original name is unchanged",
                    "status": "error",
                    "agents_error": [
                        {"id": aid, "error": e} for aid, e in failures.items()
                    ],
                },
                status_code=500,
            )

        if folder:
            with _db() as conn:
                conn.execute(
                    "UPDATE agent_secrets SET folder=? WHERE owner_user_id=? AND key=?",
                    (folder, int(owner_id), new_key),
                )
        revoked, revoke_failures = await _revoke_secret_grants_unlocked(
            owner_id, old_key, holders,
        )

    overall = "ok" if not revoke_failures else "partial"
    restart_needed = _secret_restart_entries(holders, owner_id)
    _audit_event(
        request, "secret.panel_rename", actor=user.get("email") or "user",
        target=f"{old_key}->{new_key}", status=overall,
        meta={"agents": holders, "old_name_revoked": revoked,
              "old_name_errors": list(revoke_failures),
              "folder": folder or "Unfiled", "owner_user_id": owner_id,
              "on_behalf": owner_id != int(user["id"])},
    )
    return {
        "status": overall,
        "key": new_key,
        "previous_key": old_key,
        "folder": folder,
        "owner_user_id": owner_id,
        "agents_ok": holders,
        "agents_error": [
            {"id": aid, "error": e} for aid, e in revoke_failures.items()
        ],
        "restart_needed": restart_needed,
        "container_restart_needed": [
            item for item in restart_needed if item.get("container")
        ],
        "secrets": _list_secrets_for_owner(owner_id),
    }


# ---------------- conversational secret / integration builder ----------------
# The user describes what they want to connect (Gmail, Workspace, Stripe…) and who
# should have access; the orchestrator asks follow-ups or proposes the named
# secret(s) + which agents to grant. CRITICAL: the REAL secret values never reach
# this endpoint or the model — the client collects them in a secure field and POSTs
# them straight to /api/secrets. This endpoint only designs key names + grants.
SECRET_COMPOSE_TIMEOUT_S = float(os.environ.get("SECRET_COMPOSE_TIMEOUT_S", "90"))


def _secret_compose_roster(scope_agents: list[dict]) -> str:
    """Roster block for the secret builder: every agent the owner can be granted a
    secret on (online or not — host bridges read their secrets at startup),
    described by its self-reported strengths so the orchestrator can pick who
    should hold the credential."""
    lines = []
    for a in scope_agents:
        aid = a["id"]
        card = (_CAP_CACHE.get(aid) or {}).get("card") or {}
        best = (card.get("best_for") or AGENT_LANES.get(aid)
                or AGENTS_BY_ID.get(aid, {}).get("tagline") or "general-purpose agent")
        strengths = card.get("strengths") or []
        extra = f" Strengths: {', '.join(str(s) for s in strengths[:4])}." if strengths else ""
        lines.append(f"- {aid} ({a.get('name') or aid}): {best}.{extra}")
    return "\n".join(lines) or "(no agents available)"


def _build_secret_compose_prompt(
    history: list[dict], roster: str, existing_keys: list[str], scope_name: str
) -> str:
    convo_lines = []
    for m in history[-20:]:
        who = "User" if m.get("role") == "user" else "Setup assistant"
        txt = str(m.get("content") or "").strip()
        if txt:
            convo_lines.append(f"{who}: {txt}")
    convo = "\n\n".join(convo_lines) or "User: (no message yet)"
    have = ", ".join(existing_keys) if existing_keys else "(none yet)"
    whose = f"{scope_name}'s" if scope_name else "the user's"
    return (
        "You are the SECRET SETUP ASSISTANT for a multi-agent chat app. Users connect their "
        "agents to outside services (Gmail, Google Workspace, Stripe, Slack, GitHub, OpenAI, a "
        "database, etc.) by storing credentials as named SECRETS that get pushed into each "
        "chosen agent's private store. The user describes, in plain language, what they want to "
        "connect and which agents should have access; you design the secret(s).\n\n"
        "CRITICAL — NEVER handle the actual secret value. Do NOT ask the user to type, paste, or "
        "tell you any API key, password, or token, and never print one. They enter the real "
        "value into a secure field you never see. Your job is ONLY to: (1) work out WHICH "
        "credential(s) the integration needs, (2) name each one in UPPER_SNAKE_CASE, (3) decide "
        "which agents should hold them, and (4) explain where the user gets each value.\n\n"
        f"AGENTS AVAILABLE (use agent ids only from this list — these are {whose} agents):\n{roster}\n\n"
        f"SECRETS THAT ALREADY EXIST for this user: {have}\n\n"
        "HOW TO WORK:\n"
        "- If it's unclear what service, which account, what the agents will do with it, or which "
        "agents should get access, ASK up to 3 focused questions first.\n"
        "- Know the common shapes and propose ALL the keys an integration actually needs, not "
        "just one: Gmail SMTP sending needs an address + a 16-char app password (GMAIL_ADDRESS, "
        "GMAIL_APP_PASSWORD); a Google service account needs its JSON key "
        "(GOOGLE_SERVICE_ACCOUNT_JSON); Stripe needs a secret key (STRIPE_API_KEY); a Slack bot "
        "needs a bot token (SLACK_BOT_TOKEN); and so on.\n"
        "- Reuse an existing key name when the user clearly means the same credential.\n"
        "- The moment you know enough (or the user says to just set it up), return the secret(s). "
        "If the user asks to change a proposal, return the full updated set.\n"
        "- Keep messages friendly, concise, and free of markdown headers. For each secret give a "
        "one-line 'hint' telling the user exactly where to get the value, and a 'setup_url' when "
        "there's a well-known page for it.\n\n"
        f"CONVERSATION SO FAR (the LAST user turn is the newest ask — build on the whole "
        f"thread):\n{convo}\n\n"
        "Reply with ONLY a JSON object — no prose, no code fence — in ONE of these two shapes:\n"
        'ASK:    {"action": "ask", "message": "<your reply plus any questions, plain conversational text>"}\n'
        'CREATE: {"action": "create", "message": "<one or two short lines: what to set up and the next step>", '
        '"agent_ids": ["bare id from roster", "..."], '
        '"secrets": [{"key": "GMAIL_APP_PASSWORD", "label": "Gmail app password", '
        '"hint": "Generate one at the Google App Passwords page", '
        '"setup_url": "https://myaccount.google.com/apppasswords", "strip_spaces": true}]}\n'
        "Include 1–6 secrets. 'label', 'hint', and 'setup_url' are optional per secret (omit "
        "setup_url when there's no obvious page). Set 'strip_spaces': true when the credential "
        "is a single opaque token with no real spaces — API keys, OAuth tokens, and app "
        "passwords (Gmail shows its app password in 4 space-separated groups, but the real value "
        "has none). Set it false (or omit) for values that can legitimately contain spaces or "
        "newlines: JSON service-account keys, PEM/certificates, connection strings, or a "
        "user-chosen passphrase. Only use agent ids that appear in the roster above. Never put a "
        "real credential value anywhere in your reply."
    )


def _normalize_proposed_secrets(
    parsed: dict, allowed_ids: set
) -> tuple[list[dict], list[str]]:
    """Validate the orchestrator's proposed secret set into a safe shape for the
    panel — drop malformed keys, dedupe, cap at 6, and restrict agent_ids to the
    owner's allowed set. Returns ([], []) when nothing usable was proposed."""
    raw_secrets = parsed.get("secrets")
    if not isinstance(raw_secrets, list):
        return [], []
    out: list[dict] = []
    seen: set = set()
    for s in raw_secrets[:6]:
        if not isinstance(s, dict):
            continue
        key = str(s.get("key") or "").strip().upper()
        if not SECRET_PANEL_KEY_RE.match(key) or key in seen:
            continue
        seen.add(key)
        url = str(s.get("setup_url") or "").strip()
        if url and not url.lower().startswith(("http://", "https://")):
            url = ""
        out.append({
            "key": key,
            "label": str(s.get("label") or "").strip()[:80],
            "hint": str(s.get("hint") or "").strip()[:240],
            "setup_url": url[:400],
            # True for opaque single-token creds (API keys, app passwords) where a
            # pasted-in space is always an artifact — the card pre-checks "remove
            # spaces". False/omitted for JSON, PEM, or passphrases that may contain
            # real spaces. The client also hard-guards multiline/JSON values.
            "strip_spaces": bool(s.get("strip_spaces")),
        })
    agent_ids = [a for a in (parsed.get("agent_ids") or []) if a in allowed_ids]
    agent_ids = list(dict.fromkeys(agent_ids))  # de-dup, preserve order
    return out, agent_ids


@app.post("/api/secrets/compose")
async def api_compose_secret(request: Request):
    """Conversational secret/integration builder. The user describes what they want
    to connect and who should have access; the orchestrator asks follow-ups or
    returns a proposed set of named secrets + the agents to grant them. Stateless —
    the client replays the transcript each call. The REAL secret VALUES never reach
    this endpoint or the model; the user enters them into the secure field on the
    proposal card and they go straight to POST /api/secrets."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await request.json()
    except Exception:
        body = {}
    owner_id, owner_user, err = _resolve_secret_owner(user, (body or {}).get("owner_user_id"))
    if err:
        return err
    raw_msgs = body.get("messages") if isinstance(body, dict) else None
    history: list[dict] = []
    if isinstance(raw_msgs, list):
        for m in raw_msgs[-20:]:
            if not isinstance(m, dict):
                continue
            content = str(m.get("content") or "").strip()
            if not content:
                continue
            role = "assistant" if m.get("role") == "assistant" else "user"
            history.append({"role": role, "content": content[:4000]})
    if not history or history[-1]["role"] != "user":
        return JSONResponse({"ok": False, "error": "say what you want to set up"}, status_code=400)
    router = (
        AGENTS_BY_ID.get(_effective_concierge_agent_id())
        or AGENTS_BY_ID.get(LEAD_AGENT_ID)
        or (AGENTS[0] if AGENTS else None)
    )
    if router is None:
        return JSONResponse({"ok": False, "error": "no orchestrator agent configured"}, status_code=503)
    scope_agents = _secret_scope_agents(owner_user)
    allowed_ids = {a["id"] for a in scope_agents}
    roster = _secret_compose_roster(scope_agents)
    existing = [s["key"] for s in _list_secrets_for_owner(owner_id)]
    scope_name = ""
    if owner_id != int(user["id"]):
        scope_name = (owner_user.get("preferred_name") or owner_user.get("display_name")
                      or owner_user.get("email") or "this user")
    try:
        raw = await _concierge_call(
            router, _build_secret_compose_prompt(history, roster, existing, scope_name),
            SECRET_COMPOSE_TIMEOUT_S)
    except Exception as exc:
        logger.warning("secret compose via %s failed: %s", router["id"], exc)
        return JSONResponse({"ok": False, "error": "couldn’t reach the orchestrator"}, status_code=502)
    parsed = _parse_skill_reply(raw)  # shared JSON extractor (handles code fences)
    if not isinstance(parsed, dict):
        # Not clean JSON — treat its text as a question so the chat can continue.
        return JSONResponse({"ok": True, "action": "ask",
                             "message": (raw or "").strip()
                             or "Tell me a bit more about what you want to connect."})
    message = str(parsed.get("message") or "").strip()
    if parsed.get("action") != "create":
        return JSONResponse({"ok": True, "action": "ask",
                             "message": message or "Could you tell me a bit more?"})
    secrets, agent_ids = _normalize_proposed_secrets(parsed, allowed_ids)
    if not secrets:
        return JSONResponse({"ok": True, "action": "ask",
                             "message": message or "I need a bit more detail to set that up."})
    _audit_event(request, "secret.compose", actor=user.get("email") or "user", status="ok",
                 meta={"keys": [s["key"] for s in secrets], "agents": agent_ids,
                       "owner_user_id": owner_id, "on_behalf": owner_id != int(user["id"])})
    return JSONResponse({"ok": True, "action": "create", "message": message,
                         "secrets": secrets, "agent_ids": agent_ids, "owner_user_id": owner_id})


@app.post("/api/secrets/{key}/revoke")
async def api_secrets_revoke(key: str, request: Request):
    """Revoke a secret from one agent (agent_id in body) or from all agents
    (omit agent_id). Deletes the value from the agent's store."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    key = (key or "").strip().upper()
    if not SECRET_PANEL_KEY_RE.match(key):
        return JSONResponse({"error": "invalid key"}, status_code=400)
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    owner_id, _owner_user, err = _resolve_secret_owner(user, payload.get("owner_user_id"))
    if err:
        return err
    current = _owner_secret_agents(owner_id, key)
    one = (payload.get("agent_id") or "").strip()
    targets = [t for t in ([one] if one else list(current)) if t in current]
    if not targets:
        return JSONResponse({"error": "no matching grant"}, status_code=404)
    revoked, failures = await _revoke_secret_grants(owner_id, key, targets)
    overall = "ok" if not failures else ("partial" if revoked else "error")
    _audit_event(
        request, "secret.panel_revoke", actor=user.get("email") or "user",
        target=key, status=overall,
        meta={"revoked": revoked, "errors": list(failures), "owner_user_id": owner_id,
              "on_behalf": owner_id != int(user["id"])},
    )
    return JSONResponse(
        _secret_revoke_response(
            key=key, owner_user_id=owner_id, revoked=revoked, failures=failures,
        ),
        status_code=500 if failures else 200,
    )


@app.post("/api/secrets/{key}/grant")
async def api_secrets_grant(key: str, request: Request):
    """Grant an ALREADY-created secret to one or more additional agents WITHOUT
    re-entering the value: the value is recovered server-side from an agent that
    already holds it (see _recover_secret_value) and copied into each new agent's
    store. The value is never returned. Idempotent — agents that already hold the
    key are skipped. If the value can't be recovered (e.g. it lives only in an
    Agent Zero vault, which has no read-back), returns 409 with needs_value so the
    panel falls back to Edit / re-enter the value."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    key = (key or "").strip().upper()
    if not SECRET_PANEL_KEY_RE.match(key):
        return JSONResponse({"error": "invalid key"}, status_code=400)
    try:
        payload = await request.json()
    except Exception:
        payload = {}

    owner_id, owner_user, err = _resolve_secret_owner(user, payload.get("owner_user_id"))
    if err:
        return err

    one = (payload.get("agent_id") or "").strip()
    requested = payload.get("agent_ids") or ([one] if one else [])
    if not isinstance(requested, list):
        return JSONResponse({"error": "agent_ids must be a list"}, status_code=400)

    current = _owner_secret_agents(owner_id, key)
    if not current:
        return JSONResponse({"error": "secret not found"}, status_code=404)

    # Same guardrail as POST /api/secrets: a grant can only land on agents the
    # OWNER actually has access to. Already-held agents are skipped (idempotent),
    # not re-written, so a stray double-tap is a no-op.
    allowed = _allowed_agent_ids_for_user(
        owner_user, include_secret_conflicts=True,
    )
    targets = list(dict.fromkeys(
        aid for aid in requested if aid in allowed and aid not in current
    ))
    skipped = [aid for aid in requested if aid not in allowed]
    if not targets:
        return JSONResponse(
            {"error": "pick an agent this user can access and doesn't already hold",
             "agents_skipped": skipped}, status_code=400)

    results: dict[str, dict] = {}
    async with _SECRET_MUTATION_LOCK:
        shared = [
            aid for aid in targets if _secret_agent_is_shared(owner_id, aid)
        ]
        if shared:
            return _secret_shared_agent_response(shared)
        conflicted = [
            aid for aid in targets if _secret_slot_has_other_owner(owner_id, key, aid)
        ]
        if conflicted:
            return _secret_conflict_response(conflicted)
        value = _recover_secret_value(owner_id, key)
        if not value:
            return JSONResponse(
                {"error": "can’t copy this secret’s value automatically — open Edit and re-enter it",
                 "needs_value": True}, status_code=409)

        for aid in targets:
            status, serr = await _set_secret_with_grant(
                owner_id, key, aid, value,
            )
            results[aid] = {"status": status, "error": serr}

    ok = [aid for aid, r in results.items() if r["status"] == "ok"]
    errored = [aid for aid, r in results.items() if r["status"] == "err"]
    overall = "ok" if ok and not errored else ("error" if not ok else "partial")
    # Same restart bookkeeping as save: managed host bridges and container agents
    # only read their env at startup, so newly-granted ones need a bounce.
    restart_needed = [
        {"id": aid, "name": AGENTS_BY_ID[aid]["name"],
         "container": (CONTAINER_NAMES.get(aid)
                       if _container_env_file(aid) is not None else None)}
        for aid in ok
        if aid in MANAGED_BRIDGES or _container_env_file(aid) is not None
    ]
    container_restart_needed = [a for a in restart_needed if a["container"]]
    _audit_event(
        request, "secret.panel_grant", actor=user.get("email") or "user",
        target=key, status=overall,
        meta={"agents_ok": ok, "agents_error": errored,
              "owner_user_id": owner_id, "on_behalf": owner_id != int(user["id"])},
    )
    return {
        "status": overall,
        "key": key,
        "owner_user_id": owner_id,
        "agents_ok": ok,
        "agents_error": [{"id": a, "error": results[a]["error"]} for a in errored],
        "agents_skipped": skipped,
        "restart_needed": restart_needed,
        "container_restart_needed": container_restart_needed,
        "secrets": _list_secrets_for_owner(owner_id),
    }


@app.delete("/api/secrets/{key}")
async def api_secrets_delete(key: str, request: Request):
    """Delete a secret entirely — revoke from every agent and forget the name."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    key = (key or "").strip().upper()
    if not SECRET_PANEL_KEY_RE.match(key):
        return JSONResponse({"error": "invalid key"}, status_code=400)
    owner_id, _owner_user, err = _resolve_secret_owner(
        user, request.query_params.get("owner_user_id"))
    if err:
        return err
    targets = list(_owner_secret_agents(owner_id, key))
    orphans = _orphaned_secret_agents(owner_id, key)
    if not targets and not orphans:
        return JSONResponse({"error": "secret not found"}, status_code=404)
    revoked, failures = (
        await _revoke_secret_grants(owner_id, key, targets) if targets else ([], {})
    )
    # Clear the retired-agent rows too, but only once the live revokes are clean.
    # Dropping them while a real revoke failed would leave the key looking gone
    # while a live agent still holds the value.
    purged: list[str] = []
    if orphans and not failures:
        purged = _purge_orphaned_secret_grants(owner_id, key)
    overall = (
        "ok" if not failures
        else ("partial" if revoked else "error")
    )
    _audit_event(
        request, "secret.panel_delete", actor=user.get("email") or "user",
        target=key, status=overall,
        meta={"revoked": revoked, "errors": list(failures),
              "orphans_purged": purged, "owner_user_id": owner_id,
              "on_behalf": owner_id != int(user["id"])},
    )
    payload = _secret_revoke_response(
        key=key, owner_user_id=owner_id, revoked=revoked, failures=failures,
    )
    payload["orphans_purged"] = purged
    return JSONResponse(payload, status_code=500 if failures else 200)


@app.post("/api/reset")
async def api_reset(request: Request):
    """Detach a single agent's Agent Zero context for the active chat. Used
    by the per-agent "Reset Context" button in the inspector. Requires an
    explicit agent_id — the global wipe path was removed because it was a
    footgun that overlapped with delete-chat / new-chat."""
    blocked = _require_origin(request)
    if blocked: return blocked
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    target = (payload or {}).get("agent_id")
    if not target or target not in AGENTS_BY_ID:
        return JSONResponse({"error": "agent_id required"}, status_code=400)
    active_chat_id = _active_chat_id_for_request(request)
    contexts = _chat_contexts(active_chat_id)
    contexts.pop(target, None)
    _reset_agent_last_seen(active_chat_id, target)
    _save_contexts(active_chat_id, contexts)
    _audit_event(
        request,
        "context.reset",
        chat_id=active_chat_id,
        target=target,
        status="ok",
    )
    return {"reset": [target]}


@app.get("/api/tasks")
async def api_tasks(request: Request):
    active_chat_id = _active_chat_id_for_request(request)
    tasks = []
    for task_id, info in RUNNING_TASKS.items():
        if info.get("chat_id") != active_chat_id:
            continue
        task = info.get("task")
        tasks.append({
            "id": task_id,
            "chat_id": info.get("chat_id"),
            "agent_id": info.get("agent_id"),
            "agent_name": info.get("agent_name"),
            "started_ts": info.get("started_ts"),
            "done": bool(task.done()) if task else True,
        })
    return {"status": "ok", "tasks": tasks}


def _working_for_chat(cid) -> list[dict]:
    """Agents currently mid-response in `cid`, used to restore the live
    "working…" indicator after a reconnect / chat-switch / page reload.

    RUNNING_TASKS is the server-side source of truth. The `typing` start/stop
    events alone are transient — a client that reloads (switchChat does a full
    location.reload) or whose SSE drops while backgrounded would otherwise lose
    the indicator even though the agent is still running. Shipping this in the
    `hello` payload lets the client rebuild state.typing from authoritative data.
    """
    out: list[dict] = []
    for task_id, info in RUNNING_TASKS.items():
        if info.get("chat_id") != cid:
            continue
        task = info.get("task")
        if task is not None and task.done():
            continue
        out.append({
            "agent_id": info.get("agent_id"),
            "id": task_id,
            "turn_id": info.get("turn_id"),
            "started_ts": info.get("started_ts"),
            "progress": info.get("progress_text") or "",
            "progress_active": bool(info.get("progress_active")),
        })
    return out


@app.post("/api/tasks/{task_id}/cancel")
async def api_cancel_task(task_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    active_chat_id = _active_chat_id_for_request(request)
    info = RUNNING_TASKS.get(task_id)
    if not info or info.get("chat_id") != active_chat_id:
        return JSONResponse({"error": "task not found"}, status_code=404)
    task = info.get("task")
    if not task or task.done():
        _audit_event(
            request,
            "task.cancel",
            chat_id=active_chat_id,
            target=task_id,
            status="already_done",
            meta={"agent_id": info.get("agent_id")},
        )
        return {"status": "already_done", "id": task_id}
    # Mark this as a DELIBERATE stop so the durable-run safety net settles the turn
    # quietly instead of posting a "run interrupted — resume" card (cleared in
    # _route_turn_then_notify's finally).
    _mark_intentional_stop_tasks([task])
    task.cancel()
    _audit_event(
        request,
        "task.cancel",
        chat_id=active_chat_id,
        target=task_id,
        status="ok",
        meta={"agent_id": info.get("agent_id")},
    )
    return {
        "status": "cancel_requested",
        "id": task_id,
        "agent_id": info.get("agent_id"),
    }


@app.post("/api/tasks/cancel_all")
async def api_cancel_all_tasks(request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    active_chat_id = _active_chat_id_for_request(request)
    cancelled: list[dict] = []
    already_done: list[str] = []
    seen_tasks: set = set()

    for task_id, info in list(RUNNING_TASKS.items()):
        if info.get("chat_id") != active_chat_id:
            continue
        task = info.get("task")
        if not task or task.done():
            already_done.append(task_id)
            continue
        task.cancel()
        seen_tasks.add(task)
        cancelled.append({
            "id": task_id,
            "agent_id": info.get("agent_id"),
            "agent_name": info.get("agent_name"),
        })

    # Also cancel the turn-orchestration task(s) for this chat. In a sequential
    # mode this IS the task already cancelled above (cancelling twice is a no-op),
    # but in a parallel mode (delegate/poll) the orchestrator is separate from the
    # gather children, and there's a brief window between sequential agents where
    # no per-agent task is registered. Cancelling the turn task closes both gaps so
    # Stop-all reliably tears down the whole turn rather than letting the next agent
    # start. Deduped against tasks already cancelled above.
    turns_cancelled = 0
    for turn_task in list(RUNNING_TURNS.get(active_chat_id, set())):
        if turn_task and not turn_task.done() and turn_task not in seen_tasks:
            turn_task.cancel()
            seen_tasks.add(turn_task)
            turns_cancelled += 1

    # Flag a DELIBERATE stop ONLY when we actually tore something down, so the
    # durable-run safety net settles the cancelled turn quietly instead of posting
    # a "run interrupted — resume" card. Gated (not set on a no-op Stop-all) so the
    # marker can't leak to a later, genuinely-unexpected interruption; the turn's
    # finally clears it. No await between here and the cancelled tasks being
    # scheduled, so the flag is in place before any CancelledError is processed.
    if cancelled or turns_cancelled:
        _mark_intentional_stop_tasks(seen_tasks)
        INTENTIONAL_STOP.add(active_chat_id)

    _audit_event(
        request,
        "task.cancel_all",
        chat_id=active_chat_id,
        status="ok",
        meta={
            "cancelled": len(cancelled),
            "turns_cancelled": turns_cancelled,
            "already_done": len(already_done),
            "agent_ids": [item.get("agent_id") for item in cancelled],
        },
    )
    return {
        "status": "cancel_requested" if (cancelled or turns_cancelled) else "none_running",
        "cancelled": cancelled,
        "turns_cancelled": turns_cancelled,
        "already_done": already_done,
    }


@app.post("/api/tasks/{task_id}/nudge")
async def api_nudge_task(task_id: str, request: Request):
    blocked = _require_origin(request)
    if blocked: return blocked
    active_chat_id = _active_chat_id_for_request(request)
    info = RUNNING_TASKS.get(task_id)
    if not info or info.get("chat_id") != active_chat_id:
        return JSONResponse({"error": "task not found"}, status_code=404)
    task = info.get("task")
    if not task or task.done():
        _audit_event(
            request,
            "task.nudge",
            chat_id=active_chat_id,
            target=task_id,
            status="already_done",
            meta={"agent_id": info.get("agent_id")},
        )
        return {"status": "already_done", "id": task_id}

    now_ms = int(time.time() * 1000)
    last_nudge = int(info.get("last_nudge_ts") or 0)
    if now_ms - last_nudge < 15_000:
        _audit_event(
            request,
            "task.nudge",
            chat_id=active_chat_id,
            target=task_id,
            status="rate_limited",
            meta={"agent_id": info.get("agent_id")},
        )
        return JSONResponse({"error": "nudge already sent recently"}, status_code=429)

    info["last_nudge_ts"] = now_ms
    info["nudge_count"] = int(info.get("nudge_count") or 0) + 1
    agent = AGENTS_BY_ID.get(info.get("agent_id"))
    if not agent:
        return JSONResponse({"error": "agent not found"}, status_code=404)

    _spawn_chat_task(active_chat_id, _dispatch_nudge(agent, active_chat_id, task_id))
    _audit_event(
        request,
        "task.nudge",
        chat_id=active_chat_id,
        target=task_id,
        status="ok",
        meta={"agent_id": info.get("agent_id"), "nudge_count": info["nudge_count"]},
    )
    return {
        "status": "nudge_sent",
        "id": task_id,
        "agent_id": info.get("agent_id"),
    }


@app.get("/sw.js")
async def service_worker():
    js = r"""
self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

async function notificationPayload(event) {
  if (event.data) {
    try { return event.data.json(); } catch {}
    try { return { title: 'Agents Chat Alert', body: event.data.text() }; } catch {}
  }
  try {
    const sub = await self.registration.pushManager.getSubscription();
    if (!sub || !sub.endpoint) throw new Error('missing subscription');
    const res = await fetch('/api/push/latest', {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ endpoint: sub.endpoint }),
      cache: 'no-store',
    });
    if (!res.ok) throw new Error('latest lookup failed');
    const data = await res.json();
    return data.notification || {};
  } catch (err) {
    return {
      title: 'Agents Chat Alert',
      body: 'Open Agents Chat for the latest update.',
      severity: 'info',
    };
  }
}

self.addEventListener('push', (event) => {
  event.waitUntil((async () => {
    const payload = await notificationPayload(event);
    const severity = payload.severity || 'info';
    const title = payload.title || 'Agents Chat Alert';
    const body = payload.body || 'Open Agents Chat for the latest update.';
    await self.registration.showNotification(title, {
      body,
      tag: payload.chat_id ? `agent-chat-${payload.chat_id}` : 'agent-chat-alert',
      renotify: severity === 'critical' || severity === 'error' || severity === 'warn',
      silent: false,
      icon: '/icon.svg',
      badge: '/icon.svg',
      data: { chat_id: payload.chat_id || null, url: '/' },
    });
  })());
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil((async () => {
    const url = event.notification.data?.url || '/';
    const allClients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const client of allClients) {
      if ('focus' in client) {
        try {
          await client.focus();
          return;
        } catch {}
      }
    }
    if (self.clients.openWindow) await self.clients.openWindow(url);
  })());
});
"""
    return Response(
        js.strip() + "\n",
        media_type="application/javascript; charset=utf-8",
        headers={
            "Cache-Control": "no-store",
            "Service-Worker-Allowed": "/",
        },
    )


@app.get("/api/changelog")
async def api_changelog():
    """Serve the correct in-app history for the active edition.

    The private app's long-form history is deliberately kept separate from the
    public Community release notes so preparing a public release can never
    rewrite the operator's everyday ``What's new`` panel again. Read fresh on
    every request so later edits show up without restarting the app.
    """
    changelog_path = (
        BASE_DIR / "community" / "CHANGELOG.public.md"
        if community_mode()
        else BASE_DIR / "CHANGELOG.md"
    )
    try:
        text = changelog_path.read_text(encoding="utf-8")
    except OSError:
        text = "# What's new\n\nNo changelog found."
    return Response(
        text,
        media_type="text/markdown; charset=utf-8",
        headers={"Cache-Control": "no-store"},
    )


