def _agent_http_error(resp: httpx.Response) -> RuntimeError:
    body = resp.text.strip()
    detail = ""
    retryable: Optional[bool] = None
    data = None
    if body:
        try:
            data = resp.json()
        except json.JSONDecodeError:
            data = None
        if isinstance(data, dict) and isinstance(data.get("error"), str):
            detail = data["error"].strip()
            if isinstance(data.get("retryable"), bool):
                retryable = data["retryable"]
        elif body:
            detail = body[:500]
    err = RuntimeError(detail or f"Agent API HTTP {resp.status_code}")
    # Tag the error so callers can decide whether to auto-retry. A bridge can state
    # outright whether the failure is worth retrying (e.g. Codex marks a usage/quota
    # cap non-retryable so we don't burn the 2s/4s budget on a limit that resets
    # hours later); otherwise fall back to the status code — a 529/503/429 is a
    # temporary upstream condition, a 400/401/404 is a real fault.
    err.status_code = resp.status_code
    err.transient = retryable if retryable is not None else (resp.status_code in _TRANSIENT_HTTP_STATUS)
    detail_l = (detail or "").lower()
    if any(s in detail_l for s in ("oauth", "authenticat", "could not be refreshed", "sign in")):
        err.transient = False
        err.auth_expired = True
    else:
        err.auth_expired = False
    # A bridge may have completed billable steps or produced a useful partial
    # answer before the upstream cap/error arrived. Preserve that structured
    # evidence on the exception so dispatch can meter and deliver it instead of
    # turning a long run into an apparently empty failure.
    if isinstance(data, dict):
        usage = data.get("usage")
        err.usage = usage if isinstance(usage, dict) else None
        err.partial_response = str(data.get("partial_response") or "").strip()
        err.model = str(data.get("model") or "").strip()
        err.reasoning = str(data.get("reasoning") or "").strip()
        err.error_provider = str(data.get("error_provider") or "").strip().lower()
        err.limit_scope = str(data.get("limit_scope") or "").strip().lower()
    else:
        err.usage = None
        err.partial_response = ""
        err.model = ""
        err.reasoning = ""
        err.error_provider = ""
        err.limit_scope = ""
    return err


def _agent_response_text_and_metadata(agent_id: str, data) -> tuple[str, dict]:
    metadata: dict = {}
    if not isinstance(data, dict):
        return str(data), metadata
    # model_requested/model_fallback are the bridge admitting it could NOT honour
    # the model the room asked for. Carry them into the turn metadata so the chip
    # row says so, instead of showing the substituted model as if it were the pick.
    for key in (
        "model", "model_requested", "model_fallback",
        "reasoning", "thinking", "preset", "tools",
        "session_reused", "session_rotated", "turn_count",
    ):
        if key in data:
            metadata[key] = data[key]
    usage = data.get("usage")
    if isinstance(usage, dict):
        metadata["usage"] = usage
    cost = data.get("cost") or data.get("cost_usd")
    if isinstance(cost, (int, float, str)):
        metadata["cost_usd"] = cost
    if metadata:
        metadata["agent_id"] = agent_id
    for k in ("response", "text", "message", "content", "output"):
        if k in data and isinstance(data[k], str):
            return data[k], metadata
    return json.dumps(data, indent=2), metadata


class AgentUsageGuardBlocked(RuntimeError):
    """A queued call was safely withheld after acquiring the per-agent lock."""


def _agent_request_workspace(
    agent_id: str, cid: int, explicit_workspace: Optional[str] = None,
) -> str:
    """Return the validated workspace path this agent should receive.

    CLI implementers always receive the chat's effective workspace, including
    the private scratch folder they use as a working directory. Perplexity is a
    different boundary: its visible desktop app can only read a local folder
    after that folder is selected through Perplexity's Folders control. Send it
    only a folder the owner explicitly attached to the chat (directly or through
    a project), never Agents Chat's implicit scratch directory.
    """
    if agent_id == PERPLEXITY_AGENT_ID:
        info = _chat_workspace_info(cid)
        if info.get("source") in {"chat", "project"}:
            selected = str(info.get("path") or "").strip()
            if not selected:
                return ""
            if explicit_workspace is not None and str(explicit_workspace).strip():
                try:
                    requested_path = Path(str(explicit_workspace)).resolve()
                    selected_path = Path(selected).resolve()
                except (OSError, RuntimeError) as exc:
                    raise RuntimeError(
                        "Perplexity workspace request could not be matched to the "
                        "folder attached to this chat; the request was not sent."
                    ) from exc
                if requested_path != selected_path:
                    raise RuntimeError(
                        "Perplexity workspace request does not match the folder "
                        "attached to this chat; the request was not sent."
                    )
            return selected
        if explicit_workspace is not None and str(explicit_workspace).strip():
            raise RuntimeError(
                "Perplexity can use only a folder explicitly attached to this chat "
                "or its project; the request was not sent."
            )
        return ""
    if explicit_workspace:
        return str(explicit_workspace).strip()
    if _is_workspace_implementer(agent_id):
        return _chat_workspace(cid)
    return ""


async def call_agent(
    agent: dict,
    message: str,
    cid: int,
    *,
    workspace: Optional[str] = None,
    workspace_access: str = "writable",
) -> tuple[str, dict]:
    access_mode = str(workspace_access or "writable").strip().lower()
    if access_mode not in {"writable", "read-only"}:
        raise ValueError("workspace_access must be writable or read-only")
    token = os.environ.get(agent.get("token_env", "")) or agent.get("token", "")
    if not token:
        raise RuntimeError(
            f"No API token for {agent['id']}. Set {agent.get('token_env')} in .env"
        )
    headers = {"X-API-KEY": token, "Content-Type": "application/json"}

    provider = _provider_for_agent(agent["id"])
    async with _provider_lock(provider), _agent_lock(agent["id"]):
        # Recheck only after acquiring the lock: a queued turn may have passed
        # preflight before an earlier turn consumed the remaining rolling budget
        # or tripped a real provider cap.
        if await _cap_short_circuit(agent, cid):
            raise AgentUsageGuardBlocked("provider cap")
        if await _usage_budget_short_circuit(agent, cid):
            raise AgentUsageGuardBlocked("rolling safety budget")
        payload: dict = {
            "message": message,
            "workspace_access": access_mode,
        }
        request_workspace = _agent_request_workspace(
            agent["id"], cid, explicit_workspace=workspace,
        )
        contexts = _chat_contexts(cid)
        ctx = contexts.get(agent["id"])
        if ctx:
            payload["context_id"] = ctx
        if agent["id"] == CODEX_AGENT_ID:
            payload.update(_codex_settings_for_chat(cid))
            if (_DESKTOP_EXECUTION_PROFILE.get() == "host_setup"
                    or _is_onboarding_guide_chat(cid)):
                payload["execution_profile"] = "host_setup"
        elif agent["id"] == CLAUDE_AGENT_ID:
            payload.update(_claude_settings_for_chat(cid))
        elif agent["id"] == MINIMAX_AGENT_ID:
            payload.update(_minimax_settings_for_chat(cid))
        elif agent["id"] == ANTIGRAVITY_AGENT_ID:
            payload.update(_antigravity_settings_for_chat(cid))
        elif agent["id"] == GROK_AGENT_ID:
            payload.update(_grok_settings_for_chat(cid))
        elif agent["id"] == PERPLEXITY_AGENT_ID:
            payload.update(_perplexity_settings_for_chat(cid))
        elif agent["id"] == OPENROUTER_AGENT_ID:
            payload.update(_openrouter_settings_for_chat(cid))
        if request_workspace:
            payload["workspace"] = request_workspace
        # Auto-retry transient upstream failures (overload/rate-limit/gateway,
        # or the bridge momentarily unreachable) with exponential backoff before
        # giving up, so a sequential turn isn't stranded by a passing 529. Read
        # timeouts are intentionally NOT retried here — AGENT_TIMEOUT_S is long,
        # and a genuine slow turn is handled at the dispatch layer, not stacked.
        data = None
        for attempt in range(1, AGENT_RETRY_MAX + 1):
            try:
                async with httpx.AsyncClient(timeout=_agent_timeout(AGENT_TIMEOUT_S)) as client:
                    resp = await client.post(agent["url"], json=payload, headers=headers)
                    if resp.status_code == 401:
                        raise RuntimeError("API key rejected by agent (token rotated?).")
                    # If the stored context_id is stale (agent restarted, context
                    # expired), the agent returns 404. Drop our stored ID and retry
                    # once with a fresh context so we re-establish one continuous chat.
                    if resp.status_code == 404 and ctx:
                        contexts.pop(agent["id"], None)
                        _save_contexts(cid, contexts)
                        retry_payload: dict = {
                            "message": _message_with_full_preamble(agent, cid, message),
                            "workspace_access": access_mode,
                        }
                        if agent["id"] == CODEX_AGENT_ID:
                            retry_payload.update(_codex_settings_for_chat(cid))
                            if (_DESKTOP_EXECUTION_PROFILE.get() == "host_setup"
                                    or _is_onboarding_guide_chat(cid)):
                                retry_payload["execution_profile"] = "host_setup"
                        elif agent["id"] == CLAUDE_AGENT_ID:
                            retry_payload.update(_claude_settings_for_chat(cid))
                        elif agent["id"] == MINIMAX_AGENT_ID:
                            retry_payload.update(_minimax_settings_for_chat(cid))
                        elif agent["id"] == ANTIGRAVITY_AGENT_ID:
                            retry_payload.update(_antigravity_settings_for_chat(cid))
                        elif agent["id"] == GROK_AGENT_ID:
                            retry_payload.update(_grok_settings_for_chat(cid))
                        elif agent["id"] == PERPLEXITY_AGENT_ID:
                            retry_payload.update(_perplexity_settings_for_chat(cid))
                        elif agent["id"] == OPENROUTER_AGENT_ID:
                            retry_payload.update(_openrouter_settings_for_chat(cid))
                        if request_workspace:
                            retry_payload["workspace"] = request_workspace
                        resp = await client.post(agent["url"], json=retry_payload, headers=headers)
                    if resp.status_code >= 400:
                        raise _agent_http_error(resp)
                    resp.raise_for_status()
                    try:
                        data = resp.json()
                    except json.JSONDecodeError:
                        return resp.text, {}
                break  # success — leave the retry loop
            except httpx.ConnectError as exc:
                transient_exc: Exception = exc
            except RuntimeError as exc:
                if not getattr(exc, "transient", False):
                    raise  # a real fault (401/404/4xx) — surface it immediately
                transient_exc = exc
            # A transient failure: back off and retry unless attempts are exhausted.
            if attempt >= AGENT_RETRY_MAX:
                raise transient_exc
            delay = min(AGENT_RETRY_CAP_S, AGENT_RETRY_BASE_S * (2 ** (attempt - 1)))
            await _route_system_note(
                cid,
                f"{agent['name']} hit a temporary error — retrying in {int(delay)}s "
                f"({attempt}/{AGENT_RETRY_MAX - 1}): {str(transient_exc)[:120]}",
                level="warn",
            )
            await asyncio.sleep(delay)

        if isinstance(data, dict) and "context_id" in data:
            new_ctx = data["context_id"]
            if contexts.get(agent["id"]) != new_ctx:
                contexts[agent["id"]] = new_ctx
                _save_contexts(cid, contexts)
        return _agent_response_text_and_metadata(agent["id"], data)


# --- Per-chat workspace (Phase 1: un-sandbox the file-capable agents) -------
# Each chat resolves to ONE workspace, shared by the file-capable bridge agents
# (claude, codex, antigravity), so "do the work" lands in a real project dir
# instead of inside the Agent-Chat app folder. Default: an auto-created scratch
# dir per chat under AGENT_WORKSPACES_ROOT. A chat can be bound to an existing
# project via the /api/send `workspace` field (kept in WORKSPACE_BY_CHAT).
# Injected for the file-capable agents: claude/codex/antigravity (bridge spawns a
# CLI in this cwd) and minimax (bridge passes it as the Mavis daemon session's
# workspaceDir). NOT injected for Lead/Sales (Agent Zero containers) or Hermes
# (containerized, MiniMax-M3 cloud model) — those runtimes own their workspace.
WORKSPACES_ROOT = Path(
    os.environ.get("AGENT_WORKSPACES_ROOT", str(Path.home() / "AGENTS" / "workspaces"))
).expanduser()
WORKSPACE_BY_CHAT: dict[int, str] = {}
# Persist bindings across restart — a small JSON sidecar rather than a chats
# table column (single-user, tiny, and avoids the DB's multi-path write logic).
WORKSPACE_BINDINGS_FILE = Path(
    os.environ.get("WORKSPACE_BINDINGS_FILE", str(DATA_DIR / "workspace_bindings.json"))
)
# Where "create a workspace folder" lands by default (confirmed with Owner
# 2026-07-17): a dedicated projects root, discoverable by the picker.
PROJECTS_FOLDER_ROOT = Path(
    os.environ.get("PROJECTS_FOLDER_ROOT", str(Path.home() / "AGENTS" / "projects"))
).expanduser()
# Roots whose immediate subdirectories the picker offers as named projects.
WORKSPACE_DISCOVER_ROOTS = [
    Path(p).expanduser()
    for p in os.environ.get(
        "WORKSPACE_DISCOVER_ROOTS",
        os.pathsep.join([str(Path.home() / "AGENTS"), str(PROJECTS_FOLDER_ROOT)]),
    ).split(os.pathsep)
    if p.strip()
]
# Folders agents must never use as a working directory: the live Agent-Chat
# tree (this running app — agents get read-only ideas, never a cwd) and the
# pinned references library. Compared realpath-to-realpath at bind time so the
# versions/v5.15 symlink route cannot sidestep the guard. Extend via env
# (os.pathsep-joined absolute paths).
PROTECTED_WORKSPACE_PATHS = [
    BASE_DIR.parent,
    Path.home() / "AGENTS" / "references",
] + [
    Path(p).expanduser()
    for p in os.environ.get("PROTECTED_WORKSPACE_PATHS", "").split(os.pathsep)
    if p.strip()
]


def _path_identity(path: Path) -> Optional[tuple]:
    """(device, inode) — a filesystem's own idea of "the same directory"."""
    try:
        st = path.stat()
        return (st.st_dev, st.st_ino)
    except OSError:
        return None


def _protected_workspace_reason(raw: str) -> Optional[str]:
    """Human-readable refusal if `raw` is, or sits inside, a protected tree.

    Compares by filesystem IDENTITY (device+inode), not by path text. macOS is
    case-insensitive, so /users/... and /Users/... are the same directory while
    comparing unequal as strings — which let the live app tree be attached as a
    workspace just by changing the case. Identity also covers symlinks, hard
    links and `..`, all of which reach the same inode by a different spelling.
    """
    try:
        candidate = Path(raw).expanduser().resolve()
    except OSError:
        return "path could not be resolved"
    chain = [(p, _path_identity(p)) for p in [candidate, *candidate.parents]]
    for protected in PROTECTED_WORKSPACE_PATHS:
        try:
            root = protected.expanduser().resolve()
        except OSError:
            continue
        refusal = (
            f"{root.name or str(root)} is protected — it is read-only for "
            "agents and cannot be a project workspace"
        )
        root_id = _path_identity(root)
        if root_id is None:
            # Protected path doesn't exist (yet); fall back to text comparison.
            if candidate == root or root in candidate.parents:
                return refusal
            continue
        for _p, ident in chain:
            if ident is not None and ident == root_id:
                return refusal
    return None


def _managed_project_root(owner_user_id: int) -> Path:
    """Private filesystem root for a non-admin user's project workspace folders."""
    return PROJECTS_FOLDER_ROOT / f"user-{int(owner_user_id)}"


def _validated_workspace_path(
    raw: object,
    user: Optional[dict],
    *,
    require_exists: bool = True,
) -> tuple[Optional[Path], Optional[str]]:
    """Canonicalize and authorize an explicit workspace/project directory.

    Admins may attach any existing unprotected directory. Regular users are
    confined to their own managed project root; this app has no OS-level uid or
    container boundary, so letting them point a host-side agent/process at an
    arbitrary absolute path would expose the service account's files.
    """
    if not isinstance(raw, str):
        return None, "workspace must be a string path"
    cleaned = raw.strip()
    if not cleaned:
        return None, "workspace path required"
    if not _workspace_path_is_safe(cleaned):
        return None, "workspace path may not contain quotes, backslashes, or control characters"
    expanded = Path(cleaned).expanduser()
    if not expanded.is_absolute():
        return None, "workspace must be an absolute path"
    try:
        resolved = expanded.resolve()
    except OSError:
        return None, "workspace path could not be resolved"
    if require_exists and not resolved.is_dir():
        return None, "workspace folder does not exist"
    protected = _protected_workspace_reason(str(resolved))
    if protected:
        return None, protected
    if not user:
        return None, "workspace owner could not be resolved"
    if not _is_admin_user(user):
        try:
            managed_root = _managed_project_root(int(user["id"])).resolve()
        except (KeyError, OSError, TypeError, ValueError):
            return None, "workspace owner could not be resolved"
        if resolved != managed_root and managed_root not in resolved.parents:
            return None, "workspace must be inside your managed workspace folder"
    return resolved, None


def _load_workspace_bindings() -> None:
    try:
        if WORKSPACE_BINDINGS_FILE.is_file():
            data = json.loads(WORKSPACE_BINDINGS_FILE.read_text())
            if isinstance(data, dict):
                for k, v in data.items():
                    try:
                        if isinstance(v, str) and os.path.isabs(v):
                            WORKSPACE_BY_CHAT[int(k)] = v
                    except (TypeError, ValueError):
                        continue
    except Exception:
        pass


def _save_workspace_bindings() -> None:
    try:
        tmp = WORKSPACE_BINDINGS_FILE.with_suffix(".tmp")
        tmp.write_text(
            json.dumps({str(k): v for k, v in sorted(WORKSPACE_BY_CHAT.items())}, indent=2)
        )
        tmp.replace(WORKSPACE_BINDINGS_FILE)
    except OSError:
        pass


def _git_branch(path: str) -> Optional[str]:
    """Current git branch of `path`, or None if it isn't a repo. Best-effort."""
    try:
        out = subprocess.run(
            ["git", "-C", path, "rev-parse", "--abbrev-ref", "HEAD"],
            capture_output=True, text=True, timeout=3,
        )
        if out.returncode == 0:
            return out.stdout.strip() or None
    except Exception:
        pass
    return None


def _workspace_registry(user: Optional[dict] = None) -> list[dict]:
    """Named workspaces the picker offers: immediate subdirs of the discover
    roots (the user's project workspace folders), with git branch where applicable. The
    per-chat scratch root itself is excluded."""
    seen: set = set()
    out: list[dict] = []
    roots = (
        WORKSPACE_DISCOVER_ROOTS
        if _is_admin_user(user)
        else ([_managed_project_root(int(user["id"]))] if user else [])
    )
    for root in roots:
        try:
            children = sorted((p for p in root.iterdir() if p.is_dir()), key=lambda p: p.name.lower())
        except OSError:
            continue
        for child in children:
            try:
                rp = str(child.resolve())
            except OSError:
                continue
            resolved = child.resolve()
            if rp in seen or resolved == WORKSPACES_ROOT.resolve():
                continue
            # A discover root nested under another (e.g. ~/AGENTS/projects under
            # ~/AGENTS) is a container, not a project itself.
            if any(resolved == r.expanduser().resolve() for r in WORKSPACE_DISCOVER_ROOTS):
                continue
            # Never offer what bind-time will reject (live app tree, references).
            if _protected_workspace_reason(rp):
                continue
            seen.add(rp)
            out.append({"name": child.name, "path": rp, "branch": _git_branch(rp)})
    return out


# A workspace path is later interpolated into a shell command AND an AppleScript
# `do script "..."` literal (Terminal launch). Reject anything that could break
# out of either quoting layer — double-quote, backslash, and any control char
# (CR/LF/NUL). This is the primary guard against workspace-path command injection;
# _open_command_for additionally AppleScript-escapes as defense-in-depth.
# Backslashes are path separators on Windows, so reject them only on POSIX where
# the path is later embedded in an AppleScript command. Quotes and control bytes
# remain invalid everywhere.
_WORKSPACE_FORBIDDEN = re.compile(
    r'["\x00-\x1f\x7f]' if os.name == "nt" else r'["\\\x00-\x1f\x7f]'
)


def _workspace_path_is_safe(path: str) -> bool:
    return not _WORKSPACE_FORBIDDEN.search(path or "")


def _safe_download_name(name: object, fallback: str = "file") -> str:
    """Filesystem- and header-safe display name for a stored/served file. Strips
    path separators, double-quotes, and control chars so the name cannot break out
    of a `Content-Disposition: ... filename="…"` token or traverse a path."""
    cleaned = re.sub(r'[/\\"\r\n\x00-\x1f\x7f]', "_", str(name or "")).strip()
    return (cleaned or fallback)[:200]


def _uniquify_artifact_name(name: object, taken) -> str:
    """Return `name` unchanged when it is free, else append a ` (2)`, ` (3)`, …
    counter *before* the extension so two DIFFERENT files never share a display
    label in Files/Canvas. `taken` is any container of names already shown.

    This only disambiguates the human-facing title; the on-disk file and the
    artifact's identity key (`source_name`) are left untouched, so re-scans that
    key on the real basename stay idempotent."""
    name = str(name or "")
    if name not in taken:
        return name
    head, dot, tail = name.rpartition(".")
    stem, suffix = (head, "." + tail) if dot else (name, "")
    n = 2
    while f"{stem} ({n}){suffix}" in taken:
        n += 1
    return f"{stem} ({n}){suffix}"


def _set_chat_workspace(cid: int, raw: object) -> bool:
    """Bind a chat to a project dir (absolute path), or clear the binding (revert
    to the per-chat scratch dir) when raw is empty/"default"/"scratch". Returns
    True if the binding changed. Persisted across restart. A non-absolute or
    non-string value is ignored, so a stray /api/send field never breaks a send."""
    if not isinstance(raw, str):
        return False
    raw = raw.strip()
    changed = False
    if raw in ("", "default", "scratch"):
        if WORKSPACE_BY_CHAT.pop(cid, None) is not None:
            changed = True
    else:
        owner = _user_by_id(_chat_owner_id(cid))
        path, error = _validated_workspace_path(raw, owner)
        if error or path is None:
            # Defense-in-depth for non-HTTP callers: invalid paths never replace
            # the last known-good binding. HTTP routes return the precise error.
            return False
        new = str(path)
        if WORKSPACE_BY_CHAT.get(cid) != new:
            WORKSPACE_BY_CHAT[cid] = new
            changed = True
    if changed:
        _save_workspace_bindings()
    return changed


def _chat_project_folder(cid: int) -> Optional[dict]:
    """The folder-bearing project this chat belongs to, or None. Returns the
    project row so callers can name it (tombstones, UI badges)."""
    try:
        project = _project_row(_chat_project_id(cid))
    except Exception:
        return None
    if project and isinstance(project.get("folder"), str) and project["folder"].strip():
        return project
    return None


def _chat_coding_project(cid: int) -> Optional[dict]:
    """Return coding context only when this conversation opted into it.

    ``auto`` preserves the behavior of pre-migration conversations. Explicitly
    regular chats remain regular even when they are organized inside a project
    that also has source files attached.
    """
    if _chat_intent(cid) == "chat":
        return None
    return _chat_project_folder(cid)


def _chat_workspace_info(cid: int) -> dict:
    """Resolve this chat's effective workspace and which layer supplied it.
    Precedence (locked 2026-07-17): explicit chat binding > project workspace folder >
    per-chat scratch. The winning dir is created on demand like scratch always
    was, so a freshly attached project workspace folder can never 404 a bridge spawn."""
    bound = WORKSPACE_BY_CHAT.get(cid)
    source, project = "scratch", None
    owner = _user_by_id(_chat_owner_id(cid))
    if bound:
        validated, error = _validated_workspace_path(bound, owner)
        if not error and validated is not None:
            path, source = validated, "chat"
        else:
            bound = None
    if not bound:
        project = _chat_project_folder(cid)
        if project:
            validated, error = _validated_workspace_path(project["folder"], owner)
            if not error and validated is not None:
                path, source = validated, "project"
            else:
                project = None
        if not project:
            path = WORKSPACES_ROOT / f"chat-{cid}"
    try:
        path.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass
    return {
        "path": str(path),
        "source": source,
        "project_id": int(project["id"]) if project else None,
        "project_number": project.get("number") if project else None,
        "project_title": project.get("title") if project else None,
    }


def _chat_workspace(cid: int) -> str:
    return _chat_workspace_info(cid)["path"]


_TOMBSTONE_NAME = "MOVED.md"


def _atomic_replace_text(path: Path, content: str) -> None:
    """Atomically replace a text file without ever following its final symlink."""
    fd, tmp_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
    tmp_path = Path(tmp_name)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    finally:
        try:
            tmp_path.unlink(missing_ok=True)
        except OSError:
            pass


def _create_text_exclusive(path: Path, content: str) -> bool:
    """Create a seed file once, refusing existing files and final symlinks."""
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        fd = os.open(path, flags, 0o600)
    except OSError:
        return False
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(content)
        return True
    except OSError:
        return False


def _sync_scratch_tombstone(cid: int) -> None:
    """Reconcile the MOVED.md tombstone in this chat's scratch dir (Owner
    requirement 2026-07-17: a vacated chat-# folder must say where the work
    went so future-you never wonders why it's empty). Idempotent: writes or
    rewrites the tombstone while the chat works elsewhere, removes it when the
    chat comes home to scratch. Never creates the scratch dir just to mark it."""
    scratch = WORKSPACES_ROOT / f"chat-{cid}"
    try:
        # A chat scratch path is app-managed. If it has been replaced by a
        # symlink (or moved outside the configured root), do not write through it.
        root = WORKSPACES_ROOT.expanduser().resolve()
        if scratch.is_symlink() or scratch.parent.expanduser().resolve() != root:
            return
        info = _chat_workspace_info(cid)
        marker = scratch / _TOMBSTONE_NAME
        if not scratch.is_dir():
            return
        scratch_real = scratch.resolve()
        if scratch_real.parent != root:
            return
        if Path(info["path"]).expanduser().resolve() == scratch_real:
            if scratch.is_dir():
                marker.unlink(missing_ok=True)
            return
        if info["source"] == "project":
            where = (
                f"project **{info.get('project_number') or ''} — "
                f"{info.get('project_title') or 'untitled'}**"
            )
        else:
            where = "a folder this chat was explicitly bound to"
        _atomic_replace_text(marker,
            "# This chat's workspace moved\n\n"
            f"Agents Chat conversation #{cid} now works in:\n\n"
            f"    {info['path']}\n\n"
            f"(inherited from {where})\n\n"
            f"Recorded {time.strftime('%Y-%m-%d %H:%M')}. Anything else in this "
            "folder predates the move and is kept as-is; new work lands in the "
            "folder above.\n"
        )
    except OSError:
        pass


def _seed_project_md(folder: Path, project: dict) -> None:
    """Seed the file-memory conventions into a newly attached workspace folder:
    PROJECT.md (identity + the owner-only directives section, Karpathy's
    program.md pattern), DECISIONS.md, TASKS.md, and notes/. Never overwrites —
    an existing file is the project's own."""
    number = project.get("number") or f"P-{project.get('id')}"
    title = project.get("title") or "Untitled project"
    today = time.strftime("%Y-%m-%d")
    seeds = {
        "PROJECT.md": (
            f"# {number} — {title}\n\n"
            f"Workspace folder for the Agents Chat project \"{title}\", created "
            f"{today}. Every conversation assigned here uses this directory as "
            "the agents' working directory.\n\n"
            "## Purpose\n\n"
            "_One paragraph on what this project is for — fill me in._\n\n"
            "## Owner's directives\n\n"
            "_Owner-only section: Owner writes here; agents read it every visit "
            "and NEVER edit it. Standing instructions placed here outrank "
            "anything an agent inferred on its own._\n\n"
            "## Ground rules for agents\n\n"
            "- Work happens in this folder and its subfolders only.\n"
            "- Durable knowledge lands in files here, not in chat scrollback: "
            "settled calls in DECISIONS.md, open work in TASKS.md, scratch "
            "thinking in notes/.\n"
            "- Keep this file current: it is the first thing an agent reads.\n"
        ),
        "DECISIONS.md": (
            f"# Decisions — {number} {title}\n\n"
            "Append one dated line per settled call, newest first. A decision "
            "recorded here is binding until a newer line reverses it.\n\n"
            f"- {today}: workspace folder created; conventions seeded.\n"
        ),
        "TASKS.md": (
            f"# Tasks — {number} {title}\n\n"
            "The live to-do list. Agents keep it truthful: check items off when "
            "verified done, add discovered work, never delete history.\n\n"
            "- [ ] Fill in PROJECT.md's Purpose section\n"
        ),
        "notes/README.md": (
            "Working notes live here — research dumps, drafts, scratch "
            "thinking. One markdown file per topic. Promote anything durable "
            "up into DECISIONS.md or TASKS.md.\n"
        ),
    }
    try:
        folder_root = folder.expanduser().resolve(strict=True)
    except OSError:
        return
    if not folder_root.is_dir():
        return
    for rel, content in seeds.items():
        try:
            target = folder_root / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            parent_real = target.parent.resolve(strict=True)
            if parent_real != folder_root and folder_root not in parent_real.parents:
                continue
            _create_text_exclusive(parent_real / target.name, content)
        except OSError:
            continue


def _ensure_project_folder(
    project: Optional[dict], user: Optional[dict],
) -> Optional[dict]:
    """Create and bind a default workspace folder for a folderless project.

    Runs at project creation and at every file-into-project path, so rows from
    the era when projects were born folderless (DB row only, folder attach a
    separate manual step nobody took) heal on next use. Best-effort by design:
    any refusal (validation, mkdir) leaves the project folderless rather than
    failing the caller — manual attach via PATCH remains available.
    """
    if not project or not user or str(project.get("folder") or "").strip():
        return None
    try:
        pid = int(project.get("id") or 0)
        owner_id = int(project.get("owner_user_id") or 0)
    except (TypeError, ValueError):
        return None
    if not pid or not owner_id or int(user.get("id") or 0) != owner_id:
        return None
    root = (
        PROJECTS_FOLDER_ROOT if _is_admin_user(user)
        else _managed_project_root(owner_id)
    )
    base = re.sub(
        r"[^a-z0-9]+", "-", str(project.get("title") or "").lower(),
    ).strip("-")[:60]
    base = base or str(project.get("number") or f"p-{pid}").lower()
    for attempt in range(1, 21):
        name = base if attempt == 1 else f"{base}-{attempt}"
        target, error = _validated_workspace_path(
            str(root / name), user, require_exists=False,
        )
        if error or target is None:
            return None
        with _db() as conn:
            taken = conn.execute(
                "SELECT 1 FROM projects WHERE folder=? AND id<>?",
                (str(target), pid),
            ).fetchone()
        if taken:
            continue  # directory already belongs to a sibling project
        try:
            target.mkdir(parents=True, exist_ok=True)
        except OSError:
            return None
        updated = _update_project(pid, owner_id, {"folder": str(target)})
        if updated:
            _seed_project_md(target, updated)
        return updated
    return None


async def _rehome_project_member_chats(project_id: int) -> None:
    """After a project workspace folder change, re-home every member chat that has no
    explicit binding of its own: reconcile tombstones in vacated scratch dirs
    and tell open clients which cwd is now live."""
    for member_cid in _project_member_chat_ids(int(project_id)):
        if WORKSPACE_BY_CHAT.get(member_cid) is not None:
            continue
        info = _chat_workspace_info(member_cid)
        _sync_scratch_tombstone(member_cid)
        await broadcast({
            "type": "chat_meta", "chat_id": member_cid,
            "workspace": info["path"], "workspace_is_default": True,
            "workspace_source": info["source"],
        }, global_event=True)


def _project_member_chat_ids(project_id: int) -> list[int]:
    with _db() as conn:
        rows = conn.execute(
            "SELECT c.id FROM chats AS c "
            "JOIN projects AS p ON p.id=c.project_id "
            "AND p.owner_user_id=c.owner_user_id "
            "WHERE p.id=? AND c.deleted_ts IS NULL",
            (int(project_id),),
        ).fetchall()
    return [int(r["id"]) for r in rows]


_load_workspace_bindings()


# --- Remembered model picks ----------------------------------------------------
# The model/reasoning cards are a GLOBAL per-agent preference in the browser
# (localStorage), replayed into the payload of every /api/send. The per-chat
# caches below are only a shadow of that, and they live in memory — so the
# moment a turn is NOT started by a browser send, the fallback used to be the
# shipped .env default. That covers a lot of turns: anything after an app
# restart, every automation and scheduled skill, free-will sessions, Telegram
# replies, and any agent answering in a series chat the browser never posted to.
# A room set to gpt-5.6 quietly answered on gpt-5.5, and the chip said so with
# no way to tell it from a real pick. Persist the last pick per agent so the
# fallback is the user's own choice; the shipped default only applies until the
# first pick is made.
_AGENT_SETTINGS_KEY = "agent_model_settings"
_AGENT_SETTINGS_KEY_PREFIX = f"{_AGENT_SETTINGS_KEY}:user:"
_REMEMBERED_AGENT_SETTINGS: dict[int, dict[str, dict]] = {}
_REMEMBERED_AGENT_SETTINGS_LOADED: set[int] = set()
_AUTO_REASONING_KEY_PREFIX = "auto_reasoning:user:"


def _agent_settings_key(owner_user_id: int) -> str:
    return f"{_AGENT_SETTINGS_KEY_PREFIX}{int(owner_user_id)}"


def _load_remembered_agent_settings(owner_user_id: Optional[int] = None) -> None:
    """Read one owner's persisted picks lazily — the DB isn't ready at import.

    The pre-v7.27 install-global row is accepted only for the bootstrap admin
    and copied forward on first read. Other owners must never inherit it.
    """
    owner_id = int(owner_user_id or _default_admin_id())
    scoped_key = _agent_settings_key(owner_id)
    raw_text = _get_setting(scoped_key, "")
    legacy = False
    if not raw_text and owner_id == int(_default_admin_id()):
        raw_text = _get_setting(_AGENT_SETTINGS_KEY, "")
        legacy = bool(raw_text)
    try:
        raw = json.loads(raw_text or "{}")
        remembered = {
            str(k): v for k, v in raw.items() if isinstance(v, dict)
        } if isinstance(raw, dict) else {}
    except Exception:
        remembered = {}
    _REMEMBERED_AGENT_SETTINGS[owner_id] = remembered
    _REMEMBERED_AGENT_SETTINGS_LOADED.add(owner_id)
    if legacy and remembered:
        try:
            _set_setting(scoped_key, json.dumps(remembered))
        except Exception:
            logger.exception(
                "could not migrate remembered model settings for owner %s", owner_id,
            )


def _remember_agent_settings(owner_user_id: int, agent_id: str, settings: dict) -> None:
    """Record the pick a send just carried. Writes only on change, so the common
    case (same settings every send) costs one dict compare."""
    owner_id = int(owner_user_id or _default_admin_id())
    if owner_id not in _REMEMBERED_AGENT_SETTINGS_LOADED:
        _load_remembered_agent_settings(owner_id)
    remembered = _REMEMBERED_AGENT_SETTINGS.setdefault(owner_id, {})
    if remembered.get(agent_id) == settings:
        return
    remembered[agent_id] = dict(settings)
    try:
        _set_setting(_agent_settings_key(owner_id), json.dumps(remembered))
    except Exception:
        # A failed write costs the remembered pick after the next restart, not
        # this turn — never let it break the send.
        logger.exception(
            "could not persist %s model settings for owner %s", agent_id, owner_id,
        )


def _remembered_agent_settings(owner_user_id: int, agent_id: str, normalize) -> dict:
    """The agent's last pick, re-validated against the CURRENT option list, or
    the shipped default when there's no pick yet. Re-validating matters because
    an upgrade can retire a model someone had selected months ago."""
    owner_id = int(owner_user_id or _default_admin_id())
    if owner_id not in _REMEMBERED_AGENT_SETTINGS_LOADED:
        _load_remembered_agent_settings(owner_id)
    return normalize(
        (_REMEMBERED_AGENT_SETTINGS.get(owner_id) or {}).get(agent_id) or {}
    )


def _settings_owner_for_chat(cid: int) -> int:
    """Resolve model preferences in the same tenant boundary as the chat."""
    return int(_chat_owner_id(cid) or _default_admin_id())


def _auto_reasoning_key(owner_user_id: int) -> str:
    return f"{_AUTO_REASONING_KEY_PREFIX}{int(owner_user_id)}"


def _auto_reasoning_preference_value(owner_user_id: Optional[int]) -> Optional[bool]:
    """Stored preference, or None while an upgraded browser still owns the value."""
    owner_id = int(owner_user_id or _default_admin_id())
    raw = str(_get_setting(_auto_reasoning_key(owner_id), "") or "").strip().lower()
    if not raw:
        return None
    return raw in {
        "1", "true", "yes", "on",
    }


def _auto_reasoning_preference(owner_user_id: Optional[int]) -> bool:
    """Server-authoritative Auto preference used by skills and schedules."""
    return _auto_reasoning_preference_value(owner_user_id) is True


def _set_auto_reasoning_preference(owner_user_id: int, enabled: bool) -> None:
    _set_setting(_auto_reasoning_key(int(owner_user_id)), "1" if enabled else "0")


# --- Per-run model pins (skills) -----------------------------------------------
# A skill can pin the model/reasoning each agent uses while IT runs. The pins are
# deliberately RUN-scoped, never chat-scoped: a skill that runs in a chat you
# also type in must not change what your own later messages run on. A contextvar
# carries them because create_task() copies it into the detached turn (same
# reason as _SERIES_CTX above) and the token is reset when apply_skill returns —
# so nothing outside that task tree can see them.
_RUN_MODEL_PINS: "contextvars.ContextVar[Optional[dict]]" = contextvars.ContextVar(
    "run_model_pins", default=None
)
# Never infer this from model output. Detached setup jobs set it explicitly;
# synchronous onboarding turns use the server-owned __onboarding_guide__ chat
# marker instead so the conductor can finish setup without a UI handoff.
_DESKTOP_EXECUTION_PROFILE: "contextvars.ContextVar[str]" = contextvars.ContextVar(
    "desktop_execution_profile", default=""
)
# Memo keyed by turn_runs.id, for the one dispatch path that runs OUTSIDE the
# run's task tree (the nudge in _dispatch_nudge) and therefore can't inherit the
# contextvar. Popped when the run finishes, so it can't outlive it.
_RUN_PINS_BY_RUN: dict[int, dict] = {}


def _run_model_pin(agent_id: str, cid: int) -> dict:
    """This agent's pins for the run in flight, or {} when nothing is pinned."""
    pins = _RUN_MODEL_PINS.get()
    if pins is None:
        run_id = _active_turn_run_id(cid)
        pins = _RUN_PINS_BY_RUN.get(int(run_id)) if run_id else None
    return dict((pins or {}).get(agent_id) or {})


def _pinned_settings(agent_id: str, cid: int, base: dict, normalize) -> dict:
    """Layer a run's pins over the room's resolved settings.

    The pin is merged per KEY, so pinning only `reasoning` leaves `model` on
    whatever the room resolved. Re-normalising after the merge is belt and
    braces — `_skill_agent_settings_normalize` already dropped anything invalid,
    so this can no longer coerce a pin into the shipped default."""
    pin = _run_model_pin(agent_id, cid)
    return normalize({**base, **pin}) if pin else base


def _normalize_codex_settings(raw: object) -> dict:
    raw = raw if isinstance(raw, dict) else {}
    model = str(raw.get("model") or CODEX_DEFAULT_MODEL).strip()
    reasoning = str(raw.get("reasoning") or CODEX_DEFAULT_REASONING).strip()
    if model not in CODEX_MODEL_OPTIONS:
        model = CODEX_DEFAULT_MODEL
    if reasoning not in CODEX_REASONING_OPTIONS:
        reasoning = CODEX_DEFAULT_REASONING
    return {"model": model, "reasoning": reasoning}


def _codex_settings_for_chat(cid: int) -> dict:
    s = dict(CODEX_SETTINGS_BY_CHAT.get(cid) or _remembered_agent_settings(
        _settings_owner_for_chat(cid),
        CODEX_AGENT_ID, _normalize_codex_settings,
    ))
    s = _pinned_settings(CODEX_AGENT_ID, cid, s, _normalize_codex_settings)
    s["workspace"] = _chat_workspace(cid)
    return s


