def _decision_owned_row(did: int, user: dict):
    with _db() as conn:
        row = conn.execute(
            "SELECT * FROM team_decisions WHERE id=? AND owner_user_id=?",
            (int(did), int(user["id"])),
        ).fetchone()
    return row


def _decisions_list_payload(user: dict, include_superseded: bool, query: str = "") -> dict:
    decisions = _get_team_decisions(
        user["id"], include_superseded=include_superseded, query=query, limit=500,
    )
    if query and not decisions and not include_superseded:
        decisions = _decision_token_fallback(user["id"], query, limit=100)
    for d in decisions:
        d["date"] = time.strftime("%Y-%m-%d", time.localtime((d["created_ts"] or 0) / 1000))
    # Learn-on-miss telemetry for a direct owner ledger search. It is deliberately
    # absent from the public response below.
    if query and not decisions:
        _record_gap(user["id"], query, asked_by="user", store="decisions")
    projects = {}
    try:
        for p in _list_projects(user):
            projects[str(p.get("id"))] = f"{p.get('number')} — {p.get('title')}"
    except Exception:
        pass
    # Failed searches are internal retrieval telemetry, never an owner inbox. Keep
    # the legacy key empty so older clients degrade quietly while reconciliation
    # happens through the explicit internal endpoint below.
    return {"decisions": decisions, "projects": projects, "gaps": []}


