@app.post("/api/decisions")
async def api_decisions_add(request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    body = await request.json()
    project_id = body.get("project_id")
    if project_id and not _project_belongs_to_user(project_id, user):
        return JSONResponse({"error": "unknown project"}, status_code=400)
    res = _add_team_decision(
        user["id"], str(body.get("statement") or ""), str(body.get("why") or ""),
        source="human",
        decided_by=(user.get("preferred_name") or user.get("display_name") or "owner"),
        project_id=int(project_id) if project_id else None,
        supersedes=body.get("supersedes"),
    )
    if not res.get("ok"):
        return JSONResponse({"error": res.get("error", "could not record")}, status_code=400)
    return {"ok": True, "id": res["id"], "duplicate": bool(res.get("duplicate_of"))}


@app.patch("/api/decisions/{did}")
async def api_decisions_edit(did: int, request: Request):
    """Owner curation: edit text/scope in place, or confirm=true to promote an
    agent-recorded entry to human trust (it stops rendering as unreviewed)."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    row = _decision_owned_row(did, user)
    if not row:
        return JSONResponse({"error": "not found"}, status_code=404)
    body = await request.json()
    sets, args = [], []
    if "statement" in body:
        statement = _decision_clean(body.get("statement"), _DECISION_STATEMENT_MAX)
        if not statement:
            return JSONResponse({"error": "statement cannot be empty"}, status_code=400)
        sets.append("statement=?"); args.append(statement)
    if "why" in body or "rationale" in body:
        sets.append("rationale=?")
        args.append(_decision_clean(body.get("why", body.get("rationale")), _DECISION_RATIONALE_MAX))
    if "project_id" in body:
        project_id = body.get("project_id")
        if project_id and not _project_belongs_to_user(project_id, user):
            return JSONResponse({"error": "unknown project"}, status_code=400)
        sets.append("project_id=?"); args.append(int(project_id) if project_id else None)
    if body.get("confirm"):
        sets.append("source='human'")
        sets.append("decided_by=?")
        args.append(user.get("preferred_name") or user.get("display_name") or "owner")
        sets.append("evidence_kind='user'")
        sets.append("evidence_ok=1")
    if not sets:
        return JSONResponse({"error": "nothing to update"}, status_code=400)
    with _db() as conn:
        conn.execute(
            f"UPDATE team_decisions SET {', '.join(sets)} WHERE id=? AND owner_user_id=?",
            (*args, int(did), int(user["id"])),
        )
    return {"ok": True}


@app.post("/api/decisions/{did}/supersede")
async def api_decisions_supersede(did: int, request: Request):
    """Retire an entry. With a replacement statement, the new entry takes its
    place (chained via superseded_by); without one it's simply retired."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    row = _decision_owned_row(did, user)
    if not row:
        return JSONResponse({"error": "not found"}, status_code=404)
    if row["superseded"]:
        return JSONResponse({"error": "already superseded"}, status_code=400)
    body = await request.json()
    statement = str(body.get("statement") or "").strip()
    if statement:
        res = _add_team_decision(
            user["id"], statement, str(body.get("why") or ""),
            source="human",
            decided_by=(user.get("preferred_name") or user.get("display_name") or "owner"),
            project_id=row["project_id"], supersedes=int(did),
        )
        if not res.get("ok"):
            return JSONResponse({"error": res.get("error", "could not supersede")}, status_code=400)
        return {"ok": True, "id": res.get("id")}
    with _db() as conn:
        conn.execute(
            "UPDATE team_decisions SET superseded=1 WHERE id=? AND owner_user_id=?",
            (int(did), int(user["id"])),
        )
    return {"ok": True}


