@app.post("/api/decisions/gaps/triage")
async def api_decisions_gap_triage(request: Request):
    """Compatibility route for an explicit internal reconcile + history pass.

    History answers close the telemetry row in place; they are not promoted into
    unscoped global decisions. Audited decision-id links belong in the reconcile
    endpoint; this compatibility action runs the scoped history pass.

    With resolve_app_issues (the checkbox, off until the owner opts in), questions
    that are really Agent Chat problems are also handed to a host CLI agent to
    fix in a writable checkout; those run detached and answer themselves in the
    ledger."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        body = await request.json()
    except Exception:
        body = {}
    resolve = _json_flag_true((body or {}).get("resolve_app_issues"))
    res = await _reconcile_memory_gaps(
        int(user["id"]), run_history=True, resolve_app_issues=resolve,
    )
    if not res.get("ok"):
        status = 409 if res.get("reason") == "already running" else 502
        return JSONResponse(
            {**res, "error": res.get("reason") or "triage failed"}, status_code=status,
        )
    return res


@app.post("/api/decisions/gaps/reconcile")
async def api_decisions_gap_reconcile(request: Request):
    """Explicit maintenance endpoint for internal failed-search telemetry.

    By default this applies only explicit ``links`` pairs of ``gap_id`` and
    ``decision_id``. ``run_history=true`` adds the bounded, scoped orchestrator pass
    for rows that remain open.
    """
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_admin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    try:
        body = await request.json()
    except Exception:
        body = {}
    run_history = _json_flag_true((body or {}).get("run_history"))
    resolve = _json_flag_true((body or {}).get("resolve_app_issues"))
    explicit_links = (body or {}).get("links")
    res = await _reconcile_memory_gaps(
        int(user["id"]), run_history=run_history,
        resolve_app_issues=(resolve and run_history),
        explicit_links=explicit_links if isinstance(explicit_links, list) else None,
    )
    if not res.get("ok"):
        status = 409 if res.get("reason") == "already running" else 502
        return JSONResponse(
            {**res, "error": res.get("reason") or "reconcile failed"}, status_code=status,
        )
    return res


