@app.post("/api/coding_jobs/{job_id}/merge")
async def api_merge_coding_job(job_id: int, request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    blocked = _require_coding_host_admin(request)
    if blocked:
        return blocked
    job, err = _coding_job_or_404(job_id, user)
    if err:
        return err
    if int(job.get("owner_user_id") or 0) != int(user["id"]):
        return JSONResponse({"error": "only the job owner can merge"}, status_code=403)
    # Fail fast instead of leaving the HTTP request waiting behind a long
    # implementer turn. The locked transaction below repeats this check to
    # close the race with a follow-up that commits after this read.
    with _db() as conn:
        if coding_jobs.pending_instructions(conn, job_id):
            return JSONResponse(
                {"error": "new instructions are still pending; wait for the crew to finish"},
                status_code=409,
            )
    # Merge is a filesystem mutation just like an implementer turn.  Share the
    # runner lock so a follow-up wake cannot edit (or lose) the worktree while
    # it is being merged and cleaned up.  The SQLite write lock then makes the
    # final pending/status check atomic with completion: an enqueue that won
    # first blocks this merge, while one that arrives after commit sees `done`
    # and opens a new managed job.
    async with _coding_runner_lock(job_id):
        with _db() as conn:
            conn.execute("BEGIN IMMEDIATE")
            job = coding_jobs.get_job(conn, job_id)
            if not job or int(job.get("owner_user_id") or 0) != int(user["id"]):
                return JSONResponse({"error": "job not found"}, status_code=404)
            if not conn.execute(
                "SELECT 1 FROM chats WHERE id=? AND deleted_ts IS NULL",
                (int(job.get("chat_id") or 0),),
            ).fetchone():
                return JSONResponse({"error": "job not found"}, status_code=404)
            if job["status"] not in {"review", "done"}:
                return JSONResponse({"error": "job is not ready to merge"}, status_code=409)
            if coding_jobs.pending_instructions(conn, job_id):
                return JSONResponse(
                    {"error": "new instructions are still pending; wait for the crew to finish"},
                    status_code=409,
                )
            if job.get("never_merge_live"):
                job = coding_jobs.update_job(
                    conn, job_id, status="done",
                    finished_ts=int(time.time() * 1000), error="",
                    _graph_actor_type="owner", _graph_actor_id=str(user["id"]),
                    _graph_reason="product accepted",
                )
            else:
                if job.get("branch"):
                    result = coding_jobs.merge_worktree(
                        Path(job["workspace"]), job["branch"], job.get("worktree") or "",
                    )
                    if not result.get("ok"):
                        return JSONResponse(
                            {"error": result.get("error") or "merge failed"},
                            status_code=409,
                        )
                job = coding_jobs.update_job(
                    conn, job_id, status="done",
                    finished_ts=int(time.time() * 1000), error="",
                    _graph_actor_type="owner", _graph_actor_id=str(user["id"]),
                    _graph_reason="reviewed branch merged",
                )
    await _room_clear_assignment(int(job["chat_id"]))
    if job.get("never_merge_live"):
        if job.get("bg_job_id"):
            _bg_finish_job(int(job["bg_job_id"]), "done", "product accepted")
        product = (job.get("report") or {}).get("product_path") or job.get("worktree")
        await _announce_coding_job(
            job,
            f"🎉 Job #{job_id} accepted. Product stays at {product} — live Agents Chat was not touched.",
        )
        return {"ok": True, "job": job}
    if job.get("bg_job_id"):
        _bg_finish_job(int(job["bg_job_id"]), "done", "merged")
    await _announce_coding_job(job, f"🎉 Job #{job_id} merged.")
    return {"ok": True, "job": job}


@app.post("/api/coding_jobs/{job_id}/cancel")
async def api_cancel_coding_job(job_id: int, request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    blocked = _require_coding_host_admin(request)
    if blocked:
        return blocked
    job, err = _coding_job_or_404(job_id, user)
    if err:
        return err
    if job["status"] in {"done", "cancelled"}:
        return JSONResponse({"error": "job already finished"}, status_code=409)
    with _db() as conn:
        conn.execute("BEGIN IMMEDIATE")
        current = coding_jobs.get_job(conn, job_id) or job
        if current.get("status") in {"done", "cancelled"}:
            return JSONResponse({"error": "job already finished"}, status_code=409)
        job = coding_jobs.update_job(
            conn, job_id, status="cancelled",
            finished_ts=int(time.time() * 1000),
            _graph_actor_type="owner", _graph_actor_id=str(user["id"]),
            _graph_reason="job cancelled",
        )
    await _quiesce_coding_job(job_id)
    if job.get("branch"):
        coding_jobs.cleanup_worktree(
            Path(job["workspace"]), job["branch"], job.get("worktree") or "",
        )
    await _room_clear_assignment(int(job["chat_id"]))
    if job.get("bg_job_id"):
        _bg_finish_job(int(job["bg_job_id"]), "cancelled", "cancelled by owner")
    await _announce_coding_job(job, f"Job #{job_id} cancelled.")
    return {"ok": True, "job": job}


@app.post("/api/coding_jobs/{job_id}/reject")
async def api_reject_coding_job(job_id: int, request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    blocked = _require_coding_host_admin(request)
    if blocked:
        return blocked
    job, err = _coding_job_or_404(job_id, user)
    if err:
        return err
    try:
        body = await _json_object_body(request, empty_ok=True)
    except ValueError:
        body = {}
    reason = str((body or {}).get("reason") or "rejected").strip()[:400]
    with _db() as conn:
        conn.execute("BEGIN IMMEDIATE")
        current = coding_jobs.get_job(conn, job_id) or job
        if current.get("status") in {"done", "cancelled"}:
            return JSONResponse({"error": "job already finished"}, status_code=409)
        job = coding_jobs.update_job(
            conn, job_id, status="blocked", error=reason,
            finished_ts=int(time.time() * 1000),
            _graph_actor_type="owner", _graph_actor_id=str(user["id"]),
            _graph_reason=reason,
        )
    await _quiesce_coding_job(job_id)
    if job.get("branch"):
        coding_jobs.cleanup_worktree(
            Path(job["workspace"]), job["branch"], job.get("worktree") or "",
        )
    await _room_clear_assignment(int(job["chat_id"]))
    if job.get("bg_job_id"):
        _bg_finish_job(int(job["bg_job_id"]), "blocked", reason)
    await _announce_coding_job(job, f"Job #{job_id} rejected — {reason}", level="warn")
    return {"ok": True, "job": job}


# ============================================================================
#  Skills & Automation
#  Turn a great chat into a reusable, named capability the orchestrator can
#  surface and apply again — a prose "playbook" or a structured "workflow"
#  (a chat mode + ordered per-stage instructions). Skills are DATA, never
#  executable: applying one only sets the room + feeds instructions through the
#  normal turn path, so nothing here can run a shell command. Same SQLite DB.
# ============================================================================

SKILL_KINDS = ("workflow", "playbook")
SKILL_STATUSES = ("draft", "active", "archived")
SCHEDULE_TRIGGERS = ("interval", "daily", "weekly", "manual", "event")
_SKILL_SLUG_RE = re.compile(r"[^a-z0-9]+")
_FTS_WORD_RE = re.compile(r"[A-Za-z0-9]+")
_ROLE_STOPWORDS = {
    "the", "a", "an", "and", "or", "for", "to", "of", "in", "on", "with", "this",
    "that", "please", "write", "make", "create", "your", "you", "it", "is", "as",
}
SKILL_DISTILL_TIMEOUT_S = float(os.environ.get("SKILL_DISTILL_TIMEOUT_S", "90"))
SKILL_COMPOSE_TIMEOUT_S = float(os.environ.get("SKILL_COMPOSE_TIMEOUT_S", "90"))
SKILL_SCHEDULER_TICK_S = float(os.environ.get("SKILL_SCHEDULER_TICK_S", "30"))

