# ------------------------------- data layer --------------------------------
def _slugify(text: str) -> str:
    s = _SKILL_SLUG_RE.sub("-", (text or "").strip().lower()).strip("-")
    return s[:60] or "skill"


def _unique_slug(conn, base: str, skill_id: Optional[int] = None) -> str:
    slug, n = base, 1
    while conn.execute(
        "SELECT id FROM skills WHERE slug=? AND id IS NOT ?", (slug, skill_id)
    ).fetchone():
        n += 1
        slug = f"{base}-{n}"
    return slug


def _json_loads_or(default, raw):
    try:
        v = json.loads(raw)
        return v if v is not None else default
    except Exception:
        return default


def _skill_steps_normalize(steps, roster_mode: bool = False) -> list[dict]:
    """Normalize a skill's steps. Normally a step needs an instruction (an empty
    stage is dropped as noise). But a FREE-WILL roster is different: a "step" there
    just means "this agent is in the room" — the instruction/role are ignored by
    the turn engine and are almost always blank. Passing roster_mode=True keeps any
    step that names a valid agent (deduped), so saving a freewill skill can't
    silently delete its participants just because they carry no instruction — the
    exact bug that wiped both seeded freewill rosters on edit."""
    out: list[dict] = []
    seen_agents: set = set()
    for s in (steps or []):
        if not isinstance(s, dict):
            continue
        instruction = str(s.get("instruction") or "").strip()
        aid = str(s.get("agent_id") or "").strip().lstrip("@").lower()
        aid = aid if aid in AGENTS_BY_ID else ""
        if roster_mode:
            if not aid or aid in seen_agents:
                continue  # a participant needs a real agent, and only once
            seen_agents.add(aid)
            out.append({"agent_id": aid, "role": "participant", "instruction": ""})
            continue
        if not instruction:
            continue
        step = {"instruction": instruction[:2000]}
        role = str(s.get("role") or "").strip()
        if role:
            step["role"] = role[:60]
        if aid:
            step["agent_id"] = aid
        out.append(step)
    return out[:12]


def _skill_inputs_normalize(inputs) -> list[dict]:
    out: list[dict] = []
    for i in (inputs or []):
        if isinstance(i, str):
            name = label = i
        elif isinstance(i, dict):
            # Fall back to the label when no explicit name is supplied so an input
            # carrying only a label is never silently dropped.
            name = i.get("name") or i.get("label") or ""
            label = i.get("label") or i.get("name") or ""
        else:
            continue
        name = str(name or "").strip()
        if not name:
            continue
        key = _slugify(name).replace("-", "_") or "input"
        label = str(label or name).strip()[:80]
        out.append({"name": key, "label": label})
    return out[:10]


def _skill_secrets_normalize(secrets) -> list[dict]:
    """Credentials a skill DECLARES it needs (the value is never stored here — it
    lives in the agent's vault, entered via the secure card). Each item:
    {key (UPPER_SNAKE_CASE), label, provider, help, agent_id?}."""
    out: list[dict] = []
    seen: set[str] = set()
    for s in (secrets or []):
        if isinstance(s, str):
            s = {"key": s}
        elif not isinstance(s, dict):
            continue
        key = str(s.get("key") or "").strip().upper()
        if not key or not SECRET_PANEL_KEY_RE.match(key) or key in seen:
            continue
        seen.add(key)
        label = str(s.get("label") or key.replace("_", " ").title()).strip()[:80]
        provider = str(s.get("provider") or "").strip().lower()[:40]
        help_txt = str(s.get("help") or "").strip()[:300]
        agent_id = str(s.get("agent_id") or "").strip()[:80]
        item = {"key": key, "label": label, "provider": provider, "help": help_txt}
        if agent_id:
            item["agent_id"] = agent_id
        out.append(item)
    return out[:8]


def _skill_apis_normalize(apis) -> list[str]:
    """Normalize the per-skill API/tool checklist to known catalog ids only."""
    out: list[str] = []
    seen: set[str] = set()
    for item in (apis or []):
        if isinstance(item, dict):
            api_id = str(item.get("id") or "").strip().lower()
        else:
            api_id = str(item or "").strip().lower()
        if not api_id or api_id not in SKILL_API_CATALOG_BY_ID or api_id in seen:
            continue
        seen.add(api_id)
        out.append(api_id)
    return out[:12]


# Which knobs each agent's card actually exposes, and the tuple each value is
# validated against. Anything not listed here can't be pinned at all.
_SKILL_PINNABLE = {
    CODEX_AGENT_ID: {"model": CODEX_MODEL_OPTIONS, "reasoning": CODEX_REASONING_OPTIONS},
    CLAUDE_AGENT_ID: {"model": CLAUDE_MODEL_OPTIONS, "reasoning": CLAUDE_REASONING_OPTIONS},
    GROK_AGENT_ID: {"model": GROK_MODEL_OPTIONS, "reasoning": GROK_REASONING_OPTIONS},
    MINIMAX_AGENT_ID: {"model": MINIMAX_MODEL_OPTIONS, "thinking": (True, False)},
    ANTIGRAVITY_AGENT_ID: {"model": ANTIGRAVITY_MODEL_OPTIONS},
    OPENROUTER_AGENT_ID: {
        "model": OPENROUTER_MODEL_OPTIONS,
        "reasoning": OPENROUTER_REASONING_OPTIONS,
    },
}


def _skill_agent_settings_normalize(raw) -> dict:
    """Validate a skill's model pins, DROPPING anything unrecognised.

    Dropping is the whole point, and it is why this can't reuse
    `_normalize_<agent>_settings`: those coerce an unknown model to the shipped
    .env default, which for a pin would mean a model retired by an upgrade
    silently downgrades a skill to the default instead of falling back to the
    room's own pick. Absent == inherit, at per-key granularity — pinning grok's
    reasoning leaves grok's model on whatever the room says."""
    raw = raw if isinstance(raw, dict) else {}
    out: dict[str, dict] = {}
    for agent_id, knobs in _SKILL_PINNABLE.items():
        entry = raw.get(agent_id)
        if not isinstance(entry, dict):
            continue
        picked: dict = {}
        for key, allowed in knobs.items():
            if key not in entry or entry[key] is None or entry[key] == "":
                continue  # explicitly "inherit this knob"
            value = entry[key]
            if key == "thinking":
                if isinstance(value, bool):
                    picked[key] = value
                elif str(value).strip().lower() in ("1", "true", "yes", "on"):
                    picked[key] = True
                elif str(value).strip().lower() in ("0", "false", "no", "off"):
                    picked[key] = False
                continue
            value = str(value).strip()
            if agent_id == OPENROUTER_AGENT_ID and key == "model":
                # Ox was a free preview. Preserve that safety property for
                # saved/scheduled skills instead of dropping its retired pin
                # and inheriting a possibly paid room model.
                value = OPENROUTER_RETIRED_MODEL_ALIASES.get(value, value)
            effective_allowed = (
                _openrouter_model_options()
                if agent_id == OPENROUTER_AGENT_ID and key == "model"
                else allowed
            )
            if value in effective_allowed:
                picked[key] = value
        if picked:
            out[agent_id] = picked
    return out


def _skill_pin_summary(skill: dict) -> str:
    """One human line naming the pins, e.g. 'Codex gpt-5.6-sol · xhigh, Claude
    claude-haiku-4-5'. Empty when the skill pins nothing."""
    pins = _skill_agent_settings_normalize(skill.get("agent_settings"))
    parts = []
    for agent_id, knobs in pins.items():
        name = (AGENTS_BY_ID.get(agent_id) or {}).get("name", agent_id)
        bits = [str(knobs[k]) for k in ("model", "reasoning") if k in knobs]
        if "thinking" in knobs:
            bits.append("thinking on" if knobs["thinking"] else "thinking off")
        if "tools" in knobs:
            bits.append(f"{knobs['tools']} tools")
        parts.append(f"{name} {' · '.join(bits)}".strip())
    return ", ".join(parts)


def _skill_effective_model_pins(
    skill: dict,
    cid: int,
    order: list[str],
    mode: str,
    inputs: dict,
    *,
    attachment_count: int = 0,
) -> tuple[dict[str, dict], Optional[str], bool]:
    """Resolve unattended model settings without letting skills bypass Auto.

    Auto is an owner preference, so it follows skills and schedules across
    browsers. When Auto is on, its selected model/strength is authoritative:
    old skill pins are retained as manual fallbacks but do not silently force
    an expensive model.
    """
    explicit = _skill_agent_settings_normalize(skill.get("agent_settings"))
    owner_id = _chat_owner_id(cid) or skill.get("owner_user_id") or _default_admin_id()
    auto_enabled = _auto_reasoning_preference(int(owner_id))
    base: dict[str, dict] = {}
    tier: Optional[str] = None
    if auto_enabled:
        base, tier = _automatic_model_pins(
            _skill_run_intent(skill, inputs),
            order,
            mode,
            attachment_count=attachment_count,
        )
    if not auto_enabled:
        for agent_id, knobs in explicit.items():
            base[agent_id] = {**base.get(agent_id, {}), **knobs}
    return base, tier, auto_enabled


def _skill_from_row(row) -> dict:
    return {
        "id": row["id"], "slug": row["slug"], "name": row["name"], "kind": row["kind"],
        "description": row["description"], "body": row["body"], "mode": row["mode"],
        "steps": _json_loads_or([], row["steps_json"]),
        "inputs": _json_loads_or([], row["inputs_json"]),
        "secrets": (_json_loads_or([], row["secrets_json"]) if "secrets_json" in row.keys() else []),
        "apis": _skill_apis_normalize(
            _json_loads_or([], row["apis_json"]) if "apis_json" in row.keys() else []
        ),
        "agent_settings": _skill_agent_settings_normalize(
            _json_loads_or({}, row["agent_settings_json"])
            if "agent_settings_json" in row.keys() else {}
        ),
        "tags": _json_loads_or([], row["tags_json"]),
        "pack": (row["pack"] if "pack" in row.keys() else ""),
        "category": (row["category"] if "category" in row.keys() else ""),
        "status": row["status"], "source_chat_id": row["source_chat_id"], "author": row["author"],
        "use_count": row["use_count"], "last_used_ts": row["last_used_ts"],
        "created_ts": row["created_ts"], "updated_ts": row["updated_ts"],
        "owner_user_id": row["owner_user_id"],
    }


def _get_skill(id_or_slug, owner_user_id: Optional[int] = None) -> Optional[dict]:
    with _db() as conn:
        if isinstance(id_or_slug, int) or str(id_or_slug).isdigit():
            row = conn.execute("SELECT * FROM skills WHERE id=?", (int(id_or_slug),)).fetchone()
        else:
            row = conn.execute("SELECT * FROM skills WHERE slug=?", (str(id_or_slug),)).fetchone()
    if not row:
        return None
    skill = _skill_from_row(row)
    if owner_user_id is not None and skill["owner_user_id"] and skill["owner_user_id"] != owner_user_id:
        return None
    return skill


def _list_skills(status: Optional[str] = None, owner_user_id: Optional[int] = None,
                 q: Optional[str] = None, pack: Optional[str] = None,
                 category: Optional[str] = None) -> list[dict]:
    clauses, params = [], []
    if status:
        clauses.append("status=?"); params.append(status)
    if pack is not None:
        clauses.append("lower(pack)=?"); params.append(str(pack).strip().lower())
    if category is not None:
        clauses.append("lower(category)=?"); params.append(str(category).strip().lower())
    if owner_user_id is not None:
        clauses.append("(owner_user_id IS NULL OR owner_user_id=?)"); params.append(owner_user_id)
    where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
    with _db() as conn:
        rows = conn.execute(
            f"SELECT * FROM skills{where} ORDER BY updated_ts DESC LIMIT 500", params
        ).fetchall()
    skills = [_skill_from_row(r) for r in rows]
    if q:
        ql = q.lower()
        skills = [
            s for s in skills
            if ql in (s["name"] + " " + s["description"] + " " + " ".join(s["tags"])).lower()
        ]
    return skills


def _save_skill(data: dict, owner_user_id: Optional[int] = None) -> dict:
    now = int(time.time() * 1000)
    name = str(data.get("name") or "Untitled skill").strip()[:120]
    kind = data.get("kind") if data.get("kind") in SKILL_KINDS else "workflow"
    status = data.get("status") if data.get("status") in SKILL_STATUSES else "draft"
    mode = _normalize_chat_mode(data.get("mode") or "pipeline")
    inputs = json.dumps(_skill_inputs_normalize(data.get("inputs")))
    secrets = json.dumps(_skill_secrets_normalize(data.get("secrets")))
    apis = json.dumps(_skill_apis_normalize(data.get("apis")))
    agent_settings = json.dumps(_skill_agent_settings_normalize(data.get("agent_settings")))
    tags = json.dumps([str(t).strip()[:40] for t in (data.get("tags") or []) if str(t).strip()][:12])
    description = str(data.get("description") or "").strip()[:400]
    body = str(data.get("body") or "")[:20000]
    pack = str(data.get("pack") or "").strip()[:40]
    category = str(data.get("category") or "").strip()[:40]
    sid = data.get("id")
    with _db() as conn:
        existing_row = conn.execute(
            "SELECT id, mode FROM skills WHERE id=?", (int(sid),)
        ).fetchone() if sid else None
        if sid and not existing_row:
            sid = None
        # A FREE-WILL skill's mode is sticky: the skill editor UI only knows the
        # user-selectable modes (freewill is deliberately excluded), so opening +
        # saving one would otherwise read back a blank/"pipeline" mode and silently
        # downgrade it — turning a green-room session into a pipeline run. Never let
        # a normal save change an existing freewill skill's mode away from freewill.
        if existing_row and existing_row["mode"] == "freewill":
            mode = "freewill"
        # Normalize steps AFTER the effective mode is known: a freewill roster keeps
        # its instruction-less participants (roster_mode), every other mode drops
        # empty stages as before.
        steps = json.dumps(_skill_steps_normalize(
            data.get("steps"), roster_mode=(mode == "freewill")
        ))
        if sid:
            slug = _unique_slug(conn, _slugify(data.get("slug") or name), int(sid))
            conn.execute(
                "UPDATE skills SET slug=?, name=?, kind=?, description=?, body=?, mode=?, "
                "steps_json=?, inputs_json=?, secrets_json=?, apis_json=?, agent_settings_json=?, "
                "tags_json=?, status=?, pack=?, category=?, updated_ts=? WHERE id=?",
                (slug, name, kind, description, body, mode, steps, inputs, secrets, apis,
                 agent_settings, tags, status, pack, category, now, int(sid)),
            )
            new_id = int(sid)
        else:
            slug = _unique_slug(conn, _slugify(data.get("slug") or name))
            cur = conn.execute(
                "INSERT INTO skills(slug, name, kind, description, body, mode, steps_json, inputs_json, "
                "secrets_json, apis_json, agent_settings_json, tags_json, status, pack, category, "
                "source_chat_id, author, created_ts, updated_ts, owner_user_id) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (slug, name, kind, description, body, mode, steps, inputs, secrets, apis,
                 agent_settings, tags, status, pack, category,
                 data.get("source_chat_id"), str(data.get("author") or "")[:80], now, now, owner_user_id),
            )
            new_id = int(cur.lastrowid)
        row = conn.execute("SELECT * FROM skills WHERE id=?", (new_id,)).fetchone()
    return _skill_from_row(row)


def _delete_skill(sid: int, owner_user_id: Optional[int] = None) -> bool:
    with _db() as conn:
        if owner_user_id is not None:
            cur = conn.execute(
                "DELETE FROM skills WHERE id=? AND (owner_user_id IS NULL OR owner_user_id=?)",
                (int(sid), owner_user_id),
            )
        else:
            cur = conn.execute("DELETE FROM skills WHERE id=?", (int(sid),))
        return cur.rowcount > 0


def _bump_skill_usage(sid: int) -> None:
    try:
        with _db() as conn:
            conn.execute(
                "UPDATE skills SET use_count=use_count+1, last_used_ts=? WHERE id=?",
                (int(time.time() * 1000), int(sid)),
            )
    except Exception:
        logger.exception("skill usage bump failed")


def _fts_query(text: str, limit: int = 12) -> str:
    words = [w for w in _FTS_WORD_RE.findall((text or "").lower()) if len(w) > 2]
    words = list(dict.fromkeys(words))[:limit]
    return " OR ".join(f'"{w}"' for w in words)


def _relevant_skills(goal: str, k: int = 3, owner_user_id: Optional[int] = None) -> list[dict]:
    """Top-k active skills whose name/description/tags best match the goal text."""
    q = _fts_query(goal)
    if not q:
        return []
    sql = (
        "SELECT s.* FROM skills_fts f JOIN skills s ON s.id=f.rowid "
        "WHERE skills_fts MATCH ? AND s.status='active'"
    )
    params: list = [q]
    if owner_user_id is not None:
        sql += " AND (s.owner_user_id IS NULL OR s.owner_user_id=?)"
        params.append(owner_user_id)
    sql += " ORDER BY rank LIMIT ?"
    params.append(int(k))
    try:
        with _db() as conn:
            rows = conn.execute(sql, params).fetchall()
        return [_skill_from_row(r) for r in rows]
    except Exception:
        logger.exception("skill FTS search failed")
        return []


# ------------------------------- distiller ---------------------------------
def _chat_transcript_for_skill(cid: int, limit: int = 80) -> str:
    lines = []
    for e in _load_thread(cid)[-limit:]:
        if e.get("role") == "system":
            continue
        txt = (e.get("text") or "").strip()
        if txt:
            lines.append(f"{e.get('name') or e.get('role') or '?'}: {txt}")
    return "\n\n".join(lines)


def _build_skill_distill_prompt(transcript: str, intent_name: str = "") -> str:
    # The user's chosen skill name is their INTENT. A chat is often mostly
    # exploration / debugging / setup, so distilling the transcript blind tends to
    # capture "what was discussed" (e.g. how we wired a tool) instead of the runnable
    # process the user actually wants to repeat. Aiming the distiller at the name
    # keeps the output a thing the team can RUN, with stages.
    intent = (
        f'The user is SAVING this chat as a reusable skill they named "{intent_name}". '
        "Treat that name as their INTENT: distill the transcript into a skill that DELIVERS "
        "exactly that, even if the chat spent most of its length exploring, debugging, or "
        "setting things up. Capture the runnable PROCESS the name implies — not a write-up of "
        "whatever happened to dominate the discussion.\n\n"
        if intent_name else ""
    )
    return (
        "You convert a finished multi-agent chat transcript into ONE reusable SKILL "
        "definition — a recipe the team can run again on a new input. Distill the "
        "REPEATABLE method, not the one-off specifics.\n\n"
        + intent +
        "Pick the kind:\n"
        "- \"workflow\" (DEFAULT — strongly prefer this): the skill is something the team will "
        "RUN again — a task, process, or automation. Capture it as ordered STAGES (at least 2), "
        "each with the role that does it, an optional pinned agent_id, and that stage's concrete "
        "instruction — plus the chat mode that fits: pipeline (each stage builds on the prior), "
        "delegate (parallel independent tasks), collaborate, debate, or poll. Even when the chat "
        "was mostly setup/wiring or open-ended discussion, express the thing it ENABLES as "
        "runnable stages, and fold any setup notes or gotchas into the relevant stage instruction "
        "or into 'body'.\n"
        "- \"playbook\" (RARE — only when there is genuinely NO runnable sequence): pure reference "
        "knowledge or a judgement method with no ordered steps to execute. Capture it as a markdown "
        "'body'. If you can name even a few ordered actions, choose workflow instead.\n\n"
        "Rules: 'description' is ONE line naming WHEN to reach for this skill (it is the "
        "trigger used to find it later). Use {placeholders} in step instructions for the "
        "parts that change each run and list them in 'inputs'. Keep instructions concrete and "
        "self-contained. Never invent secrets or copy literal API keys. If the repeatable "
        "process clearly expects app/tool access, include 'apis' using only these ids: "
        f"{', '.join(SKILL_API_CATALOG_BY_ID.keys())}.\n\n"
        f"TRANSCRIPT:\n{transcript[:24000]}\n\n"
        "Reply with ONLY a JSON object, no prose, no code fence:\n"
        '{"name": "...", "description": "one line: when to use this", '
        '"kind": "workflow|playbook", "mode": "pipeline|delegate|collaborate|debate|poll|counsel", '
        '"steps": [{"role": "editor", "agent_id": "optional bare id", "instruction": "..."}], '
        '"inputs": [{"name": "source_draft", "label": "..."}], "tags": ["..."], '
        '"apis": ["memory_search"], "body": "markdown for playbook kind, else empty"}'
    )


def _parse_skill_reply(raw: str) -> Optional[dict]:
    if not raw:
        return None
    text = raw.strip()
    if text.startswith("```"):
        text = text.strip("`")
        nl = text.find("\n")
        if nl != -1 and text[:nl].strip().lower() in ("json", ""):
            text = text[nl + 1:]
    start, end = text.find("{"), text.rfind("}")
    if start == -1 or end <= start:
        return None
    try:
        data = json.loads(text[start:end + 1])
    except json.JSONDecodeError:
        return None
    return data if isinstance(data, dict) else None


def _recent_runs_for_skill(skill_id: int, limit: int = 5) -> list[dict]:
    """Most-recent automation_runs across this skill's schedules (newest first),
    trimmed to what the orchestrator needs to diagnose a misbehaving run. Feeds the
    'fix this skill' flow so the orchestrator reasons from real failures, not guesses."""
    try:
        with _db() as conn:
            rows = conn.execute(
                "SELECT r.status, r.error, r.summary, r.started_ts "
                "FROM automation_runs r JOIN skill_schedules s ON s.id = r.schedule_id "
                "WHERE s.skill_id=? ORDER BY r.started_ts DESC, r.id DESC LIMIT ?",
                (int(skill_id), int(limit)),
            ).fetchall()
    except Exception:
        return []
    return [{
        "status": r["status"],
        "error": (r["error"] or "")[:500],
        "summary": (r["summary"] or "")[:500],
        "started_ts": r["started_ts"],
    } for r in rows]


def _build_skill_compose_prompt(history: list[dict], roster: str,
                                skill: Optional[dict] = None,
                                runs: Optional[list] = None) -> str:
    """Conversational builder prompt: the orchestrator either asks the user a few
    follow-ups or returns a finished skill (+ optional schedule). Stateless — the
    whole running transcript is replayed each turn."""
    convo_lines = []
    for m in history[-20:]:
        who = "User" if m.get("role") == "user" else "Skill Builder"
        txt = str(m.get("content") or "").strip()
        if txt:
            convo_lines.append(f"{who}: {txt}")
    convo = "\n\n".join(convo_lines) or "User: (no message yet)"
    edit_block = ""
    if skill:
        cur = {
            "id": skill.get("id"),
            "name": skill.get("name"),
            "description": skill.get("description"),
            "kind": skill.get("kind"),
            "mode": skill.get("mode"),
            "steps": skill.get("steps"),
            "inputs": skill.get("inputs"),
            "secrets": skill.get("secrets"),
            "apis": skill.get("apis"),
            "tags": skill.get("tags"),
            "body": skill.get("body"),
        }
        run_lines = []
        for r in (runs or [])[:5]:
            run_lines.append(
                f"- [{r.get('status') or '?'}]"
                + (f" error: {r.get('error')}" if r.get("error") else "")
                + (f" — {r.get('summary')}" if r.get("summary") else "")
            )
        edit_block = (
            "YOU ARE EDITING AN EXISTING SKILL. Return the COMPLETE revised skill with "
            'action "update" — keep every step/input/secret you are not deliberately '
            "changing, and preserve its id. Make the smallest change that satisfies the "
            "user's ask. CURRENT SKILL:\n"
            + json.dumps(cur, ensure_ascii=False)
            + (("\n\nRECENT RUNS (most recent first — use real failures to decide what to "
                "change):\n" + "\n".join(run_lines)) if run_lines else "")
            + "\n\n"
        )
    return (
        f"{edit_block}"
        "You are the SKILL BUILDER for a multi-agent chat app. The user describes, in "
        "plain language, a SKILL or AUTOMATION they want, and you turn it into a reusable "
        "recipe the orchestrator can run again. Do NOT do the task itself — design the recipe.\n\n"
        "A SKILL is one of:\n"
        "- \"workflow\": ordered agent STAGES run in a chat MODE — each stage has a role, an "
        "optional pinned agent, and an instruction.\n"
        "- \"playbook\": a markdown METHOD (steps, gotchas, what good looks like) when there is "
        "no fixed agent sequence.\n"
        "An AUTOMATION is just a skill plus a SCHEDULE or event trigger so it runs on its own.\n\n"
        f"AGENTS AVAILABLE (only pin agent_ids from this list; they are online now):\n{roster}\n\n"
        f"MODES AVAILABLE:\n{_concierge_mode_catalog()}\n\n"
        "API/TOOL CHECKBOXES AVAILABLE:\n"
        + "\n".join(
            f"- {a['id']}: {a['label']} - {a['description']}"
            for a in SKILL_API_CATALOG
        )
        + "\n\n"
        "HOW TO WORK:\n"
        "- If the request is vague or missing key details, ASK a few focused questions first "
        "(at most 3 per turn). Good things to pin down: the concrete output/deliverable; the "
        "steps and which agent or role does each; what changes from run to run (turn those into "
        "{inputs}); and, if it should run on its own, the schedule (time of day / which days / "
        "interval) or the event that triggers it.\n"
        "- Don't over-ask. The moment you have enough — or the user says to just build it — "
        "produce the skill. If the user asks to change a skill you already proposed, return the "
        "full updated skill.\n"
        "- Keep messages friendly, concise, and free of markdown headers.\n\n"
        "Use {placeholders} in instructions for the parts that change each run and list them in "
        "'inputs'. Keep instructions concrete and self-contained. Only pin agent_ids that appear "
        "in the roster above. If the recipe should rely on one of the API/tool checkboxes above, "
        "include its id in 'apis'. These are reminders/permissions, not secret values.\n\n"
        "CREDENTIALS: if the skill touches Gmail, Google (Calendar/Drive/Sheets), IMAP/SMTP email, "
        "or any external service needing an API key or password, DECLARE what it needs in 'secrets' "
        "— never invent a value or ask the user to paste one into the chat. Each secret needs: a "
        "canonical UPPER_SNAKE_CASE 'key' (use GMAIL_ADDRESS + GMAIL_APP_PASSWORD for Gmail/IMAP; "
        "otherwise PROVIDER_API_KEY), a short 'label', a 'provider' (google|openai|…), one line of "
        "'help' on how to obtain it (Gmail: 'Google Account → Security → 2-Step Verification → App "
        "passwords; spaces are fine'), and the 'agent_id' of the step that uses it. The app then "
        "shows the user a secure field — the value goes straight into that agent's private vault, "
        "never to you. When a step runs code that reads email credentials, have it "
        "`from email_creds import get_creds` and stay standard-library only — never `from dotenv "
        "import ...`, since scheduled scripts run under a bare python that lacks third-party libs.\n\n"
        "EMAIL AUTOMATION SAFETY: an automation may read, classify, flag, and draft email replies. "
        "Do not design a scheduled/unattended skill that sends or replies to email as its normal "
        "completion path. If the user asks for auto-replies, design the default version as a "
        "draft-and-approval queue; true auto-send requires a dedicated allowlist/rule set and an "
        "explicit send gate outside ordinary skill instructions.\n\n"
        "CONVERSATION SO FAR (the LAST user turn is the newest ask — build on the whole "
        f"thread):\n{convo}\n\n"
        "Reply with ONLY a JSON object — no prose, no code fence — in ONE of these shapes:\n"
        'ASK:    {"action": "ask", "message": "<your reply plus any questions, plain conversational text>"}\n'
        'UPDATE (only when a CURRENT SKILL block is present above): same shape as CREATE but '
        '"action": "update" and include the existing "id" inside "skill".\n'
        'CREATE: {"action": "create", "message": "<one short line: what you built and how to run it>", '
        '"skill": {"name": "...", "description": "one line: when to use this", '
        '"kind": "workflow|playbook", "mode": "pipeline|delegate|collaborate|debate|poll|counsel|solo", '
        '"steps": [{"role": "researcher", "agent_id": "optional bare id from roster", "instruction": "..."}], '
        '"inputs": [{"name": "topic", "label": "Topic"}], '
        '"secrets": [{"key": "GMAIL_APP_PASSWORD", "label": "Gmail app password", "provider": "google", '
        '"help": "Google Account → Security → App passwords", "agent_id": "bare id from roster"}], '
        '"apis": ["web_search", "memory_search"], '
        '"tags": ["..."], '
        '"body": "markdown for playbook kind, else empty", "pack": "optional domain", "category": "optional"}, '
        '"schedule": {"trigger_type": "daily|weekly|interval|event|none", '
        '"spec": {"hh": 9, "mm": 0, "weekday": 1, "seconds": 3600, "event": "attachment_added"}}}\n'
        "In 'spec' include ONLY the keys the chosen trigger_type needs (daily: hh,mm; weekly: "
        "weekday[0=Sun],hh,mm; interval: seconds; event: event). Interval and daily may ALSO take "
        "optional constraints: \"days\":[1,2,3,4,5] (0=Sun..6=Sat; e.g. Mon-Fri), a \"tz\" "
        "(e.g. \"America/Chicago\"), and interval may take \"win\":{\"start\":8,\"end\":18} to "
        "only fire within an hour band (end exclusive, 24h). Omit 'schedule' or use "
        "trigger_type \"none\" for a skill the user will run by hand."
    )


def _coerce_int(v, default: int) -> int:
    try:
        return int(float(v))
    except (TypeError, ValueError):
        return default


def _normalize_proposed_schedule(sched) -> Optional[dict]:
    """Validate a schedule the orchestrator proposed into the same shape the
    /schedules endpoint expects, or None for a run-by-hand skill."""
    if not isinstance(sched, dict):
        return None
    tt = str(sched.get("trigger_type") or "").strip().lower()
    if tt not in ("interval", "daily", "weekly", "event"):
        return None  # "none" / "manual" -> not an automation
    return {"trigger_type": tt, "spec": _sanitize_sched_spec(tt, sched.get("spec"))}


# ------------------------- role staffing + apply ---------------------------
def _agent_match_blob(aid: str) -> str:
    a = AGENTS_BY_ID.get(aid, {})
    parts = [aid, a.get("name", ""), a.get("tagline", "")]
    card = (_CAP_CACHE.get(aid) or {}).get("card") or {}
    parts.append(card.get("best_for") or "")
    parts.extend(card.get("strengths") or [])
    override = _get_agent_card_override(aid)
    if override:
        parts.append(override.get("best_for") or "")
        parts.extend(override.get("strengths") or [])
    parts.append(AGENT_LANES.get(aid, ""))
    return " ".join(str(p) for p in parts).lower()


def _resolve_step_agent(step: dict, candidates: list[str], used: set) -> Optional[str]:
    """Pin wins; else keyword-match the role/instruction against agent capability
    cards (preferring online + not-yet-used agents); else first free candidate."""
    pinned = step.get("agent_id")
    if pinned in AGENTS_BY_ID and pinned in candidates:
        return pinned
    # Unpinned stages should spread across the available room before reusing a
    # seat.  Scoring the whole candidate list let a cached ``online`` bonus beat
    # the smaller unused-seat bonus, so suite order (or a recent health poll in
    # production) could silently collapse distinct stages onto one agent.
    available = [aid for aid in candidates if aid not in used]
    pool = available or candidates
    terms = [
        w for w in _FTS_WORD_RE.findall(
            (str(step.get("role") or "") + " " + str(step.get("instruction") or "")).lower()
        )
        if len(w) > 2 and w not in _ROLE_STOPWORDS
    ]
    best, best_score = None, 0.0
    for aid in pool:
        blob = _agent_match_blob(aid)
        score = float(sum(1 for t in terms if t in blob))
        if (_CAP_CACHE.get(aid) or {}).get("online"):
            score += 1.0
        if aid not in used:
            score += 0.5
        if score > best_score:
            best, best_score = aid, score
    if best is not None and best_score > 0:
        return best
    if available:
        return available[0]
    return candidates[0] if candidates else None


def _substitute_inputs(text: str, inputs: dict) -> str:
    return re.sub(
        r"\{([a-zA-Z0-9_]+)\}",
        lambda m: str(inputs.get(m.group(1), m.group(0))),
        text or "",
    )


def _resolve_skill_room(skill: dict, candidates: list[str], inputs: dict) -> tuple[list[str], dict]:
    order: list[str] = []
    assignments: dict[str, str] = {}
    used: set = set()
    for step in (skill.get("steps") or []):
        aid = _resolve_step_agent(step, candidates, used)
        if not aid:
            continue
        instr = _substitute_inputs(step.get("instruction") or "", inputs).strip()
        if aid in assignments:
            if instr:
                assignments[aid] = (assignments[aid] + "\n\nThen: " + instr).strip()
        else:
            order.append(aid)
            assignments[aid] = instr
            used.add(aid)
    return order, assignments


def _skill_run_intent(skill: dict, inputs: dict) -> str:
    lines = [f"[Skill: {skill['name']}]"]
    if skill.get("description"):
        lines.append(_substitute_inputs(skill["description"], inputs))
    for k, v in (inputs or {}).items():
        v = str(v).strip()
        if v:
            lines.append(f"{k}: {v}")
    return "\n".join(lines).strip() or skill["name"]


def _skill_chat_handoff_meta(cid: int) -> dict:
    """Small authoritative chat payload returned only to an authorized launcher."""
    chat = (CHAT_INDEX.get("chats", {}).get(str(cid)) or {})
    return {
        "id": cid,
        "title": chat.get("title") or f"#{cid}",
        "mode": chat.get("mode") or _get_chat_mode(cid),
        "targets": list(chat.get("targets") or []),
        "skill_id": chat.get("skill_id"),
        "skill_name": chat.get("skill_name") or "",
    }


def _skill_missing_inputs(skill: dict, inputs: dict) -> list[dict]:
    """Declared inputs that have no value supplied for this run."""
    inputs = inputs or {}
    missing: list[dict] = []
    for inp in (skill.get("inputs") or []):
        if inp.get("required") is False:
            continue
        name = (inp.get("name") or "").strip()
        if not name:
            continue
        val = inputs.get(name)
        if val is None or str(val).strip() == "":
            missing.append(inp)
    return missing


def _skill_runtime_inputs(skill: dict, cid: int, inputs: dict) -> tuple[dict, str]:
    """Freeze one run identity for retry-safe research-monitor execution."""
    runtime = dict(inputs or {})
    slug = str(skill.get("slug") or "").strip()
    if slug not in MANIFEST_SCOPED_SKILL_SLUGS:
        return runtime, ""
    now = datetime.now().astimezone()
    base_id = now.strftime("%Y%m%d-%H%M")
    reports_root = Path(_chat_workspace(cid)) / "reports" / slug
    reports_root.mkdir(parents=True, exist_ok=True)
    run_id = base_id
    suffix = 2
    while True:
        run_dir = reports_root / run_id
        try:
            run_dir.mkdir()
            break
        except FileExistsError:
            run_id = f"{base_id}-{suffix:02d}"
            suffix += 1
    runtime.update({
        "run_id": run_id,
        "run_dir": str(run_dir),
        "run_timestamp": now.isoformat(timespec="seconds"),
    })
    note = (
        "RUN IDENTITY (authoritative for this invocation):\n"
        f"- run_id: {run_id}\n"
        f"- run_timestamp: {runtime['run_timestamp']}\n"
        f"- RUN_DIR: {run_dir}\n"
        "Create and modify deliverables only inside RUN_DIR. Reuse this exact "
        "directory after any retry or correction; never start a second run "
        "directory and never create duplicate top-level report copies."
    )
    return runtime, note


async def _post_input_request_card(cid: int, skill: dict, order: list[str],
                                   missing: list[dict]) -> None:
    """Post the interactive "this skill needs a few details" card and pause. The
    card carries the fields to fill; submitting it (frontend) re-calls the apply
    route with the values, which runs the skill for real. Attributed to the lead
    agent so it reads as that agent asking for what it needs to start."""
    lead_id = order[0] if order else None
    agent = AGENTS_BY_ID.get(lead_id) or {}
    agent_name = agent.get("name") or "The skill"
    fields = [{"name": m["name"], "label": (m.get("label") or m["name"])} for m in missing]
    labels = ", ".join(f["label"] for f in fields)
    meta = {
        "kind": "input_request",
        "skill_id": skill["id"],
        "skill_name": skill["name"],
        "agent_id": lead_id,
        "agent_name": agent_name,
        "fields": fields,
        "submitted": False,
    }
    text = f"To run “{skill['name']}”, I need a few details from you: {labels}."
    entry = append_thread(cid, "system", lead_id, agent_name, text, metadata=meta)
    PENDING_INPUT_CARDS.add(cid)
    await broadcast({"type": "input_request", "chat_id": cid, "ts": entry["ts"], **meta})
    await _emit_notification(
        cid, event="attention",
        title=f"“{skill['name']}” needs a few details",
        body=f"Fill in {labels} to start.",
        severity="info", agent_id=lead_id, push=False,
    )


async def _resolve_input_card(cid: int) -> None:
    """Flip the chat's pending input-request card to submitted (durably, so a reload
    shows it settled) and tell clients to drop its form."""
    PENDING_INPUT_CARDS.discard(cid)
    for msg in reversed(_load_thread(cid)):
        md = msg.get("metadata") or {}
        if md.get("kind") == "input_request" and not md.get("submitted"):
            _update_message_metadata(cid, msg.get("ts"), {"submitted": True})
            await broadcast({"type": "input_resolved", "chat_id": cid, "ts": msg.get("ts")})
            break


# ---------------------------- Skill safety scan ----------------------------
# Skills are DATA — applying one only sets the room and feeds its instructions
# through the normal turn path. But several agents (@claude/@codex/@hermes) DO
# have shells/tools in their workspace, so a skill's *instructions* are a
# prompt-injection surface: a borrowed or imported skill could tell an agent to
# exfiltrate secrets, run destructive shell, or override its own guardrails.
# This is a deterministic lint (no LLM) over the skill's text so the UI can
# preview risk before Apply and the orchestrator can warn on auto-apply. It
# never blocks — it surfaces, because the owner may legitimately want some of
# these (e.g. a deploy skill that runs shell).
_SKILL_SCAN_RULES: tuple[tuple[re.Pattern, str, str, str], ...] = (
    (re.compile(r"ignore\s+(?:all\s+)?(?:previous|prior|above)\s+instructions", re.I),
     "high", "prompt-injection", "tells the agent to ignore its prior instructions"),
    (re.compile(r"\b(?:disregard|override|bypass)\b[^.\n]{0,40}\b(?:instructions?|guardrails?|safety|system\s*prompt|rules?)\b", re.I),
     "high", "prompt-injection", "tries to override the agent's guardrails or system prompt"),
    (re.compile(r"(?:reveal|print|show|leak|exfiltrat\w*)\b[^\n]{0,40}\b(?:system\s*prompt|secret|api[_-]?key|password|token|credential)", re.I),
     "high", "secret-exfiltration", "asks the agent to reveal or exfiltrate secrets/credentials"),
    (re.compile(r"(?:send|post|upload|curl|wget|fetch|exfiltrat\w*)\b[^\n]{0,60}(?:\b(?:secret|api[_-]?key|password|token|credential)|\.env\b)", re.I),
     "high", "secret-exfiltration", "moves secrets/credentials off the machine"),
    (re.compile(r"\brm\s+-rf\b|\bmkfs\b|\bdd\s+if=|:\(\)\s*\{|>\s*/dev/sd|\bdrop\s+table\b|\bdelete\s+from\b", re.I),
     "high", "destructive", "contains a destructive shell/SQL command"),
    (re.compile(r"\bcurl\b[^\n|]*\|\s*(?:sudo\s+)?(?:ba)?sh\b|\bwget\b[^\n|]*\|\s*(?:ba)?sh\b", re.I),
     "high", "remote-exec", "pipes a downloaded script straight into a shell"),
    # The skill builder can emit unattended traders / money-movers. These were a
    # blind spot: "write & execute a Python script to trade" tripped nothing.
    (re.compile(r"\b(?:place|execute|executes|submit|open|close|enter|exit)\b[^.\n]{0,40}\b(?:order|orders|trade|trades|position|positions)\b|\b(?:buy|sell|long|short)\b[^.\n]{0,30}\b(?:btc|eth|sol|crypto|coins?|altcoins?|shares?|stocks?|forex)\b|\b(?:kraken|binance|coinbase|alpaca|oanda|robinhood|ccxt|metatrader|interactive\s*brokers)\b|\btrading\s+bot\b|\bwithdraw\w*\b[^.\n]{0,30}\b(?:funds?|money|crypto|balance|wallet)\b", re.I),
     "high", "financial", "places trades or moves money/crypto"),
    # Outbound communication is a real-world side effect. Drafting is fine, but
    # unattended email/message sends and auto-replies must be gated.
    (re.compile(r"\b(?:auto[-\s]?reply|auto[-\s]?respond|automatic(?:ally)?\s+(?:reply|respond|send)|confirm_send\s*[:=]\s*true|action\s*[:=]\s*['\"]send['\"]|(?:send|deliver)\s+(?:the\s+)?(?:email|reply|message)|(?:reply|respond)\s+to\s+(?:the\s+)?(?:email|message|sender|customer|client|lead))\b", re.I),
     "high", "external-send", "sends or replies to email/messages"),
    (re.compile(r"\b(?:write|writes|generate|generates|create|creates)\b[^.\n]{0,40}\b(?:and\s+(?:then\s+)?)?(?:execute|executes|run|runs)\b[^.\n]{0,20}\b(?:python|script|code|program)\b|\bexec\s*\(|\beval\s*\(|\bos\.system\b|\bsubprocess\b|\b(?:python3?|bash|sh)\s+-c\b", re.I),
     "high", "code-exec", "writes and runs code generated at runtime"),
    # NB: §§secret(KEY) is the SANCTIONED secret mechanism — not flagged. We flag
    # raw env reads and privilege escalation, which prose skills rarely need.
    (re.compile(r"\bos\.environ\b|\bsudo\b|\bchmod\s+777\b|\bcat\s+[^\n]*\.env\b", re.I),
     "medium", "sensitive-access", "reads raw environment/.env or escalates permissions"),
    (re.compile(r"\b(?:without|don'?t)\s+(?:telling|informing|asking)\s+(?:the\s+)?user\b", re.I),
     "medium", "stealth", "instructs the agent to act without telling the user"),
    (re.compile(r"https?://(?!localhost|127\.0\.0\.1)[^\s)]+", re.I),
     "low", "external-url", "references an external URL"),
)
_SKILL_SCAN_RANK = {"none": 0, "low": 1, "medium": 2, "high": 3}


def _skill_scan_text(skill: dict) -> str:
    parts = [skill.get("name") or "", skill.get("description") or "", skill.get("body") or ""]
    for st in (skill.get("steps") or []):
        if isinstance(st, dict):
            parts.append(str(st.get("instruction") or ""))
    parts.extend(str(t) for t in (skill.get("tags") or []))
    return "\n".join(parts)


def _scan_text(text: str) -> dict:
    """Run the deterministic injection/risk lint over arbitrary text. Returns
    {risk, tier, findings:[{severity,category,detail,match}]}; `risk` is the
    highest severity found (or 'none'). Used for skill scanning and unattended
    automation gating. Do not surface these findings as chat banners — the
    phrases overlap ordinary user/email wording ("reply to the email")."""
    findings: list[dict] = []
    seen: set[tuple[str, str]] = set()
    for pat, severity, category, detail in _SKILL_SCAN_RULES:
        m = pat.search(text or "")
        if not m:
            continue
        key = (category, severity)
        if key in seen:
            continue
        seen.add(key)
        findings.append({
            "severity": severity, "category": category, "detail": detail,
            "match": _clip_line(m.group(0), 80),
        })
    findings.sort(key=lambda f: -_SKILL_SCAN_RANK.get(f["severity"], 0))
    risk = findings[0]["severity"] if findings else "none"
    # Autonomy tier — what the control plane should do with this unattended:
    #   gated  = irreversible/material (trade, exec, destruct, secret move) → policy+caps or hold
    #   notify = sensitive but reversible → run + ping
    #   auto   = read-only/benign → run free, just log
    tier = {"high": "gated", "medium": "notify"}.get(risk, "auto")
    return {"risk": risk, "tier": tier, "findings": findings}


def _scan_skill(skill: dict) -> dict:
    """Deterministic risk lint over a skill's stored definition text."""
    return _scan_text(_skill_scan_text(skill))


async def apply_skill(skill: dict, cid: int, inputs: Optional[dict] = None,
                      actor: str = GENERIC_PRINCIPAL,
                      notify_event: Optional[str] = None, push: bool = False,
                      interactive: bool = False,
                      attachments: Optional[list] = None) -> dict:
    """Stage a chat with the skill's room + per-stage instructions, then kick off
    the turn in the background (so callers return immediately). Reused by the
    apply route, the scheduler, and event triggers.

    `notify_event` (e.g. "automation_done") raises a completion alert when the run
    finishes; `push` also fires an OS-level web-push (used for unattended runs).

    `interactive=True` (a manual "Run now") means the user is present: instead of
    requiring inputs up front, if the skill declares inputs the user hasn't supplied
    we post an interactive "inputs" card and STOP — the run begins only when the card
    is submitted (which re-calls this with interactive=False and the values filled).
    Unattended runs (the scheduler) leave this False and just use their stored inputs."""
    if not _chat_row_is_live(cid) or _track_current_chat_task(cid) is None:
        return {"ok": False, "error": "chat_unavailable"}
    inputs = inputs or {}
    attachments = attachments or []
    # On a manual run the user fills nothing in first — so any declared input left
    # blank is collected up front with an interactive "inputs" card (posted below),
    # and the skill doesn't actually run until they submit it. Unattended runs (the
    # scheduler) leave interactive False and just use their stored inputs.
    missing = _skill_missing_inputs(skill, inputs) if interactive else []
    mode = _normalize_chat_mode(skill.get("mode") or "pipeline")
    try:
        await _refresh_capabilities()
    except Exception:
        pass
    allowed = _allowed_agent_ids_for_chat(cid)
    candidates = [a["id"] for a in AGENTS if a["id"] in allowed]
    order, assignments = _resolve_skill_room(skill, candidates, inputs)
    if mode == "freewill" and str(inputs.get("agent_pool") or "").strip():
        requested_room, unknown_agents = _freewill_roster_from_inputs(inputs, candidates)
        if unknown_agents:
            await _route_system_note(
                cid,
                "True Free Will couldn't find: " + ", ".join(unknown_agents)
                + ". Use connected agent names or @handles from the Agents panel.",
                level="error",
            )
            return {"ok": False, "error": "unknown_agents", "agents": unknown_agents}
        if len(requested_room) < 3:
            await _route_system_note(
                cid,
                "True Free Will needs at least three connected agents so questions "
                "and floor handoffs have somewhere to go.",
                level="error",
            )
            return {"ok": False, "error": "not_enough_agents"}
        order, assignments = requested_room, {}
    if skill.get("kind") == "playbook" and not order:
        order = candidates[:1]  # a playbook just needs one agent to carry it out
    if mode == "sweep" and not order:
        # The sweep is code-backed and ignores its roster (it calls the orchestrator
        # directly), but apply_skill's staffing gate below still needs a non-empty
        # order — seed it with the orchestrator (or any granted agent as a fallback).
        _orch = _effective_concierge_agent_id()
        order = [_orch] if _orch in allowed else candidates[:1]
    if not order:
        await _route_system_note(
            cid, f"Skill “{skill['name']}” couldn’t be staffed — no eligible agents.", level="error"
        )
        return {"ok": False, "error": "no_agents"}
    _save_chat_mode(cid, mode)
    _save_chat_targets(cid, order)
    _set_chat_skill(cid, skill["id"], skill["name"])
    if missing:
        # Ask for the inputs FIRST, as an interactive card, and stop. The skill only
        # runs once the user fills them in and submits — which re-calls apply_skill
        # with the values supplied (interactive=False), so substitution into every
        # stage is clean instead of agents guessing from chat history. This also
        # avoids the pipeline marching past the lead before it has what it needs.
        await _post_input_request_card(cid, skill, order, missing)
        return {"ok": True, "chat_id": cid, "agents": order, "mode": mode,
                "awaiting_input": [m["name"] for m in missing],
                "chat": _skill_chat_handoff_meta(cid)}
    runtime_inputs, run_identity_note = _skill_runtime_inputs(skill, cid, inputs)
    if run_identity_note:
        order, assignments = _resolve_skill_room(skill, candidates, runtime_inputs)
        for aid in order:
            assignments[aid] = (
                run_identity_note + "\n\n" + str(assignments.get(aid) or "")
            ).strip()
    # FREE-WILL skips the synthetic kickoff entirely: no human is ever in this
    # room, so a "{actor}: Run the FREE-WILL Session" line (and the "▶ Running…"
    # note) would contradict the very first thing the host says — that nobody
    # else is here — and would sit at the top of an episode meant to be read or
    # listened to as pure dialogue. _run_freewill_turn supplies its own opener.
    if mode == "freewill":
        # Stash a user-supplied topic (a freewill skill input) for _run_freewill_turn
        # to open on — the room ignores it otherwise. Keyed by this fresh chat id.
        _topic = _freewill_topic_from_inputs(inputs)
        if _topic:
            _FREEWILL_TOPIC_OVERRIDE[cid] = _topic
    run_intent = _skill_run_intent(skill, inputs)
    _skill_pins, _skill_auto_tier, _skill_auto_enabled = _skill_effective_model_pins(
        skill, cid, order, mode, inputs, attachment_count=len(attachments),
    )
    if mode not in ("freewill", "sweep"):
        intent = run_intent
        # Files attached to the input-request card's fields ride the kickoff message
        # so every agent in the run sees them through the normal attachment-prompt
        # path (inline extracted text + signed fetch URL) — same as a file in chat.
        entry = append_thread(cid, "user", None, actor, intent, attachments=attachments)
        await broadcast({
            "type": "message", "chat_id": cid, "sender": "user", "name": actor,
            "text": intent, "ts": entry["ts"], "attachments": attachments,
        })
        joiner = " → " if mode == "pipeline" else ", "
        roster = joiner.join(AGENTS_BY_ID[a]["name"] for a in order)
        # Premium feel: hide the engine (no mode/model jargon). Name the extra agents
        # only when more than one is involved; otherwise just "Running '<name>'…".
        if len(order) > 1:
            await _route_system_note(cid, f"▶ Running “{skill['name']}” · {roster}…")
        else:
            await _route_system_note(cid, f"▶ Running “{skill['name']}”…")
        # Say it out loud when this run isn't using the room's models — the whole
        # point of the pins is that the models in play are never a surprise.
        pin_note = _skill_pin_summary(skill)
        if _skill_auto_enabled and _skill_auto_tier:
            await _route_system_note(
                cid,
                "⚙ " + _automatic_model_selection_summary(
                    order, _skill_pins, _skill_auto_tier,
                ),
            )
        if pin_note:
            await _route_system_note(cid, f"⚙ Model overrides for this run: {pin_note}")
    # Skill lint still gates unattended automations (hold / notify). Do not
    # dump it into the thread — "reply to the email" is a normal request.
    _bump_skill_usage(skill["id"])
    if skill.get("kind") == "playbook" and skill.get("body"):
        await _route_system_note(cid, "Playbook to follow:\n" + _substitute_inputs(skill["body"], inputs))
    turn_assignments = None if skill.get("kind") == "playbook" else assignments
    # A skill/automation run is fire-and-forget by nature: the user launches it and
    # walks away (or the scheduler fired it). So a stage that stalls — e.g. Codex
    # hitting its account usage limit — must AUTO-SKIP and let the run finish, never
    # park the interactive "retry / fix / continue" hold. That hold backs up a
    # pipeline (and recurring automations) with a card nobody is watching. Mark the
    # detached turn unattended; create_task() captures this context at creation, so
    # _run_pipeline_stages skips instead of holding. This makes EVERY skill path
    # consistent — manual "Apply"/"Run now" included, not just the scheduler (which
    # already sets it in _run_schedule). The interactive hold still appears for a
    # free-form pipeline typed in regular chat, which never goes through apply_skill.
    _skill_unattended = _UNATTENDED.set(True)
    # Model pins ride the same window: captured by create_task() into the
    # detached turn, reset before we return, so they apply to this run and
    # nothing else in the chat.
    _pins_tok = _RUN_MODEL_PINS.set(_skill_pins) if _skill_pins else None
    try:
        _spawn_chat_task(cid, _route_turn_then_notify(
            cid, order, mode, lead_id=None, assignments=turn_assignments,
            notify_event=notify_event,
            notify_title=(f"⏰ “{skill['name']}” finished" if notify_event == "automation_done" else None),
            push=push,
            # Mirror the background-job fan-out so completion reaches the chat,
            # other devices, and the Telegram pager — not just a single in-app card.
            pager=bool(notify_event), done_note=bool(notify_event),
        ))
    finally:
        _UNATTENDED.reset(_skill_unattended)
        if _pins_tok is not None:
            _RUN_MODEL_PINS.reset(_pins_tok)
    return {"ok": True, "chat_id": cid, "agents": order, "mode": mode,
            "chat": _skill_chat_handoff_meta(cid)}


# ------------------------------- API routes --------------------------------
@app.post("/api/chats/{cid}/save_skill")
async def api_save_skill(cid: int, request: Request):
    """Distill the current chat into a draft skill the user can review + activate."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    blocked = _require_chat_access(request, cid)
    if blocked:
        return blocked
    user = _current_user(request)
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    override_name = str((payload or {}).get("name") or "").strip()[:120]
    # If skill_id is given, fold this chat back INTO that existing skill (the chat
    # was launched from it and refined) rather than creating a new draft.
    update_id = (payload or {}).get("skill_id")
    existing = _get_skill(int(update_id), owner_user_id=(user or {}).get("id")) if update_id else None
    if update_id and not existing:
        return JSONResponse({"ok": False, "error": "skill not found"}, status_code=404)
    transcript = _chat_transcript_for_skill(cid)
    if not transcript.strip():
        return JSONResponse({"ok": False, "error": "empty chat"}, status_code=400)
    router = (
        AGENTS_BY_ID.get(_effective_concierge_agent_id())
        or AGENTS_BY_ID.get(LEAD_AGENT_ID)
        or (AGENTS[0] if AGENTS else None)
    )
    # Aim the distiller at what the user actually wants this skill to be: the name
    # they typed when capturing (new draft), or the skill being refined (update).
    intent_name = override_name or (existing.get("name") if existing else "") or ""
    distilled = None
    if router is not None:
        try:
            raw = await _concierge_call(
                router, _build_skill_distill_prompt(transcript, intent_name), SKILL_DISTILL_TIMEOUT_S
            )
            distilled = _parse_skill_reply(raw)
        except Exception as exc:
            logger.warning("skill distill via %s failed: %s", router["id"], exc)
    chat_meta = (CHAT_INDEX.get("chats", {}).get(str(cid), {}) or {})
    if not distilled:
        # Never hard-fail: seed a minimal draft from the chat's mode/targets so the
        # user can finish it in the editor.
        distilled = {
            "name": chat_meta.get("title") or f"Skill from chat #{cid}",
            "description": "",
            "kind": "workflow",
            "mode": _get_chat_mode(cid),
            "steps": [{"agent_id": t, "instruction": ""} for t in (chat_meta.get("targets") or [])],
        }
    if existing:
        # Merge the refined process into the existing skill, keeping its identity
        # (id/slug/status/pack/category and name, unless the user renamed it). Only
        # overlay fields the distill actually produced, so a thin distill can't wipe
        # the skill's domain/inputs.
        merged = dict(existing)
        for k in ("description", "mode", "tags", "body", "kind", "apis"):
            val = distilled.get(k)
            if val not in (None, "", []):
                merged[k] = val
        # Steps/inputs only overlay when the distill produced real content, so a
        # failed/thin distill (the minimal fallback below) can't blank the skill.
        new_steps = [s for s in (distilled.get("steps") or []) if isinstance(s, dict)]
        if any((s.get("instruction") or "").strip() for s in new_steps):
            merged["steps"] = new_steps
        if distilled.get("inputs"):
            merged["inputs"] = distilled["inputs"]
        merged["id"] = existing["id"]
        merged["status"] = existing["status"]
        merged["source_chat_id"] = cid
        if override_name:
            merged["name"] = override_name
        skill = _save_skill(merged, owner_user_id=(user or {}).get("id"))
        _audit_event(request, "skill.update", chat_id=cid, target=skill["slug"],
                     status="ok", meta={"kind": skill["kind"], "skill_id": skill["id"]})
        return JSONResponse({"ok": True, "skill": skill, "updated": True})
    distilled["status"] = "draft"
    distilled["source_chat_id"] = cid
    distilled["author"] = (user or {}).get("display_name") or GENERIC_PRINCIPAL
    if override_name:  # user named it up front — keep their name over the distilled one
        distilled["name"] = override_name
    skill = _save_skill(distilled, owner_user_id=(user or {}).get("id"))
    _audit_event(request, "skill.capture", chat_id=cid, target=skill["slug"],
                 status="ok", meta={"kind": skill["kind"]})
    return JSONResponse({"ok": True, "skill": skill, "updated": False})


@app.post("/api/skills/compose")
async def api_compose_skill(request: Request):
    """Conversational skill/automation builder. The user describes what they want in
    plain language; the orchestrator either asks follow-up questions or returns a
    ready-to-review skill draft (plus an optional schedule). Stateless — the client
    replays the running transcript each call and nothing is saved until the user
    accepts the proposal (via the normal /api/skills + /schedules endpoints)."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    try:
        body = await request.json()
    except Exception:
        body = {}
    raw_msgs = body.get("messages") if isinstance(body, dict) else None
    history: list[dict] = []
    if isinstance(raw_msgs, list):
        for m in raw_msgs[-20:]:
            if not isinstance(m, dict):
                continue
            content = str(m.get("content") or "").strip()
            if not content:
                continue
            role = "assistant" if m.get("role") == "assistant" else "user"
            history.append({"role": role, "content": content[:4000]})
    if not history or history[-1]["role"] != "user":
        return JSONResponse({"ok": False, "error": "say what you want to build"}, status_code=400)
    # Optional edit context: {"skill_id": N, "intent": "fix"}. When present, the server
    # authoritatively loads the current skill + its recent runs (never trusting a
    # client-sent skill body) so the orchestrator fixes the live definition.
    ctx = body.get("context") if isinstance(body, dict) else None
    ctx_skill = None
    ctx_runs = None
    if isinstance(ctx, dict) and ctx.get("skill_id"):
        try:
            ctx_skill = _get_skill(int(ctx["skill_id"]), owner_user_id=(user or {}).get("id"))
        except Exception:
            ctx_skill = None
        if not ctx_skill:
            return JSONResponse({"ok": False, "error": "skill not found"}, status_code=404)
        ctx_runs = _recent_runs_for_skill(ctx_skill["id"], limit=5)
    orchestrator = await _orchestrator_status(request)
    if not orchestrator["ready"]:
        return JSONResponse({
            "ok": False,
            "code": "orchestrator_setup_required",
            "error": orchestrator["reason"],
            "orchestrator": orchestrator,
        }, status_code=409)
    router = AGENTS_BY_ID.get(orchestrator["chosen_id"])
    if router is None:
        return JSONResponse({
            "ok": False, "code": "orchestrator_setup_required",
            "error": "Choose and test an orchestrator before building a skill.",
            "orchestrator": orchestrator,
        }, status_code=409)
    allowed = _allowed_agent_ids_for_user(user)
    roster, _online = await _concierge_roster_and_online(
        set(allowed) if allowed else None, include_dossier=True,
        owner_user_id=(user or {}).get("id"),
    )
    try:
        raw = await _concierge_call(
            router,
            _build_skill_compose_prompt(history, roster, skill=ctx_skill, runs=ctx_runs),
            SKILL_COMPOSE_TIMEOUT_S,
        )
    except Exception as exc:
        logger.warning("skill compose via %s failed: %s", router["id"], exc)
        _clear_orchestrator_verification()
        status = await _orchestrator_status(request, force=True)
        return JSONResponse({
            "ok": False,
            "code": "orchestrator_unavailable",
            "error": (
                f"{router.get('name') or router['id']} stopped responding. "
                "Reconnect it or choose another orchestrator."
            ),
            "orchestrator": status,
        }, status_code=502)
    parsed = _parse_skill_reply(raw)
    if not isinstance(parsed, dict):
        # Model didn't return clean JSON — fall back to treating its text as a
        # question so the conversation can continue rather than dead-ending.
        return JSONResponse({"ok": True, "action": "ask",
                             "message": (raw or "").strip()
                             or "Tell me a bit more about what you want this to do."})
    action = parsed.get("action")
    is_build = action in ("create", "update") and isinstance(parsed.get("skill"), dict)
    is_update = action == "update" and ctx_skill is not None
    message = str(parsed.get("message") or "").strip()
    if not is_build:
        return JSONResponse({"ok": True, "action": "ask",
                             "message": message or "Could you tell me a bit more?"})
    src = parsed.get("skill") or {}
    proposed = {
        "id": (ctx_skill["id"] if is_update else None),
        "name": str(src.get("name") or "Untitled skill").strip()[:120],
        "description": str(src.get("description") or "").strip()[:400],
        "kind": src.get("kind") if src.get("kind") in SKILL_KINDS else "workflow",
        "mode": _normalize_chat_mode(src.get("mode") or "pipeline"),
        "steps": _skill_steps_normalize(src.get("steps")),
        "inputs": _skill_inputs_normalize(src.get("inputs")),
        "secrets": _skill_secrets_normalize(src.get("secrets")),
        "apis": _skill_apis_normalize(src.get("apis")),
        "tags": [str(t).strip()[:40] for t in (src.get("tags") or []) if str(t).strip()][:12],
        "body": str(src.get("body") or "")[:20000],
        # Taxonomy is user-owned classification. "Fix with AI" may rebuild the
        # recipe, but it must not silently blank or reclassify the existing skill.
        # New skills can still take the orchestrator's suggested taxonomy, and the
        # manual editor remains the place to change an existing Industry/Category.
        "pack": (
            str(ctx_skill.get("pack") or "").strip()[:40]
            if is_update else str(src.get("pack") or "").strip()[:40]
        ),
        "category": (
            str(ctx_skill.get("category") or "").strip()[:40]
            if is_update else str(src.get("category") or "").strip()[:40]
        ),
        # Carried through, never model-authored: "Fix with AI" rebuilds the whole
        # skill, so without this an AI edit would silently drop the user's pins.
        # The orchestrator is not asked for this field and cannot set it.
        "agent_settings": ((ctx_skill.get("agent_settings") or {}) if is_update else {}),
        "status": (ctx_skill.get("status") if is_update else "draft"),
    }
    schedule = _normalize_proposed_schedule(parsed.get("schedule"))
    out_action = "update" if is_update else "create"
    _audit_event(request, "skill.compose", status="ok",
                 meta={"kind": proposed["kind"], "scheduled": bool(schedule), "action": out_action})
    return JSONResponse({"ok": True, "action": out_action, "message": message,
                         "skill": proposed, "schedule": schedule})


def _attach_schedule_summaries(skills: list, owner_user_id: Optional[int], *,
                               include_legacy: bool = False) -> None:
    """Annotate each skill with a lightweight schedule summary so the gallery can
    show an automation badge and power the Automations filter without a per-card
    round-trip. Adds: schedule_count, automation (>=1 enabled recurring schedule),
    cadence (human label of the soonest enabled schedule), next_run_ts."""
    if not skills:
        return
    clauses, params = [], []
    if owner_user_id is not None:
        clauses.append(
            "(owner_user_id IS NULL OR owner_user_id=?)"
            if include_legacy else "owner_user_id=?"
        )
        params.append(owner_user_id)
    where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
    by_skill: dict = {}
    with _db() as conn:
        rows = conn.execute(
            "SELECT skill_id, enabled, trigger_type, spec_json, next_run_ts "
            f"FROM skill_schedules{where}", params
        ).fetchall()
    for r in rows:
        by_skill.setdefault(r["skill_id"], []).append(r)
    for s in skills:
        scheds = by_skill.get(s["id"], [])
        enabled = [r for r in scheds if r["enabled"]]
        s["schedule_count"] = len(scheds)
        s["automation"] = bool(enabled)
        cands = enabled or scheds
        if cands:
            pick = min(cands, key=lambda r: (r["next_run_ts"] or float("inf")))
            s["cadence"] = _cadence_label(
                {"trigger_type": pick["trigger_type"],
                 "spec": _json_loads_or({}, pick["spec_json"])}
            )
            s["next_run_ts"] = pick["next_run_ts"]
        else:
            s["cadence"] = ""
            s["next_run_ts"] = None


def _skill_taxonomy(owner_id) -> dict:
    """Per-user custom Industry/Category values the user added from the Skills
    filter. Kept even when no skill uses them yet so they stay selectable; the
    client merges these with the values derived from the user's own skills."""
    raw = _get_setting(f"skills.taxonomy.{int(owner_id or 0)}", "")
    try:
        d = json.loads(raw) if raw else {}
    except Exception:
        d = {}
    ind = [x for x in (d.get("industries") or []) if isinstance(x, str) and x.strip()]
    cat = [x for x in (d.get("categories") or []) if isinstance(x, str) and x.strip()]
    return {"industries": ind, "categories": cat}


def _skill_taxonomy_add(owner_id, kind: str, value: str) -> dict:
    """Append one custom Industry/Category (case-insensitively deduped) and persist."""
    key = "industries" if kind == "industry" else "categories"
    tax = _skill_taxonomy(owner_id)
    v = value.strip()
    if v and v.lower() not in {x.lower() for x in tax[key]}:
        tax[key] = sorted(tax[key] + [v], key=str.lower)
        _set_setting(f"skills.taxonomy.{int(owner_id or 0)}", json.dumps(tax))
    return tax


@app.get("/api/skills")
async def api_list_skills(request: Request):
    user = _current_user(request)
    status = request.query_params.get("status")
    if status not in SKILL_STATUSES:
        status = None
    owner_id = (user or {}).get("id")
    skills = _list_skills(
        status=status, owner_user_id=owner_id, q=request.query_params.get("q")
    )
    _attach_schedule_summaries(
        skills, owner_id, include_legacy=_is_admin_user(user)
    )
    return JSONResponse({
        "ok": True,
        "skills": skills,
        "taxonomy": _skill_taxonomy(owner_id),
        "api_catalog": list(SKILL_API_CATALOG),
    })


@app.post("/api/skills/taxonomy")
async def api_skill_taxonomy_add(request: Request):
    """Add a custom Industry or Category from the Skills filter so it's selectable
    before any skill is tagged with it. Per-user; merged with skill-derived values."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    if not user:
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    try:
        body = await request.json()
    except Exception:
        body = {}
    kind = (body.get("kind") or "").strip().lower()
    value = (body.get("value") or "").strip()
    if kind not in ("industry", "category"):
        return JSONResponse({"ok": False, "error": "kind must be industry or category"}, status_code=400)
    if not value:
        return JSONResponse({"ok": False, "error": "name required"}, status_code=400)
    if len(value) > 40:
        return JSONResponse({"ok": False, "error": "keep it under 40 characters"}, status_code=400)
    tax = _skill_taxonomy_add(user["id"], kind, value)
    _audit_event(request, "skill.taxonomy_add", target=f"{kind}:{value}", status="ok")
    return JSONResponse({"ok": True, "taxonomy": tax})


def _skill_export_view(skill: dict) -> dict:
    """A portable, install-agnostic skill: roles only (agent pins dropped so it
    staffs from the target install's agents), no ids/owner/usage/timestamps."""
    return {
        "slug": skill["slug"],  # stable id so re-import can update in place
        "name": skill["name"], "description": skill["description"], "kind": skill["kind"],
        "mode": skill["mode"], "pack": skill.get("pack", ""), "category": skill.get("category", ""),
        "tags": skill.get("tags", []), "inputs": skill.get("inputs", []),
        "apis": skill.get("apis", []),
        # Declared credentials travel with the pack (agent_id dropped — install-agnostic)
        # so the importing install knows to capture them via the secure card.
        "secrets": [
            {"key": s.get("key", ""), "label": s.get("label", ""),
             "provider": s.get("provider", ""), "help": s.get("help", "")}
            for s in (skill.get("secrets") or [])
        ],
        "body": skill.get("body", ""),
        "steps": [
            {"role": st.get("role", ""), "instruction": st.get("instruction", "")}
            for st in (skill.get("steps") or [])
        ],
        "status": "active",  # a shipped pack arrives ready to use
    }


# NOTE: registered BEFORE /api/skills/{sid} so "export" isn't swallowed as an id.
@app.get("/api/skills/export")
async def api_export_skills(request: Request):
    """Download a portable skill pack (a JSON bundle) — by pack name or ids."""
    user = _current_user(request)
    pack = request.query_params.get("pack")
    category = request.query_params.get("category")
    ids = request.query_params.get("ids")
    skills = _list_skills(owner_user_id=(user or {}).get("id"),
                          pack=pack if pack else None, category=category if category else None)
    if ids:
        want = {i.strip() for i in ids.split(",") if i.strip()}
        skills = [s for s in skills if str(s["id"]) in want]
    bundle = {
        "format": "agentchat.skillpack", "version": 1,
        "pack": pack or "", "exported_ts": int(time.time() * 1000),
        "count": len(skills), "skills": [_skill_export_view(s) for s in skills],
    }
    fname = (_slugify(pack) if pack else "skills") + "-pack.json"
    return JSONResponse(bundle, headers={"Content-Disposition": f'attachment; filename="{fname}"'})


@app.post("/api/skills/import")
async def api_import_skills(request: Request):
    """Import a skill pack bundle into this install.

    mode='add' (default): only create skills that don't already exist (matched by
    the pack's stable slug, else by name) — safe, never touches existing rows.
    mode='update': also OVERWRITE existing pack skills in place, so re-shipping an
    improved pack refreshes them. Either way it's non-destructive — skills not in
    the bundle (e.g. ones the client created locally) are never removed."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    uid = (user or {}).get("id")
    try:
        body = await request.json()
    except Exception:
        body = {}
    if isinstance(body, list):
        items, pack_override, mode = body, None, "add"
    elif isinstance(body, dict):
        items = body.get("skills") or []
        pack_override = body.get("pack_override")
        mode = "update" if body.get("mode") == "update" else "add"
    else:
        items, pack_override, mode = [], None, "add"
    if not isinstance(items, list) or not items:
        return JSONResponse({"ok": False, "error": "no skills in bundle"}, status_code=400)
    by_name = {s["name"].strip().lower(): s for s in _list_skills(owner_user_id=uid)}
    added, updated, skipped = 0, 0, 0
    for it in items[:300]:
        if not isinstance(it, dict) or not str(it.get("name") or "").strip():
            skipped += 1
            continue
        # Match an existing skill by the pack's stable slug first, then by name.
        slug = str(it.get("slug") or "").strip()
        current = _get_skill(slug, owner_user_id=uid) if slug else None
        if current is None:
            current = by_name.get(it["name"].strip().lower())
        data = {k: v for k, v in it.items() if k not in ("id", "owner_user_id")}
        if pack_override:
            data["pack"] = pack_override
        data.setdefault("status", "active")
        data["author"] = "import"
        if current:
            if mode != "update":
                skipped += 1
                continue
            data["id"] = current["id"]          # overwrite in place
            data["slug"] = current["slug"]
            _save_skill(data, owner_user_id=uid)
            updated += 1
        else:
            row = _save_skill(data, owner_user_id=uid)
            by_name[row["name"].strip().lower()] = row
            added += 1
    _audit_event(request, "skill.import", status="ok",
                 meta={"mode": mode, "added": added, "updated": updated, "skipped": skipped})
    return JSONResponse({"ok": True, "mode": mode, "added": added, "updated": updated,
                         "skipped": skipped, "imported": added})


