def _attachments_from_payload(cid: int, raw_attachments) -> list[dict]:
    """Validate client-supplied attachment metas against this chat's disk store and
    return them in the canonical thread shape. Same trust model as the /api/send
    route: we only accept files that already exist under this chat (i.e. they came
    from /api/chats/{cid}/attachments), then derive url/text_url from disk so they
    can't be spoofed. Used by the skill input-request card so a file attached to a
    form field rides the kickoff message and every agent in the run can read it."""
    out: list[dict] = []
    if not isinstance(raw_attachments, list):
        return out
    for a in raw_attachments[:8]:  # cap per-message attachment count
        if not isinstance(a, dict):
            continue
        fid = a.get("id") or ""
        bytes_path, _ = _attachment_paths(cid, fid)
        if not bytes_path or not bytes_path.is_file():
            continue
        att = {
            "id": fid,
            "name": str(a.get("name", fid))[:200],
            "mime": str(a.get("mime", "application/octet-stream"))[:100],
            "size": int(a.get("size", 0) or 0),
            "url": f"/attachments/{cid}/{fid}",
        }
        if bytes_path.with_suffix(".txt").is_file():
            att["text_url"] = f"/attachments/{cid}/{fid}/text"
        out.append(att)
    return out


@app.post("/api/skills/{sid}/apply")
async def api_apply_skill(sid: int, request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    skill = _get_skill(int(sid), owner_user_id=(user or {}).get("id"))
    if not skill:
        return JSONResponse({"ok": False, "error": "not found"}, status_code=404)
    try:
        body = await request.json()
    except Exception:
        body = {}
    inputs = body.get("inputs") if isinstance(body.get("inputs"), dict) else {}
    # A first "Run now" is interactive (default): if the skill declares inputs, post
    # the inputs card and wait. The card's submit re-calls this route with the values
    # AND interactive=False, so that pass skips the card and runs the skill for real.
    interactive = bool(body.get("interactive", True))
    raw_attachments = body.get("attachments")
    cid = body.get("chat_id")
    if cid is not None:
        blocked = _require_chat_access(request, int(cid))
        if blocked:
            return blocked
        cid = int(cid)
    else:
        cid = _create_chat_record(
            f"▶ {skill['name']}", mode=_normalize_chat_mode(skill.get("mode") or "pipeline"),
            owner_user_id=(user or {}).get("id"),
        )
        await broadcast({
            "type": "chat_meta", "chat_id": cid,
            "title": CHAT_INDEX["chats"][str(cid)]["title"],
        }, global_event=True)
    attachments = _attachments_from_payload(cid, raw_attachments)
    result = await apply_skill(
        skill, cid, inputs, actor=(user or {}).get("display_name") or GENERIC_PRINCIPAL,
        # Once it actually runs it's a walk-away run — push=True so a skill the user
        # launched then left still reaches a closed app / other device (same contract
        # as the 🚀 fire-and-forget job; pager + in-chat note fire too).
        notify_event="automation_done", push=True, interactive=interactive,
        attachments=attachments,
    )
    # If this pass actually started the skill (not just posted the inputs card),
    # settle any inputs card in this chat so its form flips to "submitted". Scans
    # the thread, so it's robust even if the in-memory pending set was lost.
    if result.get("ok") and not result.get("awaiting_input"):
        await _resolve_input_card(cid)
    _audit_event(request, "skill.apply", chat_id=cid, target=skill["slug"],
                 status="ok" if result.get("ok") else "error", meta={"agents": result.get("agents")})
    return JSONResponse({"ok": result.get("ok", False), "chat_id": cid, **result})


# ----------------------------- scheduling ----------------------------------
def _schedule_from_row(row) -> dict:
    return {
        "id": row["id"], "skill_id": row["skill_id"], "name": row["name"],
        "enabled": bool(row["enabled"]), "trigger_type": row["trigger_type"],
        "spec": _json_loads_or({}, row["spec_json"]),
        "inputs": _json_loads_or({}, row["inputs_json"]),
        "target": row["target"], "next_run_ts": row["next_run_ts"],
        "last_run_ts": row["last_run_ts"], "last_status": row["last_status"],
        "created_ts": row["created_ts"], "updated_ts": row["updated_ts"],
        "owner_user_id": row["owner_user_id"],
        "series_chat_id": (row["series_chat_id"] if "series_chat_id" in row.keys() else None),
        "archetype": (row["archetype"] if "archetype" in row.keys() else "") or "",
        "notify": _json_loads_or({}, row["notify_json"]) if "notify_json" in row.keys() else {},
        "change_gate": bool(row["change_gate"]) if "change_gate" in row.keys() else False,
        "hold_gated": bool(row["hold_gated"]) if "hold_gated" in row.keys() else False,
    }


def _list_schedules(skill_id: Optional[int] = None, owner_user_id: Optional[int] = None,
                    *, include_legacy: bool = False) -> list[dict]:
    clauses, params = [], []
    if skill_id is not None:
        clauses.append("skill_id=?"); params.append(int(skill_id))
    if owner_user_id is not None:
        clauses.append(
            "(owner_user_id IS NULL OR owner_user_id=?)"
            if include_legacy else "owner_user_id=?"
        )
        params.append(owner_user_id)
    where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
    with _db() as conn:
        rows = conn.execute(
            f"SELECT * FROM skill_schedules{where} ORDER BY id DESC", params
        ).fetchall()
    return [_schedule_from_row(r) for r in rows]


def _next_clock_ms(now_epoch: float, hh: int, mm: int) -> int:
    base = datetime.fromtimestamp(now_epoch)
    target = base.replace(hour=hh % 24, minute=mm % 60, second=0, microsecond=0)
    if target <= base:
        target += timedelta(days=1)
    return int(target.timestamp() * 1000)


def _next_weekly_ms(now_epoch: float, weekday: int, hh: int, mm: int) -> int:
    base = datetime.fromtimestamp(now_epoch)
    target = base.replace(hour=hh % 24, minute=mm % 60, second=0, microsecond=0)
    target += timedelta(days=(int(weekday) - base.weekday()) % 7)
    if target <= base:
        target += timedelta(days=7)
    return int(target.timestamp() * 1000)


# Optional "active window" constraints a user can attach to interval/daily
# automations: restrict firing to certain weekdays and/or a daily hour band, in a
# chosen timezone (defaults to server-local time, which here is US Central). Days
# use the same 0=Sun..6=Sat convention as the weekly trigger / WEEKDAYS array.
_SCHED_TZ_CHOICES = {
    "America/Chicago", "America/New_York", "America/Denver", "America/Phoenix",
    "America/Los_Angeles", "America/Anchorage", "Pacific/Honolulu", "UTC",
}


def _sched_tz(tz_name):
    """ZoneInfo for a stored tz name, or None to use server-local time."""
    if not tz_name:
        return None
    try:
        from zoneinfo import ZoneInfo
        return ZoneInfo(str(tz_name))
    except Exception:
        return None


def _clean_tz(raw) -> str:
    tz = str(raw or "").strip()
    return tz if tz in _SCHED_TZ_CHOICES else ""


def _clean_days(raw) -> list:
    """Whitelist a list of weekday ints (0=Sun..6=Sat), de-duped and sorted."""
    out = []
    for d in (raw or []):
        try:
            di = int(d) % 7
        except (TypeError, ValueError):
            continue
        if di not in out:
            out.append(di)
    return sorted(out)


def _window_bounds(win):
    """(start_h, end_h) with 0<=start<end<=24, or None for no/invalid window."""
    if not isinstance(win, dict):
        return None
    try:
        start = int(win.get("start"))
        end = int(win.get("end"))
    except (TypeError, ValueError):
        return None
    start = max(0, min(23, start))
    end = max(1, min(24, end))
    if start >= end:
        return None
    return (start, end)


def _sched_dow(dt) -> int:
    """Weekday in the schedule convention (0=Sun..6=Sat) for a datetime."""
    return (dt.weekday() + 1) % 7


def _sched_local_dt(epoch_s, tz):
    return datetime.fromtimestamp(epoch_s, tz) if tz else datetime.fromtimestamp(epoch_s)


def _next_interval_run(now_s, seconds, days, win, tz_name) -> int:
    """Next interval fire >= now+seconds, snapped forward to land on an allowed
    weekday and (if set) inside the daily hour window, in the chosen timezone."""
    seconds = max(60, int(seconds or 3600))
    tz = _sched_tz(tz_name)
    days_set = {int(d) % 7 for d in (days or [])}
    bounds = _window_bounds(win)
    cand = now_s + seconds
    for _ in range(370):  # bounded: at most ~a year of day hops
        dt = _sched_local_dt(cand, tz)
        day_ok = (not days_set) or (_sched_dow(dt) in days_set)
        if day_ok and bounds is None:
            return int(cand * 1000)
        if day_ok and bounds is not None:
            start, end = bounds
            if start <= dt.hour < end:
                return int(cand * 1000)
            if dt.hour < start:  # before today's window -> jump to its start
                cand = dt.replace(hour=start, minute=0, second=0, microsecond=0).timestamp()
                continue
        # wrong day, or past today's window: jump to the next day's window start
        nxt = (dt + timedelta(days=1)).replace(
            hour=(bounds[0] if bounds else 0), minute=0, second=0, microsecond=0)
        cand = nxt.timestamp()
    return int(cand * 1000)


def _next_daily_run(now_s, hh, mm, days, tz_name) -> int:
    """Next daily fire at hh:mm, optionally limited to allowed weekdays, tz-aware."""
    tz = _sched_tz(tz_name)
    days_set = {int(d) % 7 for d in (days or [])}
    base = _sched_local_dt(now_s, tz)
    target = base.replace(hour=int(hh) % 24, minute=int(mm) % 60, second=0, microsecond=0)
    if target <= base:
        target += timedelta(days=1)
    for _ in range(8):
        if (not days_set) or (_sched_dow(target) in days_set):
            break
        target += timedelta(days=1)
    return int(target.timestamp() * 1000)


def _clean_hhmm(raw):
    """A {'hh','mm'} time-of-day → (hh, mm) clamped, or None when absent/invalid."""
    if not isinstance(raw, dict):
        return None
    if raw.get("hh") is None and raw.get("mm") is None:
        return None
    return (_coerce_int(raw.get("hh"), 0) % 24, _coerce_int(raw.get("mm"), 0) % 60)


def _start_anchor_ts(hhmm, tz_name, now_s=None) -> Optional[int]:
    """Absolute epoch-ms of the next hh:mm occurrence at-or-after now, in the
    schedule's tz. Used to gate an automation's FIRST run (it won't fire before
    this time); later runs follow the normal cadence."""
    if not hhmm:
        return None
    hh, mm = hhmm
    now_s = now_s if now_s is not None else time.time()
    tz = _sched_tz(tz_name)
    base = _sched_local_dt(now_s, tz)
    target = base.replace(hour=hh, minute=mm, second=0, microsecond=0)
    if target <= base:
        target += timedelta(days=1)
    return int(target.timestamp() * 1000)


def _apply_start_anchor(spec: dict, raw: dict) -> dict:
    """If raw carries an optional start_at {hh,mm}, record the time-of-day plus an
    absolute first-run anchor (next occurrence in the spec's tz, server-local when
    none). Stored once at save so it gates only the first run."""
    hhmm = _clean_hhmm(raw.get("start_at"))
    if not hhmm:
        return spec
    spec["start_at"] = {"hh": hhmm[0], "mm": hhmm[1]}
    ts = _start_anchor_ts(hhmm, spec.get("tz"))
    if ts:
        spec["start_at_ts"] = ts
    return spec


def _sanitize_sched_spec(trigger_type: str, raw) -> dict:
    """Whitelist/clamp a schedule spec by trigger type, including the optional
    day/window/tz constraints and first-run start anchor on time-based automations."""
    raw = raw if isinstance(raw, dict) else {}
    if trigger_type == "interval":
        spec = {"seconds": max(60, _coerce_int(raw.get("seconds"), 3600))}
        days = _clean_days(raw.get("days"))
        if days and len(days) < 7:  # all 7 == no restriction, so store nothing
            spec["days"] = days
        bounds = _window_bounds(raw.get("win"))
        if bounds:
            spec["win"] = {"start": bounds[0], "end": bounds[1]}
        tz = _clean_tz(raw.get("tz"))
        if tz:
            spec["tz"] = tz
        return _apply_start_anchor(spec, raw)
    if trigger_type == "daily":
        spec = {"hh": _coerce_int(raw.get("hh"), 9) % 24, "mm": _coerce_int(raw.get("mm"), 0) % 60}
        days = _clean_days(raw.get("days"))
        if days and len(days) < 7:
            spec["days"] = days
        tz = _clean_tz(raw.get("tz"))
        if tz:
            spec["tz"] = tz
        return _apply_start_anchor(spec, raw)
    if trigger_type == "weekly":
        spec = {"weekday": _coerce_int(raw.get("weekday"), 0) % 7,
                "hh": _coerce_int(raw.get("hh"), 9) % 24, "mm": _coerce_int(raw.get("mm"), 0) % 60}
        return _apply_start_anchor(spec, raw)
    if trigger_type == "event":
        return {"event": (str(raw.get("event") or "attachment_added").strip() or "attachment_added")[:60]}
    return raw


def _compute_next_run(trigger_type: str, spec: dict, now_ms: Optional[int] = None) -> Optional[int]:
    now = (now_ms or int(time.time() * 1000)) / 1000.0
    spec = spec or {}
    if trigger_type == "interval":
        nxt = _next_interval_run(now, spec.get("seconds") or 3600,
                                 spec.get("days"), spec.get("win"), spec.get("tz"))
    elif trigger_type == "daily":
        nxt = _next_daily_run(now, spec.get("hh", 9), spec.get("mm", 0),
                              spec.get("days"), spec.get("tz"))
    elif trigger_type == "weekly":
        nxt = _next_weekly_ms(now, int(spec.get("weekday", 0)), int(spec.get("hh", 9)), int(spec.get("mm", 0)))
    else:
        return None  # manual / event have no time-based next run
    # Optional first-run anchor: hold the very first fire until the start time.
    # Stored absolute, so once it has passed it no longer affects later runs.
    sa = spec.get("start_at_ts")
    if nxt is not None and isinstance(sa, (int, float)) and sa > nxt:
        return int(sa)
    return nxt


def _schedule_effective_owner(owner_user_id: Optional[int]) -> int:
    """Owner used by legacy NULL-owner schedules.

    NULL schedules predate tenants and historically ran in the bootstrap admin's
    workspace. Keeping that mapping preserves their behavior without treating
    them as shared rows that every tenant may read or fire.
    """
    return int(owner_user_id) if owner_user_id is not None else _default_admin_id()


def _schedule_skill_matches_owner(skill: Optional[dict],
                                  owner_user_id: Optional[int]) -> bool:
    if not skill:
        return False
    skill_owner = skill.get("owner_user_id")
    return skill_owner is None or int(skill_owner) == _schedule_effective_owner(owner_user_id)


def _schedule_target_is_valid(target: object, owner_user_id: Optional[int]) -> bool:
    """A numeric schedule target must be an existing chat owned by the schedule.

    Non-numeric targets retain the existing new-chat behavior. This check is run
    both on save and immediately before execution so deletion or ownership drift
    cannot turn a formerly valid schedule into a cross-tenant write primitive.
    """
    raw = str(target or "new_chat").strip()
    if not raw.isdigit():
        return True
    with _db() as conn:
        row = conn.execute(
            "SELECT owner_user_id FROM chats WHERE id=? AND deleted_ts IS NULL",
            (int(raw),),
        ).fetchone()
    return bool(
        row and row["owner_user_id"] is not None
        and int(row["owner_user_id"]) == _schedule_effective_owner(owner_user_id)
    )


def _schedule_owner_is_admin(owner_user_id: Optional[int]) -> bool:
    if owner_user_id is None:
        return True
    with _db() as conn:
        row = conn.execute(
            "SELECT role, is_active FROM users WHERE id=?", (int(owner_user_id),)
        ).fetchone()
    return bool(row and row["role"] == "admin" and row["is_active"])


def _save_schedule(data: dict, owner_user_id: Optional[int] = None) -> Optional[dict]:
    skill_id = data.get("skill_id")
    try:
        skill_id = int(skill_id)
    except (TypeError, ValueError):
        return None
    skill = _get_skill(skill_id)
    if not skill_id or not _schedule_skill_matches_owner(skill, owner_user_id):
        return None
    now = int(time.time() * 1000)
    trigger_type = data.get("trigger_type") if data.get("trigger_type") in SCHEDULE_TRIGGERS else "interval"
    spec = _sanitize_sched_spec(trigger_type, data.get("spec"))
    inputs = data.get("inputs") if isinstance(data.get("inputs"), dict) else {}
    target = str(data.get("target") or "new_chat")[:32]
    if not _schedule_target_is_valid(target, owner_user_id):
        return None
    enabled = 1 if data.get("enabled", True) else 0
    name = str(data.get("name") or "")[:120]
    next_run = _compute_next_run(trigger_type, spec, now) if enabled else None
    archetype = str(data.get("archetype") or "")[:32]
    notify = data.get("notify")
    if not isinstance(notify, dict):
        notify = _json_loads_or({}, data.get("notify_json") or "{}")
    change_gate = 1 if data.get("change_gate") else 0
    hold_gated = 1 if data.get("hold_gated") else 0
    sid = data.get("id")
    if sid is not None:
        try:
            sid = int(sid)
        except (TypeError, ValueError):
            return None
    with _db() as conn:
        existing = conn.execute(
            "SELECT id, skill_id, owner_user_id FROM skill_schedules WHERE id=?",
            (sid,),
        ).fetchone() if sid is not None else None
        if sid is not None and not existing:
            return None
        if existing:
            same_owner = (
                existing["owner_user_id"] is None and owner_user_id is None
            ) or (
                existing["owner_user_id"] is not None and owner_user_id is not None
                and int(existing["owner_user_id"]) == int(owner_user_id)
            )
            # A caller-supplied id is only an update handle for the exact same
            # owner + path skill. It may never retarget or take over another row.
            if not same_owner or int(existing["skill_id"]) != skill_id:
                return None
            conn.execute(
                "UPDATE skill_schedules SET skill_id=?, name=?, enabled=?, trigger_type=?, spec_json=?, "
                "inputs_json=?, target=?, next_run_ts=?, archetype=?, notify_json=?, change_gate=?, "
                "hold_gated=?, updated_ts=? WHERE id=?",
                (skill_id, name, enabled, trigger_type, json.dumps(spec), json.dumps(inputs),
                 target, next_run, archetype, json.dumps(notify), change_gate, hold_gated, now, sid),
            )
            new_id = sid
        else:
            cur = conn.execute(
                "INSERT INTO skill_schedules(skill_id, name, enabled, trigger_type, spec_json, inputs_json, "
                "target, next_run_ts, archetype, notify_json, change_gate, hold_gated, created_ts, updated_ts, "
                "owner_user_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (skill_id, name, enabled, trigger_type, json.dumps(spec), json.dumps(inputs),
                 target, next_run, archetype, json.dumps(notify), change_gate, hold_gated, now, now, owner_user_id),
            )
            new_id = int(cur.lastrowid)
        row = conn.execute("SELECT * FROM skill_schedules WHERE id=?", (new_id,)).fetchone()
    return _schedule_from_row(row)


def _mark_schedule_ran(sid: int, status: str, advance: bool) -> None:
    now = int(time.time() * 1000)
    with _db() as conn:
        row = conn.execute("SELECT * FROM skill_schedules WHERE id=?", (int(sid),)).fetchone()
        if not row:
            return
        if advance and row["enabled"]:
            nxt = _compute_next_run(row["trigger_type"], _json_loads_or({}, row["spec_json"]), now)
        elif advance:
            nxt = None
        else:
            nxt = row["next_run_ts"]
        conn.execute(
            "UPDATE skill_schedules SET last_run_ts=?, last_status=?, next_run_ts=? WHERE id=?",
            (now, str(status)[:60], nxt, int(sid)),
        )


_RECURRING_TRIGGERS = ("interval", "daily", "weekly")


def _cadence_label(sched: dict) -> str:
    """Human cadence for the digest card header ("hourly", "every 4h", "daily")."""
    tt = sched.get("trigger_type")
    spec = sched.get("spec") or {}
    if tt == "interval":
        secs = max(60, int(spec.get("seconds") or 3600))
        if secs % 3600 == 0:
            h = secs // 3600
            return "hourly" if h == 1 else f"every {h}h"
        m = max(1, secs // 60)
        return "every minute" if m == 1 else f"every {m}m"
    if tt == "daily":
        return "daily"
    if tt == "weekly":
        return "weekly"
    return str(tt or "")


def _set_schedule_series_chat(sid: int, cid: int) -> None:
    with _db() as conn:
        conn.execute(
            "UPDATE skill_schedules SET series_chat_id=? WHERE id=?", (int(cid), int(sid))
        )


async def _ensure_series_chat(sched: dict, skill: dict) -> int:
    """Return the stable chat a recurring schedule's runs append into, creating it
    once on first run (so every hourly run lands in one place and folds into a
    single digest card). The id is stored back on the schedule row for reuse."""
    existing = sched.get("series_chat_id")
    if existing and str(int(existing)) in CHAT_INDEX.get("chats", {}):
        existing_owner = _chat_owner_id(int(existing))
        if (existing_owner is not None
                and int(existing_owner) == _schedule_effective_owner(
                    sched.get("owner_user_id"))):
            return int(existing)
    cid = _create_chat_record(
        f"🔁 {skill['name']}",
        mode=_normalize_chat_mode(skill.get("mode") or "pipeline"),
        owner_user_id=sched.get("owner_user_id"),
    )
    _set_schedule_series_chat(int(sched["id"]), cid)
    sched["series_chat_id"] = cid
    await broadcast({
        "type": "chat_meta", "chat_id": cid,
        "title": CHAT_INDEX["chats"][str(cid)]["title"],
    }, global_event=True)
    return cid


async def _ping_gated_run(cid: int, skill: dict, source: str,
                          scan: dict, owner_user_id: Optional[int]) -> None:
    """Capped-and-logged autonomy. A `gated` skill (trades, code execution,
    destructive/secret-moving actions) firing UNATTENDED still runs — but the
    owner is pinged the instant it does, on every channel (in-app card + web
    push + Telegram pager), so a money/exec automation can never act unseen.
    Each channel is isolated so one failing never starves the others."""
    name = skill.get("name") or "skill"
    cats = ", ".join(dict.fromkeys(
        f["category"] for f in scan.get("findings", []) if f["severity"] == "high"
    )) or "gated action"
    title = f"⚠️ Gated automation fired: {name}"
    body = f"{source} · {cats}. It runs within its limits — open the chat if this looks wrong."
    try:
        await _emit_notification(cid, event="gated_automation", title=title, body=body,
                                 severity="warn", push=True, owner_user_id=owner_user_id)
    except Exception:
        logger.exception("gated-run ping: notify/push failed for chat %s", cid)
    try:
        await _tg_send(f"<b>{_tg_esc(title)}</b>\n{_tg_esc(body)}", parse_html=True)
    except Exception:
        logger.exception("gated-run ping: telegram failed for chat %s", cid)


async def _hold_gated_run(sched: dict, skill: dict, source: str, scan: dict) -> None:
    """Opt-in pre-execution approval gate (hold_gated). Instead of running a
    `gated` automation unattended, park a pending approval item and post a hold
    card + ping on every channel. The run fires only when the owner approves
    (api_decide_automation_item re-enters _run_schedule with bypass_hold=True)."""
    sid = int(sched["id"])
    # Never stack holds: if this schedule already has a pending gated_hold, leave it.
    with _db() as conn:
        dup = conn.execute(
            "SELECT id FROM automation_items WHERE schedule_id=? AND kind='gated_hold' "
            "AND state='pending' LIMIT 1", (sid,)).fetchone()
    if dup:
        return
    # Land the hold card where the run would have appeared: the series chat for a
    # recurring automation, otherwise a fresh chat.
    target = sched.get("target") or "new_chat"
    recurring = sched.get("trigger_type") in _RECURRING_TRIGGERS
    if target == "new_chat" and recurring:
        cid = await _ensure_series_chat(sched, skill)
    elif target == "new_chat" or not str(target).isdigit():
        cid = _create_chat_record(
            f"⏸️ {skill['name']} (held)",
            mode=_normalize_chat_mode(skill.get("mode") or "pipeline"),
            owner_user_id=sched.get("owner_user_id"))
        await broadcast({"type": "chat_meta", "chat_id": cid,
                         "title": CHAT_INDEX["chats"][str(cid)]["title"]}, global_event=True)
    else:
        cid = int(target)
    cats = ", ".join(dict.fromkeys(
        f["category"] for f in scan.get("findings", []) if f["severity"] == "high"
    )) or "gated action"
    payload = {"skill_name": skill.get("name"), "categories": cats,
               "chat_id": cid, "source": source}
    now = int(time.time() * 1000)
    with _db() as conn:
        conn.execute(
            "INSERT INTO automation_items(schedule_id, run_id, owner_user_id, kind, state, "
            "payload_json, created_ts) VALUES (?,?,?,?,?,?,?)",
            (sid, None, sched.get("owner_user_id"), "gated_hold", "pending",
             json.dumps(payload), now))
    title = f"⏸️ Gated automation held for approval: {skill.get('name')}"
    body = (f"{source} · {cats}. This automation can take an irreversible action, so it is "
            f"paused until you approve it. Approve in Automations to run it now, or reject to skip.")
    try:
        await _route_system_note(cid, f"{title} — {body}", level="error")
    except Exception:
        logger.exception("hold-gated note failed for chat %s", cid)
    try:
        await _emit_notification(cid, event="gated_hold", title=title, body=body,
                                 severity="warn", push=True,
                                 owner_user_id=sched.get("owner_user_id"))
    except Exception:
        logger.exception("hold-gated notify failed for chat %s", cid)
    try:
        await _tg_send(f"<b>{_tg_esc(title)}</b>\n{_tg_esc(body)}", parse_html=True)
    except Exception:
        logger.exception("hold-gated telegram failed for chat %s", cid)


# ----------------------- Mission Control: automation runs -----------------------
# An "automation" is a recurring skill_schedules row. Mission Control promotes it
# to a first-class job: a discrete run history (automation_runs), an archetype that
# drives a default escalation policy, and an approvals inbox (automation_items).
# No parallel table and no message migration — runs REFERENCE the existing series
# chat. All of this is additive; ordinary chat turns never touch it.
AUTOMATION_ARCHETYPES = ("monitor", "action_queue", "report", "alert")
_ARCH_FALLBACK = "monitor"
_NOTIFY_LOUDNESS = ("off", "brief", "push", "telegram")

# Per archetype: event -> baseline loudness. The orchestrator starts here, bumps
# for stakes (gated skills), and the user can pin overrides on top.
_NOTIFY_BASELINE = {
    "monitor":      {"completed_ok": "brief", "failed_recovered": "brief", "failed_hard": "push"},
    "action_queue": {"completed_ok": "brief", "needs_approval": "brief",
                     "failed_recovered": "brief", "failed_hard": "telegram"},
    "report":       {"completed_ok": "brief", "failed_recovered": "brief", "failed_hard": "push"},
    "alert":        {"completed_ok": "off", "failed_recovered": "brief",
                     "failed_hard": "telegram", "alert_triggered": "telegram"},
}


def _infer_archetype(skill: dict) -> str:
    """Best-guess archetype from a skill's name/description/tags. The orchestrator
    can set it explicitly at creation; this is the fallback so existing schedules
    still resolve to a sensible default policy."""
    hay = " ".join([
        skill.get("name") or "", skill.get("description") or "",
        " ".join(skill.get("tags") or []) if isinstance(skill.get("tags"), list) else "",
        skill.get("category") or "",
    ]).lower()
    if any(w in hay for w in ("alert", "watcher", "watch for", "threshold", "notify when", "anomaly")):
        return "alert"
    if any(w in hay for w in ("draft", "reply", "approve", "outreach", "send email", "triage", "follow-up", "follow up")):
        return "action_queue"
    if any(w in hay for w in ("report", "deliverable")):
        return "report"
    return "monitor"


def _default_notify_policy(archetype: str, gated: bool = False) -> dict:
    base = dict(_NOTIFY_BASELINE.get(archetype, _NOTIFY_BASELINE[_ARCH_FALLBACK]))
    if gated:
        bump = {"off": "brief", "brief": "push", "push": "telegram", "telegram": "telegram"}
        for ev in ("failed_hard", "needs_approval"):
            if ev in base:
                base[ev] = bump[base[ev]]
    return base


def _effective_notify(sched: dict, gated: bool = False) -> dict:
    """The policy actually in force: the archetype/stakes baseline, with any event
    the user explicitly saved (a pinned override) layered on top."""
    arch = (sched.get("archetype") or _ARCH_FALLBACK)
    base = _default_notify_policy(arch, gated=gated)
    saved = sched.get("notify") or {}
    for ev, loud in saved.items():
        if ev.startswith("_") or ev == "quiet_hours":
            continue
        if loud in _NOTIFY_LOUDNESS:
            base[ev] = loud
    return base


def _resolve_run_notify(schedule_id: int, *, completed: bool, arun_status: str,
                        health: str, standin: bool) -> "tuple[Optional[str], str]":
    """Decide how a finished automation run should notify, per its schedule's
    policy (archetype baseline + the user's pinned overrides + the gated bump).
    Resolves the run's outcome to ONE policy event, then returns (event, loudness)
    with loudness ∈ off|brief|push|telegram. Returns (None, "off") for outcomes
    that must never ping (a deliberate Stop). The caller maps loudness onto the
    cumulative channel ladder (off < brief < push < telegram)."""
    try:
        with _db() as conn:
            row = conn.execute(
                "SELECT * FROM skill_schedules WHERE id=?", (int(schedule_id),)
            ).fetchone()
        sched = _schedule_from_row(row) if row else None
    except Exception:
        logger.exception("notify: schedule load failed for %s", schedule_id)
        sched = None
    if not sched:
        return None, "off"
    gated = False
    try:
        skill = _get_skill(int(sched["skill_id"])) or {}
        gated = bool(skill) and _scan_skill(skill).get("tier") == "gated"
        if not sched.get("archetype") and skill:
            sched["archetype"] = _infer_archetype(skill)
    except Exception:
        pass
    policy = _effective_notify(sched, gated=gated)

    # Outcome → policy event.
    if arun_status == "stopped":
        return None, "off"                        # a deliberate Stop never pings
    if arun_status == "held":
        event = "needs_approval"
    elif standin and completed:
        event = "failed_recovered"
    elif arun_status == "failed" or (not completed and health == "red"):
        event = "failed_hard"
    elif completed and health == "green":
        event = "completed_ok"
    elif completed:
        # Completed but self-flagged amber/red: an alert watcher tripping, or a
        # monitor/report surfacing a concern. Use the "tripped" event; when the
        # archetype has no such event it falls through to the health floor below.
        event = "alert_triggered"
    else:
        event = "completed_ok"

    loud = policy.get(event)
    if loud not in _NOTIFY_LOUDNESS:
        # Event not defined for this archetype (e.g. a monitor that got held) →
        # floor by health so a real problem is never silently dropped.
        loud = {"green": "brief", "amber": "push", "red": "telegram"}.get(health, "brief")
    return event, loud


def _automation_run_cost(conn, chat_id, start_ts: int, end_ts: int) -> tuple[int, float]:
    """Tokens and USD spent during a run = token_usage rows for the run's chat in
    its time window.

    USD is priced per (model, provider) group with the same list-price model the
    usage dashboard uses, so a run's cost and the dashboard's totals can't drift:
    uncached input at the input rate, cached reads at the discounted rate, output
    at the output rate. `input_tokens` already includes the cached portion (see
    _record_token_usage), hence max(i - c, 0)."""
    if not chat_id:
        return 0, 0.0
    rows = conn.execute(
        "SELECT agent_id, model, provider, "
        "COALESCE(SUM(input_tokens),0) AS i, COALESCE(SUM(output_tokens),0) AS o, "
        "COALESCE(SUM(cached_tokens),0) AS c, COALESCE(SUM(reasoning_tokens),0) AS r "
        "FROM token_usage WHERE chat_id=? AND ts>=? AND ts<=? "
        "GROUP BY agent_id, model, provider",
        (int(chat_id), int(start_ts), int(end_ts)),
    ).fetchall()
    toks = 0
    usd = 0.0
    for row in rows:
        i, o, c, r = int(row["i"]), int(row["o"]), int(row["c"]), int(row["r"])
        toks += i + o + r
        # Prefer the agent's live provider — history can carry a stale one.
        prov = _provider_for_agent(row["agent_id"] or "", row["model"] or "") or row["provider"]
        rates = _price_for_model(row["model"] or "", prov)
        usd += (max(i - c, 0) * rates["in"] + c * rates["cached"] + o * rates["out"]) / 1e6
    return toks, round(usd, 6)


def _automation_run_open(schedule_id: int, run_key: Optional[int], chat_id: Optional[int],
                         trigger: str) -> int:
    now = int(time.time() * 1000)
    with _db() as conn:
        cur = conn.execute(
            "INSERT INTO automation_runs(schedule_id, run_key, chat_id, started_ts, status, trigger) "
            "VALUES (?,?,?,?,'running',?)",
            (int(schedule_id), int(run_key) if run_key else None,
             int(chat_id) if chat_id else None, now, str(trigger)[:32]),
        )
        return int(cur.lastrowid)


# Words that downgrade a COMPLETED run from green. Deliberately conservative — the
# explicit `STATUS:` marker is the real signal; this is the heuristic fallback for
# skills that just write prose. Red beats amber when both appear.
# Bare "red"/"down" were dropped: report bodies say "the campaign in the red",
# "revenue is down 5%", "shut it down" as ordinary domain prose, not automation
# health. Genuine health-red prose declares itself — the emoji, a STATUS: marker
# (handled above), or an explicit "red flag/alert". Keep the strong signal words.
_HEALTH_RED_RE = re.compile(
    r"🔴|\bred[ -](?:flag|alert)\b|\b(urgent|critical|escalat|failing|outage|breach|data ?loss)\b",
    re.IGNORECASE,
)
# Negation guard: "none urgent", "not critical", "nothing urgent" are the opposite
# of a red signal. Reject a keyword hit whose immediately-preceding word negates it.
_HEALTH_NEGATION_RE = re.compile(r"\b(?:no|none|not|nothing|never|zero)\W+$", re.IGNORECASE)
_HEALTH_FAILURE_RE = re.compile(
    r"\b(?:"
    r"(?:can(?:not|'t)|could(?:\s+not|n't))\s+(?:produce|complete|access|query|check|triage)\b"
    r"|did(?:\s+not|n't)\s+(?:actually\s+)?(?:deliver|query|triage|reach)\b"
    r"|never\s+(?:queried|triaged|reached|accessed)\b"
    r"|hit\s+(?:a\s+)?(?:[a-z0-9_` -]{0,40})?error\b"
    r"|invalid\s+session(?:[-\s]?id)?\b"
    r"|session[-\s]?id\s+error\b"
    r"|(?:failed\s+the\s+same\s+way|same\s+failure)\b"
    r"|(?:upstream|previous)\s+stage\b.{0,80}\b(?:failed|hit|error|did(?:\s+not|n't)\s+deliver)\b"
    r"|(?:inbox|email|imap|gmail|tool)\b.{0,80}\b(?:failed|failure|error|unavailable|did(?:\s+not|n't)\s+(?:run|return|deliver))\b"
    r"|died\b.{0,60}\b(?:tool|email|inbox|gmail|imap)\b"
    r")",
    re.IGNORECASE,
)
# Bare "watch"/"hold" were dropped: "hold the position", "watch the market",
# "on hold" are routine posture language in report bodies. Held/interrupted runs
# are already scored amber via final_status, not this keyword scan.
_HEALTH_AMBER_RE = re.compile(
    r"🟡|\b(amber|yellow|warning|watchlist|degraded|elevated|caution|at risk)\b",
    re.IGNORECASE,
)
_HEALTH_MARKER_RE = re.compile(r"\bSTATUS:\s*(green|amber|red)\b", re.IGNORECASE)


def _derive_run_health(completed: bool, final_status: str, text: str) -> tuple[str, str]:
    """Map a finished automation run to (health, headline).

    health ∈ {green, amber, red} — green = clean, amber = needs a glance, red =
    needs you. An interrupted/held/failed run is amber/red by definition. A
    completed run trusts an explicit `STATUS: <color>` marker the skill may emit,
    else falls back to a conservative keyword scan, else green.

    headline = the run's one-line delta for the resting pulse row: the first
    sentence of the final output (markdown stripped), capped. Empty input yields a
    safe default so the row never renders blank."""
    raw = (text or "").strip()
    # Headline: first sentence / line, markdown-stripped, capped ~90 chars.
    flat = re.sub(r"[*_`#>]+", "", raw).replace("\n", " ")
    flat = re.sub(r"\s+", " ", flat).strip()
    m = re.search(r"(.+?[.!?])(\s|$)", flat)
    headline = (m.group(1) if m else flat)[:90].strip()
    if not headline:
        headline = "Run completed." if completed else "Run interrupted."

    if not completed:
        if final_status == "failed":
            return "red", headline
        # held / stopped / interrupted — wants attention but not a hard failure.
        return "amber", headline

    marker = _HEALTH_MARKER_RE.search(raw)
    if marker:
        return marker.group(1).lower(), headline
    if _HEALTH_FAILURE_RE.search(raw):
        return "red", headline
    if _health_keyword_hit(_HEALTH_RED_RE, raw):
        return "red", headline
    if _health_keyword_hit(_HEALTH_AMBER_RE, raw):
        return "amber", headline
    return "green", headline


def _health_keyword_hit(rx: "re.Pattern[str]", text: str) -> bool:
    """True if `rx` matches somewhere the match is not directly negated. A hit whose
    immediately-preceding word is a negator ("none urgent", "no critical issues")
    is the opposite of a health signal, so it does not count."""
    for m in rx.finditer(text):
        if not _HEALTH_NEGATION_RE.search(text[:m.start()]):
            return True
    return False


# Tokens that fluctuate run-to-run without meaning a real change — a re-pull an
# hour later re-stamps the clock, the run counter, and the reporting window, but
# the underlying findings are the same. Stripping them BEFORE hashing is what lets
# the change-gate recognize "Run 7" as identical to "Run 1": only the substantive
# finding text survives into the digest.
_DIGEST_VOLATILE_RES = [
    re.compile(r"\brun\s*#?\s*\d+\b", re.IGNORECASE),                 # "Run 7", "run #7"
    re.compile(r"\d{4}-\d{2}-\d{2}[t ]\d{1,2}:\d{2}(:\d{2})?\b", re.IGNORECASE),  # ISO datetime
    re.compile(r"\b\d{4}-\d{2}-\d{2}\b"),                             # date
    re.compile(                                                       # long date: "Thursday, August 6, 2026"
        r"\b((mon|tues|wednes|thurs|fri|satur|sun)day,?\s+)?"
        r"(january|february|march|april|may|june|july|august|september|october|november|december)"
        r"\s+\d{1,2}(st|nd|rd|th)?,?(\s+\d{4})?\b",
        re.IGNORECASE),
    re.compile(r"~?\bday\s*\d+\b", re.IGNORECASE),                    # streak counter: "day 23", "~day 23"
    re.compile(r"\b\d{1,2}:\d{2}\s*(am|pm|ct|cst|cdt|et|est|edt|utc|z)?\b", re.IGNORECASE),  # clock
    re.compile(r"\b\d+\s*(triggers?|runs?|passes?|attempts?)\b", re.IGNORECASE),  # counters
    re.compile(r"\b\d+(\.\d+)?\s*%"),                                 # percentages
    re.compile(r"\b\d+(\.\d+)?\s*(ti?b|gi?b|mi?b|ki?b|bytes?)\b", re.IGNORECASE),  # sizes
    re.compile(r"\b\d+\s*(second|minute|hour|day|week|month)s?\s*ago\b", re.IGNORECASE),  # relative
    re.compile(r"\blast\s+\d+\s*h(ours?)?\b", re.IGNORECASE),         # "last 24h" window
]


def _findings_digest(text: str) -> str:
    """A stable fingerprint of a run's MATERIAL findings, insensitive to the
    volatile stamps (run number, timestamp, counters, reporting window) that a
    re-pull re-mints. Two runs that surface the same findings hash the same; a
    genuinely new/changed finding hashes differently.

    Returns '' for empty/near-empty output so the gate never fires on nothing —
    a run with no findings is never treated as "unchanged"."""
    raw = (text or "").strip().lower()
    if not raw:
        return ""
    for rx in _DIGEST_VOLATILE_RES:
        raw = rx.sub(" ", raw)
    raw = re.sub(r"[*_`#>\-•·|]+", " ", raw)          # markdown / bullet noise
    # Order-independent set of substantive lines: split on line and sentence
    # breaks, drop trivia, dedupe, sort. Reordered findings still match.
    parts = re.split(r"[\n.;!?]+", raw)
    lines = sorted({re.sub(r"\s+", " ", p).strip() for p in parts})
    lines = [ln for ln in lines if len(ln) >= 4]
    if not lines:
        return ""
    return hashlib.sha256("\n".join(lines).encode("utf-8")).hexdigest()


def _automation_budget_breach(conn, schedule_id: int, run_tokens: int) -> str:
    """Has this schedule blown a token budget? Returns a human reason, or ''.

    Two ceilings, because the observed failure mode is not one huge run. Per-run
    spend tops out around 4.4M tokens (p99 2.2M), but a single monitor accrued
    64M across 47 firings — the burn is cumulative, so a per-run cap alone would
    never have caught it. Defaults sit well above normal operation so this acts
    as a runaway breaker and not a throttle on working automations."""
    if AUTOMATION_MAX_RUN_TOKENS > 0 and run_tokens > AUTOMATION_MAX_RUN_TOKENS:
        return (f"single run used {run_tokens:,} tokens, over the "
                f"{AUTOMATION_MAX_RUN_TOKENS:,} per-run ceiling")
    if AUTOMATION_MAX_DAILY_TOKENS > 0:
        since = int(time.time() * 1000) - 86_400_000
        row = conn.execute(
            "SELECT COALESCE(SUM(cost_tokens),0) AS t FROM automation_runs "
            "WHERE schedule_id=? AND started_ts>=?",
            (int(schedule_id), since),
        ).fetchone()
        spent = int((row["t"] if row else 0) or 0)
        if spent > AUTOMATION_MAX_DAILY_TOKENS:
            return (f"used {spent:,} tokens in 24h, over the "
                    f"{AUTOMATION_MAX_DAILY_TOKENS:,} daily ceiling")
    return ""


def _hold_schedule_over_budget(conn, schedule_id: int, reason: str) -> None:
    """Park a schedule that blew its budget: disable it and record why, so it
    stops burning instead of repeating. Deliberately reversible — the user
    re-enables it from the automation panel once they've looked."""
    try:
        conn.execute(
            "UPDATE skill_schedules SET enabled=0, last_status=? WHERE id=?",
            (f"held: over budget — {reason}"[:200], int(schedule_id)),
        )
    except sqlite3.OperationalError:
        return
    logger.warning("automation: schedule %s held over budget — %s", schedule_id, reason)


def _schedule_change_gate(schedule_id: int) -> bool:
    """Is delta-only surfacing enabled for this schedule? Cheap point read; the
    finalize path calls it once per automation run."""
    try:
        with _db() as conn:
            row = conn.execute(
                "SELECT change_gate FROM skill_schedules WHERE id=?", (int(schedule_id),)
            ).fetchone()
        return bool(row and row["change_gate"])
    except Exception:
        logger.exception("change-gate lookup failed for schedule %s", schedule_id)
        return False


def _prev_completed_run_signature(schedule_id: int) -> "Optional[tuple[str, str, int]]":
    """(health, findings_digest, finished_ts) of the most recent COMPLETED run for
    this schedule that carries a digest — the baseline the current run is compared
    against. None when there is no prior digested run (so the first run of a gated
    automation always surfaces). Excludes the still-'running' current run by
    filtering to finished rows."""
    try:
        with _db() as conn:
            row = conn.execute(
                "SELECT health, findings_digest, finished_ts FROM automation_runs "
                "WHERE schedule_id=? AND status='ok' AND finished_ts IS NOT NULL "
                "AND findings_digest<>'' ORDER BY finished_ts DESC, id DESC LIMIT 1",
                (int(schedule_id),),
            ).fetchone()
    except Exception:
        logger.exception("prev-run signature lookup failed for schedule %s", schedule_id)
        return None
    if not row:
        return None
    return (row["health"] or "", row["findings_digest"] or "", int(row["finished_ts"] or 0))


def _delta_gate_no_change(prev_sig: "Optional[tuple[str, str, int]]",
                          health: str, digest: str) -> bool:
    """True when a completed run is a no-op vs the prior completed run — same
    findings fingerprint AND same health. `digest` must be non-empty; an empty
    digest means "no findings to compare" and never gates (so an empty/errored
    run is never mistaken for 'unchanged'). Pure so the finalize path's gate
    decision is unit-testable without driving a full turn."""
    if not digest or not prev_sig:
        return False
    return prev_sig[0] == (health or "") and prev_sig[1] == digest


def _automation_run_finish(schedule_id: int, run_key: Optional[int], *, status: str,
                           summary: str = "", turn_run_id: Optional[int] = None,
                           error: str = "", trigger: Optional[str] = None,
                           health: str = "", headline: str = "",
                           findings_digest: str = "", no_change: bool = False) -> None:
    """Finalize the open run for (schedule_id, run_key). No-op if none is open, so
    it is safe to call from the shared turn-completion path."""
    if not run_key:
        return
    now = int(time.time() * 1000)
    with _db() as conn:
        row = conn.execute(
            "SELECT id, started_ts, chat_id FROM automation_runs "
            "WHERE schedule_id=? AND run_key=? AND status='running' ORDER BY id DESC LIMIT 1",
            (int(schedule_id), int(run_key)),
        ).fetchone()
        if not row:
            return
        tokens, usd = _automation_run_cost(conn, row["chat_id"], row["started_ts"], now)
        sets = ["finished_ts=?", "status=?", "summary=?", "cost_tokens=?", "cost_usd=?"]
        vals: list = [now, str(status)[:24], str(summary)[:600], tokens, usd]
        if turn_run_id is not None:
            sets.append("turn_run_id=?"); vals.append(int(turn_run_id))
        if error:
            sets.append("error=?"); vals.append(str(error)[:600])
        if trigger is not None:
            sets.append("trigger=?"); vals.append(str(trigger)[:32])
        if health:
            sets.append("health=?"); vals.append(str(health)[:16])
        if headline:
            sets.append("headline=?"); vals.append(str(headline)[:120])
        if findings_digest:
            sets.append("findings_digest=?"); vals.append(str(findings_digest)[:64])
        # no_change is a definitive per-run verdict (0 or 1), always written.
        sets.append("no_change=?"); vals.append(1 if no_change else 0)
        vals.append(row["id"])
        conn.execute(f"UPDATE automation_runs SET {', '.join(sets)} WHERE id=?", vals)
        # Cost circuit breaker. Checked after the row is written so the run that
        # blew the budget is itself counted, then the schedule is parked so the
        # next firing doesn't repeat it.
        try:
            breach = _automation_budget_breach(conn, int(schedule_id), int(tokens))
            if breach:
                _hold_schedule_over_budget(conn, int(schedule_id), breach)
        except Exception:
            logger.exception("automation budget check failed for schedule %s", schedule_id)


def _automation_runs_for(schedule_id: int, limit: int = 30) -> list[dict]:
    with _db() as conn:
        rows = conn.execute(
            "SELECT * FROM automation_runs WHERE schedule_id=? "
            "ORDER BY started_ts DESC, id DESC LIMIT ?",
            (int(schedule_id), int(limit)),
        ).fetchall()
    cols = rows[0].keys() if rows else []
    def _g(r, k, default=None):
        return r[k] if k in cols else default
    return [{
        "id": r["id"], "status": r["status"], "trigger": r["trigger"],
        "run_key": _g(r, "run_key"),
        "started_ts": r["started_ts"], "finished_ts": r["finished_ts"],
        "summary": r["summary"], "cost_tokens": r["cost_tokens"], "cost_usd": r["cost_usd"],
        "chat_id": r["chat_id"], "turn_run_id": r["turn_run_id"], "error": r["error"],
        "health": _g(r, "health", "") or "", "headline": _g(r, "headline", "") or "",
        "fix_job_id": _g(r, "fix_job_id"), "fix_agent": _g(r, "fix_agent", "") or "",
        "fix_state": _g(r, "fix_state", "") or "",
        "no_change": bool(_g(r, "no_change", 0)),
    } for r in rows]


def _automation_outputs(series_chat_id: Optional[int], limit: int = 40) -> list[dict]:
    """The reports/PDFs/images/HTML an automation produced = the attachments + the
    canvas artifacts on its series chat, newest first. Pure read over the existing
    stores (attachments_meta + thread artifacts) — no new capture."""
    if not series_chat_id:
        return []
    cid = int(series_chat_id)
    out: list[dict] = []
    try:
        for a in _list_attachment_meta(cid):
            out.append({
                "kind": "attachment", "id": a.get("id"),
                "name": a.get("name") or "file", "mime": a.get("mime") or "",
                "size": int(a.get("size") or 0), "ts": int(a.get("ts") or 0),
                "url": a.get("url"), "by": a.get("source_name") or "",
            })
    except Exception:
        logger.exception("automation outputs: attachments failed for chat %s", cid)
    try:
        for msg in _load_thread(cid):
            mts = int(msg.get("ts") or 0)
            for art in (msg.get("artifacts") or []):
                if isinstance(art, dict) and art.get("id"):
                    out.append({
                        "kind": "artifact", "id": art.get("id"),
                        "name": art.get("title") or art.get("kind") or "artifact",
                        "mime": art.get("mime") or "", "size": 0,
                        "ts": int(art.get("ts") or mts),
                        "url": art.get("external_url") or f"/artifacts/{cid}/{art.get('id')}",
                        "by": AGENTS_BY_ID.get(art.get("agent_id") or "", {}).get(
                            "name", art.get("agent_id") or ""),
                        "art_kind": art.get("kind") or "",
                    })
    except Exception:
        logger.exception("automation outputs: artifacts failed for chat %s", cid)
    out.sort(key=lambda o: o.get("ts") or 0, reverse=True)
    return out[:limit]


def _mission_control_enabled() -> bool:
    """Feature flag for the new Automations surface. Off → the chat list still
    shows series chats and nothing changes; on → they move into Mission Control."""
    return _get_setting("mission_control", "0").strip() == "1"


def _automation_owner_agent(skill: dict) -> str:
    """The agent that 'owns' an automation = the first real agent in its room.
    Used to put a face on each card. Best-effort; '' if undeterminable."""
    for step in (skill.get("steps") or []):
        if isinstance(step, dict):
            aid = step.get("agent") or step.get("agent_id") or step.get("id")
            if aid and aid in AGENTS_BY_ID:
                return aid
        elif isinstance(step, str) and step in AGENTS_BY_ID:
            return step
    return ""


def _automation_card(sched: dict) -> dict:
    """Assemble the Mission Control card for one schedule: schedule + skill +
    archetype + next/last run + recent run health + effective escalation policy."""
    skill = _get_skill(int(sched["skill_id"])) or {}
    arch = sched.get("archetype") or (_infer_archetype(skill) if skill else _ARCH_FALLBACK)
    try:
        gated = bool(skill) and _scan_skill(skill).get("tier") == "gated"
    except Exception:
        gated = False
    runs = _automation_runs_for(int(sched["id"]), limit=30)
    try:
        with _db() as conn:
            pend = conn.execute(
                "SELECT COUNT(*) AS n FROM automation_items WHERE schedule_id=? AND state='pending'",
                (int(sched["id"]),),
            ).fetchone()["n"]
    except Exception:
        pend = 0
    # Cheap output badge: count attachments on the series chat (the common case —
    # PDFs/images/HTML files). Canvas-artifact outputs also show in the detail
    # Outputs section; this count just drives the card indicator.
    try:
        scid = sched.get("series_chat_id")
        with _db() as conn:
            ocount = conn.execute(
                "SELECT COUNT(*) AS n FROM attachments_meta WHERE chat_id=?",
                (int(scid),),
            ).fetchone()["n"] if scid else 0
    except Exception:
        ocount = 0
    return {
        "id": sched["id"],
        "name": sched.get("name") or skill.get("name") or "Automation",
        "skill_id": sched.get("skill_id"),
        "skill_name": skill.get("name", ""),
        "archetype": arch,
        "owner_agent": _automation_owner_agent(skill),
        "enabled": sched.get("enabled"),
        "cadence": _cadence_label(sched),
        "trigger_type": sched.get("trigger_type"),
        "next_run_ts": sched.get("next_run_ts"),
        "last_run_ts": sched.get("last_run_ts"),
        "last_status": sched.get("last_status"),
        "change_gate": sched.get("change_gate"),
        "hold_gated": bool(sched.get("hold_gated")),
        "series_chat_id": sched.get("series_chat_id"),
        "pending_items": int(pend or 0),
        "output_count": int(ocount or 0),
        "gated": gated,
        "notify": _effective_notify(sched, gated=gated),
        "notify_overrides": {k: v for k, v in (sched.get("notify") or {}).items()
                             if not k.startswith("_")},
        "health": [r["status"] for r in runs],
        "last_run": runs[0] if runs else None,
    }


async def _run_schedule(sched: dict, source: str = "schedule",
                        bypass_hold: bool = False) -> dict:
    skill = _get_skill(int(sched["skill_id"]))
    if not skill:
        return {"ok": False, "error": "skill_gone"}
    if not _schedule_skill_matches_owner(skill, sched.get("owner_user_id")):
        return {"ok": False, "error": "skill_owner_mismatch"}
    if not _schedule_target_is_valid(
        sched.get("target") or "new_chat", sched.get("owner_user_id")
    ):
        return {"ok": False, "error": "target_not_found"}
    skill_mode = _normalize_chat_mode(skill.get("mode") or "pipeline")
    # Pre-execution approval gate (opt-in per automation). Before any chat/run
    # record is created, an unattended run the scan rates `gated` PARKS for one-tap
    # approval instead of firing. bypass_hold=True is the approval re-entry path.
    if not bypass_hold and source != "manual run" and sched.get("hold_gated"):
        if _scan_skill(skill).get("tier") == "gated":
            await _hold_gated_run(sched, skill, source, _scan_skill(skill))
            return {"ok": True, "held": True}
    # A scheduled/event run is unattended (a "manual run" from the UI is not — the
    # user is right there). Mark it so a stage that can't finish auto-skips instead
    # of parking a hold nobody will resolve. The detached turn task captures this at
    # create_task() time inside apply_skill.
    unattended_token = _UNATTENDED.set(source != "manual run")
    target = sched.get("target") or "new_chat"
    recurring = sched.get("trigger_type") in _RECURRING_TRIGGERS
    series_token = None
    # FREE-WILL never reuses a chat across firings — every firing is its own
    # fresh episode (see _run_freewill_turn's docstring: "pull up Tuesday's
    # session" has to mean exactly one chat, not a scroll through a growing
    # log) — so it never takes the usual series-chat-reuse path even when
    # recurring. It's still tagged + tracked under the schedule's series key
    # just like any other recurring automation (Mission Control groups by that
    # key, not by chat id), so the two booleans below cover the SAME overall
    # condition the original code used (`target == "new_chat" and recurring`)
    # — only which chat gets created differs.
    reuse_chat = target == "new_chat" and recurring and skill_mode != "freewill"
    fresh_freewill_episode = target == "new_chat" and recurring and skill_mode == "freewill"
    if reuse_chat:
        # Recurring run → one reused "series chat" + tag every message it writes so
        # the runs collapse into a single digest card (and the pager edits in place).
        cid = await _ensure_series_chat(sched, skill)
        # Start each firing from a clean agent session. The series chat is reused
        # forever, and context_id is what the bridge hands its CLI to resume the
        # PREVIOUS session — so without this the CLI's context (history plus every
        # browser scrape and data dump its tools pulled) accrues across every
        # firing. One monitor reached ~120k tokens of input per message that way,
        # against ~600 for a comparably sized ordinary chat. Each run re-sends the
        # skill prompt and cross-run continuity already comes from the stored
        # findings digest, not from CLI memory, so nothing is lost by resetting.
        if AUTOMATION_FRESH_CONTEXT:
            _reset_contexts_for_run(cid)
    elif target == "new_chat" or not str(target).isdigit():
        # One-off / manual / event run, OR a recurring FREE-WILL firing → a fresh
        # chat every time.
        title = f"🎙️ {skill['name']}" if skill_mode == "freewill" else f"⏰ {skill['name']}"
        cid = _create_chat_record(
            title, mode=skill_mode, owner_user_id=sched.get("owner_user_id"),
        )
        await broadcast({
            "type": "chat_meta", "chat_id": cid,
            "title": CHAT_INDEX["chats"][str(cid)]["title"],
        }, global_event=True)
    else:
        cid = int(target)
    if reuse_chat or fresh_freewill_episode:
        run_key = int(time.time() * 1000)
        series_token = _SERIES_CTX.set({
            "key": f"sched:{int(sched['id'])}",
            "schedule_id": int(sched["id"]),
            "label": skill["name"],
            "cadence": _cadence_label(sched),
            "run_id": run_key,
        })
        # Open the discrete run record now; the shared turn-completion path
        # (_route_turn_then_notify) finalizes it once the turn actually ends.
        try:
            _automation_run_open(int(sched["id"]), run_key, cid,
                                 "manual" if source == "manual run" else "scheduled")
        except Exception:
            logger.exception("automation run open failed for schedule %s", sched.get("id"))
    try:
        # FREE-WILL skips this — see apply_skill's matching guard: no out-of-
        # character line belongs anywhere near the top of an unwatched hangout.
        if skill_mode != "freewill":
            await _route_system_note(cid, f"⏰ Triggered by {source}: skill “{skill['name']}”.")
        # Capped-and-logged: an unattended `gated` run fires a ping the moment it
        # starts (a manual "Run now" is skipped — the user is already here).
        _sched_scan = _scan_skill(skill)
        if source != "manual run" and _sched_scan.get("tier") == "gated":
            await _ping_gated_run(cid, skill, source, _sched_scan,
                                  sched.get("owner_user_id"))
        return await apply_skill(
            skill, cid, sched.get("inputs") or {}, actor=_chat_principal_name(cid),
            notify_event="automation_done", push=True,
        )
    finally:
        # The fire-and-forget turn task already captured a copy of this context at
        # create_task() time, so resetting here only clears OUR frame — the run's
        # own messages stay tagged. Prevents the next scheduler tick from inheriting.
        if series_token is not None:
            _SERIES_CTX.reset(series_token)
        _UNATTENDED.reset(unattended_token)


# ----- Proactive meeting prep (calendar-driven) ----------------------------
# A background loop that auto-fires the Meeting Prep skill a bit before each
# calendar meeting, so the brief is waiting when you need it. Dormant unless a
# calendar is configured. Env-tunable; CALENDAR_PREP_ENABLED=0 to disable.
CALENDAR_PREP_TICK_S = float(os.environ.get("CALENDAR_PREP_TICK_S", "300"))
CALENDAR_PREP_LEAD_MIN = float(os.environ.get("CALENDAR_PREP_LEAD_MIN", "30"))
CALENDAR_PREP_ENABLED = os.environ.get("CALENDAR_PREP_ENABLED", "1").strip() not in ("0", "false", "no")
_prepped_meetings: "set[str]" = set()


def _meeting_key(ev: dict) -> str:
    return f"{ev.get('start', '')}|{(ev.get('title') or '')[:60]}"


def _meetings_due_for_prep(events: list, now: datetime, lead_min: float,
                           tick_min: float, already: set) -> list:
    """Meetings whose start is ~lead_min away (within one tick) and not yet prepped."""
    due = []
    for ev in events:
        try:
            start = datetime.fromisoformat(ev["start"])
        except (KeyError, ValueError, TypeError):
            continue
        mins = (start - now).total_seconds() / 60.0
        if lead_min - tick_min <= mins <= lead_min and _meeting_key(ev) not in already:
            due.append(ev)
    return due


async def _fire_meeting_prep(skill: dict, ev: dict) -> None:
    owner = skill.get("owner_user_id")
    title = f"⏰ Prep: {(ev.get('title') or 'meeting')[:40]}"
    cid = _create_chat_record(title, mode=_normalize_chat_mode(skill.get("mode") or "solo"),
                              owner_user_id=owner)
    try:
        await broadcast({"type": "chat_meta", "chat_id": cid,
                         "title": CHAT_INDEX["chats"][str(cid)]["title"]}, global_event=True)
    except Exception:
        pass
    when = f'the meeting "{ev.get("title") or "meeting"}" starting {ev.get("start")}'
    await apply_skill(skill, cid, {"when": when}, actor="Calendar",
                      notify_event="automation_done", push=True)


async def _calendar_prep_tick() -> None:
    if not (CALENDAR_PREP_ENABLED and calendar_ics.configured()):
        return
    if _automation_paused():  # honor the global kill switch
        return
    try:
        res = await calendar_ics.upcoming(days=1, limit=20)
    except calendar_ics.CalendarError:
        return
    skill = _get_skill("meeting-prep")
    if not skill:
        return
    now = datetime.now(calendar_ics._UTC)
    due = _meetings_due_for_prep(res.get("events", []), now, CALENDAR_PREP_LEAD_MIN,
                                 CALENDAR_PREP_TICK_S / 60.0, _prepped_meetings)
    if len(_prepped_meetings) > 1000:  # bound the in-memory dedup set
        _prepped_meetings.clear()
    for ev in due:
        _prepped_meetings.add(_meeting_key(ev))
        try:
            await _fire_meeting_prep(skill, ev)
        except Exception:
            logger.exception("meeting prep fire failed for %s", _meeting_key(ev))


async def _migrate_calendar_primary():
    """Fold a legacy single CALENDAR_ICS_URL into the multi-calendar store once,
    so the Settings list becomes the single source of truth. Idempotent, cheap,
    best-effort — never blocks boot."""
    try:
        if calendar_ics.migrate_primary_into_store(delete_env=_delete_shared_env_secret):
            logger.info("calendar: migrated legacy CALENDAR_ICS_URL into the calendars store")
    except Exception:
        logger.exception("calendar primary migration failed")


async def _start_calendar_prep_loop():
    """Auto-fire Meeting Prep before calendar meetings. Dormant until a calendar is
    configured; delivery uses the same push path (and is held during a meeting)."""
    async def _loop():
        await asyncio.sleep(12)  # settle after boot
        while True:
            try:
                await _calendar_prep_tick()
            except Exception:
                logger.exception("calendar prep loop error")
            await asyncio.sleep(CALENDAR_PREP_TICK_S)
    asyncio.create_task(_loop())


# ----- Daily Brief episode (calendar-driven, voiced) -----------------------
# Once each morning, build a short spoken brief of the day from the calendar,
# post it as agent turns, and (best-effort) voice it via the episode engine.
# Dormant until a calendar is configured. Env: CALENDAR_BRIEF_HOUR (local hour),
# CALENDAR_BRIEF_ENABLED=0 to disable.
CALENDAR_BRIEF_ENABLED = os.environ.get("CALENDAR_BRIEF_ENABLED", "1").strip() not in ("0", "false", "no")
CALENDAR_BRIEF_HOUR = int(os.environ.get("CALENDAR_BRIEF_HOUR", "7"))


def _fmt_local_time(iso: str) -> str:
    try:
        return datetime.fromisoformat(iso).astimezone().strftime("%-I:%M %p")
    except Exception:
        return iso


async def _daily_brief_segments(owner_user_id: Optional[int] = None) -> list:
    """Spoken-style brief segments for today, from the calendar. Deterministic."""
    try:
        res = await calendar_ics.upcoming(days=1, limit=12)
        events = res.get("events", [])
    except calendar_ics.CalendarError:
        events = []
    if not events:
        body = "Your calendar is clear today — no meetings on the books. A good day to get ahead."
    else:
        n = len(events)
        parts = [f"{e.get('title') or 'an event'} at {_fmt_local_time(e.get('start', ''))}"
                 for e in events[:6]]
        body = f"You have {n} thing{'s' if n != 1 else ''} today: " + "; ".join(parts) + "."
    segs = [
        f"Good morning. Here's your day. {body}",
        "That's the shape of it — I'll have a prep brief ready before each meeting.",
    ]
    if owner_user_id is not None:
        try:
            with _db() as conn:
                lessons = coding_jobs.recent_lessons(conn, owner_user_id, limit=1)
            if lessons:
                segs.append("From last night's crew audit: " + lessons[0][:400])
        except Exception:
            pass
    return segs


async def _run_daily_brief() -> Optional[int]:
    skill = _get_skill("meeting-prep")
    owner = skill.get("owner_user_id") if skill else None
    segs = await _daily_brief_segments(owner)
    lead = AGENTS_BY_ID.get(LEAD_AGENT_ID) or (AGENTS[0] if AGENTS else None)
    if not lead:
        return None
    title = f"🎙️ Daily Brief — {datetime.now().strftime('%a %b %-d')}"
    cid = _create_chat_record(title, mode="solo", owner_user_id=owner)
    try:
        await broadcast({"type": "chat_meta", "chat_id": cid,
                         "title": CHAT_INDEX["chats"][str(cid)]["title"]}, global_event=True)
    except Exception:
        pass
    for seg in segs:
        append_thread(cid, "agent", lead["id"], lead.get("name", "Lead"), seg)
    try:
        # Use the same tracked lifecycle as a user-requested episode so Trash
        # can cancel/wait for the long synth pipeline before hiding the chat.
        episode_task = _spawn_chat_task(cid, _build_episode(cid))
        if episode_task is not None:
            await episode_task  # best-effort — Kokoro may be down; text brief still stands
    except Exception:
        logger.exception("daily brief episode build failed")
    try:
        await _emit_notification(
            cid, event="daily_brief", title="Your Daily Brief is ready",
            body=segs[0][:200], severity="info", agent_id=lead["id"], push=True,
            owner_user_id=owner,
        )
    except Exception:
        logger.exception("daily brief notify failed")
    return cid


def _nightly_chat_facts(owner_user_id: int, since_ts: int) -> dict:
    """How automatic chat routing held up since since_ts."""
    try:
        with _db() as conn:
            # Scoped to THIS owner's chats. The owner_user_id argument used to be
            # accepted and then ignored, so on a multi-user install every tenant's
            # nightly audit counted everyone's routing and drew its "lesson" from
            # conversations that were not theirs.
            rows = conn.execute(
                "SELECT r.status, r.decision_json, r.corrected_to "
                "FROM routing_outcomes r JOIN chats c ON c.id=r.chat_id "
                "WHERE r.ts>=? AND c.owner_user_id=? AND c.deleted_ts IS NULL "
                "AND r.source IN ('auto','clarify') "
                "AND r.status IN ('applied','overridden') "
                "ORDER BY r.id DESC LIMIT 80",
                (int(since_ts), int(owner_user_id)),
            ).fetchall()
    except Exception:
        return {"applied": 0, "overridden": 0, "has_findings": False}
    applied = overridden = 0
    for row in rows:
        if row["status"] == "overridden":
            overridden += 1
        else:
            applied += 1
    return {
        "applied": applied,
        "overridden": overridden,
        "has_findings": bool(overridden or applied),
    }


def _deterministic_nightly_lesson(build: dict, chat: dict) -> str:
    bits = []
    for aid, counts in (build.get("verify_by_agent") or {}).items():
        if counts.get("failed"):
            bits.append(
                f"@{aid} failed verify {counts['failed']}x — prefer a tighter task or a swap sooner"
            )
        elif counts.get("passed"):
            bits.append(f"@{aid} verified {counts['passed']}x — keep that staffing")
    open_jobs = build.get("open_jobs") or []
    if open_jobs:
        bits.append(
            f"{len(open_jobs)} build(s) still open — unblock or cancel before starting another"
        )
    if chat.get("overridden"):
        bits.append(
            f"users overrode auto-routing {chat['overridden']}x — read those corrections before the next Auto send"
        )
    if not bits:
        return ""
    return "; ".join(bits)[:800]


async def _run_orchestrator_nightly_audit() -> None:
    """Once a night: look at builds and chat routing, write lessons, speak only if needed."""
    since_ts = int(time.time() * 1000) - 26 * 3600 * 1000
    try:
        with _db() as conn:
            owners = {
                int(r["owner_user_id"])
                for r in conn.execute(
                    "SELECT DISTINCT owner_user_id FROM coding_jobs "
                    "WHERE owner_user_id IS NOT NULL AND updated_ts>=?",
                    (since_ts,),
                ).fetchall()
            }
            for r in conn.execute(
                "SELECT DISTINCT c.owner_user_id AS owner_user_id "
                "FROM routing_outcomes r JOIN chats c ON c.id=r.chat_id "
                "WHERE c.owner_user_id IS NOT NULL AND c.deleted_ts IS NULL "
                "AND r.ts>=?",
                (since_ts,),
            ).fetchall():
                owners.add(int(r["owner_user_id"]))
            owners = list(owners)
    except Exception:
        logger.exception("nightly audit: could not list owners")
        return
    orch = AGENTS_BY_ID.get(_effective_concierge_agent_id()) or AGENTS_BY_ID.get(LEAD_AGENT_ID)
    for owner in owners:
        try:
            with _db() as conn:
                build = coding_jobs.nightly_facts(conn, owner, since_ts=since_ts)
            chat = _nightly_chat_facts(owner, since_ts)
            if not build.get("has_findings") and not chat.get("overridden"):
                continue
            lesson = _deterministic_nightly_lesson(build, chat)
            if orch:
                prompt = (
                    "You are the orchestrator doing a nightly crew audit. "
                    "Write 2-4 short lessons so tomorrow's builds and Auto chats "
                    "are tasked better, run faster, and waste fewer tokens. "
                    "No preamble. No fluff. Facts:\n"
                    f"BUILDS: {json.dumps(build)[:1500]}\n"
                    f"CHAT ROUTING: {json.dumps(chat)}\n"
                )
                try:
                    raw = await _concierge_call(orch, prompt, min(CONCIERGE_TIMEOUT_S, 25))
                    if raw and len(raw.strip()) > 20:
                        lesson = raw.strip()[:800]
                except Exception:
                    logger.info("nightly audit: orchestrator write-up failed, using facts")
            if not lesson:
                continue
            with _db() as conn:
                coding_jobs.save_lesson(conn, owner, lesson, kind="nightly", facts={
                    "build": build, "chat": chat,
                })
            title = f"Nightly crew audit — {datetime.now().strftime('%a %b %-d')}"
            cid = _create_chat_record(title, mode="solo", owner_user_id=owner)
            name = (orch or {}).get("name") or "Orchestrator"
            oid = (orch or {}).get("id")
            body = (
                "Last night's look at the crew.\n\n"
                f"{lesson}\n\n"
                "These lessons ride into tomorrow's Auto routing and every new build task."
            )
            append_thread(cid, "agent", oid, name, body)
            await broadcast({
                "type": "chat_meta", "chat_id": cid,
                "title": CHAT_INDEX["chats"][str(cid)]["title"],
                "owner_user_id": owner,
            }, global_event=True)
            try:
                await _emit_notification(
                    cid, event="daily_brief", title="Nightly crew audit is ready",
                    body=lesson[:200], severity="info", agent_id=oid, push=True,
                    owner_user_id=owner,
                )
            except Exception:
                logger.exception("nightly audit notify failed for owner %s", owner)
        except Exception:
            logger.exception("nightly audit failed for owner %s", owner)


async def _start_orchestrator_audit_loop():
    """Fire one crew/chat audit per night at ORCHESTRATOR_AUDIT_HOUR (local, default 21)."""
    hour = int(os.environ.get("ORCHESTRATOR_AUDIT_HOUR", "21"))

    async def _loop():
        await asyncio.sleep(25)
        while True:
            try:
                if not _automation_paused():
                    nowl = datetime.now()
                    today = nowl.strftime("%Y-%m-%d")
                    if nowl.hour == hour and _get_setting("orchestrator_audit_last_date", "") != today:
                        _set_setting("orchestrator_audit_last_date", today)
                        await _run_orchestrator_nightly_audit()
            except Exception:
                logger.exception("orchestrator audit loop error")
            await asyncio.sleep(300)
    asyncio.create_task(_loop())


async def _start_daily_brief_loop():
    """Fire a morning Daily Brief once per day at CALENDAR_BRIEF_HOUR (local).
    Dormant until a calendar is configured."""
    async def _loop():
        await asyncio.sleep(20)
        while True:
            try:
                if (CALENDAR_BRIEF_ENABLED and calendar_ics.configured()
                        and not _automation_paused()):
                    nowl = datetime.now()
                    today = nowl.strftime("%Y-%m-%d")
                    # Durable dedup — persisted so a restart within the brief hour
                    # can't re-fire a duplicate brief/episode/push.
                    if nowl.hour == CALENDAR_BRIEF_HOUR and _get_setting("daily_brief_last_date", "") != today:
                        _set_setting("daily_brief_last_date", today)
                        await _run_daily_brief()
            except Exception:
                logger.exception("daily brief loop error")
            await asyncio.sleep(300)
    asyncio.create_task(_loop())


async def _run_decisions_hygiene() -> None:
    """For each owner with active decisions, build the hygiene report and — only
    when it has findings — drop it into a fresh chat and ring that owner's bell.
    A clean ledger produces nothing, by design: this automation exists to keep the
    ledger sharp, not to generate monthly noise."""
    try:
        with _db() as conn:
            owners = [r["owner_user_id"] for r in conn.execute(
                "SELECT DISTINCT owner_user_id FROM team_decisions WHERE superseded=0"
            ).fetchall()]
    except Exception:
        logger.exception("decisions hygiene: could not enumerate owners")
        return
    lead = AGENTS_BY_ID.get(LEAD_AGENT_ID) or (AGENTS[0] if AGENTS else None)
    for owner in owners:
        try:
            report = _decisions_hygiene_report(owner)
        except Exception:
            logger.exception("decisions hygiene report failed for owner %s", owner)
            continue
        if not report.get("has_findings"):
            continue
        cid = _create_chat_record("🧹 Team Memory — monthly review", mode="solo",
                                  owner_user_id=owner)
        try:
            await broadcast({"type": "chat_meta", "chat_id": cid,
                             "title": CHAT_INDEX["chats"][str(cid)]["title"]}, global_event=True)
        except Exception:
            pass
        await _route_system_note(cid, report["digest"])
        try:
            await _emit_notification(
                cid, event="decisions_hygiene",
                title="Your Team Memory has items to review",
                body=report["summary"][:200], severity="info",
                agent_id=(lead or {}).get("id"), push=False, owner_user_id=owner,
            )
        except Exception:
            logger.exception("decisions hygiene notify failed")


async def _start_decisions_hygiene_loop():
    """Once per calendar month, post a decisions-log hygiene review (stale /
    unreviewed / near-duplicate / near-cap) so the ledger stays sharp instead of
    quietly rotting into a swamp. Silent when the ledger is clean. Honors the
    automation kill switch; a durable month marker means a restart can't double-
    fire within the same month."""
    async def _loop():
        await asyncio.sleep(45)  # let boot settle before any monthly sweep
        while True:
            try:
                if not _automation_paused():
                    cur_month = datetime.now().strftime("%Y-%m")
                    if _get_setting("decisions_hygiene_last_month", "") != cur_month:
                        # Stamp BEFORE running so a crash mid-run can't re-fire all month.
                        _set_setting("decisions_hygiene_last_month", cur_month)
                        await _run_decisions_hygiene()
            except Exception:
                logger.exception("decisions hygiene loop error")
            await asyncio.sleep(3600)
    asyncio.create_task(_loop())


async def _start_skills_scheduler_on_startup():
    """In-process scheduler: fire due skill schedules. launchd KeepAlive keeps the
    app (and thus this loop) alive; mirrors the capability-warm startup task."""
    async def _loop():
        await asyncio.sleep(8)  # let bridges + capability warm settle first
        while True:
            try:
                # Close runs whose driver stopped reporting. Runs even while the
                # kill switch is on: a hung run is stale regardless, and without
                # this it stays 'running' (and "live" in the panel) until the next
                # process restart. Indexed by (status, started_ts), so a tick that
                # finds nothing is nearly free.
                try:
                    await asyncio.to_thread(_reap_stale_automation_runs)
                except Exception:
                    logger.exception("stale automation run reap tick failed")
                if _automation_paused():
                    # Kill switch on: leave due schedules untouched (no fire, no
                    # status churn, no next_run advance) so they resume cleanly.
                    await asyncio.sleep(SKILL_SCHEDULER_TICK_S)
                    continue
                now = int(time.time() * 1000)
                with _db() as conn:
                    due = conn.execute(
                        "SELECT * FROM skill_schedules WHERE enabled=1 AND next_run_ts IS NOT NULL "
                        "AND next_run_ts<=? ORDER BY next_run_ts LIMIT 5", (now,)
                    ).fetchall()
                for row in due:
                    sched = _schedule_from_row(row)
                    try:
                        # Quiet hours (User Profile platform): don't run a scheduled
                        # automation while its owner is in a quiet window (e.g.
                        # Shabbos) — skip this occurrence and advance to the next, so
                        # the app neither runs nor pings. The profile's promise is
                        # enforced in code, not left to the agent.
                        _qh, _qlabel = _profile_quiet_now(sched.get("owner_user_id"))
                        if _qh:
                            logger.info("scheduler: skipping schedule %s during quiet hours (%s)",
                                        sched.get("id"), _qlabel)
                            _mark_schedule_ran(sched["id"], f"skipped: quiet hours ({_qlabel})", advance=True)
                            continue
                        res = await _run_schedule(sched)
                        _mark_schedule_ran(sched["id"], "ok" if res.get("ok") else (res.get("error") or "error"), advance=True)
                    except Exception as exc:
                        logger.exception("scheduled skill run failed")
                        _mark_schedule_ran(sched["id"], f"error: {exc}", advance=True)
            except Exception:
                logger.exception("skills scheduler tick failed")
            await asyncio.sleep(SKILL_SCHEDULER_TICK_S)

    asyncio.create_task(_loop())


