def _schedule_access_error(request: Request, row) -> Optional[JSONResponse]:
    """Owner gate for a single-schedule mutation/detail route. `row` is a fetched
    skill_schedules row (or None). Returns a 404 JSONResponse when the caller may
    not act on it (non-owner of an owned row and not admin), else None.
    NULL-owner rows are legacy admin data, never shared tenant data."""
    if not row:
        return JSONResponse({"ok": False, "error": "not found"}, status_code=404)
    try:
        owner = row["owner_user_id"]
    except (KeyError, IndexError):
        owner = None
    user = _current_user(request)
    if _is_admin_user(user):
        return None
    if owner is None:
        return JSONResponse({"ok": False, "error": "not found"}, status_code=404)
    if user and int(owner) == int(user["id"]):
        return None
    return JSONResponse({"ok": False, "error": "not found"}, status_code=404)


