@app.post("/api/schedules/{schid}/clear")
async def api_clear_schedule_runs(schid: int, request: Request):
    """Empty a recurring automation's series chat — the "delete the whole bucket"
    action on the digest card. Wipes the accumulated run messages (keeping the chat
    and the schedule) and resets the Telegram message id so the next run starts a
    fresh daily pager message."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    with _db() as conn:
        row = conn.execute(
            "SELECT series_chat_id, owner_user_id FROM skill_schedules WHERE id=?", (int(schid),)
        ).fetchone()
        denied = _schedule_access_error(request, row)
        if denied:
            return denied
        if not row["series_chat_id"]:
            return JSONResponse({"ok": False, "error": "no series chat"}, status_code=404)
        cid = int(row["series_chat_id"])
        conn.execute("DELETE FROM messages WHERE chat_id=?", (cid,))
        conn.execute(
            "UPDATE skill_schedules SET tg_message_id=NULL, tg_msg_day='' WHERE id=?", (int(schid),)
        )
    # Drop the JSON disaster-recovery mirror too so a reload can't resurrect runs.
    try:
        _get_thread_path(cid).write_text("")  # empty JSONL mirror
    except Exception:
        logger.exception("clear series: failed to reset thread mirror for chat %s", cid)
    return JSONResponse({"ok": True, "chat_id": cid})


