def _desktop_agents_for_chat(cid: Optional[int]) -> list[dict]:
    """The agents an automation finding can be handed to for an autonomous fix:
    chat-allowed agents that actually have a desktop runtime to run headless in
    (@claude/@codex/@antigravity today). Mirrors the gate /pass_to_desktop
    enforces, so the dropdown can only offer agents the dispatch will accept."""
    if not cid:
        return []
    out = []
    for aid in _allowed_agent_ids_for_chat(int(cid)):
        if aid not in AGENTS_BY_ID:
            continue
        cap = _agent_capabilities(aid, int(cid))
        if (cap.get("ui") or {}).get("surface") == "desktop":
            out.append({"id": aid, "name": AGENTS_BY_ID[aid].get("name", aid)})
    out.sort(key=lambda a: a["name"].lower())
    return out


def _arun_row(schid: int, run_key: int) -> Optional[dict]:
    """Fetch one automation run by (schedule, run_key) as a plain dict, or None."""
    with _db() as conn:
        r = conn.execute(
            "SELECT * FROM automation_runs WHERE schedule_id=? AND run_key=? "
            "ORDER BY id DESC LIMIT 1",
            (int(schid), int(run_key)),
        ).fetchone()
    return dict(r) if r else None


def _run_scoped_briefing(cid: int, run_key: int) -> str:
    """Compact JUST the failing run (its messages in the series chat tagged with
    this run_key) into a briefing — not the whole hourly series chat, which would
    bury the finding under dozens of unrelated runs. Falls back to the run's
    stored headline/summary when the messages can't be loaded."""
    try:
        msgs = [
            m for m in _load_thread(int(cid))
            if ((m.get("metadata") or {}).get("series") or {}).get("run_id") == run_key
            and m.get("role") not in ("user",)
        ]
    except Exception:
        msgs = []
    lines = []
    for m in msgs:
        who = m.get("name") or m.get("role") or "agent"
        txt = re.sub(r"\s+", " ", (m.get("text") or "")).strip()
        if txt:
            lines.append(f"{who}: {txt[:700]}")
    return "\n".join(lines)[:6000]


_DISK_FINDING_RE = re.compile(
    r"\b(disk|storage|free space|low.?space|out of space|volume.*full|"
    r"\d{2,3}\s*%\s*(?:full|used)|gib?\s*free|gb\s*free)\b",
    re.IGNORECASE,
)

_DISK_FIX_SAFETY_NOTE = (
    "Disk-safety guardrails for this cleanup: First measure free space with "
    "`df -h /System/Volumes/Data` (not a `du` walk of the home folder — that trips "
    "the macOS \"would like to access data from other apps\" permission prompt "
    "repeatedly and is slow). If freed space doesn't show up in `df`, it's almost "
    "certainly pinned by local Time Machine snapshots — check `tmutil "
    "listlocalsnapshots /` and reclaim with `tmutil thinlocalsnapshots / "
    "<bytes> 4`. When you do need to find large items, scope `du` to specific "
    "non-protected paths (e.g. ~/AGENTS, ~/Library/Caches, ~/.cache) rather than "
    "the whole home directory, and never delete anything in Desktop, Documents, "
    "Downloads, or Dropbox without explicit confirmation."
)


def _disk_fix_safety_note(finding: str) -> str:
    """Return cleanup guardrails when a flagged finding is about disk/storage, else
    empty. Keeps the desktop agent off home-folder `du` walks (TCC popup storm) and
    aware that reclaimed space is pinned by local Time Machine snapshots."""
    if finding and _DISK_FINDING_RE.search(finding):
        return _DISK_FIX_SAFETY_NOTE
    return ""


@app.post("/api/automations/{schid}/runs/{run_key}/fix_draft")
async def api_fix_draft(schid: int, run_key: int, request: Request):
    """Pre-draft, in the user's first-person voice, the instruction to hand a
    desktop agent so it FIXES what this automation run flagged. Read-only — seeds
    nothing and starts no job; the UI shows the draft for the user to confirm/edit
    before dispatching via /dispatch_fix. Scoped to the one failing run."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    with _db() as conn:
        row = conn.execute("SELECT * FROM skill_schedules WHERE id=?", (int(schid),)).fetchone()
    denied = _schedule_access_error(request, row)
    if denied:
        return denied
    sched = _schedule_from_row(row)
    cid = sched.get("series_chat_id")
    if not cid:
        return JSONResponse({"ok": False, "error": "no series chat"}, status_code=400)
    run = _arun_row(int(schid), int(run_key))
    if not run:
        return JSONResponse({"ok": False, "error": "run not found"}, status_code=404)
    body = await request.json()
    agent_id = body.get("agent_id") or ""
    agent_name = AGENTS_BY_ID.get(agent_id, {}).get("name") or "the agent"
    finding = (run.get("headline") or run.get("summary") or "the flagged issue").strip()
    transcript = _run_scoped_briefing(int(cid), int(run_key)) or finding
    prior = (
        f"This automation “{sched.get('name') or 'automation'}” flagged: {finding}\n\n"
        "Draft the instruction telling the agent to FIX it (not just re-report)."
    )
    draft = {"instructions": "", "questions": []}
    router = (
        AGENTS_BY_ID.get(_effective_concierge_agent_id())
        or AGENTS_BY_ID.get(LEAD_AGENT_ID)
        or (AGENTS[0] if AGENTS else None)
    )
    if router is not None:
        try:
            raw = await _concierge_call(
                router, _build_pass_draft_prompt(agent_name, transcript, prior),
                CONCIERGE_TIMEOUT_S,
            )
            draft = _parse_pass_draft(raw)
        except Exception as exc:
            logger.warning("fix draft via orchestrator failed: %s", exc)
    if not draft.get("instructions"):
        draft["instructions"] = (
            f"Please investigate and fix this issue flagged by the automation: {finding}. "
            "Make the needed changes directly, then report what you did and the result."
        )
    # Disk/storage findings: steer the desktop agent away from a home-folder `du`
    # walk, which (a) trips the macOS "would like to access data from other apps"
    # TCC prompt over and over for unsigned CLIs like agy, and (b) misreports free
    # space because reclaimed bytes are pinned by local Time Machine snapshots.
    note = _disk_fix_safety_note(finding)
    if note and note not in draft["instructions"]:
        draft["instructions"] = draft["instructions"].rstrip() + "\n\n" + note
    return JSONResponse({"ok": True, "draft": draft,
                         "fix_agents": _desktop_agents_for_chat(int(cid))})


@app.post("/api/automations/{schid}/runs/{run_key}/dispatch_fix")
async def api_dispatch_fix(schid: int, run_key: int, request: Request):
    """Hand a flagged automation run to a desktop agent to fix autonomously. Seeds
    the (confirmed) fix instruction + a run-scoped briefing into the series chat,
    starts a detached background job (which already fans completion out to in-app
    note + web push + Telegram), and records the job on the run so its pulse row
    shows fixing→fixed and the completion can flip its health to resolved."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    user = _current_user(request)
    with _db() as conn:
        row = conn.execute("SELECT * FROM skill_schedules WHERE id=?", (int(schid),)).fetchone()
    denied = _schedule_access_error(request, row)
    if denied:
        return denied
    sched = _schedule_from_row(row)
    cid = sched.get("series_chat_id")
    if not cid:
        return JSONResponse({"ok": False, "error": "no series chat"}, status_code=400)
    cid = int(cid)
    run = _arun_row(int(schid), int(run_key))
    if not run:
        return JSONResponse({"ok": False, "error": "run not found"}, status_code=404)
    body = await request.json()
    agent_id = body.get("agent_id")
    instructions = (body.get("instructions") or "").strip()[:4000]
    if agent_id not in AGENTS_BY_ID or agent_id not in _allowed_agent_ids_for_chat(cid):
        return JSONResponse({"ok": False, "error": "unknown or not-allowed agent"}, status_code=400)
    cap = _agent_capabilities(agent_id, cid)
    if (cap.get("ui") or {}).get("surface") != "desktop":
        return JSONResponse({"ok": False, "error": "this agent has no desktop runtime"}, status_code=400)
    agent = AGENTS_BY_ID[agent_id]
    ws = _chat_workspace(cid)
    principal = _chat_principal_name(cid)
    finding = (run.get("headline") or run.get("summary") or "the flagged issue").strip()
    briefing = _run_scoped_briefing(cid, int(run_key))
    instruction = (
        f"[Fix dispatch · {agent['name']}] An automation run flagged an issue. Work "
        f"autonomously now in {ws} — make the needed edits/commands directly, then "
        f"report what you fixed and the result.\n\nFlagged: {finding}"
    )
    if instructions:
        instruction += f"\n\nWhat to do:\n{instructions}"
    if briefing:
        instruction += f"\n\nRun details:\n{briefing}"
    entry = append_thread(cid, "user", None, principal, instruction)
    await broadcast({
        "type": "message", "chat_id": cid, "sender": "user", "name": principal,
        "text": instruction, "ts": entry["ts"], "attachments": [],
    })
    job_id = await _start_background_job(
        cid, [agent_id], "solo",
        owner_user_id=(int(user["id"]) if user else None),
        label=f"fix · {agent['name']} · {sched.get('name') or 'automation'}",
    )
    # Record the dispatch on the run so the pulse can render fixing→fixed and the
    # bg-job completion hook (_maybe_resolve_fix_dispatch) can tie back to it.
    with _db() as conn:
        conn.execute(
            "UPDATE automation_runs SET fix_job_id=?, fix_agent=?, fix_state='dispatched' "
            "WHERE id=?",
            (int(job_id), str(agent_id)[:48], int(run["id"])),
        )
    return JSONResponse({"ok": True, "job_id": job_id, "agent_id": agent_id})


@app.post("/api/automations/{schid}/notify")
async def api_save_automation_notify(schid: int, request: Request):
    """Save the escalation policy / archetype for an automation. An event present
    in `notify` is a PINNED override (it wins over the orchestrator baseline);
    sending it as 'inherit'/'' un-pins it back to the default."""
    blocked = _require_origin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except Exception:
        body = {}
    with _db() as conn:
        row = conn.execute("SELECT * FROM skill_schedules WHERE id=?", (int(schid),)).fetchone()
    denied = _schedule_access_error(request, row)
    if denied:
        return denied
    sched = _schedule_from_row(row)
    if body.get("archetype") in AUTOMATION_ARCHETYPES:
        sched["archetype"] = body["archetype"]
    if "change_gate" in body:
        sched["change_gate"] = bool(body["change_gate"])
    if "hold_gated" in body:
        sched["hold_gated"] = bool(body["hold_gated"])
    notify = dict(sched.get("notify") or {})
    incoming = body.get("notify") if isinstance(body.get("notify"), dict) else {}
    for ev, loud in incoming.items():
        if ev == "quiet_hours":
            notify["quiet_hours"] = bool(loud)
        elif loud in _NOTIFY_LOUDNESS:
            notify[ev] = loud
        elif loud in (None, "", "inherit"):
            notify.pop(ev, None)
    sched["notify"] = notify
    saved = _save_schedule(sched, owner_user_id=sched.get("owner_user_id"))
    _audit_event(request, "automation.notify.save", target=str(schid), status="ok",
                 meta={"archetype": sched.get("archetype")})
    return JSONResponse({"ok": True, "automation": _automation_card(saved)})


@app.get("/api/brief")
async def api_brief(request: Request):
    """Today's brief: the hero band of the dashboard and the 7am push payload."""
    user = _current_user(request)
    scheds = [s for s in _list_schedules(
        owner_user_id=(user or {}).get("id"), include_legacy=_is_admin_user(user)
    )
              if s.get("trigger_type") in _RECURRING_TRIGGERS]
    day_start = int(datetime.now().replace(
        hour=0, minute=0, second=0, microsecond=0).timestamp() * 1000)
    sched_ids = [int(s["id"]) for s in scheds]
    name_by_id = {int(s["id"]): (s.get("name") or "") for s in scheds}
    counts: dict = {"ok": 0, "failed": 0, "held": 0, "running": 0, "skipped": 0, "stopped": 0}
    lines: list = []
    ran_today = 0
    pend = 0
    if sched_ids:
        placeholders = ",".join("?" * len(sched_ids))
        with _db() as conn:
            runs_today = conn.execute(
                f"SELECT * FROM automation_runs WHERE started_ts>=? "
                f"AND schedule_id IN ({placeholders}) ORDER BY started_ts DESC, id DESC",
                [day_start] + sched_ids,
            ).fetchall()
            pend = conn.execute(
                f"SELECT COUNT(*) AS n FROM automation_items WHERE state='pending' "
                f"AND schedule_id IN ({placeholders})", sched_ids,
            ).fetchone()["n"]
        ran_today = len(runs_today)
        for r in runs_today:
            counts[r["status"]] = counts.get(r["status"], 0) + 1
            if r["status"] in ("failed", "held") or r["trigger"] == "orchestrator_standin":
                lines.append({
                    "schedule_id": r["schedule_id"],
                    "name": name_by_id.get(r["schedule_id"], ""),
                    "status": r["status"], "trigger": r["trigger"],
                    "summary": r["summary"],
                })
    return JSONResponse({
        "ok": True,
        "active": len(scheds),
        "ran_today": ran_today,
        "needs_you": int(pend or 0),
        "failed": counts.get("failed", 0),
        "counts": counts,
        "lines": lines,
        "paused": _automation_paused(),
    })


def _foreman_append_capped(path: Path, line: str) -> None:
    """Bounded append for the foreman's write-only archives, shared with the
    package's LogChannel so every foreman JSONL file has the same ceiling."""
    try:
        from jarvis_foreman.channels import append_capped
        append_capped(path, line)
    except Exception:
        with path.open("a", encoding="utf-8") as f:
            f.write(line + "\n")


def _control_room_read_jsonl(path: Path, limit: int = 40) -> list[dict]:
    """Tail a JSONL file newest-first without loading huge histories.

    Reads only the final chunk of the file rather than slurping the whole thing:
    this runs on every GET /api/control-room (every 15 s while the HUD is open),
    and the foreman event log is append-per-tick.
    """
    if not path.is_file():
        return []
    try:
        with path.open("rb") as f:
            f.seek(0, 2)
            size = f.tell()
            want = min(size, 512 * 1024)
            f.seek(size - want)
            chunk = f.read()
    except OSError:
        return []
    text = chunk.decode("utf-8", errors="replace")
    raw = text.splitlines()
    if want < size and raw:
        raw = raw[1:]  # the seek landed mid-line; drop the partial head
    out: list[dict] = []
    for line in reversed(raw[-max(limit * 3, 80):]):
        line = (line or "").strip()
        if not line:
            continue
        try:
            out.append(json.loads(line))
        except Exception:
            continue
        if len(out) >= limit:
            break
    return out


_RETIRED_FOREMAN_SENSOR_IDS = frozenset({"memory_gap"})


def _control_room_filter_retired_sensors(rows: list[dict], limit: int) -> list[dict]:
    """Keep retired internal sensors out of every public historical feed."""
    out = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        sensor_id = str(row.get("sensor_id") or "")
        source = str(row.get("source") or "")
        if sensor_id in _RETIRED_FOREMAN_SENSOR_IDS:
            continue
        if source in {f"sensor:{sid}" for sid in _RETIRED_FOREMAN_SENSOR_IDS}:
            continue
        out.append(row)
        if len(out) >= int(limit):
            break
    return out


def _control_room_filter_retired_audit(entries: list[dict], stream: str) -> list[dict]:
    """Remove retired sensor material from durable Junior/Senior audit reads."""
    out: list[dict] = []
    for original in entries if isinstance(entries, list) else []:
        if not isinstance(original, dict):
            continue
        row = dict(original)
        if stream == "senior":
            flag = row.get("flag") if isinstance(row.get("flag"), dict) else {}
            if flag.get("sensor_id") in _RETIRED_FOREMAN_SENSOR_IDS:
                continue
            out.append(row)
            continue
        watching = row.get("watching") if isinstance(row.get("watching"), list) else []
        retired_watching = [
            item for item in watching
            if isinstance(item, dict) and item.get("id") in _RETIRED_FOREMAN_SENSOR_IDS
        ]
        # A non-green retired watcher influenced the Junior model's narration even
        # when it chose different wording ("memory gaps", "unanswered question",
        # and many other variants exist in the durable corpus). Drop that whole
        # historical snapshot instead of trying to redact generated prose. Green
        # watcher rows can still carry legitimate narration about another sensor;
        # retain those after removing the retired watcher structurally.
        if any(str(item.get("severity") or "").lower() != "green"
               for item in retired_watching):
            continue
        row["watching"] = [
            item for item in watching
            if not (isinstance(item, dict) and item.get("id") in _RETIRED_FOREMAN_SENSOR_IDS)
        ]
        handoff = row.get("handoff") if isinstance(row.get("handoff"), dict) else None
        if handoff and handoff.get("sensor_id") in _RETIRED_FOREMAN_SENSOR_IDS:
            continue
        out.append(row)
    return out


def _control_room_voice_choices(current_id: str = "") -> list[dict]:
    """The Control Room offers exactly the voices the per-agent voice setting offers —
    same base ids, same custom presets, same order — so the operator only ever picks
    from voices they have already heard an agent speak with. Deriving this from
    _kokoro_voice_catalog() rather than a hand-kept list means adding a preset to
    custom_voices/voices.json shows up in both pickers at once, and the two can't drift.
    Ids outside the catalog silently synthesize as af_heart (a FEMALE voice), which is
    why the POST validates through _kokoro_resolve_voice instead of trusting the client.
    """
    choices = [
        {
            "id": voice["id"],
            "label": voice["name"],
            "lang": voice.get("lang", ""),
            "custom": bool(voice.get("custom")),
        }
        for voice in _kokoro_voice_catalog()
    ]
    # Same sort the per-agent picker applies client-side (lang, then name).
    choices.sort(key=lambda v: f"{v['lang']} {v['label']}")
    # A config saved before this catalog existed may pin a raw blend (e.g. the retired
    # "bm_george,bm_daniel"). It still synthesizes fine, but with no matching <option>
    # the browser would show the FIRST voice as selected while the foreman speaks a
    # different one. Surface it instead of quietly misreporting what is configured.
    current_id = str(current_id or "").strip()
    if current_id and not any(v["id"] == current_id for v in choices):
        choices.insert(0, {
            "id": current_id,
            "label": f"{current_id} — current (not in catalog)",
            "lang": "",
            "custom": False,
        })
    return choices


def _control_chat_title(cid) -> Optional[str]:
    try:
        chat = (CHAT_INDEX.get("chats") or {}).get(str(int(cid)))
    except (TypeError, ValueError):
        return None
    return chat.get("title") if isinstance(chat, dict) else None


def _control_room_ack_windows(cfg) -> dict:
    """{sensor_id: ack_until} — episodes the operator has said "I know" to."""
    try:
        from jarvis_foreman.bus import ForemanBus
        return ForemanBus(cfg).ack_windows()
    except Exception:
        return {}


def _control_room_resolved_map(cfg) -> dict:
    """{sensor_id: resolved_key} — conditions the operator marked handled/fixed."""
    try:
        from jarvis_foreman.bus import ForemanBus
        return ForemanBus(cfg).resolved_map()
    except Exception:
        return {}


def _control_room_poll_sensors(cfg) -> list[dict]:
    """Live sensor pulse for the Control Room (independent of foreman enabled)."""
    try:
        from jarvis_foreman.sensors import build_default_registry
    except Exception as e:
        return [{"id": "import", "severity": "amber", "headline": f"sensors unavailable: {e}", "detail": {}}]
    acks = _control_room_ack_windows(cfg)
    resolved = _control_room_resolved_map(cfg)
    signals: list[dict] = []
    try:
        for s in build_default_registry(cfg):
            try:
                for sig in s.poll():
                    sid = getattr(sig, "sensor_id", getattr(s, "id", "unknown"))
                    sig_key = sig.key() if hasattr(sig, "key") else ""
                    signals.append({
                        "id": sid,
                        "severity": getattr(sig, "severity", "green"),
                        "headline": getattr(sig, "headline", ""),
                        "detail": getattr(sig, "detail", {}) or {},
                        # Stable condition id, so the Senior debounce keys on the
                        # condition and not the churny offender text.
                        "dedupe_key": sig_key,
                        # Acked = silenced, never hidden. The HUD still shows it red.
                        "ack_until": acks.get(sid),
                        # Resolved = operator marked THIS exact condition handled; the
                        # HUD clears it. A changed condition (new key) un-resolves it.
                        "resolved": bool(sig_key) and resolved.get(sid) == sig_key,
                    })
            except Exception as e:
                signals.append({
                    "id": getattr(s, "id", "unknown"),
                    "severity": "amber",
                    "headline": f"sensor error: {e}",
                    "detail": {"error": str(e)},
                })
    except Exception as e:
        signals.append({"id": "registry", "severity": "amber", "headline": str(e), "detail": {}})
    return signals


@app.get("/api/control-room")
async def api_control_room(request: Request):
    """Aggregator for the Control Room HUD: seats, live sensors, brief, events.

    Open contract (v:1). Zones can upgrade without renaming this route.
    Does not enable the foreman daemon; reads config + polls sensors for display.

    Admin-only, like every mutating /api/control-room route. This is an operator
    console: it surfaces the pinned control chat, its Canvas artifacts, the box's
    calendar and the whole roster. A merely-authenticated non-admin has no business
    reading it, and previously could.
    """
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        from jarvis_foreman.config import load_config
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"foreman unavailable: {e}"}, status_code=500)

    cfg = load_config()
    raw = cfg.raw or {}
    seats = raw.get("seats") or {}
    channels = raw.get("channels") or {}
    data_dir = Path(cfg.path).parent

    # Brief slice (reuse same shape as /api/brief without double client round-trips)
    brief = None
    try:
        user = _current_user(request)
        scheds = [s for s in _list_schedules(
            owner_user_id=(user or {}).get("id"), include_legacy=_is_admin_user(user)
        )
                  if s.get("trigger_type") in _RECURRING_TRIGGERS]
        day_start = int(datetime.now().replace(
            hour=0, minute=0, second=0, microsecond=0).timestamp() * 1000)
        sched_ids = [int(s["id"]) for s in scheds]
        counts: dict = {"ok": 0, "failed": 0, "held": 0, "running": 0, "skipped": 0, "stopped": 0}
        lines: list = []
        ran_today = 0
        pend = 0
        if sched_ids:
            placeholders = ",".join("?" * len(sched_ids))
            with _db() as conn:
                runs_today = conn.execute(
                    f"SELECT * FROM automation_runs WHERE started_ts>=? "
                    f"AND schedule_id IN ({placeholders}) ORDER BY started_ts DESC, id DESC",
                    [day_start] + sched_ids,
                ).fetchall()
                pend = conn.execute(
                    f"SELECT COUNT(*) AS n FROM automation_items WHERE state='pending' "
                    f"AND schedule_id IN ({placeholders})", sched_ids,
                ).fetchone()["n"]
            ran_today = len(runs_today)
            name_by_id = {int(s["id"]): (s.get("name") or "") for s in scheds}
            for r in runs_today:
                counts[r["status"]] = counts.get(r["status"], 0) + 1
                if r["status"] in ("failed", "held") or r["trigger"] == "orchestrator_standin":
                    lines.append({
                        "schedule_id": r["schedule_id"],
                        "name": name_by_id.get(r["schedule_id"], ""),
                        "status": r["status"], "trigger": r["trigger"],
                        "summary": r["summary"],
                    })
        brief = {
            "active": len(scheds),
            "ran_today": ran_today,
            "needs_you": int(pend or 0),
            "failed": counts.get("failed", 0),
            "counts": counts,
            "lines": lines[:8],
            "paused": _automation_paused(),
        }
    except Exception as e:
        logger.exception("control-room brief assemble failed")
        brief = {"error": str(e)}

    sensors = [
        sig for sig in await asyncio.to_thread(_control_room_poll_sensors, cfg)
        if sig.get("id") not in _RETIRED_FOREMAN_SENSOR_IDS
    ]
    rank = {"green": 0, "amber": 1, "red": 2}
    worst = "green"
    for sig in sensors:
        if sig.get("resolved"):
            continue  # operator marked it handled — doesn't tint the room
        if rank.get(sig.get("severity"), 0) > rank.get(worst, 0):
            worst = sig.get("severity") or "green"

    events = _control_room_filter_retired_sensors(
        _control_room_read_jsonl(data_dir / "jarvis_foreman_events.jsonl", 120), 24,
    )
    alerts = _control_room_filter_retired_sensors(
        _control_room_read_jsonl(data_dir / "jarvis_foreman_alerts.jsonl", 60), 12,
    )
    voice_hints = _control_room_filter_retired_sensors(
        _control_room_read_jsonl(data_dir / "jarvis_foreman_voice_hints.jsonl", 25), 5,
    )

    # Lightweight roster strip from in-process agent defs (no bridge ping flood)
    roster = []
    try:
        for a in AGENTS if isinstance(AGENTS, list) else []:
            roster.append({
                "id": a.get("id"),
                "name": a.get("name"),
                "color": a.get("color"),
            })
    except Exception:
        roster = []

    # Calendar strip (best-effort; empty if ICS not configured)
    calendar_block: dict = {"ok": False, "events": [], "error": None}
    try:
        cal_res = await calendar_ics.upcoming(days=3, limit=6)
        if isinstance(cal_res, dict):
            evs = cal_res.get("events") or cal_res.get("items") or []
            calendar_block = {
                "ok": True,
                "events": [
                    {
                        "title": (e.get("title") or e.get("summary") or "Event")[:120],
                        "start": e.get("start") or e.get("when") or e.get("start_iso"),
                        "end": e.get("end") or e.get("end_iso"),
                        "all_day": bool(e.get("all_day") or e.get("allDay")),
                    }
                    for e in (evs if isinstance(evs, list) else [])[:6]
                    if isinstance(e, dict)
                ],
                "error": None,
            }
        else:
            calendar_block = {"ok": False, "events": [], "error": "unexpected calendar shape"}
    except Exception as e:
        calendar_block = {"ok": False, "events": [], "error": str(e)[:200]}

    # A pinned control chat that no longer exists (room was deleted) must not be
    # served verbatim — the HUD would render live-looking buttons that all 404.
    # Emit None + the stale id so the panel can prompt a re-pin; the config file
    # itself is not mutated here (the drain self-heals it).
    control_cid = raw.get("control_chat_id")
    control_chat_missing = None
    if control_cid is not None and str(control_cid) not in (CHAT_INDEX.get("chats") or {}):
        control_chat_missing = {"id": control_cid}
        control_cid = None

    # Canvas dock: recent artifacts from control chat or newest active chat
    canvas_cid = control_cid
    try:
        canvas_cid = int(canvas_cid) if canvas_cid is not None else None
    except (TypeError, ValueError):
        canvas_cid = None
    if not canvas_cid:
        try:
            # Newest chat with artifacts — but only among the caller's OWN chats.
            # Unfiltered, this dock happily surfaced another user's artifact names
            # and signed URLs to whoever opened the panel.
            owner_id = (_current_user(request) or {}).get("id")
            with _db() as conn:
                row = conn.execute(
                    "SELECT m.chat_id FROM messages m JOIN chats c ON c.id = m.chat_id "
                    "WHERE m.artifacts_json IS NOT NULL AND m.artifacts_json != '[]' "
                    "AND c.owner_user_id IS ? AND c.deleted_ts IS NULL "
                    "ORDER BY m.ts DESC LIMIT 1",
                    (owner_id,),
                ).fetchone()
            if row:
                canvas_cid = int(row["chat_id"])
        except Exception:
            canvas_cid = None
    canvas_items: list[dict] = []
    if canvas_cid:
        try:
            arts = _canvas_artifacts_as_files(canvas_cid)[:12]
            for a in arts:
                canvas_items.append({
                    "id": a.get("id"),
                    "chat_id": canvas_cid,
                    "name": a.get("name") or "Artifact",
                    "kind": a.get("kind") or "",
                    "mime": a.get("mime") or "",
                    "url": a.get("url") or "",
                    "ts": a.get("ts") or 0,
                    "source_name": a.get("source_name") or "",
                })
        except Exception as e:
            logger.debug("control-room canvas list failed: %s", e)

    senior_id = cfg.senior_id()
    junior = (seats.get("junior_pm") or {})
    seat_choices = [
        {"id": a.get("id"), "name": a.get("name")}
        for a in (AGENTS if isinstance(AGENTS, list) else [])
        if a.get("id")
    ]
    # Failed Decisions searches are internal retrieval telemetry. Preserve the legacy
    # response key for older clients, but never turn those misses into Control Room
    # attention or owner work.
    open_questions: list[dict] = []

    _cr_voice = raw.get("voice") or {"id": "bm_fable", "speed": 1.06}
    orchestrator = await _orchestrator_status(request)
    return JSONResponse({
        "ok": True,
        "v": 1,
        "ts": time.time(),
        "app": {
            "build": APP_VERSION,
            "name": "Agents Chat",
            "mission_control": _mission_control_enabled(),
        },
        "foreman": {
            "enabled": bool(cfg.enabled),
            "poll_interval_sec": raw.get("poll_interval_sec"),
            "control_chat_id": control_cid,
            "control_chat_title": _control_chat_title(control_cid),
            "control_chat_missing": control_chat_missing,
            "quiet_hours": raw.get("quiet_hours") or {},
            "loop": {
                "running": bool(_FOREMAN_LOOP_STATE.get("running")),
                "last_tick_ts": _FOREMAN_LOOP_STATE.get("last_tick_ts"),
                "last_tick_result": _FOREMAN_LOOP_STATE.get("last_tick_result"),
                "last_drain": _FOREMAN_LOOP_STATE.get("last_drain"),
                "last_error": _FOREMAN_LOOP_STATE.get("last_error"),
                "ticks": _FOREMAN_LOOP_STATE.get("ticks") or 0,
                "drained_total": _FOREMAN_LOOP_STATE.get("drained_total") or 0,
            },
            "outbox_pending": _foreman_outbox_pending_count(data_dir),
            # Junior's live read — narration, what it's watching, last handoff to
            # Senior. Written by the background loop tick (jarvis_foreman.narrator).
            "junior": _FOREMAN_LOOP_STATE.get("junior"),
            # Senior's latest analysis (verdict / root cause / recommended fix) of the
            # flag Junior handed up. Written by _run_senior_analysis.
            "senior": _FOREMAN_LOOP_STATE.get("senior"),
        },
        # The HUD speaks with its own voice, not the senior agent's.
        "voice": _cr_voice,
        "voice_choices": _control_room_voice_choices(_cr_voice.get("id", "")),
        # Agents a red/amber flag can be handed to for an autonomous fix. Same gate
        # /pass_to_desktop enforces, so the HUD can only offer what dispatch accepts.
        "desktop_agents": _desktop_agents_for_chat(control_cid),
        "voice_hints": voice_hints,
        "seats": {
            "senior_pm": {
                "roster_agent_id": senior_id,
                "capabilities": (seats.get("senior_pm") or {}).get("capabilities") or [],
            },
            "junior_pm": {
                "roster_agent_id": junior.get("roster_agent_id"),
                "model_hint": junior.get("model_hint") or "cheap",
                "capabilities": junior.get("capabilities") or [],
                "status": "planned" if not junior.get("roster_agent_id") else "configured",
            },
            "choices": seat_choices,
        },
        "orchestrator": orchestrator,
        "pulse": {
            "worst": worst,
            "sensors": sensors,
        },
        "open_questions": open_questions,
        "brief": brief,
        "calendar": calendar_block,
        "canvas": {
            "chat_id": canvas_cid,
            "items": canvas_items,
        },
        "events": events,
        "alerts": alerts,
        "channels": {
            k: {
                "enabled": bool((v or {}).get("enabled")),
                "parked": k in ("twilio", "retell"),
            }
            for k, v in (channels or {}).items()
        },
        "roster": roster,
        "zones": [
            "pulse", "open_questions", "seats", "jobs", "flags", "roster",
            "calendar", "canvas", "phone_parked",
        ],
        "actions": {
            "open_mission": True,
            "open_canvas": True,
            "open_agentic_voice": True,
            "open_agents_settings": True,
            "set_senior": True,
            "set_control_chat": True,
            "set_foreman_enabled": True,
            "force_tick": True,
            "open_agentic_as_senior": True,
            "twilio": False,
        },
    })


@app.get("/api/control-room/audit")
async def api_control_room_audit(request: Request):
    """Durable Junior audit trail — one day's tick-by-tick record (default today).

    Reads data/junior_audit/<date>.jsonl (uncapped daily files), separate from the
    trimmed hot events feed, so you can go back and audit what Junior saw and said.
    Admin-only, like the rest of the control room.
    """
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        from jarvis_foreman.config import load_config
        from jarvis_foreman import audit as _jf_audit
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"foreman unavailable: {e}"}, status_code=500)
    cfg = load_config()
    stream = (request.query_params.get("stream") or "junior").strip().lower()
    if stream not in ("junior", "senior"):
        stream = "junior"
    day = (request.query_params.get("date") or "").strip() or None
    # Guard the day-file path against traversal: only accept a literal YYYY-MM-DD.
    if day and not (len(day) == 10 and day[4] == "-" and day[7] == "-" and day.replace("-", "").isdigit()):
        day = None
    try:
        limit = min(max(int(request.query_params.get("limit") or 200), 1), 1000)
    except (TypeError, ValueError):
        limit = 200
    entries = await asyncio.to_thread(_jf_audit.read_audit, cfg, day, limit, stream)
    entries = _control_room_filter_retired_audit(entries, stream)
    days = await asyncio.to_thread(_jf_audit.list_days, cfg, 30, stream)
    return JSONResponse({
        "ok": True,
        "stream": stream,
        "date": day or (days[0] if days else None),
        "days": days,
        "entries": entries,
    })


@app.post("/api/control-room/senior")
async def api_control_room_set_senior(request: Request):
    """Set senior_pm seat to a roster agent id. Open upgrade path for Agents Settings later."""
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid json"}, status_code=400)
    if not isinstance(body, dict):
        return JSONResponse({"ok": False, "error": "object required"}, status_code=400)
    agent_id = str(body.get("roster_agent_id") or body.get("agent_id") or "").strip()
    if not agent_id or agent_id not in AGENTS_BY_ID:
        return JSONResponse(
            {"ok": False, "error": f"unknown roster agent: {agent_id or '(empty)'}"},
            status_code=400,
        )
    try:
        from jarvis_foreman.config import load_config, save_config
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"foreman unavailable: {e}"}, status_code=500)
    cfg = load_config()
    seats = cfg.raw.setdefault("seats", {})
    senior = seats.setdefault("senior_pm", {})
    senior["roster_agent_id"] = agent_id
    if not senior.get("capabilities"):
        senior["capabilities"] = ["chat", "voice", "tools_full"]
    save_config(cfg)
    _audit_event(
        request, "control_room.set_senior", actor="admin", status="ok",
        meta={"roster_agent_id": agent_id},
    )
    return JSONResponse({
        "ok": True,
        "seats": {
            "senior_pm": {
                "roster_agent_id": agent_id,
                "capabilities": senior.get("capabilities") or [],
            }
        },
    })


# A pinned room is the foreman's destination *and* the chat a flag is handed off
# from, so it earns a visible mark in the thread list. The badge is a prefix, not a
# replacement: unpinning restores the original title exactly.
CONTROL_ROOM_BADGE = "🎛️ Control Room"
_CONTROL_ROOM_PREFIX = f"{CONTROL_ROOM_BADGE} · "


def _badge_control_chat(cid: int) -> Optional[str]:
    """Prefix a pinned chat's title with the Control Room badge. Idempotent.

    Deliberately NOT capped at 80 chars the way `_create_chat_record` caps a new
    title. Truncating here would eat the tail of a long original, and unpinning —
    which recovers the original by stripping this exact prefix — would hand back a
    permanently shortened title. Nothing stores the original separately: CHAT_INDEX
    is rebuilt from the chats table on boot, so any extra key would not survive a
    restart. Keeping the badge lossless is what makes unpinning exact.
    """
    chat = (CHAT_INDEX.get("chats") or {}).get(str(cid))
    if not isinstance(chat, dict):
        return None
    title = str(chat.get("title") or f"#{cid}")
    if title == CONTROL_ROOM_BADGE or title.startswith(_CONTROL_ROOM_PREFIX):
        return title
    chat["title"] = _CONTROL_ROOM_PREFIX + title
    _save_index()
    return chat["title"]


def _unbadge_control_chat(cid: Optional[int]) -> Optional[str]:
    """Strip the badge when a chat stops being the control room."""
    if not cid:
        return None
    chat = (CHAT_INDEX.get("chats") or {}).get(str(cid))
    if not isinstance(chat, dict):
        return None
    title = str(chat.get("title") or "")
    if title.startswith(_CONTROL_ROOM_PREFIX):
        chat["title"] = title[len(_CONTROL_ROOM_PREFIX):] or f"#{cid}"
        _save_index()
        return chat["title"]
    return title


def _mint_control_room_chat(cfg, owner_user_id: Optional[int] = None) -> int:
    """Mint the dedicated Control Room chat (senior seat pre-targeted). Shared by
    the pin endpoint's {"create": true} path and the drain self-heal so both
    produce identical rooms. Does NOT write the foreman config — callers pin."""
    senior = cfg.senior_id()
    # _create_chat_record flips active_id as a side effect; nobody asked to be
    # moved out of the room they are standing in, so put it back.
    prior_active = CHAT_INDEX.get("active_id")
    chat_id = _create_chat_record(
        CONTROL_ROOM_BADGE,
        mode="solo",
        targets=[senior] if senior in AGENTS_BY_ID else [],
        owner_user_id=owner_user_id,
    )
    if prior_active is not None:
        CHAT_INDEX["active_id"] = prior_active
        _save_index()
    return chat_id


@app.post("/api/control-room/control-chat")
async def api_control_room_set_control_chat(request: Request):
    """Pin the room that receives foreman flags + owns the Canvas dock default.

    `{"create": true}` mints a dedicated room instead of commandeering an existing
    conversation. Pinning badges the chat title; unpinning un-badges the old one.
    """
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid json"}, status_code=400)
    if not isinstance(body, dict):
        return JSONResponse({"ok": False, "error": "object required"}, status_code=400)

    try:
        from jarvis_foreman.config import load_config, save_config
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"foreman unavailable: {e}"}, status_code=500)
    cfg = load_config()
    previous_cid = cfg.raw.get("control_chat_id")
    try:
        previous_cid = int(previous_cid) if previous_cid is not None else None
    except (TypeError, ValueError):
        previous_cid = None

    created = False
    if body.get("create"):
        user = _current_user(request)
        chat_id = _mint_control_room_chat(cfg, owner_user_id=(user or {}).get("id"))
        created = True
    else:
        raw_cid = body.get("chat_id", body.get("control_chat_id", "__missing__"))
        if raw_cid is None or raw_cid == "" or raw_cid == "null":
            chat_id = None
        else:
            try:
                chat_id = int(raw_cid)
            except (TypeError, ValueError):
                return JSONResponse({"ok": False, "error": "chat_id must be int or null"}, status_code=400)
            chats = (CHAT_INDEX.get("chats") or {}) if isinstance(CHAT_INDEX, dict) else {}
            if str(chat_id) not in chats:
                return JSONResponse(
                    {"ok": False, "error": f"unknown chat_id: {chat_id}"},
                    status_code=400,
                )

    cfg.raw["control_chat_id"] = chat_id
    save_config(cfg)

    title = None
    if previous_cid and previous_cid != chat_id:
        old_title = _unbadge_control_chat(previous_cid)
        if old_title:
            await broadcast({"type": "chat_meta", "chat_id": previous_cid, "title": old_title}, global_event=True)
    if chat_id is not None:
        title = _badge_control_chat(chat_id)
        if title:
            await broadcast({"type": "chat_meta", "chat_id": chat_id, "title": title}, global_event=True)
    drain = {"skipped": True}
    if chat_id is not None:
        try:
            drain = await _foreman_drain_chat_outbox(cfg)
        except Exception as e:
            drain = {"ok": False, "error": str(e)}
    _audit_event(
        request, "control_room.set_control_chat", actor="admin", status="ok",
        meta={"control_chat_id": chat_id, "created": created},
    )
    return JSONResponse({
        "ok": True,
        "control_chat_id": chat_id,
        "title": title,
        "created": created,
        "drain": drain,
    })


@app.post("/api/control-room/ack")
async def api_control_room_ack(request: Request):
    """Acknowledge an open episode: stop telling me, I know. Silences the noisy
    channels for `hours` without hiding anything in the HUD. A changed condition or
    an escalation opens a new episode and drops the ack."""
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid json"}, status_code=400)
    sensor_id = str((body or {}).get("sensor_id") or "").strip()[:64]
    if not sensor_id:
        return JSONResponse({"ok": False, "error": "sensor_id required"}, status_code=400)
    try:
        hours = float((body or {}).get("hours", 4))
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "hours must be a number"}, status_code=400)
    hours = max(0.0, min(hours, 72.0))

    try:
        from jarvis_foreman.bus import ForemanBus
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"foreman unavailable: {e}"}, status_code=500)
    result = await asyncio.to_thread(lambda: ForemanBus().acknowledge(sensor_id, hours))
    if not result.get("ok"):
        return JSONResponse(result, status_code=400)
    _audit_event(
        request, "control_room.ack", actor="admin", status="ok",
        meta={"sensor_id": sensor_id, "hours": hours},
    )
    return JSONResponse(result)


@app.post("/api/control-room/resolve")
async def api_control_room_resolve(request: Request):
    """Mark a flag's CURRENT condition handled/fixed — or undo it. Stronger than ack:
    resolve CLEARS the flag from the pulse and silences it, for a fix the sensor can't
    see or a false positive. It holds only while the condition is unchanged; a changed
    condition (a new dedupe key) re-flags it. Pass {sensor_id, key} to resolve, or
    {sensor_id, undo:true} to revert."""
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid json"}, status_code=400)
    sensor_id = str((body or {}).get("sensor_id") or "").strip()[:64]
    if not sensor_id:
        return JSONResponse({"ok": False, "error": "sensor_id required"}, status_code=400)
    undo = bool((body or {}).get("undo"))
    key = str((body or {}).get("key") or "").strip()[:512]

    try:
        from jarvis_foreman.bus import ForemanBus
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"foreman unavailable: {e}"}, status_code=500)

    if undo:
        result = await asyncio.to_thread(lambda: ForemanBus().unresolve(sensor_id))
    elif not key:
        return JSONResponse({"ok": False, "error": "key required to resolve"}, status_code=400)
    else:
        result = await asyncio.to_thread(lambda: ForemanBus().resolve(sensor_id, key))
    if not result.get("ok"):
        return JSONResponse(result, status_code=400)
    _audit_event(
        request, "control_room.resolve", actor="admin", status="ok",
        meta={"sensor_id": sensor_id, "undo": undo, "key": key[:120]},
    )
    return JSONResponse(result)


@app.post("/api/control-room/voice")
async def api_control_room_set_voice(request: Request):
    """Pick the Control Room's own speaking voice (id must be a Kokoro base id or a
    known preset — anything else silently synthesizes as af_heart, a female voice)."""
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid json"}, status_code=400)
    voice_id = str((body or {}).get("id") or "").strip()[:100]
    if not _kokoro_resolve_voice(voice_id):
        return JSONResponse({"ok": False, "error": f"unknown voice: {voice_id}"}, status_code=400)
    try:
        speed = float((body or {}).get("speed", 1.06))
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "speed must be a number"}, status_code=400)
    speed = max(0.7, min(1.3, speed))

    try:
        from jarvis_foreman.config import load_config, save_config
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"foreman unavailable: {e}"}, status_code=500)
    cfg = load_config()
    cfg.raw["voice"] = {"id": voice_id, "speed": speed}
    save_config(cfg)
    _audit_event(
        request, "control_room.set_voice", actor="admin", status="ok",
        meta={"voice": voice_id, "speed": speed},
    )
    return JSONResponse({"ok": True, "voice": cfg.raw["voice"]})


@app.post("/api/control-room/foreman")
async def api_control_room_set_foreman(request: Request):
    """Enable/disable the background foreman bus (sensors → escalate → channels)."""
    blocked = _require_admin(request)
    if blocked:
        return blocked
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid json"}, status_code=400)
    if not isinstance(body, dict) or "enabled" not in body:
        return JSONResponse({"ok": False, "error": "enabled bool required"}, status_code=400)
    enabled = bool(body.get("enabled"))
    try:
        from jarvis_foreman.config import load_config, save_config
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"foreman unavailable: {e}"}, status_code=500)
    cfg = load_config()
    cfg.raw["enabled"] = enabled
    if body.get("poll_interval_sec") is not None:
        try:
            iv = int(body.get("poll_interval_sec"))
            cfg.raw["poll_interval_sec"] = max(15, min(iv, 900))
        except (TypeError, ValueError):
            pass
    save_config(cfg)
    _audit_event(
        request, "control_room.set_foreman", actor="admin", status="ok",
        meta={"enabled": enabled},
    )
    return JSONResponse({
        "ok": True,
        "enabled": enabled,
        "poll_interval_sec": cfg.raw.get("poll_interval_sec"),
        "loop_running": bool(_FOREMAN_LOOP_STATE.get("running")),
    })


@app.post("/api/control-room/tick")
async def api_control_room_tick(request: Request):
    """One-shot foreman tick (force runs even when enabled=false) + drain outbox."""
    blocked = _require_admin(request)
    if blocked:
        return blocked
    force = True
    try:
        body = await request.json()
        if isinstance(body, dict) and "force" in body:
            force = bool(body.get("force"))
    except Exception:
        pass
    result = await _jarvis_foreman_loop_tick(force=force)
    _audit_event(
        request, "control_room.tick", actor="admin", status="ok",
        meta={"force": force, "ok": result.get("ok")},
    )
    return JSONResponse({"ok": True, **result})


# ---------------------------------------------------------------------------
# Jarvis Foreman — Phase B light: background tick + drain outbox into chat
# ---------------------------------------------------------------------------
_FOREMAN_LOOP_STATE: dict = {
    "running": False,
    "last_tick_ts": None,
    "last_tick_result": None,
    "last_drain": None,
    "last_error": None,
    "ticks": 0,
    "drained_total": 0,
    # Junior's live read + Senior's latest analysis, for the HUD + audit.
    "junior": None,
    "senior": None,
    "senior_inflight": False,
    # flag_key -> ts of last Senior analysis, to debounce (one analysis per distinct
    # problem, not one per 60s tick while the same problem stays open).
    "senior_analyzed": {},
    # sensor:state:severity -> ts of last bell emit, so an unchanged condition
    # (e.g. a chat stalled for a day) doesn't re-page every poll and evict real
    # alerts from the 200-row notification center. First occurrence and any state
    # change always emit; only exact repeats within the window are suppressed.
    "alert_emitted": {},
}

# How long before the SAME unchanged foreman condition is allowed to re-alert.
_FOREMAN_REALERT_MS = int(os.environ.get("FOREMAN_ALERT_REALERT_MS", str(2 * 60 * 60 * 1000)))

# job_id -> {sensor_id, dedupe_key, agent_id, agent_name} for desktop handoffs of a
# foreman flag, so the job's completion can re-check whether the fix cleared it. In
# memory on purpose: background jobs are asyncio tasks that don't survive a restart,
# so a persisted correlation would only ever point at a dead job.
_FOREMAN_HANDOFF_JOBS: dict[int, dict] = {}


def _foreman_track_handoff_job(job_id: int, flag_ctx: dict) -> None:
    _FOREMAN_HANDOFF_JOBS[int(job_id)] = flag_ctx
    # Backstop against a leak if a job somehow never reports completion.
    if len(_FOREMAN_HANDOFF_JOBS) > 200:
        for k in list(_FOREMAN_HANDOFF_JOBS)[:100]:
            _FOREMAN_HANDOFF_JOBS.pop(k, None)


def _foreman_outbox_pending_count(data_dir: Path) -> int:
    path = data_dir / "jarvis_foreman_chat_outbox.jsonl"
    if not path.is_file():
        return 0
    try:
        n = 0
        for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
            if line.strip():
                n += 1
        return n
    except OSError:
        return 0


async def _foreman_drain_chat_outbox(cfg=None) -> dict:
    """Post pending chat-channel flags into the control room chat (or per-line cid).

    Lines without a resolvable chat stay in the outbox until control_chat_id is set.
    """
    try:
        from jarvis_foreman.config import load_config
    except Exception as e:
        return {"ok": False, "error": f"import: {e}", "drained": 0, "held": 0}

    cfg = cfg or load_config()
    data_dir = Path(cfg.path).parent
    outbox = data_dir / "jarvis_foreman_chat_outbox.jsonl"
    if not outbox.is_file():
        return {"ok": True, "drained": 0, "held": 0, "path": str(outbox)}

    try:
        raw_lines = outbox.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError as e:
        return {"ok": False, "error": str(e), "drained": 0, "held": 0}

    default_cid = cfg.raw.get("control_chat_id")
    try:
        default_cid = int(default_cid) if default_cid is not None else None
    except (TypeError, ValueError):
        default_cid = None

    # Self-heal a deleted control room. A configured default cid that no longer
    # exists would otherwise hold every default-routed line forever — a silent,
    # ever-growing backlog. Recreate at most once per drain pass, via the same
    # path the pin endpoint's {"create": true} uses.
    chats_now = (CHAT_INDEX.get("chats") or {}) if isinstance(CHAT_INDEX, dict) else {}
    if default_cid is not None and str(default_cid) not in chats_now and cfg.channel_enabled("chat"):
        try:
            from jarvis_foreman.config import save_config
            new_cid = _mint_control_room_chat(cfg)
            cfg.raw["control_chat_id"] = new_cid
            save_config(cfg)
            logger.warning("foreman control chat %s missing — recreated as %s", default_cid, new_cid)
            default_cid = new_cid
        except Exception:
            logger.exception("foreman control chat %s missing and recreate failed", default_cid)
            _FOREMAN_LOOP_STATE["last_error"] = f"control chat {default_cid} missing"

    remaining: list[str] = []
    drained = 0
    held = 0
    archive = data_dir / "jarvis_foreman_chat_outbox.done.jsonl"

    for line in raw_lines:
        if not (line or "").strip():
            continue
        try:
            payload = json.loads(line)
        except Exception:
            remaining.append(line)
            held += 1
            continue
        if not isinstance(payload, dict):
            remaining.append(line)
            held += 1
            continue

        cid = payload.get("control_chat_id") if payload.get("control_chat_id") is not None else default_cid
        try:
            cid = int(cid) if cid is not None else None
        except (TypeError, ValueError):
            cid = None

        chats = (CHAT_INDEX.get("chats") or {}) if isinstance(CHAT_INDEX, dict) else {}
        # Lines queued before the control room was deleted carry the dead cid
        # baked in; re-route them to the current room instead of holding forever.
        if cid is not None and str(cid) not in chats and default_cid is not None:
            cid = default_cid
        if not cid or str(cid) not in chats:
            remaining.append(line)
            held += 1
            continue

        text_body = str(payload.get("text") or "").strip()
        if not text_body:
            try:
                _foreman_append_capped(archive, json.dumps({"dropped_empty": True, "raw": payload}, ensure_ascii=False))
            except OSError:
                pass
            continue

        agent_id = str(payload.get("as_agent") or cfg.senior_id() or "grok")
        agent = AGENTS_BY_ID.get(agent_id) or {}
        name = agent.get("name") or agent_id
        role = "agent" if agent_id in AGENTS_BY_ID else "system"
        use_agent_id = agent_id if role == "agent" else None
        use_name = name if role == "agent" else "Foreman"
        # The channel ships a `card` dict so the thread renders a briefing card
        # instead of raw markdown. Older outbox lines predate it — fall back to
        # the flat shape so a queue written by a previous build still drains.
        card = payload.get("card")
        if isinstance(card, dict) and card:
            meta = dict(card)
            meta.setdefault("source", "jarvis_foreman")
            meta.setdefault("foreman", True)
            meta.setdefault("event_id", payload.get("event_id"))
        else:
            meta = {
                "source": "jarvis_foreman",
                "event_id": payload.get("event_id"),
                "foreman": True,
                "severity": (payload.get("event") or {}).get("severity")
                if isinstance(payload.get("event"), dict)
                else None,
            }
        try:
            entry = append_thread(
                cid,
                role,
                use_agent_id,
                use_name,
                text_body,
                metadata=meta,
            )
            await broadcast({
                "type": "message",
                "chat_id": cid,
                "sender": role,
                "agent_id": use_agent_id,
                "name": use_name,
                "text": text_body,
                "ts": entry["ts"],
                "metadata": entry.get("metadata") or {},
            })
            drained += 1
            try:
                _foreman_append_capped(archive, json.dumps({**payload, "drained_ts": time.time(), "chat_id": cid}, ensure_ascii=False))
            except OSError:
                pass
        except Exception as e:
            logger.exception("foreman outbox drain failed for chat %s", cid)
            remaining.append(line)
            held += 1
            _FOREMAN_LOOP_STATE["last_error"] = f"drain: {e}"

    try:
        if remaining:
            tmp = outbox.with_suffix(".jsonl.tmp")
            tmp.write_text("\n".join(remaining) + "\n", encoding="utf-8")
            tmp.replace(outbox)
        else:
            outbox.write_text("", encoding="utf-8")
    except OSError as e:
        return {"ok": False, "error": f"rewrite: {e}", "drained": drained, "held": held}

    _FOREMAN_LOOP_STATE["drained_total"] = int(_FOREMAN_LOOP_STATE.get("drained_total") or 0) + drained
    _FOREMAN_LOOP_STATE["last_drain"] = {
        "ts": time.time(),
        "drained": drained,
        "held": held,
    }
    return {"ok": True, "drained": drained, "held": held}


async def _foreman_drain_alert_bell(cfg=None) -> dict:
    """Cursor-drain alert_bell JSONL into the notification center."""
    try:
        from jarvis_foreman.config import load_config
    except Exception as e:
        return {"ok": False, "error": str(e), "emitted": 0}

    cfg = cfg or load_config()
    data_dir = Path(cfg.path).parent
    path = data_dir / "jarvis_foreman_alerts.jsonl"
    cursor_path = data_dir / "jarvis_foreman_alerts.cursor"
    if not path.is_file():
        return {"ok": True, "emitted": 0}

    try:
        offset = int(cursor_path.read_text(encoding="utf-8").strip() or "0") if cursor_path.is_file() else 0
    except Exception:
        offset = 0

    try:
        raw = path.read_bytes()
    except OSError as e:
        return {"ok": False, "error": str(e), "emitted": 0}

    if offset > len(raw):
        offset = 0
    chunk = raw[offset:]
    if not chunk:
        return {"ok": True, "emitted": 0}

    text_chunk = chunk.decode("utf-8", errors="replace")
    lines = text_chunk.splitlines()
    complete = lines if text_chunk.endswith("\n") or text_chunk.endswith("\r") else lines[:-1]
    if not complete:
        return {"ok": True, "emitted": 0}

    cid = cfg.raw.get("control_chat_id")
    try:
        cid = int(cid) if cid is not None else None
    except (TypeError, ValueError):
        cid = None
    if not cid:
        try:
            cid = int(CHAT_INDEX.get("active_id") or 0) or None
        except Exception:
            cid = None
    if not cid:
        return {"ok": True, "emitted": 0, "held": "no_chat"}

    emitted = 0
    for line in complete:
        line = line.strip()
        if not line:
            continue
        try:
            row = json.loads(line)
        except Exception:
            continue
        if not isinstance(row, dict):
            continue
        sev = str(row.get("severity") or "amber")
        headline = str(row.get("headline") or "Foreman flag")[:200]
        notif_sev = "critical" if sev == "red" else ("warn" if sev == "amber" else "info")
        # Debounce an unchanged condition. The cursor still advances past this line
        # (it's consumed either way), so skipping only suppresses the duplicate
        # notification/page — it is never re-shown later.
        akey = f"{row.get('sensor_id') or '?'}:{row.get('state') or ''}:{sev}"
        now_ms = int(time.time() * 1000)
        seen = _FOREMAN_LOOP_STATE.get("alert_emitted") or {}
        if now_ms - int(seen.get(akey) or 0) < _FOREMAN_REALERT_MS:
            continue
        seen[akey] = now_ms
        _FOREMAN_LOOP_STATE["alert_emitted"] = seen
        try:
            await _emit_notification(
                cid,
                event="jarvis_foreman",
                title=f"Foreman {sev}",
                body=headline,
                severity=notif_sev,
                agent_id=cfg.senior_id(),
                push=(sev == "red"),
            )
            emitted += 1
        except Exception:
            logger.exception("foreman alert_bell emit failed")

    try:
        joined = "\n".join(complete) + ("\n" if complete else "")
        advanced = len(joined.encode("utf-8"))
        new_offset = offset + advanced
        # Compact once the consumed prefix gets large: everything before the cursor
        # has already been emitted, so drop it and reset the cursor to 0. This is the
        # cursor-safe way to bound this file — a naive front-trim elsewhere would
        # leave the byte offset dangling and re-notify the whole tail. Unlike the
        # other foreman logs, the alerts file can't use append_capped for that reason.
        if new_offset > 256 * 1024:
            remainder = raw[new_offset:]
            tmp = path.with_suffix(".jsonl.tmp")
            tmp.write_bytes(remainder)
            tmp.replace(path)
            cursor_path.write_text("0", encoding="utf-8")
        else:
            cursor_path.write_text(str(new_offset), encoding="utf-8")
    except OSError as e:
        return {"ok": False, "error": str(e), "emitted": emitted}

    return {"ok": True, "emitted": emitted}


def _foreman_flag_key(flag: dict) -> str:
    """Stable identity of a flag's underlying condition (never its churny counts), so
    Senior analyzes a distinct problem once, not every tick it stays open.

    Prefer the sensor's own Signal.key() (e.g. "self:load", "cost:approaching",
    "chat:990046,990830") — it already names the condition, not its metrics. Only if
    that's somehow absent do we fall back to stable detail sets, and NEVER to the
    offenders list, whose human-readable strings embed live numbers that churn."""
    sid = flag.get("sensor_id") or "?"
    dk = flag.get("dedupe_key")
    if dk:
        return f"{sid}:{dk}"
    d = flag.get("detail") or {}
    ident = (d.get("offender_chat_ids") or d.get("down") or d.get("missing")
             or flag.get("severity") or "")
    return f"{sid}:{ident}"


def _gather_senior_context(cfg, flag: dict) -> str:
    """Evidence for the Senior model: recent messages of the offending chats (for
    chat_activity) plus the sensor's own offender notes. Sync — call via to_thread.
    Bounded; text is left raw because the prompt fences it as untrusted data."""
    d = flag.get("detail") or {}
    parts: list[str] = []
    offenders = d.get("offenders") or []
    if offenders:
        parts.append("Junior's notes:\n" + "\n".join(f"- {o}" for o in offenders[:8]))
    cids = d.get("offender_chat_ids") or []
    n_msgs = int((cfg.raw.get("senior") or {}).get("context_messages") or 12)
    for cid in cids[:4]:
        try:
            thread = _load_thread(int(cid))
        except Exception:
            continue
        tail = thread[-n_msgs:]
        title = ((CHAT_INDEX.get("chats", {}) or {}).get(str(cid), {}) or {}).get("title") or f"#{cid}"
        lines = [f"[chat {cid} — {title}]"]
        for m in tail:
            who = m.get("name") or m.get("role") or "?"
            txt = (m.get("text") or "").strip().replace("\n", " ")
            lines.append(f"{who}: {txt[:400]}")
        parts.append("\n".join(lines))
    ctx = "\n\n".join(parts)
    return ctx[:6000] if ctx else "(no additional context)"


def _senior_candidate_ids(cfg) -> list[str]:
    """Configured Senior first, then a small ordered fallback roster."""
    primary = cfg.senior_id()
    scfg = cfg.raw.get("senior") or {}
    raw_fallbacks = scfg.get("fallback_agent_ids") or ["grok", "minimax"]
    if not isinstance(raw_fallbacks, list):
        raw_fallbacks = [raw_fallbacks]
    out: list[str] = []
    for value in [primary, *raw_fallbacks]:
        aid = str(value or "").strip()
        if aid and aid not in out:
            out.append(aid)
    return out


async def _senior_unavailable_reason(agent: dict) -> str:
    """Return why a Senior candidate should be skipped, else an empty string.

    This combines the persistent provider circuit breaker with each managed
    bridge's honest /health. Unreachable/unparseable health remains fail-open in
    _managed_bridge_deep_status, so a probe glitch never removes a usable agent.
    """
    provider = _provider_for_agent(agent.get("id", ""))
    capped_until = await asyncio.to_thread(_provider_capped_until, provider)
    if capped_until:
        return f"{provider} provider capped until {_fmt_clock(capped_until)}"
    degraded, reason = await _managed_bridge_deep_status(agent.get("id", ""))
    return reason if degraded else ""


def _foreman_control_chat_id(cfg) -> Optional[int]:
    raw = cfg.raw.get("control_chat_id")
    try:
        return int(raw) if raw is not None else None
    except (TypeError, ValueError):
        return None


async def _run_senior_analysis(cfg, flag: dict, flag_key: str) -> None:
    """Invoke the seated Senior agent to analyze one Junior flag; if real, post a full
    briefing into the control chat + push a notification, and record it. Runs detached
    from the poll loop so a slow model never delays monitoring. Never raises."""
    from jarvis_foreman import senior as _senior
    from jarvis_foreman import audit as _jf_audit
    scfg = cfg.raw.get("senior") or {}
    try:
        configured_senior_id = cfg.senior_id()
        senior_id = configured_senior_id
        agent = AGENTS_BY_ID.get(senior_id)
        cid = _foreman_control_chat_id(cfg)
        context = await asyncio.to_thread(_gather_senior_context, cfg, flag)
        timeout = float(scfg.get("timeout_sec") or CONCIERGE_TIMEOUT_S)
        analysis = None
        candidate_errors: list[str] = []

        for candidate_id in _senior_candidate_ids(cfg):
            candidate = AGENTS_BY_ID.get(candidate_id)
            if candidate is None:
                candidate_errors.append(f"{candidate_id}: not configured")
                continue
            unavailable = await _senior_unavailable_reason(candidate)
            if unavailable:
                candidate_errors.append(f"{candidate_id}: {unavailable}")
                continue
            prompt = _senior.build_analysis_prompt(
                flag, context, senior_name=(candidate.get("name") or "Senior"))
            try:
                raw = await _concierge_call(candidate, prompt, timeout)
                analysis = _senior.parse_analysis(raw, flag)
                senior_id = candidate_id
                agent = candidate
                break
            except Exception as e:
                logger.warning("senior analysis via %s failed: %s", candidate_id, e)
                candidate_errors.append(f"{candidate_id}: {str(e)[:120]}")
                if _is_quota_cap_message(str(e)):
                    if cid is not None:
                        await _handle_quota_cap(candidate, cid, str(e))
                    else:
                        provider = _provider_for_agent(candidate_id)
                        now_ms = int(time.time() * 1000)
                        reset_ms = _parse_cap_reset_ms(str(e), now_ms)
                        _record_cap_event(provider, candidate_id, None, reset_ms, 0, str(e))

        if analysis is None:
            reason = "; ".join(candidate_errors)[:300] or "no senior agent available"
            analysis = _senior.fallback_analysis(flag, reason=reason)
            agent = AGENTS_BY_ID.get(configured_senior_id)
            senior_id = configured_senior_id

        analysis["flag"] = {k: flag.get(k) for k in ("sensor_id", "severity", "headline")}
        analysis["senior_id"] = senior_id
        analysis["configured_senior_id"] = configured_senior_id
        if senior_id != configured_senior_id:
            analysis["fallback_from"] = configured_senior_id
        analysis["ts"] = time.time()

        min_conf = float(scfg.get("min_confidence") or 0.5)
        # A fallback (model down) surfaces conservatively; a real model verdict must
        # clear the confidence bar before it pushes a notification at the operator.
        surfaced = bool(analysis.get("is_real")) and (
            analysis.get("source") == "fallback"
            or float(analysis.get("confidence") or 0) >= min_conf
        )
        analysis["surfaced"] = surfaced

        if surfaced and cid is not None and str(cid) in (CHAT_INDEX.get("chats") or {}):
            agent_name = (agent or {}).get("name") or senior_id or "Senior"
            body = _senior.render_analysis_message(flag, analysis)
            try:
                entry = append_thread(cid, "agent", senior_id, agent_name, body, metadata={
                    "source": "jarvis_foreman", "foreman": True, "senior": True,
                    "severity": analysis.get("severity"),
                })
                await broadcast({
                    "type": "message", "chat_id": cid, "sender": "agent",
                    "agent_id": senior_id, "name": agent_name, "text": body,
                    "ts": entry["ts"], "metadata": entry.get("metadata") or {},
                })
            except Exception:
                logger.exception("senior briefing post failed")
            if scfg.get("notify", True):
                try:
                    sev = analysis.get("severity", "amber")
                    notif_sev = "critical" if sev == "red" else ("warn" if sev == "amber" else "info")
                    preview = (analysis.get("recommended_fix") or analysis.get("analysis")
                               or analysis.get("headline") or "")[:200]
                    await _emit_notification(
                        cid, event="jarvis_foreman",
                        title=_senior.analysis_headline(analysis),
                        body=preview, severity=notif_sev,
                        agent_id=senior_id, push=(sev in ("red", "amber")),
                        owner_user_id=_chat_owner_id(cid),
                    )
                except Exception:
                    logger.exception("senior notification failed")

        _FOREMAN_LOOP_STATE["senior"] = analysis
        try:
            _jf_audit.append_audit(cfg, {
                "flag_key": flag_key,
                "flag": analysis["flag"],
                "is_real": analysis.get("is_real"),
                "surfaced": surfaced,
                "severity": analysis.get("severity"),
                "confidence": analysis.get("confidence"),
                "headline": analysis.get("headline"),
                "analysis": analysis.get("analysis"),
                "root_cause": analysis.get("root_cause"),
                "recommended_fix": analysis.get("recommended_fix"),
                "source": analysis.get("source"),
                "senior_id": senior_id,
                "configured_senior_id": configured_senior_id,
                "fallback_from": analysis.get("fallback_from"),
            }, stream="senior")
        except Exception:
            logger.exception("senior audit failed")
    except Exception:
        logger.exception("senior analysis pipeline failed")
    finally:
        _FOREMAN_LOOP_STATE["senior_inflight"] = False


async def _maybe_run_senior_analysis(cfg, jun: dict) -> None:
    """If Junior has a NEW flag and Senior is idle+enabled, spawn a detached Senior
    analysis. Debounced by flag_key (one analysis per distinct problem) with a re-analyze
    window so a long-standing problem is revisited, not analyzed forever or never again."""
    scfg = cfg.raw.get("senior") or {}
    if not scfg.get("enabled", True):
        return
    flag = jun.get("flag")
    if not flag or _FOREMAN_LOOP_STATE.get("senior_inflight"):
        return
    flag_key = _foreman_flag_key(flag)
    now = time.time()
    reanalyze_after = float(scfg.get("reanalyze_after_sec") or 21600)  # 6h
    analyzed = _FOREMAN_LOOP_STATE.setdefault("senior_analyzed", {})
    last = analyzed.get(flag_key)
    if last is not None and (now - last) < reanalyze_after:
        return
    analyzed[flag_key] = now
    if len(analyzed) > 200:  # bound the debounce map across long uptimes
        for k in sorted(analyzed, key=analyzed.get)[:100]:
            analyzed.pop(k, None)
    _FOREMAN_LOOP_STATE["senior_inflight"] = True
    asyncio.create_task(_run_senior_analysis(cfg, flag, flag_key))


async def _maybe_recheck_foreman_flag(job_id, status) -> None:
    """After a desktop handoff of a foreman flag completes, re-check whether the flag
    cleared, post a Senior verdict into the control chat, and auto-resolve it if fixed.
    Closes the loop the operator used to have to eyeball. Mirrors
    _maybe_resolve_fix_dispatch; no-op for non-foreman jobs. Never raises."""
    flag_ctx = _FOREMAN_HANDOFF_JOBS.pop(int(job_id), None)
    if not flag_ctx:
        return
    try:
        from jarvis_foreman.config import load_config
        from jarvis_foreman import audit as _jf_audit
        from jarvis_foreman.channels import sensor_label as _sensor_label

        sensor_id = flag_ctx.get("sensor_id")
        dedupe_key = flag_ctx.get("dedupe_key")
        agent_name = flag_ctx.get("agent_name") or flag_ctx.get("agent_id") or "the agent"
        label = _sensor_label(sensor_id)
        cfg = load_config()
        senior_id = cfg.senior_id()
        senior = AGENTS_BY_ID.get(senior_id) or {}
        senior_name = senior.get("name") or senior_id or "Senior"

        # Fresh read so we see the post-fix world. Match the exact condition by its
        # stable key when we have one; the in-chat card path has no key, so fall back
        # to "any amber/red still on this sensor."
        snapshot = await asyncio.to_thread(_control_room_poll_sensors, cfg)
        def _still(s):
            if s.get("id") != sensor_id or s.get("severity") not in ("amber", "red"):
                return False
            return (s.get("dedupe_key") == dedupe_key) if dedupe_key else True
        match = next((s for s in snapshot if _still(s)), None)
        cleared = (status == "done") and match is None

        if cleared:
            body = (f"**✓ Fixed — {label} cleared.** {agent_name}'s handoff resolved the flag; "
                    "the sensor now reads clean.")
            verify = "fixed"
        elif status != "done":
            body = (f"**⚠ Fix didn't finish — {label} still flagged.** {agent_name}'s job ended "
                    f"'{status}'. The flag is unchanged — try again or hand it off afresh.")
            verify = "job_failed"
        else:
            sev = match.get("severity") if match else "amber"
            head = match.get("headline") if match else ""
            body = (f"**⚠ Still flagging after the fix.** {agent_name} ran, but {label} still reads "
                    f"{sev}: {head}. Re-analyzing.")
            verify = "still_flagging"

        cid = cfg.raw.get("control_chat_id")
        try:
            cid = int(cid) if cid is not None else None
        except (TypeError, ValueError):
            cid = None
        if cid is not None and str(cid) in (CHAT_INDEX.get("chats") or {}):
            try:
                entry = append_thread(cid, "agent", senior_id, senior_name, body, metadata={
                    "source": "jarvis_foreman", "foreman": True, "senior": True, "verify": verify,
                })
                await broadcast({
                    "type": "message", "chat_id": cid, "sender": "agent",
                    "agent_id": senior_id, "name": senior_name, "text": body,
                    "ts": entry["ts"], "metadata": entry.get("metadata") or {},
                })
            except Exception:
                logger.exception("foreman verify post failed")

        try:
            _jf_audit.append_audit(cfg, {
                "verify": verify, "sensor_id": sensor_id, "dedupe_key": dedupe_key,
                "cleared": cleared, "agent": flag_ctx.get("agent_id"),
                "job_id": int(job_id), "job_status": status,
            }, stream="senior")
        except Exception:
            logger.exception("foreman verify audit failed")

        # Still red on a completed job → have Senior re-analyze with fresh context,
        # bypassing the debounce for this one condition.
        if verify == "still_flagging" and match:
            flag = {"sensor_id": sensor_id, "severity": match.get("severity"),
                    "headline": match.get("headline"), "detail": match.get("detail") or {},
                    "dedupe_key": dedupe_key}
            flag_key = _foreman_flag_key(flag)
            (_FOREMAN_LOOP_STATE.get("senior_analyzed") or {}).pop(flag_key, None)
            if not _FOREMAN_LOOP_STATE.get("senior_inflight"):
                _FOREMAN_LOOP_STATE["senior_inflight"] = True
                asyncio.create_task(_run_senior_analysis(cfg, flag, flag_key))
    except Exception:
        logger.exception("foreman flag recheck failed")


async def _jarvis_foreman_loop_tick(*, force: bool = False) -> dict:
    """One background cycle: optional bus tick + drain outbox + drain alert bell."""
    try:
        from jarvis_foreman.config import load_config
        from jarvis_foreman.bus import ForemanBus
    except Exception as e:
        _FOREMAN_LOOP_STATE["last_error"] = str(e)
        return {"ok": False, "error": str(e)}

    cfg = load_config()
    tick_result = None
    tick_signals: list = []
    if cfg.enabled or force:
        def _run():
            bus = ForemanBus(cfg)
            if force and not bus.cfg.enabled:
                bus.cfg.raw["enabled"] = True
            return bus.tick_with_signals()

        try:
            tick_result, tick_signals = await asyncio.to_thread(_run)
            _FOREMAN_LOOP_STATE["last_tick_ts"] = time.time()
            _FOREMAN_LOOP_STATE["last_tick_result"] = {
                "ok": tick_result.get("ok"),
                "skipped": tick_result.get("skipped"),
                "worst": tick_result.get("worst"),
                "signal_count": tick_result.get("signal_count"),
            }
            _FOREMAN_LOOP_STATE["ticks"] = int(_FOREMAN_LOOP_STATE.get("ticks") or 0) + 1
        except Exception as e:
            logger.exception("jarvis foreman tick failed")
            _FOREMAN_LOOP_STATE["last_error"] = f"tick: {e}"
            tick_result = {"ok": False, "error": str(e)}
            tick_signals = []

    # Junior's brain: narrate the current snapshot for the HUD live panel + durable
    # audit. Cheap local qwen3:4b; fully off-path from severity/channels. Only runs
    # while the foreman is on — "off" means Junior stands by too — and never breaks
    # the loop: narrate() and append_audit() each swallow their own errors.
    if cfg.enabled:
        try:
            from jarvis_foreman import audit as _jf_audit
            from jarvis_foreman import narrator as _jf_narrator

            # Reuse the signals the bus just polled — no second poll of all 13 sensors.
            # Each Signal.key() is the sensor's stable condition id, which flows into
            # the flag so Senior debounces on the condition, not churny offender text.
            if tick_signals:
                snapshot = [{
                    "id": s.sensor_id, "severity": s.severity, "headline": s.headline,
                    "detail": getattr(s, "detail", {}) or {}, "dedupe_key": s.key(),
                } for s in tick_signals]
            else:
                snapshot = await asyncio.to_thread(_control_room_poll_sensors, cfg)
            jun = await _jf_narrator.narrate(cfg, snapshot)
            senior = cfg.senior_id()
            if jun.get("flag"):
                jun["flagging_now"] = True
                jun["last_handoff"] = {**jun["flag"], "to": senior, "ts": jun.get("ts")}
            else:
                jun["flagging_now"] = False
                prev = _FOREMAN_LOOP_STATE.get("junior") or {}
                if prev.get("last_handoff"):
                    jun["last_handoff"] = prev["last_handoff"]
            _FOREMAN_LOOP_STATE["junior"] = jun
            _jf_audit.append_audit(cfg, {
                "worst": jun.get("worst"),
                "narration": jun.get("narration"),
                "source": jun.get("source"),
                "model": jun.get("model"),
                "latency_ms": jun.get("latency_ms"),
                "watching": jun.get("watching"),
                "handoff": jun.get("last_handoff") if jun.get("flagging_now") else None,
                "enabled": True,
            })
            # Hand a NEW flag to Senior for deep analysis (detached; won't block).
            await _maybe_run_senior_analysis(cfg, jun)
        except Exception as e:
            logger.exception("junior narrate/audit failed")
            _FOREMAN_LOOP_STATE["last_error"] = f"junior: {e}"
    else:
        prev = _FOREMAN_LOOP_STATE.get("junior") or {}
        _FOREMAN_LOOP_STATE["junior"] = {
            **prev,
            "narration": "Foreman is off — Junior is standing by.",
            "source": "standby",
            "worst": "green",
            "flagging_now": False,
            "ts": time.time(),
        }

    drain = await _foreman_drain_chat_outbox(cfg)
    alerts = await _foreman_drain_alert_bell(cfg)
    return {
        "ok": True,
        "tick": tick_result,
        "drain": drain,
        "alerts": alerts,
        "enabled": bool(cfg.enabled),
        "force": force,
    }


async def _start_jarvis_foreman_loop():
    """Background poll — always runs; bus.tick no-ops while foreman enabled=false."""
    async def _loop():
        await asyncio.sleep(18)  # settle bridges / DB
        _FOREMAN_LOOP_STATE["running"] = True
        logger.info("jarvis foreman loop started")
        while True:
            interval = 60
            try:
                from jarvis_foreman.config import load_config
                cfg = load_config()
                interval = int(cfg.raw.get("poll_interval_sec") or 60)
                interval = max(15, min(interval, 900))
                await _jarvis_foreman_loop_tick(force=False)
            except Exception as e:
                logger.exception("jarvis foreman loop error")
                _FOREMAN_LOOP_STATE["last_error"] = str(e)
            await asyncio.sleep(interval)

    asyncio.create_task(_loop())


@app.get("/api/automation-items")
async def api_list_automation_items(request: Request):
    user = _current_user(request)
    state = (request.query_params.get("state") or "pending").strip()[:24]
    owner_id = (user or {}).get("id")
    if owner_id is None:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    with _db() as conn:
        if _is_admin_user(user):
            rows = conn.execute(
                "SELECT * FROM automation_items WHERE state=? "
                "AND (owner_user_id IS NULL OR owner_user_id=?) "
                "ORDER BY created_ts DESC LIMIT 200",
                (state, owner_id),
            ).fetchall()
        else:
            rows = conn.execute(
                "SELECT * FROM automation_items WHERE state=? "
                "AND owner_user_id=? "
                "ORDER BY created_ts DESC LIMIT 200", (state, owner_id),
            ).fetchall()
    items = [{
        "id": r["id"], "schedule_id": r["schedule_id"], "run_id": r["run_id"],
        "kind": r["kind"], "state": r["state"], "created_ts": r["created_ts"],
        "payload": _json_loads_or({}, r["payload_json"]),
    } for r in rows]
    return JSONResponse({"ok": True, "items": items})


@app.post("/api/automation-items/{iid}/{decision}")
async def api_decide_automation_item(iid: int, decision: str, request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    if decision not in ("approve", "reject"):
        return JSONResponse({"ok": False, "error": "bad decision"}, status_code=400)
    user = _current_user(request)
    who = (user or {}).get("display_name") or (user or {}).get("email") or "user"
    state = "approved" if decision == "approve" else "rejected"
    now = int(time.time() * 1000)
    with _db() as conn:
        item = conn.execute(
            "SELECT * FROM automation_items WHERE id=?", (int(iid),)).fetchone()
        if not item:
            return JSONResponse({"ok": False, "error": "not found"}, status_code=404)
        # Owner gate BEFORE the state change: a gated_hold approval fires the held
        # automation with bypass_hold, so a non-owner must never be able to decide
        # another tenant's item. NULL-owner legacy items are admin-only.
        item_owner = item["owner_user_id"]
        if not _is_admin_user(user):
            if item_owner is None or not user or int(item_owner) != int(user["id"]):
                return JSONResponse({"ok": False, "error": "not found"}, status_code=404)
        sched_row = conn.execute(
            "SELECT * FROM skill_schedules WHERE id=?",
            (int(item["schedule_id"]),)).fetchone()
        # A forged/stale item must not be a bridge into a schedule belonging to a
        # different tenant. Admins retain their existing repair/override access.
        if not _is_admin_user(user) and (
            not sched_row or sched_row["owner_user_id"] is None
            or int(sched_row["owner_user_id"]) != int(item_owner)
        ):
            return JSONResponse({"ok": False, "error": "not found"}, status_code=404)
        cur = conn.execute(
            "UPDATE automation_items SET state=?, decided_ts=?, decided_by=? "
            "WHERE id=? AND state='pending'",
            (state, now, str(who)[:120], int(iid)),
        )
    decided = cur.rowcount > 0
    # A decided gated_hold either fires the held automation (approve) or records
    # the skip (reject). Fire as a detached task with bypass_hold=True so it runs
    # once without re-parking another hold.
    if decided and item and item["kind"] == "gated_hold":
        payload = _json_loads_or({}, item["payload_json"])
        cid = payload.get("chat_id")
        nm = payload.get("skill_name") or "automation"
        if decision == "approve" and sched_row:
            sched = _schedule_from_row(sched_row)
            asyncio.create_task(
                _run_schedule(sched, source=f"approved by {who}", bypass_hold=True))
            note = f"✅ Approved by {who} — running “{nm}” now."
        else:
            note = f"🚫 Rejected by {who} — “{nm}” was skipped, not run."
        if cid:
            try:
                await _route_system_note(int(cid), note)
            except Exception:
                logger.exception("gated_hold decision note failed for chat %s", cid)
    return JSONResponse({"ok": decided, "state": state})


async def _fire_event_triggers(event: str, owner_id: Optional[int] = None, *,
                               include_legacy: Optional[bool] = None) -> list[int]:
    """Run event schedules in one tenant boundary.

    Legacy NULL-owner schedules are the bootstrap admin's data. They accompany an
    admin event, but never a non-admin owner's event. With no owner context, only
    legacy rows are eligible rather than every tenant's schedules.
    """
    if _automation_paused():
        return []  # global kill switch — unattended triggers don't fire
    with _db() as conn:
        if owner_id is not None:
            allow_legacy = (
                _schedule_owner_is_admin(owner_id)
                if include_legacy is None else bool(include_legacy)
            )
            owner_clause = (
                "(owner_user_id=? OR owner_user_id IS NULL)"
                if allow_legacy else "owner_user_id=?"
            )
            rows = conn.execute(
                "SELECT * FROM skill_schedules WHERE enabled=1 AND trigger_type='event' "
                f"AND {owner_clause}", (int(owner_id),),
            ).fetchall()
        else:
            rows = conn.execute(
                "SELECT * FROM skill_schedules WHERE enabled=1 AND trigger_type='event' "
                "AND owner_user_id IS NULL"
            ).fetchall()
    fired: list[int] = []
    for row in rows:
        sched = _schedule_from_row(row)
        if (sched.get("spec") or {}).get("event") != event:
            continue
        try:
            res = await _run_schedule(sched, source=f"event:{event}")
            _mark_schedule_ran(sched["id"], "ok" if res.get("ok") else (res.get("error") or "error"), advance=False)
            fired.append(sched["id"])
        except Exception:
            logger.exception("event-trigger run failed")
    return fired


@app.post("/api/skills/trigger/{event}")
async def api_skill_event_trigger(event: str, request: Request):
    blocked = _require_origin(request)
    if blocked:
        return blocked
    # Scope to the caller: a tenant may only fire their own event schedules.
    # Bootstrap-admin callers also retain access to legacy NULL-owner schedules.
    user = _current_user(request)
    owner_id = (user or {}).get("id")
    if owner_id is None:
        return JSONResponse({"error": "unauthorized"}, status_code=401)
    return JSONResponse(
        {"ok": True, "fired": await _fire_event_triggers(
            str(event)[:60], int(owner_id), include_legacy=_is_admin_user(user)
        )}
    )
